-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D = TauriChineseDB
D.Strings[15814]="一派胡言。部落杀死那只亡灵易如反掌，不需要你，更别说那个傲慢的国王。"
D.Strings[15815]="呸。"
D.Strings[15816]="我们是客人，加尔鲁什，你要注意你的言行。"
D.Strings[15817]="感谢您的邀请，弗丁大人。我们期待着精彩的比赛。"
D.Strings[15818]="说的好。"
D.Strings[15819]="加尔鲁什，够了！"
D.Strings[15820]="当然，提里奥，我为他的莽撞向你致歉，我保证下不为例。"
D.Strings[15821]="在你眼前的是这个世界上最具艺术品位的采矿系统。只有土包子才会在山下挖隧道以获得矿石。我们则会将整座山移开！现在，我们就可以直接从地面上挖掘珍贵的金属了。"
D.Strings[15822]="%s等着$n，发出一阵震耳欲聋的怒吼！"
D.Strings[15823]="%s的尖刺正在追击$n！"
D.Strings[15824]="可以开始了！"
D.Strings[15825]="这么长时间里，我们终于有机会研究散布在这里的废墟了……希望这些财迷不会先把这个地方毁掉"
D.Strings[15826]="哈！"
D.Strings[15827]="易如反掌。"
D.Strings[15828]="没用的东西。"
D.Strings[15829]="这就是部落最强的战士？"
D.Strings[15830]="联盟对付这些部落垃圾不需要恶魔领主的帮助！来吧，蠢货！"
D.Strings[15831]="为荣耀而战！英雄们，为国王和人民而战！"
D.Strings[15832]="我们的荣耀被玷污了！他们对我们进行肆意的污蔑与诽谤。我要讨回公道！请允许我的勇士代替你的人出场，提里奥。我们要挑战部落！"
D.Strings[15833]="即使是巫妖王最强大的爪牙也无法与联盟抗衡。为胜利欢呼吧！"
D.Strings[15834]="你的猛兽阻挡不了我的勇士！提里奥。"
D.Strings[15835]="软蛋！"
D.Strings[15836]="败了……"
D.Strings[15837]="狡诈的联盟狗！召唤恶魔领主来对抗部落的战士？你们离死不远了。"
D.Strings[15838]="不要手下留情，部落勇士们！LOK'TAR OGAR!"
D.Strings[15839]="部落需要公正！我们向联盟挑战！请允许我们代你出战，圣骑士。我们要让那些狗知道侮辱部落的下场。"
D.Strings[15840]="这只是一个小小的开始。为了部落！"
D.Strings[15841]="圣骑士，你还在怀疑部落的力量吗？我们战无不胜！"
D.Strings[15842]="我在鲜血之环经历过更强大的挑战。这是浪费时间，圣骑士。"
D.Strings[15843]="欢迎，勇士们！你们听到了银色北伐军的号召，并勇敢地作出了响应！此时此地，就在十字军演武场，你们将面对最强大的挑战。能在这次选拔中活下来的人都将加入北伐的行列，共同进军冰冠堡垒！"
D.Strings[15844]="让游戏开始吧！"
D.Strings[15845]="他来自风暴峭壁最幽深，最黑暗的洞穴，穿刺者戈莫克！准备战斗，英雄们！"
D.Strings[15846]="做好准备，英雄们，两头猛兽已经进入了竞技场！它们是酸喉和恐鳞！"
D.Strings[15847]="当下一名斗士出场时，空气都会为之冻结！它是冰吼，胜或是死，勇士们！"
D.Strings[15848]="这些恐怖的野兽终于被消灭了！"
D.Strings[15849]="悲剧……他们英勇奋战，但还是没有制服诺森德的猛兽。让我们为这些死去的英雄默哀。"
D.Strings[15850]="高阶术士威尔弗雷德·菲兹班将是你们的下一个对手。等待他的上场吧。"
D.Strings[15851]="快，英雄们，消灭那只恶魔，不要让他打开通向恶魔空间的传送门！"
D.Strings[15852]="很遗憾，我们失去了威尔弗雷德·菲兹班，但这也给那些胆敢研习黑暗魔法的人们敲响了警钟。唉，你胜利了。准备面对下一个挑战吧。"
D.Strings[15853]="大家冷静！不要慌乱！这并不是什么阴谋！这名术士只是在按照自己的意愿行事，并不是联盟的授意。比赛必须继续！"
D.Strings[15854]="接下来你们将面对银色北伐军最强的骑士！只有打败他们，才能证明你的价值……"
D.Strings[15855]="好吧，我同意了。为荣誉而战吧！"
D.Strings[15856]="肤浅且可悲的胜利。今天的内耗让我们又一次被削弱了。这种愚蠢的行为只能让巫妖王受益！伟大的战士们就这样白白牺牲，而真正的威胁却步步逼近。巫妖王正计算着我们的死期。"
D.Strings[15857]="你们只有团结才能战胜最终的挑战。来自于冰冠冰川的深处，天灾军团最强的战将：巫妖王的双翼使者，恐怖的瓦格里！"
D.Strings[15858]="这是对巫妖王的一次重创！你的实力绝不亚于银色北伐军的勇士。很快，我们将携手攻入冰冠堡垒，消灭天灾军团的残余！只要心齐，我们必将胜利！"
D.Strings[15859]="阿尔萨斯！你已经孤立无援了！放下霜之哀伤，我会让你死个痛快。"
D.Strings[15860]="感谢你，大领主。挑战者们，我将开始召唤仪式。当仪式完成时，一个恐怖的末日守卫就会出现！"
D.Strings[15861]="准备迎接末日吧！"
D.Strings[15862]="啊哈！我做到了！看看召唤大师威尔弗雷德·菲兹班强大的力量吧！为我效命吧，恶魔！"
D.Strings[15863]="我才是主人……呦，哦……哦……"
D.Strings[15864]="渺小的侏儒！你们的傲慢将会招致灭亡！"
D.Strings[15865]="面对加拉克苏斯吧，燃烧军团的艾瑞达之王！"
D.Strings[15866]="卑微的虫子！"
D.Strings[15867]="被逐入虚空吧！"
D.Strings[15868]="会有人来代替我。而你们注定要被毁灭……"
D.Strings[15869]="血肉成灰！"
D.Strings[15870]="前进！这是主人的命令！"
D.Strings[15871]="地狱——之火！"
D.Strings[15872]="以黑暗之主的名义。为了巫妖王。你必死无疑。"
D.Strings[15873]="我们确认了你的力量，知道你正是我们需要的人。"
D.Strings[15874]="无能！"
D.Strings[15875]="天灾军团无人可挡……"
D.Strings[15876]="你被终结了！"
D.Strings[15877]="让黑暗吞噬你！"
D.Strings[15878]="让光明焚毁你！"
D.Strings[15879]="会有人战败你的，弗丁。"
D.Strings[15880]="蛛魔在诺森德的冻土荒原地下建立了一个帝国。只有最愚蠢的人才会在这个帝国上方建起房屋。那是我的帝国！"
D.Strings[15881]="你们死去勇士的灵魂都将属于我，弗丁。"
D.Strings[15882]="啊，我们的客人到了，主人说的果然没错。"
D.Strings[15883]="这里将是你的葬身之地！"
D.Strings[15884]="又是一个献给主人的灵魂。"
D.Strings[15885]="我让您失望了，主人……"
D.Strings[15886]="Auum na-l ak-k-k-k, isshhh。起来，奴仆们，吃吧……"
D.Strings[15887]="虫群会吞噬你！"
D.Strings[15888]="做好准备！"
D.Strings[15889]="呃！你！回去再练练吧。"
D.Strings[15890]="不！不！我再说一遍，不！还不够好。"
D.Strings[15891]="我认输！我投降。你做的很好。我可以走了吧？"
D.Strings[15892]="感谢你，传讯者，你的话真令我高兴。"
D.Strings[15893]="愿圣光赐我力量，让我不负众望。"
D.Strings[15894]="现在，让时光在你脑中倒流。"
D.Strings[15895]="下去休息吧。"
D.Strings[15896]="安心的去吧。"
D.Strings[15897]="这场闹剧该结束了！"
D.Strings[15898]="真是对生命的浪费。"
D.Strings[15899]="不！我绝不能再……失败了……"
D.Strings[15900]="我的烂肉还真碍事！"
D.Strings[15901]="我可不需要用骨头来打败你！"
D.Strings[15902]="你了解上古战争吗，$n？那是在万年以前发生的事情。那时，燃烧军团的恶魔第一次到达艾泽拉斯。他们打算将这个世界彻底吞噬，就如同他们吞噬无数个其它世界一样。在这次入侵中，这片土地曾经的心脏——艾萨拉的古老首都被夷为平地。你会在这一地区的各个角落找到古老的废墟遗迹，它们就是祖先曾经自负的证据。"
D.Strings[15903]="我现在很关心东边门纳尔湖周围的废墟。千万年以前，门纳尔学院第一个开始研究奥术的技艺，那是一座美丽的多层建筑，环绕一座平静的湖泊，非常有利于贤者们沉思和冥想。正是在那里，我的祖先首先发现魔法能量从永恒之井中溢出。$B$B很抱歉，我的介绍是不是太过冗长了？至今为止，我沉浸在这段神秘的历史中已经有数十年之久。我忘记了，其他人并不一定有和我一样的兴趣。"
D.Strings[15904]="总的来说，学院对于这种新发现的力量抱着相当谨慎的态度。从那个时代留存下来所剩无几的史籍资料来看，当时的贤者法师们非常担心我们会沉迷在这种奥术能量中而无法自拔,而这正是时至今日仍困扰我族的麻烦根源。$B$B因此，门纳尔贤者们最终与艾萨拉女王和她的上层精灵仆从决裂。而艾萨拉女王和她的奴仆很快便肆无忌惮地汲取并滥用这股力量，丝毫不在意这其中蕴含的巨大危险。"
D.Strings[15905]="当燃烧军团发动攻击时，门纳尔学院的贤者法师们已经远离了艾萨拉女王。他们本应该在那场战争中发挥巨大的力量，但当精灵的都市毁灭时，他们拒绝撤退。$B$B他们没有在城外重新集结，加入到反击燃烧军团的队伍中，而是留了下来，竖起魔法屏障，将他们曾经静瑟安详的家园变成一座堡垒。在恶魔入侵刚刚开始的那段恐慌日子里，难民不断涌入门纳尔学院，幸存者们开始在那里建立防御。"
D.Strings[15906]="挡住？面对燃烧军团先锋的全力进攻？这根本不可能！$B$B不，历史没有记录后来发生了什么……那里已经不再有幸存者了。狂暴的恶魔只留下了你今天所看到的这些废墟。学院的秘密就深埋在这片艾萨拉的泥土中。"
D.Strings[15907]="我喜欢你的想法，$r！$B$B就在不久以前，埋藏在这片废墟中的魔法能量还一直吸引着蓝龙军团的注意。所以我无法对这里进行研究。而现在，那些巨龙的注意力已经转移到别的地方去了，但一个更加可怕的威胁正在形成——那些绿色的小畜生想要把这片废墟推平，为一座燃料补给站开辟道路！用不了多久，埋藏上万年的神秘知识就将永远遗失了。我们必须尽快采取行动。"
D.Strings[15908]="欢迎你们，萨尔酋长，地狱咆哮统帅。"
D.Strings[15909]="我希望你能明白现在的状况，加尔鲁什。如果再这样互相争斗，就休想战胜天灾军团。"
D.Strings[15910]="在我这里，各位，我相信你们不会乱来。"
D.Strings[15911]="那就请跟我来。"
D.Strings[15912]="他们马上就要把我绑在祭坛上，吸取我的灵魂里。让我们赶快离开这里！"
D.Strings[15913]="干得好，胜利属于部落！"
D.Strings[15914]="你打得非常英勇。"
D.Strings[15915]="勇士们，祝贺你们！经历过一系列计划之中和意料之外的试炼，你们终于取得了胜利。"
D.Strings[15916]="现在去休息一下吧，辛苦了。"
D.Strings[15917]="参加联盟和部落之间的战斗吧！欢迎你加入到银色十字军的麾下。"
D.Strings[15918]="我们的目标就在南方。我们将向那座要塞进军，直捣天灾军团的心脏。"
D.Strings[15919]="这可不是一个轻松的任务。"
D.Strings[15920]="一场动员所有人参加的大规模攻击只会导致本可以避免的惨重伤亡。而每一名倒下的士兵都会变成敌人再爬起来。到那时候，艾泽拉斯将再没有力量对抗亡灵怪物的威胁。"
D.Strings[15921]="实际上，我们需要组建一支小规模的精英力量，对敌人造成致命打击。这才是我们的取胜之道。所以我们举办了银色锦标赛。"
D.Strings[15922]="你将在这里接受测试。你必须以自身的战斗实力来对抗诺森德最凶暴危险的力量。而你的领袖们将亲眼见证你的战斗。"
D.Strings[15923]="你们的勇敢、力量和机智都将受到万众瞩目。这些竞赛将决定谁才是艾泽拉斯最强的战士。"
D.Strings[15924]="胜利者将成为进攻冰冠堡垒大军的先锋。我们将并肩对抗邪恶。阿尔萨斯必将灭亡！"
D.Strings[15925]="瓦里安·乌瑞恩国王殿下和吉安娜·普罗德摩尔女士已经茹临比武场！让路！"
D.Strings[15926]="部落的酋长萨尔和督军加尔鲁什·地狱咆哮已经来到比武场！让路！"
D.Strings[15927]="大领主提里奥·弗丁已经来到台上，要向聚集在比武场上的人们讲话！来听他的演讲吧！"
D.Strings[15928]="寒风猛烈地吹过这里的峭壁，在冰冠冰川的这个角落，绝大多数生命都不会做片刻停留。不过，只需要一点耐心，生命又都会回来。所以我现在走在这片大地上。总有一天，这些树木会高过我们所有人。"
D.Strings[15929]="很快，全世界都将知道威尔弗雷德的名字！"
D.Strings[15930]="为这些竞技选手们召唤恶魔敌人的工作当然应该由我来完成。我是威尔弗雷德·菲兹班，召唤大师！在我钢铁般意志的控制下，即使是恶魔也会瑟瑟发抖！"
D.Strings[15931]="保护无辜者！"
D.Strings[15932]="那群傻瓜竟然让我帮他们管理他们的商店！而我只喜欢花。$B$B<小艾德琳突然斜眼盯着你，表情显得异常严肃>$B$B你喜欢花吗？"
D.Strings[15933]="猛犸人并不像看上去那样愚蠢。看管戈莫克就是一个非常困难的任务。但现在他已经被紧紧地捆住，应该不会有任何危险了。"
D.Strings[15934]="我帮助戈莫克照顾这些怪物。我并不完全赞同这种屠杀。但至少，他有机会进行战斗了。"
D.Strings[15935]="雪人是一种凶猛而狡诈的怪物，而这头雪人又是雪人之中最强壮的一头。我们在他的食物里掺了药，让他睡着了。$b$b但你可千万别以为他在斗兽场里还会这样昏昏沉沉地酣睡。"
D.Strings[15936]="我们照顾这些虫子已经有一段时间了。我希望它们能在斗兽活动中充分发挥作用。要知道，你要打败的不是一条冰虫，而是两条。"
D.Strings[15937]="我们也许只能在上流社会的阴影中做着默默无闻的事情。只有离开这里，在战争的最前线，我们的力量才能得到应有的尊重。"
D.Strings[15938]="你！好啊，就是你！$b$b好好看着我。对你来说，遇到我是你不可多得的幸运。过不了多久，全世界的人都会知道并畏惧威尔弗雷德·菲兹班的名字和我威严的面容！一旦我宏大的召唤最终完成，将没有任何人敢怀疑我的能力！"
D.Strings[15939]="这里……不是……你们的……"
D.Strings[15940]="第一场挑战需要你骑上一匹银色战马。"
D.Strings[15941]="我……我失去了对这些矿藏的控制！$B$B求求你，$g先生:女士;，不要解雇我！"
D.Strings[15942]="你好，如果你需要我的拍卖服务，那么我只能遗憾地告诉你：不行。只有宗师级工程师才有足够的能力操纵我的超级功能。$b$b更重要的是，为什么你还在和我说话？"
D.Strings[15943]="今天拍卖行有什么东西？"
D.Strings[15944]="卡莱莎，你还活着！赶快找掩蔽所，这些怪物简直……无穷无尽！"
D.Strings[15945]="我还在流血？我不能……不能坚持下去了。你有没有见到任何一位大法师？"
D.Strings[15946]="嗯，我想这是魔法作用的结果。你收获了你所见到的一切……愿艾露恩保佑我们。"
D.Strings[15947]="卡莱莎，大法师瑟维恩正在找你。她应该就在附近……"
D.Strings[15948]="这些怪物……它们实在太多了。这么多人都死了！艾萨拉陷入了火海。那些上层精灵到底做了些什么？"
D.Strings[15949]="为什么我没有和其他人一起逃走？他们已经将学院包围了。我们被困在了这里。"
D.Strings[15950]="我维持着那些奥术结界的能量。"
D.Strings[15951]="我的力量……正在……减弱。卡莱莎，请告诉我，大法师们还有备用计划……"
D.Strings[15952]="我没办法将这面护盾维持太久了。卡莱莎，我们之中能有人活过这场劫难吗？"
D.Strings[15953]="还有更多怪物！它们都是从哪里来的？首都现在怎么样了？"
D.Strings[15954]="卡莱莎！赶快，大法师瑟维恩正急着想要见你。也许我们还能渡过这个难关？"
D.Strings[15955]="我只能维持住这些结界。卡莱莎！赶快去找到一位大法师。我觉得我就要崩溃了……"
D.Strings[15956]="卡莱莎……完成了。这块岩石已经被充满能量，并开始从传送门转移能量。你的水性还和多年前一样令人惊叹吗？绝不能让恶魔或者我们“敬爱”的女王找到这块石头。$B$B游到湖底去，卡莱莎，将这块石头深埋在湖心。希望那些恶魔入侵者在摧毁湖周围的圣殿时不会发现它。去吧！"
D.Strings[15957]="<这个闪烁微光的身影并不知道你的出现。她迷失在自己的世界中，依旧只是关注着千万年以前发生的事情。>"
D.Strings[15958]="当进攻冰冠堡垒的战斗开始时，我一定会加入。"
D.Strings[15959]="你好，$c。$B$B现在部落控制着冬拥堡垒。当争夺冬拥堡垒的战斗开始的时候，你和我交谈，就能加入这场战斗。$B$B"
D.Strings[15960]="你好，$c。$B$B现在部落控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！"
D.Strings[15961]="你好，$c。$B$B现在联盟控制着冬拥堡垒。但争夺这座堡垒的战斗已经开始了。快些赶往冬拥湖，帮助我们进行这场战斗吧！"
D.Strings[15962]="你好，$c。$B$B现在联盟控制着冬拥堡垒。当战斗就要开始的时候，你和我交谈，就能加入这场战斗。$B$B"
D.Strings[15963]="排队等待冬拥湖战场。"
D.Strings[15964]="你好，$g先生:女士;！我能为你做些什么？"
D.Strings[15965]="在时间和空间构造上出现的这道裂痕看起来非常凶险。许多截然不同的景象从这道裂痕中以可怕的速度闪过。此时此刻，大概只有极为勇敢的人才会跳入其中……"
D.Strings[15966]="北风苔原"
D.Strings[15967]="索拉查盆地"
D.Strings[15968]="冰冠冰川"
D.Strings[15969]="风暴峭壁"
D.Strings[15970]="嚎风峡湾"
D.Strings[15971]="这里并不安全，$n。赶快去找避难所。"
D.Strings[15972]="谁能挡住这个食尸鬼！"
D.Strings[15973]="这一定很痛！脑子！"
D.Strings[15974]="我们孤立无援！联盟击溃了我们，让我们流落到天知道是在哪里的孤岛上！$B$B但生意还得进行，不是吗，$n？"
D.Strings[15975]="漂亮的爆头射击！"
D.Strings[15976]="你好，$c。$B$B现在部落控制着冬拥堡垒。但下一场争夺这座堡垒的战斗就要开始了。赶快做好准备，前往冬拥湖帮助我们作战吧！$B$B这场战斗将在$4354k内开始。"
D.Strings[15977]="你好，$c。$B$B现在冬拥堡垒由联盟控制，但下一次战斗就要开始了！加入冬拥湖的战斗，帮助我们赢取胜利吧！$B$B这场战斗将在$4354k内开始。"
D.Strings[15978]="$n被踏倒了！"
D.Strings[15979]="你好，$c。$b$b看看你的周围。你有没有认真考虑过所有这些东西的意义？"
D.Strings[15980]="裁决者玛蕾尔·图哈特请求我们负责锦标赛所需的各项工作。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。"
D.Strings[15981]="$n? $G先生:女士;，你不是猎人，你是$c。"
D.Strings[15982]="我们需要你，$n！这里到处都是狼人！"
D.Strings[15983]="这太恐怖了。我怀疑他们全都死了。$B$B现在我该怎样把卡亚矿石从这里运出去？"
D.Strings[15984]="%s从地面上升起来了！"
D.Strings[15985]="风已经悄声告诉我，一名$r$c即将到来。$g他:她;会帮助我取得成功，而不是像其他人那样只能让我尝到失败的苦果。$b$b你会是那个人吗？"
D.Strings[15986]="我无法对你进行任何训练，$n。但我需要你帮我对付这些该死的猴子！"
D.Strings[15987]="我喜欢术士！今天我能在你的耳边说一些怎样的黑暗秘密？"
D.Strings[15988]="嗨，$n$g先生:女士; ，我无法传授你魔法技艺，只能教你如何用手指按摩僵硬的脖子。"
D.Strings[15989]="请原谅，恐怕现在我还有别的事情必须去做。请以后再来找我。"
D.Strings[15990]="干得漂亮，$n$g先生:女士;。保持这种高水平的发挥吧。"
D.Strings[15991]="我预见到了你光辉的未来，我的孩子！今天我要教你些什么？"
D.Strings[15992]="一座岛屿旁的失事船只上挤满了扔炸弹的猴子？那这以后又会有什么……一座即将爆炸的火山？"
D.Strings[15993]="你能看见我？你怎么可能看见我，老板？$B$B我正在努力提高自己的潜行技巧呢。"
D.Strings[15994]="不管是训练还是按摩，我能满足你的一切需要，老板。只是当你成为新的贸易大王时不要忘记我！"
D.Strings[15995]="那名术士肯定没有召唤末日守卫。你在下一场挑战中将和银色十字军作战。做好接受挑战的准备了吗？"
D.Strings[15996]="好吧，你做好准备之后，我就会向提里奥发出信号。"
D.Strings[15997]="发信号吧！我们已经准备好了！"
D.Strings[15998]="这场战斗真是野蛮残忍至极。我已经有许多年没见到过如此大规模的战斗了！实在是令人震惊！"
D.Strings[15999]="我已经等不及要看到下一场战斗了！他们似乎已经做好了准备。所以，你们也赶快进行准备吧！"
D.Strings[16000]="我们走吧。"
D.Strings[16001]="为了抓住你就要见到的这个挑战者，我们可是蒙受了很大的伤亡！"
D.Strings[16002]="地下……"
D.Strings[16003]="瓦格里的团队协作能力真是令人震惊。现在我终于明白，为什么只是抓住两只瓦格里就会如此困难。"
D.Strings[16004]="很困难吗？"
D.Strings[16005]="你最好记住！你要面对的是阿尔萨斯最强大的两个瓦格里侍从！"
D.Strings[16006]="瓦格里？我们已经准备好和他们作战了。"
D.Strings[16007]="我希望你能够迅速提高！"
D.Strings[16008]="现在，竞技场终于落成了。而锦标赛的管理者也请求我们负责管理在那里面举行的竞技活动。而我们只会邀请那些曾经在我们面前证明过自身实力的真正勇士帮助我们完成这些工作。"
D.Strings[16009]="现在，竞技场已经竣工。裁决者玛蕾尔·图哈特请求我们帮助管理锦标赛和保护赛事安全。她想让我们和那些无能的银色盟约混蛋们一同工作。但他们只会碍事。"
D.Strings[16010]="救命！"
D.Strings[16011]="当我作为一名奥格瑞玛卫兵接受训练的时候，萨尔叮嘱我们在对敌作战的时候需要保持耐心和谨慎。$B$B但纳迦时刻都有可能完全占领这座半岛。萨尔也不再是我的酋长了。现在应该是对敌人予以痛击的时候了，$c。"
D.Strings[16012]="太好了，今天你们证明了自己是强大的勇士。只要你们和银色十字军并肩作战，我们必将战胜天灾军团！"
D.Strings[16013]="无论给予你怎样的赞扬都不会过份。提里奥肯定想亲自表彰你的功绩。嗨，你有没有突然觉得有些冷？"
D.Strings[16014]="持剑的手臂要挺直，$n。"
D.Strings[16015]="你不是战士！你最好回到安全的地方去……当然，我这样说不是要冒犯你。"
D.Strings[16016]="你在这里建立的功业不会被遗忘，$n！我将确保这一点。"
D.Strings[16017]="你所走的并非旧时的道路。我没有什么可以教你的，孩子。"
D.Strings[16018]="狼人会消失。我们也会消失。$B$B只有大地和她的秘密会留存下来。你愿意学习吗，$n？"
D.Strings[16019]="一定要非常、非常安静。这里到处都是狼人。"
D.Strings[16020]="我在寻求进一步的训练。"
D.Strings[16021]="当然，我会和你分享我的智慧。你可以借助这些智慧帮助我们击败狼人。"
D.Strings[16022]="教导你耗费了我很大力气。而为了让自己的心智适应奥术力量，你还需要经历许多个岁月的磨砺。"
D.Strings[16023]="我发誓，这不是我的错。为什么你要这样看着我？"
D.Strings[16024]="即使是现在这个最黑暗的时代，圣光的教诲依旧能指引你安然无恙地穿行在这个危险的世界上。"
D.Strings[16025]="圣光与你同在，$c。今天你必将不会受到伤害。"
D.Strings[16026]="我想，我们也许已经激怒他们了。"
D.Strings[16027]="对于我所保藏的秘密，即使是最肤浅的一瞥，也能够让你发疯，$c。"
D.Strings[16028]="什么事，凡人？"
D.Strings[16029]="欢迎，勇士！你是否已经聚集起力量，做好准备，打算迎接大十字军的试炼的挑战了？只有最强大，最聪明的冒险者才能进行这样的试炼。为了参与这次试炼，你们必须首先完成普通的十字军的试炼。"
D.Strings[16030]="大十字军的试炼比十字军的试炼更加困难。这里的每一个敌人都会变得更强大。而且你无法为自己挑选敌人，除非你们曾经战胜过他们。如果在这周之内，你们进行了50次不成功的尝试，就只能等到下周再继续大十字军的试炼了。在成功地完成大十字军的试炼之后，你们将获得另一个宝物匣。现在，是否已经为这一试炼做好了准备？"
D.Strings[16031]="<基拉格示意你压低声音。>"
D.Strings[16032]="勇士们，你们还活着！你们不仅克服了十字军试炼的每一场挑战，还直接阻挠了阿尔萨斯的计划！你们的技巧和机智在对抗天灾军团的战斗中一定能发挥极为强大的作用。干得好！请让我的一名法师将你们传送回地面吧！"
D.Strings[16033]="现在，你已经完成了十字军的试炼，你应该考虑去参加大十字军的试炼了。只有最强大的冒险者才有希望完成这一试炼。但你的努力一定能换回丰厚的报偿。"
D.Strings[16034]="祝贺，请在准备好之后进入这个通向达拉然的传送门！"
D.Strings[16035]="看到同伴的死亡，%s被激怒了！"
D.Strings[16036]="你们两个要更加小心！我们的人只有这么点了！"
D.Strings[16037]="什么？！你认为我是矿工出身？$B$B你还能有更糟糕的想法吗？"
D.Strings[16038]="看到海滩那边的旋翼机了吗，$n？！"
D.Strings[16039]="拿上钥匙，然后到旋翼机那里去！"
D.Strings[16040]="我已经见到了未来，$r。$b$b如果我们不能迅速采取行动，半人马的土地将永远地堕落。"
D.Strings[16041]="啧！这肯定是侏儒建造的。"
D.Strings[16042]="一位地精？我肯定是眼花了。感谢你，并很高兴见到你，小家伙！"
D.Strings[16043]="$n，坐下。火已经热了。这可不是给猴子准备的。"
D.Strings[16044]="谁能想到，在我们渡过那么多难关之后，却会在这里结束？"
D.Strings[16045]="嗨，看啊，是$n！"
D.Strings[16046]="看样子我们被困在这儿了。你能让我们从这里出去吗？"
D.Strings[16047]="哦，$n，我们被困住了！"
D.Strings[16048]="我想念科赞。我们还能再看到锈水码头吗，$n？"
D.Strings[16049]="和我一起坐一会儿。我们可以唱唱歌，在火上烤烤螃蟹。"
D.Strings[16050]="我全都指望你了，但你怎样做才能让我们离开这座岛？"
D.Strings[16051]="<大胖哼哼着。>$B$B俺现在是银行家了！"
D.Strings[16052]="$n，很高兴再见到你。"
D.Strings[16053]="为了部落的荣耀，$n！"
D.Strings[16054]="进入神庙中心，使用元素愤怒号角！"
D.Strings[16055]="你可以在炼金区找到他们。你可以叫他们赫伯特·哈尔希医生和马尔什医生。要小心。"
D.Strings[16056]="赫伯特·哈尔希医生就是你要找的人。别干傻事。再搞那种无聊的瘟疫，你的脑袋就得搬家。"
D.Strings[16057]="所有的拍卖师都在中央区域。"
D.Strings[16058]="如果你想看看这里的市场，那么就到中央区域去吧。"
D.Strings[16059]="银行？就在贸易区中间的塔里。"
D.Strings[16060]="就在城的正中央。中心区的小房间。"
D.Strings[16061]="纳兹尼克是这里的理发师。他的理发店就开在贸易区的上层区域。"
D.Strings[16062]="迈克尔·加勒特是幽暗城的蝙蝠管理员。他就在贸易区的上层区域。"
D.Strings[16063]="蝙蝠管理员的架子就搭在贸易区的上层区域。远远的就会闻到那股味儿的。"
D.Strings[16064]="战场军官都在皇家区内；你可以在王座厅四周找到他们。"
D.Strings[16065]="詹姆斯·范·布朗特的锻造生意一直不错，就在军事区的内环区域。"
D.Strings[16066]="铁匠在军事区干活，买了他们武器的人马上就可以在旁边试上一试。铁匠就在那里的内环区域。"
D.Strings[16067]="贸易区的尤奈斯·伯奇是这里的厨师。是你的肚子在叫，不是我的。"
D.Strings[16068]="这里的厨师是尤奈斯·伯奇，你可以在贸易区找到她。"
D.Strings[16069]="拉文尼亚·克洛文是这里的附魔师。他的店就开在炼金区的内环区域。"
D.Strings[16070]="炼金区内环区域的拉文尼亚·克洛文可以教你有关附魔的知识。"
D.Strings[16071]="弗兰克林·洛伊德是这里的工程师。他平时都在盗贼区外环区域修修补补。"
D.Strings[16072]="听着，如果你要去见盗贼区外环区域的那些工程师，那就看好标记。"
D.Strings[16073]="你可以找玛丽·艾塔斯谈一谈。她就呆在盗贼区的内环区域。"
D.Strings[16074]="你好！终于见到一个身上没有臭鱼味的人了。我喜欢。"
D.Strings[16075]="即使是行尸走肉也需要维护自己的身体。玛丽·艾塔斯精通此道。她就在盗贼区的内环区域。"
D.Strings[16076]="疯狂的渔夫就在魔法区的港口那。"
D.Strings[16077]="你好，朋友。$b$b相信你很喜欢这个地方吧？"
D.Strings[16078]="我不知道阿曼德·克伦威尔在试图追赶什么，不过他已经到了魔法区的码头。"
D.Strings[16079]="克里斯托弗·德库尔是这里的公会注册员。他的办公区设在贸易区东侧平台。"
D.Strings[16080]="公会注册员在贸易区办公。你可以在东侧平台找到他。"
D.Strings[16081]="马尔萨·奥列斯塔是这里的草药学家。你可以在炼金区的内环区域找到她。"
D.Strings[16082]="去炼金区的内环区域，那里的马尔萨·奥列斯塔可以教你有关草药学的知识。"
D.Strings[16083]="旅馆——如果算得上的话——在贸易区的上层区域。那里连床铺都没有。"
D.Strings[16084]="贸易区上层区域的诺曼是这里的旅店老板，他的店只不过是几面满是灰尘和裂缝的墙壁。"
D.Strings[16085]="这里的抄写员在炼金区，她的名字叫玛尔迦·帕克雷。"
D.Strings[16086]="城里的皮匠在盗贼区的内环区域。"
D.Strings[16087]="亚瑟·摩尔是这里的皮匠。他在盗贼区的内环区域传授制皮技能。"
D.Strings[16088]="如果要钥匙，你可以找盗贼区的沃特尔·索雷夫谈一谈，不过要小心。"
D.Strings[16089]="法师？他们都在魔法区的中央建筑中。你得机灵点儿才能找得到。"
D.Strings[16090]="在魔法区的外环区域你能找到一座大型、阶梯式的建筑。法师们都在那里。"
D.Strings[16091]="邮箱在贸易区的棺材铺前面，也有人管那里叫旅馆。"
D.Strings[16092]="邮箱吗？你可以到城中央上层区域的旅店看看，那里有邮箱。"
D.Strings[16093]="和军事区内环区域的布罗姆·基里安谈一谈，他可以教你如何采矿。"
D.Strings[16094]="这里的采矿训练师在军事区的内环区域工作。他的名字叫布罗姆·基里安。"
D.Strings[16095]="找圣骑士你得去皇家区。那些有几个精灵可以教你。"
D.Strings[16096]="牧师们都在军事区的外环区域。"
D.Strings[16097]="去军事区外环区域看看吧。那里的牧师努力确保没有哪个断掉的肋骨长时间得不到修复。"
D.Strings[16098]="盗贼们都呆在盗贼区。就这么简单。你可以在外环区域找到他们。"
D.Strings[16099]="你可以在盗贼区外环区域找到那些潜行者。"
D.Strings[16100]="基里安·哈根是这里的剥皮训练师。他就在盗贼区的内环区域。"
D.Strings[16101]="如果你想学习剥皮，就要前往盗贼区。剥皮训练师的铺位就在内环区域。"
D.Strings[16102]="如果你真的想把宠物委托给某个亡灵，那你可以和安雅·玛尔雷谈谈，他就呆在贸易区上层的旅馆里。"
D.Strings[16103]="你可以同安雅·玛尔雷谈一谈，他就在贸易区上层的旅店旁边。我并不建议你这样做，不过它们毕竟是你的宠物。"
D.Strings[16104]="这里的裁缝叫乔瑟夫·格里高利。他就在魔法区的内环区域。"
D.Strings[16105]="先到魔法区，然后朝内环区域走，裁缝店就在那里。"
D.Strings[16106]="你竟然有胆量问我有关术士的事。到魔法区的外环区域看看吧，现在给我消失。"
D.Strings[16107]="你可以在魔法区的主建筑区域找到那些术士，我希望告诉你这些不会引起什么麻烦。"
D.Strings[16108]="战士都在军事区外环区域进行操练。"
D.Strings[16109]="你可以在军事区的外环区域找到那些战士。"
D.Strings[16110]="到军事区内环区域找到阿基巴德，他可以教你如何某些使用武器。"
D.Strings[16111]="很高兴有人愿意学点儿真正有用的东西。到军事区的内环区域去找阿基巴德吧。"
D.Strings[16112]="你想离开这，这我不怪你。先到最顶层，然后朝废墟的北面走。坐上两座塔那的地精飞艇就可以离开了。"
D.Strings[16113]="飞艇塔就在幽暗城的北面。"
D.Strings[16114]="在这看到兽人感到意外吧？用不着这样。$b$b需要有人看着那些被遗忘者。如果从一开始我们就好好盯着，或许天谴之门的事根本就不会发生。"
D.Strings[16115]="希望你要找的不是那些憎恶。炼金师没有一个靠得住，他们造出来的那些在大厅里巡逻的东西也一样。真正保卫这里安全的是我们。"
D.Strings[16116]="Lok'tar。不要在这里做出任何可疑的行为。如果那些亡灵打算加入部落，他们就得接受我们的监视。"
D.Strings[16117]="怎么了？骨头堆。在找人吗？这里只有我，要买东西就快点儿。"
D.Strings[16118]="我会盯着你的，法拉尼尔。"
D.Strings[16119]="没有憎恶保护你。没有秘密。没有私下密谋。"
D.Strings[16120]="这里完全不欢迎随地吐痰的人。"
D.Strings[16121]="我向您保证，监工，皇家药剂师协会愿意为这场导致了大量死亡的悲剧事故做出补偿。"
D.Strings[16122]="我们不会给你惹麻烦的。我们只想安安静静地继续我们的研究。"
D.Strings[16123]="让那个死脑筋把嘴闭上！"
D.Strings[16124]="闭嘴，叽里呱啦的蠢货！"
D.Strings[16125]="我敢说你们这些无赖一定觉得自己在天谴之门干得很漂亮，对吧？游戏结束了。我们来就是要阻止你们的一切行为。"
D.Strings[16126]="我会告诉你都该知道些什么，但这并不表示我有多么愿意。我们一直在监视着你和你的同类。"
D.Strings[16127]="坑里臭气熏天，还有一群蛇围着我。不过我来这是有事要做的。$b$b自从普特雷斯在天谴之门上演了一出好戏，酋长便不再信任那些人，而是离他们远远的。这就是为什么我们会在这里。那些药剂师离了我什么都做不了。"
D.Strings[16128]="我没有能在吉尔尼斯城保护我的人民。但命运似乎是要给我第二次机会，$n。我不会再失败了！"
D.Strings[16129]="很高兴看到憎恶们祥和的喘气声和气体爆破声又回到了幽暗城。兽人的体味可难闻多了。"
D.Strings[16130]="你已经被麻痹毒素感染了！"
D.Strings[16131]="我能看看你的古代宝石配方么？"
D.Strings[16132]="这是什么，$c？恶魔不在了，这里有很多东西我要看。总得有人来整理这些文书，确保普特雷斯的事不再发生。$b$b我真是走运。"
D.Strings[16133]="看看你周围，$c！$b$b这里难道不是非常美丽吗？"
D.Strings[16134]="你还好吗，$g小伙子:姑娘;？"
D.Strings[16135]="<格蒙刚的声音发出隆隆的回音，让你感到耳鼓震痛，脚下的地面也在一阵阵颤抖。>$B$B你好，小软人。$B$B你们总是喜欢四处乱窜。来，和我休息一会儿吧。"
D.Strings[16136]="哈——啊哈！食物？我们可不吃这种有汁水的东西，朋友，除非他们来伤害我们。我们吃的是岩石、石块和沙砾。不过有时候我也觉得嚼嚼小骨头是一种不错的调剂。$B$B<格蒙刚用一只巨大的手举起一块巨石。将你带来的尸体摁在上面，就好象在蛋糕上放一块水果。然后在一阵宏亮的“嘎吱”声中，他把那块石头嚼碎，咽下了肚。>"
D.Strings[16137]="艾萨莱特水晶？你们这些软弱的家伙倒是喜欢乱起新名字。这个“艾萨莱特水晶”又是什么？"
D.Strings[16138]="<格蒙刚的笑声浑厚而悠长。大地也随着他的声音在颤抖，远处细碎的砾石在不住地滑动。>$B$B哦……哈！哈！哈！小朋友，我很抱歉。我想，我们一族的行为方式和你总会有些区别。"
D.Strings[16139]="它来自——嗯——你们的语言是怎样说的？嗯。我要说，我们一族可是没有厕所的。你明白吗？"
D.Strings[16140]="看起来是这样。你和你的朋友们可以随意收集这些东西。我想，它可能是有些用处。我们可不是经常会有这些东西的。"
D.Strings[16141]="我们的生命进程不像你们那样快，我柔软的朋友！一个健康的巨人每十年会吃三顿饭。不过我每两年会吃一次小点心。我们每15到25年会上一次厕所……拉肚子除外。"
D.Strings[16142]="<格蒙刚和善地喷了一下鼻息。>$B$B 哈！我还没有这样细致地考虑过自己的个人习惯呢。你们总是让我感到吃惊。再见，朋友，祝你好运……无论你要找的是什么。"
D.Strings[16143]="抓住一个！"
D.Strings[16144]="搞定！"
D.Strings[16145]="打败他们！"
D.Strings[16146]="听着，$n，我不能让别人看见我在和你说话。你不再是贸易大王眼中的红人了，而我则需要为我的未来考虑。$B$B你明白我的意思，对吧，宝贝儿？另外，我现在和小甜甜在一起了。"
D.Strings[16147]="我的房子！"
D.Strings[16148]="<贸易大王用低微的耳语说道。>$B$B不管你是否能逃掉，绝不要以为我会忘记你这个卑微的家伙，$n。$B$B不必再为你那颗$g简单:漂亮;的脑袋而担心了。记住，我很快就会进行复仇！$B$B到时候，你将羡慕那些能成为我的奴隶的人。你逃不出我的手心。"
D.Strings[16149]="我们欠你的永远都还不清，$n。"
D.Strings[16150]="$n，谢谢你救了萨尔。我们一直都找不到他。$B$B<阿格娜关切的看着酋长。>"
D.Strings[16151]="又见到你了，柔软的小朋友。这次你要做什么？"
D.Strings[16152]="嗨，$g兄弟:小姐;。乘坐火箭吧！耶！"
D.Strings[16153]="哦，$n，你又救了我们！感谢你为我们消灭了那些恶棍！"
D.Strings[16154]="<格蒙刚带着怀疑的神情看着这团软软的东西，然后又嗅了嗅它，便气恼地将它捏塑成一只地精的样子。>$B$B我怀疑你那些小绿人朋友没想让你做好事儿。去告诉他们，我们巨人可不是任人玩弄的。$B$B<为了表达他的意思，格蒙刚在把他刚做成的地精雕像交给你的时候，又用力拧断了它的脑袋。>"
D.Strings[16155]="钩锤相信我能把事情做好。不能让这些琐碎的事情干扰他。"
D.Strings[16156]="你准备好被缩小了吗？这也许有一点痛，还有一点烧灼感。不过疼痛和抽搐很快就会过去的。"
D.Strings[16157]="嗯，什么？"
D.Strings[16158]="这套衣服真漂亮。专程为了聚会穿的吧！"
D.Strings[16159]="<这是一段手写的文字：>$B$B          秘密实验室档案馆$B     X.尼泽柏克，实验室主管$B$B$B请按蜂鸣器呼叫服务。"
D.Strings[16160]="加弗斯特厌倦了这些凡人。刺骨的寒风刮起来！"
D.Strings[16161]="斧子太弱了。看我弄好他，然后……然后砸扁你。"
D.Strings[16162]="嗨，$n。我知道这挺糟的，但贸易大王的船骸暂时就是我们的家了。"
D.Strings[16163]="你好，$r。请不要太惊讶。我确实是在用你的语言与你交谈。$B$B虽然身为迅猛龙，但我的智力已经通过一系列试验得到了大幅增强。你可以称我为“九号实验品”，这是我的创造者们不久以前给我取的名字。不过现在他们要么消失要么挂掉了。也许你能帮我个忙？"
D.Strings[16164]="随着我认知能力的增强，我开始审视我们这个种族。我们的大部分精力都被用于捕捉猎物。我在想，为什么我们不能用这些时间驯服并圈养这些猎物，让它们成为我们稳定的食物供给？$B$B我认为人类是很好的食物来源——很快就能被养肥，而且味道鲜美，还能够进行训练，代替我们完成畜牧工作。嗯……"
D.Strings[16165]="我早知道我会受到这种冷遇。长久以来我们一直在隐居，因为我们必须要与族人分离。$b$b那段时间已经过去。不管这颗幼树之荫下的居民是否会接受我们，上层精灵们都要摒弃过去的身份，从黑暗中返回光明。"
D.Strings[16166]="这真的是个好主意吗？"
D.Strings[16167]="我的兄弟和我乘船几天时间就能到达北吉尔尼斯。当然，我们得先完成修理工作。"
D.Strings[16168]="海象人风筝"
D.Strings[16169]="迷你坐骑"
D.Strings[16170]="幽灵虎幼崽"
D.Strings[16171]="天灾战争"
D.Strings[16172]="刚出油锅，又入烈火，是吗，$n？"
D.Strings[16173]="我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！"
D.Strings[16174]="我现在还有点耐心。但如果他们不尽快让火箭弹射器正常工作，有人可就要吃我的暗影箭了！$B$B需要训练吗，$n？"
D.Strings[16175]="我看见戴姆维克骑过这东西。所以我宁可使用缓落术。不过我还不知道这法术该怎么用。"
D.Strings[16176]="干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？"
D.Strings[16177]="干得好，$n！这是不是很令人兴奋？我很想知道，下一座岛会是什么样？$B$B我能教你些新东西吗？"
D.Strings[16178]="看样子你进行过不少冒险，$n。那些联盟软蛋手里可是有不少钱。"
D.Strings[16179]="嗨，$n。我很高兴能远离那些该死的猴子！"
D.Strings[16180]="全能战士NX-01型当前处于离线状态。"
D.Strings[16181]="全能战士NX-01型在线。$B$B请塞入硬币，接受训练。"
D.Strings[16182]="我要再重申一次，$n，我们之间工作关系的发展实在是令我感到高兴。在我的心智得到大幅度提升之后的几个星期里，我的地精恩人们开始了解到我的智力已经超越了他们。虽然他们仍然对此深表怀疑。$B$B很遗憾，正是由于我的祖先没能阻止最近这一系列的工业化“事件”，现在的我才能变得如此无所不能……"
D.Strings[16183]="你会想看看幽暗城的模样。它就坐落在南边的旧洛丹伦废墟，你会找到一个下行的升降梯。等你到了，幽暗城的卫兵会给你更详细的指引。"
D.Strings[16184]="卡亚矿……你是否知道，就是这种传说中的玩意儿，帮助地精全族成为了炼金术和工程学的究极大师？！$B$B正是这种材料帮助我们推翻了压迫我们的丛林巨魔，控制了科赞——愿她得到安息——它是最珍贵的矿石！$B$B嗨，你不会是认为卡亚矿石对那些猴子也起了作用吧？"
D.Strings[16185]="散布在这一地区的废墟是暗夜精灵文明发展到顶峰时期留下的遗迹。对于研究奥术的人来说，它们是蕴含着无数珍贵信息的宝藏。$B$B看样子，一队最不同寻常的暗夜精灵法师已经注意到了它们。是的，听我说，$r——暗夜精灵要取回他们的魔法遗产！如果他们在这里发现了有价值的东西，很可能会导致可怕的后果。除此之外，我倒是觉得他们的举动很有些意思。"
D.Strings[16186]="<奥术构造体的“声音”似乎在你周围四面八方同时响起，撕扯你的耳膜，让你寒毛倒竖。这个构造体在用一种你听不懂的语言和你说话。就好象有多个话音叠加在一起，同时传入你的耳朵。>"
D.Strings[16187]="%s正在追赶你。快跑！"
D.Strings[16188]="%s开始释放一块毒云！"
D.Strings[16189]="不，是那个！那个！就是他！"
D.Strings[16190]="快点，趁他们在一起的时候上毒！"
D.Strings[16191]="不要乱动！站稳了，等我把他们都炸飞！"
D.Strings[16192]="%s开始不断召唤出炸雷！"
D.Strings[16193]="$n，我的孩子！$B$B你想要学习我的手掌热疗技术吗？$B$B不？绷带技术？你想要学习绷带技术？"
D.Strings[16194]="%s发动了一场白骨风暴！"
D.Strings[16195]="白骨风暴！"
D.Strings[16196]="请不要见怪，$n。也许你的确是一台狂野的杀戮机器，不过你现在至少还是我们这一边的。"
D.Strings[16197]="我还记得和我的兄弟一起在艾萨拉荒野上露营的时候。看看它现在的样子。"
D.Strings[16198]="真高兴能再看到你，$n。而且一根毛都不缺。"
D.Strings[16199]="时刻保持警惕，$n。"
D.Strings[16200]="%s发出怒吼，在黑暗力量的作用下开始膨胀！"
D.Strings[16201]="我能为你提供些什么，$n？"
D.Strings[16202]="对新武器有兴趣吗，$c？"
D.Strings[16203]="你知道些什么有关古剑的事？"
D.Strings[16204]="当我在失落群岛上束手无策的时候，我见识了我们新地精盟友的能力。但现在，我们要测试他们的才华了：我们要在敌人的要塞中与他们作战。"
D.Strings[16205]="有人不相信传说中的暗夜精灵莫霍克。$B$B真为他们悲哀。"
D.Strings[16206]="我相信你。"
D.Strings[16207]="幸会，莫霍克的好$G兄弟:姐妹;。"
D.Strings[16208]="霜牙，干掉那个蠢货！"
D.Strings[16209]="冰霜巨龙霜牙凝视着$n，准备发动一次冰霜袭击！"
D.Strings[16210]="因为在龙骨荒野发生的那场，啊，“误会”，我们不得不将全部设备都迁移到这座破旧肮脏的城堡里。$B$B不过我们现在有了足够的时间和场地来制作各种新鲜可爱的……产品……"
D.Strings[16211]="我准备好了。但是，我倒是愿意不参加这庆典。"
D.Strings[16212]="%s开始施放哀嚎之魂！"
D.Strings[16213]="%s开始|cFFFF0000释放灵魂！|r"
D.Strings[16214]="你将得到强大的祝福，好$r。"
D.Strings[16215]="第一场挑战要求你骑上一头银色战狼。你会在演武场的墙边找到这些坐骑，骑着它们来找我，然后我们继续。"
D.Strings[16216]="%s释放毒气孢子！"
D.Strings[16217]="%s开始施放|cFFFF7F00刺鼻毒气！|r"
D.Strings[16218]="你们的努力是徒劳的，入侵者。巫妖王让我统率的可是一支亡灵大军！小心了！"
D.Strings[16219]="固执的家伙！你们根本到不了主人的密室！士兵们，消灭他们！"
D.Strings[16220]="霜牙，把他们困在隧道里！统统给我埋了！"
D.Strings[16221]="|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 过热  |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t"
D.Strings[16222]="圣光与你同在……只需要掏一两个银币！"
D.Strings[16223]="这不算很厉害，但它也许刚好能保护到你的绿皮肤。"
D.Strings[16224]="只想让你知道，我们全都在指望你呢！"
D.Strings[16225]="要让我说的话，暗夜精灵在一万年以前就已经丢掉了这个地方。今天他们被我们驱逐只不过是一个形式上的事情。"
D.Strings[16226]="在这见到我吃惊吗？每个人都需要干净衣服，除了找你的水元素帮忙，还有更好的办法吗？$B$B只需把你的衣服拿来，象征性的付点钱，不知不觉中你的衣服又变得清爽、干净！"
D.Strings[16227]="奥术师泰拜林说你会借我一件战袍。"
D.Strings[16228]="你很走运。我刚装了些你需要的，正准备拿去洗。"
D.Strings[16229]="看到大堆的衣服和那桶水了吧？我会大声喊需要什么，你就把需要的扔进盆里。准备好了吗？"
D.Strings[16230]="哦，不！不应该这样的。现在我们不得不再弄些清洁剂重新开始了！"
D.Strings[16231]="别人会取代他。你是在浪费时间。"
D.Strings[16232]="你们之中的某一个能不能快点把对方干掉？我们可是急着要拿钱呐！"
D.Strings[16233]="朝桶里扔几条裤子！"
D.Strings[16234]="快点儿，扔几件衬衫到洗衣桶里！"
D.Strings[16235]="加几件儿恶心的…呃，我是说，“棘手的”！"
D.Strings[16236]="桶里需要加水！"
D.Strings[16237]="看到人多好办事了吧？尽管从干净的里面挑你需要的吧，不过别忘了穿完了再送回来。"
D.Strings[16238]="阿夸诺斯，别把衣服扔那么高了！我知道你不用看艾萨斯·夺日者在喷泉找到自己裤子时的脸色！"
D.Strings[16239]="太强大了。我们必须马上离开！我的魔法只能暂时拖住他。快来，英雄们！"
D.Strings[16240]="你来这要干什么，$c？"
D.Strings[16241]="魔导师哈瑟尔，我已经做好递送宝典的准备了。"
D.Strings[16242]="永远不要相信那些夺日者。他们不遗余力的破坏我们和银色北伐军盟友的关系。"
D.Strings[16243]="找到你了！我几乎以为你已经被逐日者劫走了。你准备好把宝典递送给冰冠冰川的使者了吗？"
D.Strings[16244]="你能为我准备一套新的夺日者伪装吗？"
D.Strings[16245]="魔导师哈瑟尔，你能为我准备一套新的银色盟约伪装吗？"
D.Strings[16246]="<这头恐龙紧盯着你，大声咆哮着，嘴里不停地流出口水。>$B$B<看样子，九号实验品留下了一个她的克隆品，只是这个克隆品的智力没有像她一样得到强化。她这样做大概是为了隐藏自己的行迹。聪明的女孩！你在考虑你给这个宇宙带来了什么……>"
D.Strings[16247]="等等！停！别杀我！我把一切都告诉你！"
D.Strings[16248]="你要找的就在主人的巢穴里，但要先干掉泰兰努斯才能进去。霜之哀伤就在映像大厅里……你们……你们能在它那里找到真相。"
D.Strings[16249]="我发誓我没说谎！求你了！别杀我！"
D.Strings[16250]="啊…不！！"
D.Strings[16251]="为什么女妖之王要饶恕你的小命？"
D.Strings[16252]="霜之哀伤？巫妖王从不离开他的佩剑。如果你撒谎……"
D.Strings[16253]="叛徒就是这种下场。来吧，我们必须解救那些奴隶，再看看巫妖王的密室中都有什么。"
D.Strings[16254]="没用的虫子！死亡正等待着你！"
D.Strings[16255]="不要以为我会那么容易让你进入主人的密室。有本事放马过来吧。"
D.Strings[16256]="我不会因为你的可怜而手下留情，有话快说吧。"
D.Strings[16257]="恶有恶报。来吧，英雄们。去看看那个侏儒说的是真是假。如果阿尔萨斯没了霜之哀伤，我们也许有机会阻止他。"
D.Strings[16258]="霜之哀伤无人守卫？不可能！"
D.Strings[16259]="我们准备好了！出发！"
D.Strings[16260]="我没办法阻挡他太久，我们必须马上离开！"
D.Strings[16261]="只有几次漂亮的坠毁才能真正“磨砺”一台飞行器。$B$B任何头脑正常的地精都不会只安心于安全的飞行。"
D.Strings[16262]="为什么你要破坏我们的家园？！"
D.Strings[16263]="你打破我们的洞穴，我要打破你的脑袋！"
D.Strings[16264]="穴居人洞穴全完了！你要为此付出代价！！"
D.Strings[16265]="你来自寻死路吗？很高兴能帮到你。"
D.Strings[16266]="旧伤尚未复原，$g小伙子:姑娘;。我尚能深深地感觉到。没错，我还有仇要向阿尔萨斯报，当他还未成气候时我就应该好好教训他，我会给他补上这个的。总是感觉他有些不对劲。$B$B你的船员准备好以后告诉我一声，我们准备起飞直达堡垒的顶部。$B$B阿尔萨斯决不会料到这一招！"
D.Strings[16267]="我的战友全都加入，穆拉丁。出发吧！"
D.Strings[16268]="这是我们最后的阵地。今天的一切都将千古流传。无论是生是死，我们都是为了荣誉而战。我们都是为了自由和人民而战！记住，英雄们，在这邪恶之地，恐惧是你们最大的敌人。勇气将让你们的灵魂比千颗太阳还要明亮。敌人会在你们面前溃不成军。正义的光芒将彻底摧毁他们！"
D.Strings[16269]="$G先生:女士;"
D.Strings[16270]="元素变幻莫测，没有受过训练的双手很难控制它们。很抱歉，我并不需要你。"
D.Strings[16271]="能拥有如此众多忠诚而具有献身精神的学徒，这是我的幸运。如果没有这些测试样品，我的工作也不可能进行。"
D.Strings[16272]="准备战斗，北伐军的弟兄们。维库人会用他们的生命保护冰霜女王。"
D.Strings[16273]="都给我严肃点！我们的勇士已经到了，我们要奋勇战斗，支援他们！"
D.Strings[16274]="卫兵！把这个$r用链子锁住！"
D.Strings[16275]="我宁愿死在这里，也不要为那个疯子芬克斯坦收集材料。"
D.Strings[16276]="不要打我！告诉匹克，我变好了。"
D.Strings[16277]="先是大火，现在又是$r！你死定了！"
D.Strings[16278]="你问我们要干什么？我们在等待。"
D.Strings[16279]="真不知道那些灵魂为什么要如此排斥我们。"
D.Strings[16280]="孩子，别担心。格瑞克尼尔会帮助我们。"
D.Strings[16281]="格瑞克尼尔说他会和这个元素谈谈，让它帮助我们作战。"
D.Strings[16282]="我们很快就会占领这座山谷。"
D.Strings[16283]="那些灵魂痛恨我们。"
D.Strings[16284]="我们的世界是一片冰雪之地。"
D.Strings[16285]="但孩子，在那片大地之下，燃烧着永恒的烈火。"
D.Strings[16286]="来自于深渊彼方的灵魂正在同格瑞克尼尔交谈。"
D.Strings[16287]="我们得到命令，要再次进行冲锋。而迎击我们的是一片长矛组成的壁垒。我做不到，$c。我的武器滑出了双手，两条腿也无法动弹。$B$B我玷污了自己的荣誉。"
D.Strings[16288]="我的指挥官就在我的眼前被杀害了，兄弟们不断地在我身边倒下。我无法继续战斗下去。我没有能为他们报仇，$c，我让他们蒙受了羞耻。"
D.Strings[16289]="不要看我，$r，我让部落蒙羞，我彻底完蛋了。"
D.Strings[16290]="任何兽人都不应该像我一样逃离战场。别理我，让我单独咀嚼自己的耻辱吧。我不害怕死在这座塔里，却害怕知道我的祖先会如何看待我的懦弱。"
D.Strings[16291]="去工作，孩子们！"
D.Strings[16292]="不要着急，我们很快就能出去。"
D.Strings[16293]="我们要保持这股火继续燃烧，矮人们！"
D.Strings[16294]="乔恩在那里干什么？"
D.Strings[16295]="只有当你潜入雪层时，你的冰虫才能够移动，但潜入后你的冰虫无法攻击。浮出雪层的冰虫可以使用它强大的酸性攻击穿透钢铁巨像的护甲。要做好随时下潜的准备以躲避钢铁巨像最具毁灭性的攻击。"
D.Strings[16296]="还没有哪支队伍能够把这么不利的局势扳回来！"
D.Strings[16297]="谢谢！从这里开始，我自己就能搞定了。"
D.Strings[16298]="你是大救星！为了铁炉堡！"
D.Strings[16299]="啊，这下好多了。我欠你一个人情。"
D.Strings[16300]="火箭背包不见了？看看在不在背包里。"
D.Strings[16301]="原谅我，英雄们。我应该听乌瑟尔的。我……我只是希望能够，能够看他最后一眼。对不起。"
D.Strings[16302]="我们知道该怎么做了。我会把这个消息带给瓦里安国王和弗丁大人。"
D.Strings[16303]="这……这是死路！我们别无选择，只能战斗。准备迎战，英雄们，这是我们最后的阵地。"
D.Strings[16304]="穷途末路……变成我的奴仆吧！"
D.Strings[16305]="那些山丘和隐秘的小路就是我的家。许多年以来，我一直利用它们进行狩猎。$B$B但我从没有想过会利用它们进行一场战争。"
D.Strings[16306]="几年以前，恐怖图腾袭击了我的村庄。直至今日，痛苦、愤怒和失落仍然沉重地压在我的心上。$B$B现在，我自己却在安慰和帮助其他失去了自己村庄的人。"
D.Strings[16307]="那么，你打算钻进这条隧道……？"
D.Strings[16308]="借助这些隐秘的路径，我们能够对下面的敌人发动猛烈的进攻。$B$B游击战算不上是荣誉的行动，但一名优秀的战士明白该如何让他的敌人措手不及。"
D.Strings[16309]="滚回去，你这个肮脏的怪物！"
D.Strings[16310]="来尝尝矮人的枪子儿吧！"
D.Strings[16311]="为了铁炉堡！"
D.Strings[16312]="$c，你想要什么？"
D.Strings[16313]="$n，那些巨魔可真奇怪。我不喜欢这样，一点也不喜欢。"
D.Strings[16314]="把他们引到这里来。我们会支援你。"
D.Strings[16315]="快！推进！"
D.Strings[16316]="她的援兵就要到了！我们必须迅速消灭她！"
D.Strings[16317]="我来挡住她。让我的兄弟回到坟墓中去，然后帮我消灭她！"
D.Strings[16318]="愚蠢的科罗克。你带来了我的援军。银色勇士们，用你们的死来效忠巫妖王吧！"
D.Strings[16319]="你也许曾和我并肩作战，科罗克，但现在你只不过是一个叛徒。接受你的第二次死亡吧！"
D.Strings[16320]="你就是我要找的$c！我正在测试一种新的火箭助推飞行器，我需要你的帮助！\n\n拿上一个控制器放到你的护甲里。按下侧面的按钮，砰，你就飞起来了。\n\n不过你别想把它私吞了。每个飞行器都装有推进器8000，并且和我手里这个相连接。如果你飞得太远，推进器就会关闭主引擎，你便无法起飞，除非回到我这里。\n\n我把那些责任书放哪了？"
D.Strings[16321]="没错，你最看重的是安全。给我个火箭背包。"
D.Strings[16322]="记住，英雄们，在这邪恶之地，恐惧是你们最大的敌人。勇气将让你们的灵魂比千颗太阳还要明亮。敌人会在你们面前溃不成军。正义的光芒将彻底摧毁他们！"
D.Strings[16323]="现在，我们向冰冠堡垒进军！"
D.Strings[16324]="阿尔萨斯！我发誓会彻底消灭你和天灾军团！昔日的恩怨会在今天做个了断！"
D.Strings[16325]="我为这个灵魂耗费了巨大的力量，让他承受了无数痛苦……他抵抗了那么长时间，但用不了多久就会屈服了。"
D.Strings[16326]="绝不！我……绝不……服从你。"
D.Strings[16327]="弗丁领主，这是真的？如果伯瓦尔还活着，也许联盟和部落之间还有和平的希望。我们必须冲到堡垒顶层，救出圣骑士！"
D.Strings[16328]="圣光在上，胜利属于我们！"
D.Strings[16329]="让破天号做好空袭城堡的准备！"
D.Strings[16330]="敌人的数量远远超过我们，我们与十字路口和杜隆塔尔的联系已经被切断。但一个兽人能打败十个联盟懦夫。$B$B我们要对他们迎头痛击，把他们像赶猪群一样轰走。"
D.Strings[16331]="英雄们，你们必须尽快在冰冠堡垒内部夺取一个立足点。我们在城墙上汇合！"
D.Strings[16332]="联盟耍了一个极端狡诈的诡计，$n。联盟的军队从北方城堡出发，沿着黄金之路前进，在日暮时分向十字路口发动了进攻。到了深夜，他们又掉头南进，只留下空无一人的营地和依旧在燃烧的篝火。$B$B当黎明的第一缕曙光出现时，我们在荣耀岗哨的大军突然遭到了联盟的猛烈袭击。大批联盟士兵冲过隘口。我们许多最勇敢的战士都死在了他们的刀锋之下。"
D.Strings[16333]="好消息！各位！我修好了毒性软泥管道！"
D.Strings[16334]="那名圣骑士还活着？是真的吗，大领主？他居然还活着？"
D.Strings[16335]="那我们必须去救他！如果我们救出了伯瓦尔·弗塔根，就能平息联盟和部落无休止的纷争。"
D.Strings[16336]="任务已经明确：巫妖王将为他的罪行付出代价，我们一定要救出伯瓦尔·弗塔根公爵。"
D.Strings[16337]="库卡隆，为最后的冲锋做好准备！勇士们，炮船将在那座堡垒的顶部着陆。我们在那里汇合！"
D.Strings[16338]="圣光的力量没有止境，萨鲁法尔。他的灵魂饱受压抑，但他现在，还活着。"
D.Strings[16339]="是的，我们在隘口东边重新集结，准备发动反击。但在第二天，天空变成了赤红色，大地分裂成两块，就好象一块被小孩掰开的饼干。在地平线与地平线之间，一切都惨遭凌夷。$B$B刚刚建起防御碉堡的联盟军队也像我们一样惊恐异常，茫然不知所措。这本来是最佳的进攻时机！但督军加杜尔坚持要撤往南方，重组队伍。$B$B<基洛克向地面上啐了一口。>$B$B我们之中有许多人没有跟着他走。在上一场战争中，我曾经和恶魔正面交战，半步未退，$n。现在我也不打算掉头逃跑，让联盟占据我们的土地。"
D.Strings[16340]="是的，我们继续作战。也许我们难免一死，但我们不会给他们半寸土地，$c。$B$B敌人的数量远远超过我们。我们的盔甲破碎，武器损坏。$B$B但这是我们的土地！我们的牛头人盟友熟悉这片山丘中的每一条小道、裂谷和每一个山口。我们埋伏在高地上，向联盟发动了出其不意的突袭，然后又像影子一样消失。恐惧就是我们的武器，我们要向敌人发动毫无止歇的攻击。"
D.Strings[16341]="哦，天哪。菲利克斯的情况并不乐观。"
D.Strings[16342]="吹个球，吹个“卟卟”会爆的大气球！"
D.Strings[16343]="|TInterface\\Icons\\spell_shadow_unstableaffliction_2.blp:16|t%s开始施放|cFFFF0000不稳定的软泥爆炸！|r"
D.Strings[16344]="可怜的生物！死吧！"
D.Strings[16345]="你认为我什么时候能离开？我还要回去工作呢。"
D.Strings[16346]="那些穴居人到底是从哪里来的？他们一直都住在地下吗？"
D.Strings[16347]="你最好能安下心来。在穴居人被消灭干净之前，铁枷不会让任何人出去。"
D.Strings[16348]="外面有什么新闻吗？我听说那些巨魔也在蠢蠢欲动。"
D.Strings[16349]="这里真是拥挤得令人窒闷。我在密闭空间里总是感到不自在。"
D.Strings[16350]="试想一下，在经历了灾变程度的大地震后，你最不想待的地方应该就是屋里了，不是吗？"
D.Strings[16351]="$n! 我听说你是铁枷的新$r奴隶。她要你做些什么？"
D.Strings[16352]="我觉得自己永远都要被关在这里了。已经到美酒节了吗？"
D.Strings[16353]="永远……差那么……一点儿……"
D.Strings[16354]="这是为了让我得到变质的蜘蛛毒液！"
D.Strings[16355]="你们这些傻瓜永远找不到一只像样的蝙蝠翅膀。"
D.Strings[16356]="不要……让芬克斯坦拿我……做药……"
D.Strings[16357]="天哪，这里全都是石头！"
D.Strings[16358]="我几乎放弃了希望。"
D.Strings[16359]="你好吗，$c？"
D.Strings[16360]="到黄昏时分，火舌已经照亮了天空。我失去了一切。一切。$B$B为什么他们要烧掉一家旅店？"
D.Strings[16361]="<克尔苏瓦避开你的眼睛。>$B$B我在战斗中逃了出来，但没有能及时放开所有被拴住的牲口。$B$B我没办法聚拢它们，结果它们全都逃进烟雾里去了……"
D.Strings[16362]="火山岩！来看看这里的火山岩吧！"
D.Strings[16363]="出售火山岩！刚离开火山，还热气腾腾哪！你想要的，就在我这里！"
D.Strings[16364]="火山岩，最新低价！你一定会爱上我的岩石。"
D.Strings[16365]="来看看这里的火山岩吧！……对猫正合适！"
D.Strings[16366]="把大灾变的纪念带回家吧！出售火山岩——火热，火热，火热的火山岩！"
D.Strings[16367]="能做镇纸，能挡门，还能砸窗户！来看看，来看看！火山岩。"
D.Strings[16368]="火山岩。用法多多。"
D.Strings[16369]="火山岩！限时供应！配有品质证书和一切相关手续！"
D.Strings[16370]="%s 准备释放一波严寒！"
D.Strings[16371]="绝望吧，体会主人那无穷无尽的力量吧！"
D.Strings[16372]="在牛头人语中，“乌纳菲”是避难所的意思。但这个名字已经不再合适了。从我们建起这座营地的时候开始，这片诡异的丛林就要将这座营地吞噬。"
D.Strings[16373]="当我们最强壮的战士进行狩猎的时候，他们对陶拉祖发动了进攻。我们遇到的也许是一个奇迹。在联盟的阵线中出现了一个缺口。所以我和另一些人才能带着这些小东西逃出来……$B$B<塔瓦妮的声音低沉了下去。他正努力不让自己在孩子们的面前哭出来。>"
D.Strings[16374]="<静电噪音>$b这东西连通了吗？喂？"
D.Strings[16375]="在援兵赶到前我会尽量拖延时间，但你必须继续前进。$B$B阿尔萨斯很快会发现我们在这里。"
D.Strings[16376]="啊，你在这里。你好！我想，既然你飞去了卡拉诺斯，我应该告诉你一下寒脊山谷外都发生了什么事。"
D.Strings[16377]="看样子，你们这些寒脊山人根本不知道过去几天发生了什么。"
D.Strings[16378]="如果你们以为寒脊山最大的问题是巨魔，那么就到卡拉诺斯去看看吧！这场大灾变让巨魔全都发了疯。"
D.Strings[16379]="你能抵挡野猪启示录吗？"
D.Strings[16380]="你……没有被那些野猪干掉？<哼哼>那么多野猪！真让我难过！<呼噜>"
D.Strings[16381]="软弱的凡人……"
D.Strings[16382]="也许……你是对的，科罗克。"
D.Strings[16383]="你们的入侵结束了！无人可以生还！"
D.Strings[16384]="你能感受到死神之手的那股寒意吗？"
D.Strings[16385]="痛苦吧，凡人，你们可怜的魔法背叛了你们！"
D.Strings[16386]="终于……自由了……"
D.Strings[16387]="够了！我厌倦了这些游戏！"
D.Strings[16388]="这看上去像是萨洛瑞安·寻晨者的遗体，奎尔德拉最后的使用者。"
D.Strings[16389]="一声尖叫直入云霄！"
D.Strings[16390]="什么？这就死了？这也不错。"
D.Strings[16391]="啊！我必须休息一下了。"
D.Strings[16392]="勇士们！我就要挡不住她了。"
D.Strings[16393]="他……太强大了。英雄们，快，快过来！我们必须马上离开！你们先走。我会尽全力挡住他。"
D.Strings[16394]="天杀的死路！看来真的无路可走了。准备战斗，英雄们，让我们放手一搏！"
D.Strings[16395]="我们暂时……安全了。他的力量已经十倍于往昔。只有一支大军才能战胜巫妖王。单凭部落的力量毫无胜算。"
D.Strings[16396]="你的盟友到了，吉安娜，你说的没错。全都变成效忠我的天灾战士吧。"
D.Strings[16397]="我不会再犯同样的错误，希尔瓦娜斯。这次你走不了了，你们死后都会成为我的奴仆！"
D.Strings[16398]="阴冷的死亡等待着你。"
D.Strings[16399]="屈服于死亡的严寒吧！"
D.Strings[16400]="死路一条！"
D.Strings[16401]="你们无路可逃！"
D.Strings[16402]="接受现实吧，$c。$b$b巫妖王的统治已经到了尽头。"
D.Strings[16403]="灰烬审判军是怎么一回事？"
D.Strings[16404]="灰烬审判军是由黑锋骑士团和银色北伐军中的精英工匠组成的一支队伍。他们的创造标志了一种团结，各支力量齐心协力同巫妖王及其爪牙展开最终的战斗。  $b$b正是通过灰烬审判军的努力，我们掌握了如何将源生萨隆邪铁为我们所用的方法。"
D.Strings[16405]="如何学习加工源生萨隆邪铁？"
D.Strings[16406]="$c，和炼金师菲肯斯坦谈谈。他会为你指明道路。$b$b表明你的忠诚，你就会知道他们的办法。"
D.Strings[16407]="巫妖王已经离我们很近了，$n。我感觉到了他声音中的嘲弄…$b$b去让他安静下来吧！"
D.Strings[16408]="住手！你快把那剑放下！"
D.Strings[16409]="你知道你在干什么吗？"
D.Strings[16410]="你用上古之神的血，萨隆邪铁重铸了这把剑。巫妖王的力量会召唤它。"
D.Strings[16411]="只有一个办法能净化它。赶快到太阳之井去，将剑沉入井水之中。"
D.Strings[16412]="我抵抗不住霜之哀伤的召唤…"
D.Strings[16413]="%s准备攻击！"
D.Strings[16414]="立刻上船！快！这面山壁随时都可能塌陷。"
D.Strings[16415]="快！立刻上船！此地不可久留，整面山壁随时都可能塌陷。"
D.Strings[16416]="看这些小东西，你给加弗斯特带来了好吃的！"
D.Strings[16417]="可以留下来当个小点心。"
D.Strings[16418]="这个好像不……不太好吃。加弗斯特真笨！真笨！"
D.Strings[16419]="加弗斯特不想弄的太狼狈。不想给头领丢脸。晚了。"
D.Strings[16420]="我们的工作绝不能被干扰！伊克，招呼他们！"
D.Strings[16421]="这些部件也许对我们有用。"
D.Strings[16422]="我们正缺胳膊和腿呢！感谢你们的大力援助！"
D.Strings[16423]="我改主意了，现在我要的是这个！"
D.Strings[16424]="你打这个家伙干什么？真正危险的人在那儿，傻子！"
D.Strings[16425]="嗨！我来自皇冠药剂公司。$B$B你在寻找礼物吗？还是要找份工作？想不想送自己点东西？好吧，你来对地方了，朋友。$B$B如果我没有你想要的东西，那么在我旁边的福星基维或是可爱的商贩一定会有。"
D.Strings[16426]="我们要利用那些补给为所有人做好战斗的准备。$B$B继续吧。我们会再见面的。"
D.Strings[16427]="我会集结其它的奴隶，被让他们做好战斗的准备。在你同天灾领主泰兰努斯开始交战前我们会赶上你的。"
D.Strings[16428]="我曾经在陶拉祖营地安全的环境中训练年轻的猎人熟悉荒野之道。$B$B现在我们不能奢望再有那种条件了。敌人已经踏过了我们的门槛，我们的年轻人必须在与敌人的激烈搏杀中学会战斗的技巧。"
D.Strings[16429]="英雄们！我们就算拼了性命，也会挡住那些亡灵。去消灭天灾领主吧！"
D.Strings[16430]="唉，勇敢的冒险者，你们的路已经到头了。难道你们没有听到身后隧道里钢铁撞击的声音吗？那就是末日降临的乐章。"
D.Strings[16431]="哈，一群不自量力的乌合之众。等我杀了你们之后，主人的剑就能尽情享用你们的灵魂了。去死吧。"
D.Strings[16432]="英雄们，我们会追随你们的领导。今夕就是天灾领主的死期。"
D.Strings[16433]="终于，开始了……"
D.Strings[16434]="看啊！神圣与堕落的结合，那就是影锋，一把潜能无限的武器。"
D.Strings[16435]="让它服从你，你就能获得无法想象的力量！"
D.Strings[16436]="如果失败，你的灵魂就将永远被奴役。"
D.Strings[16437]="%s向$n施放|cFF00AACC深度冻结|r。"
D.Strings[16438]="我以为我会死在这坑里。谢谢你！"
D.Strings[16439]="我欠你一顿好酒，我的朋友。"
D.Strings[16440]="收下我的礼物吧。"
D.Strings[16441]="不要放走任何一个。"
D.Strings[16442]="拜托了，为我们向天灾领主报仇。"
D.Strings[16443]="在你打败矿坑的头目以后，替我向他的尸体吐口水，好吗？"
D.Strings[16444]="在这个被遗忘的区域，我迷失在了时间的长河中。能见到你真不错，我的朋友。"
D.Strings[16445]="你的出现是美妙的一幕…对此你可能还并不能理解。"
D.Strings[16446]="我们在这个大坑里损失太多人了。太多太多了。"
D.Strings[16447]="很高兴你来了。我本来撑不了那么久的。"
D.Strings[16448]="报仇的时刻到了。"
D.Strings[16449]="来个男人强有力的拥抱吧。"
D.Strings[16450]="我真想吻你！"
D.Strings[16451]="总有一天我会想办法报答你的，我的英雄。"
D.Strings[16452]="我简直无法相信自己的眼睛。谢谢你。真的，谢谢你。"
D.Strings[16453]="%s点头表示感谢。"
D.Strings[16454]="%s露出了感激的笑容。"
D.Strings[16455]="%s跌跌撞撞向你走来时几乎要倒下去了。"
D.Strings[16456]="%s对自己的命运发出了短短的一声苦笑。"
D.Strings[16457]="%s举起空着的手向你做了个敬酒的姿势。"
D.Strings[16458]="%s给了你一个飞吻。"
D.Strings[16459]="%s闭上了眼睛，细细品味了一下自由的味道。"
D.Strings[16460]="%s每挥出一锄时都完全任由矿工锄拖在地上，明显体力不支。"
D.Strings[16461]="为了报答你，我愿付出任何代价。"
D.Strings[16462]="我要回去帮助解救其它奴隶。再次感谢你，英雄。"
D.Strings[16463]="我要回到采石场前线去。帮我多杀几个。"
D.Strings[16464]="贫瘠之地现在也许是干枯荒凉的，但这片土地曾经生机勃勃。我们在这里漫游、狩猎，过着丰足的生活。$B$B然后，联盟来了……他们烧杀抢掠。被他们蹂躏过的地方，现在被我们称为鲜血旷野，$c。$B$B那里的居民已经全部流亡到其它地方。留下来的只有继续与敌人苦战的士兵。"
D.Strings[16465]="快点。士兵们已经出发了。"
D.Strings[16466]="寻找一切可以做掩护的东西。"
D.Strings[16467]="我们还没有将这家旅店里的敌人清除干净？完成这个任务之后就把它一把火烧掉！"
D.Strings[16468]="这帮家伙身上只有些破珠子和硬皮。财宝到底在哪里？"
D.Strings[16469]="我们在浪费时间。这个地方必须在他们发动反攻之前清理干净。"
D.Strings[16470]="嗨，有人搜过信箱了没？"
D.Strings[16471]="还应该有更多的东西。再把他们搜查一遍！"
D.Strings[16472]="有人见到那些被关在笼子里的野猪人吗？"
D.Strings[16473]="去试试吧，老板！"
D.Strings[16474]="勇士们，你们救了我们，还我们自由……这种大恩大德我们无以为报。但我发誓，从今往后所有人都会知道你们的事迹，知道你们如何在这座黑暗的城堡中劈开一条光明之路。"
D.Strings[16475]="今天我们不仅见证了你们的勇猛，还见证了联盟和部落抛开仇怨，精诚团结的力量。有了这种力量，即使是巫妖王也会败倒在你们脚下。"
D.Strings[16476]="嘿，伙计，我不认识你，也不知道你为什么要一直跟着我，但我马上就要上船了，并且我想自己一个人呆着，明白吗？"
D.Strings[16477]="斯内维尔，我这有一只火箭，上面有你的标记。"
D.Strings[16478]="%s施放了|cFFFFFF00灵魂倒映!|r"
D.Strings[16479]="干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务会在目的地等着你。"
D.Strings[16480]="感谢圣光，你安然无恙！为了消灭巫妖王和天灾军团，我们还有很多事要做。"
D.Strings[16481]="银色北伐军和黑锋骑士团的盟军已经打破冰冠堡垒的大门，他们正努力在城堡中建造一个前哨站。"
D.Strings[16482]="我们在这些厅堂中的发现将决定他们的成败。虽然任务危险重重，但我们必须坚持！"
D.Strings[16483]="当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找有用的重要情报，从而一劳永逸地铲除天灾军团。"
D.Strings[16484]="瓦里安国王的军情七处得到情报，巫妖王的私人密室就深藏在一个被称作映像大厅的地方。"
D.Strings[16485]="我们要想办法杀出一条通往映像大厅的血路。我感到那里潜藏着强大的魔法。那将是摧毁天灾军团的关键！"
D.Strings[16486]="你的首个任务是摧毁灵魂引擎中的死亡机器，为我们的士兵杀出一条路来。"
D.Strings[16487]="赶快，勇士们！我会让部队紧跟在你们身后。"
D.Strings[16488]="银色北伐军和黑锋骑士团已经攻入冰冠城堡大门，正准备向天灾军团发动总攻。我们的任务虽小，但同样重要。"
D.Strings[16489]="当巫妖王的注意力被吸引到前门的时候，我们就从侧翼潜入，寻找能帮助我们的重要情报，彻底除掉巫妖王。"
D.Strings[16490]="我们的侦察兵说巫妖王在冰封王座外有个私人密室，深藏在被称作映像大厅的地方。那就是我们的目标，勇士们。"
D.Strings[16491]="我们会一路杀进这个被诅咒的地方，找到进入映像大厅的入口。那里一定隐藏着某些极具价值的情报。"
D.Strings[16492]="黑暗女王正在看着你，加紧行动！"
D.Strings[16493]="干得漂亮，勇士们！我们将在这些房间里建立营地。我的人很快就能让这架天灾传送器恢复工作。准备好就站进去。我和新的任务在目的地等着你。"
D.Strings[16494]="在援兵赶到前我会尽量拖延时间，但你必须继续前进。阿尔萨斯很快会发现我们在这里。"
D.Strings[16495]="%s向你用力投出一大块萨隆邪铁巨石！"
D.Strings[16496]="有人闯进了主人的房间！"
D.Strings[16497]="那是一场激烈的战斗，$n！集结部队、重整旗鼓。谁知道在那道门后面等待我们的是什么？$B$B准备好以后告诉我，我们准备向上游攻打敌人的堡垒。"
D.Strings[16498]="我们准备好了，穆拉丁。"
D.Strings[16499]="你能肯定吗，$g 伙计:小姑娘;？再给你一两分钟？"
D.Strings[16500]="确信无疑。出发吧！"
D.Strings[16501]="那我们要行动了，我们要……"
D.Strings[16502]="你每消灭一名部落士兵，或是杀死一只联盟狗。巫妖王的军力就会增长一分。瓦格里正在把你们的阵亡者变为天灾战士。"
D.Strings[16503]="你们就要大祸临头了。来吧，尝尝巫妖王赐予我的力量吧！"
D.Strings[16504]="区区一个兽人竟然想与联盟对抗？？？"
D.Strings[16505]="冲锋！！！"
D.Strings[16506]="欢迎来到凄凉要塞，$c。我们在此等待时机，向联盟还以颜色。"
D.Strings[16507]="快一点， $c。酋长亲自派我来评估我们在贫瘠之地的工作进展，然而我却在这里看到我们的城镇燃起大火，联盟败狗肆无忌惮地发狂。"
D.Strings[16508]="你很有潜力，$n。要想重获对贫瘠之地的控制权，就绝对少不了像你这样的精兵。"
D.Strings[16509]="我第一眼看到它，就知道这是一把龙铸之刃。"
D.Strings[16510]="怎么可能？难道真的……？"
D.Strings[16511]="这把剑的形制和铭文表明它是一把龙铸之刃。终于，答案找到了。"
D.Strings[16512]="过了这么多年，难道它真的……"
D.Strings[16513]="矮人……"
D.Strings[16514]="血柄督军？加尔鲁什的狗腿子？$B$B正如你看到的，这儿不需要他——啊，告诉他这里的一切状况都在我的掌握之中。"
D.Strings[16515]="但是，啊，目前的供给非常紧张。而且，呃，我这里的人力也很短缺。告诉血柄，啊-"
D.Strings[16516]="我……终于……解脱了……"
D.Strings[16517]="冰霜女王飞走了。我们……我们必须继续前进——目标就在眼前。"
D.Strings[16518]="英雄们，到我这来！"
D.Strings[16519]="我……我救不了他们……该死，阿尔萨斯！你这恶魔！"
D.Strings[16520]="不要再耽搁了，他——啊——他就快到了！$B$B到最北边塔的塔顶找我"
D.Strings[16521]="奎尔德拉。"
D.Strings[16522]="巨龙铸造出奎尔塞拉，送给了卡多雷；而将奎尔德拉，送给了我们。"
D.Strings[16523]="国王将它赠予了我的朋友，萨洛瑞安·寻晨者。"
D.Strings[16524]="但即使是萨洛瑞安的力量和奎尔德拉的魔力也无法从天灾手中拯救银月城。"
D.Strings[16525]="为掩护族人逃生，萨洛瑞安在太阳之井的大门前壮烈牺牲。"
D.Strings[16526]="我曾经发过誓，再没有任何东西能让我重新拿起这把剑了。$B$B我是个傻瓜。"
D.Strings[16527]="战后，我从战场上找回这把剑，为了我的王子，为了替我的族人复仇，我把它带到了诺森德。"
D.Strings[16528]="阿尔萨斯粉碎了我们，将我们最强大的战士变成他的爪牙，萨莱因。"
D.Strings[16529]="对萨洛瑞安的回忆已和他的剑一样冰冷。"
D.Strings[16530]="是我将奎尔德拉带来，交给它的铸造者，只为打碎这把武器，消除它的力量。"
D.Strings[16531]="奎尔德拉只能有一个主人！"
D.Strings[16532]="%s气喘吁吁。"
D.Strings[16533]="这就是萨鲁法尔的儿子——部落在天谴之门的指挥官。真是个悲剧……"
D.Strings[16534]="远处那里……那里是什么！"
D.Strings[16535]="士兵们，集合！看样子部落马上又要射击了！"
D.Strings[16536]="不出所料……"
D.Strings[16537]="你真以为能轻易地完成莫格莱尼的任务？"
D.Strings[16538]="你们会和他父亲一样饱受折磨……"
D.Strings[16539]="永不得安息！"
D.Strings[16540]="死吧，蠢货。"
D.Strings[16541]="你们这些蠢货胆敢闯入这里。诺森德的冰风将卷走你们的灵魂！"
D.Strings[16542]="见证逐日者夺回奎尔德拉是我们的使命。"
D.Strings[16543]="我发誓，银色盟约终将迎来奎尔德拉的回归。"
D.Strings[16544]="就是这里。我能感觉到这就是发生那场大悲剧的地方。痛苦的嚎叫仿佛仍然在这里回荡。毫无疑问，这就是那些异界的恐怖曾经肆虐横行的地方。$B$B为了能彻底将那些异界怪物入侵这个世界的道路封死，我必须先将它完全打开。那时，我需要你的力量来挡住可能从其中出来的一切东西。$B$B你准备好了吗？"
D.Strings[16545]="别逼我，兽人。我不能让你过去。"
D.Strings[16546]="躺在那里的是我唯一的儿子。无论什么也不能把我和他分离。"
D.Strings[16547]="我，我不能这样做。回到船上去，我就饶你一命。"
D.Strings[16548]="退后，穆拉丁，让这位伤心的父亲过去。"
D.Strings[16549]="我不会忘记您的……仁慈。感谢您，殿下。"
D.Strings[16550]="我……那时不在天谴之门。但活下来的士兵告诉了我当时的情况。你的儿子为荣耀而战，他英勇地战死，应该得到英雄般的厚葬。"
D.Strings[16551]="你在与天灾的战争中立下了大功。愿圣光给你恩泽。"
D.Strings[16552]="战斗难免牺牲，而我们的战友无论生死，都会效忠银色北伐军。"
D.Strings[16553]="拯救这个邪恶之地非你莫属，谢谢你。"
D.Strings[16554]="小心前面潜伏的危险……就是死也要留个全尸。"
D.Strings[16555]="火箭背包启动！"
D.Strings[16556]="火箭背包已关闭。移至扎福德·波姆布克斯旁边以重新启动。"
D.Strings[16557]="躲到我后面来！快！"
D.Strings[16558]="我以为他永远都闭不上嘴。但辛达苟萨让这个呱噪的家伙安静下来了。勇士们，向映像大厅前进！我能感觉到……目标已近。"
D.Strings[16559]="吉安娜，你怎么哭了？"
D.Strings[16560]="穆拉丁，守住甲板，组织士兵向城堡上层发动进攻。我会带另一支暴风城部队过去。"
D.Strings[16561]="没什么，陛下……我只是，为国王而自豪。"
D.Strings[16562]="这就去，陛下！"
D.Strings[16563]="我们没有时间可以浪费了，$c。为什么你在这停了下来？"
D.Strings[16564]="有什么我能效劳的，女妖之王？"
D.Strings[16565]="我们时间不多了，英雄。你需要些什么？"
D.Strings[16566]="有什么我能效劳的，我的女士？"
D.Strings[16567]="魔导师哈瑟尔说你会借我一件战袍。"
D.Strings[16568]="<他看了看火箭，咧开嘴紧张地笑了笑。>$b$b好吧，我是给别人做了些火箭。那又怎么样？价格不错，我也得到了酬劳。这不是出不出人命的问题。工作就要实事求是。这跟你有关系吗？"
D.Strings[16569]="听着，我不知道，可以吗？我不知道！$b$b我只是拿钱做了一些火箭，用来空运那些化学品，这就是我是任务。我的任务结束了，朋友。火箭都做好了，而且装备完成发射了出去。我拿了钱，正准备去消费消费，你就在这个时候满世界的追我。我这没有那种化学品了，我也不知道那究竟是什么东西。"
D.Strings[16570]="那些化学品是送到哪去的？"
D.Strings[16571]="你要我想起所有那些让我精神失常的事？听着。他们并没有付钱让我跟进这件事，我们之间的协议也不允许我透露这些。我可以把我的账本扔在地上，你自己捡起来然后别来烦我了。$b$b听明白了？"
D.Strings[16572]="你听说过我们的“慈善情人符”计划吗？$B$B官方的加冕活动，像我这样的福星会得到授权，分发可爱的情人符工具箱。$B$B你可以用得来的可爱的情人符为自己的朋友和心爱的人制作可爱的情人符手镯，或是把它们拿到可爱的商贩那里来兑换爱情信物！$B$B这期间的另一个流行做法是将自己制作的手镯送给自己喜爱的领袖，让他们感受到众人对他们的欣赏和爱戴…"
D.Strings[16573]="我想要一个可爱的情人符工具箱。"
D.Strings[16574]="我已经把我知道的都告诉你了，现在走吧！"
D.Strings[16575]="无论你要什么，布雷泽·盖茨！明白吗？$B$B而且我指的不光是那些“合法”的东西。我是说——无论——你要什么，朋友！任何东西……"
D.Strings[16576]="我对你喜欢的那些怪东西不感兴趣，布雷泽。只管拿给我“合法”的东西。"
D.Strings[16577]="你能取出那把剑吗？"
D.Strings[16578]="黑暗女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。"
D.Strings[16579]="真是……不敢相信！霜之哀伤居然……无人看管，那个侏儒说的没错。来吧，英雄们！"
D.Strings[16580]="我不敢碰它。后退！后退，我要试着和这把剑交谈！也许我们的救赎就在其中……"
D.Strings[16581]="乌瑟尔……乌瑟尔·光明使者。怎么……"
D.Strings[16582]="巫妖王就在这里？那今天就是我完成使命的日子！"
D.Strings[16583]="一定有办法……"
D.Strings[16584]="冰封王座……"
D.Strings[16585]="你别想轻易逃走，阿尔萨斯！我的仇一定要报！"
D.Strings[16586]="你太迟了，信使。不，我不想听你的借口；这个任务极为重要。"
D.Strings[16587]="这是我们的使者从龙眠神殿带回来的宝典。立刻将它带给麦雷昂·阳炎。"
D.Strings[16588]="信使，你要小心。我无须向你解释这本书的重要性，况且，银色盟约的人会不惜一切代价把它从我们手里夺走。"
D.Strings[16589]="小心，女孩。我听说这把被诅咒的剑救过我们。注意周围，看看霜之哀伤都创造了些什么。"
D.Strings[16590]="你没有时间了。巫妖王能看到剑旁的一切。他就要来了。"
D.Strings[16591]="在这里，你无法击败巫妖王。这种企图是愚蠢的。他会打倒那些跟随你的人，把他们变成强大的天灾战士。只有你除外，希尔瓦娜斯……他对你的“馈赠”要比上次更恐怖。"
D.Strings[16592]="也许吧，但要记住：一定要有一位巫妖王。即使你终结了阿尔萨斯，也要有另一个人来取代他。没有了巫妖王的控制，天灾军团就会像蝗灾一样横扫世界，所到之处，寸草不生。"
D.Strings[16593]="我不知道，女妖之王。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。"
D.Strings[16594]="唉，击败巫妖王的唯一方法就是在他的诞生地摧毁他。"
D.Strings[16595]="啊……他……他来了。你……你必须……"
D.Strings[16596]="这种刺骨的寒冷……血液好像都要凝结了。"
D.Strings[16597]="看前面！那是什么！难道是？英雄们，到我身边来！"
D.Strings[16598]="霜之哀伤：正是它摧毁了我们的王国。"
D.Strings[16599]="后退！如果碰到这把剑，你的灵魂就会受到永恒的创伤！我必须试着与封印在霜之哀伤中的灵魂交谈。远离我，请再后退一点。"
D.Strings[16600]="乌瑟尔！亲爱的乌瑟尔！我……很难过。"
D.Strings[16601]="阿尔萨斯在这里？也许我……"
D.Strings[16602]="但是，乌瑟尔，哪怕有一丝见到他的可能，我……我也要去。"
D.Strings[16603]="告诉我，乌瑟尔，我该怎样终结我的王子？我的……"
D.Strings[16604]="你是对的，乌瑟尔。原谅我。我……我不知道自己是怎么了。正在冰冠堡垒与天灾军团作战的国王和骑士们很快就会得到我们的报告。"
D.Strings[16605]="谁能扛起这样的重担？"
D.Strings[16606]="也许还有希望……"
D.Strings[16607]="你不能拒绝我，阿尔萨斯！我必须知道……必须明白……"
D.Strings[16608]="吉安娜！真的是你吗？"
D.Strings[16609]="吉安娜，你没有时间了。巫妖王能看到剑旁的一切。他就要来了。"
D.Strings[16610]="不，孩子。阿尔萨斯不在这里。阿尔萨斯只是巫妖王意识中的一个存在。一个即将泯灭的存在……"
D.Strings[16611]="吉安娜，听我说。你必须终结巫妖王。不要试图说服他。他会把你们全杀掉，变成天灾军团的战士。"
D.Strings[16612]="振作起来，女孩。你必须在巫妖王和耐奥祖融合的地方－－冰封王座，将他终结。这是唯一的办法。"
D.Strings[16613]="还有…还有一些事情你需要知道。天灾军团绝不能失去控制。即使你战胜了这个巫妖王，也要有别人来取代他。没有巫妖王的控制，天灾军团就会横扫整个世界，摧毁一切生灵。"
D.Strings[16614]="要有个崇高的灵魂作出牺牲……"
D.Strings[16615]="我不知道，吉安娜。我怀疑正是阿尔萨斯残留在巫妖王体内的一缕灵魂阻止了天灾军团彻底毁灭艾泽拉斯。"
D.Strings[16616]="不，吉安娜！啊……他……他来了。你……你必须……"
D.Strings[16617]="闭嘴，圣骑士！"
D.Strings[16618]="你真的想和死人交谈？我会满足你。"
D.Strings[16619]="法瑞克，玛维恩，杀掉他们，送到我的大殿来。"
D.Strings[16620]="你要找那个早就被我干掉的家伙吗？现在他只是一个幽魂，一个我脑中微弱的回音……"
D.Strings[16621]="你是个奇怪的小家伙。"
D.Strings[16622]="总算盼到你来了，信使。克拉苏斯将其余的上古龙铸之刃复制品中的一个交给了我们。"
D.Strings[16623]="给你书。你要确保赶在夺日者发现这一切之前将书送到卡莱迪斯·亮矛那里。"
D.Strings[16624]="快马加鞭！夺日者发现我们有他们要的信息时会抓紧一切时间对付我们。"
D.Strings[16625]="部落勇敢的战士，我向你致敬！如果没有你和你盟友的帮助，我们一定会死在联盟炮艇的火力下。$B$B请稍事休息，随后我们会展开针对敌人堡垒上游的袭击。"
D.Strings[16626]="我们准备好了，大王。巫妖王必须死！"
D.Strings[16627]="你能肯定吗，$n？要想战胜天灾军团，我们必须全力以赴。如果你休息得差不多了，我们就开始吧。"
D.Strings[16628]="Lok'tar ogar！我们准备好了！兽人兄弟们，冲啊！"
D.Strings[16629]="库卡隆，行动！勇士们，提高警惕。天灾军团已经……"
D.Strings[16630]="加入我，父亲。让我们一同以天灾之名来粉碎这个渺小的世界——巫妖王万岁！"
D.Strings[16631]="我曾听过我的孩子在那里发生的故事。现在，他已经成了巫妖王手下一名强大的死亡骑士。如果这是真的，我必须大义灭亲。$B$B我现在的责任就是指挥奥格瑞姆之锤号抵达冰冠堡垒之顶，并消灭所有阻拦我们的天灾军团。你和你的盟友准备好以后我们就出发。"
D.Strings[16632]="算上我所有的同伴，萨鲁法尔。出发吧！"
D.Strings[16633]="我的儿子战死在天谴之门。我来只是想带走他的尸体。"
D.Strings[16634]="顽固的老头。你以为你能赢？即使你最强壮的时候，也不如我现在的力量。"
D.Strings[16635]="我给他起名为德拉诺什，意思是“德拉诺之心”。我不会让那些术士带走他。我的孩子会安全地藏在加拉达尔长老那里。"
D.Strings[16636]="我在他的母亲弥留时许下诺言。我会孤身穿过黑暗之门。无论我是生是死，我的儿子都不会有事，都会纯净如初……"
D.Strings[16637]="今天，我兑现了诺言。"
D.Strings[16638]="可怜的老兽人！来吧，英雄们，来尝尝天灾军团的力量吧！"
D.Strings[16639]="面对霜之哀伤，奎尔德拉很快复苏了！"
D.Strings[16640]="%s开始咳嗽。"
D.Strings[16641]="%s对着自己儿子的尸体流下了眼泪。"
D.Strings[16642]="你会在纳格兰有一个隆重的葬礼，安睡在你的母亲与祖先身旁。"
D.Strings[16643]="年轻的英雄们……无论战斗多么可怕……也不要忘记荣耀。"
D.Strings[16644]="听从您的吩咐，主人……"
D.Strings[16645]="敌人即将大难临头，主人！"
D.Strings[16646]="来吧，斩亡者。我会让主人知道，我们谁才配得上“勇士”之名！"
D.Strings[16647]="怎么选这种低能的盟友，科罗克！"
D.Strings[16648]="结束了，主人。"
D.Strings[16649]="主人……我……失败了。"
D.Strings[16650]="别害怕，主人。看我怎么将敌人撕个粉碎！"
D.Strings[16651]="一点都不疼了，是不是？"
D.Strings[16652]="很抱歉……"
D.Strings[16653]="能感到那灼热吗？"
D.Strings[16654]="我……做了什么？不！"
D.Strings[16655]="这就是你距离炸弹太近的结果！"
D.Strings[16656]="多么……爆炸性的结局啊！"
D.Strings[16657]="什么？这种力量是……？所有的痛苦都消失了！你……？难道我们都投入了永恒的死亡怀抱？"
D.Strings[16658]="我已经救不活了。兄弟们，继续战斗……"
D.Strings[16659]="请……将我火化。让我在死后得到温暖……"
D.Strings[16660]="不！不！为什么我不能在火中死去？ 都烧成焦炭吧！"
D.Strings[16661]="我死的……很值得。"
D.Strings[16662]="巫妖王的意志不可逃避。准备好迎接一场爆炸吧！"
D.Strings[16663]="传送器闪出水晶般的光芒。"
D.Strings[16664]="传送到圣光之锤。"
D.Strings[16665]="现在，我们要赢得这场战争！$B$B越过这片满目疮痍的地区向东，联盟希望在他们的海岸要塞之间建立起陆上连接。他们想要在这里，在贫瘠之地的正中心建立一座堡垒。但这是我的贫瘠之地。$B$B我绝不会允许那座堡垒出现。"
D.Strings[16666]="这太可怕了，$c。我被蛮横地赶出奥格瑞玛。当我被拖出奥格瑞玛的大门时，我的实验材料全都被扔在地上，被彻底毁了。$B$B他们对待我就好象对待某种可怕的怪物！$B$B幸运的是，我在这里还能继续我的研究。这里从不会缺乏新鲜的实验材料。"
D.Strings[16667]="启动引擎！小伙子们，向命运之战前进！"
D.Strings[16668]="都给我抓紧了！"
D.Strings[16669]="那到底是什么？来人，给我望远镜！"
D.Strings[16670]="以我的胡子起誓！部落的速度真快啊！"
D.Strings[16671]="规避动作！炮火准备！"
D.Strings[16672]="卑鄙的家伙！竟敢偷袭我们！"
D.Strings[16673]="想挡住我？也不看看自己是谁？我现在就要去和阿尔萨斯算账了，谁也别想拦着我！注意！全火力射击！开火！开火！"
D.Strings[16674]="强大的天灾军团将让死亡和毁灭席卷整个世界！"
D.Strings[16675]="这不是你的战斗，矮人。回去，否则我们就只能摧毁你们。"
D.Strings[16676]="又一份给主人的献礼！"
D.Strings[16677]="到下面去挣扎吧！"
D.Strings[16678]="我的眼前……只有黑暗。"
D.Strings[16679]="来吧！部落忠诚勇敢的儿女们！今天是部落仇敌灭亡的日子！LOK'TAR OGAR！"
D.Strings[16680]="主人的怒火赐予我力量！"
D.Strings[16681]="库卡隆，出发！"
D.Strings[16682]="那是什么？有东西正从远方靠近！"
D.Strings[16683]="死亡是唯一的解脱！"
D.Strings[16684]="联盟的炮船！全体集合！"
D.Strings[16685]="白骨的束缚！"
D.Strings[16686]="定住吧！"
D.Strings[16687]="在你面前的是萨鲁法尔！"
D.Strings[16688]="你很快就会明白了。库卡隆，消灭他们！"
D.Strings[16689]="兽人！挪开你的破飞艇，否则我就把它轰烂！这里没部落什么事！"
D.Strings[16690]="火枪手，加速射击！"
D.Strings[16691]="火炮小队，装弹！"
D.Strings[16692]="将士们，给我进攻！"
D.Strings[16693]="我们的船体受伤了，赶快叫个法师来干掉那些大炮！"
D.Strings[16694]="什么？！别妄想能轻易就夺走我们铁炉堡的船！"
D.Strings[16695]="我早就警告过你，恶棍！兄弟姐妹们，前进！"
D.Strings[16696]="指挥官巴雷特，离开这里！我们受到重创，难以漂浮了！"
D.Strings[16697]="飞斧手，加速掷斧！"
D.Strings[16698]="火箭手，装弹！"
D.Strings[16699]="我们的船体受损了，赶快叫个战斗法师来轰掉那些大炮！"
D.Strings[16700]="你竟敢上我的船？你活不长了。"
D.Strings[16701]="联盟不行了。向巫妖王进攻！"
D.Strings[16702]="把火扑灭，控制损伤！让你们见识一下部落的坚强！"
D.Strings[16703]="<一只蟑螂从卡尔德的嘴里爬出来，又爬进了他的一只空眼窝。>"
D.Strings[16704]="<一看到你，卡尔德装上他的下巴，准备和你说话。>"
D.Strings[16705]="<你发现卡尔德正用一把匕首无聊地拨弄着他的耳朵。>"
D.Strings[16706]="知道我喜欢什么吗，$n？"
D.Strings[16707]="杀戮。"
D.Strings[16708]="传送到诅咒祷堂。"
D.Strings[16709]="传送到颅骨之墙。"
D.Strings[16710]="传送到死亡使者的高台。"
D.Strings[16711]="传送到尖塔上层。"
D.Strings[16712]="传送到辛达苟萨的巢穴。"
D.Strings[16713]="你们永远别想把我们赶出城去，银色盟约的混蛋！"
D.Strings[16714]="你们这些夺日者下人全都一个样。"
D.Strings[16715]="你来晚了，$n。来自达拉然的另一位访客已经来过这里，同样是为了了解有关远古龙剑的事情。"
D.Strings[16716]="根据你的描述我可以断定，我借给那位访客的书能使你很容易地对这把武器做出鉴定。"
D.Strings[16717]="恐怕，你得找——嗯，或许卡雷苟斯会帮忙。"
D.Strings[16718]="$n可能已经发现了古剑的碎片，卡雷苟斯。你会帮助我们的到访者吗？"
D.Strings[16719]="你确定你应该帮助那些凡人取得那把剑吗？"
D.Strings[16720]="这些武器，克拉苏斯…它们制造于很久以前，那时候的一切…都不同。"
D.Strings[16721]="你认为我们的盟友没有能力控制这些剑的力量？"
D.Strings[16722]="慢一些，朋友。你说将军就要来了？$B$B我的墙上又要增添一件战利品了！我会吸引那些近卫的注意，你的任务就是去干掉霍索恩将军。准备好了吗？"
D.Strings[16723]="凡间的勇士长久以来都在使用这些武器对抗着邪恶。我认为没有理由不让他们在这场战斗中使用这些剑。"
D.Strings[16724]="我们的敌人曾利用我们最强大的武器来对抗我们。是什么让你觉得这些古剑会有所不同？"
D.Strings[16725]="遵从您的意愿，我的女王。我不会阻拦他们，但我会对他们紧密监视。"
D.Strings[16726]="我们都会如此。"
D.Strings[16727]="陶拉祖的屠夫将会付出代价。"
D.Strings[16728]="在把他们赶回到大海之前，我不会休息，$n。"
D.Strings[16729]="明白！Grok'thar More'gar。Bok choy，朋友。呃。Zub zub！"
D.Strings[16730]="遵……遵命。呃。准备工作！"
D.Strings[16731]="只有取得游侠将军的许可才能进入太阳井高地。"
D.Strings[16732]="耶，兄弟。去敲烂几个蒂基面具假人吧！"
D.Strings[16733]="$n。祖尼。你们可以在东边的训练场找到你的训练师。不要给暗矛部族丢脸。"
D.Strings[16734]="我告诉过加杜尔，不要在异种生物的巢穴上建造城堡。$B$B他会听克劳格的话吗？不！"
D.Strings[16735]="玩吗？玩吗？"
D.Strings[16736]="哈哈，我做到了！"
D.Strings[16737]="死吧，死吧，死！"
D.Strings[16738]="我的妈呀！"
D.Strings[16739]="你……玩完了！"
D.Strings[16740]="我有点不舒服……*呕*"
D.Strings[16741]="不！你杀了大臭！你赔！"
D.Strings[16742]="我把它弄坏了……"
D.Strings[16743]="我会拿你做新玩具！"
D.Strings[16744]="真是糟糕……"
D.Strings[16745]="该睡觉了！"
D.Strings[16746]="黏啊，真黏啊！"
D.Strings[16747]="什么？我的心肝？不！！！"
D.Strings[16748]="喜讯，各位！我想我已经研制出一种能够毁灭艾泽拉斯的药剂了！"
D.Strings[16749]="嗯，有趣……"
D.Strings[16750]="噩耗，各位……我觉得我要失败了……"
D.Strings[16751]="这是普通的毒云，但请千万小心，这毒云其实并不普通！"
D.Strings[16752]="嗯，什么感觉也没有。什么？！这是哪儿来的？"
D.Strings[16753]="味道像……樱桃！哦！见笑了！"
D.Strings[16754]="两泥，一室。会有无限惊喜哦！"
D.Strings[16755]="惊天噩耗，我作的腐面，刚刚死了。但重大喜讯，他留下了，大量软泥！哇，我居然还有这么出众的诗歌才华……雷死了！"
D.Strings[16756]="哦烂肠，你是我的最爱，仅次于腐面。不过你的死给我留下了那么多毒气，我都快被熏死了！"
D.Strings[16757]="%s大声哭嚎起来！"
D.Strings[16758]="我获得了新生！伊瑟拉的恩泽赐予我消灭邪恶的力量！"
D.Strings[16759]="我的天才不可能被束缚在一个胶囊里！$B$B等等，这里不是艾萨拉？！这是什么地方？这是一座休眠火山！$B$B我本来有些想去找贸易大王的！但我也在考虑将肉鸡蛋实现武器化的可能！"
D.Strings[16760]="当我们被像行李一样打包运到胶囊镇里的时候，他们对我们说的是我们将受雇前往艾萨拉的某地工作。这是艾萨拉吗？$B$B我问你：是谁搞出了胶囊镇，却又不在里面准备好足够的食物？！某个肮脏的变鸡器？！$B$B我们都知道机动战鸡的微型化是怎么实现的。"
D.Strings[16761]="大领主莫格莱尼，我必须请你为我重新铸造影锋。"
D.Strings[16762]="靠我近点，朋友。我在上一次袭击中被一颗子弹射中了。$B$B<甘恩努力想挪动一下身体，却只是痛苦地呻吟了一声。他的左手按在一处伤口上。血不断地从他的指缝间涌出。>$B$B当矮人们最初入侵贫瘠之地的时候，我只是满足于骚扰他们的挖掘工，破坏他们的设备。我真应该趁有机会的时候对他们发动致命的打击。"
D.Strings[16763]="维兹尔·滑影，伪装大师！"
D.Strings[16764]="|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你获得了|cFF00FF00畸变感染|r效果！"
D.Strings[16765]="拜托你了，凡人，同达拉然的奥术师泰拜林谈一谈。他可能有办法和夺日者进行交涉，让你看一看那本书。"
D.Strings[16766]="拜托你了，凡人，在达拉然找到魔导师哈瑟尔。他可能有办法和银色盟约进行交涉，让你看一看那本书。"
D.Strings[16767]="英雄们，请快些帮助我，我……我快要抵挡不住他们了。请治疗我的伤口！"
D.Strings[16768]="我打开了进入梦境的传送门。英雄们，救赎就在其中……"
D.Strings[16769]="我的力量回来了。坚持，英雄们！"
D.Strings[16770]="我们不会让你轻易逃脱的！"
D.Strings[16771]="你认为你能活着逃走吗？"
D.Strings[16772]="这不算什么大挑战，朋友，但在接纳你之前，我们要确认你有能力对付这个地穴里的东西。"
D.Strings[16773]="巫妖王的爪牙，这里不欢迎你们！"
D.Strings[16774]="他们正在进行挑战，朋友。耐心一些。"
D.Strings[16775]="安静点，蠢货。如果我要杀你，你早已经死了。"
D.Strings[16776]="我一点也不喜欢这个皇冠药剂公司的样子。"
D.Strings[16777]="照顾好你的武器，它们就能照顾好你。"
D.Strings[16778]="男人，女人，还有孩子……没人能逃过主人的怒火。你的死早已注定。"
D.Strings[16779]="我不能帮助你，如果你想接受德鲁伊训练，就去和岑塔布拉谈谈。"
D.Strings[16780]="我不能帮助你，如果你想接受牧师训练，就去和图娜尼谈谈。"
D.Strings[16781]="我不能帮助你，如果你想接受法师训练，就去和索拉萨谈谈。"
D.Strings[16782]="无能的家伙！"
D.Strings[16783]="斯坦索姆的小孩子都要比你们勇猛！"
D.Strings[16784]="玛维恩，干掉他们……"
D.Strings[16785]="洛丹伦的战士们，服从主人的召唤！"
D.Strings[16786]="绝望……如此甘甜……"
D.Strings[16787]="恐惧……如此美好……"
D.Strings[16788]="你们只会寻得死亡！"
D.Strings[16789]="我看到的是同样的眼神。泰瑞纳斯怎么也想不到。"
D.Strings[16790]="痛苦的窒息吧！"
D.Strings[16791]="对，去吧……迎接你的命运吧……痛苦、冰冷的拥抱正等着你。"
D.Strings[16792]="如您所愿，我的主人。"
D.Strings[16793]="你的躯壳将在你的眼前朽化！"
D.Strings[16794]="灰飞烟灭吧！"
D.Strings[16795]="在混乱的战场上，光与影的平衡将引领我们取得胜利。"
D.Strings[16796]="侍从是骑士的左右手。要知道，手应该特别擅长于搬运东西，所以你的第一个任务就是负责搬运我的杂物、小东西和其它各种随身用具。这样我才能放心地在世界各处维护正义。毕竟搬运杂物可不是骑士应该做的事情。"
D.Strings[16797]="很好。第二，你必须知道，对于骑士来说，最重要的莫过于骑士精神。骑士永远要秉承慷慨仁慈的骑士情怀，就如同绝对不能放开手中的长枪。他的勇猛果敢必须比他身上的铠甲更加耀眼夺目。无论他的佩剑多么锋利刚硬，他对待朋友却必须和善谦恭。$b$b现在，告诉我，$n，你会立下誓言，坚守骑士的精神和勇气吗？"
D.Strings[16798]="哈！我没有说过吗，好$n，骑士精神和勇气是骑士必须坚持的原则？你要做的只是一名侍从。严格的骑士精神对于侍从来说是难以承受的重担。就像我曾经提到过的一样，你要扛起的担子只有我的随身物品。"
D.Strings[16799]="开始吧！骑士精神是骑士之道，我正是一名骑士。你必须明白，我天生就是一名勇者。这是真的，我为多罗莉亚女士而战，要将她的美丽与高贵在全世界传颂。任何对她的美好有所质疑的人都是我最大的敌人，一定会得到我正义的惩罚。$b$b当我说话的时候，我才意识到我的一个失误。我们已经正式开始了接纳侍从的仪式，但我还没有确认你是应该接受我的赞许，还是我的正义怒火。$b$b现在我必须知道，你是否认为多罗莉亚女士是艾泽拉斯无可置疑的最美丽的人？"
D.Strings[16800]="很高兴听到你这样说。祝贺你，$n，你已经完成了训练。现在你可以跟随我一同上战场了。"
D.Strings[16801]="聪明，你会发现，魔法比任何武器都要强大得多。"
D.Strings[16802]="要信任你的弓。当你需要它的时候，它绝不会辜负你。"
D.Strings[16803]="当一切都已失去，自然仍然会指引你。"
D.Strings[16804]="<麦斯米兰沉浸在祈祷中，忘却了你的存在。>"
D.Strings[16805]="收起你的剑，取下你的头盔。在我们用刀剑作战之前，我有好些话得先灌输到你的耳朵里去。$b$b准备好了吗？"
D.Strings[16806]="%s刺穿了$n！"
D.Strings[16807]="%s的以太护盾已经被$n击碎。"
D.Strings[16808]="干净整洁！"
D.Strings[16809]="应该这么干！"
D.Strings[16810]="干得好。我不想知道那点污迹究竟是什么。"
D.Strings[16811]="阿夸诺斯要忙不过来了！"
D.Strings[16812]="我应该留住你的。"
D.Strings[16813]="你们将在这里魂飞魄散！"
D.Strings[16814]="我变成了……死神！"
D.Strings[16815]="翻腾的仇恨将吞没你们！"
D.Strings[16816]="愚蠢的凡人。你以为能轻易打败我们？萨莱因是巫妖王永生的战士！现在他们将合力撕碎你！"
D.Strings[16817]="晚餐……开席。"
D.Strings[16818]="见识到黑暗堕落者的力量了吧？"
D.Strings[16819]="向萨莱因屈服吧！"
D.Strings[16820]="纳克萨纳尔的失败早已过去！有了这颗宝珠，瓦拉纳就能完成复仇！"
D.Strings[16821]="杯子已经被斟满了。"
D.Strings[16822]="你们也敢来冒犯？"
D.Strings[16823]="死亡才是真谛。"
D.Strings[16824]="我的女王，他们……来了。"
D.Strings[16825]="如此汹涌的力量！黑暗堕落宝珠让我所向无敌！"
D.Strings[16826]="血溅当场吧！"
D.Strings[16827]="蛆虫。"
D.Strings[16828]="乞求宽恕吧！"
D.Strings[16829]="在塔达拉姆面前颤抖吧，因为我拥有黑暗堕落宝珠的力量！"
D.Strings[16830]="享受痛苦吧！"
D.Strings[16831]="你竟敢和灵魂之主对视？我会把你一口吃掉！"
D.Strings[16832]="磨难！痛苦！和混乱！来吧，吃个痛快！"
D.Strings[16833]="看这深渊，那里有你的末日。"
D.Strings[16834]="时间就是金钱，我的朋友。快快快！"
D.Strings[16835]="可爱的商贩正等着呢。快点吧！"
D.Strings[16836]="箱子不会自己长腿走路，朋友。开始干活儿吧！"
D.Strings[16837]="你没什么东西要搬吗？"
D.Strings[16838]="我需要一套新的伪装。"
D.Strings[16839]="有东西在发出臭味，这次可不是我的袜子。"
D.Strings[16840]="希望破灭……"
D.Strings[16841]="末日降临！"
D.Strings[16842]="迎接你的凄惨结局吧。"
D.Strings[16843]="霜之哀伤饿了……"
D.Strings[16844]="霜之哀伤，服从我！"
D.Strings[16845]="霜之哀伤会饱餐你们盟友的灵魂！"
D.Strings[16846]="我会让你的血脉和躯壳化为寒冰！"
D.Strings[16847]="你周围的世界将在眼前崩塌！"
D.Strings[16848]="你做了一个……愚蠢的……决定。"
D.Strings[16849]="末日！"
D.Strings[16850]="瓦格里，主人在召唤你！"
D.Strings[16851]="就咬一小口……"
D.Strings[16852]="这是天灾军团的神圣土地。圣光在这里毫无用处，圣骑士。你将孤立无援……"
D.Strings[16853]="弗丁，你本应是我最强大的战士，你的黑暗力量将清洗这个世界，开启一个新的世代。"
D.Strings[16854]="但这个荣耀不属于你了。很快，我将有一名新的勇士。"
D.Strings[16855]="我饿了！"
D.Strings[16856]="你们最终都要臣服于我。"
D.Strings[16857]="你受得了吗？"
D.Strings[16858]="就要来了……"
D.Strings[16859]="多么的……不幸啊。"
D.Strings[16860]="对！吃吧，宝贝！你是我的了！"
D.Strings[16861]="真的……？你就这点能耐？"
D.Strings[16862]="真是可怜。"
D.Strings[16863]="一切都结束了！"
D.Strings[16864]="真是的……我们相处得……那么……好……"
D.Strings[16865]="怎么，自诩正义的圣光终于来了？我是不是该丢下霜之哀伤，恳求您的宽恕呢，弗丁？"
D.Strings[16866]="让我来亲自告诉你。当一切结束，你将跪求我的宽恕－－而我会拒绝你。你痛苦的哀号将是我狂野力量的最好证明……"
D.Strings[16867]="我会让你活着目睹这个末日，弗丁。这悲惨的世界将在我手中重铸，我不想让圣光最强大的勇士错过这一切。"
D.Strings[16868]="来吧，勇士们。释放你们的怒火吧！"
D.Strings[16869]="我不再有问题，也不再有疑问。你是艾泽拉斯最强大的勇士。我的阻挠都被你一一化解。我最悍勇的仆从也都倒在了你的无情怒火和利刃之下……"
D.Strings[16870]="真的是正义在驱使你吗？我很好奇……"
D.Strings[16871]="你把他们训练的很好，弗丁。你把世界上最强大的勇士都送到了我的面前，这正合我意！你们的默默牺牲会得到我的褒奖。"
D.Strings[16872]="亲眼目睹吧，我会把他们从尸骸变为天灾军团的战士。艾泽拉斯会在他们的手中陷入混乱，走向毁灭！而你，将是第一具尸体。"
D.Strings[16873]="我会享受这种讽刺。"
D.Strings[16874]="站起来，兄弟们，消灭这些敌人！"
D.Strings[16875]="这不可能..."
D.Strings[16876]="真是一把神奇的剑，你觉得呢？这绝不会是出自矮人之手，不，还要古老的多。$B$B这些夺日者和银色盟约的使者似乎打算对这一秘密一探究竟。我已经开始准备给布莱恩的报告了。"
D.Strings[16877]="作为德鲁伊，我们的任务就是维护自然的平衡。但我的努力却与此背道而驰。我的愚蠢造成极为巨大的混乱。必须在这种异常的作物进一步扩散之前将它收割。"
D.Strings[16878]="我会留在这里，照看这片正在痊愈的大地。请一定注意来自于这里的游荡者……"
D.Strings[16879]="我们会让你死个痛快，阿尔萨斯。对于犯下累累罪行的你，这是最大的仁慈了。"
D.Strings[16880]="好吧，勇士们，进攻！"
D.Strings[16881]="无上的圣光啊！请祝福我！赐予我力量……帮助我冲破这些枷锁！"
D.Strings[16882]="结束了，阿尔萨斯！你残害生灵的日子今天结束了！"
D.Strings[16883]="你是来审判阿尔萨斯的吗？想要看到巫妖王的灭亡？"
D.Strings[16884]="首先，你需要摆脱霜之哀伤的控制，否则就会像我一样，永世成为这把邪剑的囚徒。"
D.Strings[16885]="帮我摧毁这些痛苦的灵魂！我们合力就能弱化霜之哀伤的控制，从内部削弱巫妖王！"
D.Strings[16886]="终于自由了！结束了，我的儿子。清算的时候到了。"
D.Strings[16887]="圣光的勇士们！集结起来！"
D.Strings[16888]="重大喜讯！各位！软泥又开始流动啦！"
D.Strings[16889]="%s的法力壁垒闪着微光并在逐渐消退！"
D.Strings[16890]="是谁在打扰我？你们竟敢擅闯这神圣的地方？这里将会是你们的埋骨之地！"
D.Strings[16891]="你还不明白自己的徒劳吗？"
D.Strings[16892]="拥抱黑暗吧……永恒的黑暗。"
D.Strings[16893]="这全是主人的计划……你的结局是必然的……"
D.Strings[16894]="够了！看来需要我亲自上阵了！"
D.Strings[16895]="软弱的你抵挡不了我强大的意志！"
D.Strings[16896]="陪你们玩的够久了！"
D.Strings[16897]="我等待这一天的到来已经太久了，英雄。你和你的同袍们是否已经准备好对巫妖王进行正义的审判？我们将在你的命令下向敌人发起冲锋！"
D.Strings[16898]="来接受这祝福，让入侵者尝尝主人伟大的力量吧！"
D.Strings[16899]="我们准备好了，大领主。让我们为艾泽拉斯的命运而战！为冲破黑暗的光明而战！"
D.Strings[16900]="忠诚的追随者，从血肉的诅咒中解脱吧！"
D.Strings[16901]="来吧，为纯粹的形态欢喜吧！"
D.Strings[16902]="好好看看你粗陋的手：看看那肌腱、软肉和其中的黑暗之血。"
D.Strings[16903]="多么的软弱和不堪……这真是造物主的玩笑。"
D.Strings[16904]="你只有承认自己必然的失败，才有可能早日获得更强的力量，重获新生。"
D.Strings[16905]="我的主人是无所不能的，他有无比强大的力量，不可抗拒的意志。"
D.Strings[16906]="反抗者必将被毁灭。而那些全身心的，坚定不移的，有虔诚的思想与灵魂的效忠者们，必将得到超乎你们想象范畴的强大的力量。"
D.Strings[16907]="你们之所以在这里，那是因为你们是少数几个拥有特殊能力，能够洞悉这诅咒世界的人。"
D.Strings[16908]="你们能够看穿遮蔽世界的迷雾，掌握真正的力量。"
D.Strings[16909]="父亲……"
D.Strings[16910]="父亲。你的圣洁……让我，感到战栗。"
D.Strings[16911]="父亲……为了你，我万死不辞。"
D.Strings[16912]="达里安，我的孩子。"
D.Strings[16913]="终于，我能够重新见到你了。"
D.Strings[16914]="巫妖王一直在折磨我，达里安。"
D.Strings[16915]="无休无止，他想要击溃我的意志，让我屈服，成为剑中的冤魂……"
D.Strings[16916]="最后，战争让他无暇分身，他才放弃了我。"
D.Strings[16917]="有个回忆，是我的力量，达里安……是让我不被奴役的力量……"
D.Strings[16918]="那就是你的牺牲，我的儿子，再度拯救我于万劫不复。"
D.Strings[16919]="阿尔萨斯……"
D.Strings[16920]="艾泽拉斯的英雄们，你们对我的恩泽远超想象。"
D.Strings[16921]="长久以来，我苦苦地想要宽恕王子的滔天罪行。"
D.Strings[16922]="焦虑和痛苦撕扯着我的灵魂，邪恶的念头……让我远离圣光。"
D.Strings[16923]="我清晰地记得他眼中的光芒，那光芒带着荣耀，带着击败圣光之敌的热切……"
D.Strings[16924]="带着宁死也要保护人民的决心……"
D.Strings[16925]="这就是阿尔萨斯，我要永记于心的阿尔萨斯。"
D.Strings[16926]="朋友，你们的恩情没齿难忘。"
D.Strings[16927]="谢谢。"
D.Strings[16928]="哦，伙计……"
D.Strings[16929]="我忘不了在洛丹伦的那些日子……"
D.Strings[16930]="……用这把钝剑训练你的剑术……"
D.Strings[16931]="……让你成才，期待着你去完成伟大的使命。"
D.Strings[16932]="呵呵……那些功夫没有白费，不是吗，伙计？"
D.Strings[16933]="如果那天我能阻止你，也许一切都会不一样。"
D.Strings[16934]="要是我从没发现过那把被诅咒的剑……"
D.Strings[16935]="再见了，阿尔萨斯……好兄弟。"
D.Strings[16936]="一切都结束了。"
D.Strings[16937]="我不敢相信这是真的——因为巫妖王已经愚弄我太多太多次了。"
D.Strings[16938]="他对我们犯下累累罪行，现在他终于付出了代价。"
D.Strings[16939]="来吧，侍从$n，冒险正等待着我们！"
D.Strings[16940]="愿艾泽拉斯不要忘记那曾因软弱和傲慢所付出的沉重代价。"
D.Strings[16941]="但现在呢，英雄？那些摆脱了他的束缚，却无法摆脱凡尘俗世的人呢？"
D.Strings[16942]="退下。"
D.Strings[16943]="我的思绪很乱。"
D.Strings[16944]="巴尔莫丹……那些矮人……"
D.Strings[16945]="这道伤痕被封印了！感谢塞纳留斯……"
D.Strings[16946]="这……他还留着？一直以来，他还带着它？"
D.Strings[16947]="我知道！"
D.Strings[16948]="我还能感觉到他！饱受摧残……苦苦挣扎……啊，阿尔萨斯！"
D.Strings[16949]="也许……也许有一天，他会想起真正的自己。"
D.Strings[16950]="圣光啊，愿他摆脱那把魔剑的寒冷束缚，魂归故里。"
D.Strings[16951]="又是你……真希望你不曾如此尽心竭力地想要安抚我的灵魂。我早就明白，没有了她，就不会有和平，再也不会有了。$B$B我要将他们的家全部夷为平地。你准备好消灭这些可憎的杀人犯了么？"
D.Strings[16952]="救救我！我的东西都掉在这个热泉里了。$b$b我的长袍就在那里！"
D.Strings[16953]="我曾经是一名圣骑士，$n。由于我罪孽深重，现在圣光已离我远去。$B$B我会尽我所能帮助我的盟友，我绝不会再触碰黑暗的力量。"
D.Strings[16954]="朋友，这是自己造成的创伤。我实在无法面对这样一个在巫妖王的蹂躏下充满恐慌的世界。$B$B这是我救赎之旅的第一站，如果我的罪孽无法得到原谅，我会设法用我的余生加以偿还。"
D.Strings[16955]="欧姆斯，你的眼睛怎么了？"
D.Strings[16956]="从这里，你能看到大灾变所造成的全部破坏。看到我们的世界竟然如此脆弱，这真是令人胆寒。"
D.Strings[16957]="$c，东方吹来了一阵污秽的风。"
D.Strings[16958]="对于治疗这种蔓生，我有一点主意，$c。$B$B不幸的是，纳拉雷克斯已经完全陷入了混乱，拒绝进行任何尝试。"
D.Strings[16959]="这会让你明白别管闲事的道理！"
D.Strings[16960]="你在盯着看什么？没见过天才吗？"
D.Strings[16961]="没错，我会把那些“烟火”列一张表出来。"
D.Strings[16962]="从南海回来后那些东西就能卖大价钱了。"
D.Strings[16963]="你…别以为我看不到你。离我远点！"
D.Strings[16964]="伙计，感谢你提供这么棒的理发、修面服务。"
D.Strings[16965]="因为我就要离开了，所以准备了这么一点额外的东西。"
D.Strings[16966]="我又想了想，整个袋子都拿走吧。我必须，嗯，走了。"
D.Strings[16967]="你真以为我这么容易就会被你困住？"
D.Strings[16968]="绝不能让悲痛的心情削弱我们的力量。我们将并肩作战，以强大的力量击退入侵者。"
D.Strings[16969]="终于盼到我要的援助了！我准备了滑栓需要的各项文书。现在只剩下找人执行了。"
D.Strings[16970]="你知道的，那个闻起来十分的…嘿！别拿那个喷我！"
D.Strings[16971]="我的责任是测试我们年轻的学徒对于狩猎技艺的掌握程度。$B$B这就是我今天要做的。而那些野猪人就是我们的猎物。"
D.Strings[16972]="很高兴你能和我们在一起，$n。对付纳迦可不是一件容易的事！"
D.Strings[16973]="你好，$c！荣耀岗哨就在前面。那是联盟在石爪山脉和海岸之间的唯一通道。$B$B根据我的亲身经验，那也是一条充满危险的道路。"
D.Strings[16974]="我来到这里是为了看看能否和那些纳迦建立贸易往来。但他们的回答并不尽如人意。"
D.Strings[16975]="你好，$c。我们萨满祭司聚集在火石岗哨，照看这片土地，治疗它受到的伤害。"
D.Strings[16976]="她回来了。暗矛部族的仇恨终于要在今天有个了结。$B$B准备好以后就告诉我们，$n。我们绝不会再让她逃走。"
D.Strings[16977]="瓦里玛萨斯？不，他已经有一阵子没来报到了。他无疑是外出完成他的女王交给他的任务去了。"
D.Strings[16978]="瓦里玛萨斯，嗯…不在的时候，我被派来协助布拉贡大人完成任务。"
D.Strings[16979]="由于幽暗城的大部分兵力都已部署在了诺森德的复仇港，酋长派我们来支援幽暗城的防守。"
D.Strings[16980]="这片土地属于尖啸！牛头人必将毁灭！"
D.Strings[16981]="对赚钱有兴趣吗？"
D.Strings[16982]="我们来到安戈洛只为了一件事：利润。我的同伴我和一直在寻找生意上的合作对象。你有兴趣吗？"
D.Strings[16983]="你好， $n。很高兴见到你在这里。这里简直是一团乱了。"
D.Strings[16984]="你知道吗？贫瘠之地曾经是一片青葱茂密的森林。几千年以前，那时第一次大崩裂还没有发生。卡多雷照料着这片繁荣富饶之地。但随着大陆分崩离析，这一片被撕裂的陆地成为了现在被我们称为卡利姆多的地方，昔日的绿地成为了一片被阳光炙烤的荒芜平原。$B$B当我第一次听说这场恐怖的悲剧时，我就决定要找到办法，让森林重新生长在这片土地上。"
D.Strings[16985]="在研究这片土地的时候，我发现有一座洞穴一直延伸到地下很深的地方。在这片炎热的荒原下面，地下暗河形成的水网覆盖了很大一片地方。我称这座因暗河冲刷而形成的洞穴为哀嚎洞穴。因为风和水流在这座洞中总是会发出一阵阵凄厉的嚎叫。$B$B我相信，这座洞穴是让大地回复生机的契机。暗河中的水已经在贫瘠之地的一些角落里渗透到地面，形成了一些葱翠茂盛的绿洲……如果这种渗水作用得到加强，那么这片土地就会被绿色所覆盖。"
D.Strings[16986]="我的计划是将这些地下水与翡翠梦境直接连通。我带领我忠实的信徒们，进入到哀嚎洞穴深处，在冥想中进入翡翠梦境。通过我的躯体，这个世界和翡翠梦境连接在一起。$B$B然而就在那时，发生了可怕的灾祸。"
D.Strings[16987]="我在翡翠梦境中遭遇了可怖的腐蚀力量，言语难尽其详。无尽的噩梦抓住了我，折磨我的心智。我无法摆脱它的囚禁。我的信徒们无法唤醒我。$B$B无论这种腐蚀来自于何处，它已经通过我的躯体来到了我们的世界。它的能量藉由我进入哀嚎洞穴。那种恐怖的力量扭曲了这里的野生动物，让它们变成了怪物。就连我的信徒们也受到了影响。他们的意识变得疯狂野蛮。他们的身体变得如同巨大的毒蛇。现在他们称自己为毒牙德鲁伊。"
D.Strings[16988]="我被我的最后一名信徒穆约和一队冒险者救了出来。我以为我的计划已经彻底失败了。当大灾变到来时，我才意识到，我的计划可以说是过度地成功了！$B$B当贫瘠之地裂开时，巨大的地下水流涌上地表，其中充满了那股在哀嚎洞穴中肆虐的诡异能量。各种生命随之迅速繁衍壮大，无论植物还是动物……都在不受控制地过度生长。$B$B我以为自己能控制自然本身的形态和变化。而现在，我必须为自己的傲慢做出补救。这种生命的蔓生必须被阻止，否则它就会吞没整个自然生态。"
D.Strings[16989]="这是个好问题。$b$b温泉的周围，西边悬崖上的烽火，以及北面通往希利苏斯的小路。$b$b这些都是我要去查看的地方。"
D.Strings[16990]="胡说。难道我雇佣了一个瞎眼的侍从？这里到处都是龙。$b$b我的邻居斯巴克说它们是“恐龙”。但我知道龙是什么样子。所以它们必须被消灭。"
D.Strings[16991]="主人的意志不容侵犯…"
D.Strings[16992]="你无法逃脱主人的怒火……"
D.Strings[16993]="没人能阻挡巫妖王的步伐…"
D.Strings[16994]="屈服吧…投入死亡冰冷的怀抱…"
D.Strings[16995]="让你自己摆脱生命的轮回…"
D.Strings[16996]="死亡将你吞噬…"
D.Strings[16997]="你的每个举动都在他的监视之下…"
D.Strings[16998]="在痛苦中哭泣吧…让你的痛消磨你的力量…"
D.Strings[16999]="%s开始施放软泥喷射！"
D.Strings[17000]="别试探我！你根本不知道那些东西里究竟有什么吧？"
D.Strings[17001]="我的女王，我想我听到了阿尔萨斯的临近。不管您有什么样的计划，请快些执行。"
D.Strings[17002]="我们的密探在搜集可用的天灾军团枯萎样本时经历了很多次失败，现在我亲自到前线来视察工作进度。就像他们说的，如果你希望工作能够干好…"
D.Strings[17003]="简直难以置信！你身上覆盖了奇异的活性剧毒枯萎！拜托，请允许我采集这些纯净的标本。我还会帮你的队友清楚残留的感染，并以医学的名义对你们的勇敢和自我牺牲精神加以回报！准备好了以后请告诉我。"
D.Strings[17004]="你在这里什么都得不到。走吧。"
D.Strings[17005]="你现在明白了，$n？"
D.Strings[17006]="我的主人需要你。"
D.Strings[17007]="你是谁？你想从我们的部族得到什么？"
D.Strings[17008]="娜博亚，是你吗？"
D.Strings[17009]="外乡人，欢迎来到我们的家园。"
D.Strings[17010]="你是来进行观察的吗？想要一个椰子吗？"
D.Strings[17011]="我们部落中的一些人能够驾驭雷电的力量。我们就是用这种力量来抵抗入侵者，不管是人类、兽人还是恐龙。$b$b要知道，我们的雷电能够震晕任何恐龙。"
D.Strings[17012]="个体的力量很重要，但全族的力量更加重要。只有当我们部族中最弱小的个体也强大起来，我们的部族才会真正变得强大。"
D.Strings[17013]="南边的鳄鱼人喜欢吃小动物，比如青蛙和鹦鹉。我们猩猩则喜欢吃鳄鱼人。恐龙喜欢吃猩猩。所有这些都是严肃的自然规律。$b$b人类和兽人也会猎杀猩猩。但他们只剥去我们的毛皮，我们的尸体则被随意丢弃，任由它们腐烂。所以我们才会攻击人类和兽人。"
D.Strings[17014]="安戈洛环形山中的这种花是非常特别的。你说对不对，$n？"
D.Strings[17015]="只要你留在这里，奎尔德拉就会汲取这里的邪能。"
D.Strings[17016]="就像过去一样，对不对， $n？"
D.Strings[17017]="有人愿意帮忙吗？还是你需要更多训练，$n？$B$B不知你是否注意到，我现在很忙。"
D.Strings[17018]="这个地方看上去很不错。只是需要进行一下清洁。$B$B你在找工作吗，$n？"
D.Strings[17019]="这些俾格米人减少了我的利润！"
D.Strings[17020]="你已经掌握了诀窍，$n。尽量使用它们！"
D.Strings[17021]="全能战士NX-01型毁坏！"
D.Strings[17022]="嗨，你听过那个关于$r$c的故事么？事情是这样的：$b$b一个$r$c走进一座洞穴，开始和猩猩战斗。那群猩猩的头领说：“嘿，你为什么要这么干？！”那个$r$c就说：“是一个地精让我这么干的。”$b$b猩猩头领说：“地精让你干什么，你就干什么？”$r$c回答：“是的，因为我很笨，浑身臭气，而且还用两条腿走路。”$b$b很有趣，对不对？嗯……也许还需要再做些加工……"
D.Strings[17023]="以巫妖王的力量为名！"
D.Strings[17024]="吃吧，奴仆们！"
D.Strings[17025]="安戈洛环形山的存在有其特殊的意图，$n。现在该是你知道这个意图的时候了。"
D.Strings[17026]="我是娜博亚，卡兹格罗斯的弟子，安戈洛环形山的使者。我也被称为观察者。$b$b自从我的导师离开艾泽拉斯之后，我就是他的代表。他就是在这里塑造了许多生物。"
D.Strings[17027]="我在观察。看护安戈洛就是我的职责。这里就是我观察的位置。$b$b我还会进行测试，并记录测试结果。这些测试让我能够观察最令我感兴趣的事物。"
D.Strings[17028]="简单的刺激——响应测试。一般来说，我们不会干扰艾泽拉斯的运转。但在安戈洛，我们可以自由地使用更加直接的手段，因为安戈洛是泰坦的试验场。$b$b比如说，卡兹格罗斯想要知道，当他创造的一种生物被暴露在硫磺热泉中的时候，会有怎样的变化。他可以等待千万年，观察，等待这种生物在偶然间跌落入热泉——或是他亲手将这种生物放进热泉中。$b$b在安戈洛，我们就能这么做。"
D.Strings[17029]="不尽然。事实上，这座环形山中的许多生物在我的导师到来之前就已经存在了……$b$b无论是否由我的导师亲手创造，我都对它们进行绝对客观的观察。"
D.Strings[17030]="当大灾变肆虐艾泽拉斯的时候，也打破了保证这一地区处于隐藏状态的屏蔽系统。如此一来，具有智慧的种族发现我就只是时间问题了。$b$b老实说，我们此前并未预见过这种情况。所以现在，我们需要进行一些新的测试。而你，$n，就是我的测试对象。"
D.Strings[17031]="我没有权限回答这个问题。但我可以向你提供一个建议：$b$b找到布莱恩·铜须。$b$b他已经掌握了许多关于我们的线索。而且现在他即将有一个新的发现。帮助他，他也许就能帮助你找到你所需要的知识。"
D.Strings[17032]="夺回吉尔尼斯城的时刻已经到了。"
D.Strings[17033]="终于，来了个看客！"
D.Strings[17034]="吞噬者在等待着…"
D.Strings[17035]="死亡的漩涡在召唤你！"
D.Strings[17036]="我会剥下你低贱的灵魂！"
D.Strings[17037]="去注满引擎吧。"
D.Strings[17038]="又是一个属于我们的灵魂！"
D.Strings[17039]="凡人们，你们将我从那比死亡更可怕的厄运中拯救了出来。如果继续困在那些设备中，我的意志迟早会被巫妖王的巫师们摧毁，我的身体也将遭受永恒的折磨。在你们面前的便是荣耀一时的辛达苟萨——玛里苟斯的配偶。$B$B奈萨里奥的背叛使她受到了致命的创伤，躺在冰冠冰川的积雪中孤独的等待死亡，现在的她完全被仇恨所充斥。然而，恶意之下仍存留着龙之女王的高尚灵魂。我相信辛达苟萨的灵魂还有机会回归安宁。"
D.Strings[17040]="%s施放了|cFFFF7F00窒息毒气弹！|r"
D.Strings[17041]="|TInterface\\Icons\\inv_misc_herb_evergreenmoss.blp:16|t%s施放了|cFF00FF00可延展黏液！|r"
D.Strings[17042]="%s开始施放不稳定的实验！"
D.Strings[17043]="这就是你们的开始与终结之地，凡人们。休想进入主人的密室！"
D.Strings[17044]="你好，$r。我察觉到你对我出现在这里感到困惑。其他人也心存怀疑，不过鉴于我的同胞给他们带来的遭遇，我并不怪他们。$B$B太阳之井事件后发生了很多事，几乎没有一样是好事。我着手开始收拾残局，希望能挽救我此行带来的影响。要说的很多，要做的更多，不过记住这一点：不是蓝龙军团的每个成员都责怪艾泽拉斯的凡人给这个世界带来的祸患。$B$B我们中的某些成员对此有着更深的理解。"
D.Strings[17045]="他真的离去了，是吗？$b$b我……我能感觉到。"
D.Strings[17046]="真的没有办法拯救他吗？$b$b我恐怕永远也无法对此释怀。"
D.Strings[17047]="我…我在哪…？这真是场可怕的恶梦…不过没时间细想了，还有很多事情在等着我汇报！"
D.Strings[17048]="你嗜血成性！"
D.Strings[17049]="死吧，入侵者！没人能干预教派的计划！"
D.Strings[17050]="我醒了!"
D.Strings[17051]="那里是谁？"
D.Strings[17052]="你好，联盟的成员！$B$B作为加基森的官方代表，我的任务是确保我们离散的可怜侏儒们能够与与热砂港地精在加基森和平相处！为此，我们甚至可以容忍他们新的部落地精朋友。$B$B相信有你的帮助，我们能够达成令人愉快的共识！"
D.Strings[17053]="$n，你一定能拯救我们的族人！"
D.Strings[17054]="我会摧毁这道屏障，但你必须挡住那些亡灵！"
D.Strings[17055]="又是一道冰墙！不要让那些亡灵打断我的法术，这样我才能摧毁冰墙。"
D.Strings[17056]="我们就要到了……不要放弃！"
D.Strings[17057]="你的屏障挡不住我们，怪物！我会将它们全部粉碎！"
D.Strings[17058]="没有墙壁能阻挡女妖之王。挡住那些亡灵，英雄们。我会粉碎这道屏障！"
D.Strings[17059]="又是一道！坚持住，勇士们。我会粉碎这面冰墙。"
D.Strings[17060]="我厌倦了你的把戏，阿尔萨斯！你的冰墙阻挡不了我！"
D.Strings[17061]="你们这些恶魔拦不住我们！挡住那些亡灵，我在努力摧毁冰墙！"
D.Strings[17062]="这是个意外！"
D.Strings[17063]="重大喜讯！各位"
D.Strings[17064]="灵魂的汹涌不会被削弱！一切都只是徒劳。"
D.Strings[17065]="彻底毁灭吧！"
D.Strings[17066]="啊！强烈的灼痛！这是什么魔法？"
D.Strings[17067]="前面有个出口，赶快！"
D.Strings[17068]="我到这里来可不是为了渡假，朋友。诺格弗格派我来这里完成一个任务：确认该如何从这些异种怪物身上获取利润。如果不行，就将它们消灭干净。$B$B如果像你这样的$r想要为热砂集团做些事情，那么我倒是可以给你个机会。"
D.Strings[17069]="我甚至不知道该如何使用这件武器……但我相信，如果我摆出一副凶恶的样子，那些狼人也许就会逃到别的地方去。"
D.Strings[17070]="凯雷塞斯王子获得了鲜血唤醒的效果！"
D.Strings[17071]="瓦拉纳王子获得了鲜血唤醒的效果！"
D.Strings[17072]="塔达拉姆王子获得了鲜血唤醒的效果！"
D.Strings[17073]="还有其它套牌吗？"
D.Strings[17074]="你的提问相当机敏，年轻的$c。铭文师能够制作蕴藏强大力量的塔罗牌，当然即使是铭文师自己也无法完全驾驭他们所创造出来的东西。决定一切的还是命运。$b$b如果你有办法集齐完整的套牌，请把它带给我，你会得到不错的回报。"
D.Strings[17075]="专注于比赛，$n！"
D.Strings[17076]="你好，小子。你干得很不错！$B$B我会在另一边等你。"
D.Strings[17077]="这些关于食物的话题让我更饿了！"
D.Strings[17078]="$n！你还好吗？"
D.Strings[17079]="蜂拥的阴影在$n的四周积聚！"
D.Strings[17080]="强能烈焰飞快地冲向$n！"
D.Strings[17081]="%s的血兽获得了血之气息！"
D.Strings[17082]="现在不是自相残杀的时候，$n。"
D.Strings[17083]="兰德鲁的宠物笼"
D.Strings[17084]="霜翼大厅前的最后一道屏障已经被我们击破了，$g小伙子:姑娘;。只有辛达苟萨还挡在正义之师和巫妖王之间！还等什么？！"
D.Strings[17085]="所有的屏障都被击破了，$n！只有辛达苟萨还挡在我们和巫妖王之间。审判即将开始…"
D.Strings[17086]="你没有资格觐见巫妖王！"
D.Strings[17087]="你能抵挡多久？"
D.Strings[17088]="苏醒吧，奴仆们。拦住他们。"
D.Strings[17089]="奴仆们，抓住他们！带他们的尸体来见我！"
D.Strings[17090]="%s向$n掷出一颗冰冻宝珠！"
D.Strings[17091]="我们在这里的情况相当糟糕，$n。"
D.Strings[17092]="我确定合同里没提过会遇到这种情况！俾格米人，僵尸……这次霍巴特一定要把我晋升到一个足够高的职位才行！"
D.Strings[17093]="我本来以为情况不可能更糟了……"
D.Strings[17094]="我们待在这里干什么？难道我们不应该想办法离开这座岛吗？！！！"
D.Strings[17095]="胶囊镇实在是工程学上的一项伟大成就！"
D.Strings[17096]="$n感染了死亡疫病！"
D.Strings[17097]="入侵者闯入了内室。加紧毁掉那条绿龙！留下龙筋龙骨用来复生！"
D.Strings[17098]="不可能……霜牙……警报……"
D.Strings[17099]="低劣的顽抗，死亡是对你的优待。"
D.Strings[17100]="也许你早应该留在……群山里！"
D.Strings[17101]="力量……无上的力量！"
D.Strings[17102]="我不会让巫妖王失望的。准备受死吧！"
D.Strings[17103]="很高兴你这样问，$n！$B$B还从来没有人来问过这东西是怎么运作的。他们要不来了就说：“把它给我，我要炸东西了。”要不就是：“别拿那些细节的事情来烦我，我只需要瞄准和射击。”还有更糟的：“谁在乎它是怎么运作的，这次爆炸不是比上一次更壮观吗？”$B$B我发誓，有时候我真的很想尖叫。霍巴特总是把他的工作全都扔给我，我辛辛苦苦地做完了，却根本得不到承认！我一定是最不被承认，最过劳，所得报酬最不合理的工匠助手！$B$B等等，你刚才在问什么？"
D.Strings[17104]="是的，是的，这非常有趣。但你要知道，我们正在为生存而战。和藏在那座洞里的东西相比，这些俾格米人根本算不上什么问题！$B$B我那个没用的助手在哪里？我现在可是非常需要她呢！也许她又去偷懒了。我猜她肯定还在抱怨没有人关心她，没有人看重她……"
D.Strings[17105]="任何地方，除了这里…"
D.Strings[17106]="不应该让这些食人魔坐在沙子里，浪费生命。他们能够加入部落，为我们工作。$B$B我倒是要看看！如果我们不能利用他们，还有谁能？"
D.Strings[17107]="想要什么？"
D.Strings[17108]="食人魔看起来很有趣。"
D.Strings[17109]="我不喜欢沙子。"
D.Strings[17110]="医生！"
D.Strings[17111]="给我看看天灾领主的护甲，欧姆斯。"
D.Strings[17112]="我帮助地精女士和食人魔交朋友。"
D.Strings[17113]="你好，英雄。我制造和出售德鲁伊需要的树纹套装。"
D.Strings[17114]="你好，英雄。我制造和出售萨满祭司需要的霜巫套装。"
D.Strings[17115]="你好，英雄。我制造和出售潜行者需要的影刃套装。"
D.Strings[17116]="你好，英雄。我制造和出售猎人需要的安卡哈猎血套装。"
D.Strings[17117]="你好，英雄。我制造和出售战士需要的伊米亚之王套装。"
D.Strings[17118]="你好，英雄。我制造和出售圣骑士需要的光誓套装。"
D.Strings[17119]="你好，英雄。我制造和出售牧师需要的血色侍僧套装。"
D.Strings[17120]="你好，英雄。我制造和出售法师需要的血法套装。"
D.Strings[17121]="你好，英雄。我制造和出售术士需要的黑巫套装。"
D.Strings[17122]="古老的仇恨在今天得以消弭。"
D.Strings[17123]="你是来参加狩猎的吗，$n？"
D.Strings[17124]="滚吧，$c。我的狩猎不需要你。"
D.Strings[17125]="你需要什么？"
D.Strings[17126]="那么，你想要找到传说中的沙怒之剑？$B$B为了寻求财富与权力，你已经准备好为苏萨斯而杀戮？将热血泼洒在黄沙之上？$B$B既然如此……欢迎来到这片沙漠，朋友。"
D.Strings[17127]="就凭你们的人对我们所做的一切，你们也不配继续占据这片土地！离开这里，否则狼人的怒火就要把你们烧毁！"
D.Strings[17128]="我会确保暗矛巨魔顽强屹立，发挥出它所应有的力量。"
D.Strings[17129]="人们对迅猛龙的了解只限于野蛮凶残，除此之外知之甚少。实际上，他们的忠诚和机智超乎你的想象。"
D.Strings[17130]="%s开始发动强能震荡涡流！"
D.Strings[17131]="你想要加入对抗纳迦的战斗吗？"
D.Strings[17132]="滚开，怪物！别盯着我！我知道我很丑！"
D.Strings[17133]="你不丑，莉莉安……你跟我们一样。来，看看这面镜子，看看你自己的样子。"
D.Strings[17134]="你不明白……我不能变成亡灵！我不能，现在不能……"
D.Strings[17135]="你在这里干什么？离开这儿！"
D.Strings[17136]="我是来救你的。"
D.Strings[17137]="首先，我不需要被援救。第二，我绝不会让你这样的憎恶来救我！"
D.Strings[17138]="莉莉安，你是被遗忘者，就像我一样。可问题是——为什么血色十字军会把你放进笼子里？他们通常只要见到亡灵就会立刻杀掉。"
D.Strings[17139]="我不是亡灵！至少很快就不是了。我父亲会来救我，我知道……"
D.Strings[17140]="你父亲？"
D.Strings[17141]="时间到了，我的小俘虏……你父亲那里传来了消息。"
D.Strings[17142]="盖比勒，你来了！他怎么说？"
D.Strings[17143]="高阶牧师沃斯已经抛弃了你这个女儿。他要求立刻把你处死。"
D.Strings[17144]="什么？不！这不可能！盖比勒，你了解我……我们曾经是朋友！"
D.Strings[17145]="高阶牧师对你失望不已。他曾经以为，你终有一天会成为我们对抗敌人的一件强大武器。"
D.Strings[17146]="不幸的是，你活着的时候就太过危险，成为亡灵后变得更加危险。受死吧，天灾女巫……"
D.Strings[17147]="生者的世界已经抛弃了我，但我并不是该诅咒的天灾亡灵。走吧。"
D.Strings[17148]="是……等等，安静！我听到那名军官正向这里走来。"
D.Strings[17149]="盖比勒，父亲，为什么你们……"
D.Strings[17150]="作为暗矛部族的一员，是我最大的光荣。沃金将领导我们赢取巨大的荣耀。"
D.Strings[17151]="我如同羊群前的雄狮，但它们不畏惧我。"
D.Strings[17152]="也不敢畏惧。"
D.Strings[17153]="真冷……"
D.Strings[17154]="请从寒冷中拯救我！"
D.Strings[17155]="准备去死吧！"
D.Strings[17156]="这太疯狂了！沃金是认真的。他要找到那个女海巫，向她复仇。"
D.Strings[17157]="你也想分一份？那你可要努力了，宝贝儿！"
D.Strings[17158]="赶快，$c！能拿的全拿走！"
D.Strings[17159]="所有这些牛头人的身上都只有一些念珠和垃圾。你有没有找到什么有用的东西？"
D.Strings[17160]="嗨，$c！这个地方已经被搜检得差不多了。不过你也许还可以花些时间来搜索一下。"
D.Strings[17161]="喔，你来这里不是要对我们进行突击搜查吧？"
D.Strings[17162]="你的训练师应该就在不远的地方。稍后我再来找你，兄弟。"
D.Strings[17163]="我希望这次行动过程中不会出现任何严重事故。"
D.Strings[17164]="火山爆发的时候，你的朋友全都被贸易大王加里维克斯抓住了。$B$B我们必须尽快解决联盟的人，这样才能救出他们，离开这座岛。"
D.Strings[17165]="为杰罗德工作并不是那么糟糕。他也许偶尔会发发脾气，但他付的薪水很高。当我不能按进度完成工作的时候，他甚至还会帮我的忙。"
D.Strings[17166]="我能为你做些什么？"
D.Strings[17167]="<亡灵卫兵希米尔专注地看着你。>"
D.Strings[17168]="酋长会帮助我们保卫我们的族人，对付加里维克斯。只要我们帮助他们对付联盟。$B$B听上去，这是一笔公平的交易。我的朋友的敌人就是我的敌人，对不对？"
D.Strings[17169]="要到哪里去？"
D.Strings[17170]="现在我要飞往布瑞尔。"
D.Strings[17171]="贫瘠之地告诉我们，只有焦土政策才能彻底清除那些部落怪物。对敌人不要有半点同情！"
D.Strings[17172]="莉莉安……你……真高兴能看到你没事。"
D.Strings[17173]="闭嘴。"
D.Strings[17174]="你将我培育成一个杀手。我做得如何，爸爸？"
D.Strings[17175]="我，啊……"
D.Strings[17176]="但，等一等……我现在记起来了。你教过我只能杀亡灵。那么你想让我杀掉我自己吗，爸爸？"
D.Strings[17177]="莉莉安，我……"
D.Strings[17178]="那么，我为什么要把自己杀死……我可以杀死你！"
D.Strings[17179]="谢谢你为我做的一切……爸爸。"
D.Strings[17180]="我能帮助你吗？"
D.Strings[17181]="是否做好开始的准备了？"
D.Strings[17182]="我们在这里竭尽全力医治残破的大地。就在这种极为艰难的情况下，我们还在夜晚遭到了袭击。"
D.Strings[17183]="很好，跟着我。"
D.Strings[17184]="现在该是开始的时候了。"
D.Strings[17185]="代弗林·阿加曼德！听我说！"
D.Strings[17186]="你在凡间的遗骸已经被收集完整，被放置在这个你渡过童年光阴的地方！"
D.Strings[17187]="代弗林，抵抗巫妖王的意志！到我们这里来吧！"
D.Strings[17188]="我最好回到我的岗位上去。如果有需要，你可以在楼下找到我。"
D.Strings[17189]="$c，现在我有一点忙……等我有空的时候再来找我吧。"
D.Strings[17190]="这里出了什么事？"
D.Strings[17191]="等等，我是……在家里？"
D.Strings[17192]="你们……你们在这里干什么？为什么你们会在我的房子里？"
D.Strings[17193]="妈妈……爸爸……萨尔曼……你们在哪里？来帮帮我！"
D.Strings[17194]="不……我想起来了。我的家人都死了。我也死了。"
D.Strings[17195]="我的灵魂……我的灵魂属于天灾！"
D.Strings[17196]="死吧，倒霉鬼！"
D.Strings[17197]="希米尔说葛尔多有肚子，却没有脑子。这是什么意思？"
D.Strings[17198]="葛尔多喜欢摘花。摘花就像是打仗。"
D.Strings[17199]="这里通风很不错。"
D.Strings[17200]="乔汉说，葛尔多需要个裁缝来修整一下葛尔多的肚子。"
D.Strings[17201]="我代表杰出的，并依旧保持中立的热砂集团向你表示问候，并衷心希望你能在这里渡过一段愉快的时光。$B$B请记住，加基森欢迎所有人！只有海盗除外。"
D.Strings[17202]="死者的鲜血依旧在呼唤着公正的到来。"
D.Strings[17203]="绝不能再耽搁了。必须完成凯旋壁垒的建造和布防，否则我们将没有可能在这片大陆上建立永久定居点。"
D.Strings[17204]="当我和我的蛮锤佣兵受雇守卫凯旋壁垒的时候，我以为我们的敌人将是部落。$B$B但现在我们却陷入了无数敌人的围困之中！爆炸的地精，挖洞的虫子，放电的蜥蜴……"
D.Strings[17205]="记住我的话，锈水财阀终将在这里稳稳地扎下根来。"
D.Strings[17206]="<克拉莉斯看着这具尸体，目光显得苍白而空洞。>$B$B我一得到消息，就从塞拉摩岛马不停蹄地赶到这里。$B$B约翰和我一直在讨论，等战争结束以后就定居下来。$B$B我觉得这场战争永远也不会结束，你觉得呢？"
D.Strings[17207]="萨尔万岁，$n！你是要帮我们消灭那些可恶的矮人和侏儒吗？"
D.Strings[17208]="也许这是岛上唯一凉快的地方了……虽然它就在火山的旁边！"
D.Strings[17209]="嗨，$n。你要进去吗？"
D.Strings[17210]="$n！能帮帮我摆脱菲兹吗？他又要发脾气了！"
D.Strings[17211]="我不敢相信菲兹和艾沃竟然会自相残杀。这一定是因为他们的压力太大了。现在我们更加需要你了，$n。"
D.Strings[17212]="你要到那里去？我可不打算回去了！"
D.Strings[17213]="请投入硬币。"
D.Strings[17214]="这里本来是一个美好而又安全的地方。但前面那片空地上突然就出现了一支侏儒军队。$B$B如果我们让那些卑鄙的小个子在这里打赢我们，加里维克斯一定会要我的脑袋。"
D.Strings[17215]="别闲逛了，我们在这里还有工作。"
D.Strings[17216]="这就是真相！战斗导致杀戮，杀戮导致战争。而这几乎就是我们全部客户的结局！$B$B现在，当人们要进行战斗的时候，它就发生在这里，也在这里结束！并发挥出最大的观赏潜力！"
D.Strings[17217]="我听说过这个叫奈辛瓦里的家伙。他来自于荆棘谷，以猎捕各种野兽为乐。$B$B他认为这是一种运动。真是个彻头彻尾的白痴，对不对？真不知道他到底把多少值钱的东西扔在田野里，任由它们烂掉！"
D.Strings[17218]="他是我的助手。$B$B虽然他也受到了瘟疫的感染，但显然感染的方式和我们有些区别。就像你和我一样，他也臣服于希尔瓦娜斯。$b$b这话不要告诉别人……说实话，我相信当他进入黑暗女王的房间时，黑暗女王并没有怀疑他的忠诚。"
D.Strings[17219]="我们必须在火山真正爆发之前救出所有人，并离开这里！"
D.Strings[17220]="多克纳……这太难堪了。"
D.Strings[17221]="多克纳，你在干什么？"
D.Strings[17222]="立刻给我下来！"
D.Strings[17223]="你不怕两只脚被烧掉吗？"
D.Strings[17224]="坚持住，$r。$b$b纳迦随时有可能再次发动攻击。"
D.Strings[17225]="这里正是这场可能毁灭世界的大灾变爆发的核心区域之一。$b$b如果我们要生存下去，就必须发掘出它的原因。"
D.Strings[17226]="对于这些船只的攻击显然不是偶然的。$b$b我们必须查清楚那些纳迦的动机。"
D.Strings[17227]="%s施放了毒伤！现在马上放好图腾！"
D.Strings[17228]="侏儒夺回家园的时候终于到了。$B$B诺莫瑞根将再次回到我们的手中！"
D.Strings[17229]="我们在矮人王国中得到了庇护。因此，我们对矮人感激不尽。但瑟玛普拉格对诺莫瑞根的统治应该到头了。$B$B我们犯下的大错让诺莫瑞根承受了太长时间的毒害。辐射炸弹曾经让我们彻底失去家园。现在，我们终于掌握了恢复家园的技术！$B$B我们必须夺回诺莫瑞根，让瑟玛普拉格得到正义的审判！"
D.Strings[17230]="诺莫瑞根行动将分成数个步骤完成：$B$B首先，我们必须夺回航空塔。这样我们的飞机才能支援进攻诺莫瑞根主入口的部队。$B$B而且，我们还在诺莫瑞根入口附近的一座建筑中发现了防辐射服。装备上防辐射服的侏儒部队能够直接进入诺莫瑞根。$B$B这样，我们就能在诺莫瑞根的核心对瑟玛普拉格发动直接攻击！"
D.Strings[17231]="有人吗……有人吗……"
D.Strings[17232]="我永远也见不到我的妻子了……"
D.Strings[17233]="我永远也见不到我的丈夫了……"
D.Strings[17234]="救救我！"
D.Strings[17235]="我无法再战斗了……"
D.Strings[17236]="矿车已经做好了出发的准备。"
D.Strings[17237]="这么多数据……这么点时间……"
D.Strings[17238]="教练在这里？！他一定有办法的！"
D.Strings[17239]="我有一个有趣的计划，孩子！"
D.Strings[17240]="不知道我们能将他们拖延多久，$g小子:姑娘;，希望你知道该怎样做！"
D.Strings[17241]="<哼哼>"
D.Strings[17242]="你要学会的第一件事就是遵守纪律。"
D.Strings[17243]="不管怎样，一场战争中最重要的部分是你该如何庆祝来之不易的胜利！"
D.Strings[17244]="当你进入战斗的时候，知道如何用震耳欲聋的战吼威吓敌人是非常重要的！"
D.Strings[17245]="但要记住，赢得战争的关键因素是活跃的增援力量。"
D.Strings[17246]="大家欢呼吧！"
D.Strings[17247]="这些伐木机是从哪里来的？"
D.Strings[17248]="好啊，你真有让机器起死回生的能力。让我们开始工作吧！"
D.Strings[17249]="好了，新兵们，敬礼！"
D.Strings[17250]="让我听听你们的战吼！"
D.Strings[17251]="灰烬审判军和像你一样的英雄们以惨重的牺牲为代价，终于接近了最终的胜利。现在，我来到冰冠堡垒，帮助所有对抗天灾军团的勇士们。我们将并肩作战，结束巫妖王的暴行！"
D.Strings[17252]="尊敬的殿下，我们能够完成这个任务。"
D.Strings[17253]="你一个人就行？你是傻了？还是自信过度？\n\n当然，我能在你的眼睛里看到取胜的决心。不过你需要用实力来证明自己。好吧，如果你想要这样，我会从战场上撤退。"
D.Strings[17254]="跳舞吧！"
D.Strings[17255]="我要让你们知道该如何成为一名真正的士兵！"
D.Strings[17256]="我们恳请您解除戒备，陛下。"
D.Strings[17257]="要击败巫妖王，你需要的将不止是勇气。祝你好运。"
D.Strings[17258]="你已经做出了选择。至于是生是死，就只能靠你自己了。"
D.Strings[17259]="我一发出信号，你们就用最大的力气吼叫！"
D.Strings[17260]="听我的命令，敬一个标准的军礼，让我看看你们的纪律！"
D.Strings[17261]="我们言出如山，巫妖王必将败倒在我们脚下！"
D.Strings[17262]="诺森德的战事需要你的关注，地狱咆哮统帅。没有你的力量，我们也将去讨伐巫妖王和他的爪牙。"
D.Strings[17263]="战歌远征军已经到达冰冠堡垒。胜利就在眼前！巫妖王的惨败将成为部落新的荣耀！"
D.Strings[17264]="你的选择很勇敢！而你对荣耀和功业的欲望也值得尊敬！光荣地去死吧，$n！"
D.Strings[17265]="你们还要懂得在战场上用欢呼激励你们的同袍。现在，听我的命令，发出欢呼！"
D.Strings[17266]="我一发出信号，就给我跳出最漂亮的胜利舞蹈！"
D.Strings[17267]="喔，真是惊人啊！"
D.Strings[17268]="太棒了！"
D.Strings[17269]="漂亮极了！"
D.Strings[17270]="你们是我见过的最优秀的新兵！我们很快就会再次开始演习了。"
D.Strings[17271]="以前的情形要比现在好得多……我们到底出了什么事？"
D.Strings[17272]="登上这架飞行器吧。"
D.Strings[17273]="看上去，它足以承载一名侏儒，也许还能承载两个。"
D.Strings[17274]="我们其余所有人都在那下面！"
D.Strings[17275]="提拉加德现在归北卫军了！"
D.Strings[17276]="要是菲兹能稍微机灵点儿，我们绝对不会被捉住！"
D.Strings[17277]="暮光之锤是起决定性作用的力量。因为我们，死亡之翼自由了。因为我们，上古之神从大地深处重生。因为我们……海加尔在燃烧。$B$B你觉得你能为我们做什么？"
D.Strings[17278]="全靠你了，$n。你必须击败贸易大王，否则我们将一败涂地。"
D.Strings[17279]="嗨。"
D.Strings[17280]="请插入硬币，然后继续同贸易大王做交易。"
D.Strings[17281]="运气如何？"
D.Strings[17282]="不管是地震还是洪水，魂灵使出的任何把戏都别想阻止我履行自己的职责。"
D.Strings[17283]="天意如此，$n。你必须获胜，否则我们将落得一败涂地，与这座岛屿一同消亡。"
D.Strings[17284]="老实说，这些家伙怎么老是会被捉住？真是彻彻底底的无能！$B$B这简直让我为地精的身份而感到羞耻。$B$B说到羞耻，我那个好吃懒做的助手跑哪儿去了？不用猜，她肯定正坐在什么地方发呆呢！$B$B喔，这可真叫做能者多劳。我想只能靠我来想办法帮大家脱困了。"
D.Strings[17285]="我们来此表达对伟大森林的敬意，亲眼见证大地之母馈赠的奇迹。"
D.Strings[17286]="你是来帮忙的吗，$c？这个山谷就是个天然的阻塞点。要是我们能扼住这条补给线，就能为我们在世界之树的同伴争取时间来发起反击。"
D.Strings[17287]="我不明白这些补给品是从哪儿来的。暮光之锤不知想出了什么办法，同时对整座圣山发起攻击……"
D.Strings[17288]="<这只机器人大猩猩似乎已经损坏了。>"
D.Strings[17289]="你想要什么，$r？"
D.Strings[17290]="我吓到你了吗，$r？"
D.Strings[17291]="怎么了，老兄……没见过狼人吗？"
D.Strings[17292]="算我一个！"
D.Strings[17293]="炸毁那些杜隆塔尔的岩石大道！我已经确定了几个需要炸毁的地方。但这里并不是其中之一。"
D.Strings[17294]="坡道上面，$n！帮助萨尔击败贸易大王！"
D.Strings[17295]="$n，帮助我。贸易大王已经强大了许多！$B$B我不知道自己还能坚持多久。"
D.Strings[17296]="戈杜尼食人魔已经破坏这片土地相当久了。我们来这里，就是要为部落夺回这片土地以及它丰富的资源！"
D.Strings[17297]="石槌部族效忠于部落！$B$B在奥格瑞玛建立期间，当我们的族人努力将卡利姆多改造成我们的家园时，英雄雷克萨击败了石槌食人魔部族的首领。$B$B从那时起，他们便发誓为部落效忠，我已经将他们召集至此，铲除戈杜尼部族。"
D.Strings[17298]="<菲兹尔的躯体晃动着，毫无生命气息，右手却依然紧攥着那颗宝珠。>"
D.Strings[17299]="<你抓住那颗宝珠，但菲兹尔的手将它抓得更紧了。这颗球微微闪烁着光亮。>"
D.Strings[17300]="别被鹰身人那长满羽毛的翘臀迷惑……她们的杀伤力可是致命的！"
D.Strings[17301]="Lok'tar ogar，士兵。"
D.Strings[17302]="我们暂时还无法返回卡利姆多。只有卡乌格会跟你一起回去。另一艘船会把我们剩下这些人带去目的地。$B$B最伟大的冒险还在前方等着你呢，$n。我们的道路还会再次交汇，到那时，世界的命运将掌握在我们手中！"
D.Strings[17303]="我们要先去奥格瑞玛，$g 小伙子 : 姑娘;，然后前往我们在艾萨拉的新家。在那儿见吧！"
D.Strings[17304]="这可真是个漫长的旅程啊，宝贝儿。谢谢你！$B$B现在让我们离开这座岛吧。"
D.Strings[17305]="谢谢……你……"
D.Strings[17306]="你是位真正的$g大英雄:女英雄;，$n！是锈水财阀的偶像$g帅哥:美女;。$B$B我们的股价将一路飙升，而我也能得到加薪了！"
D.Strings[17307]="锈水财阀的未来看起来可不乐观。一点儿也不。$B$B你必须帮我们及早抽身，$n，否则我们不如直接跳进那边的火山里算了。"
D.Strings[17308]="喔天哪，你做到了，$n，你真的做到了！$B$B现在，根据我的估计，如果我们不在最短最短的时内里起航，那堆巨型火山石从天而降，把快艇击成碎片的可能性会越来越大。$B$B出发吗？"
D.Strings[17309]="这里就是被你称为很糟糕的地方！"
D.Strings[17310]="真是一团糟！我该怎么旋转这个？$B$B这是真的吗？僵尸地精？！！"
D.Strings[17311]="你成功了，孩子！你带球冲进了得分区，引爆并一举取得了胜利！$B$B现在让我们离开这儿吧。我想新的队伍可以命名为$n爆破队！"
D.Strings[17312]="你做到了，我的$g 小伙子 : 姑娘;，你做到了！$B$B现在让我们前往艾萨拉，是时候开始我的新事业了。这个假期可真漫长，我还有账单要付！"
D.Strings[17313]="我不认为你还能想到什么办法把我们从这里弄出去？有吗？$B$B啊，好吧，希望当岩浆缓缓流进来时，我们不会死得太痛苦。"
D.Strings[17314]="我知道你一直都有这潜质，$n。$B$B现在说说——你觉得在艾萨拉会有我的位置吗？那儿有巨魔吗？"
D.Strings[17315]="我只想说声谢谢，$n。$B$B这儿的医生能把你救醒真是太好了，不然我们现在都已经死了，甚至更糟！"
D.Strings[17316]="我才不会为你收拾残局呢，你听好了！$B$B你得去解决贸易大王那只老鼠，我就是这么想的！"
D.Strings[17317]="为$n三呼万岁！$B$B我真恨不得现在就去艾萨拉搭起我的小床，吃顿可口的早餐。你觉得那里会是什么样的？"
D.Strings[17318]="你干得棒极了，$n。你可真是一流！$B$B不过，当然，要是没有我的聪明才智，你也做不到——我相信你肯定会在工作报告中写上这一条的。不管怎样，虽然我那笨手笨脚的助手老是添乱，你还是圆满完成了。"
D.Strings[17319]="我们的目的地是奥格瑞玛和艾萨拉。舰船宝贝儿，起航！"
D.Strings[17320]="请把硬币插入船里，以驶离爆炸的岛屿。"
D.Strings[17321]="让我们起航前先把菲兹扔出去。我抬头，你搬脚！"
D.Strings[17322]="让我们彻底解决那个废物吧，艾沃。艾萨拉没法同时容下我们两个人！"
D.Strings[17323]="我就知道你能做到，$n！你救了我们。$B$B现在趁我还没杀死菲兹和艾沃，让我们赶快离开这儿。"
D.Strings[17324]="你知道你为我们节省了多少宝贵的时间和金钱吗，$n？这原本有可能成为一场彻底的灾难，而你单凭一己之力就拯救了整个财阀。$B$B你和萨尔就这么放过了加里维克斯真是太可惜了。我想你肯定能成为一位杰出的贸易$g大王:女王;！"
D.Strings[17325]="没人能取得你的成就，$n。可我不明白为什么你没把加里维克斯拉下马。你本该接替他的职位。$B$B希望我们能顺利在艾萨拉安下新家。我盼望着能早点儿退休呢。"
D.Strings[17326]="我现在没和你说话。如果我是你，我决不会指望今年的加薪了，$n。"
D.Strings[17327]="你成功了！我们得救了！"
D.Strings[17328]="我们真的要去艾萨拉吗？那里是不是也有一座火山？"
D.Strings[17329]="我该怎么感谢你呢，$n？"
D.Strings[17330]="如果我是你，我就会放亮眼睛、竖起耳朵。有传闻说，卡亚罗和失落群岛的火山喷发都与你有关。$B$B我知道这听起来很疯狂。但人们八卦的素材总是千奇百怪，而且总以毁掉英雄为乐——尤其是在有利润和晋升驱使的情况下。"
D.Strings[17331]="我们得在被火山杀死之前离开码头！"
D.Strings[17332]="等您准备好就能出发了，$g 阁下 : 女士;！"
D.Strings[17333]="我不知道。我想我会想念这里的。我们在这儿共度了不少美好时光。"
D.Strings[17334]="我有个主意……这次我们别在联盟和部落的海战中徘徊了。$B$B我只是说说。"
D.Strings[17335]="愿大地母亲时刻护佑你，$n。谢谢你的帮助。"
D.Strings[17336]="你的生命之歌将永远激昂，$n。下次再见。"
D.Strings[17337]="我在艾萨拉还有其它事情要解决，所以我会和你一起上路，$n。"
D.Strings[17338]="你有一颗巨人的心，$n。我无比荣幸！"
D.Strings[17339]="看来就这样了，$g阁下:女士;。这真是我的荣幸。相信我们很快就会再见面。"
D.Strings[17340]="克罗米，你和我都知道在这个时间流中会出什么事。我们以前都遇到过这种情形。你能不能略过这些部分，直接进入真正的行动？"
D.Strings[17341]="没错，我曾在这里见过你！我怎么会忘记呢？$B$B如果你愿意的话，我可以立刻把你传送到斯坦索姆去。"
D.Strings[17342]="%s开始施展污染！"
D.Strings[17343]="|TInterface\\Icons\\ability_creature_disease_02.blp:16|t你受到了|cFFBC05FF死疽|r的伤害! |TInterface\\Icons\\ability_creature_disease_02.blp:16|t"
D.Strings[17344]="他们也许会夺走我们的生命，但他们永远也无法夺走……"
D.Strings[17345]="你们要搜遍每个补给站，每个居民点，每一座仓库、农舍、鸡窝、厕所和狗屋。哪怕钻进地心也要把目标找出来！"
D.Strings[17346]="我们不会沉默地堕入黑夜！我们不会不经一战就自行消失！"
D.Strings[17347]="嗯，我猜它可能会有用。但它至少还要再诱人一些！"
D.Strings[17348]="什么？我甚至不知道你在说些什么！这太恐怖了！"
D.Strings[17349]="太可怕了！好吧，也许它只是需要被清理一下？"
D.Strings[17350]="Al'tha， Al'tha bormaz， Ni bormaz ta'thall？它来了，它行走在火焰中，$r！"
D.Strings[17351]="阴影看得见。Bo'al lal arwi C'toth。末日即将来临，掩藏在无声的烈焰之中。"
D.Strings[17352]="Mar'kowa tallol ye'tarin，它知道，它明白。"
D.Strings[17353]="恐惧从永恒之心内蒸腾而出。别逼我看！我所看到的一切已经超出了我的承受极限！"
D.Strings[17354]="我们什么都不是。Tulall par'okoth。Far'al, ka'kar。虚空吞噬一切。"
D.Strings[17355]="<暮光仆从向你“嘎嘎”地叫着，白色的泡沫从嘴角边淌了下来。>"
D.Strings[17356]="H'thon，黑暗的幕帘延伸到视野之外。H'thon marwol qualar：面对黑暗的永恒之握。"
D.Strings[17357]="……我们的发明！"
D.Strings[17358]="那个逃亡者的名字是机械师瑟玛普拉格。"
D.Strings[17359]="去找到他。"
D.Strings[17360]="虽然历经劫难，但我们还是会生存下去！今天，我们要庆祝……"
D.Strings[17361]="……我们终于夺回了主权！"
D.Strings[17362]="$n，你们从狼神小径救出来的那些暮光奴隶进了营地，可他们无法讲明他们的身份，语言也含混不清。$B$B我原本以为暮光之锤是以古老的方式对待奴隶——你知道，就是鞭子和锁链那种——但很显然，他们还加入了洗脑的步骤……"
D.Strings[17363]="运气怎么样？试着和那些被解救的奴隶交谈真让我头痛不已。$B$B他们口齿不清的发着刺耳的噪音，然而还很押韵。"
D.Strings[17364]="谢谢你的帮助，$n。"
D.Strings[17365]="不知恢复神智是不是件好事。$B$B我所知道的一切……也许即将发生在这世界上的一切……$B$B<他战栗着陷入了沉默。>"
D.Strings[17366]="多谢你救了我们，$c。$B$B我们要护送下一个车队下山，但……我不认为我还会犯同样的错误……"
D.Strings[17367]="哨兵部队在卡利姆多各地阻挡部落的攻势。当灰谷与石爪山相继被战火席卷之时，这里也需要我们的帮助——我们要保护那些仅存的野生动植物，并阻止我们的敌人攻占更为纵深的据点。"
D.Strings[17368]="你好啊，$c。我想你一定有很多问题要问。$B$B简单说吧，罗伊斯·暮语把我派到这个食人魔洞穴里干什么与暮光之眼相关的活计，可进展得并不顺利。$B$B要是我能抓住那个皮包骨头、没心没肺、油嘴滑舌的暗夜小精灵……$B$B<倒吊在空中的克里斯托弗无助的扭动着，脸涨得通红。>"
D.Strings[17369]="你闻到什么了吗？"
D.Strings[17370]="我很愿意帮你，可我被……链子缠住了。我只能往回晃一点儿。"
D.Strings[17371]="你可真是个与众不同的$c，$n。我不是在说你坏话。我只是说，你还挺有趣儿。"
D.Strings[17372]="我吊在那儿多久了？感觉应该有好多天了。"
D.Strings[17373]="像那样吊在链子上的滋味可不怎么好。不过，老实说，那对我头发有好处。"
D.Strings[17374]="食人魔。$B$B我恨食人魔。"
D.Strings[17375]="当有东西给你杀时，你总是话那么多吗？"
D.Strings[17376]="少说废话，多杀点儿食人魔。好吗？"
D.Strings[17377]="阿莱克丝塔萨选对了盟友……很可惜，你们都将死在这里！"
D.Strings[17378]="不要心存侥幸！"
D.Strings[17379]="这是最好的结局。"
D.Strings[17380]="海里昂，我……"
D.Strings[17381]="让他们化为灰烬，仆从们！"
D.Strings[17382]="嗯？你打算帮我下去吗？"
D.Strings[17383]="$n，$n，我能叫你$n吗？$B$B我马上就要被挂到食人魔洞穴里的肉钩子上了。$B$B你觉得我的研究进度如何？你这个中看不中用的笨$c！到这里来！你这个坏家伙！$B$B<克里斯托弗在锁住他的链子上晃来晃去，拼命想要踢到你的脸。>"
D.Strings[17384]="<克里斯托弗哼哼着。>"
D.Strings[17385]="在所有远古半神中，戈德林是最杰出的一位。他的狂怒，他的决心……你一定能赶上他。"
D.Strings[17386]="陷阱！一台全线运作的辐射器！"
D.Strings[17387]="太安静了。瑟玛普拉格的军队在哪里？"
D.Strings[17388]="不！不，不，不！！！我不会让你进入我的王国！我绝不允许！"
D.Strings[17389]="激活终极原子保卫系统。"
D.Strings[17390]="……彻底粉碎他们！"
D.Strings[17391]="十分钟！你还没改那东西的设置？快把控制器给我，白痴！"
D.Strings[17392]="十分钟？足够拆除这个装置了。"
D.Strings[17393]="辛克尔斯，把高速青铜齿轮和清凉的泉水给我。克斯宾，扔给我肮脏的穴居人布片和一把螺栓……"
D.Strings[17394]="呦喔！雷戈，送我们回去，赶快！"
D.Strings[17395]="我来这里是为了研究灵魂精华——野性魔法的作用方式。巫医尤克里派我来从森林里的低等生物入手。"
D.Strings[17396]="你好，$c。$B$B山脉崩塌，大灾变造成海水灌入，淹没了千针石林。$B$B我们需要你的帮助，就是现在！"
D.Strings[17397]="在主人的烈焰中燃烧吧！"
D.Strings[17398]="这是个好人，$r。我们曾在多次战争中并肩作战……$b$b这些野兽有债要偿！"
D.Strings[17399]="3000型辐射器已开启。注意，紧急。你有十分钟来抵达最近的安全区域。"
D.Strings[17400]="*哔*注意，紧急。你有十秒钟来抵达最近的安全区域。"
D.Strings[17401]="擅闯者死！"
D.Strings[17402]="本该如此……"
D.Strings[17403]="海里昂会高兴的。"
D.Strings[17404]="啊，娱乐要开始了！"
D.Strings[17405]="我……没想到会这样……"
D.Strings[17406]="巴尔萨鲁斯从不留活口！"
D.Strings[17407]="这个世界的英雄够多了。"
D.Strings[17408]="双倍的痛苦不过是个开始。"
D.Strings[17409]="多管闲事的虫子！你们来晚了。红玉圣殿已经沦陷了！"
D.Strings[17410]="我们向艾森娜发出的祈求没有得到回应。拉格纳罗斯麾下的燃烧爪牙已经将我们逼到了悬崖的边缘。如果我们不能在此终止他们的行径，世界之树将被大火烧得只剩下残桩断枝！"
D.Strings[17411]="生命的希翼已被斩断。$B$B梦游者一定会复仇的。"
D.Strings[17412]="啊……$b$b我的感觉……不太好……"
D.Strings[17413]="多谢你，$c。$b$b我差一点儿死在那了。"
D.Strings[17414]="我们来此为我们的人民守护这些土地。"
D.Strings[17415]="$R，你要找我？自从主人去世之后，我已经被遗弃多久了？"
D.Strings[17416]="欢迎你，$c。$B$B海加尔燃起了熊熊烈火，我耗尽毕生心血保护的世界已在毁灭的边缘。$B$B告诉我——你可曾听说过泰拉斯·黑角这个名字？"
D.Strings[17417]="十年前，在海加尔山的顶峰爆发了一场旷世之战。污染者阿克蒙德指挥恶魔大军攻占了世界之树，并将其力量据为己有。$B$B他的战败标志着燃烧军团入侵艾泽拉斯计划的终结……但他许多堕落的支持者却仍没有离开。"
D.Strings[17418]="既是又不是。他现在也许是个恶魔，可泰拉斯·黑角曾经是个暗夜精灵。就像他用恶魔军团许给他的权利去劝诱和转变的那些同胞一样。$B$B在主人战败后，他被俘获并关在这顶峰上，神圣能量缚住了他不朽的人形。$B$B可也许在他心中仍有最晦暗的灵魂火光在燃烧……我们至少要设法弄个明白。"
D.Strings[17419]="我的帮助？事态已经恶化到如此地步了吗？$B$B<黑角残忍的黑色瞳仁里闪着许久未见的光焰。>$B$B告诉我，我为什么不该让你的世界自生自灭？"
D.Strings[17420]="我在这里是为了防备有人晕倒。新兵们有时会因为过度兴奋而导致体力透支。\n\n……嗯，有时候那种新型步行坦克也会爆炸。轰！"
D.Strings[17421]="凡人？不错，我曾是个凡人。弱小的凡人。$B$B你看到我现在所受的束缚了吗？但与身为凡人的桎梏相比，这些根本算不了什么。$B$B甚至现在，我主人的馈赠都在我体内激涌，随时准备释放。$B$B不，$c，凡人的身份已经离我远去，假如我体内还有丝毫过往生命的残焰在燃烧，我也希望它尽快熄灭。你最好去想其它办法，$r。"
D.Strings[17422]="被摧毁了？好吧，这也有可能。深夜里，我常常会受到同一个噩梦的困扰——这个世界从内部被撕成了碎片。但我并不觉得哀伤，也没有愤怒。只是……好奇。$B$B$c，我侍奉我的主人，从而换取力量。但你与之战斗的这些家伙……他们想要的只有灭亡。这真是一个奇怪的动机。"
D.Strings[17423]="<黑角挣扎了一下。他第一次显露出烦乱的神情。>$B$B算了吧！难道你真能逃出燃烧军团的魔爪吗？不要自鸣得意了！难道你们十年前的所为和在外域的所作所为曾经减慢过燃烧军团的步伐吗？他们一定会回来的，$r。他们会回来。我则会在这里迎接他们。"
D.Strings[17424]="<咳嗽。>$b$b我……死了吗？"
D.Strings[17425]="你很有天赋，$n。但仁慈使你懦弱。"
D.Strings[17426]="……主人？"
D.Strings[17427]="你们的世界正在灭绝的边缘摇摆。你们都将见证毁灭时代的到来！"
D.Strings[17428]="享受胜利吧，凡人们，这是你们最后的胜利。回归的主人将烧毁这个世界！"
D.Strings[17429]="又一个“英雄”倒下了。"
D.Strings[17430]="暮光的世界将会让你痛不欲生！够胆量的就进来吧！"
D.Strings[17431]="天空在燃烧！"
D.Strings[17432]="阴影在弥漫！"
D.Strings[17433]="黑暗能量正在这颗旋转的魔球中脉动！"
D.Strings[17434]="我就是交织的光影！凡人，在死亡之翼的使者面前颤抖吧！"
D.Strings[17435]="战友们的努力逼迫%s进一步进入了物质世界！"
D.Strings[17436]="战友们的努力逼迫%s进一步进入了暮光世界！"
D.Strings[17437]="真好，你终于来了！$b$b时间不多，你准备好了吗？"
D.Strings[17438]="我是第一批响应沃金的号召，投身军队的人之一。你愿意加入我们吗？"
D.Strings[17439]="兰德鲁的礼物盒"
D.Strings[17440]="快干塑像"
D.Strings[17441]="炽焰角鹰兽"
D.Strings[17442]="涂料炸弹"
D.Strings[17443]="传送石"
D.Strings[17444]="犀牛坐骑"
D.Strings[17445]="天谴之门"
D.Strings[17446]="我原以为我的首次洋底冒险会是波澜不惊和令我大开眼界的。也许会有种与大自然融为一体的感觉？$B$B可这地方毫无自然之感。我们周围无所不在的元素们都在为复仇而呼号。"
D.Strings[17447]="如果你想要蝙蝠，那么你可是来对地方了。我掌管着全部哨兵的蝙蝠。"
D.Strings[17448]="你！$B$B你以为你能像这样轻而易举的走进来夺走我的位置？再好好想想吧，$g小男孩:小姑娘;！$B$B我听见了会议室里的窃窃私语。在指挥部里围绕在你身边的那些人都是些溜须拍马的狗腿子，为上位不择手段。我应该知道的……当初是我把他们找来的。$B$B你的飞黄腾达只不过是侥幸，而且我已经做好充分的准备把你打回原形！你给我小心点儿，$n。没准儿哪天你还需要我帮你的忙！"
D.Strings[17449]="%s“咯咯”笑着。"
D.Strings[17450]="你为战争做好准备了吗，$r？"
D.Strings[17451]="瓦妮拉让我从你这里借一只蝙蝠。"
D.Strings[17452]="我真想能再续上一杯。"
D.Strings[17453]="呃……给我来个桶！"
D.Strings[17454]="要是我能有个舞伴儿就好了。"
D.Strings[17455]="我喜欢焰火！"
D.Strings[17456]="太美味了！还有更多的餐前点心吗？"
D.Strings[17457]="%s即将被你推离暮光世界！"
D.Strings[17458]="%s即将被你推离物质世界！"
D.Strings[17459]="是的，只要毁了四种元素，门就会打开。我确定。不过要小心那些穴居人。那些脾气乖戾、又臭又脏的生物——尽管他们还没屈服于血肉诅咒。"
D.Strings[17460]="我不知道你怎么样，老兄，可我不能在水下呼吸。"
D.Strings[17461]="我在此需要用来证明自己的，就是我的爪子！"
D.Strings[17462]="然后放弃我帅气的特制潜水头盔？没门。"
D.Strings[17463]="我愿意出力。"
D.Strings[17464]="一切为了沃金！"
D.Strings[17465]="指引我杀敌！"
D.Strings[17466]="我就是尖端技术的代表，宝贝儿！灌注元素能量的高科技。到艾泽拉斯海洋的最深处去探求失落的学识与新的资源吧。$B$B请牢记我的名字。"
D.Strings[17467]="我们花费了大量精力训练和照料我们的动物们，但这一切都是值得的。$B$B尽管如此，有额外的帮手总是好的。"
D.Strings[17468]="贸易大王的游艇就要扬帆起航了。所有人都到码头上去！把钥匙给我，老板。我来驾驶。做好出发准备以后就通知我一声。"
D.Strings[17469]="新巨魔报道！"
D.Strings[17470]="报告工作。"
D.Strings[17471]="准备开始对扎拉赞恩的战斗。"
D.Strings[17472]="准备同沃金并肩作战！"
D.Strings[17473]="训练什么时候开始？"
D.Strings[17474]="你在这儿真是太好了，朋友！$B$B那些野生动物不得不逃到这片树林里来躲避烈火。它们已经无处可去了。我们必须保护幸存者！"
D.Strings[17475]="珊蒂斯女士正指望我呢。我不会让她失望的。"
D.Strings[17476]="嘿，$g老兄:小姐;！听说你对贸易大王的职位有兴趣。$B$B是真的吗？"
D.Strings[17477]="嘿你好啊，宝贝儿！你和$g小甜甜:奇普;的传闻是怎么回事？"
D.Strings[17478]="今天可真是个好日子，正适合开挖这世上仅存的卡亚矿石，你不这样认为吗，$n？"
D.Strings[17479]="卡亚矿石在几千年前把我们变得非常聪明，现在却对我们这些巨魔产生不了任何效果，这不奇怪吗？"
D.Strings[17480]="能想到用卡亚矿石蒸馏出卡亚可乐，你可真是个天才啊，$n。贸易大王这下要担心你要抢他的位子了！"
D.Strings[17481]="我可真想一拳打在奇普的脸上！我还想一口亲在小甜甜的脸上！"
D.Strings[17482]="哈，有人在说“聚会”?"
D.Strings[17483]="这瓶叫做卡亚可乐的玩意儿让我想法不断。我们真需要竞赛来获取灵感吗？"
D.Strings[17484]="嘿，嘿！别再怀有敌意了！我就是你们常遇到的那些人畜无害的中立地精，跟部落没关系！"
D.Strings[17485]="我曾经是位女祭司，但我不变的身份却是学者。能够汲取上层精灵的学识，比施行无知的严律要宝贵得多。$B$B更重要的是，这里的大多数学徒，都是在第三次大战期间成年的年轻人。他们需要指引，需要智慧……$B$B我只希望那些曾把我当成朋友的人能明白这一点。"
D.Strings[17486]="暂时够了！"
D.Strings[17487]="不要这么惊讶。你的萨满朋友有着明察秋毫的眼睛，或者说，有着明察秋毫的青蛙。"
D.Strings[17488]="我们德鲁伊一直潜伏在这里，等待着，看沃金是不是会回来。"
D.Strings[17489]="看样子，暗矛部族正在返回这些岛屿。也许我们现身的时候到了。"
D.Strings[17490]="回到沃金那里去，告诉他：岑塔布拉已经做好了和他并肩作战的准备。"
D.Strings[17491]="为哨兵守住这片区域，将是我们守卫菲拉斯任务的最后一步。"
D.Strings[17492]="猛虎之灵，将你的力量借给$n，帮助我们找到答案吧！"
D.Strings[17493]="猛虎女王出现了！在战斗中证明你自己吧！"
D.Strings[17494]="大灾变毁了千针石林的西部山脉。南海灌入并淹没了峡谷。$B$B拜托了，$c，你必须来新萨兰纳尔帮帮我们！"
D.Strings[17495]="大灾变毁掉了千针石林，$c。你愿意在我们最危难的时刻来帮帮我们吗？"
D.Strings[17496]="$C，这场大灾变震碎了山脉。南海淹没了千针石林。$B$B我们需要你的帮助！"
D.Strings[17497]="愿英灵指引你，$c。"
D.Strings[17498]="让我们来解读预兆。"
D.Strings[17499]="恐怖图腾出其不意地突袭了我们。我们就快要坚持不住了。"
D.Strings[17500]="暗矛的成员们，我们要向祖灵寻求答案！鼓手，立刻就位！"
D.Strings[17501]="伟大的英灵啊，我们聚集于此，寻求您的指引。"
D.Strings[17502]="我们的领袖，森金之子沃金向全体暗矛部族的成员发起了号召：夺回回音群岛。"
D.Strings[17503]="伟大的英灵啊！我向您献出自己的身躯。请通过我说话吧！现在是不是强大的沃金开始行动的时刻？"
D.Strings[17504]="巫医，祖先听到你的话了！"
D.Strings[17505]="你们的计划让我们喜悦，暗矛部族，森金之子的道路是正确的。"
D.Strings[17506]="你们的任务相当艰巨，但你们将得到我们的祝福。"
D.Strings[17507]="你们离开回音群岛，放弃了家园和祖先的光荣。祖先不喜欢你们如此冷漠沉寂。"
D.Strings[17508]="如果你们想要击败扎拉赞恩，你们就必须向亡魂的守护者邦桑迪赎罪。把这件事告诉森金之子。"
D.Strings[17509]="祖灵祝福了我们！回音群岛将再次成为我们的家园！"
D.Strings[17510]="在我们最为危难的时刻，恐怖图腾怎么能对我们作出这种事？"
D.Strings[17511]="看看这惨状，$c！放眼望去，视线所及到处都是鲜血与灰烬。$B$B但自然不会如此轻易被打败。只要我们做些努力，这片焦灼的土地将会重焕生机。"
D.Strings[17512]="我认为符文图腾在这毁灭的中心地带设营是在鲁莽行事，可我并不会让大德鲁伊只身来此。$B$B他在酝酿着什么计划，大计划。"
D.Strings[17513]="这群恐怖图腾畜生很快就要去见他们的造物主了！"
D.Strings[17514]="扎拉赞恩让他的大多数巨魔妖术师藏在那座大岛上的树屋里面。"
D.Strings[17515]="他有一支规模很大的军队，而且他正在策划着一个阴谋。"
D.Strings[17516]="谢谢你，哨兵。你还要继续巡逻的工作。不过现在你应该去休息一下。解散。"
D.Strings[17517]="我的迅猛龙能战胜任何事任何人！"
D.Strings[17518]="%s用一声战吼鼓舞起了其他战士的士气。"
D.Strings[17519]="我告诉你，那个科林·烈酒是个疯子。\n\n他没有受邀请参加美酒节的美酒竞赛不是我的错！但这并不能阻止他和他的黑铁同伙殴打我的雇员，还喝光了我的藏酒。\n\n必须有人阻止他的暴行！"
D.Strings[17520]="必须阻止冰霜领主埃霍恩。\n\n现在他正在获得现实的躯体。暮光之锤的疯狂教徒们将它从元素牢狱中召唤了出来。\n\n如果他完全进入我们的世界，他会用永恒的寒冬埋葬我们。"
D.Strings[17521]="必须有人去阻止皇冠药剂公司。我用我的黄金虚空火箭打赌，他们那些让人发疯的巧克力里一定酝酿着另一个大阴谋……\n\n如果有人能逮捕他们的药剂师就好了！这样我们就能结束这场阴谋……也许还能取得他们的全部财产！"
D.Strings[17522]="$g小子:姑娘;，你带了一些石头进来，却没有说明。\n\n你想要干什么？"
D.Strings[17523]="什么？！你说什么？！你怎么敢这样！我的啤酒比他们在美酒节喝的那些烂东西要好得多！\n\n你要为你所做的付出代价，$c！"
D.Strings[17524]="我需要去剃刀岭，为沃金招募新兵。我能借一只蝙蝠吗？"
D.Strings[17525]="我已经做好了夺回回音群岛的准备。带我去军队集结地吧！"
D.Strings[17526]="你怎么敢这样！你阻止不了埃霍恩大人！"
D.Strings[17527]="欢迎来到侏儒区！"
D.Strings[17528]="这块碎冰中回荡着冰川切割地壳时深沉的碎裂声。它能够将你的思维变成没有生命，没有尽头的寒冬。"
D.Strings[17529]="用这块石头召唤埃霍恩大人。"
D.Strings[17530]="扎拉赞恩就要完蛋了。回音群岛将再次属于暗矛部族！"
D.Strings[17531]="暗矛部族回到了家园！$n，如果没有你的帮助，我们无法实现这个梦想。现在，让我们庆祝吧！"
D.Strings[17532]="菲兹尔与普兹克赛艇平台——我的小宝贝儿！是我造出来的！不是他们，不是拉泽瑞克！$B$B它应该叫做金吉赛艇平台才对！"
D.Strings[17533]="我的任务就是确保整个进攻行动像时钟一样准确地进行。$B$B大工匠梅卡托克已经到战场去了，但他正计划返回这里，再将更多的部队带上战场。$B$B他从不会迟到，所以你应该在这里等他。"
D.Strings[17534]="快点！你现在应该去找梅卡托克！如果我们不尽快开始进攻，我们就要耽误行动了。$B$B如果我们耽误的话，我们的首领可是要发火的！"
D.Strings[17535]="菲兹尔、普兹克、金吉……他们都把自己当成我们的救星。但其实是我！船是我造的！$B$B它应该叫拉泽瑞克的赛艇平台！"
D.Strings[17536]="沃金要我在他回来之前一直敲这面鼓。如果你在等他，那么我可以告诉你，他很快就会回来夺回这些岛屿了。$B$B暂时先在这里等一等他，欣赏一下这音乐吧！"
D.Strings[17537]="没有了来自两个领域的压力，%s开始重生了。"
D.Strings[17538]="我们该怎样做？"
D.Strings[17539]="我们正在为夺回回音群岛做准备。扎拉赞恩一直在施展他的黑暗魔法，操纵傀儡，进行古老的黑暗仪式。$B$B他知道我们的行动，所以我们必须做好万全的准备。"
D.Strings[17540]="如果要成功地夺回这些岛屿，我们就需要有援军的帮助。$B$B岑塔布拉一直在照看这片群岛上的动物们。我们需要她和那些动物的帮助。$B$B邦桑迪是一位强大的神灵。他控制着这片群岛上死者们的灵魂。他的祝福对我们是至关重要的。$B$B当我们取得他们的援助之后，扎拉赞恩和被他控制的巨魔将必败无疑！那时，回音群岛就会回到暗矛部族的怀抱！"
D.Strings[17541]="站着别动！罗姆欧格要打碎你的脑袋！"
D.Strings[17542]="显然是这些人对我们的船只发动了突袭，可我没看见任何失踪者。他们被带到哪儿去了？"
D.Strings[17543]="要是有谁能严肃对待我的工作，我会感激不尽。虽然我干的不是像和鲨鱼摔跤或是把鳗鱼打结那样的活儿，可不代表这就不重要。"
D.Strings[17544]="<上古半神的眼睛巨大而深邃。>$B$B<它说话的速度很慢。你也听不懂它所说的语言。寒意爬上了你的脊骨，恐惧和困惑占据了你的心灵。>"
D.Strings[17545]="<上古半神缓缓地张开眼睛，那双眼睛如同充满痛苦与畏惧的深潭。>"
D.Strings[17546]="嘿，快进来乘乘凉。$B$B我帮你弄点儿喝的吧？反正我在这儿也没其它事情可做。"
D.Strings[17547]="战场牌子兑换荣誉值。"
D.Strings[17548]="<上古半神巨大的黑眼睛盯着你，眼睛里流露出不信任的神情。>"
D.Strings[17549]="要是你问我的话，我认为我的兄弟应该解决这些地精！据说他们当中有人用足球炸弹引发了大灾变！$B$B我们得尽快除掉他们，再晚就来不及了！"
D.Strings[17550]="要不是因为那些侏儒，我们怎么会陷入这种混乱！$B$B众所周知，他们才是大灾变的罪魁祸首！引起灾难的就是他们那些能放大世界的装置和诸如此类的破烂！"
D.Strings[17551]="我已经尽力让这艘船不至于散架，我能做的就这么多，而且我还得腾出精力去对付像菲兹尔那样自吹自擂的小丑！"
D.Strings[17552]="我告诉你，这家伙快要把我逼疯了！难道真有人相信，地精能帮忙完成像这座赛艇驳船平台一样的宏伟之作？$B$B他们唯一的本事就是炸东西，而且多半炸飞的是自己！"
D.Strings[17553]="怪物！怪物来抢我们的金子了！"
D.Strings[17554]="杀了那只蠢猪！让它的血溅出来！"
D.Strings[17555]="啊，$n！一只小鸟告诉我，你会来这里。$B$B这是艾维娜传递信息的方式。"
D.Strings[17556]="到处都是烟尘。就算热不死我，我也会窒息而死。"
D.Strings[17557]="你将失败，你的身躯将会破碎！让我的诅咒落在你的身上。这是注定的命运！"
D.Strings[17558]="我欠你的永远还不清，$n。也许，能还清？$B$B嗯？"
D.Strings[17559]="听着，$n，我不喜欢亏欠任何人。所以你能不能低调处理这件事，保守我们俩之间的秘密？$B$B我可不想让我的债主知道。"
D.Strings[17560]="嗯？怎么了？"
D.Strings[17561]="别想冲破我们的封锁线！"
D.Strings[17562]="在月神殿底层有两名德莱尼正在和埃莉萨·杜马斯——就是那位操纵魔法传送门的人类法师谈话。$B$B他们会知道该如何帮助你。"
D.Strings[17563]="干得好，$c。$b$b现在我和我的人已经准备好面对敌人了。"
D.Strings[17564]="救命！我被困在这棵树里了！我需要帮助！"
D.Strings[17565]="谢谢你的帮助！我已经濒临崩溃了……这里发生了可怕的事情。"
D.Strings[17566]="我们相信圣殿是坚不可摧的，但我们没想到会遭受这样的攻击。"
D.Strings[17567]="黑龙人凭空出现，在我们反应过来之前就发动了攻击。"
D.Strings[17568]="我们全面溃败。同胞们一个个死去。只有我撤退到这里，并封住了入口。"
D.Strings[17569]="他们冷酷无情地屠杀我们，但他们真正的目标似乎是圣殿里的那些卵。"
D.Strings[17570]="指挥他们的是一个名叫萨瑞瑟里安的残忍家伙。但我担心他背后还有更强大的力量。"
D.Strings[17571]="刚受到攻击时，我看见了他们真正的首领，一头恐怖的暮光巨龙。"
D.Strings[17572]="我还不知道他们的全盘计划，但我知道，英雄们，绝不能让他们得逞！"
D.Strings[17573]="你的力量在减弱，老家伙……准备下去见你的朋友吧。"
D.Strings[17574]="我们很快就会再见……"
D.Strings[17575]="你得帮帮我！我可怜的，可怜的切尔希……"
D.Strings[17576]="你会灭火并阻止那些海盗上船的，对吧？"
D.Strings[17577]="喔天哪！喔神哪！你会扑灭火焰，并阻止那些海盗登上赛艇平台，是吧？！！"
D.Strings[17578]="海盗、半人马、恐怖图腾，我的天！$B$B而且我想我昨晚还看到一个庞然大物从头顶上飞了过去。它可真是太大了，大得把月亮都遮住了！"
D.Strings[17579]="我们在这儿可能会遇到各种各样的麻烦，但至少我们已经进入开放水域了。$B$B虽然我们不一定能逃过昨晚从我头顶飞过的那大家伙。那玩意儿可真大……我是说，真的很大！"
D.Strings[17580]="献给那些在冰封荒原上为了对抗天灾军团而英勇牺牲的战士们。"
D.Strings[17581]="必定要铲除巫妖王。"
D.Strings[17582]="你好啊，$c！$B$B这些可怜的小家伙正在这黑暗的地方竭尽全力对抗暮光之锤的爪牙！$B$B我已经尽力让那些倒下的死而复生。$B$B要是你需要另一只坐骑，这些鸟已经准备好再次展翅翱翔。好好对待它们！"
D.Strings[17583]="小心，朋友。炎魔之王有结界保护，让我们无法对他发动攻击。"
D.Strings[17584]="嗨你好啊，$g帅哥:美女;。欢迎光临赛艇平台酒吧。$B$B想来点儿什么？"
D.Strings[17585]="你好，$c。希望你能有宾至如归的感觉，即使是在这战火之中。"
D.Strings[17586]="我们在此对抗的势力远远不止暮光之锤、拉格纳罗斯甚至是死亡之翼。我们惟有取胜才能确保我们的世界不至于消亡。"
D.Strings[17587]="我们的胜算不大，但我们不能退缩，$n。在敌人的大军和诺达希尔之间就只剩下我们这一道屏障。"
D.Strings[17588]="拜托了，$r。$b$b我不知道自己还能在这儿撑多久……"
D.Strings[17589]="暮光之锤对我来说不仅仅是个组织。它就像是我的家。$B$B所以，我严加小心以确保不会有人滥竽充数地通过训练。"
D.Strings[17590]="我得尽快找个安全的地方。$b$b老马克的情况不太好。"
D.Strings[17591]="我们需要你的帮助，$n。帮我们阻止那些凶残的部落！"
D.Strings[17592]="这热浪。这令人窒息的热浪。$B$B令我想要靠破坏来发泄。"
D.Strings[17593]="从传送门那边又有人过来了！希望你已经做好了战斗的准备，$c。"
D.Strings[17594]="我们现在已经深入敌后了，$n。我们要尽可能地对敌人制造伤害！"
D.Strings[17595]="要是我们任由暮光之锤在艾泽拉斯各地打开像这样的传送门，那这世上就没有任何军团能挽救这个星球。我们必须一举解决这个坑道网！"
D.Strings[17596]="我们必须坚持，$n。我从我们敬爱的狼神先祖身上学到了一样东西。$B$B那就是永远、永远、永远都不要放弃。"
D.Strings[17597]="派伦迪乌斯倒下了！我们在这儿的工作完成了。$B$B现在只要穿过火焰之门就能返回海加尔山了，$c。我会确保看好大门的。"
D.Strings[17598]="嘘！轻点儿！你要害我们被发现了。"
D.Strings[17599]="<尽管伊瑟拉的肉身就站在你面前，可她的意识却仿佛在两个世界间游移。>"
D.Strings[17600]="你最近去过灰谷吗？那里情况怎么样？"
D.Strings[17601]="莱恩为名，买卖随性！你想来点儿什么？"
D.Strings[17602]="我们猛禽德鲁伊并不适于前线作战。我们是空中侦察兵，是渗透者……$B$B不过我偶尔也不介意让我的爪子沾上血污。"
D.Strings[17603]="在这下面小心点儿，$c。这些雪怪都是残暴的战士。"
D.Strings[17604]="我这辈子看够这个洞穴了。我恨不得立即返回卡拉诺斯。"
D.Strings[17605]="这些雪怪当然是个麻烦，可真正的战斗却是对付那些霜鬃难民。"
D.Strings[17606]="小心，$n！督军罗克托克就在附近。他随时都会出现！"
D.Strings[17607]="石爪山这里总是困难重重，$n，但这片土地和生活在这里的人民从没像现在这么痛苦过。如果不加以制止的话，部落会把我们全都毁掉。"
D.Strings[17608]="你一定要救救我，$c！他已经疯了……疯了知道吗！由于他不能改变千针石林被洪水吞没的事实，他已经彻底精神失常了！$B$B他把一切都怪罪到我头上，包括大灾变。他可能认为我是死亡之翼或什么东西假扮的！$B$B救命！"
D.Strings[17609]="你从我这里什么都别想得到，$r！"
D.Strings[17610]="<玛瑞恩一边大声喘叫一边瞪着你。>"
D.Strings[17611]="你们的城市将会陷落，$r。你们将消亡在新政权的黑暗之中！"
D.Strings[17612]="想做什么尽管去做。我的新主人将会在他们处死你之前，把我的名字刻进你的血肉里。"
D.Strings[17613]="她要这些蛋。要把它们带到她在另一个王国的炽热孵化场。$B$B而其中一只蛋……很特别的一只……是她最想要的。"
D.Strings[17614]="她是天穹之主，也是黑暗之王。她是大地守护者的子嗣。她是不可战胜的！"
D.Strings[17615]="愚蠢的$r！新的秩序已然建立。艾维娜已经死了。死了！再也不会回来了。$B$B回去告诉树林里的那群德鲁伊。$B$B塞西莉亚很快将成为新的天穹之主，而且有她在，艾维娜再也别想重生！蛋是塞西莉亚的了！$B$B你来的太迟了。"
D.Strings[17616]="需要什么吗？"
D.Strings[17617]="冰淇淋！"
D.Strings[17618]="那该死的野兽被赶跑了，可我宝贵的水资源被玷污了！我必须立刻净化它。$b$b如果你坚持要继续留在这儿，就请自保吧。"
D.Strings[17619]="欢迎你，$c！欢迎来到艾维娜圣殿——天空中所有生灵的避风港。$B$B艾维娜或许已经不再与我们同在，但她的心魂与她的凶猛战力却将永远留存在所有藉双翼翱翔的生灵身上。$B$B要是你想了解艾维娜的故事，可以与位于下方的楚伦娜交谈。"
D.Strings[17620]="我不知道我在这儿干什么。我没有做合约谈判员的经验。$B$B我以前曾经干过酒保，可因为黛西的原因做不下去了。也许是时候转行了。"
D.Strings[17621]="楚伦娜和希萨莉都已经把他们的报告给了我。现在我已经非常清楚了……$B$B$n，我相信艾维娜应该很快就会回来了，但我们必须阻止黑龙塞西莉亚！"
D.Strings[17622]="喂——这边！暂时别出现在视线之内……"
D.Strings[17623]="我以前就是个在赛道边上谋生的奖券商。可现在没比赛，也就没钱赚了。$B$B我现在正在努力学习谈判。你能帮我让这里的一切顺利进行吗？他们有油！"
D.Strings[17624]="许多人把血魔法当作一门黑暗与失落的艺术，对其避之不及。从那以及许多其它方面来说，它与恶魔的法术有着某种共通的鲜明特性。在这里——在黑色沼泽恶魔肆虐的遗迹中，我们相信我们的血魔法一定能焕发光华。"
D.Strings[17625]="你能教一名士兵学会杀戮的技巧，可你不能教他杀戮的欲望。还好我们在这下面不用担心这一点。我的每一位弟兄都已经迫不及待地想要把那些纳迦撕成碎片，让他们为犯下的恶行付出代价，而我也一样。$B$B我们要想办法与上面建立联系，可在那之前，我想先跟那些纳迦“联系”一下。那些倒下的兄弟不能白死。"
D.Strings[17626]="请帮帮我，要是这群懒虫能有一个叫得动，我就会让他回去工作，再把其它人打得鼻青脸肿！$B$B我们在这儿有工作要做！"
D.Strings[17627]="这里有令人惊叹的材料。任何工程材料和替换件都能找到代用品。一切皆有可能！"
D.Strings[17628]="那盒子是在自己移动吗？还是我发疯了？赶快，去个人检查一下！"
D.Strings[17629]="这地方让我们比先前更加暴露了，$r。$b$b我们必须尽快找到安全的藏身处！"
D.Strings[17630]="我们必须集结你的同伴，探明纳迦在这里的真正目的。$b$b不过首先，我们得先找个更为安全的地方。"
D.Strings[17631]="我觉得我们对纳迦在此地出现的原因了解得远远不够。$b$b我以前从没见过他们像现在这么富于组织性和纪律性。"
D.Strings[17632]="村庄……消失。家庭消失。纳迦……带走……一切。"
D.Strings[17633]="这对我们所有人来说都很困难，可我们正在勉强支撑。$B$B你要做的就是挽起袖子，做你该做的事。"
D.Strings[17634]="<这名士兵痛苦的呻吟声在水中变得有些扭曲。>"
D.Strings[17635]="<这名受伤的士兵似乎还有呼吸。谢天谢地，他的魔法气泡还没掉。>"
D.Strings[17636]="<这名受伤的士兵似乎还有呼吸。谢天谢地，她的魔法气泡还没掉。>"
D.Strings[17637]="<这名士兵的体侧有一道深得可怕的伤口。>"
D.Strings[17638]="<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了他的命。>"
D.Strings[17639]="<看样子，这名士兵靠装死摆脱了纳迦的怀疑。这个举动大概救了她的命。>"
D.Strings[17640]="第三舰队被诅咒的魂灵将永世游荡在这片海岸上，$r。帕雷斯之眼掌控着我们的生命，并永远将我们囚禁在泥沼之中。"
D.Strings[17641]="嘘，小声点儿！我们正躲着呢。"
D.Strings[17642]="奥克莉拉不喜欢让我们这些非兽人进入镇子，但那并不妨碍她安排我们去工作。不管怎样……我倒宁可待在这外面。"
D.Strings[17643]="你已进入兽人的地盘。你需要什么吗，$r？"
D.Strings[17644]="我需要你按我说的去做，$r。如果我们退却，我们就很可能落入拉瑟莱克的股掌之中。"
D.Strings[17645]="我们正在对付的，看来要比大地之环预料到的任何东西都要大得多。"
D.Strings[17646]="在这个洞穴之外集结了大批纳迦。$b$b我们能神不知鬼不觉地到达这个地方，可真是幸运。"
D.Strings[17647]="我们的士兵……他们都已沦为俘虏。"
D.Strings[17648]="我们许多人都试图逃离纳迦。$b$b我是唯一成功的幸运儿……"
D.Strings[17649]="我不知道原因，但那些怪物在想方设法让我们的人活下来……"
D.Strings[17650]="好！拿去护符，可$r要帮助岩池鱼人。"
D.Strings[17651]="我们生活在同一片海浪中，吞吐着同一片海水，膜拜着同一位神灵。那究竟是为什么——纳迦要与我们反目为敌？"
D.Strings[17652]="戈德林是狼神先祖，在部落语中又被称作“洛戈什”。他有着传奇般的坚韧战力。$B$B为纪念他而建造的圣殿就位于世界之树西边的盆地那里，但它的看守人在那次攻击之后就变得杳无声息。我担心最坏的事情已经发生了。$B$B在我们继续前进之前，你必须确保圣殿安全无虞，查明狼神先祖的下落，击退他的敌人。"
D.Strings[17653]="艾森娜是自然之魂，也是我在这个世界和梦境中永恒的同伴。她位于海加尔西部的圣殿，就在暮光入侵的最前线，此刻应该已被战火席卷。$B$B$n，如果没有艾森娜的帮助，我们永远都别想重建海加尔山。确保她的圣殿免受大火的侵袭，并救救附近那些被烈焰威胁的生灵吧。要是我们做不到，就将失去这整座山。"
D.Strings[17654]="艾维娜是天穹的失落卫士，一万年前在与恶魔大军的对抗中不幸消亡的鸟之女神。为纪念她而建造的圣殿就在西南边，在一棵参天大树的虬枝之中。$B$B猛禽德鲁伊把那圣殿作为他们的大本营，而我们需要他们的支援。你必须前去帮助他们。同时也帮助艾维娜，愿她能找到回归这世界的通途……"
D.Strings[17655]="我已经派大德鲁伊哈缪尔·符文图腾前往被烧得面目全非的玛洛恩庇护所。他在前线的后方——被称作烈焰之痕的焦枯之地。他正在寻找让我们挽回损失的办法，并调查龟神托尔托拉的下落。$B$B但在你前去帮他之前，你必须先确保西边艾森娜神殿的安全，还要保护那里的生灵免受烈焰的侵袭。否则我们将失去一切！先集中精力解决艾森娜林地的问题，然后他们会在适当的时候送你去大德鲁伊那里。"
D.Strings[17656]="也许这里并不怎么舒适宜人，可这里仍旧是卡兹莫丹，所以它还是我们的家。"
D.Strings[17657]="我们的城镇沉没在被诅咒的洋底，我们的要塞已被黑铁叛徒侵占，而我也身受重伤，对这种局面束手无策。$B$B所以欢迎来到米奈希尔港！"
D.Strings[17658]="伊瑟拉派我来这里与艾森娜的荒野灵魂取得联系。$B$B可这古老的灵魂仍在保持沉默。"
D.Strings[17659]="不是我们将战火引向部落，而是部落将战火引向我们。"
D.Strings[17660]="正当我以为我们终于能摆脱那些迅猛龙，喘口气时，这里的情况却变得更糟。$B$B可是抱怨是没用的。我们得像个真正的矮人一样去面对！"
D.Strings[17661]="别提那些迅猛龙。提也别提。"
D.Strings[17662]="欢迎来到远离家乡的家园，$c。希望我们能为您献上无比殷勤的款待。"
D.Strings[17663]="在谷地里要多加小心，$n。四周到处都是敌人！"
D.Strings[17664]="想要做买卖吗？"
D.Strings[17665]="东西都弄坏了，嗯？"
D.Strings[17666]="列兵霍金纳多·伯纳德，暴风城步兵团第十三编队……$g阁下:女士;。"
D.Strings[17667]="我们发现了他们……部落的船队……然后突然就不见了，有触手伸出来一把抓住了我们的船……把它折成了两截！$b$b幸存者们……我们一落水就立刻被纳迦抓住。$b$b那是差不多一星期以前的事了。"
D.Strings[17668]="真是奇怪……从没想过纳迦竟然会设法让我们活下来。$b$b他们弄出这些像珍珠一样的泡泡……一人一个……让我们能够呼吸。$b$b他们每天都会送走一些囚犯……不知道去往哪里。$b$b再也没见过他们……"
D.Strings[17669]="另一名士兵设法获得了自由，打碎了我们的珍珠……释放了我们。$b$b有人游向了水面……有人看到这座洞穴，并向它游来。$b$b我是唯一一个活下来的……"
D.Strings[17670]="啊！$r！后退！"
D.Strings[17671]="说不好……$b$b他们每天都会带来新的士兵。部落和联盟的都有。$b$b有些在来的当天就会被拖走……其它像我一样的，会在那儿待上一个星期……也许更久。"
D.Strings[17672]="试都别试，$r。$b$b趁还来得及，赶快离开这儿……$b$b有太多人都将……必死无疑……"
D.Strings[17673]="城市已被攻陷。艾萨尔向你发出了胜利的恭贺。你今天为自己赢得了足够的尊重。"
D.Strings[17674]="我没想到能这么快地夺取这座城市。看来我们将有大把时间来准备入侵。"
D.Strings[17675]="召唤咒语已经就绪，可我们是依靠纳萨林坩埚来汲取法术能量。必须找回这件圣物。"
D.Strings[17676]="马迪亚斯·肖尔亲自派我来协助暗夜精灵。"
D.Strings[17677]="大灾变在丹莫罗引起了混乱。穴居人以我们前所未见的规模成群结队地迁移到地表，把我们的宿敌霜鬃巨魔赶到了离我们居住地更近的地方。$B$B铁炉堡已经派出我的巡山小队来协助解决这一问题。"
D.Strings[17678]="从过往的灰烬中生出新的生命……这是艾森娜的馈赠。$B$B如果没有你，这奇迹决不会出现。"
D.Strings[17679]="<这个上古生物盯着你。那双眼睛比你的头还要大。望着它们就好象坠入了一片深蓝的海洋。>"
D.Strings[17680]="等我们完成之后，那些霜鬃巨魔会把我们看作是比穴居人更可怕的对手。他们只能离开，别无选择。"
D.Strings[17681]="哇——我这是在哪儿？你是和他们一伙的吗？"
D.Strings[17682]="都结束了没有？"
D.Strings[17683]="必须……回到……铁木那里！"
D.Strings[17684]="你不是暮光之锤的人。外面发生什么事了？"
D.Strings[17685]="我烧伤了。非常严重。"
D.Strings[17686]="暮光之锤……我听见他们尖叫窜逃……我们是在发动反攻吗？"
D.Strings[17687]="城镇……被毁了！我们无法阻止他们。"
D.Strings[17688]="他们打开了通往火焰之地的传送门……告诉我希望还在！"
D.Strings[17689]="这个生灵……她相当年迈且非常睿智。要是我们能与奈瑟匹拉交谈的话，我们就能了解很多与瓦丝琪尔和纳迦有关的事。"
D.Strings[17690]="这间破旧的旅馆从外面看已经惨不忍睹，不过倒是个理想的据点。"
D.Strings[17691]="一股黑暗力量在席卷石爪峰。"
D.Strings[17692]="我不明白这地方的起源与用途。$B$B这些通道是行军用的，这没错，可这里同样遍布烧焦与饱受折磨的尸体，有些尸体已经部分被吞食，而大部分则只是被打得面目全非。$B$B尽管我们是在火焰之地，我却感觉像是已经跨进了地狱。"
D.Strings[17693]="我已经试着向沙尔斯巴里解释过很多次了——我没办法把他变成一只狼人。可他总是充耳不闻，反而让自己坚信，只要能获得我的信任，我就会和他分享秘密。$B$B侏儒可真是奇怪的家伙。"
D.Strings[17694]="戈德林的坚韧战力充满着传奇色彩。$B$B各地的战士都纷纷到访这座圣殿，祈求能像戈德林那样勇猛卓绝。"
D.Strings[17695]="$r，我这一辈子都没见过这样的东西……"
D.Strings[17696]="我们的战备不足以在此交战。$b$b必须做好准备才行……"
D.Strings[17697]="他从不放弃——铁木队长——他说要让他们为其所玷污的每一寸土地付出代价。他很可能就在那下面，也许还活着！"
D.Strings[17698]="%s大口喘息着，在寒风中颤抖着。"
D.Strings[17699]="还不够好……"
D.Strings[17700]="这些水下的资源真是让人无话可说。任何工程材料和替换件都能找到代用品。给我几天时间，我就能用水藻和贝壳做出一辆水下改装跑车！"
D.Strings[17701]="这地方跟废墟相比没那么凉爽，如果要我说的话，这儿的空气也有些太过潮湿，不过确实给我一种舒服的、回到家里的感觉。$B$B你不这么认为吗？"
D.Strings[17702]="我不知道你怎么想，可我真的很想念下面废墟里那些取之不尽的原料！$B$B就凭我们在这洞里找到的少得可怜的材料，我甚至都不知道能不能造出一颗哑弹！"
D.Strings[17703]="纳迦。$B$B<维索恩充满厌恶地朝地上吐了口唾沫。>$B$B他们可真蠢，居然妄想能用鞭子把兽人训得任其差遣。我们要让他们后悔，没把握住机会杀了我们，让他们一个个全都后悔。"
D.Strings[17704]="欢迎你，朋友。\n\n虽然我们这儿没什么现成的补给品，可我一定会尽我所能为你提供帮助。"
D.Strings[17705]="我的营救计划非常完美。简直无懈可击。只有一个地精可能阻止我成功。一个长鳍的地精。这想法可真可怕。"
D.Strings[17706]="从野性生灵在艾泽拉斯出现的那一刻起，这个世界上就有了戈德林的身影。他就像是猎手之魂，是野兽嗅到食物或感受到幼子身处险境时迸发的动物本能。他出现时是一头身形巨大的白狼，凶猛而诡诈。$B$B他闻名于各种文化。兽人甚至给他起了个特有的名字——“洛戈什”。$B$B一万年前，当恶魔首次入侵艾泽拉斯时，戈德林与其它远古半神们比肩拼死抵抗。"
D.Strings[17707]="就是那段最黑暗的日子，为戈德林坚忍的作战风格笼上了一层传奇色彩。正当别人在那些恶魔军团面前战栗时，他们的数量却只会激发出狼神先祖更强大的战技。他会冲进敌阵，尖牙沾满敌人肮脏的血液，他的利爪会一下刺穿数十个敌人……$B$B据说，他在暗夜精灵撤离埃雷萨拉斯——现在被我们叫做厄运之槌的古城时，在后方担负着掩护的重任。$B$B他死了吗？我不知道这凶猛的野兽之魂是否会真的死去，$n。"
D.Strings[17708]="狼魂先祖的坚忍战力充满传奇色彩。$B$B以他为榜样吧，$c，胜利一定就在前方等着你。"
D.Strings[17709]="洛戈什是猎手之魂，是野兽嗅到食物或感受到幼子身处险境时迸发的动物本能。他始终与我们同在，与部落血脉相连，永存于我们的天性与血液之中。$B$B他以多种形态出现在我们的世界与此地。在艾泽拉斯，人们说他是一只巨大的白狼，凶猛又诡诈。暗夜精灵叫他“戈德林”。$B$B他们讲述着一场发生在一万年前的传奇之战——洛戈什击败了恶魔军团。你想要了解一下吗？"
D.Strings[17710]="一万年前，恶魔首次侵入了我们的世界，就像他们夺取兽人的家园德拉诺一样。他们鱼贯而入，将战火蔓延到了各个角落。艾泽拉斯伟大的远古半神们帮助凡间种族拼死抵抗。$B$B洛戈什的坚忍战力便是在这段最黑暗的日子里成为了传奇。他对恶魔毫无畏惧。他会冲进敌阵，尖牙沾满敌人肮脏的血液，他的利爪会一下刺穿数十个敌人……$B$B他不屈于恶魔的勇武精神激励着我们每一个人。我们都能从他身上汲取能量。"
D.Strings[17711]="高贵的艾维娜——百鸟之神！艾泽拉斯的所有空中生灵曾经都对她效忠，尤其是猛禽德鲁伊。正是由于她的恩赐，我们才获得了变换形态和翱翔天空的能力。$B$B艾维娜集美丽与可怖于一身，就像那些被她甄选而打造成的强大猛禽一样。她曾住在耸入云天的母亲之树加尼尔的精神圣域，而每当她在艾泽拉斯出现时，她的形象总是一位长着双翼的女神。"
D.Strings[17712]="<楚伦娜的脸色暗淡了下来。>$B$B一万年前，恶魔在上古战争期间闯入艾泽拉斯。艾维娜召集她的子嗣集聚天穹，在前线阻击恶魔军团。$B$B愤怒中的她所向披靡，千百个恶魔被她的利爪撕裂。可她最终还是陷入了末日守卫的包围，他们尖利的长矛从她身体两侧齐齐刺入……$B$B据说她的鲜血也仿佛有意志一般，向恶魔发起凶猛的攻击，烧灼他们的血肉，就像是她自己从天而降，把他们一举击溃。"
D.Strings[17713]="艾维娜在那天倒在了战场上，但凡间种族和其余的上古诸神最终还是取得了胜利。首批德鲁伊在遍地尸殍中找到了她的遗体，并将她埋葬在了这里——埋在了这高山之巅。$B$B她就永眠在这圣殿之外，在圣石圈起的圆环之中。$B$B人们用加尼尔的一颗种子种出了世界之树——这也是那圣域唯一的留存，否则整个圣域都会同艾维娜一同消亡。"
D.Strings[17714]="我们凡间种族对艾森娜知之甚少，她是在茂密的野性丛林中潜行的荒野之魂。她是森林之灵，是它跃动的心脉，是粉碎岩石、吞噬遗迹、将茂密的丛林用神秘与恐惧灌注的生命能量之源。艾森娜是生命之网的中心。$B$B暗夜精灵在卡利姆多各地都为她修建了圣殿。人们崇敬她……可并不了解她。$B$B你觉得要是我们能对这避世而强大的远古半神有少许了解，那会怎么样呢？"
D.Strings[17715]="啊，托尔托拉！它总是被误解，总是被低估。那些在陆地和海洋之间轻松穿行的生物都会将托尔托拉当作神祗和祖先来崇拜。$B$B一万年以前，燃烧军团入侵艾泽拉斯。托尔托拉与塞纳留斯和其他凡间种族共赴战场。$B$B当恶魔大军对守卫者们的阵线发动冲击的时候，他们拿托尔托拉毫无办法。一开始，他们对它并不在意。但托尔托拉可怕的重量和致命的双颚在转瞬间就杀死了成百上千的恶魔……"
D.Strings[17716]="托尔托拉从未倒下。尽管最后被那些强大的军团末日守卫团团围住，可他们却对他那坚硬的皮肤和刀枪不入的龟壳束手无策。喔，他们当时别提有多暴怒了！在凡间种族得以重整兵力来关闭传送门、终结入侵之前，托尔托拉守住了阵地，并掩护他们完成了决定性的撤退。$B$B据说在战斗结束后，有人发现托尔托拉被压在堆成山的恶魔尸体下面。他抖抖身上的尸体，从斑驳血污里伸出了头。然后安静地、慢慢地……问我们打赢了没。$B$B<哈缪尔把一只手按在了肚子上，发出了发自肺腑、无法抑制的狂笑。>"
D.Strings[17717]="欢迎你，$c！"
D.Strings[17718]="大地观察者不会容许派系争斗威胁到大地之环在此地的工作。\n\n任何打破和平的人，都将面临……严厉的处罚。"
D.Strings[17719]="蛮锤总是对萨满巫术青睐有加，这没错，可让我们待在海底下，作为大地之环的一员？\n\n要是在一年前，几大杯啤酒就能让我相信这个事实。"
D.Strings[17720]="这些土地是黑暗女王征战的前线，$n。看看它们吧；过不了多久，这些都将落入被遗忘者的掌控之中。"
D.Strings[17721]="黑暗女王在注视着你……"
D.Strings[17722]="在这种情况下要我怎么保持旅店的清洁？你会负责处理这俾格米的麻烦吗？"
D.Strings[17723]="地精僵尸？！接下来是什么……火山喷发？"
D.Strings[17724]="怎么，女武士？"
D.Strings[17725]="女武士，你的出现使我倍感荣幸。现在可以开始仪式了吗？"
D.Strings[17726]="啊！嗯……你好啊。我在这儿只是在检查这个壳。继续！这儿没什么好看的！"
D.Strings[17727]="我看来遇到了……漂浮的麻烦。"
D.Strings[17728]="我也不确定。可能是因为我骨头太轻，或是肺活量异于常人。也许只是因为我中午吃的那块奶酪。$b$b不管怎样，要不是有这壳在，我早就像火箭一样窜出水面了。"
D.Strings[17729]="哎，家族遗传问题。恐怕掘歌家的人总是被浮力问题困扰。"
D.Strings[17730]="我用手划啊划啊，$g小伙子:小姑娘;……精疲力竭地划。我都不知道究竟有多少海水直接灌进了我的鼻子。$b$b不过你应该看见我用脚和牙齿力战大螃蟹的精彩场面了！那可真是荣耀啊，真的。"
D.Strings[17731]="我记得当我还是个小不点儿的时候……别的男孩子都能一猛子扎到洛克莫丹湖底，拾上来各种各样的海胆和贝壳。奥斯卡和我却只能趴在湖面上，两腿乱蹬，分享不到半点儿乐趣。"
D.Strings[17732]="我都数不清究竟有多少次，远远看见水底有金光闪闪的矿脉，透过水面折射出诱人的光芒。我却只能拿着矿锄两手空空地游走，眼睁睁地看着该死的兽人和血精灵轻而易举的潜入水底，大摇大摆的携矿而去。"
D.Strings[17733]="你根本无法想象像这样被困在瓦丝琪尔是什么感觉！你知道有多少鱼把我当成海草，咬我的脚趾头，在我的护甲里钻来钻去吗？$b$b光是挠痒痒就能把一个矮人逼疯！"
D.Strings[17734]="我知道你没兴趣听我抱怨这些。不要紧。$b$b但别忘了你有多幸运——“深谙水性”还能“向着一个方向游泳而不是只能往上浮”。"
D.Strings[17735]="痛肠可真了不起。痛肠是在这新地方头一个打碎弱小人类的英雄。$B$B痛肠可真高兴。"
D.Strings[17736]="希尔瓦娜斯的胜利！这些土地将是我们的。"
D.Strings[17737]="不找到她，我就哪儿都不去！"
D.Strings[17738]="谢谢你为我带回了狼。"
D.Strings[17739]="有人正在用这些烧杯和炼金工具进行各种潜水艇燃料的实验。"
D.Strings[17740]="我们的人民被人类当作囚犯、当作奴隶，就关在这座营地里。我被锁在这些笼子里面；我看到我的兄弟们被关在这儿，吊在这些绞架上。$B$B我看见我们所有人的领袖——奥格瑞姆·毁灭之锤，被利刃刺穿背部。他的血把我们脚下的土地都染成了深色。$B$B现在再看看我们。落锤镇——我们世代的家园，我们在这里失去了一切，然后再用我们自己的双手夺回来。"
D.Strings[17741]="你面前放着几种油料样本，旁边还有一个空烧杯。烧杯看起来能装下大约五种样本。$b$b你想先选哪种油料？"
D.Strings[17742]="你接下来想要选哪种油料？"
D.Strings[17743]="你现在有两份油料样本了。接下来想要选哪种？"
D.Strings[17744]="你现在有三份样本了。接下来想要选哪种？"
D.Strings[17745]="你现在选好四份样本了，只能再选一份。选哪种呢？"
D.Strings[17746]="你已经把五份样本都选好了。"
D.Strings[17747]="你可以用这些烧杯和炼金工具进行各种潜水艇燃料的实验。"
D.Strings[17748]="你发现了一种新型生物燃料！快把它拿给工程师“洗衣桶”测试一下。"
D.Strings[17749]="你发现了一种新型生物燃料！快把它拿给菲亚斯科·尖笑测试一下。"
D.Strings[17750]="我们坚持到现在已经消灭了许多纳迦，可他们还在前仆后继地冲过来。到底要怎么做才能逃出这该死的洞穴？"
D.Strings[17751]="我不在乎自己是否会死在这儿，$n。我要让这些纳迦为我们每一个被杀死或奴役的同胞付出代价！$b$b就让其它人去烦恼该如何逃生吧。我要考虑的是该怎么让这些魔鬼受到惩罚。"
D.Strings[17752]="他们为什么这么做？为了珠宝？为了战争？上古之神奈瑟匹拉远比纳迦了解得要强大得多。要是奈瑟匹拉能为他们所用……那他们所能造成的伤害将达到令人发指的程度。"
D.Strings[17753]="我不喜欢这里的感觉，$n。到处都是纳迦巫师和奴役者……我在这洞里唯一能感受到的就是痛苦。古老的生命在试图呼喊，可我却说不出话来。"
D.Strings[17754]="我们需要你的帮助，$c。我们已经拼尽了全力，但纳迦的攻势丝毫没有减弱。"
D.Strings[17755]="要是你的双手沾上了纳迦的鲜血，那你就是我的盟友。$b$b很久以前，我发誓决不再做任何人的奴隶，在那以后我一直信守对自己的承诺，直到落在埃卓凯丝的手里。现在我已经抑制不住胸中的怒火。鲜血是我唯一的渴望……我可以不吃不睡，甚至可以不要胜利……只要鲜血。"
D.Strings[17756]="<拉葛雷克的声音在你脑中回荡。>$B$B我已经要……死了。你必须帮忙……阻止……暮光之锤。$B$B他们汲取……我的能量……来创造……他们的升腾者。他们在……对抗耐普图隆的……战争中……将是重大的……威胁。"
D.Strings[17757]="元素在愤怒的咆哮着。这与纳迦的到来一定不会是巧合。他们一定在等待着什么。"
D.Strings[17758]="啊，就算没有这些新麻烦不断的冒出来，维持这儿的秩序就已经够让人头痛的了！希望你有好消息，$n……"
D.Strings[17759]="见过我所见过的那些，做过我所做过的那些，而现在还能呼吸……我真是个幸运的侏儒。"
D.Strings[17760]="诺莫瑞根行动取得了成功。当然，那个卑鄙的瑟玛普拉格使出了让人出乎意料的一招，但我们还是把他赶跑了！诺莫瑞根很快就会被肃清，重新回到我们的手中，这只是时间问题！"
D.Strings[17761]="为国王料理膳食是份荣耀，可不是工作。你有时间帮我跑跑腿儿吗？"
D.Strings[17762]="守望堡有时真是闷得够呛。有时一个矮人需要的只是一杯啤酒，让她的脑袋换换气儿！"
D.Strings[17763]="我只是稍事休息。永恒地坚守并不像听上去那么容易，$r。"
D.Strings[17764]="对不起，$c，我帮不了你。你得去找$c训练师。"
D.Strings[17765]="很抱歉，我不能对你进行训练。你得去找更熟悉你技能的训练师。"
D.Strings[17766]="就算我们要死，也要带着消灭夙敌的荣耀！"
D.Strings[17767]="在我们加入最终战斗之前，我们必须对发生在对面那个上古生灵体内的事情做个了断。否则，我们将毫无胜算。$B$B尽全力去帮埃鲁纳克吧，$n。"
D.Strings[17768]="拉葛雷克是位远古之神，就在沟壑的另一侧。他正在受到某种力量的侵扰。$B$B我们必须终结这一切，否则我们谁都活不了！"
D.Strings[17769]="尽管我们拼尽了全力，纳迦还是对裂口发动了攻击！$B$B必须守住水元素位面！"
D.Strings[17770]="在深渊裂口，一场战争正在酝酿。希望与扳钳X2号一起赶来的援军足够抵挡。"
D.Strings[17771]="在我们加入深渊裂口的最终战斗之前，我们必须终结在对面那上古生灵体内所发生的一切。否则，我们都将失败。$B$B尽全力去帮埃鲁纳克吧，$n。"
D.Strings[17772]="要是你问我的话，我认为让那些汤羹和肉汁去充数就够了。$B$B趁我们还没变成烤面包之前，应该纵身从这儿逃出去。$B$B你明白我的意思吗，宝贝儿？"
D.Strings[17773]="我们两个私下说，宝贝儿，我的身高不适合执行这种任务。再坚持一个月我就要离开了。$B$B我已经死过一次。没必要再来一回。"
D.Strings[17774]="要与第一个上古生物奈瑟匹拉打交道已经够难了。而在我们对面的那个，叫拉葛雷克的，就快要死了。$B$B我能感觉到它痛苦的哀号。有什么东西正在偷取它的生命能量。我不知道那些被偷走的生命能量将被用于什么目的。"
D.Strings[17775]="我希望能与你在即将打响的战争中并肩作战，但埃鲁纳克要我留下。$B$B祝你好运，$n。"
D.Strings[17776]="这深渊可真是噩梦。$B$B但和即将加入的下方裂口里的战斗比起来，简直就是小巫见大巫。"
D.Strings[17777]="我什么都不会告诉你！"
D.Strings[17778]="滚开。"
D.Strings[17779]="喔，是大英雄来了。我得救了！对，是的……"
D.Strings[17780]="你想聊聊？给钱。"
D.Strings[17781]="我们召集起了一支强大的军队，击败了瑟玛普拉格的爪牙，一路杀回这座城市。但瑟玛普拉格这个篡位者还留了一招……"
D.Strings[17782]="我们不得不撤退。瑟玛普拉格则继续躲在地下的辐射尘中，派遣他的部下碎轮来到地面上作恶。"
D.Strings[17783]="这片土地在饱受煎熬……它在乞求怜悯，$r，它在乞求怜悯。"
D.Strings[17784]="喂饱 一支部落大军可不是件容易的事。我有许多活儿要干，你有时间帮帮我吗？"
D.Strings[17785]="我们必须不惜一切代价将世界之柱碎片重新拼合在一起。$B$B但首先，我们得先找齐它们。"
D.Strings[17786]="我这辈子都没离开过西部荒野，$g兄弟:姐妹;。我还记得西部荒野曾是荆棘谷这一侧最富生机的地方。那些日子已经一去不复返了。$B$B尽管我们摆脱了迪菲亚制造的麻烦，但他们恐怖统治的影响至今犹存。更糟糕的是，我们现在正面临有史以来最严重的经济危机。由于我们将所有的积蓄都拿去对付天灾军团，所以那些不在军中任职的普通百姓全都陷入失业与最终无家可归的境地。$B$B你猜这些人最后怎么办了？"
D.Strings[17787]="没错，她是这么说的：“只是一次前往废土的简单旅程，毫无压力。”"
D.Strings[17788]="正在初始化清除……"
D.Strings[17789]="就算是在这儿——在这海浪与暖日的环抱下，我都能感觉到在这些土地上涌动的黑暗力量。$B$B这可真有趣儿，你不觉得吗？"
D.Strings[17790]="我们自豪地宣称，我们是效忠于部落的森林巨魔最后的部族。$B$B总有一天，我们将战胜其它部族，还有那些矮人，辛特兰将属于我们。"
D.Strings[17791]="这里的巨魔很能接受像我这样的人。毕竟，在被遗忘者还没出现时，他们就已经与死者交流了几个世纪。$B$B这是个很好的契机。"
D.Strings[17792]="在我小时候，我的家人不许我研习萨满巫术。任性而愚蠢的我竟然从他们身边逃离，一个人学习了起来。有一天当我回到故乡，却发现父母都已不在。我的家园也已被毁。没人知道是谁下的手。\n\n我耗尽毕生的精力，想要延展我萨满的视野来回望过去——查明在我家人身上究竟发生过什么，谁该对此负责。我一路走来历尽艰辛。现在我已学会将意念集中在于不久前发生的重大事件上，可要想获知发生在那么久之前的事，我还有很长的路要走。"
D.Strings[17793]="辛萨罗一定属于我们，朋友。邪枝部族只不过是软弱而令人生厌的背叛者，他们不配得到神灵的眷顾。"
D.Strings[17794]="诺森德的战火给我们所有人都造成了损失，$n。尽管我们在寒冰荒野上取得了胜利，我们自己的土地却陷入了混乱。"
D.Strings[17795]="谢谢你把我从这儿弄出来！"
D.Strings[17796]="我再也不想闻到穴居人身上几百年没洗的臭味了！"
D.Strings[17797]="谢谢你。现在，让我们把这洞穴炸烂吧！"
D.Strings[17798]="你想象不出我见到你有多高兴！"
D.Strings[17799]="终于见到个不是穴居人的人！"
D.Strings[17800]="我自由了！我真的自由了！"
D.Strings[17801]="去做准备吧，$n，但动作要快！"
D.Strings[17802]="别去打扰这年老的龙喉兽人喝酒了，$c。$B$B我曾经对抗过足以把你脊椎扭弯的怪物，在湿地的沼泽和外域的废墟间看着自己的人民惨遭屠戮。$B$B茫然。无措。"
D.Strings[17803]="这是什么，$c？你知道我叫什么？$B$B那你可知道我的名气？$B$B我是龙喉部族的火牙。我曾统领军团，驭龙驰骋，见证过格瑞姆巴托的分崩离析……$B$B该死的暮光之锤，还有他们屁股后面那群食人魔哈巴狗。看看我现在的落魄样。只能絮叨着与廉价的烈酒为伴。"
D.Strings[17804]="这么说来，暮光之锤想要除掉我？恬不知耻的垃圾！$B$B我一定会帮助你的，$c。你说你需要一张地图？"
D.Strings[17805]="不管在别处正在发生着什么，铁炉堡没有忘记这片土地，也没有忘记卡兹莫丹的任何角落！"
D.Strings[17806]="你怎么还待在这儿，$c？$B$B你不是应该已经抵达暮光高地，让那该死的教派彻底毁灭吗？"
D.Strings[17807]="麦氏移山人有限公司杰萨普·麦格雷，为您效劳。"
D.Strings[17808]="要是您想要搬山，找我就对了。我还能为您造座山出来。"
D.Strings[17809]="这不是我所干过最重要的工作，连边儿都沾不上。大灾变一定是我们所经历过最棒的事了！"
D.Strings[17810]="已发现光学感应故障！正在关闭中……"
D.Strings[17811]="嘿，$c！$B$B有兴趣签几份赚钱的合约吗？我会分给你十分之一！百分之一的十分之一！"
D.Strings[17812]="到底是怎么回事，$c？$B$B码头附近有传言说，你最近一直在我的建筑工地附近游荡……"
D.Strings[17813]="关于此次攻击没什么混乱的。元素和巨人们有组织地前来对付我们。看来我们在不经意间引起了石母本人——塞拉赞恩的愤怒。"
D.Strings[17814]="祭司了解很多与祖尔格拉布有关的事。$b$b祭司认为你需要她的帮助。"
D.Strings[17815]="碎轮的失败将向他的主人瑟玛普拉格发出强大的信息。诺莫瑞根的侏儒是不可被阻止的！"
D.Strings[17816]="我已经准备好发起攻击了。"
D.Strings[17817]="机械师瑟玛普拉格拒绝承认他的失败已经近在眼前！现在，他又派出了拉兹诺·碎轮来阻止我们重新建设我们亲爱的诺莫瑞根！"
D.Strings[17818]="但是我们勇敢的朋友$n已经挫败了他们的邪恶计划。铁炉堡的矮人也在与我们并肩作战！"
D.Strings[17819]="让我们击败他，让他爬着回去见他的主子！"
D.Strings[17820]="你！怎么可能逃过我的哨兵机器人？这不可能！"
D.Strings[17821]="没有关系！我会带领护卫迅速地干掉你。准备战斗！"
D.Strings[17822]="我们成功了！我们胜利了！"
D.Strings[17823]="碎轮被打败了，瑟玛普拉格一定正在他的机械坦克里发抖，下一个完蛋的就是你，瑟玛普拉格，下一个就是你！"
D.Strings[17824]="这就是你招惹强大铁炉堡和诺莫瑞根的下场！"
D.Strings[17825]="对，让我们给这脑筋错乱的侏儒上一课！"
D.Strings[17826]="将炉石绑在此处。"
D.Strings[17827]="你永远也不可能战胜真正的诺莫瑞根之子！"
D.Strings[17828]="你可真勇敢，居然想要逃走，年轻的奥根阿卡。$b$b在你继续之前，让我教你如何用牙齿咬破那些巨魔的网。"
D.Strings[17829]="你要离开迅猛龙巢穴了吗？我奉命守卫这岗哨并阻止逃逸，不过……我想我明白你为什么会想要离开。$b$b好吧。你可以通过这里，但首先，我有个要求。$b$b巨魔们经常会携带好多包迅猛龙爱吃的食物，而我已经许多天没进过食了。也许你打架毫无胜算，可你身形小巧，应该能趁那些巨魔熟睡时从帐篷里偷点儿吃的出来……"
D.Strings[17830]="能走到这一步可真令人印象深刻啊，奥根阿卡。你可真是只天赋异禀的年轻迅猛龙……可最难通过的考验还在后面呢。$b$b巨魔们就在前方的桥附近巡视，他们的注意力很难被分散。可要是你能在他们的必经之路上放块头骨，也许能把他们绊个跟头……"
D.Strings[17831]="梅卡托克——大炮！"
D.Strings[17832]="梅卡托克——激光！"
D.Strings[17833]="梅卡托克——导弹！"
D.Strings[17834]="梅卡托克——射线！"
D.Strings[17835]="你好，朋友！$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B你看起来底子不错，$c，可我们需要的士兵得更加……久经沙场一些。也许有一天你和我能并肩作战。在那以前，继续加紧训练吧！"
D.Strings[17836]="你好，朋友！很高兴见到诺森德战役的老战友。$B$B酋长命我集结他麾下最精锐的部队攻击暮光高地。$B$B<酋长把你上下打量了一番。>$B$B我们也许需要你的帮助。去奥格瑞玛的酋长那里，看看他有没有任务交给你。"
D.Strings[17837]="一位士兵在这样的城镇里能惹上许多麻烦。$B$B许多麻烦。"
D.Strings[17838]="谢谢你。$b$b作为回报，我会教你如何分散前面那群巨魔的注意力。"
D.Strings[17839]="你想逃走？没问题，可你必须得先了解一些事情。$b$b离那些巨魔远点儿。他们不会杀你，可他们会困住你然后把你带回来。$b$b和你所见到的每只迅猛龙都打个招呼。它们不仅能教你新的技能，还会帮你记住你的进度，让你能更加容易地逃离祖尔格拉布。$b$b你已经学会了急奔技能——用它来脱离险境吧。$b$b喔……还要注意别下水。$b$b祝你好运！"
D.Strings[17840]="你在错误的时间来到了错误的地点，$g小伙子:小姑娘;！"
D.Strings[17841]="$c，欢迎来到格罗姆高。为了避免今后发生问题，我现在要提醒你，我的营地里可容不下懒人。希望像你这样的健康$r能在这里发挥出应有的作用。"
D.Strings[17842]="即使是在这个世界如此偏远的角落里，都不要忘记地狱咆哮的双目在注视着你。"
D.Strings[17843]="荆棘谷的巨魔对我们暗矛部族并不怎么友好。我不怕那些血顶或劈颅，可是……格罗姆高的高墙令我感到安全。"
D.Strings[17844]="也许格罗姆高并非像我想的那么安全。$b$b身为巨魔，不论走到哪里，都要随时小心自己的脖颈被偷袭。"
D.Strings[17845]="<大锅在冒着气泡。>"
D.Strings[17846]="<巨魔自己唱着歌，眼睛看着锅里。他像是受了伤。>"
D.Strings[17847]="在那片丛林里可藏着许多钱，$r。你看见了吗？$b$b不，这钱的样子跟你平时见到的金币或铜币不同。它的外观是迅猛龙的龙皮，还有矿脉，以及古老的巨魔圣物。$b$b好吧，也许矿脉和金币铜币的样子有点儿像。$b$b不过反正你明白我的意思了，对吧？"
D.Strings[17848]="伟大的拉斯塔哈为你送来了问候，部落的成员。"
D.Strings[17849]="你必须飞往巨石之炉，帮我的人民击败石头穴居人，救出我的父亲。$B$B等我与唤地者谈过之后就会去那里找你。$B$B别让他死了，$n，否则我会亲手把你埋进地里！"
D.Strings[17850]="你去过丛林吗，$r？$b$b那可真是个好地方。"
D.Strings[17851]="荆棘谷，$g伙计:宝贝儿;。就在那儿！"
D.Strings[17852]="啊，要是再回到荆棘谷。那些发出尖啸的迅猛龙，巨魔间的战争，目力所及处各式各样的丛林生物，就等着人们的捕杀……$b$b<博特叹了口气。>"
D.Strings[17853]="我的机器人就要大功告成了。"
D.Strings[17854]="终于，完成了。"
D.Strings[17855]="起来吧，我的……我该叫你什么好呢？叫你“多功能机器人”怎么样？起来吧，我的多功能机器人！"
D.Strings[17856]="呃……看来还需要略做调整……"
D.Strings[17857]="难道你又带了一队人来，会吗？我们这儿已经没有人手了。"
D.Strings[17858]="暮光教派中存在着对我们具有严重威胁的法术。$B$B我们恨不得马上让他们滚出我们的家园。$B$B我们被分开了，所以我们不能这么做。$B$B于是我在观望着……$B$B等待着……"
D.Strings[17859]="准备作战！我们已经对邪枝部族忍无可忍！"
D.Strings[17860]="我们必须终结渗入灰谷的堕落之息。"
D.Strings[17861]="我们不能再任由我们的敌人——瑟玛普拉格，继续对诺莫瑞根的其余地区施行统治了。"
D.Strings[17862]="他已经命部下——拉奇诺·碎轮来让我们疲于防御。辛克尔斯，有什么关于拉奇诺和他手下的最新情报吗？"
D.Strings[17863]="我们的侦察兵很难获知碎轮的计划。"
D.Strings[17864]="据我们所知，碎轮正在使用一种先进的步行坦克原型，而他手下那些被辐射的侏儒们正在破旧的兵工厂里奋力修复更多同类坦克。"
D.Strings[17865]="若想单凭我们的力量解决简直太难了。我已经送信到矮人主城铁炉堡，请求他们的支援。"
D.Strings[17866]="要是你往你的左边看看，就会发现侏儒们已经夺回了诺莫瑞根！我们真是太伟大了！"
D.Strings[17867]="外面也有许多事情正在发生。通往机场的路线打通了，在东边有关于黑铁部族的传闻……噢，我想矮人国王麦格尼最近也有些不太对劲。也许应该去查清楚。"
D.Strings[17868]="我们到了！欢迎来到卡拉诺斯！出去时请小心脚下。"
D.Strings[17869]="有位来自烈酒村的信使今早抵达了这里。矮人们正派出一支巡山人小队来帮我们。"
D.Strings[17870]="当巡山人抵达时，我们必须做好对付碎轮的准备。"
D.Strings[17871]="打败碎轮之后，瑟玛普拉格肯定会立刻启动他的步行坦克。你的下一个目标就是瑟玛普拉格！下一个目标就是！"
D.Strings[17872]="准备好打斗了吗，$g小伙子:小姑娘;？"
D.Strings[17873]="深岩之洲是个平静而节奏缓慢的地方。永远都充满生机，平稳改变，有条不紊。我一度努力与大地融为一体。在很大的程度上，我成功了。$B$B后来，大地的守卫者回来了，身上带着累累伤痕。起初他并没有扰乱平衡。他曾经在这里生活过，我们了解他。直到暮光教派开始和他打交道以后，他才真正开始发生了变化。"
D.Strings[17874]="当大地守护者逐渐恢复的时候，他开始不满足于这里的安静与和平。没过多久，他就驱使岩石巨龙攻击我们。$B$B死亡之翼离开之后，它们一直没有明确的目标。我们能够让它们明白我们的力量，再次将它们送回到大地母神的怀抱中。"
D.Strings[17875]="感恩吧，公民。我推荐你去见卫兵帕克。他就在这座塔的顶上。"
D.Strings[17876]="有人吗……请……把……这块……石头……挪开……"
D.Strings[17877]="疼啊……真是太疼了……"
D.Strings[17878]="请……杀死……我……"
D.Strings[17879]="我……只……想……建好……这座……该死的……桥……"
D.Strings[17880]="把你们的后背靠上去，孩子们！"
D.Strings[17881]="用力！"
D.Strings[17882]="嚯！"
D.Strings[17883]="该死的石头，就是不动！"
D.Strings[17884]="继续用力！"
D.Strings[17885]="我已经拼尽全力了！这东西肯定有一吨重！"
D.Strings[17886]="我们会救你出来的，工头。坚持住！"
D.Strings[17887]="$n，要去岸边？$B$B只要你说一声，我就会为你放下一艘小船。"
D.Strings[17888]="他们怎么敢囚禁我们的国王！$B$B我们要夺回巨石之炉，然后将战线推进到石头穴居人的老窝，在那里彻底粉碎他们！"
D.Strings[17889]="让我们从这里出去，把那些石头穴居人赶回到地底去，$r！"
D.Strings[17890]="我需要你上阵支援我，$n。$B$B你将使战局产生逆转。我们将一举击溃石头穴居人。$B$B我们必须救出岩幔国王！"
D.Strings[17891]="<克莱嘟囔着，冷笑着。>$B$B这个该死的时代。"
D.Strings[17892]="等到仪式完成的时候，玛尔纳就会到来。我的人会帮忙塑造出这个奇异的怪物。"
D.Strings[17893]="死亡之翼的侵入在我们的世界和深岩之洲之间打开了一道裂隙。$B$B重建世界之柱是唯一控制住裂隙的方法。"
D.Strings[17894]="谈判进展得并不顺利，$n。龙喉氏族还不是意志自由的兽人。$B$B不管怎样，我们必须争取他们加入部落！$B$B如果你要返回舰队，就告诉我。"
D.Strings[17895]="去哪里，朋友？"
D.Strings[17896]="我们龙喉氏族经历过太多的磨难……在格瑞姆巴托的失败……那么多强大的战士死在外域……现在，暮光之锤又向我们发动了进攻。$B$B有时我会怀疑，我们是否还能再次强大起来。但像扎伊拉这样的年轻人让我们这些老骨头又有了希望。"
D.Strings[17897]="你需要什么，外乡人？我不应该和你说话的……"
D.Strings[17898]="我可不喜欢坐在这个洞里。真希望我们在等待达纳斯将军回来的时候能好好喝上一杯潘趣酒。"
D.Strings[17899]="嗨，这身红褂子就让我看上去是一件可消耗品吗？"
D.Strings[17900]="欢迎来到鹰巢山，蛮锤部族的家园。$B$B大领主弗斯塔德·蛮锤已经前往铁炉堡，有事情的话可以和我说。"
D.Strings[17901]="这片土地的英灵不会再容忍这种黑暗魔法和邪恶的献祭。$B$B邪枝巨魔必须被赶走！"
D.Strings[17902]="你的脑袋倒是能做成个好袋子！"
D.Strings[17903]="不要浪费时间了！这里还有许多亡灵呢。"
D.Strings[17904]="你是否愿意不惜一切代价来挽救你的王国？"
D.Strings[17905]="我们知道的只是皮毛而已，$n。我可以向你担保。"
D.Strings[17906]="这么多无谓的损失。"
D.Strings[17907]="钓鱼是我家族世代相传的天性。不过你看上去倒像是能帮点儿小忙。替钓鱼者跑跑腿儿怎么样？"
D.Strings[17908]="你一杯！我一杯！愿我们默契永相随。$b$b可要是没了默契……那你就去死吧！我再来一杯。"
D.Strings[17909]="这一定就是海克拜瑞·斯莫特船长提到的那艘救生船。"
D.Strings[17910]="我们来这儿是想要帮忙的，可看来他们对你的好感还没有延及我们。"
D.Strings[17911]="世界闻名的诺格弗格药剂此处有售！$B$B由纯天然材料萃取炼制而成，只在加基森当地装瓶销售！而且口感顶呱呱——这是当然的！"
D.Strings[17912]="我不能和你做交易，$c。这是酋长的命令。"
D.Strings[17913]="我这儿没什么东西可以卖给你。"
D.Strings[17914]="走开，$c！我可不想让执行者看见我在和你做交易……"
D.Strings[17915]="滚开，我不想让酋长发现我在跟部落的人说话。"
D.Strings[17916]="我不会把商品卖给部落。你不满意？那去找酋长吧！"
D.Strings[17917]="莫格霍尔酋长不许我们和部落做生意。$B$B<商人暴怒地朝地上吐了口口水，拒绝再对这话题有任何回应。>"
D.Strings[17918]="我感觉不太好……"
D.Strings[17919]="这地方还不赖，前提是你不过分专注于那“阳光”。"
D.Strings[17920]="猩猩可真是令人着迷的生物。比暗夜精灵要好多了，那些家伙就只会干蠢事……比如在赌场上输个精光，还害自己登上“海狼”马克基雷的黑名单。"
D.Strings[17921]="继续，$r。给我个理由。"
D.Strings[17922]="这儿可是莫格霍尔酋长说了算。别忘了这一点。"
D.Strings[17923]="<执行者的眼中闪着红光。>$B$B我倒希望你们这些可怜的兽人来攻击我们。我很久没畅快地挥洒热血了，$c！"
D.Strings[17924]="那愤怒！那力量！我一生中从未感到如此强壮。$B$B很快，整个龙喉部族都将有同样的感觉。"
D.Strings[17925]="不要自取其辱，$c。$B$B<执行者握住剑柄的手指又紧了紧，就等你先动手了。>"
D.Strings[17926]="莫格霍尔酋长将率领龙喉部族再次崛起！$B$B我们用不着你们这群没用的部落。"
D.Strings[17927]="观众的兴奋，战斗的刺激——你真该亲眼看看！自从厄运之槌竞技场被那群食人魔占领之后，我就被迫在这儿扎营。目击者格林比克斯——哈！目击什么？目击营火？还是那丛灌木？或者是这棵怪里怪气的紫树？\n\n听着，要是你想打上一架的话，斯卡尔正在前往拉瑞斯小亭，拉扎尔正在朝新萨兰纳尔飞去。在血战开始前，别忘了通知我下注！"
D.Strings[17928]="这个石头穴居人与赤红岩床的变数有关。$B$B我在这里感觉到一股奇怪的力量……多加小心。"
D.Strings[17929]="<小母牛正在努力思索该怎么下楼。>"
D.Strings[17930]="<小母牛用大大的、澄澈的黑眼睛望着你。>"
D.Strings[17931]="<小母牛优雅地低下了头，仿佛理解你请求中所包含的重要性与意义。>"
D.Strings[17932]="想要购买什么海盗物品吗？"
D.Strings[17933]="欢迎来到藏宝海湾，$r。"
D.Strings[17934]="看起来不错，但是我认为要是能把它弄皱些就更好了。你知道，要给人一种经历过战斗的感觉。你说呢？"
D.Strings[17935]="我的兄弟们很强壮，但却总是非常被动。$B$B没有运动、没有竞争、没有暴力，就不会产生变化。我们的敌人深谙此道，不管他们是不是完全意识到了这一点。我兄弟们被动的天性使他们在这些新的敌人面前显得脆弱而无力。$B$B别把我算在内。我不惧怕改变。我愿意撕裂大地，挪移群山。我热爱改变。"
D.Strings[17936]="你是来帮龙喉重获自由吗？$B$B去和扎伊拉谈谈——她在协调我们的反抗行动！"
D.Strings[17937]="啊哈！"
D.Strings[17938]="今天是审判日，$c！"
D.Strings[17939]="你是来帮忙对付莫格霍尔的吗？"
D.Strings[17940]="扎伊拉说部落需要援助！我能做些什么？"
D.Strings[17941]="不用给我盔甲。一把刀就够了，告诉我要杀谁。"
D.Strings[17942]="部落来了！是时候发挥领袖的作用了！"
D.Strings[17943]="我会与你并肩作战，$c。你不会后悔帮助我们的！"
D.Strings[17944]="看来今天不是个戒杀兽人的好日子。"
D.Strings[17945]="算我一个，教官！我做好战斗的准备了！"
D.Strings[17946]="今天莫格霍尔的暴行即将终结。"
D.Strings[17947]="没错，$c！革命开始了！"
D.Strings[17948]="$c！扎伊拉说部落为我们准备了武器。有些什么呢？"
D.Strings[17949]="我的另一半走丢了！快帮帮我！"
D.Strings[17950]="镇民正在不断消失，所罗门。你打算怎么办？"
D.Strings[17951]="该醒醒了，长官！这次不是普通的豺狼人攻击！"
D.Strings[17952]="我们从暴风城请来的援兵呢？"
D.Strings[17953]="要是你的卫兵连豺狼人都阻挡不了，那我们为什么要交税给你？"
D.Strings[17954]="我的孩子在睡梦中被劫走了！我想要知道真相，所罗门！"
D.Strings[17955]="你最好赶紧采取行动，不然暴乱是难免的了，所罗门！"
D.Strings[17956]="豺狼人从没这么放肆过。到底怎么了，所罗门？快告诉我们！"
D.Strings[17957]="我们得在这儿站多久，才会有人听到我们的恳求？"
D.Strings[17958]="快让这该死的队伍动起来！"
D.Strings[17959]="你一无是处，所罗门！"
D.Strings[17960]="你别想连任了，地方官！"
D.Strings[17961]="没有正义，没有和平！"
D.Strings[17962]="要是你不对这些豺狼人采取行动，我们要动手了！"
D.Strings[17963]="快帮帮我！我全家只剩我一个了。其它人都被劫走了！"
D.Strings[17964]="不指望你了，所罗门。我会自己找到我的家人。"
D.Strings[17965]="小小胖为您服务。请吃好住好。"
D.Strings[17966]="圣光将教会你什么？"
D.Strings[17967]="愿圣光保护你， $c。"
D.Strings[17968]="太阳的光辉照耀着通往智慧的道路。我们今天要去哪儿，朋友？"
D.Strings[17969]="愿太阳的光辉守护你，$c。"
D.Strings[17970]="哈哈！这下可热闹了！"
D.Strings[17971]="我不在乎成功率会有多低。只要我们能从这丛林的疯狂与凶残中救出一只狼人，我们的努力就都没有白费。"
D.Strings[17972]="亡者在乞求慰藉。他们的痛苦在风中回响。"
D.Strings[17973]="很高兴再次见到你，朋友。"
D.Strings[17974]="我们终将自长久萦绕的阴影中获得解脱。"
D.Strings[17975]="呜哈！"
D.Strings[17976]="我宁可去酿酒也不愿意打架！$B$B可要是走运的话，也许我两项工作都能胜任，呃？"
D.Strings[17977]="这片土地的祝福与你同在。"
D.Strings[17978]="我们必须让那些真菌恶魔远离前线。它们太强大了！"
D.Strings[17979]="我父亲就在附近，我能感觉到！我们必须突破他们的防线，救出我的父亲！"
D.Strings[17980]="如果你想要骑乘狮鹫，那你就来对地方了。"
D.Strings[17981]="欢迎来到多兰纳尔，$c。如果你需要菜谱或者基础的烹调材料，就请来找我。"
D.Strings[17982]="希望你不是在找东西吃，$c。"
D.Strings[17983]="来吧！*哼哼*我在这里就能闻到你的$r臭气。"
D.Strings[17984]="为吉尔尼斯而战"
D.Strings[17985]="你的能力还不足以参加吉尔尼斯之战。当你的经验更丰富之后再回来吧。"
D.Strings[17986]="啊，丛林。知道吗，能够偶尔离开城市真是一件好事情。"
D.Strings[17987]="你的能力还不足以参加双子峰的战斗。当你的经验更丰富之后再回来吧。"
D.Strings[17988]="伟大的拉斯塔哈向你致以问候，联盟的成员。"
D.Strings[17989]="睁大眼睛，$c。即使是杜隆塔尔也难免会潜藏着敌人。"
D.Strings[17990]="探险者协会的组建是为了发掘出隐藏在这个世界各个角落的秘密。大灾变对这个世界造成了巨大的破坏，但数不清的古代遗迹和宝藏也因此有机会重现天日。"
D.Strings[17991]="我只对战士进行训练，$c。你得去别处找找。"
D.Strings[17992]="你准备好接受训练了吗，战士？"
D.Strings[17993]="真高兴看到你成功了，$n。"
D.Strings[17994]="馅饼比蛋糕要高级多了！这简直是人尽皆知！难道像你这样有身份的$c竟不知道这么重要的事？"
D.Strings[17995]="不管暮光之锤的信徒们藏到哪里，我们都将击败他们。就连元素位面也不是他们安全的避风港。"
D.Strings[17996]="当死亡之翼毁掉世界之柱时，他打开了一道位于你我世界间的裂隙。这些孢子与菌类就是后果之一。$B$B让我们看看能否共同解决它们。"
D.Strings[17997]="你好啊，$c。想要买点儿什么吗？"
D.Strings[17998]="古拉巴什已经灭亡，连同哈卡一起。我大多数的赞达拉同胞都回到了他们的故乡。$b$b现在，守卫祖尔格拉布的重任就落在了我，查巴尔和邦巴拉暗矛巨魔的肩上。"
D.Strings[17999]="这根古老的图腾有着蝙蝠的造型。这一定就是梅维克说的那根图腾。"
D.Strings[18000]="哦，嗨，$n。"
D.Strings[18001]="那王子跑了。糟透了！"
D.Strings[18002]="Zub zub。$B$B什么？走开。"
D.Strings[18003]="Zub zub。$B$B什么？两声Zub对你来说还不够吗，$c？Zub zub。"
D.Strings[18004]="干嘛问我？我又不了解暮光之锤。"
D.Strings[18005]="<劳工一边流汗一边抽搐。>$B$B我……我是说……呃，真糟！"
D.Strings[18006]="<劳工的瞳孔因恐惧而放大。>$B$B不！你发现萨乌拉诺克是奥格瑞玛新的教派领袖？他告诉我他的秘密是安全的！"
D.Strings[18007]="你好啊，$c！奥格瑞玛是世界航运的枢纽。北飞艇塔能把你送往荆棘谷和幽暗城。南飞艇塔会带你去雷霆崖或直达诺森德。$B$B飞行管理员多拉斯会送你畅游卡利姆多各地——至少能把你送到你已经去过的地方。"
D.Strings[18008]="对不起，可我无法对你进行训练。"
D.Strings[18009]="选择成为法师就是选择走上一条布满荆棘的险途。许多人都不理解我们。就连我们自己人都在艰难地接受我们的艺术。"
D.Strings[18010]="你是来帮助铁炉堡的吗，还是要整天看着我发呆？"
D.Strings[18011]="我们必须尽快找到世界之柱的中部碎片，返回大地神殿。"
D.Strings[18012]="要是你想休息，我能为你提供免费床位。虽然不怎么舒服，不过你也不像是个会花很多时间睡觉的人。"
D.Strings[18013]="我这里没有你要学的东西。去找$c训练师吧。"
D.Strings[18014]="Lok'tar！我们需要你的帮助！"
D.Strings[18015]="尽量……别丢了……那个。"
D.Strings[18016]="你是来这儿学习考古的吗？"
D.Strings[18017]="欢迎来到守望堡，$c。你可以叫我“妈妈”，我会好好照顾你。"
D.Strings[18018]="死亡，令我们重生。"
D.Strings[18019]="变异地精的触角掉了下来，在地上滚动！"
D.Strings[18020]="你得去找别的训练师，$c。我帮不了你。"
D.Strings[18021]="需要接受训练可随时回来找我。"
D.Strings[18022]="真荣幸能有你这样的英雄与我们同在，$n。"
D.Strings[18023]="不，不，不……你毁了我的家庭，但你别想夺走我的土地！"
D.Strings[18024]="快回来，$r！"
D.Strings[18025]="你能不能别来骚扰我们？"
D.Strings[18026]="滚出我的厨房！"
D.Strings[18027]="我想我真是太好命了，$n。以被遗忘者和皇家药剂师协会成员的身份重回这个世界……我的命可真是好得无可挑剔。"
D.Strings[18028]="混乱……"
D.Strings[18029]="德鲁伊和哨兵们喜欢各干各的，但我们的合作总是很默契。$B$B各自为政并不代表合不来。"
D.Strings[18030]="真是座美丽的城市，对吧？这里当时叫做吉尔尼斯。$B$B但这都已经过去了，总有一天，我们也将成为历史。只有大地与她的秘密会永远留存。$B$B你是否愿意探究呢，$n？"
D.Strings[18031]="那才叫做吸引力！我希望我们所有的药水都能产生那样的效果！"
D.Strings[18032]="与外部冲突相比，激怒这里的野猪人太危险了，$r。我不可能永远把他们挡在外面。$B$B我们必须终止他们侵害自然的行为。"
D.Strings[18033]="走开。我没能力也没兴趣教你什么。"
D.Strings[18034]="他们在不断地冲过来！把他们击退！我们必须尽力救出更多的吉尔尼斯人！"
D.Strings[18035]="总共有两个：一个是贸易区的交易者大厅，另一个是矮人区的暴风城拍卖行。"
D.Strings[18036]="你能在矮人区的最北边，城北降落点的附近找到那间拍卖行。"
D.Strings[18037]="暴风城共有两个银行——分别是位于贸易区的暴风城会计室和位于矮人区的暴风城皇家银行。"
D.Strings[18038]="暴风城皇家银行位于矮人区最北边的角落里，城北降落点区域内。"
D.Strings[18039]="黄金酒桶旅店位于矮人区的北部，就在喷泉旁边。"
D.Strings[18040]="邮箱在城中随处可见。你在任何一间拍卖行、银行以及旅店门外都能找到。"
D.Strings[18041]="暴风城有许多特色景点，从矿道地铁到暴风要塞。$B$B你想去哪里呢？"
D.Strings[18042]="在旧城区与矮人区都能找到兽栏管理员。"
D.Strings[18043]="卡琳就在暴风城的最东边，穿过旧城区后部的门就能找到她。"
D.Strings[18044]="他们人数太多了……面对我们的袭击几乎毫发无损。而我们已经损失惨重！必须得想个办法……"
D.Strings[18045]="我们遭到攻击了！"
D.Strings[18046]="纳迦不会就此罢休。我们得集结盟友的力量，把他们彻底击退！"
D.Strings[18047]="我去找埃鲁纳克……必要的话我只能自己去！"
D.Strings[18048]="雷塔维在过去的近四十年里一直都是考古界的英雄。要是他还记得它们，哦，他要讲的那些故事……"
D.Strings[18049]="嗯，我想我应该跟他进去。$b$b再没有比在这时候去面对地狱咆哮更坏的事情了……"
D.Strings[18050]="在旧城区指挥部与矮人区里都能找到猎人训练师。"
D.Strings[18051]="你在旧城区的东门外总能看到几位猎人。"
D.Strings[18052]="雄狮之眠是一片反省与缅怀之地，是纪念那些为我们而牺牲的英雄们的宁静公园。"
D.Strings[18053]="要塞位于暴风城北部。$B$B沿着运河向北前行，你就会看到一座吊桥……通往要塞庭院。"
D.Strings[18054]="监狱？你干吗要去那儿？就在城中央，法师区的东北部。$B$B你要是真去可一定要小心。听说最近发生了不少暴动事件。"
D.Strings[18055]="位于贸易区与运河间的登曼家族珠宝，你在那里应该可以找到所有想要找的东西。"
D.Strings[18056]="除了外出实地考察外，哈里森·琼斯平时都在暴风要塞的皇家图书馆里教授考古学。"
D.Strings[18057]="专业技能供应商总是待在对应的专业技能训练师附近。其它商贩则遍布暴风城的各个角落。$B$B你要买什么？"
D.Strings[18058]="勇士大厅位于旧城区的东南端。$B$B荣誉与战利品军需官就在那里。"
D.Strings[18059]="军需官就在位于旧城区东南门外的指挥部里。"
D.Strings[18060]="马厩就在旧城区东南门边上。你在那里能找到骑术训练师与养马人。"
D.Strings[18061]="要是我能到得了发射台，再给我一架那种美轮美奂的飞机——只需一架，我就能夺回诺莫瑞根，并把“坏脾气”巴拉克斯的眼镜给吓得掉下来！$B$B如果你还需要降落伞的话，我们在降落点附近的箱子里存了一些。"
D.Strings[18062]="你知道贸易区那边的狮鹫栖息地吗，就是飞行管理员所在的地方？$B$B有几个蛮锤矮人正在那儿饲养和贩售狮鹫，他们还能教你学会骑乘这种坐骑。"
D.Strings[18063]="骑术"
D.Strings[18064]="飞行"
D.Strings[18065]="你看上去累极了。出了什么事？"
D.Strings[18066]="你取回最后一块了吗？"
D.Strings[18067]="找到塞拉赞恩了吗？"
D.Strings[18068]="你看上去很不安。有什么需要我帮忙的吗？"
D.Strings[18069]="需要我帮忙吗？"
D.Strings[18070]="我想我恐怕得稍微休息一会儿。我可真没用。"
D.Strings[18071]="暮光之锤已经渗入了我的城市。如果没人去制止他们，城市就将彻底覆灭。在围剿他们位于高地的据点前，我必须确认暴风城不会成为他们阴谋的牺牲品。$B$B我需要在城里安插更多脚踏实地、忠心不二的耳目。像你这样经验丰富的$c，作用是无可估量的。你准备好帮助暴风城了吗？"
D.Strings[18072]="欢迎来到暴风城，$c。"
D.Strings[18073]="<安度因上下打量了你>$B$B$n，对吧？你的一些英勇事迹已经被广为传诵。$B$B在诺森德奋战的感觉还好吗？你见到世界之树了吗？那些关于瓦丝琪尔的传闻是真的吗？我有太多问题要问了！"
D.Strings[18074]="你能预料到吗，傻瓜？"
D.Strings[18075]="嗨，小可爱！介意帮我涂点儿防晒霜吗？"
D.Strings[18076]="我相信你和我儿子相处得不错？安度因唯一不具备的特质就是内向。"
D.Strings[18077]="等守住了暴风城，就该轮到我们把战火烧到暮光高地了！"
D.Strings[18078]="嗨。欢迎光临我的美发沙龙。$B$B你看起来容光焕发！但如果你想换个造型的话，就随便找把椅子坐下来好了。"
D.Strings[18079]="我们必须夺回属于我们的东西。我们的生死存亡在此一举。"
D.Strings[18080]="我需要前往辛萨罗顶部。该沙普比克出场了！"
D.Strings[18081]="血色十字军将荣返故里！"
D.Strings[18082]="我知道情势非常严峻，但我们的敌人一定会为他们的恶行付出代价。我保证。"
D.Strings[18083]="不该你说话时别多嘴。"
D.Strings[18084]="我们在设法弄清真主之门那里究竟有什么重要的事情在发生。$B$B但我可以确保，那些暮光之锤败类一定不会干什么好事。太反常了！我们一路追随线索而来，现在却连靠近都做不到。"
D.Strings[18085]="我是天穹之主，谁胆敢威胁我的孩子，就必须付出代价。"
D.Strings[18086]="请叫我孪生姐妹。莫维就是这么称呼我的。$B$B不，我们长的不像。你瞎了吗？看在圣光的份上——她可是个侏儒！不过我们行事方式很像。尤其是在打架的时候。$B$B至于我的名字……你听说过鼎鼎大名的蛮锤布鲁尔家族吗？想不想来杯佳酿？"
D.Strings[18087]="暮光之锤极有可能在真主之门那里有了什么新发现。$B$B也许像你这么$g能干的:可爱的;$c刚好能帮帮我？"
D.Strings[18088]="也许我可爱的同伴已经告诉你了，我们正在追寻某样神秘而强大的物品。现在所有的线索都指向真主之门。$B$B不幸的是，那些叫做暮光之锤的狂热邪教徒却阻止我们搜寻那片区域。我相信像你这样声名远播的$c一定能帮神圣遗物学会解决这个小问题吧？"
D.Strings[18089]="你来了，$n！我还以为你已经忘了我了。"
D.Strings[18090]="你想要什么？你没看到我还有蝙蝠粪便要清理吗？"
D.Strings[18091]="是什么把你带到这片受诅咒的土地上来的？"
D.Strings[18092]="巫妖王既死，我所拥有的就只剩下责任。没有家人，没有朋友……只有这个。$b$b战争。"
D.Strings[18093]="更多加兹瑞迪安？你为什么觉得我还愿意要更多这玩意？我已经积压了九千个了，一个都卖不出去！我竟然以为有人会对这种超大块头的毒蛇雕像感兴趣！啊呸！"
D.Strings[18094]="我看见废土强盗和他们的领袖——卡利夫·斯科比斯汀往南边去了。多加小心，他们看起来更强大了！"
D.Strings[18095]="我见到一只你前所未见的大虫子，就在那其中一个——要不就是两个异种蝎虫巢附近徘徊。我想我快要中暑了……你看见那边那只沙猫没？"
D.Strings[18096]="我对龙没什么研究，可有一天，突然有一只又大又可怕的龙出现在那边——就在时光之穴入口附近。他不停的叫嚷着……说什么来着……我们所知的时间尽头？我还真没怎么注意听。"
D.Strings[18097]="我一位名叫Frokle的老友原本是要前往加基森，可他和船上的所有锈水船员却从来都没有抵达。我听说在遥远的南边，有一伙疯狂的地精潜伏在一架被击落的飞行器附近，会不会是……？"
D.Strings[18098]="我在沙丘那边分析森提帕尔异种蝎小吃（专利申请中）的潜在利润时，发现了一辆破旧的货车。于是我想，“嘿，免费货车哎！”后来就出现了那只你前所未见的大蜥蜴，害得我只能空手而逃！"
D.Strings[18099]="你见过那些会在沙丘地下窜来窜去的大土堆吗？它们是隧道虫的一种，艾泽拉斯大陆上可从来没出现过这玩意儿！要是能和它们斗上一场，对向你这样经验丰富的冒险家来说，一定是次难得的学习机会。"
D.Strings[18100]="大灾变发生时，艾泽拉斯元素间的连结大大弱化了。其中一个元素——亚奎门塔斯，获得了自由。我听说他正在给南海海盗制造不小的麻烦！"
D.Strings[18101]="<厕所里一片死寂。>"
D.Strings[18102]="你好吗，$n？"
D.Strings[18103]="嘿老兄！你是来帮赞吉吉出去的吗？"
D.Strings[18104]="在我被地狱咆哮的目光盯得无地自容前，我要把这地方烧成灰烬！"
D.Strings[18105]="我能指导你锻造的技巧，并向你提供必要的工具。$B$B需要我帮忙吗？"
D.Strings[18106]="感谢你帮助我，朋友！我已经不想再变形了……现在我要努力提高我的治疗术水平！"
D.Strings[18107]="你好，年轻人，真高兴能再见到一个高贵的灵魂。$B$B埃德萨拉已经彻底堕落，成为了今日的厄运之槌。我亲眼看着我的同胞们败倒在黑暗和混乱力量的脚下。可能许多人都认为，只有把这里彻底夷为平地，才能永远结束盘踞在这里的恐怖。$B$B但厄运之槌还是值得拯救的，凡人。帮帮我，也许我们的共同努力能够重新唤醒这里巨大的善良力量，让久远以前的美好时代重新回来。"
D.Strings[18108]="我能指导你草药学的技巧，并向你提供各种有用的物资。$B$B需要我的帮助吗？"
D.Strings[18109]="大地之子，需要我的帮助吗？"
D.Strings[18110]="丛林中暗影重重，但它的土地肥沃丰茂。$B$B愿大地之灵眷顾你，$c。"
D.Strings[18111]="戈多克们不喜欢达戈索尔，所以他杀了他们。那些愚蠢的树和山羊人也不喜欢达戈索尔，所以他也想杀光他们。$B$B小$r喜欢达戈索尔吗？是不是愿意帮助他征服这个地方？还是达戈索尔也要杀掉你？$B$B愚蠢的树一直在盯着大使达戈索尔……"
D.Strings[18112]="我已经彻底弹尽粮绝了，而道路又遭到了兽人的封锁，我的运气可真好啊！"
D.Strings[18113]="<少校略点了一下头。>"
D.Strings[18114]="$n，这么快就回来了？有没有从码头工人那里得到什么消息？"
D.Strings[18115]="现在我唯一关心的就是修复埃德萨拉。在这座城市平安无事之前，其它所有事情，战争、冲突、忠诚，对我都没有意义。"
D.Strings[18116]="愿光明拥抱你。"
D.Strings[18117]="死亡之翼的污染，连同他的暮光教徒都将被彻底从深岩之洲中清除干净！"
D.Strings[18118]="联盟成功地守住了托尔巴拉德！"
D.Strings[18119]="部落成功地守住了托尔巴拉德！"
D.Strings[18120]="联盟成功地占领了托尔巴拉德！"
D.Strings[18121]="部落成功地占领了托尔巴拉德！"
D.Strings[18122]="接管铁炉堡的时候，我也在场——那时真是一片混乱。$B$B所以当我离开城堡的时候，父亲会采取这样的保护措施也就不奇怪了。"
D.Strings[18123]="我们要离开这里！"
D.Strings[18124]="你怎么能活着走到这里？你一定就是那个来对抗厄运之槌的英雄。"
D.Strings[18125]="进来，朋友……暂时把你的担忧放到一边去吧！$B$B让自己的灵魂和躯体都好好休息一下。"
D.Strings[18126]="我提供的材料都是罕见而且强大的。"
D.Strings[18127]="你已经证明了自己的实力和才智。我相信你将成为打败旋岩虫的英雄。那是我们无法完成的任务。你要深入碎岩之渊，那里是我们唯一无法通过的地方。"
D.Strings[18128]="维尔顿只不过是个该死的懦夫。他刚刚逃得一条活命，现在却装成一副英雄的样子跑到这里来了？$B$B呸！"
D.Strings[18129]="不要听阿莱克斯瞎说。瘟疫袭来的时候他却不知道逃走，那只能说明他的愚蠢。看看他现在的样子——和这里的其他憎恶没有两样。$B$B别担心，我们会夺回通灵学院和它周围的土地。把它们交给巴罗夫最后一个活着的儿子。他才是这里的合法继承人。"
D.Strings[18130]="看看这地方！$b$b这是考古学家的梦想……"
D.Strings[18131]="好好看看，我有没有变漂亮些？"
D.Strings[18132]="他们会吸干洛克湖，直到那里只剩下一点泥巴，但我们还是要英勇奋战以保卫它。"
D.Strings[18133]="我能告诉你的秘密会让你的灵魂四分五裂，$c。$B$B相信我：你应该去别人那里接受训练。"
D.Strings[18134]="有多少人知道，外界的黑暗中到底隐藏着怎样的恐怖……那是能够让灵魂发疯的诡谲之物！$B$B我们一直都很清楚这一点。而你也想来此一探究竟，对么？"
D.Strings[18135]="你好，$n。你想要学习隐秘的艺术吗？"
D.Strings[18136]="你好，$g勇敢的:美丽的;$c。我能为你做些什么？"
D.Strings[18137]="嗯，让我想想……我看见几个苦工从那边的矿井里跑出去了。嘴里念叨着蜘蛛还是什么的。新客户？嗯，有位年轻可爱的侏儒小姐，名叫杰拉莉，她上星期买了把比她大一倍的斧子。喔，魔导师毕斯普来咨询过护甲。不知道他要板甲做什么……"
D.Strings[18138]="这算什么，审问吗？你不是弗丁的内部事务处理人员吧？$b$b嗯，反正我也没什么可隐瞒的。让我翻翻我的记录。上星期米纳尔中尉从我这儿买了件舞会礼服，这让我感到有些奇怪。还有……魔导师毕斯普买了几件皮上衣，也没说出什么原因。喔，弗拉尔·伯林汉姆来为他的硬钳避世乐园之旅订购泳衣。就这些。$b$b要是你不介意的话，我得招呼客人了！"
D.Strings[18139]="你好，$c！"
D.Strings[18140]="嗯，让我们瞧瞧。我听说魔导师毕斯普最近一直把自己关在塔顶，好像是在研究什么新法术之类的东西。$b$b德尔·盖罗恩正准备退休，回农场养老。事实上他可能已经离开了。$b$b喔，我还听说有个什么$r$c在城镇附近游荡，拉住人们问东问西！$b$b只是和你开个玩笑，宝贝儿。希望这些信息能帮到你。"
D.Strings[18141]="愿光明眷顾你，孩子。在这样美好的日子里，我能为你做些什么？"
D.Strings[18142]="被盗的补给品？嗯，让我想想……$b$b我知道有个叫达莉亚的祭司，在上星期活动结束后把剩下的酒都拿走了，并没有照我说的放回来。不过我相信她很快就会前来为此道歉的。$b$b<阿尔法斯朝你眨了眨眼。>$b$b我还听到那个法师……叫什么来着……克里斯普？还是利斯普？差不多就是这名字吧。他这礼拜一反常态地做了不少次忏悔。$b$b好了，快走开吧。"
D.Strings[18143]="你……你在这里做什么，$r？难道你看不出，你已经干扰了银色北伐军的官方行动？！"
D.Strings[18144]="<哼哼>$b$b你需要些什么，$r？"
D.Strings[18145]="怎么了？我现在有些忙。"
D.Strings[18146]="我正在接受训练。可以等一会儿吗？"
D.Strings[18147]="在我们与部落交战之后，我们的舰队在进入港口的时候还保持了大致完整的规模。我们在滩头堡的阴影中起锚，重新集结。$B$B就在此时，纳迦出现了。$B$B无数只覆盖着闪光鳞片的手攀住锚链……将人们拖入水中，让他们尖叫着沉入深渊……$B$B这是被诅咒的海岸，$n。被诅咒了。"
D.Strings[18148]="消灭他们，$c！摧毁尽可能多的纳迦，为逝去者报仇。"
D.Strings[18149]="我们不能失败，$n。许多个世界的未来都将由这场战斗而决定。"
D.Strings[18150]="带我去熔渣车间。"
D.Strings[18151]="带我去铁甲兵营。"
D.Strings[18152]="带我去典狱官岗哨。"
D.Strings[18153]="带我去东部尖塔。"
D.Strings[18154]="带我去西部尖塔。"
D.Strings[18155]="带我去南部尖塔。"
D.Strings[18156]="在死亡之后，我还能帮你些什么？"
D.Strings[18157]="真高兴能有机会喘一口气。谢谢你的帮助！"
D.Strings[18158]="真高兴能再见到你！感谢你的帮忙。我再过一会儿就能站起来了。"
D.Strings[18159]="戴上这副面具，我什么都看不见。但我可不会告诉她这个。"
D.Strings[18160]="武器……盔甲……这些都是取得胜利的关键。任何一名战士，无论他是多么强壮，都很难周全地保护自己。$B$B$r，我曾经打造过许多传奇的武器和护甲，你在全艾泽拉斯也无法找到能和它们比拟的杰出作品。它们正是我的同胞赢取胜利的关键。"
D.Strings[18161]="你走错路了，朋友？呵呵呵。\n\n我能帮你些什么？"
D.Strings[18162]="你的同类在这里并不常见，朋友。\n\n我能帮你些什么？"
D.Strings[18163]="你离家已经很远了，朋友。呵呵呵。\n\n我能帮你些什么？"
D.Strings[18164]="我一直都在打算调查这个地方。$b$b而现在这种情形还从没有发生过！"
D.Strings[18165]="我听说过许多关于你的事情，$n。这个世界比以往更加需要像你这样的人。"
D.Strings[18166]="嗨，朋友。$B$B你需要找回一个丢失的同伴吗？"
D.Strings[18167]="抱歉，$c。$B$B我不认为你有能力掌握传送门魔法的真髓。"
D.Strings[18168]="拍卖行和银行就位于山谷中部那高耸入云的建筑顶部，伙计。$B$B去找泽基和Makavu吧。"
D.Strings[18169]="你得去找斯加姆比，伙计。$B$B她就在山谷中部那座高高的建筑里。"
D.Strings[18170]="就在这座山谷的旅店外面，朋友。$B$B就是山谷中部的那座高大的建筑物。"
D.Strings[18171]="战士"
D.Strings[18172]="比起其它任何组织，圣光兄弟会更有能力铲除敢于冒犯圣光的人。我们会采取一切必要手段，将亡灵那样的邪恶怪物从这个世界上彻底清除掉。没有任何人能阻挡我们。$B$B你要加入我们？还是和我们作对？"
D.Strings[18173]="巫医尤姆布一直在山谷四处活动，照料受伤的病人与元素之灵。$B$B去中部建筑附近找他吧。"
D.Strings[18174]="库扎莉和曾迦是一流的训练大师，他们就在山谷东南端的一座小岛上，伙计。"
D.Strings[18175]="这里没有激动，这里没有道统，这里没有狂热。$B$B凝聚在这里的只有兄弟间生死与共的誓言。$B$B乌瑟尔·光明使者就是在这座礼拜堂中加入了白银之手骑士团。而我，科尔法克斯，圣光之勇士，将在此地让无畏者感到恐惧。$B$B没有任何力量能抑制我的愤怒——血色十字不行，银色黎明不行，我的兄弟们不行，你同样不行。"
D.Strings[18176]="暗影行者祖鲁能够帮助你。$B$B你可以在东南方那座更高的建筑物最下面的一层中找到他。"
D.Strings[18177]="夜行者库纳基应该是你要找的人。$B$B他就在精神谷中部建筑的北边。"
D.Strings[18178]="你要找的人是塞瑟比，伙计。$B$B她通常在老渔夫——恩姆贝托旁边的树下打盹儿，看上去就像只大老虎。"
D.Strings[18179]="你一定是疯了，伙计，居然对那样的巫术感兴趣。可我没资格阻止你。$B$B乌恩加里·邪语就在东南方那座较高的建筑里，穿过暗影祭司的神殿就是了。"
D.Strings[18180]="扎姆沙是奥格瑞玛最好的厨师，朋友。$B$B你可以在这座山谷的中心建筑南边找到她。如果你真的很饿，也可以在巴塔姆西那里买到扎姆沙烹制的食物。"
D.Strings[18181]="加迪和希尔拉亚就在这座山谷中心建筑北边的一座小屋里工作。$B$B他们能提供你所需要的帮助，朋友。"
D.Strings[18182]="老恩姆贝托就在位于山谷中部建筑东面的一座小岛上。"
D.Strings[18183]="Huju和克森图能帮上你的忙。$B$B去山谷的中央建筑里找他们吧，伙计。"
D.Strings[18184]="我们的一些德鲁伊和斥候组成了一支小队伍，前来援助乱风岗的牛头人，对抗我们共同的敌人：恐怖图腾部族。"
D.Strings[18185]="东部尖塔受到了重创！"
D.Strings[18186]="东部尖塔被摧毁了！"
D.Strings[18187]="克萨迪斯和他的蛇群就在这座山谷的中心建筑周围游荡，朋友。"
D.Strings[18188]="西部尖塔被摧毁了！"
D.Strings[18189]="西部尖塔受到了重创！"
D.Strings[18190]="南部尖塔受到了重创！"
D.Strings[18191]="南部尖塔被摧毁了！"
D.Strings[18192]="当大水涌入的时候，他们对我们发动了攻击！就好象他们早已知道了那场洪水的爆发。$B$B他们要为他们犯下的罪行付出代价。"
D.Strings[18193]="联盟失去了对铁甲兵营的控制！"
D.Strings[18194]="联盟获得了对铁甲兵营的控制！"
D.Strings[18195]="部落突袭了铁甲兵营！"
D.Strings[18196]="部落失去了铁甲兵营！"
D.Strings[18197]="联盟失去了对熔渣车间的控制！"
D.Strings[18198]="联盟获得了对熔渣车间的控制！"
D.Strings[18199]="部落突袭了熔渣车间！"
D.Strings[18200]="部落失去了熔渣车间！"
D.Strings[18201]="联盟失去了对典狱官岗哨的控制！"
D.Strings[18202]="联盟获得了对典狱官岗哨的控制！"
D.Strings[18203]="部落突袭了典狱官岗哨！"
D.Strings[18204]="部落失去了典狱官岗哨！"
D.Strings[18205]="如果你需要材料，尽可以在我这里挑选。"
D.Strings[18206]="我不能训练你，朋友。"
D.Strings[18207]="<在爆炸前，质量均可保证！>$B$B<塞入钱款，即可得到专业训练和售卖服务。>"
D.Strings[18208]="如果你愿意，可以在这里休息。现在大地神殿由我们管理。"
D.Strings[18209]="这是恐怖图腾最后一次向我们发动进攻了。既然他们不可能明白自己的错误，我们就要像消灭野兽一样摧毁他们。$B$B愿大地母亲原谅我们。"
D.Strings[18210]="<石母凝视着你。她的目光仿佛穿过你的肉体，正在望着你的灵魂。>$B$B我的女儿——瑟莱德丝，将自己隔绝在泰拉莫克水晶洞穴深处，终日为挚爱扎尔塔的离去而心伤。就在那里，突然闯进了一群没心没肺的畜生，将正沉浸在哀思之中的她杀死。$B$B要是有任何理由能让我对长着血肉之躯的凡人心存信任，这理由也已在那天消逝。而在你傲慢的态度里，我看到了坚持。$B$B总有一天，你也会变得毫无用处。"
D.Strings[18211]="警告：此交通工具不可在托尔巴拉德以外使用。现在返回。"
D.Strings[18212]="抱歉，朋友。你只能去别的地方寻找训练机会了。"
D.Strings[18213]="只要一点捐赠，我就能教导你牧师的技艺。"
D.Strings[18214]="我能帮你些什么，$c？"
D.Strings[18215]="嗯，你可以和那边的大地治愈者多罗斯谈谈……就是那名大个子的德莱尼。你可以在暮光营地的左侧找到他。"
D.Strings[18216]="他们的营地几乎被彻底摧毁了。不过我们还是从那片废墟中找到了一些可用的东西。$B$B你需要些什么，$r？"
D.Strings[18217]="我这里没有你要找的东西。$B$B不过赫格莉德正在收集暮光补给品，供我们自己使用。你也许应该找她谈一谈。"
D.Strings[18218]="别人丢下的东西，我都会收集起来。$B$B最近可是有不少东西需要收集。"
D.Strings[18219]="我不能。我只负责收集。$B$B伊布迪尔应该能帮到你。他擅长修理。"
D.Strings[18220]="别人弄坏的东西，我都会修理好。$B$B最近可是有不少东西需要修理。实在是太多了。"
D.Strings[18221]="巫婆长老所选择的人！你还没意识到，是吗？我要先干掉你！还有你的朋友！"
D.Strings[18222]="她为什么会选择……一个外人？"
D.Strings[18223]="我这里没有什么能帮到你的东西。$B$B也许德罗姆的收集品中会有一些能让你感兴趣的东西。"
D.Strings[18224]="一旦你决定成为一名萨满祭司，就再无法回头了。$B$B我曾经严重低估了火元素的效用。而且它也很容易管束：只需要加水就可以了。"
D.Strings[18225]="暮光之锤一直在这片高地的各处向我们发动进攻。现在他们已经占领了不少地方。这是我们最后的阵地了，我们可不打算把它丢给敌人，无论他们会从地底下召唤出多么恐怖的怪物来攻击我们。"
D.Strings[18226]="你就是我的姑妈派来的那个家伙？毫无疑问，这是一次测试。我会迅速地干掉你，再一次向她证明我的实力。"
D.Strings[18227]="不！玛加萨，请原谅我！带我回去！"
D.Strings[18228]="那些呆子在哪里？"
D.Strings[18229]="嗯，有的……克罗米需要这个？应该是吧。$b$b我可以把它给你，随你翻看。它会告诉你达隆郡的历史，以及导致那么多人死亡的许多事件细节。"
D.Strings[18230]="绝不要低估后勤供给的作用。战士们也许会赢得几次战斗，但只有足够的物资供应才能确保一场战争的胜利。"
D.Strings[18231]="我没办法保证你们能在这里得到平静的休息环境，$c。这些兽人根本不知道什么是平静。"
D.Strings[18232]="一个喝醉的兽人很值得看一看。而一支喝醉的兽人军队则是我绝对不想看到的。"
D.Strings[18233]="如果我妈妈告诉我会有这样的时代，我绝对不会相信她的话。"
D.Strings[18234]="嗯，我们正好顺路。是那些在道路上出没的怪兽让我无法成行，只能在皇冠哨卫这里耽误时日。$b$b我想和你做笔交易：帮我清除道路上的怪物，我就会加入你们的队伍。"
D.Strings[18235]="我已经在那个镇子里浪费了太长时间。那是一个不错的地方，我很享受在那里的生活。但我想，我更喜欢留在这里。"
D.Strings[18236]="你好，旅行者？"
D.Strings[18237]="马车里放的都是装货物的箱子。还有菲奥拉和她的同伴们的一些私人物品。"
D.Strings[18238]="这个地方真是考古学家的梦想之地！$b$b真希望我能有时间进行一场彻底的考古发掘。"
D.Strings[18239]="这里的地形真可怕！吸饱了地下水的泥土中混杂着许多树根和石块，就像一锅煮糊的麦片粥。黏软的泥浆甚至能把一辆蒸汽坦克吸进去。$B$B我们的设备全都陷在了泥里，还有部落的混蛋不停地给我们捣乱！"
D.Strings[18240]="你需要返回瓦丝琪尔吗？"
D.Strings[18241]="别害怕。我其实并不像外表显示的这样可怕。$B$B我的名字是阿克莱多斯塔兹，你可以称呼我阿克莱德。我的女王派我到这里来阻止奈法利安。在任务完成之前，我绝不会休息。但这里还有一些敌人守卫着他的巢穴。仅凭我的力量是无法战胜他们的。$B$B请帮我消灭掉他们。阿莱克丝塔萨一定会因此而感激你。也许你还不知道这个名字，但我相信，你总有一天会因为今天帮助了我而感到庆幸。"
D.Strings[18242]="这里的大门永远都向你和你的钱敞开着。"
D.Strings[18243]="你不需要和我作战，$r。我对你没有恶意。"
D.Strings[18244]="她被困在了这堆垃圾里，而我已经失去了蒸汽动力。这里的地面太泥泞了！$B$B你能帮我们离开这里么？"
D.Strings[18245]="锅炉开始猛烈地冒起了气泡。"
D.Strings[18246]="似乎什么事都没有发生。天灾之锅也许已经被毁掉了，但它看上去的确和以前没什么两样。你要怎样做？"
D.Strings[18247]="<你可以学习最多两种主要专业技能。请从下列专业技能中选择：>"
D.Strings[18248]="<你可以学习所有种类的辅助专业技能。请从下列专业技能中选择：>"
D.Strings[18249]="<数据错误……请前往扎普诺兹医生处获取进一步指示。>"
D.Strings[18250]="我没有恶意，但我觉得你连一头科多兽的肚子都射不中。$B$B我们不应该再浪费彼此的时间了，去找一位合适的训练师吧。"
D.Strings[18251]="嗨，想进行瞄准练习么？"
D.Strings[18252]="嘿，你学不会施法可不是我的错。\n\n去找个$c训练师吧，好吗？"
D.Strings[18253]="这里没什么可看的，朋友。为什么不到别处去逛逛？"
D.Strings[18254]="我听说你走了很远的路才来到这里，朋友。也许你需要更多一些训练？"
D.Strings[18255]="什么？我看上去像个$c吗？$B$B请让开一点，好吗？"
D.Strings[18256]="你需要什么？$B$B太糟糕了。我可帮不了你，$c。"
D.Strings[18257]="“为了乐趣和利润控制元素。”$B$B这就是重点所在，同意我的话吗？让我们开始吧。"
D.Strings[18258]="听着，你不会想知道我到底掌握着什么。$B$B别以为我在开玩笑。那种力量能融化你的大脑。去别的地方，找些好玩的事情吧。"
D.Strings[18259]="<次元之门发出“嗡嗡”的响声。>"
D.Strings[18260]="伊莉莎很美……真是很美……"
D.Strings[18261]="我的鸟！闪电——他们射中了她！那些肮脏的野兽从天空中射中了她！"
D.Strings[18262]="可怜的闪电。她需要一段时间才能复原。"
D.Strings[18263]="好吧。准备好飞翔了吗？"
D.Strings[18264]="冒险者都是伪君子！难道你是刚刚在路边拣到了你的武器吗？"
D.Strings[18265]="在奥格瑞玛的其它地方，你再也无法找到比这个更好的火器了。"
D.Strings[18266]="我们已经做出保证，要打开一个从暴风城前往高地的元素通道。但暮光堡垒的干扰让我们无法成功。$B$B他们到底在那里发什么疯？"
D.Strings[18267]="传送门打开了！感谢你的帮助，现在我们能够从暴风城迅速到达暮光高地了。"
D.Strings[18268]="没有什么比在高空中翱翔更令人兴奋了。$B$B嗯，也许在飞翔时战斗会更好，最好在战斗之后还能喝上一杯上好的啤酒！"
D.Strings[18269]="为什么你不早说？替我给那些暮光异教徒狠狠来一下子，好不好？"
D.Strings[18270]="如果有人告诉你天灾军团被打败了，不要信他的话。看看吧……难道他们不是仍然在病木林横行肆虐吗？他们死守着他们的腐蚀之地，如同儿童拼命抓住自己的小床。$b$b我别无选择，只能战斗。在我呼出最后一口气之前，我绝不会停止和他们的战斗。"
D.Strings[18271]="$c，你将拥有这座半岛。$B$B你将成为一件武器。$B$B你将成为带来胜利的战争之神。"
D.Strings[18272]="报告！"
D.Strings[18273]="经过一番快速的查看，你确定这个人刚刚死了几个小时。"
D.Strings[18274]="我们要不惜一切代价，阻止古加尔制造出他的终极武器，就算这意味着我们要牺牲自己的生命。"
D.Strings[18275]="没有任何事情能比飞到敌人头顶上，向他们“轰隆轰隆”地扔炸弹更痛快的了！$B$B把两百五十磅的兽人扔到敌人头顶上也不错。对不对，朋友？"
D.Strings[18276]="死亡之翼回来了，他已经控制了格瑞姆巴托和这片高地的很大一部分。我已经无力阻止他了。$B$B我们的女王很快就会到来，我们将齐心协力，把那个曾经的大地守护者赶回他应在的位置上。"
D.Strings[18277]="我监视黑铁矮人已经有很长时间了……我谋划，期待，希望着能有机会驱逐他们，夺回我的家园。$B$B他们可以保留黑石山。我希望那座山会再次爆发，彻底毁灭他们。我想得到现在被称为燃烧平原的那个地方，那里本来是赤脊山脉中属于我的那一部分，却被他们的烈焰统治者摧毁了。$B$B$C，我要让全世界知道，我的国土上到底蕴含着怎样的力量。我会在他们留下的死亡与欺诈之上建立一个和平公正的王国。我的守望已经结束。现在我要奋勇作战，夺回应属于我的东西。$B$B为此，我将不惜牺牲自己的生命。"
D.Strings[18278]="很难向龙喉兽人解释“火力覆盖”和“压制炮火”这样的概念。$B$B幸运的是，他们很清楚什么是“杀”和……嗯……“杀光”。"
D.Strings[18279]="我请求援军来帮我们守住海滩。结果部落就派来了这群小不点儿和他们的小金属管。$B$B<格拉洛克不屑地看了看身边的地精。>"
D.Strings[18280]="这座要塞相当坚固，但我们的敌人从四面八方攻击我们。我们必须先在海岸上站稳脚跟，才能向内陆挺进。"
D.Strings[18281]="火焰之地的英灵，让你的愤怒充满我的身躯！"
D.Strings[18282]="我们将永远纪念卡加斯·刃拳，为了他曾经为部落所做的一切。他是有史以来最优秀的战士之一。即使是联盟也不能否认这一点。$B$B卡加斯远征军以他为名，也以他为荣。我们将在他的名义下，驱逐黑铁矮人，夺回黑石山以及其周围区域。这些都是应该属于部落的国土。$B$B你将成为酋长对抗索瑞森的有力武器。这也是属于你的巨大光荣。"
D.Strings[18283]="天空之牆的英灵，听从我的召唤！"
D.Strings[18284]="看样子，他们已经找到了回家的路。我终于放心了。$b$b你也回来了！有兴趣加入我们吗？"
D.Strings[18285]="我希望能有一天，在圣光之愿礼拜堂建起一座商店。我对战斗不在行，但这并不意味着我就不能帮上任何忙。"
D.Strings[18286]="那些男孩和我只是一同旅行了很短一段时间，但我已经无法想象没有他们相伴的生活了。"
D.Strings[18287]="希望你随意使用我的马车里的物品。只要不是我们正在使用的物品，你都可以借走。"
D.Strings[18288]="为什么他会那样逃走？！"
D.Strings[18289]="向我保证，你一定会找到他，$n。"
D.Strings[18290]="<菲奥拉显得非常不安，没有半点说话的心情。>"
D.Strings[18291]="很高兴能再见到你，$n！"
D.Strings[18292]="嗨，$n！你是来这里看望我们，还是要买些东西？"
D.Strings[18293]="哈哈，看看谁来了！"
D.Strings[18294]="吉德文就在附近……我知道。这是圣骑士的直觉。"
D.Strings[18295]="哦，啊……你好，善良的旅行者！我这个好地精能为你做些什么？$b$b我向你保证，我会独自来到圣光之愿礼拜堂，是因为我像这些银色北伐军一样痛恨天灾军团。绝对不是因为我在一次令人羞愧的飞艇坠毁事故中逃跑了！$b$b嗯，我还是闭嘴吧。俗话说，言多必失嘛。"
D.Strings[18296]="嗨，老板，如果你需要有人帮你赶马车，就和老比吉尔说一声。"
D.Strings[18297]="践踏者，守卫你们的酋长！"
D.Strings[18298]="劫掠者们，到我的身边来！"
D.Strings[18299]="地卜师，用岩石和烈火埋葬他们！"
D.Strings[18300]="真高兴又看见你了，$n。当你准备对大门发动进攻的时候，我们中的一些人也潜入到这里。$B$B我们计划在这里与肖尔大师碰面。$B$B<那名小队长拿出一张暮光堡垒的地图，指出那个地点。>$B$B等你准备好之后就告诉我，我们将并肩作战。"
D.Strings[18301]="这里还有点乱，我们还在收拾，请别介意。$B$B你可以尽情在这里享受！放松放松，消费一下……我们这里什么都有——兑钱商、洗衣店、异国美酒、钓鱼训练师，你可以享受到一流的服务。$B$B如果有人给你麻烦，就来找我，我会为你处理的。$B$B我是米达……大老板米达。"
D.Strings[18302]="旅途中有人作伴的感觉真好。否则一路上孤孤单单的。"
D.Strings[18303]="现在还不行，$g小伙子:姑娘;。$B$B我还要调试老板的伐木机。$B$B她可不喜欢像那些老木头一样徒步在城周围走来走去，特别是在她要去对付那个酋长的时候。"
D.Strings[18304]="在病木林深处很少会有访客。通常都是憎恶。$b$b我能帮你什么忙吗？"
D.Strings[18305]="将军在上一次海战中不幸遇难。我把他的舰船改造成了堡垒。$B$B这只是个应急方案，$c。"
D.Strings[18306]="从石板上的秘密符文看来，有办法让这装置重新焕发活力。$b$b我们只需要想出该如何做……"
D.Strings[18307]="看来你的前人已经把信号弹搭好了，但还没来得及发射。$b$b现在看你的了，$n。"
D.Strings[18308]="信号弹发射器已清空。"
D.Strings[18309]="我的人民长久以来都和蛮锤部族保持着良好的关系。$B$B我们当中有少数人在此定居。那些人把这片土地看作是值得守护的家园。"
D.Strings[18310]="即使是在克尔苏加德统治结束后这光明的日子里，在巫妖王战败之后——兄弟会仍生生不息。"
D.Strings[18311]="哈卡有许多尽为人知的名字。有人叫他血神，另一些人则直白地把他称作夺灵者。抛开名衔不说，他是这个世界上强大力量与邪恶意图的化身。$B$B我早先发现了这座神庙，并将它沉到了悲伤沼泽的下方。不幸的是，我们似乎只是在帮助阿塔莱——确保他们召唤哈卡的计划能在不受干扰的环境下实施。许多负责守卫神庙的巨龙都已被腐化，夺灵者的气息却一天天变得更为强烈。$B$B我无法凭自己的力量阻止他们。但如果我们合作，也许能有足够的时间终止他们的疯狂举动。"
D.Strings[18312]="死亡之翼途径暴风城，为花园区留下了满目疮痍。我们只得暂时返回达纳苏斯。"
D.Strings[18313]="上层精灵回来了，还带回了失落已久的神秘法术。$B$B你有什么需要我检视的东西吗？"
D.Strings[18314]="奥术重铸师能更改一件物品的魔法效果，这种奇术就叫重铸。$B$B通过重铸，武器、防具或珠宝原有的某种次要属性将被移除，以为其添加新的次要属性。通过这种方式，使用者可以对其装备进行自定义，以更好地与其角色和技能相匹配。$B$B例如，如果某样物品可使你更准确地命中敌人，但你却更想获得更快的攻击速度，则可花费若干费用，通过奥术重铸师重铸这件物品，降低命中而提高急速。"
D.Strings[18315]="如果你想要找奥术重铸师重铸物品，可以去法师区外的附魔商店，那里有一位上层精灵法师可以帮上你的忙。"
D.Strings[18316]="我们别拐弯抹角了，$r。我来这儿的目的只有一个——那就是消灭古加尔！$B$B你的任务就是阻止他造出终极武器。那可能是个灌注了上古之神力量的强大神器。"
D.Strings[18317]="有个神器——那是种武器，正在被注入上古之神的力量。我们不知道它究竟在哪儿，可我们必须赶在古加尔完成之前找到它。$B$B其它任何事都是次要的。任何人的生命都是可以牺牲的，包括你和我。"
D.Strings[18318]="净化程序启动……"
D.Strings[18319]="净化已完成。等待送交。"
D.Strings[18320]="警告，系统已过载。故障即将发生！"
D.Strings[18321]="你认识我父亲吗？"
D.Strings[18322]="不，别碰净化者……那是我的骄傲与乐趣所在！"
D.Strings[18323]="啊！我可不要再这样了！我已经提出请求，要参加下一次的探险……"
D.Strings[18324]="我可怜的宝贝儿，你一定累坏了。$B$B这儿有食物和饮料，要是你愿意的话，可以放心地在这儿休息。"
D.Strings[18325]="想吃点儿什么吗，$c？$B$B还是你只想找个地方放松一会儿？"
D.Strings[18326]="喔伙计，终于有人来了！这下面简直疯狂透顶！比疯狂还要疯狂！"
D.Strings[18327]="我仅代表卓绝而永保中立的热砂集团——欢迎来到沼桨镇！我们是东部王国独一无二的滨海度假胜地与军用武器补给港。$B$B也许你们这些家伙刚刚在南面不远处经历了战火的洗礼，可在这围墙之内，只有欢声笑语。忘了肩头的重担吧，来歇会儿，喝上两杯，但切记别找麻烦……否则我这儿的彪悍卫兵会让你们明白什么叫做“中立地域”。"
D.Strings[18328]="托尔本·光爆，传送应对方案工程师为您效劳！"
D.Strings[18329]="你好啊。$B$B你是来存放宠物，还是在寻找失踪的同伴？"
D.Strings[18330]="你好啊。$B$B你是在寻找失踪的同伴？"
D.Strings[18331]="等我们安全回到地表之后，会有大把的时间供我们交谈。"
D.Strings[18332]="如果我们要活着离开这里，就必须从这群无意识的麻疯侏儒中间冲过去！"
D.Strings[18333]="你好，我名叫泰瑟兰·血望者。我将一生中最好的时光都用来进行巫术的训练，并召集与我志同道合的血精灵，组成了神圣遗物学会。$B$B要知道，在这个世界的各个角落里埋藏着许多古老、强大的宝物。我打算利用这些宝物将我的族人从他们堕落的嗜好中解救出来，让他们重新团结为一体，成为往日那个光荣而坚强的种族。$B$B我可以向你保证，魔法是可以接触的。只要得到适当的教导，任何人都能使用这种力量并且免于因它而堕落。$B$B现在，联盟的各个种族，甚至是部落的人都在嘲笑我们遭受重创的首都，仍然矗立的逐日者雕像，和我们在世界各处一次又一次遭受的挫折。$B$B但这种情况不会再继续下去了。"
D.Strings[18334]="请救救我！"
D.Strings[18335]="我不想死在这里！"
D.Strings[18336]="不要让它们吃掉我！"
D.Strings[18337]="有人吗！有人能救救我吗？！"
D.Strings[18338]="我还很年轻，还不想死！"
D.Strings[18339]="我真的要死在这里了吗？"
D.Strings[18340]="救命！我已经没力气了。"
D.Strings[18341]="我把附近残骸里能抢救的东西都抢救出来了，现在我已经坚持不住了……"
D.Strings[18342]="你们一族注定要承受这一切，$r。"
D.Strings[18343]="你和这些魔鬼结盟了？你也将会有被焚毁的一天！"
D.Strings[18344]="<黑色的巨龙身上布满了伤口。他一直盯着你，眼睛里闪烁着凶恶的光芒。>"
D.Strings[18345]="<凶恶的黑色巨龙拼命扯拽着捆缚他的锁链。你最好还是离他远一些。>"
D.Strings[18346]="我不可能永远困在这里，$c。你最好现在就祈祷，祈祷当我复仇的时候，你不会在我面前。"
D.Strings[18347]="龙并不是猪和牛那样简单的野兽。他们是一种自然的力量。强大……原始的力量。$B$B让他们服从你，就是要驾驭这个世界。$B$B能够支配他们，你也就支配了命运的力量。"
D.Strings[18348]="自从这场企业联合战争开始以前，我就在进行各种药剂混合工作了。我现在并不打算停止这行当。$B$B只要还有买家，芭芭就不愁没生意做！"
D.Strings[18349]="他们的火力相当强劲。也许我们不应该小看那些地精矬子。"
D.Strings[18350]="看到前面的通道了吗，$g小子:姑娘;？"
D.Strings[18351]="有埋伏。"
D.Strings[18352]="哦，$g小伙子:姑娘;！已经4次了。"
D.Strings[18353]="该死的，没错！"
D.Strings[18354]="如果是凯莉派你来抓我回去，那她可要失望了。这里还有许多暮光暴徒没消灭干净呢。"
D.Strings[18355]="我很快就会回来的，$g小伙子:小姑娘;。为了能过上好日子，还得再走一趟。"
D.Strings[18356]="哈！这个地方到处都是好东西！$b$b看看我在这里挖出了什么……$b$b一顶呼吸帽子！"
D.Strings[18357]="这很有趣。"
D.Strings[18358]="有没有试过我的呼吸帽？$b$b老巴德可不要再嘬蛤蜊了！不，先生……"
D.Strings[18359]="森林也要后退！"
D.Strings[18360]="哎呀！"
D.Strings[18361]="感谢圣光！我成功了。"
D.Strings[18362]="能再次回到正常侏儒的中间，实在是让人松了口气！"
D.Strings[18363]="我还以为我要完了！"
D.Strings[18364]="你……你不会吃掉我的，对吧？"
D.Strings[18365]="光凭我自己肯定不行……"
D.Strings[18366]="感谢你把我救出来！"
D.Strings[18367]="我的家人……你有没有找到我的家人？"
D.Strings[18368]="啊，一个新人。这边走，先生。"
D.Strings[18369]="一切都将焚毁！"
D.Strings[18370]="火焰……熄灭了！"
D.Strings[18371]="请让我做一下自我介绍。我是兰多菲·摩洛克。今天，我会把你们杀光。"
D.Strings[18372]="我宏大的谋略，绝妙的计划！都完了！"
D.Strings[18373]="待在我身边。我们一定会把你弄出去的。"
D.Strings[18374]="你会得到援助的。"
D.Strings[18375]="你做得很好……你会没事的。"
D.Strings[18376]="只有当最高议会全体表决通过的时候，拉穆卡恒才会对尼斐塞特发动战争。$B$B我们的机会不大，但我的兄弟必须明白，死亡之翼的盟军绝对不会讲任何道理。"
D.Strings[18377]="你和那些尼斐塞特 杂碎是一伙的？是不是他们派你来干什么肮脏的勾当？快说！"
D.Strings[18378]="还不算太糟糕……$b$b我还有我的呼吸帽子！"
D.Strings[18379]="部落的战争机器需要你！"
D.Strings[18380]="你是来这里助战的吗？海加尔山必将燃起熊熊大火！"
D.Strings[18381]="将军和他的部队正要去攻取一座已经由你进行过侦查的基地。你应该去与他们汇合。"
D.Strings[18382]="那只巨型鱿鱼就要完蛋了。凡尔纳已经重整装备，准备再次上阵……现在，我们只需要耐心等待。$B$B它会回来的。$B$B你就看着吧。"
D.Strings[18383]="啊……来这里拜访我的人并不多。$B$B请多坐一会儿吧。"
D.Strings[18384]="联盟需要你。响应英雄的号召吧！"
D.Strings[18385]="远处的那片碎石堆曾经是我们家族传承了五代的产业。$B$B我们正在把它夺回来。$B$B敌人的数量远远超过我们……但我们是蛮锤部族！你愿意帮助我们吗？"
D.Strings[18386]="天哪！我的老心脏可受不了！"
D.Strings[18387]="莫提姆·摩洛克被命中要害，颓然倒下！"
D.Strings[18388]="到此为止了，霍格！"
D.Strings[18389]="他……他已经死了？"
D.Strings[18390]="这不可能是真的。你不可能这样轻易地杀死他！"
D.Strings[18391]="你在找我？"
D.Strings[18392]="爸爸让我射击！"
D.Strings[18393]="真是一团乱！我们刚刚从拯救深岩之洲的战斗中回来，却看到了这种场面？$B$B可憎的暮光之锤！$B$B幸好你在这里，把他们解决掉了！"
D.Strings[18394]="你必须保护我，$n。没有了武器和图腾，我完全没有自卫的能力！"
D.Strings[18395]="兰多菲·摩洛克消失了！"
D.Strings[18396]="霍格愤怒了！"
D.Strings[18397]="%s开始转变为大地之力！"
D.Strings[18398]="这具矮人的尸体被严重地损毁了。暮光之锤一定都是些以屠杀为乐的疯子。"
D.Strings[18399]="我必须承认那些暮光暴徒并非无能之辈……也许他们缺乏战斗技巧，但他们的数量和坚韧完全可以弥补这个缺陷。在我们的上一次战斗中，他们的确取得了一些战果。"
D.Strings[18400]="顿沃德家族以刚强悍勇著称，但他们的脑子并不怎么灵光。我很担心我的兄弟们会把他们的名誉和生命浪费在一些不必要的地方。"
D.Strings[18401]="哈！我的兄弟们正渴望着一战。我已经无法再阻止他们了。$B$B你要参加这一战吗？"
D.Strings[18402]="你就像顿沃德家族的一员。我喜欢你。"
D.Strings[18403]="<当你靠近这座控制台的时候，它发出一阵“嗡嗡”声。>"
D.Strings[18404]="好啊，好啊！"
D.Strings[18405]="你能从那些腿上弄一个垫片下来！"
D.Strings[18406]="要以正弦波的幅度晃动它，宝贝！"
D.Strings[18407]="200马力，双重燃烧引擎，修正流体电容！开动！"
D.Strings[18408]="真是……伟大！！！"
D.Strings[18409]="武装鲨鱼？为什么我没有想到这个？！"
D.Strings[18410]="厉害！！！"
D.Strings[18411]="这座笨重的雕像立在这里，已经有许多个世纪没有被碰触过了。"
D.Strings[18412]="虽然这座雕像已经非常古老了，却没有任何被风蚀损坏的痕迹。"
D.Strings[18413]="根据颜色判断，这一定就是戒卫。$b$b你在它上面找到一个小缺口，与你的棋卒轮廓正好吻合。"
D.Strings[18414]="这座红色雕像很像是你带在身上的哨卫的棋卒。$b$b这座雕像上有一个小缺口，正好与你的棋卒形状相吻合。"
D.Strings[18415]="希望你带来了矿工锄，朝圣者。没有任何地方能比这里更适合挖掘古代宝藏了。"
D.Strings[18416]="在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。$B$B好吧，你准备好进行训练了吗？"
D.Strings[18417]="在火刃部族灭亡之后，我们剑圣就发誓，要从恶魔的统治之下解放我们自己和我们的族人。$B$B这个任务终于完成了，但我的荣誉并没有得到恢复。$B$B我要为部落而战，直到我在战场上光荣牺牲。这是我唯一的道路。"
D.Strings[18418]="不久之前，暮光之锤侵入了这片曾经质朴清澈的水域和它周围的岛屿。$B$B他们污染了我的湖水。我要彻底驱逐他们，这样我才能净化这片湖泊。"
D.Strings[18419]="这片土地是兽人和人类第一次展开大规模战争的地方。南边不到一里远就是斯通纳德。兽人在那里首次集结，入侵我们的国土。$B$B就是在这里，他们在我们不知不觉间聚集起大规模的军队。就是在这里，他们攻击西边的联盟小镇，拉开了三次兽人战争的序幕。$B$B那是我的城镇，为了救我，我的父母都死在了那里。$B$B但我来这里不是为了复仇……我是要赢得一场战争。"
D.Strings[18420]="呃……"
D.Strings[18421]="嗨！以前没有见过你。你也失去了家园吗？如果你愿意，可以和我坐在一起。"
D.Strings[18422]="你肯定不是蛮锤的人。为什么要到这里来？不管怎样，你在这个时候跑到这里来，只能说是你的运气不好。"
D.Strings[18423]="很高兴见到你，年轻的$g先生:女士;。"
D.Strings[18424]="他们在我们没有察觉的时候偷袭了我们……同时对高地各处发动了攻击。他们破地而出，又从空中俯冲而下。大部分狮鹫都受惊逃走了。许多优秀的矮人白白牺牲。$B$B如果不是科甘及时将我们召集起来，重整了队伍，我们可能早已经被围歼了。是他救了我的命。至少现在，我们还有反击的机会。"
D.Strings[18425]="你肯定不是本地人。不过这对我来说没什么关系。无论是谁，只要真心愿意帮助我们，我都会和他生死与共。"
D.Strings[18426]="我很久以前就来到这里，研究我们受到诅咒的兄弟，寻找治疗他们的办法。$B$B玛格图尔热情地欢迎我。我住在这里的时候，他成为了我最亲密的朋友。$B$B而现在，他躺在我面前，奄奄一息……"
D.Strings[18427]="看上去，你能为我们挣不少钱。去杀戮熔炉里转一圈如何，朋友？"
D.Strings[18428]="看上去，这头狮鹫受了伤。也许治疗或急救技能可以让它重新站起来。"
D.Strings[18429]="狮鹫专注地看着你。它显然是从你的衣服上闻到了熟悉的气味。"
D.Strings[18430]="这头狮鹫似乎是被困住了。不过看上去，它应该能轻松地挣脱身上的束缚。"
D.Strings[18431]="<伊瑟拉的影像在你的眼前闪动，仿佛一切都是在梦中。再没有其他人看见她在这里。而那幻象显然也感觉到了你的存在。>"
D.Strings[18432]="<伊瑟拉的幻象如同梦一般飘落在你面前。一开始，她的心思似乎并不在你身上。过了一会儿，她才注意到你。>$B$B许多年以来，艾维娜一直在我的梦境边缘闪动。我想知道，她会不会回来。但我也害怕她的灵魂因为过去那段岁月而变得黑暗……$B$B不管怎样，如果我们真的要拯救这座山脉，就必须关注一些更紧迫的事情。"
D.Strings[18433]="这里真不错。你不这样认为吗？$b$b也许是有一点热，但只是干热而已……"
D.Strings[18434]="爸爸总是对我说，大家伙力气大，但速度慢……$b$b我相信爸爸一定没有见过这个家伙！"
D.Strings[18435]="<黑角望向地狱的远方，然后又将注意力转回到你身上。>"
D.Strings[18436]="一块不显眼的大理石板。"
D.Strings[18437]="一块不显眼的石板。"
D.Strings[18438]="<这位巨大的远古半神仍然对你保持着警惕，但他已经像对待盟友一样和你说话了。>"
D.Strings[18439]="我是拉穆卡恒的纳顿亲王。尼斐塞特部族已经公然与其他托维尔为敌。$B$B请帮我逃出这里，这样我就能说服我的兄弟，也就是我们的国王向这些叛徒发动战争！"
D.Strings[18440]="我可以教导你任何最基础的采集和生产技能，仅此而已。\n\n如果你要学习初级以上的技能，你就需要去访问专门掌握某一个技能的大师。\n\n你最多可以学习两个主要专业技能：两个采集技能；或者两个生产技能；或者是采集、生产技能各一个。\n\n考古学、烹饪、急救和钓鱼是辅助技能，不会占用你的主要专业技能的学习位置。你可以学习全部辅助技能。"
D.Strings[18441]="采集技能让你能够获得生产技能所需的原始材料：采集草药；开采矿石、石料和宝石；或者从野兽的尸体上剥去皮革。\n\n你可以用自己采集来的原料支持你的生产技能需求，或者是在拍卖行中出售你采集来的原料。"
D.Strings[18442]="我要学习附魔。"
D.Strings[18443]="我要学习制皮。"
D.Strings[18444]="我要学习工程学。"
D.Strings[18445]="生产技能让你可以将采集到的原始材料加工成各种有用的物品。你可以自行使用这些物品；或者将它们赠予你的同伴；或者在拍卖行出售它们。\n\n每一项生产技能通常都会有与之相对应的采集技能，这样你就可以用自己采集的原料支持你的生产技能。不过你也可以在拍卖行购买自己所需要的原料。"
D.Strings[18446]="草药学让你能在原野上找到并采集草药。草药可以在拍卖行出售，或者作为炼金术和铭文技能的原料。\n\n技艺高超的草药师还能利用他们对于大地的知识进行自我治疗。"
D.Strings[18447]="采矿让你能够在原野和地下洞窟中找到矿脉露头，采掘矿石、矿物、石料。你可以在拍卖行出售你的采掘成果，或者用它们支持锻造、工程学和珠宝加工技能。\n\n技艺高超的采矿师在采矿过程中会让身体逐渐强化，使耐力得到提升。\n\n如果要采矿，你需要一把矿工锄；你可以从商人或者采矿供应商那里购买到矿工锄。"
D.Strings[18448]="剥皮让你能够从被猎杀的动物身上剥取皮革，并对皮革进行硝制。你可以在拍卖行中出售你的皮革，或者用它们来支持你的制皮技能。\n\n技艺高超的剥皮师往往还是解剖学专家，从而提高他们对敌人造成爆击的几率。\n\n为了从动物身上剥取皮革，你需要一把剥皮小刀。你可以从商人或者制皮供应商那里买到剥皮小刀。"
D.Strings[18449]="炼金术让你能够利用草药和其它原料制作具有各种效能的药剂、药水、油剂、合剂和药锅。如果你使用自己配制的药剂和合剂，你获得的优势将更为强大，持续时间也会更长。\n\n技艺高超的炼金术师还能够制作出各种元素和矿物材料，供其它生产技能使用。\n\n炼金术师与草药学为对应技能，你可以利用草药学自行采集草药，供炼金术使用。"
D.Strings[18450]="锻造让你能够利用金属、矿物和石料铸造近战武器，锁甲、板甲等重型铠甲，以及其它专业技能所需的原料，还能让你制造磨刀石、盾刺等可升级装备的物品。\n\n技艺高超的锻造师能够在他们自己的护腕和手套，以及他们自己或他人的腰带上开凿宝石槽。这些宝石槽中可以装入魔法宝石，使物品变得更加强大。\n\n锻造很适合与采矿搭配，因为你可以利用采矿自行采集矿石等原料，供锻造使用。"
D.Strings[18451]="附魔让你能够对物品施加魔法，从而使它们具备各种作用；并能够分解物品；以及制造魔杖和魔法油。\n\n技艺高超的附魔师甚至可以对他们自己的戒指进行附魔。这是其他人绝对无法做到的。\n\n附魔所需要的大部分原料必须通过分解物品获得。这会摧毁被分解的物品。所以这一技能和裁缝是对应技能。你可以通过分解带有魔法效能的裁缝物品提取出附魔所需的原料。\n\n附魔师还能将魔法施放在羊皮纸上。附魔师可以将这样的羊皮纸在拍卖行出售，或者保存它们，供以后使用。你可以从附魔供应商那里购买羊皮纸和其它有用的附魔材料。"
D.Strings[18452]="工程学让你能够制造各种有用的，令人惊叹的，或者是怪异无比的物品。比如步枪和瞄准镜，摩托车，还有机械松鼠。但这些物品中有许多只能供你自己或者其他工程师使用，比如特殊的眼镜，腰带、靴子、手套和斗篷上的机械配件，以及飞行机械。\n\n大部分工程学原料都是通过采矿获得的金属，所以这两个技能为对应技能。\n\n制造许多工程学物品都需要铁匠锤和一些必要材料，比如火药和熔剂。你可以从商人或者工程学供应商那里购买它们。"
D.Strings[18453]="铭文让你能够制造魔法卷轴、雕文、副手武器、暗月卡片，甚至还有其它专业的配方。\n\n铭文所需的许多原料都来自于草药学采集的草药，所以这两个技能很适合搭配。\n\n你需要学者的书写工具来制作铭文物品，此工具和羊皮纸等其它铭文材料都可以从铭文供应商那里购买。"
D.Strings[18454]="珠宝加工让你能够制造魔法戒指、项链、饰品以及切割宝石。\n\n珠宝加工所需的宝石可以通过购买获得，也可以对通过采矿技能获取的矿石进行选矿，从而获得。因此，珠宝加工和采矿是对应技能。\n\n制作大多数珠宝加工制品都需要用珠宝制作工具。高级珠宝加工制品往往还需要简易研磨器。这些工具都能够从珠宝加工供应商那里购买。"
D.Strings[18455]="制皮让你能够用皮革、整皮和鳞片制造皮甲、斗篷、皮甲强化护甲片和其它类似物品。制皮所需的其它材料可以通过玩家间交易获得，或者从制皮供应商那里购买。\n\n制皮与剥皮为对应技能。你可以通过剥皮技能获得原料，支持你的制皮技能所需。制皮所需的其它必要物品，比如线和染料都可以从商人或者制皮供应商那里购买。\n\n技艺高超的制皮师还可以强化他们的护腕和腿甲。"
D.Strings[18456]="裁缝让你能够用各种布料制造护甲、斗篷、衣服、袋子、魔线和其它类似物品。你可以购买这些布料，或者通过杀死人形生物获得布料。其它的必要材料，比如线和染料都可以通过玩家间交易获得，或者从裁缝供应商那里购买。\n\n技艺高超的裁缝还能够用魔法刺绣来强化他们的斗篷。\n\n很多裁缝都会兼作附魔师，这样他们就能分解他们制作出来的魔法物品了。"
D.Strings[18457]="和我说说铭文。"
D.Strings[18458]="你一定要试试这种啤酒。"
D.Strings[18459]="如果你不打算工作，那就离我们的发掘场远一些。"
D.Strings[18460]="嘿，帅哥！"
D.Strings[18461]="还有地方吗，甜心？"
D.Strings[18462]="跟我走吗？"
D.Strings[18463]="一位淑女能够上马驰骋一番吗？"
D.Strings[18464]="马特克，你今天看上去很英俊。"
D.Strings[18465]="哦，马特克，我能和你一起驰骋吗？"
D.Strings[18466]="马特克，你是我所知道的最勇敢的兽人。"
D.Strings[18467]="救救我，马特克！我需要你！"
D.Strings[18468]="这条路通向城市的更深处。继续朝南，向装载室走。"
D.Strings[18469]="必须承认，我对这个野心勃勃的小狂徒有了些兴趣。$b$b我不会急于做出判断，但我要告诉你，我已经听到了一些令人不安的谣言。$b$b时间会告诉我，他的动机是否正当。"
D.Strings[18470]="这里的效率真高，你说呢？"
D.Strings[18471]="你怎么会来找我们这些衰老又疲惫的沙漠狗子？"
D.Strings[18472]="我并不吃惊。$b$b我也不可能忽略这么多的问题……$b$b为什么一个考古发掘场里会有这么多武器？这与埋藏在地下的宝物有什么关系吗？这里的发掘人员到底效忠于谁？$b$b我还没有找到这些问题的答案。我想，我得自己去寻找真相。"
D.Strings[18473]="白痴！$b$b快滚开！$b$b难道你看不出来，我正在集中精神吗？"
D.Strings[18474]="听我说！朋友，举起望远镜！$b$b好好看看这里。$b$b要知道，在漫长的岁月里，这个地方一直被隐藏着。"
D.Strings[18475]="看看他积聚的财富！$b$b他的手段经常会让我感到不舒服，但这个结果却是无法否认的……$b$b不要去想那些令人不快的事情了。要知道，这样也不礼貌。"
D.Strings[18476]="好好想想，我亲爱的$g男孩:女孩;！$b$b一旦我们野心勃勃的小毛皮商发掘出足够的财宝，他就会成为艾泽拉斯最有影响力的角色。$b$b如果这一天到来，我们都会有一个令人满意的地位。"
D.Strings[18477]="不就是这里吗？$b$b与志同道合的伙伴一同探索这个世界从未被开发过的角落？$b$b还有什么能比这样更好的？"
D.Strings[18478]="对于我来说，他有些太活泼了。但我想，这个世界需要各种各样的人。$b$b你为什么要问这个？"
D.Strings[18479]="我明白你的意思，我想……$b$b说实话，我来这里只是因为想要看看这个世界和各种奇异的事物，让我的知识面扩大一些。$b$b对于其他人的事情，我并不是很关心。$b$b不过还是很高兴见到你。"
D.Strings[18480]="这里的风景真美，不是吗，$c？"
D.Strings[18481]="实在是太棒了！$b$b元首是如此自信，还有他的声音！必须承认，他的样子真是有魅力。$b$b你知道他结婚了吗？"
D.Strings[18482]="有传闻说，这里的一些古物具有神秘的力量！$b$b他似乎已经对这些东西彻底着迷了……"
D.Strings[18483]="很抱歉，$c。$b$b对此我真的没什么了解，所以我没什么可说的。"
D.Strings[18484]="说说你的情况，$r。"
D.Strings[18485]="我们正在注意你，$r……"
D.Strings[18486]="……一直在注意！"
D.Strings[18487]="巨龙峡口是联盟在荒芜之地建立的第一个立足点。虽然荒芜之地位于暴风城和丹莫罗中间，但在传统上，它一直是部落的势力范围。$b$b现在这一情况已经发生了改变，我们需要确立自己的权属地位。当然，那头龙对新卡加斯的进攻也不会干扰我们的计划。"
D.Strings[18488]="得知黑龙要与新卡加斯对抗，我像你一样感到惊讶。高恩非常顽固，拒绝任何人的帮助。$b$b即使这样，高阶考察者泰瑟兰·血望者还是要求我时刻注意新卡加斯的情况，以确保局势对我们不会太……糟糕。"
D.Strings[18489]="我们必须阻止塞拉赞恩的军队进攻巨石之炉。$B$B否则他们就有可能偷走世界之柱的中部残片。"
D.Strings[18490]="我们钓鱼，我们睡觉，我们炸飞各种东西。还有什么生活能比这样更好？"
D.Strings[18491]="我赶了这么远的路，就是为了和著名的“龙喉先知”谈一谈。在毁灭古加尔之前，我想看清楚他的黑心里面到底有什么。$B$B但她没告诉我任何有意义的东西。我只得到了一堆谜语。也许你能帮助我。"
D.Strings[18492]="那个箱子就在废墟里。$b$b我们行动！"
D.Strings[18493]="我们已经太久忽略了奥术的秘密。$B$B你是来学习这个秘密的吗？"
D.Strings[18494]="我们已经太久忽略了奥术的秘密。$B$B可惜的是，它对你来说只能是个秘密。"
D.Strings[18495]="感谢你救出了国王……还有王子，$n。"
D.Strings[18496]="你让我明白了朋友的意义，$n。"
D.Strings[18497]="我见证了你的成功，$n。你是你们一族的骄傲。"
D.Strings[18498]="抱歉，$c。$B$B你对奥术的掌握还不够强大，还无法理解传送门魔法。"
D.Strings[18499]="你也是一名奥术的研究者？$B$B我可以教导你传送门魔法的技艺，如果你想学的话。"
D.Strings[18500]="恐怕我没办法帮你，$r，但我相信凯琳·斯蒂文可以。"
D.Strings[18501]="你是否介意用你的暗影将太阳封锁一会儿？$b$b这样会很不错……"
D.Strings[18502]="在这里工作实在是太热了——特别是还要穿着这身制服。"
D.Strings[18503]="他们向我承诺过，可以在这里得到巨大的财富。$b$b这可真是个不错的笑话！"
D.Strings[18504]="他们让我们像狗一样工作。我们却什么也没得到！"
D.Strings[18505]="司克诺兹因为我们发了大财……但我们呢？！"
D.Strings[18506]="你觉得哥培尔如果在这里，会怎么看你？嗯？"
D.Strings[18507]="现在那个仪式完蛋了。你欠我一大笔债，$r。$b$b我会让你还的！"
D.Strings[18508]="听着，自从我们逃出来之后，我稍微庆祝了一下，喝了几杯。然后我一直在想……$b$b那些攻击我们的小人应该得到正义的惩罚！$b$b如果我们不为此做些事情，那么每一个没有准备就进入那个地方的探险家都会变成奴隶被卖掉，或者遭遇更可怕的事情！"
D.Strings[18509]="这道传送门对面就是托尔巴拉德。"
D.Strings[18510]="跟我来，$n。我会把你介绍给你的训练师，阿拉玛尔·格里姆。"
D.Strings[18511]="阿拉玛尔，请允许我向你介绍$n，他刚从诺莫瑞根逃出来。"
D.Strings[18512]="我很清楚，出现在这座森林中的恶魔是因为我们一族犯下的错误。$B$B我应该不是第一个想要对此进行弥补的上层精灵。感谢翡翠议会能够不计前嫌，接受我的帮助。"
D.Strings[18513]="在暴风要塞西北方的一座湖中小岛上，大地之环建起了通向世界不同地方的传送门。\n\n那里还有巴拉丁典狱官的代表，可以帮助你前往托尔巴拉德。"
D.Strings[18514]="其他大陆"
D.Strings[18515]="在飞艇塔楼北边的悬崖上，大地之环建起了通向世界不同地方的传送门。\n\n那里还有地狱咆哮近卫军的代表，可以帮助你前往托尔巴拉德。"
D.Strings[18516]="跟我来，$n。我会把你介绍给你的训练师，教官汽轴。"
D.Strings[18517]="军士，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[18518]="跟我来，$n。我会把你介绍给你的训练师，凯尔希·钢烁。"
D.Strings[18519]="凯尔希，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[18520]="跟我来，$n。我会把你介绍给你的训练师，贝西·冰雹。"
D.Strings[18521]="贝西，请允许我为你介绍$n，最近从诺莫瑞根出来的生还者之一。"
D.Strings[18522]="跟我来，$n。我会把你介绍给你的训练师，“怪医”克斯宾"
D.Strings[18523]="医生，请允许我为你介绍$n，他帮助内温的队伍从诺莫瑞根救出了许多幸存者。"
D.Strings[18524]="<穆兰狮鹫骑士纹丝不动，双目凝视前方，仿佛完全没有意识到你的出现。>"
D.Strings[18525]="在皇家贸易区找到神圣遗物学会。毫无疑问，那个组织中的诸多考古学家之一会在那里帮助你。"
D.Strings[18526]="道格拉斯就派你过来挨揍了？"
D.Strings[18527]="想要打架吗？"
D.Strings[18528]="看上去，你想要从我这里得到些什么……"
D.Strings[18529]="想受惩罚吗？"
D.Strings[18530]="$n，你要从那些海盗手中拯救我们，否则还能怎样？！"
D.Strings[18531]="我是否能请求你从那些海盗手中拯救我们，亲爱的$n？！"
D.Strings[18532]="你会想要找到亚当·胡萨克的。他在内环法师区南部有一个办公室。$B$B如果他没有在外面进行探索工作，他应该就在那里。"
D.Strings[18533]="总有一些新东西需要调查。"
D.Strings[18534]="快一点。"
D.Strings[18535]="任何人都无法阻挡女妖之王的怒火。"
D.Strings[18536]="血牙将会崛起。"
D.Strings[18537]="我的冰激凌帝国将迅速发展壮大。提古勒和弗洛尔就要完了！"
D.Strings[18538]="一定要保持镇定。"
D.Strings[18539]="为了希尔瓦娜斯！"
D.Strings[18540]="像奥达曼这样的地方肯定隐藏着关系到我们一族过去的秘密！"
D.Strings[18541]="戴德洛·沃姆伍德就是你想要找的那具尸体。他经常会在这个镇子的南端。"
D.Strings[18542]="我有点忙，$c。你要什么？"
D.Strings[18543]="我能帮你些什么？"
D.Strings[18544]="嗯。"
D.Strings[18545]="这个兽人受了重伤。"
D.Strings[18546]="请原谅，朋友，但我的确是很忙。$b$b我受命为这一地区指挥官的发现进行公证。$b$b这些发现具有极为重大的意义！"
D.Strings[18547]="我有一个重要的任务，那就是为司克诺兹元首撰写传记。$b$b请原谅。"
D.Strings[18548]="我向克罗姆加的军队提供各种装备。"
D.Strings[18549]="不久前，我看见他们向那些船上运送了一些古物。$b$b我还从没有见到过那么多黄金被堆在一起！"
D.Strings[18550]="数年以前，当我打算去研究双足飞龙的时候，却被困在了这里。一旦我恢复了自由，我就决心回去保护它们。$B$B现在，大灾变席卷了整个世界，暮光之锤开始大肆捕捉这些珍贵的野兽，甚至不惜对它们造成毁灭性的打击。"
D.Strings[18551]="赶快走，不要让奴隶们看见你！"
D.Strings[18552]="你……是要救我吗？"
D.Strings[18553]="你是要来阻止大公吗？"
D.Strings[18554]="嗨！我还是个新人！是生着一双大翅膀的，发着白光的一个大怪物让我活过来的！我效忠于女妖之王！嘿！$B$B救命！$B$B嗨！"
D.Strings[18555]="好啊！谢谢！我就在这里等你！谢谢！好的！"
D.Strings[18556]="我见证了巫妖王的毁灭。泰坦的造物被我强大的战斧摧毁。得到号令的时候，我一个人与诺森德的怪物们对战，凭一己之力为银色北伐军赢得了巨大的胜利。现在，我来接受这场终极挑战。希尔斯布莱德丘陵能为弑君者奥尔库斯献上些什么？？？"
D.Strings[18557]="你说有入侵者？我会有生命危险吗？我会被肢解吗？"
D.Strings[18558]="奥尔库斯会成功的！没错！"
D.Strings[18559]="看着我，农夫。我全身从头顶到脚趾可都是珍贵的传家宝。是艾泽拉斯历史上最伟大的英雄们给我的礼物。$B$B现在看看你自己。$B$B再看看我。$B$B当然，这匹马可是用晨星做成的。$B$B你为我准备了什么无聊的任务？你们的任务其实只应当由没脑子的兽人去完成。"
D.Strings[18560]="好啊，好啊，还有什么？"
D.Strings[18561]="就这些？一个任务？你一定是在开玩笑。这里没有狗熊要猎捕吗？也许我可以去采集某种罕见的花卉，让你能够用来调配致幻剂，喝下去以后让你能看到伟大的预兆？也许本地有令人困扰的地鼠捣乱，需要予以惩治？没有？什么都没有？"
D.Strings[18562]="有没有听说过瑟银兄弟会？当然，我们可能很像山谷中和黑石深渊里的那些矮人。但相信我：我们和他们根本不是一种人。$b$b那些恶棍挖得太深。现在，他们愚昧地侍奉着一股黑暗的力量——拉格纳罗斯，炎魔君主。我们很高兴自己能有独立的意志。虽然在大多数时间里，我们不得不将自己的全部精力都用来弥补那些恶棍所犯下的罪行。"
D.Strings[18563]="黑石的黑铁矮人和瑟银哨塔的那些男孩都和我没关系。$b$b我是中立的，而且我喜欢这样。当然，只要出价合适，我会帮助任何人……"
D.Strings[18564]="事实证明这个司克诺兹是个明智的投资对象。$b$b看来我的洞察力的确是超强的。"
D.Strings[18565]="就像父亲一直说的那样，要成为一名成功的投资人，必须具有精明的头脑，敏锐的直觉和无尽的勇气。$b$b必须承认，我能在一哩以外就能闻到投资的机会。"
D.Strings[18566]="大使似乎是因为某个人或某件事而遇害了！"
D.Strings[18567]="谁能知道？$b$b他已经成为了这个行动的关键，但这不能证明任何事。"
D.Strings[18568]="谁，我？$b$b为什么？我觉得自己没有资格，嗯……不，我想我应该拒绝。"
D.Strings[18569]="什……什么？！嗯，我……$b$b正在展开的发掘工作是如此令人兴奋，现在却要把注意力集中在这种事情上，我想这可能不合适。$b$b你也知道，这只能是一个令人困扰的故事。"
D.Strings[18570]="别……别碰我……$b$b出了什么事？！"
D.Strings[18571]="不！我当然不好！$b$b以前我从没见过尸体……"
D.Strings[18572]="他就从那座兵营里跌跌撞撞地爬了出来。$b$b我尖叫着寻求援助，但那些卫兵甚至不看我一眼！"
D.Strings[18573]="是的。$b$b听起来像是个好主意。"
D.Strings[18574]="我们的人已经守住了通道。现在要集中全力帮助主室中的人了。"
D.Strings[18575]="这门大炮直指海岸，而且炮膛里已经填满了弹药，安放好了引信。$B$B这可真方便啊！"
D.Strings[18576]="你是来接受训练的吗，猎人？"
D.Strings[18577]="真难以相信，我们竟然在做这个。我知道，卡尔烬德的出现会让我们全都受到威胁。但这是真的吗？统治这里的不是大地之环吗？还是别的什么组织？$b$b为什么瑟银兄弟会要如此大动干戈？"
D.Strings[18578]="欢迎来到瑟银哨塔。作为这里的工头，我负责管理瑟银兄弟会的一切行动。我们的主要工作是采矿，锻造，还有一些辅助性的守卫工作。但最近我们越来越向军事化发展了……这实在是没有必要。"
D.Strings[18579]="$n，我们已经进入了熔渣之池。现在该是最终完成工作的时候了。"
D.Strings[18580]="$n，我们任何时候都欢迎你。"
D.Strings[18581]="蠢货。奥比斯顿！起来，消灭入侵者！"
D.Strings[18582]="多谢你让我重获自由，$n。$B$B现在让我们看看能不能救出玛加萨，并终结暮光之锤在千针石林的罪恶行径。"
D.Strings[18583]="这些狼人是我们的阶下囚。它们将由最高统帅部来发落。"
D.Strings[18584]="你想干什么，小矮子？趁我还没拿锤子把你的笑脸砸扁，赶紧从我面前消失！"
D.Strings[18585]="我能帮你什么忙吗，$g帅哥:美女;？"
D.Strings[18586]="什么事？我很忙，防卫者。"
D.Strings[18587]="巨龙给了我们从暮光之锤手中夺取大门的机会。我们一定要善加利用。"
D.Strings[18588]="看到你真高兴，$c。$b$b我们最近少有访客。"
D.Strings[18589]="真意外！$b$b我们以为不会有人来……"
D.Strings[18590]="这就是那个大名鼎鼎的$r$c，嗯？$b$b如你所知，还有一个尚未被激活的方尖碑……$b$b当复原这古老装置的时机到来时，你会在那里吗？历史会记住你吗？$b$b这取决于你是否愿意合作！"
D.Strings[18591]="我没有担当领袖的经验。我应该预见到纳克拉尔的叛逆。而我却只能收拾他留下的烂摊子。$B$B我不知道加尔鲁什·地狱咆哮是如何做到的。他一定具备过人的力量，才能将如此多样化的部落大军凝聚在一起……我愿意更加深入地了解他。"
D.Strings[18592]="可以在探险者大厅内找到学者教授铁裤。"
D.Strings[18593]="在力量谷的中部要塞里有位血精灵，是银月城贝洛克代表团的成员。他就是你要找的人。"
D.Strings[18594]="可以在暗影裂口里找到那些法师。共有两个入口，一个位于力量谷与智慧谷中间，另一个在暗巷区。"
D.Strings[18595]="小心点儿，$r。$b$b仪式失败以后，司克诺兹的脾气一直非常糟糕。"
D.Strings[18596]="大使倒在血泊中。$b$b在他破烂的衣服之下，你发现一排巨大而凹深的齿印。$b$b更令人不解的是，伤口仿佛是烧蚀而成，有些地方还有焦黑的痕迹。"
D.Strings[18597]="<那人几乎当你不存在。他显然没兴趣和你多说什么。>"
D.Strings[18598]="继续前进，$r。$b$b你的存在对我毫无意义。"
D.Strings[18599]="<密使冷笑着，看都不看你一眼。>$b$b忙你自己的事去吧，$r。"
D.Strings[18600]="太可怕了！$b$b整个地区都在回响着令人毛骨悚然的咆哮声。$b$b可怜的家伙……$b$b请原谅——我想我得来一杯。"
D.Strings[18601]="我不确定自己究竟看见了什么。$b$b在我意识到发生什么之前，就已经结束了。"
D.Strings[18602]="真是太不幸了！$b$b让我们把这清理干净，好吗？$b$b如果不是万分必要，这种事情绝不能再发生……"
D.Strings[18603]="我当然很好奇，但过去的就让它过去吧。$b$b我们可不该再引起什么不必要的恐慌。那可一点儿都不明智！"
D.Strings[18604]="当然不是！$b$b我的意思是说，我确实把全部家当都押在了这儿……可老实说，一场公共危机对大家都没好处吧？"
D.Strings[18605]="发生了什么事？！$b$b你看见那人身上的伤口吗？！$b$b会是什么样的怪物干的？"
D.Strings[18606]="不，我什么都不用看也知道，我们全都要死了！$b$b你听懂没有？！"
D.Strings[18607]="你说的倒容易。$b$b我承受不了这么多！我得赶紧想办法离开！"
D.Strings[18608]="<这名演员面无表情地看着你。>"
D.Strings[18609]="我的建议很简单，$r。$b$b别在这儿碍事。"
D.Strings[18610]="有位名叫隐世者汉蒙的学者可以帮上你的忙。你可以在月神殿里找到他，他通常在那里和归返的上层精灵交谈。"
D.Strings[18611]="我们认识吗？不？欢迎来到暮光之锤。"
D.Strings[18612]="末日即将来临！"
D.Strings[18613]="你的护甲上沾了点儿血。你还好吧？"
D.Strings[18614]="新兵？你向指挥官报到了吗？"
D.Strings[18615]="在东边的凋零法阵中正酝酿着什么大事。$B$B不论是什么，都希望能早点儿结束，我们可以到环境更好的地方去。"
D.Strings[18616]="保持警惕。他们说早先那个到处袭击平民的怪人可能还在附近。"
D.Strings[18617]="我们居然把玛加萨·恐怖图腾囚禁在此，这不奇怪吗？好在她所有的图腾都被摧毁了。$B$B我甚至听说她毒害了凯恩·血蹄。希望她是站在我们这边的。"
D.Strings[18618]="督军克罗格派我到这里来固守战线。但他至今都没有派任何士兵给我。$B$B看看这个地方！对面有食人魔，有暮光之锤。我们这边却……啥也没有。"
D.Strings[18619]="欧托·灰皮通常都在长者高地的长者大厅。你可以在那里找到他。他会帮助你的。"
D.Strings[18620]="你可以在猎人高地找到烈日行者集会所。"
D.Strings[18621]="这座城里的奥术重铸师灌魔者菲娜能帮助你。通常她会和逐日王庭外的瑟丹娜及其学徒们在一起。"
D.Strings[18622]="全都下地狱了，$c！"
D.Strings[18623]="如果你要找蒂亚，她经常在纳鲁之座的幻象中流连。她一定很愿意帮助你。"
D.Strings[18624]="这些洞可都是鬼窟，伙计。里面全都是最可怕的魂能。$B$B当暮光之锤盘踞在这座山顶的时候，那些被他们淘汰的人都被扔进了这些山洞。成为了以这些山洞为巢穴的黑龙的食物。$B$B这些洞里从没有活人走出来，就连那些灵魂也逃不出来。"
D.Strings[18625]="搜寻者波杜鲁通常都在贫民窟的集市里。要找他就去那里吧。"
D.Strings[18626]="高等精灵法师和学者——达瑞妮斯是这座城里最博学的考古学家……也是最喜交际的人。$B$B她通常呆在魔术旅馆里，就在城中心的北边。她喜欢那里的气氛，常常会与魔术旅馆的老板和客人们谈论她在荒野中的冒险生活。"
D.Strings[18627]="这片广阔的田野原本并非如此，$c。是我们凭借坚定的决心和意志力，将人类腐朽的农场变成为洛丹伦最大，最丰饶的药渣田和蘑菇种植园。$B$B现在，所有这一切都可能因为一场小小的事故而将化为乌有！"
D.Strings[18628]="你要接受训练？我可帮不了你。我可不是你要找的人。"
D.Strings[18629]="你要接受训练，大个子？"
D.Strings[18630]="我会带你去装载室，$n。"
D.Strings[18631]="你想看着千针石林彻底毁灭吗？$B$B不想？$B$B那就照我说的做。"
D.Strings[18632]="我们就是在这儿集合幸存者，准备对他们进行净化。距离地表没多远了！"
D.Strings[18633]="我相信我不必提醒你，在这儿要保持警惕。"
D.Strings[18634]="这里的一切都完全是光明正大的！"
D.Strings[18635]="蛮锤矮人是我们不共戴天的仇敌。不是他们死，就是我们亡。"
D.Strings[18636]="别打扰我。"
D.Strings[18637]="我会查出谁才是这懦夫行为的背后主使！$b$b然后……"
D.Strings[18638]="要是真到了我有话对你说的时候，你应该转身就跑。"
D.Strings[18639]="你只是愚笨地在这里蹒跚而行，$r，全然不知自己已被什么样的军队包围。"
D.Strings[18640]="你心中充满了恐惧，凡人。$b$b我能感觉到。"
D.Strings[18641]="有话就说吧。尽量简短些。"
D.Strings[18642]="国王派了个陌生人来收集情报？我想你一定是那个……什么来着？$R？对，就是救出纳顿亲王的那个$r。$B$B不管怎样，我在这遥远的北部没察觉到任何尼斐塞特渣滓的活动迹象。不过在这儿倒有许多其它闲事需要处理。"
D.Strings[18643]="我听说过你，$n。你是来帮助我们的吗？"
D.Strings[18644]="不。这就是废土强盗的杰作。$B$B据说他们加入了西边一个组织更为严密的团伙。他们的暴力行径野蛮至极。"
D.Strings[18645]="我听说你在城里。你可真是个奇怪的家伙。$B$B想和我谈谈？"
D.Strings[18646]="不，尼斐塞特没什么行动。可我刚刚收到消息，一场前所未见的强大沙尘暴袭击了奥西斯城。$B$B我正准备亲自将消息带给国王，看来你可以帮忙转达一下。"
D.Strings[18647]="长久以来，我们都仍希望能挽救大地看守者和他的子嗣。在某些时候，我们必须要明智地意识到，任何程度的弥补都抵不过这些巨龙对这个世界所造成的伤害。$B$B在某些时候，我们被迫要插手。"
D.Strings[18648]="我被兴奋冲昏了头。$b$b我早该感觉到的……"
D.Strings[18649]="我一生的财富都……没了。$b$b我的生活已经毫无希望了。"
D.Strings[18650]="我以为他所做的一切都是正确的。$b$b我……满怀希望。$b$b但他完全不是他自我标榜的那种人。$b$b我真是个傻瓜。"
D.Strings[18651]="海马稳稳的漂浮着。"
D.Strings[18652]="桌上没什么令你感兴趣的东西。"
D.Strings[18653]="桌上放着几堆货物。你决定先从座狼皮开始。"
D.Strings[18654]="你看到了自己早先收集到的那堆座狼皮。这些将被用来为你做衣服。"
D.Strings[18655]="往旁边看去，映入眼帘的是你从熔岩层收集来的黑曜斑点软泥。这些将被用来为你的伪装服染色。"
D.Strings[18656]="最后，你看到了一些线团，将被用来缝制伪装服。"
D.Strings[18657]="你已经集齐了物品。把它们带给萨拉隆·巨钉来完成组合。"
D.Strings[18658]="在整个黑铁部族中，你再也找不到比我技巧更高超的工匠了！$b$b什么敲打、锻造、采掘，都见鬼去吧！一根缝针、一个顶针就是我所需要的全部金属！"
D.Strings[18659]="你给我带来了什么？"
D.Strings[18660]="该死的龙喉渣滓！$B$B他们屠戮我们的鸟禽，攻击我们的亲人，夺取我们的土地。就在这世界分崩离析之时，他们还在袭击我们的家园。$B$B要是你们这群联盟想要获取蛮锤的帮助，就只有一条途径能让我们颔首——阻——止——龙喉。"
D.Strings[18661]="<布朗迪抬眼看了看你。>$B$B啊，是的。高阶萨满正在战场上拼杀，为夺回桑德玛尔废墟而努力。我就是人们口中的“低阶萨满”。$B$B在他离开的这段日子里，他让我留下处理桑德玛尔的萨满事务……"
D.Strings[18662]="桑德玛尔是蛮锤的最后一处堡垒了。我们狭小的城镇中挤满了难民，而我的兄弟此时正在奋力作战。"
D.Strings[18663]="小心，牛头人先生！角鹰兽来了！"
D.Strings[18664]="猫咪……猫咪！我真的很抱歉，猫咪！快回来！别这样离开我！"
D.Strings[18665]="我是来自滩头堡的先遣单位，正在试图说服桑德玛尔的蛮锤部族。$B$B我想我能帮助他们，但令人难以置信的是，他们竟然没有一个三环交流极向转换装置？一个都没有！$B$B他们这些日子到底是过来的？"
D.Strings[18666]="你好啊，$c！我是来自滩头堡的先遣侦察单位，尽力说服桑德玛尔的蛮锤部族。$B$B他们的狮鹫骑士正被龙喉的龙骑士们纠缠得团团转。我设计了一个奇妙的装置来帮助他们，可我缺少一些物品。许多物品。$B$B你能帮我吗？"
D.Strings[18667]="看看这个全息平台。我想让你对诺莫瑞根行动有所了解。"
D.Strings[18668]="你好啊，兄弟会的朋友。"
D.Strings[18669]="你在那被摧毁家伙的身体里发现了几个可回收的部件。看来你只能回收一个部件。"
D.Strings[18670]="呃，什么？"
D.Strings[18671]="整理行装，$n！我们即将前往暮光高地。你准备好了吗？"
D.Strings[18672]="我奉命担任暮光高地联盟联合行动的总指挥。$B$B特立独行的蛮锤部族仍散落在这附近的乡间各地。要是我们能将他们集结于联盟的战旗之下，就将变得势不可挡！可敌人正从四面八方逼近。希望你已经做好了迎战的准备，$c。"
D.Strings[18673]="喔！$b$b我们一定要再这么干一次！$b$b好了，我要继续去做研究了。等我准备好了，我会来找你的。"
D.Strings[18674]="我们的敌人能把整座城市用沙土掩埋。我们的传统并未让我们做好应对此战的准备。"
D.Strings[18675]="我们终将重建这里，并使其复现往日的荣光——除去那些麻烦的人类。"
D.Strings[18676]="既然我们已经夺取了这座该死的岛屿，我们就得做些什么来让它变得像模像样。你能帮帮我们吗，$n？"
D.Strings[18677]="我对那个人人交口谈论的恶魔监狱不感兴趣。不过我们确实得先完成些任务才能让这地方为己所用。"
D.Strings[18678]="欢迎来到托尔巴拉德，$c。时间紧迫，我们开始吧。"
D.Strings[18679]="我们没有选择战争，$n。是战争选择了我们。$B$B我们必须竭尽全力去应对。"
D.Strings[18680]="跟黑石兽人达成约定可不是件容易的事儿。我是说，拜托！是黑石兽人哎！这些家伙所经历的战争比阿格拉玛还要多，而且他们还住在黑铁矿堆成的山上！酷毙了！"
D.Strings[18681]="你的死亡将使一切变得不同！"
D.Strings[18682]="嗯，孩子？"
D.Strings[18683]="幸好我及时出现了！$b$b我想我们还没见到那最后一个司克诺兹成员。"
D.Strings[18684]="<秧苗的叶子指向你，仿佛在注视着你所在的方向。>"
D.Strings[18685]="集中精神，$n。$b$b我们必须赶在司克诺兹的前面拿到应许约柜！"
D.Strings[18686]="这显然是内鬼干的！$b$b谁也摆脱不了嫌疑！"
D.Strings[18687]="你好！"
D.Strings[18688]="醒醒，醒醒！"
D.Strings[18689]="我是一棵树！"
D.Strings[18690]="欢迎来到维尔萨尔绿洲，朋友！$b$b艾泽拉斯的人间天堂！"
D.Strings[18691]="小心，$n！他们就在这儿。到处都是……龙喉！"
D.Strings[18692]="总有一天，我将为拉穆卡恒贡献自己的力量。"
D.Strings[18693]="该来的还是来了！他们正在发起最后的猛攻。我们已无路可退。唯有坚守桑德玛尔或手握战锤而死。$B$B为了蛮锤部族！！"
D.Strings[18694]="探险者协会和神圣遗物学会的成员非常相似：考古学是我们的宗教，而我们的信仰都不再纯粹。\n\n我们的手段和他们的伪善没什么两样。我们就像是他们的阴暗倒影。\n\n只需要轻轻推他们一把。他们就会变成我们，远离光明……"
D.Strings[18695]="你听到了吗，$n？树梢上传来了拍击翅膀的声音……纳克拉尔来了。"
D.Strings[18696]="视野一片模糊……跟这些水一样。"
D.Strings[18697]="也许你没有听到我的话。我说了，让我摆脱这些链子！"
D.Strings[18698]="看来邪教徒盯上了那些德鲁伊！$B$B你可以通过这旋转的传送门看到野性之心哨站。穿过传送门就能返回营地。$B$B等这里的工作结束后，便可藉此快速离开。"
D.Strings[18699]="穿过传送门，返回野性之心哨站。"
D.Strings[18700]="我能感觉到我的枝桠焕发着无尽的生命力。我已经迫不及待想要让它重返大地的怀抱。"
D.Strings[18701]="使用改装跑车的钥匙|TInterface\\Icons\\inv_misc_key_12.blp:32|t进入你的跑车，并搭载你的朋友小静、王牌和大胖。"
D.Strings[18702]="什么事，小子？你看不见我正忙着吗？"
D.Strings[18703]="我可不愿意和这些术士们一起被困在这里。这是克希鲁恩的工作，不是我的！$b$b我已经等不及要参加战斗了。我需要出去，和我的龙在一起。"
D.Strings[18704]="看看这是谁！是持棍人$g他自己:她自己;！"
D.Strings[18705]="捍卫者阿尔苏达和其他战士训练师都在那个能俯瞰远行者广场的地方，就是靠近锻造师所在的那个地方。"
D.Strings[18706]="这里还有很多事情要做，$r。你做好帮忙的准备了吗？"
D.Strings[18707]="欢迎来到巴拉丁营地。我知道现在这里还完全不像是一座营地，但只要经过一番努力营建，我们就能让这里初具规模了。"
D.Strings[18708]="看样子，我们在这里永远都有事要做。新的命令会在每天凌晨三点到达。这可真是奇怪。"
D.Strings[18709]="部落对这里发动了凶狠的攻击。我们要在同一时间内进行两场战争。"
D.Strings[18710]="自从格瑞姆巴托陷落之后，我们蛮锤部族就再也没有真正团结起来。在这高地之上，被世界所遗忘，各个部族都已选择了各自的生存方式。$B$B若想将他们重新凝聚在一起可不是件容易的事。"
D.Strings[18711]="是的$n，我已经了解外间所发生的悲惨事件的全貌。$B$B我原本希望我那群蛮锤兄弟们能自行解决，可看来不行。$B$B你和我必须想些有创意的办法。"
D.Strings[18712]="齐心协力，我们将缔造历史！"
D.Strings[18713]="很快，我们的行动便将在艾泽拉斯住民间广为传颂！"
D.Strings[18714]="人们将从世界各地赶来，见证我们劳动的果实，$n。"
D.Strings[18715]="这群畜生妄想趁我转身之机偷袭我的城镇？！我要让他们知道什么叫蛮锤的正义！"
D.Strings[18716]="我刚刚代表费兹·霍布诺布去过铁木工程营。"
D.Strings[18717]="我来这里是为了见证主人的回忆，还有过往的真实。"
D.Strings[18718]="这儿发生了什么事？！"
D.Strings[18719]="大德鲁伊……这究竟是……？"
D.Strings[18720]="我……我必须告诉其它人。你立刻去找女猎手塞露拉。"
D.Strings[18721]="谢谢你救了我！不过能不能别告诉费尔莉？我说是我自己逃出来的！"
D.Strings[18722]="我已得到詹姆斯·哈劳的允许，要取得前往刺枝林地的坐骑。"
D.Strings[18723]="小点儿声，动作轻些。"
D.Strings[18724]="自从月神的镰刀第一次来到这里后，我们之中很少的一部分人住到了这个地方。他们大都承受了吉尔尼斯沉沦的劫难。$B$B我们一直居住在这片森林中，学习自然之道，并致力于维持它的平衡。在这片被诅咒的土地上，我们被诅咒的族人已经找到了一条新的人生之路。"
D.Strings[18725]="绝不让那些该死的兽人再入侵赤脊山！"
D.Strings[18726]="这真是孤注一掷。我们把很多赌注都押在这个计划上了。赤脊山的自由就是其中之一。"
D.Strings[18727]="你已到达凿握据点，$g小伙子:小姑娘;。最好能发挥你的价值。"
D.Strings[18728]="石头穴居人……深渊的害虫。"
D.Strings[18729]="我很想和你做生意，朋友。我是真心实意这样说的。但你首先要得到锈水财阀的承认。"
D.Strings[18730]="呦！我是锈水三轮摩托经销商卡尔·万金。$B$B欢迎随便看看。选出您最中意的三轮摩托！$B$B一辆无比拉风的三轮摩托……一辆充满危险气息而又无惧死亡的三轮摩托……一辆为您带来荣光的三轮摩托！$B$B选好就来找我，我们来谈谈价格。"
D.Strings[18731]="我们得继续前进。这儿充满危险。"
D.Strings[18732]="他们就在这座山谷东南尽头那座高大的建筑物顶上。"
D.Strings[18733]="朋友，你是来学习钓鱼的？还是来买东西的？"
D.Strings[18734]="听着！$b$b拿走那些水晶会让构造体失去能量。"
D.Strings[18735]="使用你的改装跑车|TInterface\\Icons\\inv_misc_key_12.blp:32|t追上受雇的抢掠者，夺取他们偷走的物品。"
D.Strings[18736]="哈！$b$b你真的搅起了一场沙暴，$n。"
D.Strings[18737]="黑石兽人是我的同族。我的父亲、母亲、父亲的父亲都是黑石兽人。我也是黑石兽人。$b$b但更重要的是，我是一个兽人。这意味着荣誉对我比什么都重要。$b$b我的领主允许我来到燃烧平原完成我的任务。在这里的黑石兽人明白他们的错误之前，我绝不会离开。"
D.Strings[18738]="我忠于我的父亲，尊敬他的计划……但我也忠于我心中的正义。我的黑石兄弟们制造的阴谋和欺诈，即使用一千本书也写不完。现在，他们又要入侵赤脊山，只为了满足他们盲目的扩张主义心理。$b$b我不会让他们的阴谋继续下去。这个邪恶的故事将写完它的最后一章，并得到一个绝不会让他们满意的结局。"
D.Strings[18739]="这全都是她的错！是她让我们偷的！"
D.Strings[18740]="我的孩子们……我干了什么！"
D.Strings[18741]="不……我是永生不死的……我还会……"
D.Strings[18742]="这是我们的错……这毁灭全都是我们的错……"
D.Strings[18743]="水晶还能被找到……如果我们能再次找到它……"
D.Strings[18744]="真累啊……真想休息……"
D.Strings[18745]="水晶将拯救我们！我们将得到拯救！"
D.Strings[18746]="其实我正想要找你呢。真的！"
D.Strings[18747]="我本打算在这里搞点小买卖的！"
D.Strings[18748]="<杰克低声嘟囔着。你觉得他似乎是在说，锤子是他的武器。>"
D.Strings[18749]="德拉克·奈特弗，等候你的吩咐！"
D.Strings[18750]="我可不知道苏拉赫有这么多……熟人。"
D.Strings[18751]="你好，朋友！$B$B我的名字叫罗素，我的事业是音乐。历史长河中所有伟大的蛮锤英雄都活在我的歌曲中。借助我的鲁特琴弦和我的歌喉，我们的勇士得到了不朽的威名。$B$B请停下脚步，听我唱一段颂歌吧！"
D.Strings[18752]="我们开始吧！第一段是写给亲爱的范妮的，但我还没有最终完成。$B$B“眼睛”的韵脚该怎样去押呢？"
D.Strings[18753]="啊，我知道你是怎样的$c了，$n！那么，第二段是关于范妮和焰须在一起的故事。$B$B“皈依”的韵脚又该怎样押呢？$B$B"
D.Strings[18754]="……嗯，好吧，我想我可以完成这个作品了。最后一段！逐渐激扬的爱之庆典向蛮锤发出行动的呼唤。$B$B我现在只要押上“团结”的韵脚……"
D.Strings[18755]="我的鲁特琴已经调整到了最佳状态。我们是否准备好谱写一些东西了？"
D.Strings[18756]="我没想到这里还会有人。你打算作我的同伴，还是只想找一条路出去？"
D.Strings[18757]="终于得到了安息……"
D.Strings[18758]="谢谢你……"
D.Strings[18759]="现在，走吧……你不应该承受这水晶的怒火……"
D.Strings[18760]="水晶回来了。你必须离开……"
D.Strings[18761]="小心，$g小伙子:姑娘;。下方有无数座狼，而兽人就潜伏在路口。一个$c在这里随时都有可能丧命。"
D.Strings[18762]="虽然这些礼物并没有什么实际用处。但它们还是能让我想起那些老朋友和过去美好的时光。"
D.Strings[18763]="你是一个女孩所能梦想的最英俊的男朋友。所有女孩都会为你神魂颠倒，甜心！"
D.Strings[18764]="看到你！我就知道我是这座岛上最幸运的男孩子！！！"
D.Strings[18765]="你最好快上楼去，老板。贸易大王加里维克斯正在等你。"
D.Strings[18766]="$n，你必须加紧行动，把你的钱从银行里拿出来！"
D.Strings[18767]="他能给我们弄到更多的卡亚可乐吗？如果我们不能让自己的头号商品摆满货架，又怎么能让你成为贸易大王？！！！"
D.Strings[18768]="哦，我想你会喜欢这个的，老板！"
D.Strings[18769]="他们在这里！好了，你们三个今天来帮$g他:她; ，在聚会开始之前，$G他:她;要做的事情可是不少呢！"
D.Strings[18770]="王牌、小静、大胖，你们三个要跟着$n，帮助他处理那些坏家伙！"
D.Strings[18771]="一定要从那个银行里拿到足够的钱。我可不希望你还去买你平时喜欢穿的那种廉价衣服。这可是个重要的聚会！"
D.Strings[18772]="你们不得不等一等了！$n来了。$G他:她;将是下一任贸易大王！"
D.Strings[18773]="你要快一点，孩子。我们要让你加入比赛。但首先，我们要给这台伐木机找好零件！"
D.Strings[18774]="进入伐木机，赢得比赛。锈水财阀就指望你了！"
D.Strings[18775]="你胜利了，孩子，这太好了！可惜的是，那头龙已经把一切都毁掉了。不过没关系。你的成就让我们感到自豪。现在，回总部去吧。"
D.Strings[18776]="你可真有胆量，兄弟！"
D.Strings[18777]="我可不打算再这样了，兄弟！"
D.Strings[18778]="科赞是巨魔的！"
D.Strings[18779]="也许我应该把炸弹从你手里拿走。然后我们看看谁会爆炸！"
D.Strings[18780]="想要驰骋一番吗，$g坏家伙:甜心;？来吧，我们要去沼桨镇。这可是一次单程旅行。"
D.Strings[18781]="这么多美好的回忆，这么多丰厚的利润。我可不能袖手旁观。"
D.Strings[18782]="欢迎，蛮锤的朋友们！$B$B库斯海文是我们一族的精神核心。在这里，不同的部族会在和平中聚首。$B$B在这里，我们共同哀悼逝去的英雄，将他们和他们的狮鹫埋葬在雷霆山的顶端。让他们与天空融为一体，永垂不朽。"
D.Strings[18783]="一场婚礼？如果这还不能把这些家伙聚集在一起，我就吃掉我的锤子！$B$B我们需要让这场婚礼无比隆重盛大，$n，我们需要你的帮助。有一句蛮锤的老话……让我想想……那句话是怎么说的？"
D.Strings[18784]="婚礼就要开始了！我需要为这快乐的一对准备一件礼物。一件非常重要的礼物。$B$B蛮锤的未来完全系于这最后一个将我们团结在一起的机会！"
D.Strings[18785]="现在，你已经帮助我建立起了我的冰激凌帝国。请尽情享用我的诸多美味吧！"
D.Strings[18786]="准备启动微型机动战鸡！"
D.Strings[18787]="别喊了，霍巴特，我就在这里。嘘！"
D.Strings[18788]="给你，一只“微型机动战鸡”。我一直都不明白，你是怎么想出这些怪名字的。"
D.Strings[18789]="格瑞里叹息着，眨了眨眼。"
D.Strings[18790]="是，钩锤博士。"
D.Strings[18791]="太好了。现在，离开超级凹陷裂变测试平台，向后退。一定要慢。"
D.Strings[18792]="谢谢你。现在，你可以看着我如何稳定这种极度不稳定的微型化处理程序。"
D.Strings[18793]="助手摇了摇头。"
D.Strings[18794]="这个发明将会一劳永逸地解决困扰锈水财阀的食物短缺问题，带来无尽的利润！"
D.Strings[18795]="我很快就会成为前无古人，后无来者的，最伟大的地精工匠！另外，那个导致海地精产生的疏忽根本不值一提。"
D.Strings[18796]="打开开关！"
D.Strings[18797]="格瑞里咳嗽了一声。"
D.Strings[18798]="呃，没错，霍巴特，一切都在你的掌控之中。"
D.Strings[18799]="非常正确的回答，格瑞里。你通过了今天的突击小测验。"
D.Strings[18800]="我我要打开开关了！"
D.Strings[18801]="格瑞里，你看到了吗？我已经成功在握了！"
D.Strings[18802]="全世界的杂货店主都要给我利润抽成！"
D.Strings[18803]="我要打开第二个开关了！"
D.Strings[18804]="等等……有问题！"
D.Strings[18805]="你在想什么？霍巴特，这只微型机动战鸡很不稳定。它在剧烈膨胀！"
D.Strings[18806]="我知道……我知道！超控开关？超控开关在哪儿？"
D.Strings[18807]="就是最右边的那个！赶快，霍巴特！它就要爆炸啦！"
D.Strings[18808]="我要按啦，格瑞里，我一直都是爱你的！"
D.Strings[18809]="按下超控开关！"
D.Strings[18810]="什么？！！！"
D.Strings[18811]="我们还活着吗？"
D.Strings[18812]="我们还活着，钩锤博士，全靠你的努力。"
D.Strings[18813]="当然，我亲爱的格瑞里。看看那个。微型机动战鸡的稳定性堪称完美！"
D.Strings[18814]="你脸上那是鸡蛋吗？"
D.Strings[18815]="好了，告诉我，“你一直都是爱我的”是什么意思，钩锤？"
D.Strings[18816]="我根本不明白你在说什么，格瑞里小姐。"
D.Strings[18817]="在这一点上，我们可以达成共识，博士。"
D.Strings[18818]="嗨，你还好吗，老板？霍巴特和我正在努力确保当卡亚矿石资源枯竭时，你还会有足够的库存产品。$B$B现在矿脉中的卡亚矿石只有这么多了，如果它们都被开采干净，我害怕卡亚可乐也就没有了。"
D.Strings[18819]="很高兴见到你，$n！$B$B我刚想问你是否对我带到卡亚罗贸易公司的这些产品感到满意？$B$B包括但不限于：卡亚可乐、变鸡器、胶囊盒、巨怪愚行天才帽、卡亚罗全能训练机豪华版、神奇地精射线、永不漏气的小马泳圈、大炸弹、NX-01型自动化战士和海地精。别对最后一个有任何想法。我只是奉命办事，与我无关。$B$B不管怎样，我现在还在研究几样新鲜玩意，你也许会有兴趣——比如微型机动战鸡和一个被我命名为九号实验品的小东西。"
D.Strings[18820]="嗨，$g朋友:姑娘;我们来搞定这个？"
D.Strings[18821]="看样子，这就是最后了，如果你有足够的胆量，那我也就有，$n。"
D.Strings[18822]="<大胖看起来很凶悍，但可以确认，他心里是害怕了。>"
D.Strings[18823]="我不和废物说话！"
D.Strings[18824]="你和我不是一伙儿的，甜心。"
D.Strings[18825]="我没有劝你回学校，现在我也不打算这么干。"
D.Strings[18826]="真有趣……我说的是你穿的这身“行头”。"
D.Strings[18827]="是的，我要再来一杯。快一点。"
D.Strings[18828]="这是贸易大王的聚会，甜心。只有受邀请的人才能参加！"
D.Strings[18829]="$n，是你吗？送你一句话：不要让贸易大王抓住你。他知道你在盯着他的位子。$B$B所有人都知道。"
D.Strings[18830]="蠢货？！我可不和如此无礼的人说话。你怎么敢这样！"
D.Strings[18831]="我们应该管你这种家伙叫什么？蛮子？巨怪？$B$B我可受不了你这种人。赶快离开这里。"
D.Strings[18832]="你又大又强壮。但你需要好好洗个澡。赶快跳到池子里去吧。"
D.Strings[18833]="哦，不，别和我说话！"
D.Strings[18834]="这里是什么气味？哦，是你啊。$B$B快给我躲远点！"
D.Strings[18835]="你的名字叫什么？$B$B也许你这种蛮子还是当个哑巴比较好。否则我就只能向贸易大王投诉，告诉他你是多么令我讨厌。$B$B现在，离我远一点！"
D.Strings[18836]="再碰我一下，我就让他们送你去安德麦！"
D.Strings[18837]="哦，你可真让人讨厌！为什么来找我的总是你这种丑家伙？！"
D.Strings[18838]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B$G爸爸:妈妈;……？"
D.Strings[18839]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B我饿……是的，我饿。"
D.Strings[18840]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B“$c”是什么意思？你是地精族长吗？"
D.Strings[18841]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B他们管你叫$n。这是你特有的名字吗，还是你的一个荣誉称号？"
D.Strings[18842]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你好，我刚从一颗蛋里爬出来。你呢？"
D.Strings[18843]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你真的要把你吃的肉烤熟吗？真奇怪。"
D.Strings[18844]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你没有戴头盔。这会让你的智力变弱吗？"
D.Strings[18845]="<令你惊讶的是，这头小迅猛龙似乎是想和你说话。>$B$B你的指头尖又圆又钝。所以你要用别的东西进行战斗吗？$B$B真是有趣。"
D.Strings[18846]="$n？！你还在这里干什么？$B$B你必须离开这座岛，否则就进入我的胶囊镇！$B$B别再耽误时间了，我的孩子！浩劫就要降临在我们头上了！"
D.Strings[18847]="我还是小孩子的时候，我的父亲就已经在训练我该如何尊敬元素。大地和烈火，疾风和海洋——它们都具有无比强大的能量，$c。$B$B<格朗迪的眼睛里闪过一丝光芒。>$B$B那是你没有能力去认知的能量。"
D.Strings[18848]="看吧，哭泣吧。"
D.Strings[18849]="看到了吗？什么也无法阻挡我的战锤的力量。"
D.Strings[18850]="我是一名哲人。这意味着我比你更聪明。现在，离开吧，不要等我废黜你的时候再后悔。"
D.Strings[18851]="啊！$b$b你来得正是时候。$b$b我已经等了你好几天了。$b$b竟然把一个老矮人丢在这个闷热的地方……就算是训练新兵也比这个好。"
D.Strings[18852]="灰影墓穴在这边，跟我来，$n。"
D.Strings[18853]="这边！"
D.Strings[18854]="那么，那些物资会在哪里？"
D.Strings[18855]="也许它们就在这里？"
D.Strings[18856]="不，不在这里。"
D.Strings[18857]="嗨，帮我一把，$n！我找不到摩尔多需要的那些物资了！"
D.Strings[18858]="让我看看……它们会在……"
D.Strings[18859]="干得好！你找到它们了。我们把它们送到摩尔多那里去吧。"
D.Strings[18860]="我看到有人吃惊得下巴都掉下来了。不知道摩尔多能不能把他的下巴放回去？"
D.Strings[18861]="何必大费周章，其实你要做的只是……"
D.Strings[18862]="……砍一下而已！"
D.Strings[18863]="离我远点儿，你这怪物！"
D.Strings[18864]="亡灵是艾泽拉斯的腐蚀之源！你们这些家伙都该被毁灭！"
D.Strings[18865]="不。你在撒谎！父亲会保护我的！"
D.Strings[18866]="我不是什么畸形的怪物，我只是个亡灵。我想和你谈谈。"
D.Strings[18867]="莉莉安，你有没有意识到自己也是个亡灵？"
D.Strings[18868]="退后，怪物。想打架吗？因为我就是来大打一场的。$b$b我会把你们这些怪物都打得落花流水！听懂了吗？"
D.Strings[18869]="喔，真的吗？$b$b好的。我不想与你和你的被遗忘者为伍。也许我会创造属于自己的被遗忘者！也许我会创造出肘部会动的被遗忘者！"
D.Strings[18870]="你叫谁怪物？你才是怪物！我只是个死去的正常人。"
D.Strings[18871]="我不是来打架的。我只是奉命前来与你交谈。"
D.Strings[18872]="你想做什么都可以。"
D.Strings[18873]="什么……发生什么事了？你是谁？我这是怎么了？"
D.Strings[18874]="我……死了？$b$b是的，你说得没错。我是死了。有个兽人……他切断了我的双手，任由我死去。$b$b<瓦德雷看着自己的手。>$b$b这不是我的手！这不是我的手！"
D.Strings[18875]="<瓦德雷看着自己的手。>$b$b我想这就是我的命。哈！成为亡灵大军的一员。我怎么也没想到，自己最终竟然会为被遗忘者战斗。$b$b<他抬头看着你。>$b$b我现在还有什么选择？"
D.Strings[18876]="我明白了。那好，我们开始吧，$n！黑暗女王需要我们，对吗？"
D.Strings[18877]="你不记得了吗？你死了。"
D.Strings[18878]="别激动，瓦德雷。这可能是送葬者摩尔多为你缝上的新手。"
D.Strings[18879]="你去问送葬者摩尔多。他会告诉你该怎么做。我知道的就这么多。"
D.Strings[18880]="这是你的大型见面会。我们要让你成为贸易大王，$n！$B$B出去显示你的权威吧！"
D.Strings[18881]="海盗？！你得来解决一下，长官！他们正在毁掉派对！"
D.Strings[18882]="这看起来可不怎么样，长官。"
D.Strings[18883]="老板，我们会想尽一切办法为你集齐一万亿杏仁币的！"
D.Strings[18884]="我们得尽快结束这里的事情，把你送到码头，趁贸易大王还没把我们大家甩在身后！"
D.Strings[18885]="喔，嗨，宝贝儿。对……我们得谈谈。$B$B稍后好吗？"
D.Strings[18886]="等你准备好，就可以开始了！我会紧跟新郎新娘，以防暮光之锤有任何图谋。$B$B你准备好了吗？"
D.Strings[18887]="瓦德雷·莫莱前来报到，长官！"
D.Strings[18888]="再一次问好。"
D.Strings[18889]="我知道通往丧钟镇的路。跟我来！"
D.Strings[18890]="很好，你还在。亡灵卫兵萨尔坦在哪儿？"
D.Strings[18891]="啊，他在这儿呢。"
D.Strings[18892]="我们动身吧，$n。萨尔坦说我们会撞见一些尸体。"
D.Strings[18893]="我想我在前方看见了一些尸体。走吧，$n！你负责搜寻和战斗。体力活儿交给我。"
D.Strings[18894]="认为你已经有能力应对艾泽拉斯地下城的挑战了？入内查究……"
D.Strings[18895]="哦可怜的小家伙，你从头到脚都裹满了沙子！在这片美丽的绿洲好好休息，恢复下体力吧。"
D.Strings[18896]="我明白，阿莱克丝塔萨已经对死亡之翼做出了判决。也许这场磨难终将在这里结束？"
D.Strings[18897]="好吧，$r。$b$b看起来一切都还不错。"
D.Strings[18898]="我会留下，想办法释放这些蜘蛛。谢谢你的帮助，$n。"
D.Strings[18899]="你是来帮忙的，$c？让我们暂时待在一起。"
D.Strings[18900]="欢迎来到坠星村，旅者。你是来帮助我们的吗？"
D.Strings[18901]="我家几代人都是除虫高手！尽管我们只是普通的雇佣劳工……"
D.Strings[18902]="古加尔老板可不会喜欢这样！"
D.Strings[18903]="这就是你的下场！死吧！"
D.Strings[18904]="罗姆欧格很抱歉……"
D.Strings[18905]="拉兹很厉害！"
D.Strings[18906]="拉兹……累了……"
D.Strings[18907]="异教徒！你要为你的罪行受到惩罚！"
D.Strings[18908]="使你获得真理启迪的途径只有一条，那就是死亡！"
D.Strings[18909]="浸沐在主人的力量中！化作主人怒火的使徒！"
D.Strings[18910]="为了主人，我万死不辞，万死……"
D.Strings[18911]="又能测试我的武器了！"
D.Strings[18912]="不过是合金中的杂质……"
D.Strings[18913]="感受这灼热吧！"
D.Strings[18914]="我们的同伴无穷无尽！你只是在白费力气……"
D.Strings[18915]="你们来寻找答案吗？来吧！用你们的生命来索求吧！"
D.Strings[18916]="主人的世界中没有你们的位置。"
D.Strings[18917]="大地可以被重铸……你们却不能！你们毫无价值！"
D.Strings[18918]="我不会被毁灭……你们……只是在拖延……"
D.Strings[18919]="拉兹，不——！"
D.Strings[18920]="你可以在奥达希尔找到训练师，$n。"
D.Strings[18921]="黑丝洞就在北面。多加小心，那里近来危机四伏。"
D.Strings[18922]="月亮井在东北面，在水池另一侧的山上。"
D.Strings[18923]="通往奥达希尔的梯道就在那边。盘旋而上就能找到特纳隆。"
D.Strings[18924]="埃沃隆身上的毒素已经散去，但还需要一些时间才能复原。"
D.Strings[18925]="腐坏的种子已深植在他体内。"
D.Strings[18926]="他们当然已是无可挽回，但看着他们死去，还是令人感到心如刀绞。"
D.Strings[18927]="我亲爱的朋友们……我很抱歉……"
D.Strings[18928]="他的躯体在渴求死亡，可他的灵魂却在渴求怜悯。"
D.Strings[18929]="腐化的程度远非这些蜘蛛力量能及。我担心真正的源头并不在这洞穴之中。"
D.Strings[18930]="我为我们犯下的这些罪行而哭泣。简直令人难以忍受。"
D.Strings[18931]="如此程度的腐化不可能源自外部。"
D.Strings[18932]="他体内的腐化仿佛是与生俱来的。"
D.Strings[18933]="抱歉，女猎手。我们的新$c都还没准备好。他们还有许多东西要学。"
D.Strings[18934]="恐怕我们并没有时间优势，伊尔萨莱恩。如果我们不尽快开始行动，就连泰达希尔也将难逃战火的席卷。"
D.Strings[18935]="我们会让你继续你的训练，伊尔萨莱恩。在这方面你才是行家。"
D.Strings[18936]="好好学习吧，$n。在下个月满之夜到来之前，我们可能会需要你协同作战。"
D.Strings[18937]="我听说多亏了你的帮助，我才得到了治愈。谢谢你。衷心地向你表示感谢。"
D.Strings[18938]="这个图腾正在腐蚀这些蛋！这后面很可能隐藏着一个更加巨大的威胁。瘤背一族仍然在遭受某种极端邪恶的污染。"
D.Strings[18939]="我们要做的，就是部署卡拉兹工坊微型机场，然后开始例行考察任务。$B$B我被白痴包围了！"
D.Strings[18940]="我奉命前来调查藏宝海湾近来出现的怪事。这座地精之城出人意料地经受住了一场巨大海啸的考验，鉴于其以地精工程学而著称的美名，这就更加令人觉得不可思议。没想到这地方居然没有被巨浪冲垮。$b$b我怀疑在这里有什么魔法力量在作怪。你对藏宝海湾的了解也许远远不够，$c……"
D.Strings[18941]="你准备好离开荆棘谷了吗？"
D.Strings[18942]="哎呦！$b$b怎么就不能顺利一次？！"
D.Strings[18943]="干得好，$g小伙子:小姑娘;。$b$b你让通往储藏室的路变得畅通无阻。"
D.Strings[18944]="我带来了乌瑞恩国王的问候，$c。在我身后是“英雄的召唤”公告牌——暴风城国王在此向来自各地的冒险者昭告，哪里才是他们异禀天资的用武之地。如此，英雄们可以更好的为联盟贡献力量。"
D.Strings[18945]="Lok'tar，$c。在我身后是“酋长的命令”公告牌——我们的领袖向部落的成员们发出指引。它会告诉你，哪里才是你出色战技的用武之地，以更好的帮助部落对抗我们共同的敌人。"
D.Strings[18946]="选择目的地。"
D.Strings[18947]="银色黎明同胞兄弟们的牺牲必须被永远铭记。他们信仰黎明，尽管没人能活着看到圣光重新照亮这片土地。"
D.Strings[18948]="你的生命终结了！"
D.Strings[18949]="欢迎你，我的$g兄弟:姐妹;。如果你是来接受训练的，我将非常愿意将本领传授与你。$B$B在玛法里奥的注视下，我们现在和将来都会是平衡的保持者。永远牢记这一点。"
D.Strings[18950]="佩波跳来跳去，充满希望地抬头望着你。他显然记得你是谁。"
D.Strings[18951]="从这地方逃离比我预想中还要难。$B$B当视野之中看不到出路时，你该往哪里走？"
D.Strings[18952]="这台挖掘机有些生锈了，可看起来还能使用。"
D.Strings[18953]="你为什么要跟我说话？跟我比起来你简直就是个穷光蛋。$B$B去找你的同类吧，伙计。"
D.Strings[18954]="<岑塔布拉大笑起来。>$B$B是我们散播的那些谣言，朋友。目的是要让扎拉赞恩和其它人远离我们。别相信你所听到的任何事。$B$B不，我们刚接触那门艺术不久，几年前才开始学习。但从某种程度上来说，我们毕生都在准备响应召唤……"
D.Strings[18955]="我们当中有些人曾是祭司或巫医。就像扎拉赞恩……$B$B<岑塔布拉的视线飘向南方，神色变得严峻。>$B$B我们以为是自己惹怒了神祗，完全没怀疑过是扎拉赞恩在慢慢阻断我们之间的联结。我们知道他很强大，但没想到竟会这么强……当他的巫毒妖术蔓延到其它岛屿时，我们已无力阻止他。"
D.Strings[18956]="<岑塔布拉闭上双眼，摇了摇头。>$B$B当沃金号令所有人逃离时，我们……我们深感无颜面对宗族。于是我们逃向了南方，藏进了那片未开化的丛林群岛。$B$B那里的野兽当晚就夺去了我们几个同伴的生命。我们在岛屿中部的深邃洞穴中找到了栖身之所，但我在那里的梦境并不安宁——我看到了幻像！"
D.Strings[18957]="<岑塔布拉猛地转向你，她的眼睛闪烁着光彩，獠牙外露的大嘴现出微笑。>$B$B这真是我的记忆中最为广袤狂野的丛林！古老的迅猛龙之神，赞达拉传说中伟大的猎手贡克竟然出现在我面前！$B$B那位迅猛龙的英灵同我交谈，将我的灵魂带到了一个被称为翡翠梦境的地方。像回音群岛的其他神灵一样，那位英灵被扎拉赞恩的魔法困住了。但这位古老的英灵还是穿过扎拉赞恩的妖术，将我带到他身边。"
D.Strings[18958]="扎拉赞恩无意识的奴仆们正在这些岛屿上屠杀动物，烧毁植被。贡克需要我们去拯救这片群岛。因为扎拉赞恩的阻碍，我们还无法汲取神灵之力，所以贡克传授给我们一个新的方法，能够与所有自然之灵建立联系。我们将借助全部神灵的力量，而不再只是某一位单独的神灵。$B$B一开始，这样做会很难，朋友。但贡克已经让我们懂得，该如何进入翡翠梦境，直接与那里的神灵对话，向他们学习技艺！"
D.Strings[18959]="<岑塔布拉笑了。>$B$B其他神灵，特别是希瓦拉尔，对他的计划颇不以为然。他们仍然希望我们一次只敬拜他们之中的一位，而不是同时与全部神灵沟通。但贡克对他们施加了很大压力。而且他们都明白，这是从扎拉赞恩手中拯救群岛的唯一办法。$B$B我相信，贡克也不很在意其他神灵的意见。当我们在神灵那里进行学习的时候，他一直在嘲笑他们。"
D.Strings[18960]="我们之中的许多人都一直在侍奉这些神灵，早已熟悉了他们的形态。但在同诸神灵交流的练习中，我们还是渡过了许多个月亮的轮回。这并不容易，幸好除了教导我们的神灵们之外，翡翠梦境本身就是一位强大的教师……它会让一切事情以更快的速度演进。$B$B扎拉赞恩对我们造成了巨大的威胁。虽然神灵们在帮助我们，让我们掌握了新的技艺。但在过去几年，他的妖术和他无脑的奴仆们还是杀死了几名我们的兄弟姐妹。但我们终于保住了这些岛屿上的生命。当沃金和暗矛部族回归时，我们知道，彻底消灭扎拉赞恩的日子到了。"
D.Strings[18961]="是的，朋友，至少现在还是这样。他们对于教导更多我们的族人并不热心。但只要我们还在维护这些岛屿上的生命茁壮生长，他们就会继续帮助我们。当扎拉赞恩灭亡，贡克离开的时候，他告诉我们，如果其他神灵不遵守契约，该如何与他取得联系。$B$B我希望这样的事情永远不要发生……但为了以防万一，我们还是和塞纳里奥议会建立了联系。$B$B<岑塔布拉发出一阵狂野的笑声。>$B$B哦，你真应该看看那些暗夜精灵的表情……"
D.Strings[18962]="在渗入尼斐塞特边境的行动中，我大部分兄弟都倒下了。$B$B他们决不能白白牺牲，对此我责无旁贷。"
D.Strings[18963]="痊愈吧，$g兄弟:姐妹;！"
D.Strings[18964]="我在全力治疗你！"
D.Strings[18965]="让圣光拥抱你！"
D.Strings[18966]="在圣光的照耀下焕发新生！"
D.Strings[18967]="继续战斗，$G兄弟:姐妹;！"
D.Strings[18968]="我需要治疗，兄弟！"
D.Strings[18969]="发挥你的作用，快治疗我，帕克斯顿！"
D.Strings[18970]="我需要治疗！"
D.Strings[18971]="祝你好运，英雄！"
D.Strings[18972]="我无惧邪恶！"
D.Strings[18973]="生命不息，战斗不止！"
D.Strings[18974]="我……我很好！我很好！"
D.Strings[18975]="你是$n！人人交口称赞的大英雄！谢谢你！"
D.Strings[18976]="你好啊，$n。我们正需要你的帮助。"
D.Strings[18977]="我帮不了你，$c。"
D.Strings[18978]="我是这次行动的负责人。$B$B我可不想听到有人因为我们的运输工具爆炸，或者是敌人比我们高之类的无聊事情而抱怨。我们是专业人士，要一丝不苟地完成工作。"
D.Strings[18979]="<军情七处的密探失去了意识。>"
D.Strings[18980]="嗨，一定不要走进那个冒烟的地方！上一个不幸的$r就是因为无法承受那里的高热而完蛋的。$b$b那可真是个可怜又美味的$r。"
D.Strings[18981]="请不要让一个兽人认为你是蠢货。我这里的日子不好过，如果你能安静一点，我会很高兴的。"
D.Strings[18982]="剿灭纳兹夏尔和她的爪牙是我最想去做的事，但我也需要有人掩护……"
D.Strings[18983]="现在我最想去做的就是亲手消灭那个女巫。但我需要有人帮我挡住那些偷袭的纳迦……$b$b不要让我失望，$n！"
D.Strings[18984]="我们赶快将这里清理干净，把这些小子弄出去。我还有事要做。"
D.Strings[18985]="继续前进吧，朋友。$b$b等我的力量恢复以后，我会自己出去的。"
D.Strings[18986]="我能为你做些什么，$n？"
D.Strings[18987]="哦，僵尸？"
D.Strings[18988]="胶囊镇已经成功地安置下来了，$n。"
D.Strings[18989]="那些僵尸的速度很慢。射击他们就像打火鸡一样容易！"
D.Strings[18990]="一个胶囊镇，太好了！$B$B需要进行训练吗，$n？"
D.Strings[18991]="一个胶囊镇，太好了！"
D.Strings[18992]="他们怎么敢把我们的人民变成僵尸，还让这些可怜人反过来攻击我们！$B$B你一定要去狠狠踢爆他们的屁股！在此之前，你需要进行训练吗？"
D.Strings[18993]="保持聚变核心的稳定几乎耗尽了我的全部计算能力。$B$B现在我们只能希望那个浮点错误已经在我的上一次维护周期中被排除了。"
D.Strings[18994]="一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？$B$B需要进行训练吗？我年轻的追随者？"
D.Strings[18995]="一个胶囊镇。难道我们不是这个世界上最伟大的工匠吗？"
D.Strings[18996]="地精僵尸？地精僵尸！$n，去消灭那些俾格米人！$B$B在你出发前，需要进行一些训练么？"
D.Strings[18997]="地精僵尸？地精僵尸！$n，去消灭那些俾格米人！"
D.Strings[18998]="干得漂亮，$n。是你让这个地方活起来了！"
D.Strings[18999]="一定要对那些俾格米人采取行动，$n！"
D.Strings[19000]="曾经有一段时间，我可以对那些想要见我主人的家伙们予取予求。但现在，我的主人会接纳任何想成为他学生的人。他们能够通过他的传送门随意往来。$B$B我不会质疑他的命令，但这实在让我感到很苦恼。现在我的乐趣只剩下了让你们穿上可笑的衣服，或者看看你们的那副可怜相。但这些也已经让我感到无聊了……$B$B我对这种生活感到极度厌烦！走吧，赶快走。和别人去分享你的郁闷心情吧。"
D.Strings[19001]="你打算在这个地方花多少钱？"
D.Strings[19002]="不管是否产生于地精，僵尸在圣光的眼中永远都是憎恶的存在。而且，你绝对不可能和他们做买卖。$B$B至少现在还不行。"
D.Strings[19003]="荒野之中的城镇。我喜欢这样！"
D.Strings[19004]="你能不能在暗中靠近僵尸？难道当你靠近的时候，他们闻不到你脑子的气味ie？$B$B不过，这里大概有半数人已经不必担心这种事了"
D.Strings[19005]="全能战士NX-01型处于离线状态。"
D.Strings[19006]="那个司克诺兹是个疯子！我绝对不会回去！"
D.Strings[19007]="我主要研究两方面的问题：让微小的突然膨胀成巨大的；将巨大的放入微小的空间。$b$b今天你的需要又是什么？"
D.Strings[19008]="从坟墓中站起，向黑暗女王效忠！"
D.Strings[19009]="以女妖之王希尔瓦娜斯的名义，我将这份礼物赐予你！"
D.Strings[19010]="从死亡的沉眠中醒来，加入你们的同胞之中！"
D.Strings[19011]="醒来吧，沉睡者。新的生命正等待着你。"
D.Strings[19012]="你已经重生于世。女妖之王要求你的效忠。"
D.Strings[19013]="让我们看看，我刚才还看见了一个很适合你的下巴……"
D.Strings[19014]="这样就没问题了。如果它再掉下来，就回来找我。"
D.Strings[19015]="感谢你，送葬者。"
D.Strings[19016]="放松，朋友，我下手很快。"
D.Strings[19017]="我……我出了什么事？为什么你要这样对我？"
D.Strings[19018]="我应该是死了，就算是死了，我也会回来！"
D.Strings[19019]="这是希尔瓦娜斯女王干的？"
D.Strings[19020]="是什么样的魔法，竟然能挡住死亡之手？"
D.Strings[19021]="我……我想不起来了……为什么你们要这样做？"
D.Strings[19022]="我对黑暗女王有什么用？"
D.Strings[19023]="如果女妖之王给我这样的机会，我很愿意向她效忠。"
D.Strings[19024]="我从不想要这样！别来碰我！"
D.Strings[19025]="欢迎来到熔光码头，这座风景如画的海滨小城是爆炸狂们为爆炸狂建造的家园。"
D.Strings[19026]="欢迎来到艾维娜圣殿，$c。在这里，我们安坐于毗邻苍穹的世界之巅。"
D.Strings[19027]="我有许多信件，$n。其中大多数都是垃圾，但有一些对于像你这样有能力的$c来说的确会有些用处。这里有几封寄到永望镇的信，要在世界的这个遥远角落中寻找帮助。$b$b说实话，我觉得我根本没法选择自己的道路！好吧，让我们看看……"
D.Strings[19028]="这尊雕像实在是让人头痛。我本来设想，我们能用一台起重机和几次定向爆破让它浮出水面。但维克认为我们应该采取更加安全和能够减少损伤的办法，就是沿这道斜坡把它滚上去。$B$B现在可好了……我们把它的角度全都弄错了。就算我们把它弄到顶上，又能怎样？$B$B我有一种很糟糕的感觉，我们要在这里耽搁很长时间，很长很长的时间……"
D.Strings[19029]="按理说，既然我在暴风城港口做了这么多漂亮的工作，这个矮人总应该能对我有一点尊敬了……$B$B我只是想让这尊雕像沿斜坡而上，尽快复位。但她对于工作的每一步都抱怨个不停。实际上，她对每一个问题的解决办法都只有爆炸。我觉得她简直就是个侏儒或者地精。至少侏儒和地精还要比她更淡定一些。$B$B看看我们的工作队伍，简直一点纪律都没有。你知道是为什么？全都是因为她在捣乱！$B$B糟糕的态度，懒惰的工人……这样下去，工作根本没办法迅速完成。"
D.Strings[19030]="塞纳里奥议会已经有很长的历史了，朋友。而我们巨魔才刚刚成为其中的一员。"
D.Strings[19031]="欢迎回到桑德玛尔，$n。战火已经遍及这里的每一个角落，但只要有联盟的帮助，我相信我们一定能占据上风。"
D.Strings[19032]="你好，$c。我们蛮锤绝对不会亏待朋友。"
D.Strings[19033]="当艾萨拉还是精灵女王的时候，这里正是精灵皇室的都城之一。这里埋藏着让上古知识重现天日的关键，以及极具历史价值的古代遗物。"
D.Strings[19034]="队长和他的部队已经出发去夺取你曾经为他进行过侦查的一座基地了。你应该赶快去与他们会合。"
D.Strings[19035]="勇敢的巴特利在这个镇子里建立了狮鹫栖息地。如果你要骑乘狮鹫，就去找他吧。"
D.Strings[19036]="德鲁伊？我在这里从没有见过德鲁伊。不过我相信，你能在暴风城找到他们。你应该问问暴风城的卫兵。"
D.Strings[19037]="本杰明·福柯沃斯和他的宠物“狡猾”就在闪金镇铁匠铺的后面。也许你应该去看看他能不能帮你。"
D.Strings[19038]="萨满训练师？闪金镇可没有这种人。$B$B不过暴风城矮人区的蛮锤矮人也许能帮助你。"
D.Strings[19039]="很抱歉，$c，但上层精灵的奥术秘密是你永远也无法理解的。"
D.Strings[19040]="效忠龙喉兽人，你将得到丰厚的奖励，$c。"
D.Strings[19041]="和数千年前的魔法相比，今天的这点伎俩实在算不了什么。上层精灵掌握着许多强大的魔法。你是否已经准备好进行学习了？"
D.Strings[19042]="嗯，在卡拉诺斯，布洛兰·风须能送你去你想去的地方。"
D.Strings[19043]="哈鲁宾·霜锤，你可以在雷酒酿制厂找到这位蛮锤矮人。他能够传授你萨满之道。"
D.Strings[19044]="想要飞到别处去？安内特·威廉姆斯在镇子西部，她训练有素的蝙蝠能满足你的要求。"
D.Strings[19045]="旅店老板瑞尼已经把店搬到了镇中心的那个大房子里。那是布瑞尔最大的房子……你不会错过的。"
D.Strings[19046]="你觉得我像是懂法术的样子吗？不过，我听说凯恩·火歌就在那间实验室里，他总是喜欢鼓捣些让人不舒服的东西。"
D.Strings[19047]="啊，你在寻找黑暗牧师贝里尔。他就住在东边的那幢房子里。"
D.Strings[19048]="你要找飞龙之尾？就在勇者大厅外面。"
D.Strings[19049]="就在通向暗巷区大门的桥对面。仔细听那些地精的喊叫就能找到了。"
D.Strings[19050]="飞行管理员斯凯勒斯就站在通向永歌森林的大门前。"
D.Strings[19051]="你可以在能找到武器和盔甲的地方找到罗萨恩·银刃。一位战士绝对不会远离他的武器。"
D.Strings[19052]="在空中翱翔的自由是没有任何东西能与之相比的。如果你想飞上天空，可以和村子中央的双足飞龙管理员塔克聊聊。"
D.Strings[19053]="荣誉谷的银行就在通向暗巷区的大门前面。"
D.Strings[19054]="你找不到飞行管理员？波洛克就在镇子的南端，那些双足飞龙旁边。"
D.Strings[19055]="萨尔达恩把角鹰兽们照顾得很好。他们就在镇子的北部。"
D.Strings[19056]="如果你想要骑角鹰兽，就去找菲德利奥吧。"
D.Strings[19057]="上层精灵艾莉恩蒂就在这家旅店里。她能传授你奥术的秘密。"
D.Strings[19058]="有没有见过我最新的发明？它一定能让你大吃一惊……如果它没有爆炸的话。"
D.Strings[19059]="我需要一个GS-9x多功能机器人。"
D.Strings[19060]="%s准备对附近的敌人施放碎颅！"
D.Strings[19061]="一个暮光狂热者进化了！"
D.Strings[19062]="%s的护甲散发出热量。攻击！"
D.Strings[19063]="%s准备和他的一个影子交换位置！"
D.Strings[19064]="这座城市的附魔训练师那里有一位来访的上层精灵大法师。你可以在那里重铸你的物品。"
D.Strings[19065]="很高兴能得到你的帮助。"
D.Strings[19066]="我会在你的地图上标记出你要的地点位置。"
D.Strings[19067]="力量谷"
D.Strings[19068]="荣誉谷"
D.Strings[19069]="尼斐塞特城将要陷落！"
D.Strings[19070]="这只箱子一定已经在这里沉睡了千年之久。"
D.Strings[19071]="从深岩之洲回来之后，我们发现暮光之锤已经在这里建立起基地，控制了元素传送门。$B$B$n，请一定阻止他们，不要让古加尔在暮光堡垒中完成他的阴谋！"
D.Strings[19072]="拿上这块魔法碎片，$n。这样我就能通过和它匹配的另一块碎片亲耳听到矮人们的声音了。"
D.Strings[19073]="滚开！你不应该出现在这里！"
D.Strings[19074]="已经厌倦了你的恶魔仆从？希望能换一个名字更有趣的跟班？\n\n只要出一定的价钱，我就能帮你除去你现有的一个仆从，这样你就能召唤一个全新的恶魔了……"
D.Strings[19075]="放弃小鬼"
D.Strings[19076]="放弃虚空行者"
D.Strings[19077]="放弃魅魔"
D.Strings[19078]="放弃地狱猎犬"
D.Strings[19079]="你好，混蛋！"
D.Strings[19080]="就是这样，$n！这里就是我们的阵地！"
D.Strings[19081]="我们终于成功了。我们吉尔尼斯人从没有放弃过希望。"
D.Strings[19082]="看起来，这个传送设备最近被用来将物资传送到矿井深处。"
D.Strings[19083]="还没有完，$n。还早着呢。"
D.Strings[19084]="你要找新来的上层精灵？问我就对了。\n\n你可以在月神殿的西翼找到他们。他们之中的一个也有可能在风嚎橡树。"
D.Strings[19085]="啊……原来如此，原来如此。你就这样继续吧，直到你一命呜呼。"
D.Strings[19086]="我并不在乎听到这些，$n。你别想进入灼热峡谷，别想。这种事绝不会发生。我必须告诉你多少次，我不会让你进去！难道你不懂人话吗？难道你是伪装的兽人吗？不，绝不！$B$B如果我随便让你进去。用不了多久，你的朋友们也会想进去，然后是他们的远亲，他们的朋友，他们远亲的朋友，朋友的远亲。上次发生这种事……我们可不会讨论上次这种事发生时的情形。$b$b我是不会开门的！"
D.Strings[19087]="一个叫维图斯·暗行者的吉尔尼斯人能帮助你。你可以在风嚎橡树找到他。"
D.Strings[19088]="欢迎来到稻草人庆典，$c！$B$B按照万圣节的习俗，我们要焚烧一个稻草人，以代表我们对自我内心的净化。如同森林在秋天洒落枯叶，我们也必须抛弃自身枯萎的那一部分——恐惧、悲哀、憾恨。将枯枝投入烈火，代表着你抛下了不应带入冬天的重担。$B$B请从大篝火中拿起燃烧的枯枝，加入我们的庆典吧！"
D.Strings[19089]="你能感觉到这个地方的污染么，$c？它来自于暗影堡深处。如果不加以阻止，它会将这里的一切吞噬。$B$B我没有多少时间了，$n。只有你能帮助我及时阻止它的蔓延。$B$B<这名受伤的暗夜精灵咳嗽着，移开手，露出肋侧的血污。>"
D.Strings[19090]="只有部族中最勇猛，最具荣誉感的成员才能安息在赤色石。"
D.Strings[19091]="虽然许多火焰都经历过反复争夺与易手，被熄灭又被重新点燃，但所有人都可以去祭拜它们，$c。$b$b在大地之环中，我们只对火焰进行祭拜，不做其它任何轻率愚蠢的事。$b$b我们依照传统举行祭拜仪式。你会加入我们的仪式吗，$n？"
D.Strings[19092]="你到达了大地之环大篝火！"
D.Strings[19093]="有个可恨的加德纳尔恶魔发现了我！还在我的身侧划了一条大口子。这道伤口不浅，但我还能活下去。$B$B还有更要紧的事情要办，暗影议会将对我们在野性之心哨站的朋友们发起全面进攻。我现在没法战斗了，所以你必须代替我去阻止他们。"
D.Strings[19094]="$c，万圣节到了。希望你能在这个节日中找到许多欢乐。"
D.Strings[19095]="你好！真是令人愉悦的一天啊，对不对？"
D.Strings[19096]="<多德轻蔑地向你哼了一声。>$B$B你的动作还能再慢一点吗？我身边都是没用的白痴！"
D.Strings[19097]="嗨，我们以前见过吗？"
D.Strings[19098]="欢迎来到治愈者营地，$c。"
D.Strings[19099]="你在看什么？你这个海象脑袋的笨蛋？"
D.Strings[19100]="呀！"
D.Strings[19101]="我的佣人哪？！"
D.Strings[19102]="恐怕关于老邓肯的故事只会让人徒增伤心。知道吗？我曾经是一名真真正正的船长。$b$b但现在只要再降一级，我就又要去洗甲板了。我可没办法承受这样的耻辱。"
D.Strings[19103]="虽然我非常想念吉尔尼斯，但还有许多远古遗迹需要我去探索！"
D.Strings[19104]="财宝猎人的人生中充满了背叛与欺骗。别再犯傻了。"
D.Strings[19105]="在托尔巴拉德，我们在巴拉丁监狱的兄弟都很忙，并非总是能及时为你提供援助。现在我驻扎在这里，就是为了帮你完成由他们分配给你的任务。"
D.Strings[19106]="托尔巴拉德的战斗准备将在5分钟后开始！"
D.Strings[19107]="托尔巴拉德的战斗将在2分钟后开始！"
D.Strings[19108]="托尔巴拉德的战斗将在1分钟后开始！"
D.Strings[19109]="托尔巴拉德的胜利是我们的囊中之物！部落的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！"
D.Strings[19110]="托尔巴拉德的胜利是我们的囊中之物！联盟的防御已经崩溃，我们需要你立即去收集资源并参与保卫这座岛屿！"
D.Strings[19111]="你够格待在我的厨房里吗？"
D.Strings[19112]="见识过这里可怕的物价了吗？"
D.Strings[19113]="能给我拿些喝的来吗？我正在晒日光浴，没法去拿饮料。"
D.Strings[19114]="我眼前朦朦胧胧的，什么都看不清，但我很清楚这股气味！去死吧，肮脏的食人魔！"
D.Strings[19115]="哦…………"
D.Strings[19116]="老杜甘要去瘟疫之地，把那些天灾恶鬼全都赶回到地里去。"
D.Strings[19117]="风把死亡的气息带往所有地方，一切都因之而凋敝。"
D.Strings[19118]="当他到了那里的时候，他的矮人眼睛会看到什么？"
D.Strings[19119]="那里有上百箱的大麦会被酿成美酒！"
D.Strings[19120]="但那些美酒受到了死亡的诅咒，现在，老杜甘也被诅咒了。"
D.Strings[19121]="老杜甘被巫妖王的爪牙包围了，老杜甘能做些什么？"
D.Strings[19122]="虽然我感觉到了体内的诅咒，但是我的希望并没有泯灭。"
D.Strings[19123]="如果我真的会成为天灾恶鬼，那我最好还是先喝醉了吧！"
D.Strings[19124]="这个传送器将把你传送至北荆棘谷的格罗姆高那里。$B$B通常都会是这样。$B$B我的意思是说，有时候它会把你分解，或者让你全身的软组织都变成散发着臭气的绿色烟雾。不过大多数情况下它还是安全的！$B$B……大多数情况。"
D.Strings[19125]="这个传送器将把你传送至丹莫罗地下深处，那个充满辐射的诺莫瑞根废墟。$B$B别担心，那里还有另一个传送器，可以把你送回到这里……嗯，它也有可能让你身体的里里外外彻底翻转过来，或者把你全身的组织变成不稳定的有机爆炸物，就是这样！$B$B怎么啦？你还在等什么？跳进去吧！"
D.Strings[19126]="看到了吗？有人从天上掉下来了！"
D.Strings[19127]="布温巴能帮得上你吗？"
D.Strings[19128]="你在寻求力量？但你能走过我铺下的诅咒之路吗？"
D.Strings[19129]="我的道路是黑暗的，受到诅咒的。$c，你不会想要和我同行的。"
D.Strings[19130]="你能在城市正中，圣光广场中心的建筑物里找到沙塔斯的公会管理员——以及公会和战袍商人。"
D.Strings[19131]="职业训练师都在圣光广场中心建筑物一层的各翼区中。$B$B无论是奥尔多，占星者还是其他什么人，总有人能帮助你的。"
D.Strings[19132]="<奥术守护者指了指城市中心。>"
D.Strings[19133]="布温巴正在盯着你，年轻人。"
D.Strings[19134]="萨满祭司……？一个神秘的巨魔最近来到这里拜访长者步道的哈雷尼。她也许能帮助你。"
D.Strings[19135]="全部前往北方灰谷的运输队都会在这里停留，休息并补充食水。确保这里一切工作正常是非常重要的。"
D.Strings[19136]="欢迎，我的$g兄弟:姐妹;。如果你是要来接受训练，我很高兴能满足你的要求。"
D.Strings[19137]="如果你在寻求古老的技艺，那我无法帮助你。"
D.Strings[19138]="城门外有一个名叫达伦斯的狼人德鲁伊。他也许能帮助你。$B$B他是一头高大的猛兽，身披白色皮毛。你不可能认错他的。"
D.Strings[19139]="你好！需要拧紧螺丝或者松开栓钉吗？你可是来对地方了。"
D.Strings[19140]="黑暗女王在注视着你。"
D.Strings[19141]="来自艾泽拉斯各地的手工玩具！"
D.Strings[19142]="啊！是你啊，$n。$b$B我必须马上和你谈谈。"
D.Strings[19143]="欢迎来到冰锥甜筒，朋友！我们的冰激凌味道独一无二，冰寒爽口，是暴风城最优秀的法师学徒特别定制的！"
D.Strings[19144]="你准备好面对涅墨西斯了吗？我希望你能善用你的图腾。$b$b当你需要召唤他的时候跟我说一声。"
D.Strings[19145]="别再等待了，$n。$b$b阿纳克洛斯正在等你！"
D.Strings[19146]="轻松点，凡人。我们必须在不紧张的情况下有效交流。$b$b当然这主要取决于你是否思路清晰且明辨事理。"
D.Strings[19147]="你好，$c。我的名字是索克。以酋长的名义，我指挥这里的防御。$B$B你已经在十字路口立下了许多功绩。继续为部落而奋战吧！"
D.Strings[19148]="想找深山珠宝矿业协会，去大锻炉北侧吧。"
D.Strings[19149]="你可以在战士区找到铁匠和他的助手，就在护甲和武器供应商附近。"
D.Strings[19150]="起码还有一个吉尔尼斯工程师在工匠区工作，她应该能帮上你。"
D.Strings[19151]="你是要找工匠区的银露一家人吗？他们最近才在附魔商店附近开起了自己的小店。"
D.Strings[19152]="有二个熟练的矿工从吉尔尼斯瘟疫中成功逃了出来，来到这里，你可以在工匠区找到他们。"
D.Strings[19153]="这些巨魔没完没了，$c。"
D.Strings[19154]="很高兴见到你，$n。你是来帮我们击退敌人的吧？"
D.Strings[19155]="元素大军无穷无尽。如果得不到援助的话，我们恐怕没办法守住这个突破口。"
D.Strings[19156]="要独自开动并驾驶蒸汽坦克可不是件简单的活儿，但总得有人去做。"
D.Strings[19157]="我需要另一个狼獾人孤儿哨。"
D.Strings[19158]="当时你把石板带来给我，我就该把它们摔碎的，$n，可我没有。在此危难的时刻，我们仍需要国王的智慧来指引我们。"
D.Strings[19159]="它是红寡妇，贝丝缇拉克的子嗣。她的其他小崽子们一定会来给它们的兄弟报仇的。"
D.Strings[19160]="我们必须阻止赞达拉，艾泽拉斯所有的巨魔都联合起来听从统一的指挥，这对我们所有人都是巨大的威胁。"
D.Strings[19161]="你好，$c。这些德鲁伊都曾是我们的兄弟姐妹，可现在他们已经被炎魔之王变成了熔岩的化身。现在，烈焰德鲁伊们就在执行他的疯狂计划，试图烧毁世界之树。我们绝对不能让他们得逞。"
D.Strings[19162]="这场战争令我心情沉重。我正带领着我的人民走向死亡。但如果我们现在不站出来反抗拉格纳罗斯，将来又怎么能抵挡得住奈萨里奥呢？$B$B我们必须为自己所拥有的一切而战，否则就只能眼睁睁看着世界毁灭。"
D.Strings[19163]="杀死高阶祭司，一切都安全之后再来找我，我就可以带着我的报告回到血卫士身边了。"
D.Strings[19164]="你是来帮助暗矛部落的吗，$c？"
D.Strings[19165]="感谢你，$c。我以为我要被献祭了……"
D.Strings[19166]="我是来自暗矛巨魔的使者。我们面临的威胁也同样是联盟的威胁。你愿意帮助暗矛氏族吗，$r？"
D.Strings[19167]="感谢你，$c。$b$b如果我能帮你做什么，尽管告诉我。"
D.Strings[19168]="这个地方散发着死亡和祭品的恶臭。$b$B在你成为下一个囚犯前赶快离开吧。"
D.Strings[19169]="能从笼子里出来真好。洛尔卡尼要复仇……"
D.Strings[19170]="我在哪里？你是来帮忙的吗？"
D.Strings[19171]="巨魔犯了一个巨大的错误，$c。"
D.Strings[19172]="你把我从笼子里救了出来，非常感谢。我神智总算逐渐清醒了，可以回去向沃金报告我掌握的情报了。"
D.Strings[19173]="我的灵魂与你同在，$n。"
D.Strings[19174]="灵魂状态下行走并不轻松。"
D.Strings[19175]="嘿，你好啊！我真是越来越喜欢你了！"
D.Strings[19176]="生存，是一切生物的本能。"
D.Strings[19177]="这下面比火炉还热！啊，我的脑袋上都可以煎蛋了。"
D.Strings[19178]="索罗……是你吗……？"
D.Strings[19179]="对火焰之地的突袭刻不容缓。我们必须尽快向拉格纳罗斯和范达尔发动反击。"
D.Strings[19180]="这些巨魔突然出现，向我们寻求帮助。"
D.Strings[19181]="我几乎不明白这些巨魔想说什么。"
D.Strings[19182]="这些巨魔就不能自己解决自己的问题吗？"
D.Strings[19183]="<那巨魔看着周围成堆的尸体，自顾自地唱着歌。>"
D.Strings[19184]="你做到了，$n，我很高兴。"
D.Strings[19185]="欢迎来到熔火激流，$n。"
D.Strings[19186]="前边的火妖可不是吃素的。小心点。"
D.Strings[19187]="前面有很多热排气口，$n。如果你不小心陷入困境，可以利用它们来脱困。"
D.Strings[19188]="洞穴的深处恐怕有一个迷失的德鲁伊，$n。你千万要小心。"
D.Strings[19189]="每一头蓝龙都会铭记你的英勇事迹，$n。"
D.Strings[19190]="这是个古老、宁静又安详的墓地。"
D.Strings[19191]="虽然这里显然是座坟墓，可没有写明葬在这里的是什么人。"
D.Strings[19192]="我可以传授烹饪的艺术。\n\n你想学吗？"
D.Strings[19193]="天呐，这里可真热。我连熔炉都可以不用带了。"
D.Strings[19194]="那边那座岛上到处都是黑曜石生物！我本该自己去的，可又过不了那座桥。"
D.Strings[19195]="哦，没错。我拿了点蜡烛。\n\n那么，你想要点什么呢？"
D.Strings[19196]="对我来说，能帮助普罗德摩尔女士进行研究是莫大的荣幸。要知道，她可是全艾泽拉斯最强大的人类法师！\n\n那么，你有什么要我帮忙的吗？"
D.Strings[19197]="就算这座塔里的藏书再多一倍，对我来说仍然不算多。我是不会停止收藏和抄录的。\n\n那么，你需要我帮忙吗？"
D.Strings[19198]="你是说，这儿有个术士？就在塞拉摩？！\n\n噢，天呐。我们必须立刻通知普罗德摩尔女士！\n\n……哼。"
D.Strings[19199]="随着所有的攻城坦克接近完工，我开始觉得有点无聊了！\n\n你不是工程师吧？愿意来比下图纸吗……"
D.Strings[19200]="欢迎来到我的厨房！\n\n你是想来买吃的呢，还是想来自己做点儿？"
D.Strings[19201]="你知道，我曾是探险者协会的成员。\n\n可后来我才发现，我其实只对宝石感兴趣。\n\n硕大、璀璨、艳丽、珍贵的宝石……噢，我是多么爱它呀！"
D.Strings[19202]="他是个宝石狂人，一点没说错，可我还是爱他。他说过，我是他最爱的那颗宝石，嘻嘻！\n\n那么，我能帮你什么忙呢？是有关考古学的事，对吗？"
D.Strings[19203]="<这根法杖充盈着奥术的能量。>"
D.Strings[19204]="沼泽盛产优质皮革，如果你够胆进去找的话。里面有很多鳄鱼。我和我兄弟就打算在这里呆一段时间。\n\n有什么要我帮忙的吗？"
D.Strings[19205]="欢迎光临塞拉摩岛。我能帮你什么忙吗？"
D.Strings[19206]="去和兵营第二层的出纳员兰德里谈谈吧。\n\n他会帮你安排，把物品存入塞拉摩的金库。"
D.Strings[19207]="到靶场附近去找杰森·法兰。"
D.Strings[19208]="霍拉斯·奥德尔就在普罗德摩尔女士的法师塔底层晃悠，你可以去那里找他。"
D.Strings[19209]="到兵营外的训练假人处寻找正在监督训练的卡尔曼修士。"
D.Strings[19210]="到兵营的拳击场去找阿伦·布莱特。\n\n他和古斯塔夫·范沃森医生正在监督岛上治疗者的训练。"
D.Strings[19211]="我不太确定。你可以到码头上去问问加莉亚·哈斯汀。我听说她和军情七处有联系。"
D.Strings[19212]="还有……那个……去中心塔楼底层找一个穿红色长袍的女人，但别说我派你去的。\n\n她叫雷迪亚·沃恩特。记住，千万别提我的名字。"
D.Strings[19213]="向兵营第二层的伊文凯恩队长报到。他将负责你的训练。"
D.Strings[19214]="炼金师纳瑞特和布兰特·加斯布鲁姆就在小作坊外面，他们可以教你炼金术和草药学，也许能帮上你。"
D.Strings[19215]="据我所知，这次到访的绒套家族矮人当中有一个考古学家。\n\n我想应该是那位太太，菲娜。他们都可算是探险者。到旅店去找他们吧。"
D.Strings[19216]="到铁匠铺去找玛蕾·霍斯顿。"
D.Strings[19217]="克莱格·诺瓦德就在旅店的厨房里工作。他可以帮你。"
D.Strings[19218]="丽萨·斯贝维克位于法师塔顶层，她是吉安娜女士手下的附魔师当中的佼佼者。"
D.Strings[19219]="到铁匠铺去找卡兹·双链。"
D.Strings[19220]="古斯塔夫·范沃森医生就在兵营的底层工作。"
D.Strings[19221]="码头上的迈克尔·克罗维可以教你捕鱼、剖鱼相关的各种知识。"
D.Strings[19222]="到普罗德摩尔女士的法师塔顶层去找瑟尔顿·曼勒斯。"
D.Strings[19223]="我敢肯定，次到访的绒套家族矮人当中就有一个珠宝匠。\n\n我想应该是那位丈夫，因格。他们都可算是探险者。到旅店去找他们吧。"
D.Strings[19224]="到塞拉摩的旅店里去找坦维尔兄弟吧。他们俩当中，应该有一个能帮你。"
D.Strings[19225]="到塞拉摩的铁匠铺外去找矮人科尔里克吧。\n\n他是个酒鬼，还喜欢乱用炸药。不过他很友好，而且对矿物有独到的理解。"
D.Strings[19226]="你可以去找珊莎·玛克温斯，她就在塞拉摩的兽栏外面。"
D.Strings[19227]="提莫斯·沃森特就在塞拉摩那座大型建筑的二楼工作。他应该能帮你。"
D.Strings[19228]="我是一个从事药学的兽人，$r。如果你是来学习的，我会尽我最大的努力教你。"
D.Strings[19229]="今天的风很奇怪，真的很奇怪。"
D.Strings[19230]="古拉巴什进攻者接连不断地涌来！我们被围困在这里好多天了，完全收不到来自外围哨站的情报。"
D.Strings[19231]="这是对你的审判。"
D.Strings[19232]="承认你的虚弱。"
D.Strings[19233]="你们不能进入主人的领地，凡人。"
D.Strings[19234]="我的熔岩之怒会烧尽你们！"
D.Strings[19235]="秉承炎魔之王的命令，你也会被毁灭！"
D.Strings[19236]="来到火焰的国度，就要付出血肉的代价。"
D.Strings[19237]="愚蠢的凡人。你们这是自寻死路。"
D.Strings[19238]="别担心，我会保护好火红鞭笞者的。但在我们熟悉它的习性之前，它恐怕只能留在火焰之地了。"
D.Strings[19239]="多么特殊的标本啊！具有如此之多的可能性！我一定要更加努力地研究当地的动植物了。"
D.Strings[19240]="在我埋头搞研究的时候，你可以教教鞭笞者处世之道。"
D.Strings[19241]="卡雷苟斯已经被推举为蓝龙军团的新守护巨龙。$b$b你们中的一位勇士曾帮助阻止了阿瑞苟斯倒向死亡之翼，从而避免了一场灾难。$b$b今天，我们欢聚一堂，以颂扬他们的英雄事迹。"
D.Strings[19242]="<暗影守望者静静地看着你。>"
D.Strings[19243]="大地在我们脚下战栗，呻吟。火雨从空中倾泻而下。生灵在炽热的空气中窒息。这才是炎魔之王的国度。"
D.Strings[19244]="我们还不能休息，孩子。海加尔还没有沦陷。但如果我们在炎魔之王的门前踯躅，仍有可能一败涂地。愿远古半神的力量与我们同在。"
D.Strings[19245]="风暴乌鸦很难在这种高密度的空气中飞行，可那边山脊上的火鹰翱翔起来却好像很轻松。$B$B它们和这片火焰平原上的其他生物一样狂野，但它们的形态却十分美丽。"
D.Strings[19246]="只要有足够的时间，我们就能恢复这片土地。"
D.Strings[19247]="我们只不过是勉强站稳脚跟而已。所以我们需要每一个健全的士兵全部到岗。"
D.Strings[19248]="除了挣扎求生，战争还有什么其他意义呢？就像种子要努力破土发芽一样，我们也要为自己的生存而战。"
D.Strings[19249]="我们能否赢得这场战争？只有天知道。"
D.Strings[19250]="这里可真闷热。有人让他们升高温度了吗？"
D.Strings[19251]="我喜欢你！青出于蓝啊。"
D.Strings[19252]="有人说我很土，可我觉得自己还挺睿智的。"
D.Strings[19253]="噢，又是你呀！你觉得，我们能召集到足够的部队吗？"
D.Strings[19254]="我从来没见过这么荒凉的地方。"
D.Strings[19255]="我们就站在贝丝缇拉克的产卵区中心。在北边那些柱子那边，就有她的子嗣。它们会拼命保护她的幼崽的。"
D.Strings[19256]="你关于守望者的一切疑问，都将在战场上找到答案。"
D.Strings[19257]="守望者是什么人？我们是精密的杀戮机器。"
D.Strings[19258]="守望者是什么人？我们是播撒死亡的旋刃。"
D.Strings[19259]="守望者是什么人？我们是无声的暗影。"
D.Strings[19260]="在你的帮助下，暗影守望者和猛禽德鲁伊站到了我们这边。$B$B干得好，$c。$B$B我们已经开始扩张了，但还有许多事要做。$B$B在敌人的持续攻击下，我们仍继续建造防御工事。我们需要三样东西，$n。$B$B老树干和远古的保卫者们正守护着海加尔，可这里也急需他们的力量。$B$B虽然我们士气正盛，可我们的军械库仍需要补充额外的军用物资。$B$B最后，艾露恩的神圣之水能够治愈我们的伤兵，并让他们重获新生。$B$B为了完成这里的任务，我们需要这些东西。$B$B去吧，$n。你的努力对我们取得胜利至关重要。"
D.Strings[19261]="你做得很好，$c。拉格纳罗斯已经不能再无视我们的存在了。我们已经成了他的心腹大患。虽然他已经怒火高涨，我们仍要继续推进。$B$B在这里，我们必须时刻保持警惕，但我们应该考虑一下最终的决战了。挑战炎魔之王本人的时刻到了。"
D.Strings[19262]="用你的眼睛去看。你看到了什么？你感觉到了什么？"
D.Strings[19263]="艾维娜之风，赐予我压制火焰的力量吧！"
D.Strings[19264]="在我们准备进攻火焰之地的时候，炎魔之王派出了手下爪牙来拦截我们。我们在这里的据点绝对不能陷落，我们已经是保卫世界之树的最后一道防线了。"
D.Strings[19265]="欢迎你，$n。你是来参加对火焰之地的进攻的吗？"
D.Strings[19266]="我们暂时还无力反攻火焰之地。首先，我们得重整部队，建立补给线。你愿意帮助我们吗？"
D.Strings[19267]="眼前所发生的一切与我们所有人都息息相关。每一分力量都是宝贵的。大家必须同心协力对抗入侵。"
D.Strings[19268]="有小动物吗需要我救助吗？$B$B<米露恩两眼放光。>$B$B我要立刻去抱抱小兔子！"
D.Strings[19269]="你好。大德鲁伊正在休息。$B$B我相信，你的造访一定会令他高兴的，但我们最好还是不要去打扰他。"
D.Strings[19270]="我需要一个真正有能力的人。我能指望你吗，$c？"
D.Strings[19271]="你好，法师。你愿意领略高深莫测的魔法世界吗？"
D.Strings[19272]="我能感觉到你对力量的渴望，$c。"
D.Strings[19273]="我们已经无路可逃了。该停下来战斗了。"
D.Strings[19274]="你是喜欢枪支还是弓箭？"
D.Strings[19275]="$n，我如何才能帮助你继续深造呢？"
D.Strings[19276]="如果你在寻求指导，恕我无法提供帮助。"
D.Strings[19277]="我的古伊尔……被大海吞噬了。在他自己的欲望中煎熬！"
D.Strings[19278]="循环又开始了！古伊尔变成了活生生的石头！我们必须到深岩之洲的洞穴里去找他。$b$b在亲眼看到大地之环拯救了她的国度之后，塞拉赞恩应该更愿意帮我们救他了。如果她不肯，那位石母必将付出代价！"
D.Strings[19279]="感觉到空气中的魔法能量了吗，$c？"
D.Strings[19280]="你是来参战的吗，$c？"
D.Strings[19281]="无论要走多远，我也绝不放弃他！"
D.Strings[19282]="我的力量只够传送一次。所以你一定要做好充分的准备。古伊尔在海底等着我们……"
D.Strings[19283]="孩子们都喜欢这个节日。有些孩子已经出去要糖果了，有些却只能留在这里。还有些孩子，比如你眼前这些，则想跟你们做个小小的交易。$b$b他们的目的是收集尽可能多的糖果，而他们想到的报酬就是送糖果给那些帮他们奔波的人。当我第一次他们说起这个打算时，都有点忍俊不禁，$c。可当我看到有那么多冒险者都愿意拿糖果来交换他们的小礼品时，我又开始担心了。$b$b他们拿到的糖果太多了。我担心孩子们从此再也睡不着觉了。"
D.Strings[19284]="我们已经耽搁得够久了。现在就对这个拉格纳罗斯的仆人动手吧。"
D.Strings[19285]="我们越早摆脱石母越好。我不相信她。"
D.Strings[19286]="请随意浏览这里的拍品。如果你有东西要拍卖的话，我也可以帮你办理。"
D.Strings[19287]="我要查看拍卖的物品。"
D.Strings[19288]="污秽的凡人……不能进入主人的城堡……"
D.Strings[19289]="做好准备。火焰之地非常危险……即使是像你这样强大的$r也不能掉以轻心。$b$b你准备好之后，就告诉我一声。"
D.Strings[19290]="真是太棒了！"
D.Strings[19291]="当然，我会和你分享我的智慧。"
D.Strings[19292]="<奥术守护者指了指先知的图书馆。>"
D.Strings[19293]="您可以随意浏览拍卖中的物品并出价。我还能帮你将想要出售的物品摆上拍卖架。"
D.Strings[19294]="让我查看一下拍卖的物品。"
D.Strings[19295]="我们需要所有元素的帮助才能救回萨尔。拉格纳罗斯的爪牙可没有赛克隆纳斯、海卓里斯或者塞拉赞恩那么好说话。"
D.Strings[19296]="都结束了……我不敢相信……$b$b古伊尔自由了，我对你感激不尽，$n。"
D.Strings[19297]="没错。我们海加尔山再见，朋友。"
D.Strings[19298]="欢迎来到林荫女士，这里有最好的美酒和异域商品，只此一家！"
D.Strings[19299]="你可以在奥尔多高地的南部找到铭文训练师，记录员利迪欧。"
D.Strings[19300]="技师米希拉就在奥尔多高地上。"
D.Strings[19301]="你可以在奥尔多高地的东部找到草药学训练师吉嘉。"
D.Strings[19302]="采矿训练师弗诺就在奥尔多高地上。"
D.Strings[19303]="你可以在奥尔多高地的东北部找到编织者欧尔。"
D.Strings[19304]="|TInterface\\Icons\\spell_shadow_curse.blp:20|t%s准备使用|cFF7A0080|Hspell:99352|h[毁灭之刃]|h|r！"
D.Strings[19305]="|TInterface\\Icons\\inv_sword_09.blp:20|t%s准备使用|cFFFF0000|Hspell:99350|h[地狱火之刃]|h|r！"
D.Strings[19306]="有件事我可以肯定，那就是你总是可以依赖你的好朋友。如果在你的生命中有这么一个人，请好好珍惜他。"
D.Strings[19307]="安伦是我最好的朋友。要是没有他在，我真不知道该怎么办了。"
D.Strings[19308]="我和索罗一起度过了无数难关。我知道他一定会为了我而格外留心。"
D.Strings[19309]="重回战场前我需要恢复我的力量。最好你也这么做。"
D.Strings[19310]="那些蜘蛛的个头就和……我一样大！你知道该怎么对付成群的蜘蛛吗？$B$B嗯哼，没错。炸弹。成堆的炸弹。"
D.Strings[19311]="从我们牛头人有记录起，关于强大的白色雄鹿的传说就一直在我们的文明中流传。从开天辟地的那一刻起，玛洛恩似乎就在守护着原始的森林了。他是一位古代神灵，是自然的伟力与纯洁的化身！$B$B很久之前，最伟大的牛头人猎人会在月落时分追寻这头白鹿的踪迹。据说，哪怕是从林间瞥见一眼他那闪光的毛皮，就可以给部族里整整一代人带来巨大的幸运。$B$B你知道吗，玛洛恩还是月亮女神的伴侣。"
D.Strings[19312]="是的，玛洛恩正是月亮女神的伴侣。暗夜精灵们称这位女神为“艾露恩”。他们两位结合后生下了塞纳留斯，那位所有德鲁伊共同的守护神，同时也是艾泽拉斯最强大的生物之一。$B$B但，听我说，我还没说完呢。$B$B玛洛恩是一股难以想象的自然之力，可他只有在生死关头时，才会响应凡间种族的呼唤。你听说过他在上古战争时期的事迹吗？"
D.Strings[19313]="干得漂亮，士兵。我需要你好好活下来。"
D.Strings[19314]="这些印记象征着尊重，是战场上挥洒热血的成果。如果想要赢得这场战争，我们必须收集足够多的印记。"
D.Strings[19315]="要想战胜拉格纳罗斯，我们就必须召集起那些敢于深入火焰之地这片焦土的盟友。但在召集这些盟友之前——不管他们是德鲁伊、士兵或者仅仅是后勤人员——我们都必须给他们一个加入我们的理由。$b$b哪怕你身上只携带着几枚这种印记，也足以说明你是我们这场事业中的英雄。如果你能收集到几百枚……那就足以统领大军。$b$b现在，你明白我们的计划了吗？"
D.Strings[19316]="在我身后，就是你刚进来的地方，有一个很大的排气口，里面喷出的热气流能够一直升腾到外面。你只要站在排气口上，然后……这么一跳！你跃起的动能就足以把你送到顶上去了。$b$b噢，还有一件事——根据我从其他德鲁伊那里打听来的情况看，你出去的时候，最好小心你的脑袋。"
D.Strings[19317]="当然。顺便说一句，你可以在洞穴的深处找到一些功能类似的小型排气口。慢慢的，你就能学会如何利用这些排气口更加便捷在洞穴中穿行——或者是如何利用它们去折腾那些没脑子的火妖。"
D.Strings[19318]="其实，我的导师莫希斯才是这方面的专家。不过我可以跟你说说我知道的情况。$b$b它们并不是鸟。当然了，它们也会飞，它们的翅膀上似乎也有羽毛，而且我们也管它们叫“鹰”，但那只是和鸟类对比后的称呼。实际上，它们和巨龙之间的相同点似乎更多：同样对火焰具有非凡的亲和力，同样喜爱独居，并且——据我们观察——具备一定的智力特征。"
D.Strings[19319]="难道不是吗？但它们的寿命却和巨龙有很大不同。和我们那个世界的巨龙动辄上千年的寿命不同，这些火鹰的生命非常短暂，从孵化到成年，再到死亡，不过是短短一瞬而已。$b$b虽然我的导师一再禁止我们将个人感情带到研究中来，可有时我还是忍不住要为它们难过。它们的生命燃烧得如此灿烂……可一旦死亡，它们就会被迅速取代并遗忘。"
D.Strings[19320]="有什么好说的呢？它们不过是一群蜘蛛。只是比我们过去见过的蜘蛛更加……亲和火元素。$b$b它们能咬人，能结网，能喷吐炽热的毒液，还把我最好的几个朋友困在了灼热的蛛丝茧里。可怕的小东西。"
D.Strings[19321]="没关系。毕竟这些蜘蛛不是我们真正需要担心的。它们的蛛后，贝丝缇拉克才是我们真正的威胁。她那结满蛛网的堡垒就在东边，我们无法靠近。那里，有一整支蜘蛛大军在保护着她，个个都甘愿为这位蛛后赴汤蹈火。$b$b而且，它们的体型也非常巨大！信不信由你，你在这儿看到的那种12尺长的蜘蛛只不过是些小家伙而已。据说，它们不能算是拉格纳罗斯真正意义上的仆从，但它们仍然对我们的事业构成了威胁。所以，我们仍然要把它们当敌人来看。"
D.Strings[19322]="我知道的恐怕也不多。我并不是德鲁伊，我只是来指挥部队的。在我看来，玛法里奥想要在战区里种一棵树的想法很古怪。不过……我也说了，我并不是德鲁伊。$b$b不过，我可以这么跟你说。没有什么能比自己的老家里长出一棵郁郁葱葱的大树更让那些火元素生气的了。就算没有其他意义，当这棵树完全长成时，也可以象征我军的希望之光……并成为敌人的眼中钉。"
D.Strings[19323]="一万年前，远古半神与凡人种族并肩作战，共同抵御入侵艾泽拉斯世界的燃烧军团。许多半神死于燃烧军团之手。塞纳留斯也差点被杀，但他的父亲，玛洛恩舍身救下了他。$B$B强大的雄鹿纵身跃入战场，他的巨蹄碾碎了恶魔的颅骨，他的鹿角刺穿了无数恶魔的身躯。$B$B但随后，污染者阿克蒙德现身了。一场恶战之后，他攫住了玛洛恩的鹿角……扭断了这位半神的脖子。$B$B但只要世间还有生命在绽放，像玛洛恩这样的自然之力怎么会真正死去呢？"
D.Strings[19324]="古伊尔——你们叫他萨尔——他的灵魂四散到了各个元素位面。$b$b暮光之锤以为这样就能动摇我们的意志……但我们不会退缩。我们不会放弃古伊尔。$b$b他赌上了他的一切来拯救这个世界，而我们也会为他做同样的事情！"
D.Strings[19325]="当你准备好前往奥丹姆的时候再来找我。我们必须和赛克隆纳斯谈谈，看看他都知道些什么。"
D.Strings[19326]="是大地之环派你来的吗？$B$B我们将从这里，世界之树的脚下，开始治愈这片土地。真高兴你能见证这一切。"
D.Strings[19327]="守护巨龙们已经齐聚于此，我相信阿格娜马上也要到了。$B$B你准备好开始了吗，$n？"
D.Strings[19328]="送我到马戏团入口。"
D.Strings[19329]="我们将在火焰之地建立一座永久性的哨所，$n。即使拉格纳罗斯被打败了，但在将来的某一天，其他人仍有可能出来接替他的地位。我们不能让燃烧平原和海加尔的悲剧重演，再次威胁我们的世界。$B$B为此，我们将在这里种下“哨卫之树”。它扎根在艾泽拉斯，却能将树冠延伸到这个可怕的国度，形成保护。在它的庇荫下，我们就可以派一队德鲁伊永久驻扎下来，日夜监视这个荒芜的世界。"
D.Strings[19330]="我们虚灵的技术能够改变一件物品的魔法本质，这在过去是不可想象的。我们还能将物品放入其他位面保存起来……只是需要少许费用。具体情况，你可以找我的同伴询问。$B$B你有东西要让我检查吗？"
D.Strings[19331]="嘿，嘿！$B$B我敢说，你一定有本事把投环扔到一只慢腾腾的乌龟背上。$b$b你觉得呢？"
D.Strings[19332]="你给我一枚游戏代币，我会给你10个投环。$B$B你得想办法把它们扔到那边的暗月乌龟杜本科的背上……看到它驮着的那根柱子了吗？$b$b不过要是你没能扔中足够的环，那就再试一次！你的分数是可以累积到下一轮游戏的。"
D.Strings[19333]="你好啊！欢迎你！$B$B你是来进行挑战的吗？"
D.Strings[19334]="我们要开打了！|cFF0008E8(暗月游戏代币)|r"
D.Strings[19335]="我们要去见守护巨龙了，你准备好了吗？"
D.Strings[19336]="建立及维护场地可不容易……"
D.Strings[19337]="我动一动胳膊都觉得疼。"
D.Strings[19338]="这条伤口看来似乎好不了了。"
D.Strings[19339]="我再也不一个人去调整大炮了……"
D.Strings[19340]="我们这儿有锤子，还有豺狼人。$b$b只要一个代币，你就可以用锤子砸这些豺狼人了。"
D.Strings[19341]="在找旧的蒸汽坦克吗？$b$b好吧，我们现在有些新的货色了。$b$b通常情况下，使用坦克遥控器要花费两个代币。但由于你曾经在部队服过役，所以能享受一个代币的优惠。$b$b我们暗月马戏团的成员非常感谢你所做的贡献。"
D.Strings[19342]="我们将要攻陷地狱火堡垒，就从这些城墙开始。"
D.Strings[19343]="酋长已经下令攻击地狱火堡垒，我们就从外面这些城墙开始。"
D.Strings[19344]="鲜血熔炉见证了我的族人们黑暗的过去。"
D.Strings[19345]="如果你喜欢屠杀兽人，又不爱唠叨，那么欢迎你！$B$B如果不是的话，那么东边就有一座可爱的传送门。我听说，只有在每年的这个时候，它才会特别可爱。"
D.Strings[19346]="纳迦为了自己的目的，把所有的水都抽走了，这里的生物种群正在走向灭绝。$B$B如果我们不尽快采取行动，这个垂暮的世界上剩余的生物就会永远消失。"
D.Strings[19347]="我加入这个远征队的目的只有一个，$r，那就是复仇。"
D.Strings[19348]="这些蘑菇和地表上的任何东西都不一样。据说，谁吃了它们，就能获得无比的智慧和清晰的头脑。$B$B我要带一点回孢子村去。"
D.Strings[19349]="去幽暗沼泽进行研究和学习的机会一生只有一次，非常难得。$B$B尤其是想到我不久前还坐在奴隶围栏的笼子里，那时我和死人也没什么差别……"
D.Strings[19350]="有三个虚灵技师在暴风城里开了一家店，就在教堂广场南边的运河沿岸。\n\n店名叫“三缕风”。你只要找奇怪的机械和紫色的灯就对了……绝对不会找错的。\n\n他们那里有你想要的服务。"
D.Strings[19351]="虚空仓库"
D.Strings[19352]="节点亲王哈拉迈德一直在威胁我说，如果我们不能尽快穿过沙法尔的警戒线，他就要拿我当下一个实验品。$B$B他可不是开玩笑的。"
D.Strings[19353]="你问什么是“杂学家”？那当然是指，我什么都研究！在你所能想象到的任何领域，我都是最博学的人，比你认识或者不认识的任何人知道的都多。$B$B穿过沙法尔的警戒线不算什么。要是莫法鲁斯肯听我的，他连一根寒毛都不会掉。他这个人，老是我行我素。"
D.Strings[19354]="亡者不属于这个国度。$B$B那我们为什么还要在让他们安息之后，再不断地寻找他们呢？"
D.Strings[19355]="你根本就不懂怎么操作这个设备上的各种机械，可你心中却总有一种挥之不去的熟悉感。$B$B最好还是先别去管它。"
D.Strings[19356]="这里的灵魂已经被折磨了很久。我们只想安息。"
D.Strings[19357]="土水派的修行之道是获得真知的途径之一。通过沉思和冥想，我们发现我们的修行之道是解决问题最有效的方法。通过练习和修正，我们让自己的意志完美支配自己的身体。$B$B要学习土水派的修行之道，必须具有坚强的意志和完美的体魄。"
D.Strings[19358]="无为乃罪。"
D.Strings[19359]="很高兴再见到你。"
D.Strings[19360]="小声点，$r。塞泰克已经不欢迎我了。"
D.Strings[19361]="不用担心，$c，有了这道屏障，鸦人就看不见我了。$B$B我来这里是有公务在身的。"
D.Strings[19362]="督军卡利瑟里斯必败！"
D.Strings[19363]="你不能再参加游戏了。"
D.Strings[19364]="你想知道什么？"
D.Strings[19365]="让开点，让其他人也来玩玩吧。"
D.Strings[19366]="我们必须控制住纳迦散播到这里的疾病，否则就太迟了！"
D.Strings[19367]="我要飞行。"
D.Strings[19368]="嘿，在这儿呢！"
D.Strings[19369]="如果你想要挑战督军卡利瑟里斯，就必须先击败机械师斯蒂里格和水术师瑟丝比娅，这样才能接触到主厅控制面板。$B$B然后，你只要按下面板上的几个按钮，就能打开通向主厅的大门了！"
D.Strings[19370]="上古火灵的纯洁净化了我们，他的激情更激励着我们。"
D.Strings[19371]="我们贫民窟的人原本在暗影迷宫里有一张相当广大的间谍网络。$B$B可现在，除了我和托古恩，其他人都死了。"
D.Strings[19372]="沙塔斯的领导层行动太缓慢了，所以贫民窟的大人物把暗影迷宫的事揽到了自己手里。"
D.Strings[19373]="他们真的让我来禅院修炼了！齐齐真不敢相信！$b$b齐齐办到了！"
D.Strings[19374]="闪开！齐齐正在练功！靠近我五码之内的人都有可能被踢飞……甚至可能被踢死。$b$b呀哈——！"
D.Strings[19375]="以前齐齐最擅长误伤队友，但自从开始训练之后，齐齐已经进步很多了。"
D.Strings[19376]="熊猫人长老允许锦鱼人进入禅院是个贤明的决定。$b$b但他们给予猢狲同样的待遇，此为不智。"
D.Strings[19377]="我喜欢这个地方。要是这里的水再多一点就好了……"
D.Strings[19378]="我从这里的武僧身上学到了很多东西，$r。希望你也一样。"
D.Strings[19379]="我得说，这儿的饭菜还真是不错。啤酒也是，真心给力。"
D.Strings[19380]="你尝过这个米饭了吗？你真应该尝尝。"
D.Strings[19381]="吃东西也是一种修炼，你明白的。"
D.Strings[19382]="我是来向远近闻名的艾莎·云歌求助的，但我不能打扰她的修行。她是如此娴静、如此沉稳……如此美丽。"
D.Strings[19383]="我们是来打仗的。$B$B这是他们强加给我们的。"
D.Strings[19384]="我们是来侦察敌人的入侵行动的，可他们已经知道我们来了。"
D.Strings[19385]="阿莱克斯塔萨麾下的巨龙会在这片废墟的另一边接应我们。准备好你们的武器，这个地方太适合打埋伏了。\n\n你们做好行动的准备之后，就告诉我。"
D.Strings[19386]="要想玩游戏，你必须拥有暗月游戏代币。$b$b马戏团里到处都有出售代币的商人。$b$b我可以帮你在地图上标记出来。"
D.Strings[19387]="首先，你要先给我一个游戏代币。然后，你就可以操纵一辆蒸汽坦克。$b$b你需要驾驶坦克，在有限的时间内炸飞战场上的目标。每摧毁一个目标，你可以得一分。$b$b不过你要注意，战场上还有一些邪恶坦克和飞艇。被它们打中会损毁你的坦克。$b$b你的分数可以累积到下一轮，所以死了也不用担心。"
D.Strings[19388]="首先，你得给我一个游戏代币，而我会给你一把步枪。$B$B然后，你就用枪射击那些亮起来的靶子。$b$b如果你出手够快，能在目标亮起后直接击中它，那你就能额外得到一分。$b$b如果你没在规定时间内打到足够的分数，或者离开了游戏场地，也不用担心。你的分数可以带到下一轮游戏里。"
D.Strings[19389]="这个射击游戏怎么玩？"
D.Strings[19390]="机灵点。这附近有恶魔。"
D.Strings[19391]="你好，欢迎来到暗月马戏团入口处。$b$b这座传送门能送你去暗月马戏团。$b$b如果你在出发前有什么疑问的话，我也可以帮你解答。"
D.Strings[19392]="暗月马戏团里有各种有趣的游乐设施，有占卜师，音乐会，钓鱼大赛以及各种游戏。$b$b而且我们还在不断扩张马戏团，添加各种新的游乐设施！$b$b你要不要了解一下某种游乐设施的具体情况呢？"
D.Strings[19393]="我们给这些迷你坦克起了一个很拉风的名字，叫蒸汽坦克。它们可是我记忆当中，最受欢迎的马戏团游戏了。$b$b我们有两座坦克大战专用的战场。$b$b一座为限时挑战战场，你需要在里面快速摧毁目标，并躲避敌对坦克的攻击。只要一个代币，你就可以参加游戏了！$b$b另一座战场则是对战专用的场地，你可以驾驶自己的坦克或迷你飞艇来和朋友对战。"
D.Strings[19394]="雷管5000型超级大炮是一种代表世界最尖端技术水平的单人发射装置。$b$b它能以接近飞龙的速度将搭乘者发射出去。它的发明者是雷管家族，这个家族在航空及爆破领域享有盛名。这架超级大炮已经成为了家族的荣耀！$B$B如果你想像鸟儿一样在空中翱翔，就去找玛克希玛·雷管吧。"
D.Strings[19395]="打豺狼人？"
D.Strings[19396]="打豺狼人是一种打……豺狼人的有趣游戏。$b$b这是一个新的游乐设施，而且颇受我们大家的欢迎……好吧，其实塞格不太喜欢这玩意儿。"
D.Strings[19397]="我们希望各个年龄层的游客都能享受到游戏乐趣。$b$b套圈圈是一个简单的游戏，你只要设法把投环扔到一只不断移动的海龟背上就可以了。$b$b这也是我最喜欢的游戏之一。"
D.Strings[19398]="套圈圈？"
D.Strings[19399]="瑞林开设了一家射击场。$b$b那里只有三个射击目标，你动作越快，成绩就越好。$b$b就个人意见来说，这是我最喜欢的游戏之一。"
D.Strings[19400]="射击场？"
D.Strings[19401]="我强烈推荐你到塞格那里去算个命。$b$b我知道，我知道……他是个豺狼人。但他是个非常特别的豺狼人，他能解读你的命运！"
D.Strings[19402]="占卜师？"
D.Strings[19403]="卡萨雷兹没有我这么走运，$n。他已经和幽灵为伴了。"
D.Strings[19404]="救我下来，$n！这女人要杀了我！"
D.Strings[19405]="我就不该苟活下来，$r。$b$b我应该和其他兄弟们死在一起。"
D.Strings[19406]="这种调整工作可不简单。"
D.Strings[19407]="出什么事了？$b$b我——我们在哪儿？"
D.Strings[19408]="将军决心在这里扎营。$b$b但愿他知道自己在做什么……"
D.Strings[19409]="燃烧吧！"
D.Strings[19410]="你死定了！"
D.Strings[19411]="只有公平公正的战斗才能真正衡量出一个人的实力。任何其他的考验都是有瑕疵的。"
D.Strings[19412]="真是岁月催人老啊。我的行动已经不如从前敏捷了，所以我也很少去看我的老朋友了……"
D.Strings[19413]="如果你很强壮，那我会向你表示敬意。$b$b如果你很软弱，那我也会鼓励你。$b$b如果你是我的敌人，那我就会用拳头来揍你。如果有必要的话，我会一次又一次地接着揍你。"
D.Strings[19414]="以战生慧，以斗促觉，以动得静。$b$b这就是天之道。"
D.Strings[19415]="纪律是臻于完美的关键。你必须打败你的惰性！管好你那把懒骨头！"
D.Strings[19416]="我父亲是云瀑长老的前任。我所知道的一切都是他教的。"
D.Strings[19417]="只要反复练习，没有什么是掌握不了的。"
D.Strings[19418]="经过一阵拳打脚踢，大吃大喝之后……必须得有人来打扫。$b$b现在就该园丁上了。"
D.Strings[19419]="你还是留着你的棍术和织雾绝招吧，我站在这里看看就行了。"
D.Strings[19420]="你知道总在禅院的日课上偷懒会有什么后果吗？你会沦为园丁！就像我这样。$b$b不过这也不算太糟。我总算有了一把自己的扫帚。$b$b<老吴叹了口气。>"
D.Strings[19421]="当然是一座禅院！$b$b天禅院的武僧专门教授像我一样的年轻熊猫人如何战斗。所有的战斗大师都是在这里诞生的：剑仙宇明、铁布衫梁……甚至连伟大的帝王少昊都是在这座寺院学习的。$b$b或者至少传闻是这么说的。"
D.Strings[19422]="欢迎来到我们在群山中的家园，$r。"
D.Strings[19423]="你好啊！欢迎你！"
D.Strings[19424]="我很抱歉，可如果我让你带走一匹马的话，罗娜会气疯的。\n\n只有吉尔尼斯人崇拜的英雄才有资格得到它们。"
D.Strings[19425]="罗娜说，一个英勇的冒险者在她家的果园附近救下了许多马。\n\n我主动提出帮她照料那些远渡重洋而来的马。这个手艺是从我爸爸妈妈那里学来的，愿圣光保佑他们！\n\n你想要一匹精良的吉尔尼斯战马吗……？"
D.Strings[19426]="神秘与奇迹不仅仅存在于马戏团，我们身边每天都有奇迹发生。我们列出了一张表格，上面写着你在日常生活中可能遇到的奇迹。暗月冒险者指南能帮你找出这个世界上的奇迹。$b$b只要拥有了这本指南，你就能够发现未知的物品。你熟视无睹的东西可能就是别人孜孜以求的宝物。$b$b带上这本指南吧，用你眼睛去发现未解的谜团。$b$b如果你不小心丢失了指南，可以再来找我们，我们会免费送你一本新的。"
D.Strings[19427]="暗月冒险者指南？"
D.Strings[19428]="能再给我一本暗月冒险者指南吗？"
D.Strings[19429]="<利尔没有抬头看你。>$b$b<从他的状态来看，你甚至怀疑他连抬头的力气都没有了。>"
D.Strings[19430]="在新年的伊始，我们的先祖们会暂时降临，为生者指点迷津，并欢迎后来者加入他们的行列。"
D.Strings[19431]="射击，射击，射击……"
D.Strings[19432]="我很高兴这些“军情七处”的人愿意带上我。$b$b我们很少离开舒适的湖泊。这是我有生以来第一次离家这么远。"
D.Strings[19433]="幸运地是，你还是能辨别出一些细节，看上去似乎是某个生物的躯干。"
D.Strings[19434]="你从这个雕像残片上看不出什么来，除了它的主人是有手臂的这一点。"
D.Strings[19435]="暗月马戏团开张啦！$b$b只要交纳少许费用，我就能把你传送到马戏团的入口。$b$b你想去吗？"
D.Strings[19436]="相比它的其他部分，雕像的肩部看上去十分威武。它的主人一定是个强大的生物！$b$b它或许是一个温和的家伙。如果不是的话，那它可能十分具有侵略性！$b$b我们只能祈祷……"
D.Strings[19437]="但愿它脸上那个又大又恐怖的面具只是面具而已……"
D.Strings[19438]="无论发生了什么事——我们都必须专注于我们来的目标。"
D.Strings[19439]="你眼前的就是暗月死斗场。你是否拥有强大的实力和坚定的意志，能够打败所有的参赛者并赢得大奖？\n\n大赛将从午夜开始，每三小时举行一次。"
D.Strings[19440]="谢谢你救了我！"
D.Strings[19441]="安这个刻薄鬼，故意说我没胆子。而我是从不逃避挑衅的。"
D.Strings[19442]="<利尔的额头十分苍白，冷汗直流。他看起来非常不妙。>"
D.Strings[19443]="<利尔一直茫然地盯着地板，呼吸困难。>"
D.Strings[19444]="计划出了些岔子，我们原本是要出来找白卒的。我这会儿早该回到铁炉堡了。"
D.Strings[19445]="一切都搞砸了，$n。这原本只是一项简单的侦查任务。"
D.Strings[19446]="<涓流期待地看着你。>"
D.Strings[19447]="唔……唔……嗯……\n\n<我不会……有事的……它会慢慢……消失的……>"
D.Strings[19448]="自从你来了之后，形势迅速好转了，$n。猢狲的威胁空前强大。$b$b可我们锦鱼人……也更加强大了。"
D.Strings[19449]="我们不可能独自对抗猢狲。如果我们的部族想要生存下去，就需要联盟的帮助。"
D.Strings[19450]="这个地方很特别。$B$B我正在引导魔法，以修复魔网。虽然这么做会将我撕成碎片，可我还是觉得很不可思议！"
D.Strings[19451]="从某个角度来说，我很嫉妒你，小$r。$B$B你真是太幸运了，居然能够见证伟大的艾卓-尼鲁布帝国重生的第一步。"
D.Strings[19452]="啊，你们到了。\n这里是大分裂的前夕，永恒之井即将毁灭，撕裂整个大陆。\n$b在这里，我们要趁巨龙之魂失落于时间的迷雾之前将其夺回。\n$b但首先，你们必须先破坏艾萨拉的上层精灵侍从们的防护结界。他们就在宫殿里。我则会先行一步。\n$b祝你们好运，英雄们！"
D.Strings[19453]="利尔……伤得很重。$b$b<密探吉尔妮用力地捶了地面一拳。>$b$b他快死了，$n！可我们对此却无能为力！"
D.Strings[19454]="不，我们没有找到白卒。$b$b不行，我不能把白卒的身份告诉你。"
D.Strings[19455]="我们的敌人以为能靠冰封的荒原来击败我们。$B$B我们要让他们看看愚昧的后果。"
D.Strings[19456]="我们必须得把剩下三个灵魂安全带回来。我年事已高，力不从心，而考虑到他们的力量，艾莎和季又太过固执。$B$B你具备英雄应有的一切品质，以及他们所欠缺的平衡。必须由你完成这项任务。"
D.Strings[19457]="阴影能很好地掩盖我们的行迹。\n$b这个暗影斗篷遮掩了我的身形，也可以将它的魔法灌注到你身上。\n$b它不能让我们隐身，可只要我们和敌人保持距离，就不会被发现。"
D.Strings[19458]="你身周的这个环能够让外面的人看不到你，可只要你进行攻击或者受到伤害，幻象就会消失。\n$b我建议你隐藏起来，直到我发出指令为止。这些恶魔太强大了，我们无法与他们正面对抗。"
D.Strings[19459]="我们必须继续前进，你们准备好了吗？"
D.Strings[19460]="我们要等向导。"
D.Strings[19461]="这个向导太拖拉了……"
D.Strings[19462]="你是来带我参观的吗？"
D.Strings[19463]="你是我的向导吗？"
D.Strings[19464]="如果你不是我们的向导，就快走开。"
D.Strings[19465]="你是来带我们参观的还是来参观我们的啊？滚开。"
D.Strings[19466]="<纳乐对你微笑，你觉得自己焕发了久违的年轻活力。>"
D.Strings[19467]="我已经躲够了。和铁矮人开战的时候到了。"
D.Strings[19468]="做完的事就不用反复讨论……过去的事，也不必再去追究。"
D.Strings[19469]="艾莎花在修炼上的时间似乎太长了……但成效着实不错。她的风度十分迷人。"
D.Strings[19470]="我们的人不能再袖手旁观了。我们必须把整个奥杜尔的所有大厅扫荡一遍！"
D.Strings[19471]="噢，一个客人。我这里的客人可不多。$B$B饿了吗？我做了很多好吃的东西，亲爱的。$B$B不不，不是鱼。只有在我抓不到什么好东西的时候，才会拿鱼出来充数。"
D.Strings[19472]="我会跟着你的，$n。"
D.Strings[19473]="色彩。它赋予了我们反差、深度、浓淡和色调的变化。稍微调整一下色彩，就能让欢笑中的人们潸然泪下。"
D.Strings[19474]="每一笔一划，都表达了一个意象。它让人们的思想跃然纸上，吸引了观看者的注意力。"
D.Strings[19475]="我这一生中有过许多子女，以及许多孙辈。可没有一个曾孙辈的孩子来看望过我。他们几乎都忘了伟大的风裘家族。"
D.Strings[19476]="力量！这才是棘杖家族的生命之源。我的家族能延续至今，就是强大的肉身力量不惧任何挑战的最好明证。"
D.Strings[19477]="我亲眼见证了家族的衰落。我们曾是最伟大的酒仙，现在却只能排在风暴烈酒家族后头，呸！"
D.Strings[19478]="我听说，你从青玉巫婆手里救出了我的一个晚辈。对于你的义举，我深表感谢。"
D.Strings[19479]="愿你的清水永不干涸。"
D.Strings[19480]="你好，朋友。想顺便买点儿什么吗？"
D.Strings[19481]="我让我儿子昂管理山下的菜园。我侄子梁在西边的山下经营着一个养猪场，他父亲——也就是我兄弟——在南边的山下开了个小型牧羊场。$b$b我现在不务农了。最近，我只收购别人收割的庄稼，再向路人贩卖。虽然走动得少了，但我兜里的钱却多了。"
D.Strings[19482]="这地方太棒了！看到他们这里有多少食物了吗？"
D.Strings[19483]="当然，其他人可能已经踏上了激动人心的探险之旅，但我并不在乎。我在这里过得非常开心。"
D.Strings[19484]="从修道院长途跋涉而来可苦了我的脚——还有我的胃。我想在重新考虑启程先在这儿大吃一顿，以恢复体力。"
D.Strings[19485]="不知道你发现了没有，这是个家庭农场。我们雷脚家的人不斗争、不探险……甚至不怎么喝酒。$b$b但我们很享受美食带来的快乐。"
D.Strings[19486]="经营养猪场比你想象的要复杂……尽管多数时候可以将其概括为“寻找更多的猪食”。"
D.Strings[19487]="朱红庇护所是我们在暮光高地上的行动基地。$B$B我们可以从这个制高点监督对格瑞姆巴托的进攻，以及对下方河谷的清扫行动。"
D.Strings[19488]="遇见你是我们这几天来唯一走运的事。很高兴能得到你的帮助。"
D.Strings[19489]="欢迎你和你的朋友们来做客，想呆多久都可以。"
D.Strings[19490]="谢谢你帮我找回了车夫，朋友。"
D.Strings[19491]="我对指挥官的伤势恐怕已经无能为力了。"
D.Strings[19492]="现在，只有奇迹才能拯救指挥官了。"
D.Strings[19493]="我已经尽力抢救了。但指挥官恐怕已经坚持不了多久了。"
D.Strings[19494]="你好，$n。你也像我一样口渴吗？"
D.Strings[19495]="$n是吗？我在村里听说过你的名字。"
D.Strings[19496]="你就是那个$c，对吧？谢谢你把我哥哥的传家宝带了回来，那是我最宝贵的财富。"
D.Strings[19497]="或许我误解了你，$r。你已经帮了我们村很多忙了。"
D.Strings[19498]="你们的人很有趣，$r。我希望能更深入地了解你和你的同胞们。"
D.Strings[19499]="或许有一天，我也会去拜访你的村子的，$n。"
D.Strings[19500]="你为我们的村子做了许多好事，$n。或许我们是可以成为朋友的。"
D.Strings[19501]="我们在这座湖泊上居住了几千年了。这里的湖水源自于潘达利亚的古老水池。"
D.Strings[19502]="我们整个部落都十分感激你善行，$n。"
D.Strings[19503]="一切都还顺利吗，$n？"
D.Strings[19504]="我的腿都僵了。"
D.Strings[19505]="我听说，你们是靠火焰与蛮力来铸造金属武器的。而我，是通过水流的压力以及对其密度的精确把握来制造武器的。"
D.Strings[19506]="在我小的时候，我曾梦想成为一名酒仙。通过各种奇妙的化学反应酿造出完美的陈年佳酿。$b$b但在我学习的过程中，他们总说我酿的酒太烈了。$b$b所以我就转行搞冶炼了。当时看来，这种转行很合理。"
D.Strings[19507]="欢迎来到我的面馆，各式面条应有尽有。要是我们这儿没有的，您不吃也罢。"
D.Strings[19508]="我是强大的破军铁腹志大师，这个外号源自我那臭名昭著的腹壁神功。你大概已经听说我了吧。"
D.Strings[19509]="我曾经与长着恐怖利齿的野兽战斗过，我们最好不要提起它的名字，因为其中蕴含的恐惧足以使日月失色。"
D.Strings[19510]="秦可不是浪得虚名。曾经有过一场竞争非常激烈的面条大赛，汇集了全村的行家里手。$b$b他们在一桶桶煮沸的面汤前大展身手，只为在一天之内制作出最上乘的面条来。$b$b别提有多精彩啦！$b$b最终他技压群雄，做出来的面条好吃到连我这个美食家都为之震惊。"
D.Strings[19511]="我叫托亚！无论你需要什么我都能帮你搞到！不用找别人了，我可是全晨芳园独一无二的！"
D.Strings[19512]="再次感谢你的帮助，陌生人。我已经开始琢磨该给塞拉打造一枚什么样的戒指了。"
D.Strings[19513]="哇，陌生人！你让那个恶毒的老巫婆明白了谁才是老大。"
D.Strings[19514]="你痛打那些懒猫的招式实在是太酷了！它们气势汹汹地来，结果被你三下两下就收拾掉了。"
D.Strings[19515]="大人们总是告诉我们说，那个住在林子里的青玉巫婆只是个因为而死了丈夫伤心过度的老太婆。可你证明他们错了！$b$b只是……我不能讲给那些大人们听，我可不想给自己找麻烦。"
D.Strings[19516]="你想要寻求突破吗？"
D.Strings[19517]="你想拓展你的思维，强健你的身心，突破现在的极限吗？"
D.Strings[19518]="天禅院教会了我如何凝聚自己的力量，现在我只用一根小拇指就能点开一个酒桶。"
D.Strings[19519]="你成功了！"
D.Strings[19520]="你听到了吗？那是什么声音！"
D.Strings[19521]="开酒桶可是一门代代相传的手艺。用不着去问别人这是不是真的，只要记住我的话就行了。"
D.Strings[19522]="“一些很有深度的话。”$b$B好了。以后如果有人问你第一次见到李·寻杯时他都说了什么，你就可以回答说了“一些很有深度的话。”"
D.Strings[19523]="我是一个酒桶匠。对外行来说，这门手艺似乎很简单。但酒桶的用料对于酒水口味的影响之大，绝对会出乎你的意料。"
D.Strings[19524]="退后！$b$b等等……你不是它们的一员。我们不习惯有外人，在螳螂妖破墙而入的当下，我……$b$b无论如何，我们能为你做些什么？"
D.Strings[19525]="对不起，这里一团乱。什么都是乱糟糟的。$b$b我能帮你什么吗？"
D.Strings[19526]="有人需要医疗救助吗？"
D.Strings[19527]="你的任务是什么？我这里有你需要的工具。"
D.Strings[19528]="选择你的目的地。"
D.Strings[19529]="我们不能再浪费时间了，旅行者。"
D.Strings[19530]="幻化"
D.Strings[19531]="你想重铸物品？我这里已经不提供这种服务了。\n\n不过暴风城的教堂区里的虚灵商店“三缕风”可以帮助你。\n\n所有的城市守卫都可以帮你指路。"
D.Strings[19532]="你想重铸物品？我这里已经不提供这种服务了。\n\n不过奥格瑞玛的暗巷区里的虚灵们可以帮助你。\n\n所有的城市守卫都可以帮你指路。"
D.Strings[19533]="我打算让我的田休耕一季。一个聪明的农夫知道什么时候该让土地休息。"
D.Strings[19534]="兔妖！嗨！数不尽的兔妖！"
D.Strings[19535]="煞魔从寺庙里跑出来了，我们得把他们赶回去……或者同归于尽。"
D.Strings[19536]="靴子，不好。腰带，非常不好。衬衣，挺好看，但不适合你。我们应该给你弄个斗篷。也许再配件样式符合英雄身份的外套。"
D.Strings[19537]="你让我想起了年轻的郭大师，他腰围要再细一点。$b$B我第一次见他时他还是个农场小工，尽管衣衫褴褛，但走起路来英姿飒爽，和他英俊的外表还挺相配。$B$b我们一起做了一个服装系列，在东部地区流行了至少两年。"
D.Strings[19538]="你想干什么？"
D.Strings[19539]="啊，很高兴见到你，我的朋友！$B$B饿了吗？"
D.Strings[19540]="你不是应该在训练吗，年轻的$c？$B$B只要好好修炼你的心志和躯体，就没有什么是你做不到的。"
D.Strings[19541]="我押蓝获胜。你没看见他在上周的训练中，是怎么打倒楚的吗？"
D.Strings[19542]="对一个新手来说，拥有如此技巧实属难得。"
D.Strings[19543]="以后你一定得把你的秘诀教给我。"
D.Strings[19544]="那个沙袋毫无还手之力。"
D.Strings[19545]="你注定要成就一番大事业，新人。"
D.Strings[19546]="多谢你的指点，我必须更加努力地修炼才行。"
D.Strings[19547]="我打不过你。我认输了。"
D.Strings[19548]="你太厉害了。我认输。"
D.Strings[19549]="你很会战斗。我以后一定得好好向你学习。"
D.Strings[19550]="真是场痛快的战斗。谢谢你。"
D.Strings[19551]="你好啊！我说，你该不会是在找返回大炮的传送门吧？$B$B我就可以帮你！$B$B当然了，只是要一小笔费用……"
D.Strings[19552]="哇，准头不错嘛！$B$B就是把我的鱼吓跑了。$B$B你想快速传回大炮那里去吗？$B$B当然了，你得付一小笔费用……"
D.Strings[19553]="我们必须尽快行动！塔丽苟萨和她的守卫们已经倒下了，神殿的防御完全崩溃。决不能让死亡之翼的部队接近巨龙之魂，否则一切都完了。龙眠联军会在战斗中协助你的；我们必须打破敌人的围攻！"
D.Strings[19554]="你到底是个疯子、傻瓜，还是个值得颂扬的英雄呢？你到底是哪个？"
D.Strings[19555]="我们等着瞧吧，$C。"
D.Strings[19556]="你好啊，$n？"
D.Strings[19557]="我能帮你什么忙吗，陌生人？"
D.Strings[19558]="跟紧我，$n。我们可能需要互相帮助。"
D.Strings[19559]="成功了。巨龙之魂已经被安全送到巨龙军团手中了。"
D.Strings[19560]="我在寻找走失的小伙伴。"
D.Strings[19561]="你是来向圣光祈祷的吗？还是来接受圣光技艺的训练呢？$b$b如果你是来找大主教本尼迪塔斯的话，那我必须很抱歉地告诉你，他出门去执行任务了。"
D.Strings[19562]="是的。他受命前往龙眠神殿帮助守护巨龙。他希望能帮助他们扫除死亡之翼对艾泽拉斯的威胁。$b$b愿圣光指引他的道路。"
D.Strings[19563]="这是我们的土地，我们的家园。$B$B我绝不会眼睁睁看着它落入煞魔手中。"
D.Strings[19564]="尽管我们一直努力想要塑造更加进步的文明，可我们总是重复过去的错误。$B$B煞魔又一次威胁到了这片土地。"
D.Strings[19565]="我们不能纠结于过去的错误了，$r。$B$B现在唯一的办法就是前进。"
D.Strings[19566]="拿出你的勇气来，$r。团结一致，我们就能对抗煞魔。"
D.Strings[19567]="当煞魔开始攻击的时候，我所有的弟子都毫不犹豫地出去战斗了。$B$B我教了他们很多东西，但他们的表现总能超出我的期望。"
D.Strings[19568]="我们对煞魔的大部分认知都失传了。$B$B随着战斗的持续，我必须要研究他们的天性。$B$B只有这样，我们才能避免同样的悲剧在将来再次发生。"
D.Strings[19569]="你是来观摩我教学的吗？"
D.Strings[19570]="我们的战斗需要有营养的食物才能挡住敌人！$B$B快，告诉我我能给你弄点什么。"
D.Strings[19571]="英雄们，你们有没有拿到聚焦之虹？"
D.Strings[19572]="我从煞魔身上了解到的一点就是，他们知道如何利用我们自身的弱点。"
D.Strings[19573]="煞魔在有一点上是对的。$B$B我们最大的敌人通常就是我们自身。$B$B我只希望我自己不会是个难缠的对手。"
D.Strings[19574]="你有什么事吗，英雄？"
D.Strings[19575]="不要停。$B$B你还有时间！"
D.Strings[19576]="由于我失去了力量，巨龙之魂已经回到了原本的时空。"
D.Strings[19577]="看着这些熊猫人如此悲伤，肯肯也快变成悲伤的猢狲了。"
D.Strings[19578]="我感到元素正在苏醒，欢呼……这场灾难……结束了。"
D.Strings[19579]="如果你希望如此，我可以向你展示死亡之翼在大漩涡所造成破坏的后果。"
D.Strings[19580]="这不可能，真的结束了吗？我肯定又做梦了。"
D.Strings[19581]="我们合力完成了一件不可能的任务。"
D.Strings[19582]="现在，你们必须开创一个新的时代……一个属于凡人的时代。"
D.Strings[19583]="这道暗影之墙能挡住恶魔，直到我们安全通过。\n$b等你们和其他精灵通过之后，我也会跟上的。"
D.Strings[19584]="嘘！它们不知道我藏在这里。"
D.Strings[19585]="我只是一个熊猫人，可我必须留在这里，帮助翔龙。"
D.Strings[19586]="我们务必要保持安静。否则那些滑鳞蜥蜴人会毫不犹豫地把我们当晚餐吃了。"
D.Strings[19587]="我已经十六天没洗过澡了。这样就不太容易被发现。"
D.Strings[19588]="我已经在野外收集到那么多有关翔龙的数据了！"
D.Strings[19589]="这里是它们天然的繁殖地，我们可得小心点儿。"
D.Strings[19590]="你去过青龙寺吗？我们的许多弟子都会被派去那里潜心进修，由玉珑亲自督导。"
D.Strings[19591]="不幸的是，我们培育翔龙的努力失败了。我们现在只能仔细挑选一些野生翔龙蛋回去自己饲养了。"
D.Strings[19592]="什么？你最终还是改变主意了？我告诉过你叫你仔细挑选！$B$B算了算了，这次我就原谅你了。告诉我，你到底想要哪个蛋？"
D.Strings[19593]="几个世纪以前，这片土地还是荒野。前往海岸是危险之旅，在神鹤之巢卡桑琅附近有野兽出没，许多熊猫人都因此下落不明。$B$B这种情况一直持续着，直到有一天，大名鼎鼎的猎手朱·长眉来到了这里。厌倦了生活的无谓得失，朱带着妻子林和儿子波——他的妻儿也都是强大的猎手，历尽艰辛，在这片荒野的一隅安居下来。$B$B朱不想彻底定居荒野，尽管许多人求他这么做。他的智慧让他明白，他们同样肩负着另一项使命——保护神鹤。$B$B于是就有了朱家界，以及用作守备之用的朱家堡。"
D.Strings[19594]="我们会让朱家界重获安宁。朱的遗产不会就此消失。"
D.Strings[19595]="没错。他是长眉家族最后的传人。$B$B可惜的是，在他身上似乎看不到与老朱相同的气质。我想你肯定已经注意到了，他情绪非常……多变。$B$B请不要把这看作是软弱的象征——他的姓氏和随之而来的责任，压得他喘不过气来。我知道易默是为了朱家界好。$B$B总有一天，他会明白，有时我们必须为自己所爱的一切战斗。"
D.Strings[19596]="想要成为一个翔龙大师，道路是异常艰辛的。你准备好接受挑战了吗？"
D.Strings[19597]="想要晋升为翔龙骑士，就需要付出极大的牺牲。我祝你好运。"
D.Strings[19598]="要是你全身上下只围着一根腰带，手里拿着一把猎刀，单枪匹马地跟雪人单挑，那你也能为自己赢得“幸运”的称号。"
D.Strings[19599]="你表现出了极大的潜力，$n，但你必须依靠戒律来磨砺你的天赋。"
D.Strings[19600]="幼年翔龙是非常脆弱的。许多坏习惯就是在这时期养成的。但良好的训练能改变这一切。"
D.Strings[19601]="幼年翔龙要比成年翔龙顽皮得多。"
D.Strings[19602]="翔龙骑士的道路漫长而艰险，但你将和你的翔龙伙伴一路同行。$B$B如果你们能互相扶持走到终点，你就将收获一个终生不渝的忠实朋友。"
D.Strings[19603]="我的毛今天看起来是不是很闪亮啊？"
D.Strings[19604]="我跟阿加拉是交相辉映，相得益彰。"
D.Strings[19605]="别人告诉我，我是天空之中最英俊的骑士。如果我是你，我就不会相信这种鬼话。我也是大地之上最英俊的骑士，深海之下最英俊的骑士……呃，反正不管到哪儿我都是最英俊的！"
D.Strings[19606]="你是来欣赏我的翔龙的吧。噢，它给阿加拉也留下了深刻的印象。"
D.Strings[19607]="嘿，你在干什么？"
D.Strings[19608]="这里的事结束之后，我一定要和兄弟们去龙舞楼喝几杯！"
D.Strings[19609]="嘿菜鸟，在临风岛上注意寻找玛瑙翔龙蛋。要是你能将它带给翔龙大师，他们一定会喜出望外！"
D.Strings[19610]="哦，你是我的粉丝吗？真不好意思，我现在不能给你签名。"
D.Strings[19611]="抱歉，我现在不能和你闲聊。等我们完成这里的训练之后，就该吃午饭了！"
D.Strings[19612]="我也许不是最棒的骑士，但却拥有一流的发明！"
D.Strings[19613]="当我因失去而感到难过时，我就化悲痛为食量……"
D.Strings[19614]="我想到了一个新发明，叫做集粪桶。有了它，我就再也不用自己去收集粪便了！"
D.Strings[19615]="你知道吗，在临风岛上有时能找到稀有的玛瑙翔龙蛋。要是你将它带给翔龙大师，就能赢得骑士团的尊重。"
D.Strings[19616]="吃饱了才有力气！反正我妈妈总跟我这么说……"
D.Strings[19617]="我现在没空聊天，我很忙。"
D.Strings[19618]="你能稍后再来吗？我正在忙着训练我的云端翔龙。要是我想击败对手，就必须得加把劲。"
D.Strings[19619]="我并不担心我的比赛，因为我知道我赢定了。"
D.Strings[19620]="我唯一担心的就是奎陆，他总在自己的设备上搞些花样。"
D.Strings[19621]="你想跟我一较高下？哈！你只能看着我的翔龙尾巴，望尘莫及。"
D.Strings[19622]="要是我一直站着陪你聊天，就无法击败对手了。"
D.Strings[19623]="哦耶，我给安离长老带去了许多玛瑙翔龙蛋。我每给她一枚，就使自己在骑士团中的地位得到了提升。"
D.Strings[19624]="要是我不努力，就会被别人甩在身后。"
D.Strings[19625]="一个勤奋的骑士就是一个成功的骑士。"
D.Strings[19626]="你不该多练练吗？"
D.Strings[19627]="最好的经验就是自己的经验。"
D.Strings[19628]="我可以把我的骑术窍门告诉你，但这还是比不上你自己的刻苦练习和亲身体会。"
D.Strings[19629]="我为什么能这么快？如果我告诉你，不就对自己不利了吗？"
D.Strings[19630]="去向教头们请教吧。我没什么可教你的，我也只是个徒弟而已。"
D.Strings[19631]="其他的新手都有着各自的技巧和天赋，能和他们一起翱翔我感到很荣幸。"
D.Strings[19632]="能和你同场竞技是我的荣幸。"
D.Strings[19633]="嗨！你好吗？"
D.Strings[19634]="需要帮助的话，尽管找我！"
D.Strings[19635]="你要尽量记住那些检查点的位置。一旦搞清楚该去哪儿收集那些旗帜，你便可以制定出最短的飞行路线。"
D.Strings[19636]="穿越那些云之环是提升速度的最好办法。有时候为了提升速度而偏离一下航线还是很值得的！"
D.Strings[19637]="四处找找看有没有新路线，有时候最快捷的路线并不是那么显而易见的！"
D.Strings[19638]="我听其他受训者说，在临风岛上能找到玛瑙翔龙蛋。我找啊找啊，可却一个都没找到！"
D.Strings[19639]="技巧很重要，但归根结底有时候还得看运气。"
D.Strings[19640]="别担心，就算你最后一个冲过比赛终点，我也会为你呐喊助威的！"
D.Strings[19641]="其他弟子都是非常优秀的骑士。但愿有一天，我也能像他们那么出色。在那之前，我只要不懈地练习就行了！"
D.Strings[19642]="照顾幼年翔龙可是一门精细活儿。"
D.Strings[19643]="除非你愿意帮我清理龙穴，否则你最好让我回去工作。"
D.Strings[19644]="我一半的时间花在这座图书馆上，另一半的时间则花在照顾这些雏龙身上了。"
D.Strings[19645]="你了解翔龙骑士的历史吗？那是个非常有趣的故事。"
D.Strings[19646]="我希望有一天能增进我们的古老知识，其中绝大多数都在历史的长河中遗失了。"
D.Strings[19647]="第一名？哇！$B$B对像你这么年轻的弟子来说，这已经很不错了。"
D.Strings[19648]="嘿，第二名也不赖。你下次就能超过他们啦。"
D.Strings[19649]="魔古族大多是些暴徒和强盗。在我印象中，他们向来没有学习奥术魔法的耐心。"
D.Strings[19650]="我猜，科夏废墟就是某个重大事件的发生地。我可能是在那节历史课上打盹了。"
D.Strings[19651]="翻滚俱乐部的第一条规则：不要议论翻滚俱乐部。$B$B翻滚俱乐部的第二条规则：如果是你的第一次，你就翻滚吧。"
D.Strings[19652]="当我们遭到魔古族的伏击时，我们的使者正在去朱鹤寺的路上。"
D.Strings[19653]="我很奇怪，这些袭击者为什么能不计伤亡地拼命攻击我们。"
D.Strings[19654]="他们扒走了遇难者身上的衣物，偷走了我们家里的装饰品，还掠走了我们熔炼出来的铁锭。这是什么样的行径？"
D.Strings[19655]="朱鹤寺通常都会来帮我们抵御这些强盗。但近来他们却一点动静也没有。"
D.Strings[19656]="<口水从贾古的嘴角淌了下来。>"
D.Strings[19657]="要我送你一程吗？"
D.Strings[19658]="呜呜噜噜……我喜不喜欢礼物？那当然了！有谁会不喜欢礼物呢？"
D.Strings[19659]="胃里空空，光喝可不解饱。给锦鱼人来点吃的吧，好吗？"
D.Strings[19660]="礼物？我有个主意。$B$B你知道什么和可口的饮料最搭吗？是美味的小吃。"
D.Strings[19661]="你听说过煎炸胡萝卜吗？这是我的最爱。真想现在就吃到嘴……嗝！"
D.Strings[19662]="我曾经吃过一只可爱的苹果，太美味了。$B$B<贾古呆呆地眺目远方，似乎走神了。>"
D.Strings[19663]="你需要什么吗？我这会有点儿……忙。$B$B<科洛捏紧了正在挣扎的蜥蜴人的脖子。>"
D.Strings[19664]="有谁不喜欢收到礼物呢？$B$B我——我喜欢花。"
D.Strings[19665]="你应该把漂亮的花送给漂亮的女士，比如我。"
D.Strings[19666]="这附近长着很多漂亮的花，而我最喜欢的是泽地百合。可惜，那种美丽的花很难找到。"
D.Strings[19667]="你知道我最想要的是什么吗？一大碗迷雾汤。那一定很好喝。"
D.Strings[19668]="<布兰琪的吼声震彻风暴。>$B$B你成功了！锅炉和酒桶都到位了……现在我们就等着大自然显现神迹吧。$B$B你觉得呢？准备好来点烟火吗？"
D.Strings[19669]="我可以告诉你镇上每一个人的住处，你想找谁？"
D.Strings[19670]="艾拉住在农田的最西边，就在风暴烈酒酿造厂的北边。$B$B她的父母死后她就一直独自生活，可怜的孩子。"
D.Strings[19671]="老农山掌住在西北边的山上，他的农场就在山的南边。$B$B那个可怜的老人自从儿子死后就再也不和人交往了。"
D.Strings[19672]="吱吱的农场在西北边，就在山上不远处。$B$B那个可怜的家伙总是被疾病缠身。"
D.Strings[19673]="那个奇怪的女孩阿烁总是在山上转来转去。$B$B没人知道她从哪儿来，但她受过杀手的训练。$B$B以前帮我们对付猢狲时露过一两手。她是个好女孩，但是话不多。"
D.Strings[19674]="哦，玉儿？那个可爱的女孩住在北边码头。$B$B我在她还是个小姑娘的时候就认识她了。$B$B她总是在泥里挖来挖去，或在湖里游来游去，或在林间上串下跳。她父母还真给她起对名字了，因为她就像鱼一样滑溜。"
D.Strings[19675]="我父亲住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B他拥有山谷里几乎所有的肥沃土地，而且他从不让任何人忘记这一点。$B$B这就是我离家出走的原因。因为他觉得所有东西……所有人，都是属于他的。"
D.Strings[19676]="我的姐姐和我父亲一起住在田地中间的农舍里，就在那座古旧的仙鹤雕像东边。$B$B我很希望能时不时地见到我姐姐，但她这些天来总是忙于梳妆打扮，好引起那些路过这里的农场小伙的注意。"
D.Strings[19677]="啊，贾古……他很有可能醉倒在摊位后面了。只要往酒吧南边走上几步就能找到他。$B$B他不久前流浪至此，然后再也没离开过。$B$B这里人人都喜欢他，他可是个预测收成的行家。"
D.Strings[19678]="有些人你找不到？好吧，他们只可能出现在三个地方。$B$B要么在市集里，要么一整天待在家里，要么在日歌农场里。$B$B如果这三个地方还找不到他们，那你就该去检查下你的眼睛了！"
D.Strings[19679]="农夫老方住在镇子北边，就在水塔附近。$B$B算我倒霉，我跟他很熟。"
D.Strings[19680]="你在找谁？把地图给我，我帮你标出来。"
D.Strings[19681]="这里的树是我这一路上所见过最漂亮的。"
D.Strings[19682]="博学者瓦尔德林坚信他可以找到青春之池。$b$b想象一下，如果成功的话，那将为我们的人民带来什么啊，我们将再次获得永生……"
D.Strings[19683]="高阶女祭司泰兰德曾对批准此任务犹豫不决。$b$b她似乎觉得瓦尔德林的研究来源是一把双刃剑。$b$b在那个奥法地牢度过许多时日后，我开始认为她或许是对的。"
D.Strings[19684]="康说魔古是一群暴徒和强盗。$b$b根据我们迄今为止的观察，我认为他们也许会成为熊猫人种族最大的威胁。"
D.Strings[19685]="呃！你好……$B$B<艾拉的脸红了，她害羞地低下头。>"
D.Strings[19686]="幸运的是，地牢已被关闭，我们在传送门另一端的盟友可以把补给品传送过来了。$b$b不幸的是，我们还未能解除这个阻止我们通过传送门回传物品的封印。"
D.Strings[19687]="这些魔古都是从哪儿冒出来的？"
D.Strings[19688]="谢谢你救了我们，$c。希望我们的任务不会以失败而告终。"
D.Strings[19689]="这些“精灵”……他们信得过吗？"
D.Strings[19690]="先是螳螂妖，接着又是魔古。真是暗无天日啊。"
D.Strings[19691]="我不知道你为什么会来禁忌之林，但我很高兴你来了。要不是你，我们可能已经成了奴隶……或者更糟。"
D.Strings[19692]="魔古族什么时候学会了使用魔法传送门？"
D.Strings[19693]="魔古族偏偏在这个时候发起攻击。螳螂妖也不消停，即便是连长城也挡不住他们。"
D.Strings[19694]="我们连做梦都是螳螂妖的进攻。我们希望朱鹤寺能为我们解梦。"
D.Strings[19695]="我们希望仙鹤能够帮忙解释我们看到的现象。$b$b螳螂妖！螳螂妖在攻击我们的家园，它们飞过城墙，成群结队地攻击我们。$b$b这样的噩梦是意料之中的事情，影像中发生的一切在城墙边栩栩如生。$b$B但是近来，这一幕幕的画面在我的眼前愈演愈烈，已经到达了一个顶点。"
D.Strings[19696]="你确实不了解潘达利亚。$b$B螳螂妖是长城外面的怪物，是西部的心腹大患，是出没在我们土地上的邪恶力量。$b$B每隔一千年，螳螂妖就会来我们的土地上肆虐，掠夺财物和食品。$b$b我们的大学者告诉我们说距离螳螂妖下一次侵袭还有好几年时间，但我们的梦向我们描述了另一番景象。"
D.Strings[19697]="我想念我的父亲。"
D.Strings[19698]="我父亲是不会白白牺牲的，我们得向螳螂妖发动进攻。"
D.Strings[19699]="这些魔古族的战斗风格跟我过去面对过的对手很不一样。他们自信满满。"
D.Strings[19700]="如果棘杖妈妈看到我现在的样子……"
D.Strings[19701]="朝石犁村进发，帮他们解除螳螂妖的威胁。"
D.Strings[19702]="想要清晰了解自己的心意，就要反省你的内心。"
D.Strings[19703]="让你的思绪澄净如水。深呼吸，然后保持平静。"
D.Strings[19704]="我喜欢将自己定位为本民族的历史学家。我相信，为了更好地理解现状，我们必须研究过去的历史。"
D.Strings[19705]="我们的守卫越强壮，我们生存下来的几率也就越大。但这显而易见，即使是对于像你这样的人而言。"
D.Strings[19706]="我们得更加刻苦训练。"
D.Strings[19707]="我已经把我所会的都教给我们的战士们了。不幸的是，这似乎还不够。"
D.Strings[19708]="猢狲总是使用卑鄙的游击战术，例如伏击和陷阱。很不幸是的，我们每次都会中他们的招。"
D.Strings[19709]="我们是水上的霸主，这也是我们为什么能坚守村子如此之久的原因。但是在陆地上，特别是丛林茂密的地方，猢狲拥有压倒性的优势。"
D.Strings[19710]="多亏了你，族长祝福了我未来的女婿。我想这意味着游酒家族和金酿家族的世仇终于可以终结了。$b$b不要告诉别人，其实我还是很感激你的。长年死抱着仇恨不放是很累人的。$b$b我们过去太固执己见了，需要某些新的事物，或新的人，来帮我们理清分歧、搁置争议。"
D.Strings[19711]="酒仙游酒愿意为你效劳。$b$b我游历翡翠林，只是为了寻找最好的酿酒材料。$b$b我可不像晨芳园里那个傲慢自大的金酿家族。$b$b他们只会用他们大型的酿酒厂进行批量生产。其实他们的酒也还行啦，如果你爱喝泔水的话。"
D.Strings[19712]="你今天想去哪里游览？"
D.Strings[19713]="噢天哪……我们到另一侧来了。这真让我欣慰。$b$b开启一道通往陌生地方的传送门可不是件容易的事啊。$b$b可要是容易的话，岂不是人人都能做到了。"
D.Strings[19714]="我们正在努力工作，和你的士兵一起受训。"
D.Strings[19715]="多亏有你，猢狲以后再也不会成为我们的威胁了。我们的村子现在可以重新投入建设和发展了。"
D.Strings[19716]="明天充满了无限的可能性，而这一切都多亏了你和联盟的大力相助。"
D.Strings[19717]="或许某天，你可以跟我多讲一些有关你们那片神奇的故土的情况。"
D.Strings[19718]="我们现在是朋友了，$n。我们村随时欢迎你回来。"
D.Strings[19719]="你的名字将在我们村子里世代传诵、流芳百世。"
D.Strings[19720]="或许某天，你可以带我去看看你的故乡。那里一定有着别样的风景。"
D.Strings[19721]="我们欠你一个很大的人情，$r。"
D.Strings[19722]="终于，这么多天以来，我第一次感到我们的未来还有希望。"
D.Strings[19723]="有朝一日，我会把你的故事讲给我的孩子听，$n。"
D.Strings[19724]="我已经和你的一些……联盟……朋友聊过了。你们的人相当有趣。"
D.Strings[19725]="你是$c吗， $n？我听过很多有关你的传闻，可从没想过能见到你本人。"
D.Strings[19726]="你的到来犹如一阵春风，沐浴了我们的部族。"
D.Strings[19727]="我必须承认，我一开始怀疑过你，$n，但你已经向我们的部落证明了你自己。"
D.Strings[19728]="等我们击溃联盟和他们的盟友，并占领这片土地之后，它就将成为部落百折不挠的精神最强有力的证明。"
D.Strings[19729]="你救了我的儿子，还有我的牧场。我这辈子都会感激你的，陌生人。假如哪天你想要一头干净的牦牛，你知道该去哪找我。"
D.Strings[19730]="我一直找不到答案……$b$b$c，有时候你必须后退几步，才能看到整片森林。"
D.Strings[19731]="我的视力可能不行了，但幸运的是，我生活在一个到处都充满了感知的土地上。"
D.Strings[19732]="聪明的幸运儿会来选购我的货物。只有倒霉蛋才会匆匆走开。"
D.Strings[19733]="每一笔、每一画，都包含着千层含义。"
D.Strings[19734]="在我一生中，曾写下过无数强大的真言。可对于最强大的真言，我始终未窥门径。"
D.Strings[19735]="我更喜欢独自工作。"
D.Strings[19736]="能找到一头干净的牦牛可真是幸事。喂它喝我特制的佳酿则是更大的幸事。稞神牦牛就是这么制成的！"
D.Strings[19737]="多亏了你，采石场总算没事了。$B$B看来我得让小伙子们放个假……$B$B哈哈！我哄谁呢？瞧我自己也一本正经的样子。$B$B我们还有活儿要做呢！"
D.Strings[19738]="你完全不用担心我。$B$B啊啊啊啊！！$B$B我很快就能搞定，真的。"
D.Strings[19739]="你觉得那就算糟的了？我得说，你要是见过30年前那场灾难就不会这么想了。$B$B以前有个小伙子将他的午餐放在了外面——是某种鱼汤，如果我没记错的话。$B$B他把那锅炖汤放在中庭那里了——一大锅热气腾腾的鱼肉炖汤，没错，我现在记起来了——然后，我的老天，方圆百里之内所有猢狲都涌过来了。$B$B经历过那事之后，我已经不把几只发育过度的利齿蛛放在眼里了……"
D.Strings[19740]="这还远远不够！$B$B在潘达利亚的黑色泥土里埋藏着五件稀世珍宝：红宝石碎片、可爱的苹果、玉猫、蓝色羽毛以及泽地百合。$B$B只要你能将其中一件收入囊中，就能在附近找到愿意接受它们的人。$B$B找到其中一件并交给你喜欢的人，就有机会赢得他们的好感！每个人都会有他们最喜欢的东西，所以要跟他们多聊聊才能知其喜好。$B$B还有，这儿的人都很爱美食！说实话，谁不爱呢？如果你会做菜，那就再好不过了！$B$B关于礼物我就知道这些了。祝你好运！"
D.Strings[19741]="我去半山市集了。别碰我的蔬菜！\n\n——农夫老方"
D.Strings[19742]="你好，陌生人！"
D.Strings[19743]="我老爸无数次跟我说起过那个故事！$B$B大旱那段期间日子非常难过。农夫们都在用唾沫浇灌庄稼了，因为太干了。整个村子又饿又渴！$B$B所以农夫老愚的祖父在夜里收拾好自己的货车。$B$B然后骑着穆山兽直奔昆莱山脚下的湖泊。他在货车上装满了几百桶清水，然后立即返乡。$B$B他马不停蹄、日夜兼程！他如何能停下脚步？整个村子的人都快渴死了！当他赶着涨裂的货车回到田里时，穆山兽当场就累死了！$B$B但我们村子有了足够的水，并且还完成了春耕。$B$B泽被半山众生，老愚的祖父就是这样的人！"
D.Strings[19744]="你们这些城里人都这么没耐心？"
D.Strings[19745]="这货车可不会自己把自己修好的。"
D.Strings[19746]="要不这样吧。你接着嚎，我不干了。"
D.Strings[19747]="我既会园艺，又能打铁。我老爸把我教成了一个万能修理匠。"
D.Strings[19748]="维卡维卡只想试着经营农场。没想到竟然这么难。"
D.Strings[19749]="你是来帮我教训土拨鼠的吗？"
D.Strings[19750]="旅途愉快，$r！$B$B这天气现在看起来不错，但翡翠林的上空会伴随着风暴迅速阴沉下来。你能感觉到空气在变化吗？也许你想帮我酿造一些我传说中的闪电陈酿？"
D.Strings[19751]="啊，欢迎你。你是来买香料的吗？奇特的、稀有的、异国的香料？$b$b那你可来对地方了……邻居。"
D.Strings[19752]="我能帮你什么忙吗，$c？"
D.Strings[19753]="快进来，快进来！我今天能为你做些什么吗？"
D.Strings[19754]="吉娜？市集里的那个小女孩？哈哈！$b$b替我转告那个小美女，让她亲自来收钱。我相信在她跟我之间能达成某种……协议。"
D.Strings[19755]="我的债务？我可不欠她什么。$b$b我相当确认，那些香料，是她……送给我的。我看见她对我抛媚眼了。如果你跟我一样英俊潇洒，就也能经常碰到这种好事。$b$b你怎么还在这儿？快走吧，小$r。"
D.Strings[19756]="是的，好货品应有尽有。看看这用牦牛毛做的护符。非常热销。非常好运。"
D.Strings[19757]="我携宝物而来。来自远方的宝物。来自山那边的宝物……甚至有来自长城另一侧的宝物。"
D.Strings[19758]="今天可真是百年不遇的好日子啊，不是吗？"
D.Strings[19759]="聪明人会立刻还债。更聪明的人则会判断出自己是不是被敲诈了。$b$b吉娜一天到晚都坐在集市里数钱。而我却走在荒无人烟的路上，靠运气勉强糊口。我为什么应该付钱？"
D.Strings[19760]="吉娜的父亲很富有，超级富有。要是她缺钱，可以直接去跟他说啊。$b$b为什么非要跟可怜的老迦姆比兹过不去？"
D.Strings[19761]="进来坐坐，别老站着……我肯定你在外面跑了一整天了。$b$b那么，我有什么可以效劳的？"
D.Strings[19762]="今天外面挺暖和的，对吧？"
D.Strings[19763]="欢迎来到半山，邻居。"
D.Strings[19764]="我也想今天就能还上钱……但这段时间生意难做呀，我实在是没有钱。$b$b我身上仅有的几块金币还是准备给我家人买晚餐的。求求你……发发慈悲帮助我吧。"
D.Strings[19765]="我明白，我欠你钱。如果能还我肯定还了，但是……$b$b我急需这笔钱。我们的小店已经年久失修。如果我没钱付维修费的话，我不仅会失业……而且家庭也要垮了。"
D.Strings[19766]="看着如今这些来来往往的人。真会引发你对人生的思考。$b$b比如，也许……我也应该到别的地方来来往往一把。"
D.Strings[19767]="你觉得外面是什么样的？我是说，潘达利亚外面的世界？"
D.Strings[19768]="你总是四处游走，漫无目的吗？只是为了看看在山的那一边有些什么？$b$b妈妈总说我有一双停不下来的脚，除此之外还有个颠三倒四的大脑袋。可我觉得，也许犯糊涂的是她才对。"
D.Strings[19769]="额——噢……$b$b我也许不该告诉你，可我正在存钱，准备离开这镇子。我再也受不了只待在一个地方了。$b$b你是个冒险家……你明白的。能帮帮我吗？"
D.Strings[19770]="噢……噢不。要是让妈妈知道，我就有大麻烦了。$b$b你能帮我还债吗？"
D.Strings[19771]="只需要再等一小会儿。"
D.Strings[19772]="让我们看看谁更强大——是我的雷霆还是那块石头！我把钱押给雷霆。"
D.Strings[19773]="千万别低估一头好穆山兽的价值。"
D.Strings[19774]="<贾古斜睨着你。>$B$B嘿，我认识你吗？"
D.Strings[19775]="嘿哥们！很高兴再次见到你！$B$B嗝——儿！"
D.Strings[19776]="我的朋友又来看望贾古了？我今天能为你做点儿什么？"
D.Strings[19777]="你是我的好朋友，$n。也许是我唯一的朋友。"
D.Strings[19778]="你好啊$G兄弟:姐妹;！你是来向贾古请教问题的？"
D.Strings[19779]="嘿，你好。要回市集？我明白了。"
D.Strings[19780]="呃……到底要怎样呢？我还要经营市集呢。"
D.Strings[19781]="你来对地方啦！半山市集有你需要的所有东西。"
D.Strings[19782]="嘿，你是新来的吧。一路上有没有什么有趣的见闻啊？"
D.Strings[19783]="你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[19784]="嘿，$r。欢迎回来。"
D.Strings[19785]="呃……到底要怎样呢，哥们？我还要经营市集呢。"
D.Strings[19786]="你来对地方啦，哥们！半山市集有你需要的所有东西。"
D.Strings[19787]="嘿，哥们！有没有什么有趣的见闻啊？"
D.Strings[19788]="嘿，哥们。你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[19789]="嘿，$n。半山市集欢迎你。"
D.Strings[19790]="呃……到底要怎样呢，朋友？我还要经营市集呢。"
D.Strings[19791]="你来对地方啦，朋友！半山市集有你需要的所有东西。"
D.Strings[19792]="嘿，朋友！有没有什么有趣的见闻啊？"
D.Strings[19793]="嘿，朋友。你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[19794]="嘿，$n。我的朋友在半山市集总是大受欢迎的。"
D.Strings[19795]="呃……到底要怎样呢，我的好朋友？我还要经营市集呢。"
D.Strings[19796]="你来对地方啦，我的好朋友！半山市集有你需要的所有东西。"
D.Strings[19797]="瞧啊，这不是我的好朋友$n嘛。你知道我想要什么吗？啊哈，没错。有没有什么八卦啊？"
D.Strings[19798]="$n，我的好朋友！你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[19799]="嘿，$n。欢迎你，邻居！"
D.Strings[19800]="呃……到底要怎样呢，邻居？我还要经营市集呢。"
D.Strings[19801]="你来对地方啦，邻居！半山市集有你需要的所有东西。"
D.Strings[19802]="嘿，$n，你好啊。快跟我讲些八卦吧！"
D.Strings[19803]="你好，邻居！你是来购物的，还是来卖货的？请随便瞧瞧吧。"
D.Strings[19804]="你好。我们以前见过，对吗？"
D.Strings[19805]="哦，你这套衣服真漂亮。我之前居然没注意到。"
D.Strings[19806]="这里的人们都在谈论你。别担心，我会时不时地帮你说些好话的。"
D.Strings[19807]="你觉得这颜色衬我吗？"
D.Strings[19808]="嗨，哥们！真高兴又见到你。"
D.Strings[19809]="这些鞋子配上你的眼睛真是太漂亮了。"
D.Strings[19810]="这里的人们都在谈论你，哥们。别担心，我会时不时地帮你说些好话的。"
D.Strings[19811]="嗨，哥们！你觉得……我的耳环怎么样？"
D.Strings[19812]="你好，朋友。你的农场还顺利吗？"
D.Strings[19813]="既然大家是朋友了，我不得不说你的衣服实在是……太丑了。"
D.Strings[19814]="这里的人们都在谈论你，朋友！他们看起来都很喜欢你哦。"
D.Strings[19815]="拜托，作为朋友……实话告诉我，我的衣服怎么样？真有那么……糟吗？"
D.Strings[19816]="既然大家是朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。"
D.Strings[19817]="你不觉得农夫老方很……迷人吗？"
D.Strings[19818]="$n，我的好朋友！我希望你和老愚在农场一切顺利。"
D.Strings[19819]="既然大家是好朋友了，我不得不说你的衣服实在是……太糟了。"
D.Strings[19820]="这里的人们都在谈论你，$n！你打破了这里的平静。"
D.Strings[19821]="拜托，作为好朋友……实话告诉我，我的衣服怎么样？真有那么……难看吗？"
D.Strings[19822]="既然大家是好朋友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？"
D.Strings[19823]="你好，邻居！我希望你和老愚在农场一切顺利。"
D.Strings[19824]="既然我们是死党了，我不得不说你的衣服实在是……难看死了！"
D.Strings[19825]="这里的人们都在谈论你，$n！我跟所有人都说你是我的邻居。"
D.Strings[19826]="拜托，作为挚友……实话告诉我，我的衣服怎么样？好吗？$B$B哦？你觉得很好？哎呀，谢谢你！这就是为什么你是我一辈子的朋友！"
D.Strings[19827]="既然我们是挚友了，我得向你坦白一件事情。我……我觉得我很喜欢农夫老方。但是，农夫老愚的眼睛也很迷人，不是吗？$B$B哦，我左右为难啊！"
D.Strings[19828]="嘿，看啊，是镇上新来的$G小伙子:小姑娘;。"
D.Strings[19829]="你对牦牛有研究吗，菜鸟？我可熟悉得很。"
D.Strings[19830]="你知道谷里谁家的蔬菜长得最大吗？远在天边，近在眼前！"
D.Strings[19831]="嘿，哥们，发生什么事了？"
D.Strings[19832]="嘿，哥们，随时欢迎你来欣赏我的牦牛。"
D.Strings[19833]="嘿，$r，看在哥们的情分上，我要跟你说个秘密。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！"
D.Strings[19834]="嘿，朋友，怎么了？"
D.Strings[19835]="嘿，朋友，随时欢迎你来欣赏我的牦牛。"
D.Strings[19836]="嘿，朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？你得用肥料。$B$B那你知道谷里谁的肥料最好吗？我！"
D.Strings[19837]="我的好朋友！农场的情况怎么样？"
D.Strings[19838]="我的好朋友，你今天过得好吗？$B$B听着，一般人我不告诉他——可如果你需要牦牛，就跟老方说一声。"
D.Strings[19839]="我的好朋友，告诉你个秘诀。你想种出大个头的蔬菜吗？$B$B你得细心照料它们。浇水、施肥，还要献出你的爱。"
D.Strings[19840]="嘿，邻居！农场一切都好？"
D.Strings[19841]="你好啊邻居，今天过得怎么样？$B$B毛毛好吗？"
D.Strings[19842]="嘿，邻居！那些蔬菜看起来真不错。"
D.Strings[19843]="嘿，你好！我以前见过你？"
D.Strings[19844]="嘿，你好！以前没在这附近见过你啊。"
D.Strings[19845]="嘿，城里人！你有没有什么有趣的故事跟我分享啊？我超爱讲故事！"
D.Strings[19846]="嘿，你有没有听过关于老农阿蓟的故事？那是我所听过的最好的故事了。"
D.Strings[19847]="嘿，你的名字为什么叫$n？这名字不怪吗？"
D.Strings[19848]="这里的人们心地善良……在这儿待久了你就会发现。"
D.Strings[19849]="我老爸常说鱼儿会游、鸟儿会飞。假如我既会游又会飞，那我成啥了？"
D.Strings[19850]="嘿，哥们！很高兴再次见到你。"
D.Strings[19851]="嘿，哥们！我很喜欢那个关于小男孩阿尔萨斯的故事。你还有其他故事分享吗？"
D.Strings[19852]="嘿，哥们！我很喜欢那个关于兽人萨尔的故事。你还有其他故事分享吗？"
D.Strings[19853]="老农阿蓟在那山上有一小块地皮。$B$B有一天他在那挖呀挖呀，也不知道自己挖了多深，突然发现在山底下居然有一个洞穴！$B$B你猜他在洞穴里发现了什么？"
D.Strings[19854]="你是说“玉儿”也是个怪名字？它一点儿也不怪，哥们！我的名字取自于湖里的那些鱼！$B$B现在说说你的名字“$n”是啥意思，啊？你倒是说啊！"
D.Strings[19855]="老爸常告诫我要多交朋友少结仇，那就是为什么你会是我哥们！"
D.Strings[19856]="嘿，朋友！很高兴再次见到你。"
D.Strings[19857]="嘿，朋友！再给我讲讲世界之树的故事和那个……啥来着……世界的分裂！"
D.Strings[19858]="老农阿蓟发现了一个堆满金银财宝的洞穴！！！$B$B那里有黄金、钻石、翡翠、雕像，还有一整屋的古籍！$B$B他在洞穴里徘徊许久。很快，一整天就过去了，他感到非常饥饿。$B$B于是他就沿着来时的路往回走，却找不到回去的路了！"
D.Strings[19859]="既然我们是朋友了，你可以叫我玉儿。$B$B哈哈！我真逗！$B$B我开玩笑的……每个人都叫我玉儿！因为每个人都是我的朋友！"
D.Strings[19860]="老爸常告诫我——甜菜味虽美，友情价更高。那就是为什么你会是我的朋友，$n！"
D.Strings[19861]="你好，$n！"
D.Strings[19862]="嘿，我的好朋友！再给我讲讲那头可怕的巨龙——死亡之翼的故事！"
D.Strings[19863]="老农阿蓟被困在了洞穴里，于是他吹哨召唤他忠诚的穆山兽——波波！$B$B很快，他就听到了一声巨响，是波波在洞穴里炸出了一个洞！$B$B那头穆山兽听从了主人的召唤而来！$B$B而后，整个洞穴开始摇晃起来，洞顶开始坍塌。$B$B老农阿蓟跳上波波的后背，你知道后来发生了什么吗？"
D.Strings[19864]="知道吗，我的好朋友。我这辈子见过不少有趣的名字。玉儿真不算奇怪。不，一点儿都不奇怪！"
D.Strings[19865]="老爸常告诫我——萝卜虽爽口，友情价更高。那就是为什么你会是我的好朋友，$n！"
D.Strings[19866]="你好，邻居！你今天打算做啥？"
D.Strings[19867]="你好，邻居！我太爱听故事了，我真想把它们都听个遍！$B$B不过你知道的，我想我们一起编了不少好故事，不是吗？"
D.Strings[19868]="那洞穴开始坍塌，老农阿蓟和波波拼命跑！他们腾挪闪躲，在山洞中穿梭，直到在那山上破地而出！$B$B然后那个洞穴在他们身后合拢起来，就好像被大地吞没了一样。$B$B老农阿蓟浑身打颤，但是他到家做的第一件事就是给那个堆满财宝的洞穴画了一张藏宝图。因为那洞穴或许还在那儿，不是吗？$B$B他做了件正确的事，因为到了第二天，他就想不起来洞穴在哪儿了。接着又过了一天，他忘得更厉害了，后来就连那洞穴的事也忘得一干二净。"
D.Strings[19869]="嘿，邻居，我们到底在谈些什么啊？名字什么的无所谓啦！$B$B就像我爸常说的那样——即便你爱吃的粉瓜被叫作洋葱，你还是会吃的，对不？"
D.Strings[19870]="老爸常告诫我——土地诚可贵，友邻价更高。现在真被他说中了！$B$B那就是为什么你会是我的邻居，$n！"
D.Strings[19871]="我在这附近照看着几头猪。"
D.Strings[19872]="嘿，哥们！这些猪今天看起来不错嘛！"
D.Strings[19873]="你好，朋友！你下去见过我的猪了吗？"
D.Strings[19874]="你好，我的好朋友！为啥我爸妈没给我起名叫猪呢，我还挺费解的。"
D.Strings[19875]="嘿，邻居！你农场里的那些猪咋样？我敢打赌它们一定过得相当快活！"
D.Strings[19876]="你是新来的吗？"
D.Strings[19877]="嘿，吱吱真的很忙。你想要什么？"
D.Strings[19878]="吱吱的羊羊好怕怕……山里的坏猴子！坏猴子！"
D.Strings[19879]="嗨，我认识你。你帮过我，对吗？"
D.Strings[19880]="吱吱有大麻烦了。很大、很大的麻烦。"
D.Strings[19881]="吱吱为农场付出很多，现在被坏猴子夺走了！"
D.Strings[19882]="嘿，你是吱吱的哥们，对吗？"
D.Strings[19883]="吱吱遇到大麻烦了。很大、很大的麻烦。你能帮帮吱吱吗，哥们？"
D.Strings[19884]="吱吱为农场付出很多，你能明白的，对吗哥们？"
D.Strings[19885]="嘿，朋友。我遇到麻烦了，但又不想连累你。"
D.Strings[19886]="嘿，朋友，农场现在怎么样啦？"
D.Strings[19887]="吱吱是唯一一个有农场的猢狲！$B$B<吱吱骄傲地拍打自己的胸脯。>$B$B你，朋友，有空来转转，好吗？"
D.Strings[19888]="我的好朋友！有空来和吱吱喝两杯，怎么样？"
D.Strings[19889]="好朋友，你过得怎么样啊？"
D.Strings[19890]="吱吱的农场只有羊！$B$B谁想要羊，就来找吱吱。"
D.Strings[19891]="嘿，邻居！你喜欢羊吗？"
D.Strings[19892]="邻居，多亏你，我减轻了不少麻烦。"
D.Strings[19893]="我把我最好的羊给你，邻居！你觉得怎么样？"
D.Strings[19894]="哦！嗨！呃……我或许该……走……$B$B<艾拉红着脸，窃窃私语道。>"
D.Strings[19895]="你喜欢……芜菁吗？$B$B<艾拉脸红了，摇了摇头。>"
D.Strings[19896]="你喜欢猫咪吗？我喜欢！$B$B<艾拉为她的冒失愣住了，害羞地笑了笑。>"
D.Strings[19897]="嘿，你好啊，$n。今天过得怎么样？"
D.Strings[19898]="我在我家的农场里种芜菁。哦……我也不知道你想不想听那个……"
D.Strings[19899]="我的猫也没那么多，不是吗？我意思是，这么想还是说得过去的。"
D.Strings[19900]="嘿，你好啊，朋友！多好的天，不是吗？"
D.Strings[19901]="这些猫一直陪伴着我。自从我父母离世后，一个人在农场很寂寞……$B$B哦不，我并不想和你说这么多的。"
D.Strings[19902]="你好，我的好朋友。哦，我管你叫我的好朋友，你介意吗？"
D.Strings[19903]="我在闲暇时间会利用各种各样的酒来做实验。$B$B而且风暴烈酒酿造厂就在街对面，我有时更按耐不住了。$B$B哦，但是也没有其他地方能酿造出比这儿更好的酒了。"
D.Strings[19904]="我有多少只猫？$B$B噢，呃……我想我已经数不清了……"
D.Strings[19905]="你好，邻居！今早的芜菁看上去真不错啊。"
D.Strings[19906]="我将我的一些酒分享给镇子里的人，每个人都大加赞赏！我真是不敢相信！"
D.Strings[19907]="露娜还好吗？她可乖啦！"
D.Strings[19908]="田里有麻烦啦。我告诉你，不论是兔妖还是猢狲，都不是什么好东西。"
D.Strings[19909]="没错，我就是阡陌客的首领。你为什么要问这个？"
D.Strings[19910]="的确，这里的农田非常肥沃，但这都缘于我们起早贪黑、没日没夜的辛勤劳作！"
D.Strings[19911]="嘿，哥们，你有没有对付猢狲或兔妖的经验？"
D.Strings[19912]="哥们，你知不知道每位风尘仆仆的农夫都是阡陌客的一员？"
D.Strings[19913]="嘿，要不是我的哥们$n！我恐怕要在农田里耗上一整天了。"
D.Strings[19914]="嘿，朋友，你有没有对付猢狲或兔妖的经验？"
D.Strings[19915]="嘿，朋友，今天的地看起来怎么样啊？"
D.Strings[19916]="$n，我的朋友！让我们来一起喝一杯吧。"
D.Strings[19917]="好朋友，你肯定知道一两个消灭兔妖的办法。"
D.Strings[19918]="知道吗，好朋友常常会分享他们的务农小秘密。现在告诉我吧，你是如何把你的蔬菜种成那样的？"
D.Strings[19919]="在田里劳作一整天，会让人口干舌燥。你懂我的意思吧，好朋友？"
D.Strings[19920]="嘿，邻居，那头穆山兽活儿干得怎么样啊？她可是个大美人，不是吗？"
D.Strings[19921]="既然我们现在成邻居了，你得告诉我你的务农小秘密。你用化肥了？增长素？除草剂？快告诉我嘛！"
D.Strings[19922]="你好，邻居。想来杯冰镇啤酒吗？"
D.Strings[19923]="唉，我很忙，你看不到吗？"
D.Strings[19924]="你总是这么烦人吗？真是的。"
D.Strings[19925]="呸！我知道我见过你，但那并不意味着我们是朋友。快滚！"
D.Strings[19926]="嘿，哥们，我现在很忙。你能过会儿再来吗？"
D.Strings[19927]="哥们，你可真是个话痨。你嘴巴啥时候闲过？"
D.Strings[19928]="哥们，你知道某些时候……还是很高兴见到你的。"
D.Strings[19929]="嘿，朋友，我有点小忙。我这儿有你需要的东西吗？"
D.Strings[19930]="朋友，你真是一逮到机会嘴巴就说个不停。不过时不时的听人唠叨两句总比死一般的沉寂要好多了。"
D.Strings[19931]="你好，朋友。有没有尝过我家的新鲜鸡蛋啊？超美味的，我跟你说。"
D.Strings[19932]="嘿，朋友，感谢你今天的来访。"
D.Strings[19933]="嘿，这不是我的好朋友$n嘛！我能帮你什么忙吗？"
D.Strings[19934]="我的好朋友，你今天给我带什么消息了吗？"
D.Strings[19935]="你知道吗，$n，我得承认我偶尔会盼望你的到来。"
D.Strings[19936]="嘿，$n，我一直在想你的农场是否需要一些小鸡。你认为呢？"
D.Strings[19937]="你好，邻居。今天天气不错啊。"
D.Strings[19938]="嘿，邻居！今天地里看起来就像是一枚闪闪发光的新铜币。"
D.Strings[19939]="你好，邻居！很高兴见到你！你随时都可以来找我，听到了吗？"
D.Strings[19940]="你好吗，$n？那些小鸡还好吗？$B$B一定要仔细找找它们的蛋，那些该死的小家伙就喜欢把蛋藏在最古怪的地方！"
D.Strings[19941]="安静，陌生人。我需要集中精神来完成手头的任务。"
D.Strings[19942]="我对你没什么意见，陌生人。"
D.Strings[19943]="只有在寂静中，我们才能听到林木间的窃窃私语。"
D.Strings[19944]="安静，$r。请别分散我的注意力。"
D.Strings[19945]="我在这一带见过你。我能从你这身行头上看出来，你是一个$c。"
D.Strings[19946]="能说会道只能得点小聪明，善于倾听才会明白大智慧。"
D.Strings[19947]="嘿，哥们，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[19948]="别跟我讲什么样才算一个$c，露两手给我瞧瞧。"
D.Strings[19949]="我在研究猢狲的动作。等我找到他们的弱点时，我就会出击。"
D.Strings[19950]="我的朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[19951]="我的朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。"
D.Strings[19952]="智者不会仓促行事。智者运筹帷幄、决胜千里。"
D.Strings[19953]="我的好朋友，你弄出来的噪音都能把一群穆山兽给吓跑了。"
D.Strings[19954]="我的好朋友，总有一天我们要弄清楚谁更厉害——是你，还是我。"
D.Strings[19955]="在我的家乡，一个人能送给好朋友的最好的礼物，就是一棵树了。$B$B你知道为什么吗？$B$B树代表了和平、成长和生命。它是对友情的一种祝福。"
D.Strings[19956]="邻居，你今天手脚蛮轻得嘛。"
D.Strings[19957]="邻居，我会很高兴和你并肩作战的，无论何时。"
D.Strings[19958]="你喜欢这颗树吗？树苗可是我亲自挑选的。"
D.Strings[19959]="嘿，朋友，你知道做成好买卖的诀窍吗？那就是销售。你需要一条渠道，将你的货物卖到需要的人手中。"
D.Strings[19960]="你知道我在想什么吗，我的好友？你需要一个方法，能够在家中和你所有的朋友保持联系。$B$B我认识一个木匠，他可以上门帮你安装邮箱。这主意不错吧。"
D.Strings[19961]="那邮箱用起来感觉如何啊？是个不错的主意吧？"
D.Strings[19962]="嘿，朋友，你不觉得农夫老愚的房子看起来空荡荡的吗？"
D.Strings[19963]="我对家居装潢略知一二，我的好朋友。我知道农夫老愚的房子缺什么！"
D.Strings[19964]="嘿，邻居！你觉得农夫老愚家里的新家具看起来如何啊？没错，那都是我亲自挑选的！"
D.Strings[19965]="吱吱爱吃谷地小炒。你要是找到了，就带给我！"
D.Strings[19966]="吱吱喜欢看天空，那么美……那么蓝……"
D.Strings[19967]="噢，礼物？我还以为你没打算送我东西呢！"
D.Strings[19968]="你了解我的……我喜欢猫！"
D.Strings[19969]="既然你提到了……我妈做的虾饺最好吃了。$B$B唉……我好想她……"
D.Strings[19970]="你知道吗，我唯一赞赏的是一种生长在这附近的稀有的白色百合，它们和我的外表不分伯仲。$B$B可是，它非常难得。"
D.Strings[19971]="你吃过香烤野雉吗？$B$B嗯！我真想立刻尝上几口！"
D.Strings[19972]="的确，我是很博爱，但我最喜欢的还是动物！"
D.Strings[19973]="你知道吗，我一直都很喜欢玉石的颜色。如此翠绿，就和那森林一样。"
D.Strings[19974]="多傻的问题啊！我给你个提示吧。我最喜爱的食物里有我的名字！或许还不止一个哦！"
D.Strings[19975]="哦，你不必啦！哦，但我确实喜欢礼物，所以……或许……你还是送吧。"
D.Strings[19976]="我喜欢所有漂亮的或是闪闪发光的东西。"
D.Strings[19977]="哦，你了解我的。我是个谦逊的女孩，所以我只想要些红宝石。$B$B什么？我又不是跟你要钻石！"
D.Strings[19978]="好吧，最近我特别想吃焰灵鲑鱼。"
D.Strings[19979]="我可没骗你哦，$n。我是这谷里数一数二的大人物。大多数人都会送我非常贵重的礼物。"
D.Strings[19980]="我要告诉你一件事，$n。我喜欢玉石，但那不是我的最爱。所有人都给我玉石，老是这样！"
D.Strings[19981]="既然你提到了，我想吃碳烤虎肉排都想了好久了！我们谷里并没有多少老虎，所以这盘菜不是那么好搞的哦。"
D.Strings[19982]="不，像我这么一个老头已不需要任何东西了。但我的儿子……他现在喜欢收集蓝色羽毛……"
D.Strings[19983]="每当我的儿子找到一根蓝色羽毛时，常会说那是他在天国的妈妈，给他的一个吻。$B$B<老农山掌停顿住，因为哽噎无法继续。>"
D.Strings[19984]="我妻子常会做一道美味的炖龟肉，那味道一定能带来美好的回忆。"
D.Strings[19985]="我喜欢纯天然的东西。"
D.Strings[19986]="干我们这行的女孩常会感到饥饿，你知道吗？我真希望我有好东西吃。"
D.Strings[19987]="花是很美，但那不是我的最爱。"
D.Strings[19988]="我害怕鸟！它们的羽毛的确很艳丽，但那不是我的最爱。"
D.Strings[19989]="你有没有吃过锦绣鱼？那是我的最爱。"
D.Strings[19990]="在这里酿造！"
D.Strings[19991]="你听说过爽脆胡萝卜吗？它们明天会变得更加爽脆。"
D.Strings[19992]="南瓜！会长出巨大、无比大的南瓜！"
D.Strings[19993]="我在你的未来里看到了粉色芜菁。"
D.Strings[19994]="地里长满了白色芜菁。脆爽劲辣！"
D.Strings[19995]="你想吃肉？我这里有很多。$b$b我的意思是，在我的烤架上。"
D.Strings[19996]="你摇响了神龛上的铃铛。你现在可以向它提问，许愿也行！"
D.Strings[19997]="你和阿烁成了熟人。"
D.Strings[19998]="只有挚友才行。"
D.Strings[19999]="我们在这里已经很少能见到新面孔了。"
D.Strings[20000]="已经没有多少人有勇气穿越山脉了，朋友。如今，某些人会说你一定是疯了才要这么干。"
D.Strings[20001]="炼金跟魔法有点像，不是吗？只要略作增减，其效果就会从妙手回春，变成杀人不眨眼。"
D.Strings[20002]="我这里卖的都是既神奇又难得的宝贝。快来瞧瞧吧，不过别乱碰。"
D.Strings[20003]="补给品有限，可我只从贸易者手中购买最好的货物。"
D.Strings[20004]="高山发怒了，陌生人。现在可不适合出行。"
D.Strings[20005]="我的种子长出的菜是谷里最好的，我保证！"
D.Strings[20006]="一定要全力以赴，$n。雷掌阁需要我们。你准备好了结此事了吗？"
D.Strings[20007]="一件干净的武器表明它的主人并没有经历过战斗。"
D.Strings[20008]="武器应该是战士身体的一部分。像爱惜你自己一样，爱惜你的武器，它就不会让你失望。"
D.Strings[20009]="堂弟破烂骰在搞走我所有辛苦挣来的钱和货物！我早该知道不能相信一个土地精的。绝不能相信任何只有你一半高的东西……"
D.Strings[20010]="哦，天呐，一个访客。你的到访让我非常开心。"
D.Strings[20011]="脚步轻点，前面危机四伏。"
D.Strings[20012]="我从未想过种地也会有如此多……奇妙的感觉。"
D.Strings[20013]="你的拇指已经变绿了？$B$B我的看起来也差不多一样。"
D.Strings[20014]="嗯哼。$B$B“我觉着白天的时间太短了！”$B$B听起来咋样？太强硬了？你觉得会在市集上流行起来吗？"
D.Strings[20015]="在我们开始种地之前，我从没想过餐桌上的食物是从哪儿来的。$B$B可以说，这份经历让人很受启发！"
D.Strings[20016]="当然！$B$B是什么问题？"
D.Strings[20017]="干枯的农作物需要水！$B$B你可以用我爷爷留下的那个生锈的老式洒水壶。我把它放在那个树桩旁边了，就在田地边上。"
D.Strings[20018]="干枯的农作物需要水！$B$B有了洒水器我们就可以很轻松地照料它们了！那东西应该就在田地边上。"
D.Strings[20019]="遭虫害的农作物上爬满了害虫，真恶心！$B$B不过，既然我们有了脉波发射器，那就应该能轻而易举地消灭它们。用它来赶走那些害虫真是一种人道的方式，毫无杀虫剂成分！$B$B嘿，那是不是说我们的菜也算是有机蔬菜了？"
D.Strings[20020]="有东西在摇晃，嗯？好吧，正如爷爷常说的那样：胡萝卜可不会跳舞！$B$B有东西正试图从我们脚下拉走那些蔬菜！$B$B如果你想保护好这些农作物，恐怕你得杀掉那些在下边作祟的捣蛋鬼。是令人心碎，我知道，但这是工作的一部分。"
D.Strings[20021]="哎，有时候蔬菜长得如此漂亮，就好像是在祈求被人偷走一样。$B$B爷爷说一只平原鹰能比市集上的任何人更好地挑出一个上等的南瓜，然后能以比那啥还快的速度偷走它……呃……$B$B“比热锅上的猢狲还快。”$B$B我猜你会说诸如此类的话？$B$B关键是，你一定要保护诱人的农作物免遭虫害！"
D.Strings[20022]="快闷死的农作物之间夹杂着一种杂草！$B$B你需要像对付长在地里的难除杂草一样对付它们——得花大力气！抓住那些烦人的杂草，尽全力拔出来。该做个了结了。"
D.Strings[20023]="野生的？！真令人吃惊！爷爷常说他降服野生农作物的故事。$B$B“小愚，”他说，“别害怕去拍打你周围的大葱。”$B$B我一直觉得他很伟大。"
D.Strings[20024]="小矮子！哈！这个词我很久没听到过了！$B$B当我拒绝起床或者去什么地方的时候，爷爷总是会那么叫我。按照他的说法，他会抓住我的脖子就像“拔出一株矮小的甜菜”那样把我提起来。$B$B这些农作物只要拔一下就能长直了。牢牢抓住它们，然后往上提。"
D.Strings[20025]="纠缠的杂草，嗯？卑劣的小恶魔。它们会钻进地下差不多十五码——如果你想根除它们的话，就必须要连根拔起。$B$B抓住杂草露出地面的部分，然后一直向外拔，直到你看到根部被完全拔出来为止。就是这么回事。"
D.Strings[20026]="有时候兔妖会在地里打洞然后住进去，盼着蔬菜能掉到它们头上——我想它们是觉得我们把蔬菜放进土里是有什么原因的。$B$B赖着不走的家伙，我爷爷是这么叫它们的。你得脚踏实地，我是说字面意思。你用脚使劲跺地面，把它们震出来！"
D.Strings[20027]="难除的杂草！它们就是一种顽疾，会在土壤中蔓延，侵占你的土地。$B$B在你耕种之前，你需要先清除杂草。真的没什么窍门——就是抓住它们然后拔出来！$B$B按我爷爷的话说，“你得比那些杂草还顽固！”"
D.Strings[20028]="你要汇报什么？"
D.Strings[20029]="锦绣谷很平静。太平静了。"
D.Strings[20030]="有时候最美丽的事物也是最致命的。看着我！"
D.Strings[20031]="现在你该做的就是等！大多数农作物在开始生长之后的第二天就成熟了。$B$B在这样肥沃的山谷里拥有一块土地不是很幸运的事吗？"
D.Strings[20032]="魔古族突破了我们的防线……$B$B他们的魔玉战士大军人数太多，我们抵挡不住。$B$B我在后方照顾车，但其他人撤进了城里，准备背水一战。"
D.Strings[20033]="影踪派不在这儿，因为他们必须守护城墙。土地精欠影踪派太多了。如果影踪派没能保护土地精，那就意味着他们陷入了危险的境地，而且比任何时候都更需要土地精脚夫。"
D.Strings[20034]="呷卟督曾是土地精的朋友。他整整统治了三季。现在改由呜咔督掌权，他是脾气最为暴躁的一个。他认为来自土地精的食物供应很快就会中断，因此他开始四处掠夺。"
D.Strings[20035]="猢狲用我的牦牛来喂养他们的宠物雪人。这运气真是糟糕透顶。"
D.Strings[20036]="堂弟兔子脚也许又高又聪明，还浑身散发着好运与福气。但他却对我的幸运符牦牛鞋冷嘲热讽。"
D.Strings[20037]="想看我的幸运符吗？我还很小的时候就穿着这双牦牛鞋。多年来这双鞋给我带来了很多好运。"
D.Strings[20038]="你的幸运符是什么？所有旅行着都需要带着幸运符上路。"
D.Strings[20039]="啊，$r是最有用的。未雨绸缪，应该准备更多的$r。"
D.Strings[20040]="锦绣谷是我的家园，保护它免遭侵犯既是我的责任，亦是我的愿望。"
D.Strings[20041]="今天的风正好。"
D.Strings[20042]="幸运对着土地精的坐骑微笑。"
D.Strings[20043]="高山会原谅飞鸟，但不一定会宽恕骑手。"
D.Strings[20044]="巨魔……我还以为他们只是传说！"
D.Strings[20045]="锦绣谷曾是伟大的魔古帝国的权力中心。魔古族统治的时代非常恐怖、残酷和血腥。"
D.Strings[20046]="请在此处休息，$n。我希望山谷会带给你和平与欢乐。"
D.Strings[20047]="欢迎来到赤精栖木，朋友。"
D.Strings[20048]="这里便是朱鹤的神圣发源地，他叫赤精，是南部的天神。赤精的追随者和侍僧聚集在此处锻炼身体，磨练心神。他们彼此间互相切磋，以期让朱鹤见证他们的成长。$b$b欢迎你加入我们的训练行列，$c。带着你那烈酒般的雄心和烈酒般的功夫。"
D.Strings[20049]="欢迎来到渔人码头，$r。请随意逛逛，你在这里可以学到很多钓鱼知识。"
D.Strings[20050]="<大块头雪人看着你，眼神里充满期待。>"
D.Strings[20051]="有鱼上钩了！"
D.Strings[20052]="你在看什么呢，陌生人？"
D.Strings[20053]="我绝不能就这么死掉。绝不！"
D.Strings[20054]="走开，别管我。让我安静地体味痛苦吧。"
D.Strings[20055]="赢的人应该是我。我更强壮，也更聪明。我本来是可以赢过他的！"
D.Strings[20056]="魔古族正在策划重大的阴谋。我们得阻止他们，决不能再让他们获得远古武器了。"
D.Strings[20057]="<米师好奇地看着你。>"
D.Strings[20058]="我知道一条穿越不息山的秘密小径。行程会增加三天，但沿途上有一条十分澄澈清凉的瀑布。绝对不虚此行。"
D.Strings[20059]="在远足之前喝上一杯咖啡会交好运。远足之后喝就是厄运了。"
D.Strings[20060]="兔子脚和八铜钱为谁运气更好而争论不休。那些愚蠢的土地精竟然不记得，没什么能比在口袋里找到棉绒更走运了。"
D.Strings[20061]="一只干净的牦牛就是幸运的牦牛。一只脏兮兮的牦牛等同于雪人攻击。"
D.Strings[20062]="好运就像是土地精美女——世间罕有，但却值得你费尽心机去找寻。"
D.Strings[20063]="当你数到3时，就一定要继续数到5。不要在数到4时停下来。厄运总是会降在那些数到4的人身上。"
D.Strings[20064]="土地精熟悉所有山路。但总有一些土地精比其他人更擅长认路。"
D.Strings[20065]="多数厄运都是由大规模的猢狲劫掠带来的。使旅途变得艰难。"
D.Strings[20066]="你知道吗，我认为雪人比大多数人更崇尚好咔啡。而且自从你把她带下山后，她还没吃过一个土地精！"
D.Strings[20067]="我不知道……把这个雪人带到这里来还是让我有一种不祥的预感……$B$B有时候我发现她在……盯着我看。"
D.Strings[20068]="嗨！要叫醒这家伙还真不容易！我对他又敲又打，又吼又叫，用绳子拉，用身体压，什么法子都试过了，全都没用！$B$B好吧，我得好好想点别的主意。"
D.Strings[20069]="要我说，“先行动，后思考”才是正确的行事方法。行动可以带来灵感。但光凭思考，什么事都做不了。$B$B这就是火金之道。"
D.Strings[20070]="是的。我从会喝啤酒开始就在酿造啤酒了。$b$b这里的人说我在浪费时间，我可以去村子里买那种大桶的啤酒。我不那么认为。酿造自己的啤酒总是别有一番趣味。"
D.Strings[20071]="噢，当然不是了。那只是我酿啤酒的方法。$b$b泥水，你看……里面总会有点小虫子，帮你发酵酒浆。有人会用真正的酵母，就是那种在人为控制的环境下，在正规酒厂里生长出来的东西，诸如此类的。而我喜欢用泥水。$b$b这更合适我。$b$b我就是不像你所说的那种“科班出身”的家伙。"
D.Strings[20072]="你好！还有，呃……向你致敬，我猜。$b$b不好意思，真不知道该说些什么，我这里通常很少有人来。$b$b当然了，除非是他们来我这里买酒的时候。"
D.Strings[20073]="守卫石犁村的意义或许比你所了解的还重要。$b$b如果螳螂妖拿下了石犁村，他们就能顺势夺下整个谷。越过这道墙后，就没有什么能够阻止他们彻底扫平整个潘达利亚的了。"
D.Strings[20074]="螳螂妖在发动进攻，而我们却毫无防备，真是惭愧。$b$b在一般情况下，我们是能够预测敌人行动的。我们原本预测螳螂妖的下一次大规模入侵应当发生在十年之后，因为他们总是每百年入侵一次。$b$b当前的侵袭虽算不上“大规模”，但还是足以令普通乡村猝不及防。要不是我的影踪派弟子一直在城墙上警戒的话，石犁村恐怕早已陷落了。"
D.Strings[20075]="是的，守护石犁村的重任当前由我、守卫队长橡盾和我们派另外三名弟子担负着。正如之前我所说的，那三名影踪派弟子坚守在长城脚下，等待迎接下一波攻势。这是我们的责任——保护潘达利亚免遭普通老百姓所遗忘了的敌人蹂躏。$b$b虽然我们在石犁村的人数捉襟见肘，但我们还不打算向昆莱山请求增援……除非这里的形势变得更糟。说白了，打个比方，如果长城的弱点被攻破了。"
D.Strings[20076]="前几天，我在警戒塔上看到地底爆发出一股黑暗能量。它从西面而来，挤压着城墙，几乎把整个墙体撕裂开来。$b$b你现在还能看到它留下的痕迹。它把这些农夫的土地彻底毁了。$b$b后来，螳螂妖斥候也赶来了。我说不准他们到底是有备而来，还是只想趁火打劫。没准他们也是想逃离那个当初震裂大地的东西呢。"
D.Strings[20077]="小点心和小脆饼卖得最好。你要来点儿吗？"
D.Strings[20078]="谢谢你，勇敢的$c。"
D.Strings[20079]="欢迎，$c！务必要抽出时间欣赏景色啊！"
D.Strings[20080]="欢迎你，旅行者。看到这次比赛如此多元化，我很高兴。"
D.Strings[20081]="不必理会我身后的那只猢狲。他的戒律训练正在……进行中。"
D.Strings[20082]="我们从翡翠林出发，历尽跋涉才在今天抵达这里。我希望能在这次比赛中提升自己的技能。"
D.Strings[20083]="我对即将到来的挑战充满期待。"
D.Strings[20084]="试试你的力量！"
D.Strings[20085]="哈？你是谁？快走开。摔跤手要跟教头洛洛多练一会儿！"
D.Strings[20086]="嗯呼嗯呼！"
D.Strings[20087]="肯肯经历了艰苦的修行，现在已是超级强壮的武僧了。"
D.Strings[20088]="我对这臭味儿感到很抱歉。聪明的阿西约是条臭鱼。"
D.Strings[20089]="闻起来，你似乎马上就要输了。"
D.Strings[20090]="我的队伍将粉碎你。"
D.Strings[20091]="你知道我是谁吗？你知道我是谁吗？！"
D.Strings[20092]="啊！别跟我说话！坦住！坦住！把他的注意力吸引过去，你这蠢货！"
D.Strings[20093]="你身上有股战利品的气味。"
D.Strings[20094]="我一直梦想来到这里。就是这地方！我将在今天赢得比赛！"
D.Strings[20095]="看到这把棘杖了吗？这是我家世代相传的神兵，到目前为止已赢过数百场比赛。$b$b你能感受到其中的力量吗？在这儿，它更是前所未有的强大。"
D.Strings[20096]="你来了？这是不是意味着我们终于有机会同场竞争大赛冠军了？"
D.Strings[20097]="我很期待我们的对决。"
D.Strings[20098]="有关雪怒挑战赛的消息都传到我在翡翠林的老家那儿去了。我可无法拒绝这样的邀请。"
D.Strings[20099]="你长着一张英雄脸。天知道你是不是真那么坚毅。"
D.Strings[20100]="蠢蛋以为自己能抵挡住轰轰大狂欢？"
D.Strings[20101]="布姆布姆大师这儿有超级强大的火器。"
D.Strings[20102]="力量有多种形态。它对某些人是武器，对另一些人则是负担。而对我自己而言，它是生存之道。"
D.Strings[20103]="雪怒教导我们，力量是一种需要通过不断练习才能驾驭的工具。"
D.Strings[20104]="雪怒每隔几天就会举办一场力量大赛。只有全潘达利亚最强大最勇敢的挑战者才敢前去比试。"
D.Strings[20105]="小心雪怒的幼崽。别看他们个子小，它们可以靠纯粹的力量弥补这一弱点。"
D.Strings[20106]="相传，雪怒已经有几百年没有在他自己举行的比赛中大显身手了。$b$b他说是这是为了让我们都能有比试的机会。可我觉得，那只是因为他老了。或者……至少是……对于他那样的……存在……来说，已经老了。"
D.Strings[20107]="你们管那叫做强壮的臂膀？还没有我瘀伤里的肌肉多呢。"
D.Strings[20108]="你有猛虎的眼睛吗？"
D.Strings[20109]="什么，一个$c？也要加入比赛？这下变得更有趣了。"
D.Strings[20110]="嗯。一位$c可是颇具看点啊，但让我们看看你将如何对抗摔跤手或布姆布姆大师吧。"
D.Strings[20111]="真是个比赛的好日子啊，你觉得呢？"
D.Strings[20112]="我把钱押在了其中一个小毛孩身上，他们都是从四风谷来的。$b$b听说他们曾受训于翡翠林的禅院。"
D.Strings[20113]="我有一次看见风裘大师被十来个魔古族围攻，结果那些魔古族连一下都没能打中他。"
D.Strings[20114]="我听说摔跤手从不摘下面具。我很好奇，要是他的鼻子发痒，该怎么解决呢。"
D.Strings[20115]="无论如何，陌生人，你千万不要向我的丈夫打听他的鸡蛋面秘方。否则那将会成为你经历过的最冗长的一次谈话。"
D.Strings[20116]="你需要什么？我这里有最烈的老酒。你敢试试吗？"
D.Strings[20117]="我要感谢你。"
D.Strings[20118]="我曾在不息山上捡到过一根大绿鸟的羽毛。在不息山上可没有绿鸟啊。这真是个幸运符。"
D.Strings[20119]="发现一枚铜币，把它拾起来，一整天我都会交好运。"
D.Strings[20120]="今晚留在这儿，选购我的商品，好运定会伴你左右。"
D.Strings[20121]="*嗝*"
D.Strings[20122]="白虎寺比武大赛第一条规则：我们从不提白虎寺比武大赛。"
D.Strings[20123]="我没什么可教你的，$c。"
D.Strings[20124]="这片土地必须准备好迎接我们的舰队。$b$b无需任何理由！"
D.Strings[20125]="别太放松了，伙计。$b$b将军说，这些房子只是临时的。"
D.Strings[20126]="责法者说得没错……他们已经疯了！"
D.Strings[20127]="你……你不是他们一伙的吧，是吗？你得帮帮我！"
D.Strings[20128]="没希望了……我们的同胞已经失去了理智！"
D.Strings[20129]="你做好接受试炼的准备了吗？"
D.Strings[20130]="开启基础伤害（青铜）试炼"
D.Strings[20131]="艺术家嘛，废寝忘食是常有的事。"
D.Strings[20132]="你好。我是管理者彭启。我们以前见过面吗？我的记性不太好。"
D.Strings[20133]="我是彭启。我打扫地面，还照看小猫。他们说我曾经是位勇士。那一定很棒吧。"
D.Strings[20134]="我……我觉得我是在找寻什么东西。但又记不起来在找什么。"
D.Strings[20135]="我喜欢清扫小径上的落叶。过多的落叶会引来林精。寺庙武僧不喜欢林精。"
D.Strings[20136]="我们必须立刻阻止黑暗萨满！"
D.Strings[20137]="是加尔鲁什派你来的吗？"
D.Strings[20138]="我只是一块石头。这里没什么好看的。"
D.Strings[20139]="我们奉行服务至上的理念。我可没功夫闲聊，也没时间接受低地人的挑战。"
D.Strings[20140]="你看上去似乎身经百战。告诉我，你是为自己而战，还是为别人？"
D.Strings[20141]="我们是长城的守护者，是黑暗的监督者，是暗影的大师。我们深知潜藏在潘达利亚最深处的邪魔。我们……就是影踪派。"
D.Strings[20142]="你去过翡翠林吗？去过四风谷吗？去过昆莱的山脚下吗？$b$b告诉我，那里的人们享受和平的生活吗？他们是否仍然不知道，换取那和平所付出的代价？那是用多少影踪派弟子的鲜血换来的啊！$b$b我想他们还是不知道的好。就让他们浑然不觉地享受和平吧，这样他们才能无忧无虑地过好每一天。"
D.Strings[20143]="对于潘达利亚的每次不幸和灾难，总有一个完美的解决方案。我觉得这一点适用于所有的问题。"
D.Strings[20144]="谁能想到这些墙壁后面隐藏着那么多的知识。从这里的大量知识和你在旅途中的所见所闻之中，我相信我可以拼凑出一些有关我们被遗忘的历史的一些传说。$b$b你想要听哪一段？"
D.Strings[20145]="我听别人说……你需要乘风筝到长城上去？"
D.Strings[20146]="快跑吧，否则就迟了！"
D.Strings[20147]="玩火者，必自焚。"
D.Strings[20148]="要想成为影踪派的一员，$G他:她;就必须全心全意地投入影踪派的事业。"
D.Strings[20149]="影踪派虽然人数稀少，但我们能用强大的力量来弥补这一点。"
D.Strings[20150]="西边，螳螂妖蠢蠢欲动。$B$B西北边，魔古族正在阴谋作乱。$B$B北边，野牛人步步紧逼。$B$B我们有太多事情要做了，时间紧迫。"
D.Strings[20151]="每一个影踪派战士都能叫出彼此的名字。我们一同训练，并肩作战，同生共死。$B$B当你能做到这一点时，或许就做好了加入我们的准备。"
D.Strings[20152]="愿道路指引你的方向，旅行者。$b$b是什么风把你吹来了？"
D.Strings[20153]="幸运符？是指能带来好运和财富的人、地方或物品。$b$b幸运符是土地精给予最高的赞美之词。$b$b通常，幸运符本身拥有独特的气息。土地精灵敏的嗅觉可以通过幸运符的气味找到好运。"
D.Strings[20154]="武僧"
D.Strings[20155]="哦，艾莎？我想我看到她在湖边训练其他熊猫人，就在暴风要塞的西北方向。"
D.Strings[20156]="这座城市和我的家乡完全不同……\n\n啊，朋友，我能帮你什么忙吗？"
D.Strings[20157]="这片土地上有太多陌生又新奇的东西了。虽然和我的家乡非常不同，可给我留下了深刻的印象。"
D.Strings[20158]="打！！！"
D.Strings[20159]="噢，千杯不醉刘伶？他大部分时间都在铁炉堡大门北边的石火旅店里跟人拼酒。"
D.Strings[20160]="啊，你是武僧吧？你可以在石火旅店找到你的熊猫人朋友。"
D.Strings[20161]="兰风就在神殿花园的湖上冥想。我听说她非常擅长泡茶。"
D.Strings[20162]="老肖正在远行者广场练武呢。"
D.Strings[20163]="武魂潘劲正在俯瞰贸易阶梯的战士平台上和战士们一起训练呢。"
D.Strings[20164]="你知道比海盗更坏的是什么吗？猢狲海盗！它们袭击了我们的海岸，把鲜鱼、船只和美酒全都偷走了。没有人能偷走我们的酒……没有人。"
D.Strings[20165]="是什么风把你吹到这儿来的，$r？"
D.Strings[20166]="我们是守护者——既稳若磐石又心如止水。$b$b我们移动时，没有什么东西能阻止我们。我们站定时，没有什么东西能动摇我们。"
D.Strings[20167]="有些人认为牦牛是低等动物，只配用来放牧和做一些低贱的劳动。很少有人能看到他们的内在美，那才是这些——玄牛的子嗣——真正拥有的东西。"
D.Strings[20168]="别动！$B$B哈！我就爱说这个。"
D.Strings[20169]="今天这里很安静，真好。"
D.Strings[20170]="这条路通往昆莱山。祝那些沿着它去土地精商店购物的人好运。"
D.Strings[20171]="螳螂妖生来脑子就缺根筋，却极度渴望战争。参与到集群战争中不仅仅是一种文化上的进阶仪式——还是身体成熟的催化剂。$B$B只有那些从战场上归来的勇士，才能从聚生虫成长为有完整自主意识的个体公民。"
D.Strings[20172]="我很高兴你能来这，$n！今晚是酿月祭，而我最拿手的昆莱劲酒所需的原料都还没有运到。我派了助手出去收集它们，可一个都没回来。你能去帮我查查他们怎么了吗？"
D.Strings[20173]="在酿月祭的夜晚举行仪式，就可以在墨鳃潭见到水灵。过去这些年，我们都会向水灵敬献贡品，以获取一瓶纯净之水用于酿造昆莱劲酒。我派助手塔蒂去湖那儿了，可她还没有回来。你可以去北方查查她出什么事了吗，$n？"
D.Strings[20174]="$n！酒仙布夫派我从水灵这取一小瓶纯净水，但是波普吃了我们的贡品。现在，我没有办法说服他们给我一瓶，而且他们看上去并不十分友好。你认为你能为我说服他们吗？"
D.Strings[20175]="我派助手琪舞去贮粮塔取回一袋粮食，可她还没有回来。你可以去帮我查查她怎么了吗？你可以在小镇的西侧找到贮粮塔。"
D.Strings[20176]="欢迎来到寇塔峰。非常有名的寇塔咔啡的产地。幸运符懂得品味异域的美酒。"
D.Strings[20177]="欢迎来到我们最最卑微的营地。"
D.Strings[20178]="你的幸运符是什么？"
D.Strings[20179]="你可以通过支付金钱来更改你的主要专精。\n\n更改主要专精所需金额会随次数的增加而提高。"
D.Strings[20180]="你可以通过支付金钱来遗忘你的当前天赋，以选择新的天赋。\n\n遗忘天赋所需金额会随次数的增加而提高。"
D.Strings[20181]="你可以通过支付金钱来清空你的当前雕文，以选择新的雕文。\n\n清空雕文所需金额会随次数的增加而提高。"
D.Strings[20182]="我还有个问题。"
D.Strings[20183]="你准备好了吗？"
D.Strings[20184]="我见识过许多场战斗，医治了许多盟友，净化了许多灵魂，在我的指挥下许多敌人都死了。\n\n你可能觉得躲在城墙下会很安全，但请别弄错了，战争会像瘟疫一样席卷大地，只有很少一部分幸运的人能活下来，讲述这悲惨的往事。"
D.Strings[20185]="好无聊啊！我们去追捕些坏人吧。"
D.Strings[20186]="我早已按耐不住了！"
D.Strings[20187]="你没看见我正在刻苦训练吗？"
D.Strings[20188]="只要你一句话，我就会来帮你。"
D.Strings[20189]="很少有人能够在严寒下存活。"
D.Strings[20190]="你听说过暗影之舞吗？这是在战斗中上演的舞蹈。$B$B它是死亡之舞。"
D.Strings[20191]="有些人的舞蹈充满激情并热衷于此，比如非离。$B$B而有些人却不喜欢，除非被激怒，比如雅丽亚。"
D.Strings[20192]="暗影之舞的秘密在于掌控力。$B$B精确。$B$B敏捷。$B$B优雅。$B$B动作不能多一步，也不能缺一步。"
D.Strings[20193]="每一击都应传达你的最终意图。"
D.Strings[20194]="我通过冥想寻求智慧。"
D.Strings[20195]="只有通过内在的平衡，我们才能让自己内心平静下来。"
D.Strings[20196]="内心平静下来，我们就不会发怒、憎恨、怀疑和恐惧。"
D.Strings[20197]="我们最大的敌人就是自己。"
D.Strings[20198]="鱼竿仅仅只是辅助工具！真正的渔夫用自己的手捕鱼。"
D.Strings[20199]="我曾经抓到过一条鱼，大小有你三个祖先加起来这么大。虽然最后它逃走了，但是逮到那条鱼的喜悦感是任何东西都无法比拟的。"
D.Strings[20200]="你以前惹急过鲨鱼，让它跳出水来在陆地上追你吗？"
D.Strings[20201]="钓最大的鱼要用的最好鱼饵？把结婚戒指挂到你的鱼钩上。"
D.Strings[20202]="没人知道环礁湖底有些什么，除了那些去过下面的人们。还有那些和去过下面交流过的人。"
D.Strings[20203]="你尝过黄油海怪腿吗？真是世间美味。"
D.Strings[20204]="<他睡得很熟。>"
D.Strings[20205]="你好，朋友。你要喝些什么？"
D.Strings[20206]="最近有没喝上什么好酒？"
D.Strings[20207]="我想你可以留下来。"
D.Strings[20208]="你一定要这样喋喋不休吗？"
D.Strings[20209]="什么爆发？我一向如此。"
D.Strings[20210]="你一定要待在这吗？"
D.Strings[20211]="就把你的钱留在箱子里吧。"
D.Strings[20212]="噢，就只有你。"
D.Strings[20213]="我敢说你甚至不会买任何一件东西。就像其他人一样。"
D.Strings[20214]="我就不该开这家旅店。这里真是太压抑了。"
D.Strings[20215]="你是指除了在那边的懒汉大丹以外的其他人吗？当然！$b$b在艾薇去北方捕猎，我和她共处了一段时间。真是个乖巧可人的姑娘。$b$b当然，谁又能忘掉风暴烈酒大妈呢？"
D.Strings[20216]="和我一同飞翔吧，唤醒者，我要让你见识下掠风者的风采。"
D.Strings[20217]="你以为自己能在一场宠物大战里打败我？走上前来，试试身手吧！"
D.Strings[20218]="艾莎？我不知道该和她说些什么。也许我应该说“你长得很迷人”，但她会不会觉得我这样很怪？或许我可以告诉她我很钦慕她那从容不迫的姿态 ——但我又怕她觉得我这个人缺乏个性！"
D.Strings[20219]="是琥珀在我沉睡时让我继续存活，不过我能感觉到它的力量随着时间逐渐消逝。$B$B如果你刚才试图唤醒我时没有成功，我恐怕将永远无法苏醒。"
D.Strings[20220]="里基屯村欢迎你，外乡人。"
D.Strings[20221]="嗯？怎么回事？"
D.Strings[20222]="嗯……如果我将一些淡酒和烈酒混合……\n\n哦，我的天。瞧瞧这玩意儿！"
D.Strings[20223]="有兴趣租个风筝吗？"
D.Strings[20224]="哦，没问题！$b$b农夫老方说，如果你想要，你可以使用一只他精美的风筝。显然他喜欢上你了。"
D.Strings[20225]="放眼整片废土，凯帕圣树正在凋零。$B$B我恐怕……煞……就是这一切的罪魁祸首。"
D.Strings[20226]="远在西南方向，存活着一棵健康的凯帕圣树，但就在此时，女皇的奴隶正在试图毁灭它。"
D.Strings[20227]="如果我们放任凯帕圣树灭绝，这将是巨大的损失。$B$B琥珀即是生命。"
D.Strings[20228]="有兴趣去抓一些稀有宠物么？"
D.Strings[20229]="你看起来像是对稀有宠物感兴趣的人吧？"
D.Strings[20230]="你的死期到了。"
D.Strings[20231]="为了生存，你必须战斗。"
D.Strings[20232]="只有弱者才希望和平！"
D.Strings[20233]="我知道的唯一办法是战斗。"
D.Strings[20234]="我认为我们要少说话多战斗。"
D.Strings[20235]="太迟了！雷电之王将会崛起，从你手上夺取这片土地。"
D.Strings[20236]="你想成为“闷水壶”的船员？那你恐怕得像其他人那样，从头做起。"
D.Strings[20237]="你不介意吧？我们打算在这里拍张照片。"
D.Strings[20238]="我等不及要把这张照片寄给我家乡的女朋友了。她肯定会抓狂的！"
D.Strings[20239]="让我们瞧瞧这里……$B$B“找到合适的光圈值。光圈值等于焦距除以‘有效光圈孔径’。”$B$B这可真让我头疼。"
D.Strings[20240]="幸亏我们上一季发了笔小财，我才能邮购到这台新式相机！"
D.Strings[20241]="我现在正在潜心提高自己的摄影技术。"
D.Strings[20242]="别理外面那两个白痴——他们患上“鲨鱼狂热综合症”了。$B$B我敢打赌，他们对那照片的新鲜劲持续不了几个月。"
D.Strings[20243]="这简直酷毙了！"
D.Strings[20244]="再等一分钟鲨鱼就给你用，还没轮到你呢！"
D.Strings[20245]="你似乎能帮我们赚点钱。$B$B来破军比武场转转怎么样，伙计？"
D.Strings[20246]="那么，陌生人，你是狂野疯狂如猢狲呢？$b$b还是安静深沉如锦鱼人？"
D.Strings[20247]="你是来自长城的另一边吗？"
D.Strings[20248]="你是从哪来的？"
D.Strings[20249]="哇哦，你看起来……嗯……那个……跟我想的不太一样。你还有同类吗？"
D.Strings[20250]="你衣服的颜色真有趣啊。是你自己做的吗？"
D.Strings[20251]="你还有同类吗？"
D.Strings[20252]="噢，你好啊陌生人。你看上去像是个经历丰富的家伙。"
D.Strings[20253]="你下巴的轮廓真迷人。衣着又如此鲜艳。你是打哪儿来的？"
D.Strings[20254]="哈！你要对剑术大师“赤烟”腾武说点儿什么？"
D.Strings[20255]="我们赶快吧？"
D.Strings[20256]="这是一个狩猎的好日子。"
D.Strings[20257]="你好啊，钓友！你来这里多久了？我和我的搭档“大钩”山南海北地到处寻找大鱼！$b$b我们偶然来到这里，当地人十分友好，又是给补给品，又是好酒好菜地招待，所以我们打算留下来啦！"
D.Strings[20258]="我听闻了你旅行的消息。你乘变幻之风而来。"
D.Strings[20259]="我很好奇，在你的家乡，有和平可言吗？"
D.Strings[20260]="你觉得我们的土地怎么样？你学到什么了吗？"
D.Strings[20261]="打从黑暗时期开始，风裘拳击的武艺就在我的家族里代代相传。$b$b据说这套拳法最早是在魔古帝国的黑暗统治时代被发明的，在熊猫人争取自由的伟业中发挥了不小的作用。"
D.Strings[20262]="你的到来，犹如暴风雨来临前的一阵疾风。"
D.Strings[20263]="斜风细雨，总好过血风肉雨……明白？我只是开个玩笑。"
D.Strings[20264]="科沃克似乎在冬眠中经受住了岁月的考验。"
D.Strings[20265]="我的研究必须继续下去。"
D.Strings[20266]="不，不，不！我不能停下来。我的变异体必须活下去！"
D.Strings[20267]="在山谷小路上行走的感觉很是诡异。这里的地面也太平了。还那么热。$b$b我想念昆莱。"
D.Strings[20268]="最后一种成分，是我们家族世代相传的秘密，来自于卡桑琅丛林。我几天前派了助手布扎齐去寻找这种成分，收到的消息是他昨天晚上到达了迷雾酒肆。你能前往远古之路去看看是什么让他耽搁了吗？他最好不要在酒馆里睡过了头！"
D.Strings[20269]="啊，很好！你找到远征队了。要是没有点旅行天赋，很容易在丛林里迷失方向。$b$b那些魔古族没完没了地妨碍我狩猎。"
D.Strings[20270]="猎手狩猎。艺术家……则钻研艺术。$b$b我来这里是为了用艺术来表现狩猎的凶残。$b$b我们身处陌生的土地，而且在这世界上也没几个人熟悉我们要猎杀的这种奇怪生物。$b$b通过我的艺术，我能证明你的成功，以及奈辛瓦里远征队的成功。"
D.Strings[20271]="欢迎光临北风酒馆。"
D.Strings[20272]="你好啊朋友！想找个房间过夜吗？"
D.Strings[20273]="有兴趣抓只鲨鱼吗？"
D.Strings[20274]="想在战斗中停下来喘口气？那你可来对地方，找对人了。"
D.Strings[20275]="砮皂……我们必须得救他！"
D.Strings[20276]="你就当我疯了吧，我简直爱死这温暖的好天气了！我总觉得自己在苔原时像个流浪儿，可我觉得这新气候真是帮了我大忙！"
D.Strings[20277]="呃，北上变得越发困难了。尽管天灾的麻烦已经得到解决，我们还得不断迁移和觅食。我下定决心，是时候出去寻找新渔场了！$b$b在海上漂流了近一个月之后，我来到了这里。幸好我带了几箱腌鲱鱼，否则途中就要饿肚子了！"
D.Strings[20278]="<狗狗疑惑地看着你。>"
D.Strings[20279]="影踪派永远保持警惕，不断监视着很久以前封入地下的黑暗煞魔的能量。$B$B不幸的是，煞魔逃出了他们的囚牢，现在我们必须再次击败他们。"
D.Strings[20280]="金莲教肩负着守卫锦绣谷的重任。$B$B如果你想帮助我们，就去打败那些目前占据着锦绣谷的敌人吧。$B$B你也可以去残阳关卫戍营的训练场找安济·秋光，获取下一步的任务。"
D.Strings[20281]="共有四位至尊天神统御着这片土地。$B$B东方生命之神，青龙玉珑。$B$B南方希望之神，朱鹤赤精。$B$B北方力量之神，白虎雪怒。$B$B西方巍峨之神，玄牛砮皂。$B$B近来，随着邪煞的出现，这四位天神的寺院都陷入了混乱。他们需要我们的帮助，$r。"
D.Strings[20282]="告诉我，$r，你对钓鱼心怀向往吗？$B$B如果答案是肯定的，那你应该去卡桑琅丛林找垂钓翁。"
D.Strings[20283]="我是阡陌客的成员，这个组织是由潘达利亚的辛勤农夫组成的。如果你想对我们有更多的了解，可以到四风谷的半山来找我们。"
D.Strings[20284]="从古王国的黑暗统治时期开始，我们熊猫人就开始钻研酿酒这门神秘艺术，来振作精神，强身健体。$B$B就在我们说话间，酒仙们还在世界各地奔走，寻觅稀有强劲的原料，以制出绝品佳酿。$B$B那些有幸找到这些隐秘大师，并向他们提供帮助的人，也许能获得风味十足的物品。至少能饱饮美酒！"
D.Strings[20285]="雾纱栈道在郭雅夫人的保护之下。"
D.Strings[20286]="在迷雾酒肆里，你会大有收获。"
D.Strings[20287]="迷雾酒肆只为话少的宾客服务。"
D.Strings[20288]="欢迎来到闻道之座。这里是蕴藏着潘达利亚古代知识与智慧的伟大宝库。"
D.Strings[20289]="还有那么多精彩的故事等着我们去探寻。那么多历史。难道不使人着迷吗？"
D.Strings[20290]="<米师满怀期待地望着你。>"
D.Strings[20291]="如果你往西北走，可以去土地精集市逛逛。那有许多好看的饰品和幸运符。光顾那里的人总能交上好运。"
D.Strings[20292]="能看到禅院外面的世界，真好。"
D.Strings[20293]="只给迪嘭迪嘭最好的酒。"
D.Strings[20294]="你好啊，朋友。饿了吗？"
D.Strings[20295]="我被派去破坏希克提克桥的重建工作，可你在敌阵中左突右杀，像个真正的$c。你有机会消灭他们的领袖！"
D.Strings[20296]="我是郭雅夫人的“救援专家”。是她的意愿引导着这条道路上来来往往的人流。$b$b我的职责是确保某些贪得无厌的人不要滥用她的热情款待。"
D.Strings[20297]="昆莱劲酒完成了，$n！准备好见识一下潘达利亚最好的酒了吗？我要警告你，喝过这种酒之后，可能会产生踢东西的冲动。这是件好事，因为有太多的野牛人需要被踢飞了！"
D.Strings[20298]="我要治疗和复活我的战斗宠物。"
D.Strings[20299]="你看我的宠物如何？"
D.Strings[20300]="嗨，陌生人……可不可以借些钱给口渴的旅行者？"
D.Strings[20301]="给鱼买杯酒？"
D.Strings[20302]="今天什么风把你给吹来了，我的$G兄弟:姐妹;？"
D.Strings[20303]="水流预示着今天会有好运气，$n。"
D.Strings[20304]="嗨，哥们，可不可以资助一下可怜的锦鱼？"
D.Strings[20305]="我渴坏了，哥们。"
D.Strings[20306]="锦鱼的朋友，来和我坐一会儿。"
D.Strings[20307]="嗨，朋友，介意和我一起喝一杯吗？"
D.Strings[20308]="嗨，我的好朋友，$n。我今天感觉清醒多了。或许是因为我少吃了一些酱油。"
D.Strings[20309]="你知道的，我决定把你当做朋友了。这让我想到，或许我可以再交一些朋友。"
D.Strings[20310]="我们跟随着风的指引四处游荡，好心的$r。你愿意倾听一会儿吗？"
D.Strings[20311]="在旅途中，我们唱过很多的歌曲，但还有很多歌曲没有唱。"
D.Strings[20312]="我和我们的人民正在研究附近的河流和水塘。我们以前从来没有见过如此具有活力的水。"
D.Strings[20313]="我们认为正是山谷中的独特水质造就了这片繁荣的区域。"
D.Strings[20314]="这个水塘里的水……非常糟糕。"
D.Strings[20315]="不幸的是，我们的兄弟贾古自从家人去世之后就活得很消沉。"
D.Strings[20316]="贾古来自另外一个部落。他来自遥远的北方，很少提起自己为什么会来到这里。"
D.Strings[20317]="那边的那位兄弟只是借酒消愁，对世事不闻不问，从不辛苦工作。"
D.Strings[20318]="<当你抚摸这只大猫浓密的皮毛时，她只是冲着你动了动耳朵。>"
D.Strings[20319]="能与其他的部落幸存者重聚真是太幸运了。我根本没想到，还有别的同胞也被冲上了这片全新的土地。"
D.Strings[20320]="德兹科派我们来侦察这片地区。我们也许已经找到了莱莎幻像中出现的伟大治疗之力。"
D.Strings[20321]="当地人坚称，我们要找的伟大治愈之水不过是……风暴烈酒而已。我们得调查下这种说法的真实性。"
D.Strings[20322]="这巨魔抱怨食物不好吃，但他吃的比谁都多。"
D.Strings[20323]="你看到西面的长城了吗？我在想长城的外面有什么呢？"
D.Strings[20324]="这里所有的东西……都那么……那么……不同！"
D.Strings[20325]="海军上将泰勒派我们来此寻找年轻的王子。你能想到他们这里也酿啤酒吗？"
D.Strings[20326]="我们正在努力寻找安度因王子。顺道路过，来吃些干粮酒水。"
D.Strings[20327]="他们说潘达利亚有五千多种酒。我在尝遍这些酒之前是不会离开的！"
D.Strings[20328]="过来和我们喝一杯，$r！"
D.Strings[20329]="我就是喜欢听柯谈论他那些美味的食谱。我从不知道竟然有那么多种烤肉的方法。"
D.Strings[20330]="你有没有尝过柯的厨艺？我好像怎么都吃不够。"
D.Strings[20331]="他经常告诉我说他喜欢我的口音，我就一直问他，什么口音？"
D.Strings[20332]="嘿，$c，很高兴在这见到你！你也是被派去寻找小王子的？"
D.Strings[20333]="这里的本地人过着美好的田园生活。这不禁令我怀疑，自己是不是该放下魔杖，拿起锄头。"
D.Strings[20334]="祝你好运，$r！我和我的兄弟大老远赶来就是为了给人带来幸运符的。"
D.Strings[20335]="拜托，既然我们是村里的客人，就守规矩些。要是我们大开杀戒，主人们恐怕不会善罢甘休。"
D.Strings[20336]="我们不要让杀戮席卷这片净土，$G兄弟:姐妹;。"
D.Strings[20337]="我们一路搜寻，跨越了千山万水，可却偏巧在这里狭路相逢。看来不管走到哪里，我们的冲突都是难以避免的啊。"
D.Strings[20338]="我一直在观察你，$r。"
D.Strings[20339]="嗨，丑八怪，我恨不得立刻给你一拳……如果我觉得可以教训你！但是，你知道这里的人也会酿造啤酒吗？"
D.Strings[20340]="除了打得头破血流，不如用跳舞来解决……我们之间的分歧吧？"
D.Strings[20341]="嘿够了，这可不是打架的地方。不然谁也别想吃到这美食。"
D.Strings[20342]="音乐对人的心灵、身体和灵魂都有好处！"
D.Strings[20343]="附近地方的农夫把他们的大麦送到这里，我们磨成面粉并对谷物进行分类。$B$B有些谷物要做成食物，有些谷物拿去卖掉，但大部分都送到风暴烈酒酿造厂……你猜对了……酿啤酒！"
D.Strings[20344]="青龙！它……它碎掉了。"
D.Strings[20345]="我告诉过我的儿子，我告诉过迪恩，下雨时不要将牦牛带到牧场。然后他做了什么？他在雨天将牦牛带到牧场。$B$B现在我们的牦牛生病了，这并不奇怪！$B$B唉呀！我怎么会生出这样一个愚蠢的儿子？"
D.Strings[20346]="我的儿子吃的不多。看看他！骨瘦如柴！我要多给他吃点儿。"
D.Strings[20347]="为什么我的儿子就得是个矮子？我想要高大、强壮的儿子。$B$B在他小的时候，我就告诉他，不要在室内撑雨伞。我说，这样你会长不高！$B$B然后他做了什么？他总是打着雨伞玩！在房子里面！"
D.Strings[20348]="我的儿子迪恩说，妈妈做的饺子是全谷最好吃的！$B$B噢哈哈哈。真是我的好儿子。"
D.Strings[20349]="妈妈喜欢吃橙子，但在谷里很难找到橙子。$B$B我给我的儿子一些铜钱，让他去市集上买一些橘子。$B$B然后他做了什么？他买了一些豆子！$B$B我们又不是农民！我们是放养牦牛的牧民！我问你，我该怎么处理这些愚蠢的豆子？"
D.Strings[20350]="猢狲和锦鱼人总是在战斗，但从来没有像这样……"
D.Strings[20351]="我的儿子迪恩整天在牧场。他这么努力工作。妈妈很自豪。"
D.Strings[20352]="青龙……它现在想做什么？"
D.Strings[20353]="这是什么意思？潘达利亚的和平结束了吗？这是命中注定的吗？"
D.Strings[20354]="你来看妈妈吗？噢，坐一会儿！$B$B我告诉你，几天前，我听到一些流言。$B$B我听说吉娜·泥爪和她的父亲郝瀚·泥爪合不来！$B$B他想把她嫁给农夫老方，但她不愿意！她说她想经营她的市集。$B$B唉呀！现在的年轻姑娘们是怎么了？不想嫁给英俊的小伙子，不想成家吗？$B$B特别是老方……他这么抢手！人长得好看，又种出这么大棵的蔬菜。$B$B我的儿子怎么就没那么年轻英俊？！"
D.Strings[20355]="噢，我的儿子什么时候能遇见一位年轻漂亮的女子？他整天围着牦牛转！$B$B哪个女孩愿意嫁给臭烘烘的牦牛牧人啊？唉呀，妈妈真担心……"
D.Strings[20356]="啊，你好，$r！$B$B这是保留我们所有耕种历史和知识的地方。$B$B我们记录当地的天气，以及相应的收成，详细到谷里的每一粒种子和每一棵植物，甚至我们可能会不断种植的一堆种子。$B$B这些知识对我们而言是神圣的。即使有一天灾难会降临到这片土地上，我们也必须要保存这些种子。"
D.Strings[20357]="你好，旅行者。我在努力工作，打造我的下一个杰作！"
D.Strings[20358]="青龙雕像被毁坏了吗？怎么可能发生这样的事？"
D.Strings[20359]="难道你只喜欢看着鸟儿吗？我真想我也能飞。"
D.Strings[20360]="看看天空，$n！下雨了！对作物生长应该有好处吧？"
D.Strings[20361]="哇，看看这场暴风雨！嗯，作物喜欢喝水，对不对？"
D.Strings[20362]="“煞魔”是什么？它从哪里来的？"
D.Strings[20363]="你会帮助我们治愈土地吗？"
D.Strings[20364]="可怜的猢狲和锦鱼人！我们知道他们不喜欢对方，但走到今天这一步……"
D.Strings[20365]="所有锦鱼人和猢狲都在那次战斗中灭亡了吗？有幸存者吗？"
D.Strings[20366]="你会帮助我们对付煞魔吗？"
D.Strings[20367]="嗯？你说什么？"
D.Strings[20368]="古老的箱子布满灰尘……"
D.Strings[20369]="我和我的家人将新鲜的鱼从渔人码头带到镇上。你想买一些吗？"
D.Strings[20370]="从镇上到香里拉有很长一段路，但走路对精神有好处。这肯定有助于让小艾黎到户外活动。"
D.Strings[20371]="我不应该和陌生人说话。"
D.Strings[20372]="现在他们说，无论谁得到地图，都可以找到失去的宝藏……"
D.Strings[20373]="有一次，我看见一条非常大的鱼，你发誓它是鲨鱼。现在想起来了……"
D.Strings[20374]="你是渔夫？和他们无力的手臂和沉重的护甲吗？"
D.Strings[20375]="欢迎光临潘达利亚海岸！这里一切可能冲刷海岸的东西已经或者将冲刷上海岸。"
D.Strings[20376]="你用什么样的诱饵？我知道一个熊猫人会使用自己的手掌做饵来钓鱼。$b$b我们叫他搏鱼者。$b$b听说他退休了，境况越来越糟。"
D.Strings[20377]="可曾见过海怪？老金称自己从前捕到一条，但又放回去了，因为它“腥味太重”了。$b$b我们打赌，看他是否还能再次捕到。"
D.Strings[20378]="那么，那鱼长什么样，你又从哪里来？"
D.Strings[20379]="常年笼罩着这片海滩的迷雾散去了，这背后一定有什么原因。"
D.Strings[20380]="我认识一名武僧，他擅长使用斗鱼招式。招数虽然相当有限，但是他炖的鱼汤非常好吃。"
D.Strings[20381]="新来的吗？这就像我们告诉孩子们，没有手握大把的诱饵和撤退策略就不要下水。"
D.Strings[20382]="有个孩子发誓，有一天，他看到了在鲨鱼和章鱼之间的一个十字形物。$b$b我知道海洋中有很多奇怪的事情，但在我看来，都很无聊。"
D.Strings[20383]="你可能已经看到船撞上我们的海岸。你的船也有过那样的遭遇吗？$b$b迷雾常常给我们带来那样的“礼物”。"
D.Strings[20384]="是翔龙骑士派你来的吗？他们的翔龙不断偷取我们最好的渔获物。"
D.Strings[20385]="在这里捕鱼的时间长了，就见怪不怪了。我看到过长了胳膊和腿的海象。而且，那海象还会说话！"
D.Strings[20386]="你们那的大海是什么样的？"
D.Strings[20387]="我总对这里的锦鱼人感到奇怪。但他们知道如何捕鱼，而且技术比我们更高，所以我有什么资格去评判呢。"
D.Strings[20388]="噢，这太令人兴奋了！现实版的寻宝！"
D.Strings[20389]="我会尽力当个好学生。"
D.Strings[20390]="不知道我是怎么来到这的。但是……好运常常降临开明的人。"
D.Strings[20391]="我在努力学习如何治疗。问题在于，你得先受伤，才能被治疗。"
D.Strings[20392]="前几天，有人说我“过量治疗”了。真让人困惑。"
D.Strings[20393]="我在学习如何帮别人消除痛苦。很厉害吧？"
D.Strings[20394]="现在不能说话。必须……集中精神。"
D.Strings[20395]="我从来不知道，泡茶有多少讲究。"
D.Strings[20396]="可怜的小羊……到处乱走终于害了他。"
D.Strings[20397]="有个新来的，前几天跟我开了个玩笑。他说我应该闻得到他身上的“治疗迷雾”。治疗跟迷雾有什么关系啊。"
D.Strings[20398]="你的姿势错了。你完全站不稳脚跟。你的头脑太笨。$b$b当你已经学到准备去学的东西时，请返回这里。"
D.Strings[20399]="你的眼睛已经看不见面前的事物。毫无疑问，这是你平时不良的饮食习惯所造成的。"
D.Strings[20400]="你走起路来的步履犹如一头怀孕的牦牛。你还没有达到能在这里训练的要求。"
D.Strings[20401]="要想在水上奔跑，那么你必须跑得特别快。"
D.Strings[20402]="通过城墙，我们全都在长途跋涉中效力于莱文。我们用野牛人和螳螂妖的血来祭奠我们的刀刃！这些低估我们实力的魔古族，会由于他们的错误判断而致命。"
D.Strings[20403]="踏上恐惧废土，使我明白了探查地形与洞悉敌人行动的重要性。不论是为了取胜还是存活，先发制人总能事半功倍。"
D.Strings[20404]="对于身经百战的老兵来说，很难适应和平环境，但那是我们的职责。这些村民厌恨战争，除非别无选择，否则就不要把战火引到他们门前。"
D.Strings[20405]="有这么多人要去养活，可是从来没有足够的食物去喂饱他们！"
D.Strings[20406]="我的一位先祖参加了徒圣起义，他的尸体就躺在这墓地里。我愿意放弃我的自尊去接受和平，但是墓地里的鬼魂知道这个世界是没有和平可言的。"
D.Strings[20407]="<他对你露出了满脸的狰狞。>"
D.Strings[20408]="<他面无表情地注视着你。>"
D.Strings[20409]="我喜欢把自己看作此次行动的幕后智囊和台前花旦。安济的四肢发达。并且她也是个台前花旦。$B$B我们这里已经有很多台前花旦了。"
D.Strings[20410]="魔古族可能是一个强大的威胁，但跟我和我的士兵所面对的恐惧废土的恐惧比起来，它根本不能恫吓住我们。我们一定可以在山谷中挖出一个洞来。"
D.Strings[20411]="我们跟你们一样对这个山谷一无所知。当闸门一打开，我们就来了。失去了我们在昆莱的家园。想必在这里我们可重建它。"
D.Strings[20412]="这是整个潘达利亚最美丽的地方！聪明人在这里可以赚得盆满钵满！"
D.Strings[20413]="充满生机的村庄是谋生的绝佳去处！这里需要很多物资，所以能进行各种各样的贸易。我想我确实可以在这里过着无忧无虑的生活！"
D.Strings[20414]="早在很久之前，我就听说这是个非常宁静、美丽的山谷，那个时候没有人被允许进入。现在我们置身其中，发现到处都是形形色色的野兽，不是想打碎我们的脑袋就是想咬掉我们的脚。$B$B所以这个传说是个谎言，或者说我们只是令人憎恶的不速之客？我还是摒弃后一种想法吧，因为那样想的话就太自欺欺人了。"
D.Strings[20415]="鲁克对朋友很好。"
D.Strings[20416]="修建在生存之环中的反射可以使受训者在城墙外得以生存。在那里，威胁更不容易被放任。"
D.Strings[20417]="多美的生物啊，你不觉得吗？别被它的小身材给骗了。恐虫在幼年时期也有着致命的杀伤力。$b$b在我的发现之前，恐虫只被当做武器，几乎无人关注它们的智力。我们竭力控制它们，直到我突然意识到，我们对它们的了解还远远不够。$b$b通过与这个物种建立起纽带，我们不再需要对其强行施加控制，而是形成一种伙伴关系。$b$b科沃克将是我的下一个实验对象。"
D.Strings[20418]="守卫土地精可不是我梦想的职业，不过他们给的报酬倒是不错。此外在山路上你会遇见很多奇怪的事情。"
D.Strings[20419]="你来自低地？我们没怎么见过来自低地的人会走这条路。"
D.Strings[20420]="什么风把你吹到山上来了？"
D.Strings[20421]="土地精经常有影踪派守护在其左右。我猜在蟠龙脊上一定有危险。"
D.Strings[20422]="你听说过煞魔吗？在风里，我们经常听到它的声音。不妙。大事不妙。"
D.Strings[20423]="高山猢狲正在肆虐。在这条路上行走要多加小心。$b$b迟早他们会发现影踪派不在这里，并会向我们追赶而来。"
D.Strings[20424]="有一次，在土地精集市我看到了一个奇怪的生物。看上去像一只蹲着的锦鱼人，但是他脾气很坏，口中叫嚷着“呒啊噶呒啊呒啊噶呒噶呒噶”。$b$b我猜是某个土地精把他从海岸线那里带过来的。"
D.Strings[20425]="影踪派最近并没有走过这条路。这可不太好。$b$b我们猜想还有几年的时间，才会遇到螳螂妖再次蜂拥而至。"
D.Strings[20426]="你知道吗，我看见她了。$B$B玛祖。海之女神。$B$B我人生中最猛烈的风暴。我那时候年轻，而且缺乏经验。我从船上跌进海里。到处都是漆黑一片，我完蛋了。$B$B然后她出现在我面前，像夏天的午后一样清新。那样的美丽是你无法想象的，她的脖子上戴着贝壳，臀部挂着一串串的珍珠。她微笑着并且伸出纤细的手臂。$B$B然后我只记得，狗把我背在背上，并且船员拉我上了船。之前从未见过他，船员都说不知道他是从哪里冒出来的。但我知道他从哪里来。"
D.Strings[20427]="吱吱是你的朋友了。"
D.Strings[20428]="你是玉儿的哥们了。"
D.Strings[20429]="不知不觉之中，你和农夫老方已经成了挚友。他或许乐意帮助日歌农场。"
D.Strings[20430]="你和郝瀚是哥们了。"
D.Strings[20431]="你和老农山掌已经成了好友。"
D.Strings[20432]="欢迎，我年轻的朋友。"
D.Strings[20433]="我的$c朋友，是时候谈些其他事情了。比如螃蟹和海洋，海龟和树木……"
D.Strings[20434]="我的$r朋友，是时候谈些其他事情了。比如猢狲和土地精，还有我的肚子饿了……"
D.Strings[20435]="我的小朋友，是时候谈些其他事情了。比如魔古族和巨魔，或者锦鱼人的河流通行费……"
D.Strings[20436]="我的傻朋友，是时候谈些其他事情了。比如雪人和牦牛，或者随机的鲨鱼袭击事件……"
D.Strings[20437]="舒对我们而言非常重要。我们需要找到他，但是他各方面更趋向于小孩子，所以我们绝不能用我们的方法吓唬他。$B$B我会想想他可能待的地方，以及怎么样接近他最合适。耐心等待，我的朋友。"
D.Strings[20438]="对涓流要有耐心。他的行为举止也许像个孩子，实际上却是古老而强大的生灵。"
D.Strings[20439]="看起来你在水中没什么不妥的啊。继续这样干。"
D.Strings[20440]="全是关于那些君王蟹的事情。亲爱的，他们就是蓝色黄金。"
D.Strings[20441]="在闷水壶带我们偏离了原始的航向后，我们就在这里失事了。他以为能把我们当傻子耍。哈哈！$B$B说实话，我们很乐意看他尝试这么去做。我们每个人都不是“泛泛之辈”。"
D.Strings[20442]="这么说，你准备开始了？让我们看看你有什么能耐。"
D.Strings[20443]="参加酒仙场景战役的人可赢得勇气。要是你在与酒仙一同冒险时发现任何罕见物品，尽管将其收入囊中！"
D.Strings[20444]="潘达利亚地区最大的酿酒厂是四风谷的风暴烈酒酿造厂。如果你想冒险，可以从那里开始。$B$B酒仙实质上也是游荡者，并且他们经常四处闲逛，寻找稀有原料或调配新酒。$B$B这些酒仙通常会出现在独特的场景战役里。$B$B酒仙曲子在绿石村场景战役中抵御敌人。$B$B珀酒仙在盎迦猴岛场景战役中寻找热带配料。$B$B酒仙布夫在酿月祭场景战役中欢庆佳节，酒仙布兰琪在酝酿风暴场景战役中准备让人大吃一惊。"
D.Strings[20445]="<腾武打哈欠。>\n\n我正在等待……"
D.Strings[20446]="卡桑琅丛林东南部的渔人码头最适合垂钓了。欢迎大家来访垂钓！"
D.Strings[20447]="你问我你能从中得些什么好处，这么说是什么意思呢？那是个什么问题？$B$B难道从海里钓到大鱼还不够快乐吗？那么阳光照在你的脖子上，感觉怎么样呢？咸咸的海水飞洒到你的脸上，感觉怎么样呢？和朋友闲坐在一起，喝一杯冷啤感觉怎么样？$B$B这还不够吗？！？$B$B让我告诉你吧，$G渔夫:渔妇;的生活简直无与伦比！$B$B你可以从头学习提高钓鱼技能。获得足够的技能，你就可以购买功能强大的钓竿。$B$B倍受尊重的渔夫可以获得特殊的鱼类宠物和水黾坐骑，甚至还有自己专用的捕鱼木筏！"
D.Strings[20448]="你好，$r。$B$B我一眼就能看出你是位伟大的冒险家。$B$B在这片土地上，到处都是漆黑的地穴和广阔的宫殿，里面充满既可怕又强大的敌人。他们守着许多秘密，可是……高风险也意味着高收益。$B$B英雄中的佼佼者可以去试试身手，但千万要多加小心！你要跟时间赛跑，还要和其他英雄比拼技能。$B$B你愿意接受挑战吗？"
D.Strings[20449]="哦，我应该从哪里说起呢？！$B$B首先，农夫需要播种和收获庄稼。你出售的庄稼可以用于烧饭、拍卖出售、卖给其他买家，或者换购肉和鱼。我还听说，农夫可以种植一些稀有种子以获得特殊物品……甚至有可能是珍贵的宠物！$B$B接下来，还有整个半山供你探索！要想与当地人做朋友，最好的办法就是送他们礼物，而一旦你们成为朋友，他们就会给你一些不错的礼物作为回馈。$B$B田里一直有许多工作要做，多个人帮忙总是好的。"
D.Strings[20450]="嗯，阡陌客不会让你变得富有，而且也不会让你变强大以应付战事。$B$B不是这样的，农夫的生活略有不同。$B$B如果你坚持这样的生活，你会遇到一些非常有趣的人。你可以建立自己的农场、种植自己的庄稼，并且享受自己的劳动果实。$B$B所以，如果你感兴趣的话，就亲自去半山看看！"
D.Strings[20451]="云端翔龙骑士团发誓保卫翡翠林。我们在翡翠林青龙寺正北面的百木园进行训练。"
D.Strings[20452]="在云端翔龙骑士团中获得晋升是一种莫大的荣耀。$B$B一旦证明了自己，你就能把翔龙当成飞行坐骑，任意驰骋。$B$B你还能学会骑乘云端翔龙的技能，可以骑乘潘达利亚的任何一条云端翔龙。"
D.Strings[20453]="一旦进入云端翔龙骑士团，你就可以利用翔龙坐骑开始一段旅程。$B$B你可以孵化一头幼小的翔龙，每天培训它，看着它长大成年。"
D.Strings[20454]="需要幸运女神的眷顾么，$r？人人都要借助好运来让自己心想事成！$B$B别急，我能帮你扭转颓势！"
D.Strings[20455]="白虎雪怒顶着寒冷的北风担任守卫工作。$B$B今天，雪怒试图通过列一系列比赛找到该地区最出色的勇士。$B$B如果你相信自己的能力，就北行至白虎寺，迎接挑战！"
D.Strings[20456]="保护这四座寺庙，你就会受到至尊天神的褒奖，得以购买功能强大的物品。$B$B此外，你还可以提供帮助，保护这片土地免受强敌的攻击。"
D.Strings[20457]="锦绣谷正处于危难当中，$r。$B$B加尔鲁什·地狱咆哮用一件来自上古邪神的黑暗神器——亚煞极之心污染了这座圣谷中的水流。而他的恶行所造成的后果……呃……你也已经看见了。$B$B现在，煞魔余孽已经威胁到了我们的生存。我们别无选择，必须战斗。"
D.Strings[20458]="当然。我们应该奖励那些冒死护谷的人。$B$B通过帮助保护锦绣谷，你不仅可以使边界安宁，而且还能获得我们浩如烟海的强大珍宝。"
D.Strings[20459]="要想赢得我们的尊重，有以下几种办法。$B$B我们现正在昆莱山的火树村应对邪煞的攻势。帮助我们，你就能在我们的门徒间占得一席之地。$B$B影踪禅院也遇到了麻烦。你或许能帮帮我们在那里的兄弟姐妹。$B$B怒之煞在北面的昆莱旷野上横行。将它击败，你就能在我们的成员当中树立威信。$B$B最后，一支影踪分遣队被派往螳螂高原追击恨之煞。他们或许也需要帮助。$B$B如果你希望赢得我们最高的敬意，你必须证明自己，与金莲教的关系要先达到崇敬。然后，再到螳螂高原的影踪卫戍营来找我的兄弟姐妹们谈谈。"
D.Strings[20460]="影踪派是一个古老的组织，它只接受和培训最为精干和最有价值的成员。$B$B如果你能设法证明自己的价值，就会有许多强大的物品供你所用。"
D.Strings[20461]="游学者走遍世界，发现了新的传说，也重新阐释了旧的故事。$B$B我们仔细研究了潘达利亚地区丰富的地理人文历史。$B$B如果你自己想听某些故事，就与闻道之座的游学者周卓交谈。闻道之座在锦绣谷魔古山宫殿入口上方。"
D.Strings[20462]="游学者将派你到潘达利亚的重要地区，以收回当地的文化神器。$B$B一旦找到属于一个系列的所有神器，你就可以听完整个故事的来龙去脉。$B$B找到所有文化神器，收集所有图书，变成一个游学者！$B$B如果你觉得有趣，就闻道之座的游学者周卓交谈。"
D.Strings[20463]="旅途本身就是馈赠，年轻人。在故事中寻找快乐，你就会得到无与伦比的财富。$B$B对了，还有件事。在游学者中地位升高的人还能获得特殊的礼物——驾云而行的能力。"
D.Strings[20464]="我刚刚从城墙那边回来。$B$B我在那边听说了一些关于卡拉克西螳螂妖的谣言。据说他们来自蟠龙脊之外，可能是从螳螂妖帝国分裂出来的螳螂妖长老议会。如今他们正公然违抗螳螂妖女皇的命令。$B$B我亲眼见识了这些螳螂妖的法力。$B$B如果这些谣言可信，我们就有可能找到一条途径联合这些……卡拉克西……并和他们共同阻止螳螂妖虫群。"
D.Strings[20465]="这对我来说是个难解之谜，$r。如果你想找到他们，你就太傻、太疯狂了！$B$B但是我认为遇见卡拉克西的唯一途径是冒险越过这座城墙，到达恐惧废土。"
D.Strings[20466]="我不知道，$r。$B$B我们对卡拉克西所知甚少。他们看起来非常冷酷无情，你去了恐怕也只能送死。$B$B话说回来，他们的文明非常博大精深。如果你处理得当的话，他们或许会赐予你强大的力量。$B$B要想知道最后的结果，就只有一个办法。"
D.Strings[20467]="我们正在围攻砮皂寺。$B$B我们知道你是谁，$n。我们需要你再帮一把。"
D.Strings[20468]="我们和螳螂妖、野牛人和魔古族作战。敌人从四面八方涌来。\n\n我来这儿是为了确保没有意外。"
D.Strings[20469]="干得好。$B$B没有你，我们就无法成功。"
D.Strings[20470]="我们有幸在大门打开后找到了这片山谷。我们寻求庇护，然后就找到了安全的避风港。$B$B你迷路了吗？我可以帮你什么忙吗？"
D.Strings[20471]="银行位于二楼，在你进入的建筑物的右侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20472]="飞行管理员位于主露台上，就在你进入主楼之前所看到的双楼梯的最上层。$B$B我会在你的地图上标记这个位置。"
D.Strings[20473]="旅店位于主楼层，在你进入建筑物时的右侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20474]="雅拉·月落在工匠大厅内兜售试剂，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20475]="啊，来了一位绘卷大师！我想你在寻找墨水和羊皮纸，对吗？在工匠大厅内可以发现他们，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20476]="是的，城市里有药材供应商。在工匠大厅内可以发现托米·补铲，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20477]="你可以在工匠大厅内购买采矿用品，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20478]="我依稀记得在工匠大厅内有一名工程师，就位于你进入主建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20479]="皮革加工和皮草？你肯定在寻找一位皮匠。如果我没记错的话，应该在工匠大厅内。$B$B我会在你的地图上标记这个位置。"
D.Strings[20480]="噢，我希望伤势并不严重！治疗者在主大厅内，也就是中央楼梯的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20481]="珠宝加工？这的确是件精细活儿。你可以从工匠大厅的贝诺那购买物资。$B$B我会在你的地图上标记这个位置。"
D.Strings[20482]="你在寻找食物和饮料吗？如果是的话，客栈的晃碟大厨那儿有你要寻找的东西。$B$B我会在你的地图上标记这个位置。"
D.Strings[20483]="在找啤酒吗？好的，有两名酒仙在城市里徘徊，出售优良的啤酒。$B$B如果你没有遇见他们，夜莺旅馆的哈兰·酒腹或旅店的萨娅·茗流可以帮你安排好一切的。"
D.Strings[20484]="嘴馋想要吃些甜品吗？你需要找到粉牡丹。$B$B她通常在神殿的前露台或正殿徘徊。"
D.Strings[20485]="你需要与米歇尔·扫榻谈谈。他供应充足的肉类。$B$B我会在你的地图上标记这个位置。祝你好运！"
D.Strings[20486]="考虑过引爆一个或两个烟花吗？我应该自己去买些烟花！主露台上可以发现供应商。$B$B我会在你的地图上标记这个位置。"
D.Strings[20487]="她不漂亮吗？唉……"
D.Strings[20488]="她是那么聪明、有趣！我为她神魂颠倒。"
D.Strings[20489]="我该如何告诉她我的真实感受呢？噢，我不擅言辞！"
D.Strings[20490]="你觉得她可能对我这样的人来电吗？我很……不赞同！"
D.Strings[20491]="我敢打赌，她喜欢雄壮的男人。我该怎么办？"
D.Strings[20492]="难道你觉得我应该去那些禅院中受训做一名武僧？你知道的，为了让她留下深刻的印象。"
D.Strings[20493]="我没有大啤酒肚。我需要一个大啤酒肚。好吧。说做就做！"
D.Strings[20494]="我知道她喜欢千杯不醉的男人，所以我每天晚上喝得烂醉，来锻炼我的酒量。"
D.Strings[20495]="怎么所有的男人都不急着约女人出来？"
D.Strings[20496]="我觉得他喜欢我，但我不确定。你是怎么想的，$r？"
D.Strings[20497]="噢，不，如果他认为我太多毛了呢？如果他不喜欢黑白相间的女子呢？"
D.Strings[20498]="我使出浑身解数调情，但我想他没收到讯息！"
D.Strings[20499]="他总是谈论扳手和超载电容器。他肯定知道哄骗女孩。嗷！"
D.Strings[20500]="我当然喜欢他漂亮的脸蛋。"
D.Strings[20501]="想看些你喜欢的护甲吗，$r？只有你在潘达利亚最具挑战性的地牢中证明自己的价值，你才能获得这些罕见的护甲套件。$B$B你必须寻找这些地牢，并步行进入。以足够快的速度赢得挑战的人们应得到我们大铸甲师的尊敬，也许还会在邮件中收到一个罕见护甲礼物。"
D.Strings[20502]="我们无家可归，但只要我们还活着，就会在其他地方重建家园。"
D.Strings[20503]="我们会卷土重来，$r。"
D.Strings[20504]="我们刚刚抵达时，这里是一座壮丽的山谷。它的池塘中充盈着我们从未见过的神奇之水。$B$B可跟着，那个名叫加尔鲁什·地狱咆哮的家伙就来了。他带来的只有毁灭。等他离开时，山谷中的水已经干涸了。"
D.Strings[20505]="在翡翠林所发生的是一场可怕的悲剧。我坚信，只有向他们学习，才能避免重蹈覆辙。$B$B这个图书馆里有很多知识。我已经了解到很多关于煞魔的知识。"
D.Strings[20506]="锦鱼人曾经从这个地方，以这个权力座位统治整个潘达利亚。$B$B我们必须学习所有历史知识，这样，我们才有可能收复失地。"
D.Strings[20507]="这个图书馆里的知识令人震惊。"
D.Strings[20508]="有个名叫萨拉·芬克斯维奇的战斗训练师在主露台上训练她的宠物。$B$B我会在你的地图上标记这个位置。"
D.Strings[20509]="是的，楼下就有渔具供应商，就在夏之台的一楼。$B$B我会在你的地图上标记这个位置。"
D.Strings[20510]="你好，亲爱的。你一直都在战场上吗？"
D.Strings[20511]="有什么我可以帮你吗？"
D.Strings[20512]="锄头是忠实的$G男人的:女人的;武器。"
D.Strings[20513]="你好啊，$n。汇风岭附近发生的一切我都已经了然于胸了，宝贝儿。活到我这把年纪，总会交到几个大嘴巴的朋友。"
D.Strings[20514]="你是谁？"
D.Strings[20515]="我们的熊猫人战役才刚刚开始，$n。"
D.Strings[20516]="我相信我们最终可以找到我父亲的青春之池。我们可以为泰兰德提供尽可能多的信息。"
D.Strings[20517]="因为我们来到这片新的土地，所以我的哨兵面临许多危险。我们准备好迎接任何挑战。"
D.Strings[20518]="在进入四风谷后，我军的士气有所提高。"
D.Strings[20519]="四风谷真是个的天堂。"
D.Strings[20520]="亲眼见到这个地方是我父亲的梦想。我必须在这里完成他的心愿。"
D.Strings[20521]="在收集我们所要的信息之前，我们都在这个谷里休息。然后，我们必须想方设法回家。"
D.Strings[20522]="这里有一些屏障保护着四风谷，阴止我使用传送门魔法。"
D.Strings[20523]="我们能在这个四风谷遇见还真巧。"
D.Strings[20524]="加尔鲁什的狂妄摧毁了锦绣谷。这是无法治愈的创伤。"
D.Strings[20525]="泰兰德派我们来这里寻找圣光。"
D.Strings[20526]="这里的树比我在南部丛林见过的都更漂亮。"
D.Strings[20527]="我从来没有见过像这样的地方。"
D.Strings[20528]="这山谷里的池水莫非就是传说中的“青春之池”？也许我们可以再次掌握永生……"
D.Strings[20529]="我们已经听说了魔古族遍布四风谷的消息。他们不会胜过我们的。"
D.Strings[20530]="我们在研究池水的同时，还会巡逻城市的边界，保护这里的人。"
D.Strings[20531]="说实话，我起初并不相信瓦尔德林看见的幻像。但这地方确实散发着不同寻常的魔法之力——难道这就是传说中的“青春之池”？"
D.Strings[20532]="这很有意义！"
D.Strings[20533]="<他专心地俯视大厅。>"
D.Strings[20534]="我的下一个伟大的冒险即将开始。$B$B我看到的那是一道圣光吗？"
D.Strings[20535]="我每天都存入各种新旧资料。有时是古老的智慧书卷，有时则是某位墨水大师创作的山谷写生图。$b$b我们保存着这些知识，以便让后人能从我们的成功……和失败中借鉴一二。"
D.Strings[20536]="闻上去香极了，是吧？"
D.Strings[20537]="你需要什么吗？"
D.Strings[20538]="在黎明破晓时分，重锤将要砸落。"
D.Strings[20539]="生命中什么最美好？\n\n哥们儿，小曲儿和美酒！"
D.Strings[20540]="我喜欢女人就像我喜欢啤酒——丰满而醇厚。"
D.Strings[20541]="我为爱甘愿付出一切。可我不会这么做。至少，现在不行。"
D.Strings[20542]="你好，$c。我并无恶意。$B$B我在这以血色十字军成员的身份出现，是因为他们已经无可救药地堕入了腐化与邪恶。$B$B我需要你的帮助，彻底终结他们的罪孽。"
D.Strings[20543]="$n，在我把酒酿好之前，不要让野牛人靠近！"
D.Strings[20544]="我是听着白虎的传说长大的。他是潘达利亚人民的英雄。很荣幸能来此受训。"
D.Strings[20545]="信标彼此呼应，外来者。传递重要的信息。$b$b你的耳朵听不见那些信息。只有赢得卡拉克西信任的人才能听到他们说的话。"
D.Strings[20546]="能为我所笃信的一切牺牲自己，是我的荣耀。"
D.Strings[20547]="我很忙，外来者。"
D.Strings[20548]="终有一天，卡拉克西会晋升我的地位。会允许我消耗琥珀。"
D.Strings[20549]="卡拉克西从不轻易相信别人，外来者。我花了很多年时间才令他们正眼相看。"
D.Strings[20550]="我们人人都有天赋，外来者。只不过有些人表现得没那么明显。"
D.Strings[20551]="我想我们差不多干完一半了，对吧？已经解决了血色大厅，还剩下血色修道院。$B$B要是我突然消失了你可别吃惊——我得快点赶到那里。"
D.Strings[20552]="真是好消息。我们对这里的能量和神器的研究有回报了。$B$B我们已经对在这里找到的魔古族装置有所了解，更令人振奋的是，还找到了让它们为我所用的方法。这座建筑的围墙会汲取和削弱任何置身其中的敌人的力量。"
D.Strings[20553]="你确定吗？这地方很危险，而且我们的首批研究人员都还没能安然返回。如果我们禁用了弱化力场，我们就要离开，直到遗迹被安全守住后才能回来，而且不能再次激活装置。$B$B我再问一次——你确定吗？"
D.Strings[20554]="我真希望你知道自己在做什么。"
D.Strings[20555]="终于能重获和平了！"
D.Strings[20556]="你是真正的英雄！"
D.Strings[20557]="我终于能继续回去织毛线了！那些冬天戴的围巾可不会自己跑出来！"
D.Strings[20558]="我们要向你表达敬意与感谢。"
D.Strings[20559]="这个村庄的胜利要归功于你。"
D.Strings[20560]="一味地为弄丢遗骸而悔恨是愚蠢的。这个村子是最先挺身对抗雷电之王的先驱之一。这是一场伟大的胜利！"
D.Strings[20561]="当我们直面雷电之王时，我们一定会做好准备。"
D.Strings[20562]="是你帮这村庄找回了力量！"
D.Strings[20563]="不会只有我们一个村庄挺身对抗雷电之王！"
D.Strings[20564]="和渔夫交朋友总是好事。你永远也不会挨饿！"
D.Strings[20565]="我早知道我们能打败入侵者！"
D.Strings[20566]="不管我以前说过什么，我从没怀疑过你的能力！"
D.Strings[20567]="赞达拉决不该低估我们！"
D.Strings[20568]="这个村庄一向宁静怡人。"
D.Strings[20569]="改变是难以避免的，即便是对于像杜术这样的老顽固来说也是一样。"
D.Strings[20570]="我的女儿浑身充满了志气和坚毅！她比我丈夫还让我省心。"
D.Strings[20571]="我的侄女丽丽无法静下心来探索潘达利亚。但如果只是蜻蜓点水般的东游西逛，是不可能了解一片全新土地的。重要的是，要跟你遇见的每一个人交谈，用心体会每一个地方，直到它已深入你的灵魂。$b$b这才是云游者之道！"
D.Strings[20572]="丽丽不明白为什么我总是停下来品尝各地的美酒。可根据我的经验，一个人群的性格，就体现在他们喝的东西里！$b$b你尝过大陆熊猫人的啤酒了吗？口感既清冽，又醇厚。只需品上一口，你就会知道，这酒是经由悉心慢酿而成。喝这酒的人，也必然是淡然恬静，不慌不忙，乐于与朋友分享美好的时光。$b$b你喝什么呢，$c？它又如何反映着你的性格，嗯？"
D.Strings[20573]="如果你在这谷里待足够长的时间，也许你能与所有当地人交上朋友。甚至有一天，你可以安顿下来，拥有属于自己的一亩三分地。$b$b想象一下，你这厌倦尘世的$c，却在这里安顿下来，管理农场！$b$b<陈闭上双眼，捧腹大笑。>"
D.Strings[20574]="这些神圣之水被污染了，但希望仍在。即便是面对如此巨大的腐蚀之力，我们古老的仪式也能坚持完成净化。当水复原后，污染之人的力量就会衰退。"
D.Strings[20575]="影踪派一直是土地精的朋友。他们为什么不让我们进去做生意？"
D.Strings[20576]="我们长途跋涉。现在影踪派却说，他们不想要我们的商品。真是太奇怪了。"
D.Strings[20577]="我们一路上曾遇到愤怒的猢狲、发狂的雪人和肮脏的牦牛，最后来到这里。现在，影踪派把我们当陌生人。$b$b运气真是不好。"
D.Strings[20578]="我的鼻子凉了。这是非常糟糕的预兆。"
D.Strings[20579]="我在前来的途中丢失了牦牛。这可真糟糕。"
D.Strings[20580]="太奇怪了。影踪派是我们最好的客户。我们将物资出售给他们，他们则保证我们的安全。$b$b现在为什么要对我们不理不睬？我无法理解。"
D.Strings[20581]="那你在这干什么呢？大老远跑下来，就为了享有我的陪伴？"
D.Strings[20582]="一片充满失落秘密的新大陆！跟这里的游学者和我分享你了解到的一切，我会让你参与到其它的项目中来。"
D.Strings[20583]="让我参与你其它的项目吧。"
D.Strings[20584]="有人说过，宁愿点燃蜡烛，也不愿意诅咒黑暗……$b$b好吧，他们点过的蜡烛可能没我多。"
D.Strings[20585]="有句话是这么说的——“你的脸朝向太阳，阴影将落在你身后。”$b$b我希望你能发现光明的未来，$n！"
D.Strings[20586]="从一而精，此为烹饪之道。"
D.Strings[20587]="<米师很高兴和你在一起！>"
D.Strings[20588]="<米师兴奋得上窜下跳。>"
D.Strings[20589]="<米师冲着你笑。>"
D.Strings[20590]="<米师欢快得上窜下跳。>"
D.Strings[20591]="<米师很快乐！>"
D.Strings[20592]="我们正要去参加云游节。你一定得跟我们一起去！"
D.Strings[20593]="相传刘浪曾经骑在一只巨龟背上，去探索潘达利亚之外的广阔海域。他每隔几年会回来一次，并邀请新的探险家与他同行。直到今天，每当有熊猫人做白日梦或者呆望天空的时候，我们便会问他们是不是在“等待海龟”。$b$b大部分熊猫人并不爱冒险。他们喜欢温暖舒适的居家生活。但我们中仍然有一些梦想家……今晚我们将聚集在南部海岸的海龟沙滩眺望大海，纪念刘浪的冒险精神。$b$b这就是“云游节”。"
D.Strings[20594]="只要……再来……一次！"
D.Strings[20595]="这里的建筑很奇怪，与传统的魔古族设计风格有很多不同之处。这个房间似乎是某种装置，但是从我的笔记上看不出它的用途。\n$b我们只有去激活它然后观察，才能弄清其用途。\n$b最糟糕的情况会是什么呢？"
D.Strings[20596]="你需要什么东西吗？"
D.Strings[20597]="我们要追捕敌人。"
D.Strings[20598]="我会成为插入敌人咽喉的那把利刃。"
D.Strings[20599]="没有人敢和影踪派作对。"
D.Strings[20600]="“赤烟”腾武向你问好。"
D.Strings[20601]="影踪派的所有敌人都将倒在“赤烟”腾武面前。"
D.Strings[20602]="我主要是帮助年轻的熊猫人在这些方面发掘他们的潜力。虽然真正掌握技巧需要大量的时间和练习，但首先寻找到一种合适的方法也十分重要。"
D.Strings[20603]="你喜欢神奇的冶金技术、奥妙的熔炼技艺、优美的合金秘法吗？"
D.Strings[20604]="精力充沛，不知疲倦。一天到晚都在埋头苦干。"
D.Strings[20605]="<艾莎似乎正沉浸在她的功课中。>"
D.Strings[20606]="啊！一个药剂爱好者？酒仙们知道如何调配化合物，但却常常遗漏药剂或疗法的精细配方。"
D.Strings[20607]="你想从光板儿这里得到什么？"
D.Strings[20608]="你只是向神器中注入了魔力，并不意味着那些魔力将永远留存在其中。"
D.Strings[20609]="我在影踪派期间学到了许多秘技。或许你也已经有幸学到了一些。"
D.Strings[20610]="我为那位大人效力，他是该族最后的血脉。$b$b如果你对我有意见，就去向王子殿下诉说吧。"
D.Strings[20611]="我会时刻盯着你的，$c。但这并无恶意。$b$b如果你有任何消息，我会替你转达。如果没有，你最好不要停下。"
D.Strings[20612]="我去找，你出钱。"
D.Strings[20613]="野牛人从四面八方包围过来了，$n！快，保卫村庄，别让他们烧了它！"
D.Strings[20614]="我只为卡拉克西瓦效力。"
D.Strings[20615]="猢狲不一定是最好的酿酒师，但是盎迦猴岛的那些猢狲似乎偷到了最好的原料。"
D.Strings[20616]="欢迎来到天禅院。"
D.Strings[20617]="很高兴见到你，$n！我和我的学生来品尝酒仙布夫酿造的美酒，顺便庆祝酿月祭！"
D.Strings[20618]="作为织雾者，我们必须始终为需要帮助的人提供保护。"
D.Strings[20619]="织雾者年云也许有些严厉，但实际上是个心地善良的老师。"
D.Strings[20620]="雪怒教给了我们力量的意义。"
D.Strings[20621]="看到大家精神如此饱满，真是太好了。"
D.Strings[20622]="这个节日让我意识到昆莱山是多么美丽。"
D.Strings[20623]="你好，$n。你喜欢这个节日吗？"
D.Strings[20624]="我在我们的训练场地看到一个宠物斗士。云端翔龙无论做什么都一样表现出色，包括与其他宠物战斗！要获得雏龙的关键在于与一只成年翔龙建立良好的关系。只要你在骑士团中的声望达到崇拜，就可以在百木园的各个角落找到它们。"
D.Strings[20625]="孩子，我想你是为龙龟而来的吧？"
D.Strings[20626]="你怎么知道我会愿意卖给你啊，外来者？"
D.Strings[20627]="这个问题问得好。我们是一群奇怪的家伙……很少有熊猫人会选择住在长城的这一侧。$b$b长话短说吧，我们是酿酒的。但可不是什么酒都酿……是用伟大的凯帕圣树的树脂酿酒。"
D.Strings[20628]="……有点恶心，我知道。可事实并非如此。$b$b这些大树生成的琥珀具有神奇的治愈能力。但欲求不满的螳螂妖还进一步消耗它，用来制造武器和建筑……我甚至听到过这样的传说，螳螂妖会将它们的大英雄封存在琥珀里，以使其永存不朽。"
D.Strings[20629]="没错。树脂大师的起源可追溯到无数世代以前。我在广大渴求树脂的熊猫人中，只是一位无名小卒。$b$b但有时候，我担心自己也许是最后一代传人了。"
D.Strings[20630]="大树正在消亡。凯帕圣树·沃尔已经死了……沦为了邪煞的牺牲品。它再也不会生出琥珀。甚至连外形都不再像是一棵树。$b$b仅剩的几棵仍在生成琥珀的大树也面临着被螳螂妖过度开采的困境，或是处在邪煞的威胁之下。不论如何，一旦没有了树脂，也就不会再有树脂大师。到那时，我就只能重操旧业了。"
D.Strings[20631]="滚汤团啊。$b$b<吴暮叹息着。>"
D.Strings[20632]="卡拉克西的仆从想要什么？"
D.Strings[20633]="我会尽量将船留在这里。$B$B多加小心！"
D.Strings[20634]="我们会尽力保护船只和船员。$B$B别为我们担心！"
D.Strings[20635]="这里发生了什么事？！$B$B普罗德摩尔女士的塔就这么……消失了！"
D.Strings[20636]="真是灾难！$B$B会是什么人干的？！"
D.Strings[20637]="不知还有没有人活下来……"
D.Strings[20638]="是部落干的吗？！$B$B圣光啊，救救我们……"
D.Strings[20639]="贾鲁今天能为你做些什么？"
D.Strings[20640]="永远努力成就不可能的事。"
D.Strings[20641]="愿你在今后的日子里荣耀相伴，勇敢无畏，$r。"
D.Strings[20642]="我们只会对最可信赖的盟友透露金莲至深的秘密。"
D.Strings[20643]="欢迎到山谷来，朋友。一切随意，别惹麻烦。"
D.Strings[20644]="来自各地的商贩都进城了。你要找什么？"
D.Strings[20645]="你在城里没能找到需要的东西吗？$B$B你在找什么？也许我能帮你找到它。"
D.Strings[20646]="噢，你在找职业训练师？很可惜，他们并没能抵达锦绣谷。$B$B你可以回主城去找他们。"
D.Strings[20647]="在找专业训练师？$B$B在潘达利亚各地都能找到禅师级训练师。告诉我你要找哪位吧。$B$B如果你无法在潘达利亚找到要找的人，那就回主城找专业大师吧。他们应该也能帮你提高手艺。"
D.Strings[20648]="你可以在四风谷的丝纱工坊上找到蔡丝匠。我会在你的地图上标出他的位置。"
D.Strings[20649]="你可以去卡桑琅丛林的渔人码头找纳特·帕格，提升钓鱼技能。让我为你标出他的位置。"
D.Strings[20650]="大师级矿工就在翡翠林的绿石采掘场。他们也许能帮你提升技能。我会在你的地图上标出他们的位置。"
D.Strings[20651]="制皮训练师就在昆莱山的土地精集市。我会在你的地图上标出位置。"
D.Strings[20652]="我听说在卡拉克西当中有炼金大师，就在距离长城很远的恐惧废土。我会为你在地图上标出位置。"
D.Strings[20653]="在四风谷的奈辛瓦里狩猎队营地里有位剥皮训练师。$B$B我会在你的地图上标出位置。"
D.Strings[20654]="如果你有附魔方面的需求，就得去翡翠林的晨芳园找莱·咒爪谈谈。$B$B我会在你的地图上标出位置。"
D.Strings[20655]="你可以在四风谷的奈辛瓦里狩猎队营地里找到你要找的人。$B$B我会在你的地图上标出位置。"
D.Strings[20656]="你一定是在找禅宗铁匠劳敖！他在锦绣谷的残阳关卫戍营里工作。$B$B我会在你的地图上标出他的位置。"
D.Strings[20657]="在锦绣谷魔古山宫殿上方的闻道之座有位考古学大师。$B$B我会在你的地图上标出位置。"
D.Strings[20658]="噢是的，你一定是在找治疗者楠。她就在七星殿里。$B$B我会在你的地图上标出她的位置。"
D.Strings[20659]="想提高自己的厨艺是吗？$B$B你应该跟铁掌家族的人谈谈。他们就在四风谷的半山市集。$B$B我会为你在地图上标出位置。"
D.Strings[20660]="如果你想对草药学有更深的了解，我建议你去找翡翠林中的训练师谈谈。$B$B我会为你在地图上标出位置。"
D.Strings[20661]="是的，我知道在锦绣谷的闻道之座有位铭文训练师。$B$B让我在你的地图上标出位置。"
D.Strings[20662]="你要找的人是塑玉者麦逸。她就在翡翠林的绿石村。$B$B我会在你的地图上标出她的位置。"
D.Strings[20663]="穿云行者凌大师能教你如何在潘达利亚飞行。他正骑着云端翔龙停在主露台上。我会在你的地图上标出他的位置。"
D.Strings[20664]="在谷中没有战场军官。$B$B你必须返回主城，才能加入战场或竞技场的战斗队列。"
D.Strings[20665]="想买杂货？伯妮那儿应该有你要找的东西。她就在金色神灯卖杂货。我会在你的地图上标出位置。"
D.Strings[20666]="我看到有个小贩在金色神灯摆摊卖货。我会在你的地图上标出位置。"
D.Strings[20667]="啊，你在找什么军需官？也许我能帮你找到他们。"
D.Strings[20668]="垂钓翁军需官？看来你要找的人是纳特·帕格。他就在卡桑琅丛林的渔人码头。$B$B让我为你在地图上标出位置。"
D.Strings[20669]="如果你要找阡陌客军需官，那就去跟吉娜·泥爪谈谈。她就在半山市集经商。$B$B让我为你在地图上标出位置。"
D.Strings[20670]="嗯，恐怕我对卡拉克西一无所知，但我听人私下里提到过他们的城市——卡拉克西维斯，就在位于遥远西方的恐惧废土。也许你能在那里找到卡拉克西军需官。$B$B我会在你的地图上标出位置。"
D.Strings[20671]="影踪派军需官就在螳螂高原的影踪卫戍营。$B$B我会在你的地图上标出位置。"
D.Strings[20672]="啊，你要找宽仁的贾鲁！他就在我身旁。"
D.Strings[20673]="至尊天神军需官就在山谷里。白心贤者与其他阵营的代表都在夏之台的下层。$B$B我会在你的地图上标出他的位置。"
D.Strings[20674]="你要找谭欣眺。她就在锦绣谷魔古山宫殿上方的闻道之座。$B$B我会在你的地图上标出她的位置。"
D.Strings[20675]="勇气军需官——指挥官牛心，就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出她的位置。"
D.Strings[20676]="你可以找指挥官罗平兑换公正印记，他就在螳螂高原的砮皂寺。$B$B我会在你的地图上标出他的位置。"
D.Strings[20677]="你可以在西边那道名为蟠龙脊的雄伟长城上找到荣誉军需官。$B$B我会为你在地图上标出位置。"
D.Strings[20678]="你可以在西边的蟠龙脊上找到征服军需官和卓越征服军需官。$B$B我会在你的地图上标出他们的位置。"
D.Strings[20679]="普利波先生在教我如何做一位标本剥制师。我个人觉得他的思想过于陈旧了，应该从侏儒工程学中找点儿灵感。"
D.Strings[20680]="影踪派的不懈戍守，是这片土地至今仍未被螳螂妖大军席卷的唯一理由。我们不求感谢，可我们眼下再也无力独自完成这项任务了。"
D.Strings[20681]="你好，$n。只有精通工程学的人才能使用我的拍卖服务。很遗憾，你不在此列。只好请你离开了。"
D.Strings[20682]="你能相信他们竟然不放我进去么？在所有人当中偏偏是我？"
D.Strings[20683]="你看不见我正在参加瞪眼大赛吗？"
D.Strings[20684]="我才不会落入你的圈套，$r。胜利属于我！"
D.Strings[20685]="这个蠢货不明白。他毫无顾忌地放任自己的负面情绪。如果任其发展，我们所有人都会尝到苦果。"
D.Strings[20686]="这个老熊猫人愚蠢至极。我们怎能不带着情绪战斗？那不可能！"
D.Strings[20687]="你知道什么？别搞得自己像是艾泽拉斯的救世主一样！"
D.Strings[20688]="要是你能进入我们的睡室，那就自便吧。"
D.Strings[20689]="看在你还有用的份上，你可以留下，外来者。"
D.Strings[20690]="真没想到卡拉克西瓦竟允许你活着，反正也轮不到我管。"
D.Strings[20691]="只要你对我们还有用处，我就会为你安排膳宿。"
D.Strings[20692]="“闪光之刃就是这么来到了潘达利亚，而后又离开，从此下落不明。”$B$B在我们的人民间充满了精彩丰富的传说故事。我要做的就是将它们收集起来，使其能千秋万代地流传下去。"
D.Strings[20693]="在这里贮存着关于这个古老世界浩如烟海的广博知识，而我们才刚刚开始知晓而已！"
D.Strings[20694]="祝你好运连连，$r。$B$B如果你在找好运符，我马上就能让你如愿以偿。"
D.Strings[20695]="我曾经有个农场，但那是在很久之前了。我想要痛快地大战一场，你呢？"
D.Strings[20696]="我原本只逮到了两只兔子。可现在却有这么多！"
D.Strings[20697]="你怕蜘蛛吗？据某些在这片无尽森林中往来的旅者说，他们老觉得身上有蜘蛛在爬。"
D.Strings[20698]="你看见朗姆酒了吗？……嗝儿！我到处都找遍了！"
D.Strings[20699]="俗话说得好，树大易招风，菇小可避雨。"
D.Strings[20700]="尺有所长，寸有所短。量才器使，知人善用。"
D.Strings[20701]="早起的鸟儿有虫吃，但耐心的熊猫人才有美酒喝。"
D.Strings[20702]="暴力虽能逞一时之快，但所造恶业永难消除。"
D.Strings[20703]="以德报怨，以爱消恨。"
D.Strings[20704]="欢迎你，$r。$B$B我还只是一棵小树苗，我将在潘达利亚扎根，与这片土地融为一体。这样，泰兰德才能从它蕴藏的故事中受益。为了达成她的心愿，强弓家族自愿留下来保护我渡过幼年期。"
D.Strings[20705]="别担心，雏龙在这里会很安全的。"
D.Strings[20706]="这些年来，我见过不少弟子，但你似乎有些与众不同。"
D.Strings[20707]="对你的翔龙表现出你的善意和尊重，它就会慢慢信赖你。"
D.Strings[20708]="不积跬步，无以至千里。"
D.Strings[20709]="我会密切注意所有的弟子。我非常渴望看到你的进步。"
D.Strings[20710]="野生云端翔龙的生育率非常低。所以，每一枚翔龙蛋都是极其珍贵的。$B$B如果我们不努力保护野生云端翔龙，它们或许就会彻底绝种。"
D.Strings[20711]="在所有的野生翔龙中，玛瑙翔龙是最稀有的。据悉，这些难得一见的黑色云端翔龙会在东北边的临风岛上产卵。$B$B如果你在那里发现任何玛瑙翔龙蛋，请把它们带来给我。我会好好奖赏你的。"
D.Strings[20712]="你喜欢我的蛇吗？我感觉它们不喜欢你！"
D.Strings[20713]="<你的雏龙好奇地看着你。>"
D.Strings[20714]="<你的雏龙对你微笑。>"
D.Strings[20715]="<你的雏龙对你啾啾鸣叫。>"
D.Strings[20716]="<你的雏龙看着你。>"
D.Strings[20717]="<你的雏龙百无聊赖地看着你。>"
D.Strings[20718]="<你的雏龙四处嬉戏飞翔。>"
D.Strings[20719]="<你的雏龙在你的手臂上蹭着鳞片。>"
D.Strings[20720]="<你的雏龙舔了舔你。>"
D.Strings[20721]="人们将铭记你的英勇事迹。"
D.Strings[20722]="虚灵的商店开在楼上的走廊里，就在主建筑物进门的右手边。$B$B我会在你的地图上标出位置。"
D.Strings[20723]="你可以在主楼外的主露台上找到兽栏管理员追踪者老朗。他就站在战斗宠物训练师的旁边。$B$B我会在你的地图上标出位置。"
D.Strings[20724]="在找啤酒吗？烈酒窖有最香醇的美酒！我会在你的地图上标出位置。"
D.Strings[20725]="啊，看来你想当厨师对吧？你可以在大麦花那里找到你所需要的一切。她就在烈酒窖里卖货。$B$B我会在你的地图上标出位置。"
D.Strings[20726]="德兰达·安克辛携带着附魔物资。在师匠大厅内可以找到她，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20727]="我必须承认，在那最黑暗的时刻，我不敢相信我们还能活下来。多亏你和你的族人，幸好事情没往我预想的方向发展。"
D.Strings[20728]="织花女士伊莎那一流的制衣手艺人尽皆知。$B$B她在师匠大厅内工作，就位于你进入建筑物时的左侧。$B$B我会在你的地图上标记这个位置。"
D.Strings[20729]="那些……野牛人！\n\n它们袭击了我的农场，还有附近的西风之息……杀死了不少人，然后把剩下的全都赶走了！\n\n我在这里集结了一些乡亲。滨岸村会来帮忙吗？"
D.Strings[20730]="你见过玛瑙翔龙吗？它们会在临风岛上产卵。要是你能把龙蛋带给安离长老，一定能得到应有的回报。"
D.Strings[20731]="你参加飞行竞技赛了吗？祝你好运。"
D.Strings[20732]="我想我对朔弥的看法是错的……"
D.Strings[20733]="长者们说得对——人确实不可貌相。"
D.Strings[20734]="你觉得朔弥能向我展示她的战技吗？"
D.Strings[20735]="别让她知道我说过这些，可我认为朔弥确实将村庄守得很好。"
D.Strings[20736]="你正在寻找药剂师。他能配出真正神奇的药水和酊剂。立刻使我摆脱了皮疹！$B$B呃哼……维克多·皮尔斯在师匠大厅出售他的商品。我会在你的地图上标记这个位置。"
D.Strings[20737]="飒安·红鳞是云端翔龙骑士团的军需官。$B$B他就在翡翠林的百木园。$B$B我会在你的地图上标出他的位置。"
D.Strings[20738]="为什么……为什么是他？我们只是淳朴的农民……怎么竟然这么倒霉？"
D.Strings[20739]="我丈夫想去看看水边发生了什么事。就在那时……那时……$B$B<苏云长老泣不成声。>"
D.Strings[20740]="一枚该死的炸弹朝我们袭来。我没死，可……我丈夫……"
D.Strings[20741]="<杜宇看着你，颇感自豪。>"
D.Strings[20742]="啊，清风传达了贵客来访的消息。只要我们能保持开放的心胸，纯净的灵魂，就一定能从彼此身上获益良多。$B$B跟部落比起来，也许你的族人能给予我们更大的尊重。"
D.Strings[20743]="在探索潘达利亚时一定要心存戒备。对冒失的旅者来说，这是一片机遇与危险并存的土地。"
D.Strings[20744]="你脚下的大地富有生命力。别看它现在让你站得稳稳的，要是你胆敢将战祸和痛苦引来这里，它就会以牙还牙。这就是自然之道。"
D.Strings[20745]="我们的村庄不大，但我家世代都在这片山上酿造潘达利亚最优质的苹果酒。$B$B我现在只想平安回去，好收割庄稼，与孩子们团聚。"
D.Strings[20746]="你是种什么生物？真奇怪……"
D.Strings[20747]="在你之前到来的陌生人偷走了我们的孩子。你又想偷什么？我们的妻子？还是美酒？"
D.Strings[20748]="这里原本是个宁静的酿酒村。可现在，恐怖的战争已经让我们的孩子失去了天真。$B$B去别处打仗吧，$r。"
D.Strings[20749]="再次感谢你的帮助，$n。我们的孩子都已安全返回，敌人也已经四散而逃。$b$b对我来说，随时欢迎你和你的部落造访潘达利亚。"
D.Strings[20750]="瞧瞧你，简直瘦得皮包骨头！你得多吃点！"
D.Strings[20751]="你是否值得我们信赖，不是我说了算。在村长作出相反的判定以前，我都当你是朋友。"
D.Strings[20752]="就在不久前，我们还过着只知道酿造可口苹果酒的简单生活。在这么短的时间内，一切都变了。"
D.Strings[20753]="谁也不知道变幻之风会带来什么，也许是可怕的风暴，也许是盛大的丰收。看来这次带来的是你。$B$B现在，我想问问，你究竟是风暴还是丰收？"
D.Strings[20754]="欢迎来到坡东村，异乡人。我不知你是为何而来，但你看起来需要休息。$B$B不如坐下喝杯可口的苹果酒，将烦恼丢到一边，怎么样？"
D.Strings[20755]="<你的翔龙好奇地看着你。>"
D.Strings[20756]="<你的翔龙对你微微一笑。>"
D.Strings[20757]="<你的翔龙对你咕噜了两声。>"
D.Strings[20758]="<你的翔龙看着你。>"
D.Strings[20759]="<你的翔龙百无聊赖地看着你。>"
D.Strings[20760]="<你的翔龙优雅地四处翱翔。>"
D.Strings[20761]="<你的翔龙在你的手臂上蹭着鳞片。>"
D.Strings[20762]="<你的翔龙撞了你一下，差点把你撞倒。>"
D.Strings[20763]="<雏龙好奇地看着你。>"
D.Strings[20764]="<雏龙对你微微一笑。>"
D.Strings[20765]="<雏龙对你咕噜了两声。>"
D.Strings[20766]="<雏龙看着你。>"
D.Strings[20767]="<雏龙百无聊赖地看着你。>"
D.Strings[20768]="<雏龙优雅地四处翱翔。>"
D.Strings[20769]="<雏龙在你的手臂上蹭着鳞片。>"
D.Strings[20770]="<雏龙撞了你一下，差点把你撞倒。>"
D.Strings[20771]="欢迎来到云端翔龙骑士团。只有在我们骑士团里达到崇拜的人才能获得我们的云端翔龙。"
D.Strings[20772]="欢迎你，翔龙骑士！我这里有美丽的云端翔龙，欢迎随意挑选。"
D.Strings[20773]="我们必须小心应对近来在海岸上发生的事。坡东村是个酿酒小镇，不是战斗要塞。$B$B你也应该提醒你的首领，在评判我族人时也应该持有同样谨慎的态度。我们不主动寻衅，但也决不是缩头乌龟。$B$B我得好好想想。"
D.Strings[20774]="我的族人面对过许多考验……可却从没遇到过这样的事。"
D.Strings[20775]="你们的战争让这里遭遇了前所未有的灾难。与你们那些飞艇和炸弹比起来，就连螳螂妖的威胁都显得稍逊一筹。"
D.Strings[20776]="我已经把这里发生的一切报告给了影踪派。希望他们能采取行动。$B$B尽管我们都对即将到来的考验毫无准备，但也必须面对。"
D.Strings[20777]="去城外找奥黛丽·伯恩赫普，就在矮人区北部，湖畔小屋附近。"
D.Strings[20778]="战斗宠物训练师"
D.Strings[20779]="去城中台地的顶上找名叫瓦佐克的兽人，就在飞行管理员东边。"
D.Strings[20780]="也许我们可以把剩下的货物卖给你，换些金币？要想活命，我们就必须从其它村子采购食物和饮水。"
D.Strings[20781]="你看起来似乎饱经风霜。要是你想买什么旅途用品，一定要告诉我。"
D.Strings[20782]="一颗不长眼的炸弹击毁了我的农场。我该怎么生活下去？"
D.Strings[20783]="在南边有一处断崖，在那种田应该不错。站在崖边还能俯瞰峡谷。你也许是对的，陌生人。"
D.Strings[20784]="我们不是战士。我只负责制作工具和狩猎用的轻型武器。"
D.Strings[20785]="蜜露村根本没做好战斗的准备。希望这场争斗能尽早结束！"
D.Strings[20786]="哦天哪……那武器真不一般。"
D.Strings[20787]="想不想躺下歇会儿？那听起来当然比战斗要好。"
D.Strings[20788]="你是从哪儿找到那么精美的护甲的？能让我……摸一下吗？"
D.Strings[20789]="我们怎么办？已经一败涂地了！"
D.Strings[20790]="要是没有了庄稼，我们就要失去美酒了！"
D.Strings[20791]="拜托，别把战火引到这里来。这跟我们毫无干系！"
D.Strings[20792]="你们为什么要让这片土地遭受战争和杀戮？潘达利亚是和平之地。"
D.Strings[20793]="我们也许不是正牌的战士，可我们会不惜一切代价守护自己的家园和土地。"
D.Strings[20794]="我担心，你们的到来会打破这片土地微妙的平衡。"
D.Strings[20795]="不！猛砸！我说猛砸！"
D.Strings[20796]="你好啊，$n。我为你精心挑选了几种美酒。要是你有兴趣，我还愿意把酿造的本领传授给你。"
D.Strings[20797]="这片土地饱经风霜，灭世者败亡后，它再次焕发了生机。你会发现，我的宠物们也具备类似的坚毅品格。"
D.Strings[20798]="做好准备，$n。$b$b我们即将进入危机四伏的环境！"
D.Strings[20799]="你好啊，$n。想学习制皮技术吗？如果你需要，我这里还有不少精美的手工制品。"
D.Strings[20800]="你好啊，$n。有兴趣学习铭文的神秘艺术吗？还是想了解草药学的复杂知识？"
D.Strings[20801]="不，我也不知道里面有什么。"
D.Strings[20802]="我跟随影踪派，将他们在长城另一侧的诸多事迹如实记录下来——我可不想在这混战中弄丢任何宝贵的手札！$b$b这并非没有先例。游学者们世代以来始终在编纂着熊猫人的历史。在潘达利亚各地都散落着他们的笔记。要是你能收集到这些史料，一定能得到游学者们的赏识！"
D.Strings[20803]="翅膀给了我们高飞的自由。"
D.Strings[20804]="你能相信吗，奥妮克希亚竟然任由这些留在她的巢穴里？我要发大财了！"
D.Strings[20805]="恶魔是这个世界的未来。你越早接受这一点，就能越早加入胜利方。"
D.Strings[20806]="卡利姆多属于恐怖图腾。没人能妨碍我们。$B$B我们是至高无上的，你马上就会亲眼看着我粉碎你那悲惨的队伍。"
D.Strings[20807]="就凭你的热度还对付不了我！"
D.Strings[20808]="我在调查这里的生态情况，为了……研究。"
D.Strings[20809]="生命是通往不死的必经之路。我的宠物们深知这个道理。"
D.Strings[20810]="啊，驯龙。$B$B等这些美丽的家伙长大后，就能把我那蠢哥哥比下去了！"
D.Strings[20811]="在这片沼泽里发生过许多重大冲突。我仍然能感觉到那久未散尽的能量。"
D.Strings[20812]="让萨弗拉斯在你头顶上方挂个几年，你就能学会欣赏熔火甲虫的适应力了。"
D.Strings[20813]="你在这里只会一败涂地。"
D.Strings[20814]="要是这些小东西与它们的原型有半点相像，你就毫无机会！"
D.Strings[20815]="真希望有一天能环游世界。你见过暴风城吗？"
D.Strings[20816]="外域的微风中夹杂着平静与安宁的气息。"
D.Strings[20817]="我们必须精诚合作，保护纳格兰的本土生态。"
D.Strings[20818]="血精灵是宇宙的主宰。这毋庸置疑。"
D.Strings[20819]="这场毁灭本可避免，$c。曾几何时，塞拉摩是和平的象征……"
D.Strings[20820]="真可惜……"
D.Strings[20821]="某些决定会引发可怕的后果。"
D.Strings[20822]="我还没能证明我可以飞呢！我的宠物们也没有！"
D.Strings[20823]="孤身一人在树林里游荡不太安全，你觉得呢？"
D.Strings[20824]="不要相信别人的鬼话。龙只是战争的武器，别无它用。"
D.Strings[20825]="那些联盟渣滓会明白，激怒部落是什么下场！"
D.Strings[20826]="我们将以部落之名夺取这片土地，至死方休！"
D.Strings[20827]="他们甚至都还没见识到部落的怒火！"
D.Strings[20828]="等我们完成这里的事之后，联盟一定会后悔踏上这片土地。"
D.Strings[20829]="我总是觉得心神不宁。"
D.Strings[20830]="如果你继续在战争的路上越走越远，你的行为一定会引发严重的后果。"
D.Strings[20831]="任何行为都会引发后果。你知道自己的行为已经酿成什么后果了吗？"
D.Strings[20832]="我担心，这仅仅是个开始。"
D.Strings[20833]="你眼瞎了吗，竟然要延续这场战斗？"
D.Strings[20834]="我会为了联盟的荣耀，勇敢光荣地战斗！"
D.Strings[20835]="这里乱糟糟的，是吧？"
D.Strings[20836]="我跟妹妹从来都没在蜜露村里见过这种阵势，从来没有！"
D.Strings[20837]="你们的飞艇差点把我们的气球弄爆了！"
D.Strings[20838]="据说，“智慧能照亮前路。”$b$b……可光有智慧，我在夜晚照样会撞到脚趾头。"
D.Strings[20839]="我们必须竭尽全力保护我族人的圣地和寺院。"
D.Strings[20840]="莫鲁克要打扁你！"
D.Strings[20841]="今年的收成不仅包括庄稼！"
D.Strings[20842]="我为这场战斗做了无数小时的准备。"
D.Strings[20843]="勇闯这片荒野，已经让我的宠物变得战无不胜。"
D.Strings[20844]="你将在潘达利亚最神圣的区域内面对最困难的挑战。"
D.Strings[20845]="在这世上要是存在岩石和石料专家，那就一定是矮人！"
D.Strings[20846]="如果我们能弄清拉格纳罗斯是如何影响了海加尔的低等住民，也许就能想出更好的补救措施。"
D.Strings[20847]="你的世界……所有世界……都将燃烧！"
D.Strings[20848]="我为了迎接这一天的到来，已经做了世世代代的准备。"
D.Strings[20849]="要是我们希望消灭联盟，就得尽快重整部队了。"
D.Strings[20850]="我们只该在需要时才继续留在这里，$c。"
D.Strings[20851]="<琪麟茫然地凝视天空，没有任何回应。>"
D.Strings[20852]="很抱歉，可我没有圣物可以出售给你了。它们的魔法力量似乎已经消失了！也许我该改行当全职舞蹈家，改变一下人生的步伐也不错。"
D.Strings[20853]="水流从不说谎。"
D.Strings[20854]="你是谁来着？"
D.Strings[20855]="我的记性大不如前了。"
D.Strings[20856]="今天是礼拜几来着？"
D.Strings[20857]="冈尼和我，我们与其它几名船员一起，被冲到了翡翠林的香里拉村附近。在海上颠簸了几个月后，我们的双脚早已疼得走不动路。我们来到了这里，找到了天堂。"
D.Strings[20858]="我和拉古旅行了好多天。可就在我们认为自己已经饱览一切时，我们再次感到了惊奇。"
D.Strings[20859]="我想继续前进，直到抵达西边那道雄伟长城，看见另一侧的景象为止，可拉古的眼睛却总盯着附近那些巨大的蔬菜。也许在内心深处，他渴望成为一名农夫！"
D.Strings[20860]="那是漫长的旅程，可我最终还是找到了山谷。现在我正与哨兵部队一起努力，破解水池之谜。"
D.Strings[20861]="我们设法赢得了天神的信任，打开了山谷的大门，可我们必须继续向他们表明，我们肩负着和平的使命。"
D.Strings[20862]="看见那么多人被迫离开昆莱山的家园，这令我倍感煎熬。幸好我们为那些寻求庇护的人们找到了避风港。"
D.Strings[20863]="哨兵部队与我交换了在卡桑琅丛林经历的故事。我把自己在赤精寺院里的冒险奇遇告诉了他们。"
D.Strings[20864]="我在这片土地上游历得越久，就越喜欢这群熊猫人。唯爱佳肴美酒，平生与世无争。"
D.Strings[20865]="我在这片土地上旅行时，目睹了许多见闻。我感觉自己长大了一些……也许还略微……睿智了点儿。"
D.Strings[20866]="我相信联盟的未来与潘达利亚息息相关。$B$B在我们抵达这里后，就开始按部就班地采取行动。当神龙之心陷落时，我们就在那里。从某种意义上说，我们也参与促成了游学者周卓预见的实现。$B$B正因如此，在一切重回正途之前，我无法返回暴风城。"
D.Strings[20867]="只要我们学会如何适当地索取，大地就会给予我们许多馈赠。如果你愿意的话，我会教你如何做。"
D.Strings[20868]="你不是本地人。有兴趣了解下潘达利亚的原生植物吗？"
D.Strings[20869]="这片土地上的野兽与你家乡那些截然不同。随我训练，你也许就能学会给它们剥皮的技巧。"
D.Strings[20870]="你得去暴风城，找奥黛丽·伯恩赫普聊聊！城里的任何一名守卫都能为你指路。$b$b在寺院里有传送门，可以将你传送过去。祝你好运！"
D.Strings[20871]="我不会容忍毫无必要的暴力！"
D.Strings[20872]="坡东村欢迎你，还有你的联盟。"
D.Strings[20873]="就快了！$b$b在迷雾酒肆里有冰镇美酒等着我呢。我仿佛已经尝到了……"
D.Strings[20874]="继续走，就快到了！$b$b这是我第三次经过隘口了。真希望能用上熟能生巧这个词！$b$b等你抵达顶部之后，你会找到一家很棒的旅店，叫做“迷雾酒肆”。不过你可得把武器贴身放好。那可是个藏龙卧虎的地方。"
D.Strings[20875]="真是炮火连天啊！现在该收拾残局了。"
D.Strings[20876]="天火号上的那些人都是联盟精英。但有些事情，仍然只有军情七处可以办到。"
D.Strings[20877]="有许多飞行员都被击落在北方，其中一位是我们军情七处的特工。$B$B我们必须帮助他们，但首先得解决这些部落。"
D.Strings[20878]="真是太热闹了！\n\n相信我们的酿酒师明年也会到场竞技吧。"
D.Strings[20879]="我听说指挥官利尔他们找到了安玻！真是个好消息。"
D.Strings[20880]="难民从高原各地涌向滨岸村。我担心野牛人已经攻破了长城！"
D.Strings[20881]="国王肩上的担子很重，可身为父亲，也是肩负重责。我会不惜一切代价寻找儿子。"
D.Strings[20882]="如果部落非要把我们逼到战争的边缘，那就来吧。$B$B在圣光的庇佑下，我会为自己的王国和人民而战。$B$B荣耀属于联盟！"
D.Strings[20883]="熊猫人现在或许还是陌生人，可总有一天，他们会成为最可宝贵的盟友。"
D.Strings[20884]="哇哦……这些联盟可真会使唤人……"
D.Strings[20885]="这里的工作条件太糟糕了！我们已经几个小时没有坐下来喝喝酒了！"
D.Strings[20886]="<他擦了擦额头上的汗水。>$b$b你好啊，$c。你是来帮忙的？"
D.Strings[20887]="<她擦了擦额头上的汗水。>$b$b你好啊，$c。你是来帮忙的？"
D.Strings[20888]="真……渴啊……"
D.Strings[20889]="你是来让我休息的吗？我好像已经连续工作几辈子了！"
D.Strings[20890]="我以为我们只是要造一座房子，而不是堡垒。"
D.Strings[20891]="我从小到大都没这么玩命工作过！我不喜欢这样！"
D.Strings[20892]="这些家伙怎么有这么多武器？"
D.Strings[20893]="你休想打败我！"
D.Strings[20894]="我们当时正在地穴里调查邪煞的腐化情况……然后一切都变得很不对劲。我们的领袖金·铁拳被邪煞控制了，开始大开杀戒。即便是现在，他还在那里加害无辜。"
D.Strings[20895]="你是一位猎人？我能快速帮你解决野兽的难题！"
D.Strings[20896]="你需要别人帮你照看宠物？我保证会多加考虑，争取别吃掉它们。"
D.Strings[20897]="嗨，头儿，情况如何？"
D.Strings[20898]="谢谢你，陌生人。我……从没有过那样的感觉。"
D.Strings[20899]="人生突然变得充满光明。$B$B虽然我还是喜欢睡觉。"
D.Strings[20900]="她找到了？他在抱拳林？$b$b看来我得走一趟了。也许……等我再吃几口……"
D.Strings[20901]="林找到隐秘大师了？那我们的训练可以继续了！$b$b现在就还剩下一件事。肯肯得先帮助那些悲伤的家伙。这里有太多哀苦的人了。"
D.Strings[20902]="真令人难以置信！我以为隐秘大师一定会在荒野里。$b$b你说在抱拳林？我很快就会去找林，然后我们就能继续训练了。至于目前嘛，我已经找到属于自己的冒险了。"
D.Strings[20903]="在这里发生的事情将永远改变这片土地。"
D.Strings[20904]="你是来报名参战的吗？"
D.Strings[20905]="当然可以！我从一大堆农具里找到了我爷爷的铲子。$B$B你可以用它来挖掉生长中的作物，清理出田地来种别的东西。"
D.Strings[20906]="想要挑战顶尖高手吗？$B$B你会像别人一样铩羽而归吗？$B$B验证的办法只有一个。你敢来试试吗，$g先生:女士;？$B$B一个代币就能玩一局……"
D.Strings[20907]="在这里狩猎可带劲儿了。鸟儿在树冠间啁啾，野兽在树下的阴影中咆哮。$b$b而我们则要控制它们的数量。$b$b这是我们身为猎手使命——而且也是一项很棒的运动。"
D.Strings[20908]="欢迎来到丛林，$n。"
D.Strings[20909]="你相信吗？这儿的人居然免费发放食物！这地方真是太棒了！"
D.Strings[20910]="怎么了，$r？"
D.Strings[20911]="我的小队已经准备就绪，$r。$b$b我们已经开发出了一种可以有效打击你的部落敌人的武器。"
D.Strings[20912]="发现这些碎片中能量使我看到了走出困境，重获新生的希望。$B$B噢，而且我也被开除了。"
D.Strings[20913]="远离魔法的这四个月感觉好极了。$B$B有了这些新鲜水果和热气腾腾的茶，谁还在乎魔法的无穷奥秘呢？"
D.Strings[20914]="这些熊猫人酿的烈酒棒极了，可他们都没听说过我最喜欢的那种饮料。$B$B或许我以后可以教教他们……"
D.Strings[20915]="-嗅- 哇！这件旧长袍都有点发臭了。$B$B或许我今晚可以溜到那个池塘里洗个澡……"
D.Strings[20916]="一座通往部落或联盟主城的一次性小型传送门。$B$B它们都是一起被冲下来的，所以我也不知道哪个碎片能够通向哪里。我最多只能分辨出它们是来自于夺日者的传送门，还是银色盟约的传送门。这两边都喜欢在自己的传送门魔法中加入一点自己的特色——典型的恶趣味。$B$B我可以卖给你相应阵营的碎片，而你得在它们稳定下来之后自己分辨它们通向哪里。"
D.Strings[20917]="欢迎欢迎！我是工匠大师欧沃斯巴克，当代侏儒工程学的总工程师。$b$b我们的装配工段正在努力组装各种神奇机械，保护你免遭刀戳、剑劈、爆炸或被放逐出物质领域之害。$b$b好吧，就算出故障，至少不是敌人干的。"
D.Strings[20918]="这座堡垒会比加尔鲁什尔前哨站更难攻破。但它们迟早会被攻破的。部落必将败落。"
D.Strings[20919]="唔，我们或许可以想想办法……$b$b你把国王的指令送来时，我们正要开饭。我想，一些食物或许能让大家多些动力。$b$b还有，我想起来了，我们的尖刺还需要一些木头。你能帮我们去收集一些吗？$b$b然后……嗯……哦，还是算了吧。"
D.Strings[20920]="呃，好吧，如果你坚持的话。$b$b你瞧，$r，传说这一地区埋藏着一件古代魔古神器——一根装饰精美的权杖。传说拥有这件宝物的人将得到部属的衷心爱戴。也可能是敬畏，具体的我忘了。$b$b总之呢，这也不会有什么坏处。你说呢？"
D.Strings[20921]="这是什么，$c？"
D.Strings[20922]="你想用掉多余的委任状？都交给我吧。$b$b你想买点什么？"
D.Strings[20923]="我还以为你就不问了呢！$b$b我们迟早会完成的，可现在也有很多你帮得上忙的地方。$b$b我们侏儒的新陈代谢很快——在我们努力工作时尤其如此。所以食物总是很受欢迎的。$b$b然后是油。这些陷阱非常精巧，不用担心齿轮会被卡住。把你能找到的油都带回来给我们。$b$b除此之外，还要保障我们的安全！$b$b<罗塞向四周看了看，又压低声音说道。>$b$b还——可能还有一件事……"
D.Strings[20924]="<罗塞强忍着眼泪，说道。>$b$b我的……我的日记。它不见了。$b$b里面充满了我老爸的回忆，还有他的大量有关建造天堂都市的完美地点的研究。那可是侏儒工程学的巅峰之作！$b$b总之，里面有一副他的旧图纸或许能在这里派上用处。如果你在这附近的草丛里发现了它，请一定要告诉我。"
D.Strings[20925]="什么？在这儿？现在？我们可是在打仗！$b$b尽管你对侏儒工程学的热情让我非常欣慰，但还是等我们回到铁炉堡的工匠镇再来谈这件事情吧。"
D.Strings[20926]="我们……还有更重要的事情要做，没空来应付你。滚开，废物。"
D.Strings[20927]="我们要守住这座滩头堡垒。我们要给部落建立一处据点，全潘达利亚都将成为下一个塞拉摩。"
D.Strings[20928]="我们必须防止部落侵占潘达利亚……可我们同时还要尽力减少我们造成的伤害。"
D.Strings[20929]="怎么了，我的$g兄弟:姐妹;？你准备好给你的同胞做个榜样了吗？"
D.Strings[20930]="我们开始吧！"
D.Strings[20931]="我马上就来，$g先生:女士;。"
D.Strings[20932]="嘿！想要搭一程吗？骑我们的陆行鸟吧！"
D.Strings[20933]="如果你需要坐骑，别客气，骑上这些小可爱吧！"
D.Strings[20934]="欢迎来到暗月岛！你可以骑着这些可爱的动物前往马戏团。"
D.Strings[20935]="巨型森林陆行鸟！前往暗月马戏团的免费坐骑！"
D.Strings[20936]="*嗯哼*你好啊，旅行者！"
D.Strings[20937]="难道妹子就不能顺顺利利地拿到自己的酒？"
D.Strings[20938]="有时候看着其他人以命相搏真是令我感动！"
D.Strings[20939]="这地方根本没有跳舞的气氛嘛！"
D.Strings[20940]="我能要点喝的吗？"
D.Strings[20941]="你在看什么？我的鞋子？"
D.Strings[20942]="哎呦！今天我真是激动死了。就刚才我从那堆火里炼了八块铁。"
D.Strings[20943]="希尔达把所有的文件都给我了。你知道吗，我们每找到一个神器，我就要填六份表格！我想知道，这些该死的文件到底有什么用！？"
D.Strings[20944]="好像嫌我手头的麻烦事儿还不够多似的，那帮矿洞里的矮人最近迷上了一种叫咔啡的新饮料。$B$B他们一定要让我每天早上给他们带去新鲜的咔啡！$B$B他们知道我应该上哪儿去弄那些咔啡豆吗？行行好吧！"
D.Strings[20945]="我在执行行政管理的时候得穿上漂亮的短裤，但是其他的呢？能来点儿有新意的吗？"
D.Strings[20946]="你好啊，幸运儿。你喜欢看数据？$b$b我对这里进行的每场比赛都进行跟踪。我可以告诉你每个挑战者赢过多少场比赛。$b$b它们可能会派上用场，特别你想要……我是说……通过对一些比赛的预测来获取一些……实际利益。你懂我的意思？"
D.Strings[20947]="|cff0000ff1级：|r\n  血角：$7431w-$7432w\n  萨诺里亚克：$7445w-$7446w\n  斯马什·重蹄：$7471w-$7472w\n  阿卡玛：$7461w-$7462w\n\n|cff0000ff2级：|r\n  帝皮：$7443w-$7444w\n  奇拉瓦克：$7453w-$7454w\n  库拉卡大王：$7479w-$7480w\n  法兰与里东：$7441w-$7442w"
D.Strings[20948]="|cff0000ff3级：|r\n  布拉特：$7435w-$7436w\n  善变的瓦安：$7429w-$7430w\n  伊克西：$7447w-$7448w\n  玛扎伦：$7459w-$7460w\n\n|cff0000ff4级：|r\n  泰森·山德士：$8066w-$8065w\n  噬人蛇：$8074w-$8073w\n  幻术师多米尼卡：$7455w-$7456w\n  肉弹：$7489w-$7490w"
D.Strings[20949]="|cff0000ff5级：|r\n  大型雷震天：$8072w-$8071w\n  米莉·沃特：$7457w-$7458w\n  布鲁斯：$7427w-$7428w\n  麻风侏儒五人组：$7437w-$7438w\n\n|cff0000ff6级：|r\n  普罗波库斯：$7485w-$7486w\n  铁拳医师：$8076w-$8075w\n  乌古洛克斯：$7483w-$7484w\n  伊坎·伊祖：$7467w-$7468w"
D.Strings[20950]="|cff0000ff7级：|r\n  GG工程公司：$7475w-$7476w\n  黑暗召唤师：$7477w-$7478w\n  巴特隆：$7439w-$7440w\n  阿霍鲁：$8078w-$8077w"
D.Strings[20951]="这个屋子在旋转？"
D.Strings[20952]="……*嗝*"
D.Strings[20953]="我的酒洒啦！"
D.Strings[20954]="能请我喝一杯吗？"
D.Strings[20955]="没错，布鲁姆就是我的爱人，我们俩就像是一个豆荚里的两颗豆子，即使他是轻量级选手，我也一样爱他！"
D.Strings[20956]="你有话和我说？没问题，你负责说，我负责喝！"
D.Strings[20957]="你最好别相信我说的任何话。算了，当我没说过。"
D.Strings[20958]="啊，没错，那些关于我的谣言满天飞，可惜都是假的。什么我小时候是暗月马戏团的吉祥物，五岁生日那天杀了六个恶魔——用的还是一把勺子——我最喜欢这段了。但事实上，我只是个普通的金发姑娘。人们就喜欢相信那些有的没的。"
D.Strings[20959]="我喜欢这个地方。在别的地方，那些人总是叫我“暴力孤僻女”。好吧，其实在这儿他们也这么叫我，不过至少他们是当着我的面，并且面带着微笑地叫这个名字。"
D.Strings[20960]="我闻起来像不像火腿？"
D.Strings[20961]="我过敏了，得吃点药。"
D.Strings[20962]="前几天的一个晚上，有人扔了个球过来，还叫我去捡。我照他说的做了，只不过把球和他脑袋一起扔回去了。不用说，他没接着那个球。"
D.Strings[20963]="我总是为血角欢呼。那头愤怒的铲齿鹿看似娇小，却总是能让那些大块头吃尽苦头。"
D.Strings[20964]="城市生活会改变一名德鲁伊。上周我生平第一次使用了公共飞行路线……感觉真是不错啊。"
D.Strings[20965]="大多数德鲁伊都很古板，不过我是个例外，我是个真正的聚会动物。我的笑话说完了。你该笑了。"
D.Strings[20966]="啊，对不起，我不能请你喝酒了。我最近有点小穷，但我相信我会时来运转的。"
D.Strings[20967]="这地方看起来很硬派，但这里的人其实内心里都是软蛋。"
D.Strings[20968]="<卡拉克西瓦·伊克用审视的眼神注视着你。>"
D.Strings[20969]="有些事情必须做好，哪怕它意味着要损失一些其他的东西！"
D.Strings[20970]="噢，是啊，我刚来暴风城。这不是很明显吗？"
D.Strings[20971]="$n，到这儿来！"
D.Strings[20972]="你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。"
D.Strings[20973]="去沙塔斯城东北边的希尔米耶湖畔找老渔夫巴尔洛吧。"
D.Strings[20974]="看到我们雄壮的骑乘海龟了吗？它们乍看之下似乎慢吞吞的——可有经验的骑手却能驾着它们跟上全卡利姆多最迅捷的座狼。可惜，它们只提供给我们最信赖的盟友。"
D.Strings[20975]="你再也找不到比我们的龙龟更好的坐骑伙伴了。它们重心极低，哪怕是在急转弯时，上面的骑手也感觉不到一点震动或推挤。如果你想买的话，就必须向土水派证明你的忠诚。"
D.Strings[20976]="炸药！$b$b干得好，$n。你来得正是时候。"
D.Strings[20977]="在一个从不锁门的世界里，锁匠要怎么谋生呢？"
D.Strings[20978]="你相信吗？当我着手研究掩盖体味的魔法时，还受过嘲笑。大法师们都觉得我的研究不切实际，而且浪费时间。$b$b看看，现在站在魔暴龙的上风口笑的人又是谁？哈！"
D.Strings[20979]="真可惜，我只能掩盖我们自己的气味，却没办法驱散赞达拉巨魔和他们那些畜生身上的恶臭。"
D.Strings[20980]="我向来不喜欢野外工作，尤其是牵涉到一大群巨魔的工作。"
D.Strings[20981]="赞达拉是个骄傲的种族。他们的骄傲迟早会毁了他们。$b$b就算是最强大的敌人也会有弱点，我们只需要找出这个弱点就行了。"
D.Strings[20982]="一片全新的土地正在遭受邪恶恐怖的侵蚀。一片全新的土地在等着我们去拯救。"
D.Strings[20983]="有人嘲笑我对野兽的关注。而我要嘲笑他们的冷漠。"
D.Strings[20984]="我们可以从这些赞达拉巨魔身上学到很多东西，尤其是去做他们不做的那些事。"
D.Strings[20985]="彻底解决这些魔古族的时候到了。"
D.Strings[20986]="我来解决这里的塌方，然后我们就从后面溜进去。你准备好就告诉我一声。"
D.Strings[20987]="我对魔古族的文化和历史相当感兴趣。我这可不是一时心血来潮。"
D.Strings[20988]="大法师茉德拉采用了一种直截了当的策略——武力击败魔古族。我相信随着进一步的研究，我们或许就能发现魔古族的弱点。"
D.Strings[20989]="我决定要写一本书，就叫《魔古族魔法之谜》。听上去很厉害吧？"
D.Strings[20990]="我们在这里的人数远逊于敌人，但只要切实贯彻预定的战术，我相信我们是可以成功的。"
D.Strings[20991]="我们的战术很有效。胜利的果实正在向我们招手，我们决不能在这个时候动摇。"
D.Strings[20992]="很高兴再次见到你，冒险者。你做好出发的准备了吗？"
D.Strings[20993]="我的货物只卖给那些在战场上证明过自己的人。在我把它们托付给你之前，你得先证明自己比那些部落渣滓强。"
D.Strings[20994]="我的父母曾说过，在大分裂之前，在离我们家乡很遥远的南方居住着一个毛茸茸的奇怪种族。我一直以为他们说的是一种比较聪明的熊怪。$b$b现在我知道自己错得有多离谱了。真希望他们能活到今天，亲眼看看这一切。"
D.Strings[20995]="这片大陆是不会轻易交出自己的秘密的。"
D.Strings[20996]="我们还有很多东西要学。"
D.Strings[20997]="熊猫人热爱生活。在这个战火纷飞的年代，了解我们为何而战更能振奋人心。"
D.Strings[20998]="来喝一杯吧。这位王子正在教我玩一种当地的游戏。"
D.Strings[20999]="魔古族、螳螂妖、蜥蜴人……他们不仅是需要我们击败的敌人，更是有待解开的谜团！"
D.Strings[21000]="一旦你结识了潘达利亚的各个阵营，大量产品订单就会蜂拥而至。"
D.Strings[21001]="这就是“黑暗中的匕首”的故事！$B$B正是在这里，三位勇敢的冒险者阻止了一场精心策划的暗杀，救了部落的暗矛巨魔首领沃金一命。"
D.Strings[21002]="啊，因为你将是这个故事中的一名演员！$B$B比起从落满灰尘的卷轴上阅读历史，这样会更有趣，你说呢？$B$B现在，快出发吧，好好学习！"
D.Strings[21003]="等待装货与递送的空箱子。"
D.Strings[21004]="我相信，我们一定可以利用这里的雷霆翼龙狠狠打击雷神。"
D.Strings[21005]="虽然我们的目标是消灭魔古族，但也不能忽略我们的侧翼。$b$b虽然部落和蜥蜴人都在与我们一同攻击魔古族，但这两者随时都有可能对我们倒戈相向。"
D.Strings[21006]="蜥蜴人很卑劣，但他们或许还有用处。$b$b如果我们能煽动他们反抗魔古族，或许就能把他们的注意力从我们的人身上移开。"
D.Strings[21007]="“蜥蜴人引起了我的兴趣。$b$b事实上，由于我太过热衷，某些人甚至开始称我为‘邪刃’斯蒂芬。”"
D.Strings[21008]="我是来清理邪刃蜥蜴人留下的烂摊子的。$b$b虽然我从未见过它们这样的烂摊子，但其中肯定有相似之处。"
D.Strings[21009]="让我们快点搞定这件事，好早点回家去。"
D.Strings[21010]="打得好，$r。"
D.Strings[21011]="不能再浪费时间了。在我们说话的时候，部落正在雷神岛上不停推进呢！"
D.Strings[21012]="我从没想过加入阡陌客后会有这么多工作。"
D.Strings[21013]="日歌农场最近怎么样，$n？"
D.Strings[21014]="我已经快要忙死了，但汇风岭正日益繁荣。"
D.Strings[21015]="自从锦绣谷的大门开启，我们就在源源不断地向北方供应蔬菜。"
D.Strings[21016]="你在卡桑琅丛林的那群朋友胃口可真好，总是不断地向我们采购新鲜农产品。"
D.Strings[21017]="我正在和种子保管人辛辛一起研究更高效的耕作、采集和储存方案。阡陌客的目标就是提供美味、新鲜、高品质的农产品！"
D.Strings[21018]="雷神归来才没多久，就在麾下聚集起了这么多盟友，这可真叫人沮丧。我们得趁他不在时多消灭一些。"
D.Strings[21019]="这座岛上到处都是敌人，新老都有。如果没有流血牺牲的觉悟，我们是无法在这里立足的。"
D.Strings[21020]="我的船经过一番斗争才得以靠上这片海岸。我一定会让他们为她船体上的每一条伤疤付出代价的。"
D.Strings[21021]="这座岛蕴藏着巨大的魔力。我还不清楚它是掌握在雷电之王，还是我们的夺日者老朋友手里。$B$B但我们迟早会找到答案的。"
D.Strings[21022]="想听个小秘密吗？关于今天该去哪儿钓鱼的……."
D.Strings[21023]="想听听关于该去哪儿钓鱼的秘密吗？"
D.Strings[21024]="恐惧废土的古克罗克浅滩在迎来大渔汛之后，日益频繁的鱼类活动有时会搅松沿岸的海藻。$b $b大虾、八爪鱼之类的东西就会被这些海藻缠住。我敢打赌，如果你去那里钓钓鱼，肯定能收获许多螳螂虾。 $b $b如果你需要我帮忙寻找渔点，就告诉我一声。"
D.Strings[21025]="当然了，朋友。我可以帮你把螳螂虾的位置标在地图上。去恐惧废土的西北角看看吧，那个地方叫古克罗克浅滩。"
D.Strings[21026]="今天，昆莱山滨岸村的锦鱼人和水流沟通了一番，发现水中充满了煞能。$b $b你或许已经知道了，刺皮鱼是一种极具攻击性的鱼类。如果再给它们加点煞能，那你就能见识到什么叫疯狂了！ $b $b如果你能抓住那些愤怒的野兽，或许就能帮忙恢复当地脆弱的生态平衡……更不用说你还能抓到大量刺皮鱼。"
D.Strings[21027]="刺皮鱼就在地图的这个位置。昆莱山滨岸村的海滩上。你找天色最阴沉黑暗的地方就对了。"
D.Strings[21028]="国王希望安度因王子留在锦绣谷直至康复。但王子坚持要四处走走，并与人们多聊聊。当王子想要违抗国王时，我们又能怎么办呢？$b$b最好还是跟紧他，免得他惹上什么麻烦。"
D.Strings[21029]="<牛头人圣骑士上下打量着你，好像在猜测你的意图。>$b$b我无意与你为敌，$c。人类王子和我在白虎寺见过，他常常来找我聊我们的大酋长贝恩，并讨论战争与和平那些事。$b$b<圣骑士和王子的卫士不断用疑虑的眼神互相打量着。>"
D.Strings[21030]="拉希奥自称是最后一条活着的黑龙。你相信吗？$b$b他对世界的看法非常古怪。我不知道他是否珍视人类的生命，还是把它看做消耗品！但我真的很喜欢跟他聊天。"
D.Strings[21031]="噢，这个？<安度因指了指他的拐杖。>$b$b加尔鲁什·地狱咆哮试图用一件古老的魔古神器召唤并控制煞能。我设法阻止了他，但我好像不该亲自去对付他。他以为我死了，让我就那么埋在那个失败计划的废墟下。我发誓，他把我全身所有的骨头都打碎了。$b$b熊猫人织雾者让我重新站了起来，但我恐怕还需要一些时间才能独立行走。"
D.Strings[21032]="你知道我们和黑龙军团的往事，对吧？我不会那么快忘记普瑞斯托女士——奥妮克希亚——对我的家族所做的一切。或许这就是我来找拉希奥的原因。$b$b<安度因看了看桌子对面那位不同寻常的同伴。>$b$b可是……他和其他黑龙不一样，不是吗？他非常坦诚，却又总在隐瞒着什么。和我预想中完全不同。"
D.Strings[21033]="只要你赢得了黑王子殿下的尊重，那你也就赢得了我的尊重。再去完成一些他给你的任务吧。$b$b在此之前，请你先走开。我没有什么可卖给你的。"
D.Strings[21034]="在酒肆里找到我的黑爪军需官。他可以帮你找回我先前给你的任何奖励……当然是收费的。显然你已经注意到了，我用的材料可是一点儿也不便宜。"
D.Strings[21035]="你成功了！太好了。现在我们可以开始了。"
D.Strings[21036]="我很乐意帮忙！"
D.Strings[21037]="我可以一直数到“九——十”哦。听好了！$B$B<米莉开始掰手指头和脚趾头。>$B$B一，二，三，五，六，嗯……七，八，九——十！$B$B等等，我漏了一个……"
D.Strings[21038]="别把种子塞进鼻子了。爸爸会很生气的！"
D.Strings[21039]="我喜欢海龟。"
D.Strings[21040]="数数最好玩了！"
D.Strings[21041]="我们随时都能发动突击，只是需要一把钥匙。你找到钥匙了吗？"
D.Strings[21042]="你做好再试一次的准备了吗？"
D.Strings[21043]="这些赞达拉巨魔不可小觑。他们和我见过的任何巨魔都不一样。"
D.Strings[21044]="你做好帮我开启雷霆熔炉的准备了吗？这可能有点危险。"
D.Strings[21045]="<一本厚重的书籍，封面非常陈旧，夹缝中还有灰尘。看来老愚延续了传统，一直在这本日志上记录日歌农场的历史。日志翻到他的最后一条记录上：这是一条写给你的信息！>$B$B“感谢你让我祖传的土地恢复了昔日的荣光。我又更重要的事情要做了；现在轮到你来书写这些书页了。”"
D.Strings[21046]="你引起了我的注意。呃，没事了。"
D.Strings[21047]="我这身行头全是靠揍人换回来的。"
D.Strings[21048]="没错，我打拳的日子已经过去了。现在，我全靠美酒和三流美女打发日子了。"
D.Strings[21049]="这上面的视线确实更好，而且还不会被血溅到。"
D.Strings[21050]="我总会为机器人们欢呼。"
D.Strings[21051]="你刚才说话了吗？抱歉，每次有人被干掉时，我总会兴奋过头，从而忘了听别人说话。"
D.Strings[21052]="不，不，我不是来打拳的。我主要是来给布鲁斯捧场的。"
D.Strings[21053]="啊，没错，我还记得我第一次跟黑暗召唤师战斗的情况。然后是第二次……第三次……"
D.Strings[21054]="你问我有什么建议？永远不要低估你的对手，无论他们有多瘦小，多笨拙，或是多可爱。"
D.Strings[21055]="不管是什么邪恶力量引来了这场风暴，快去阻止它吧。这样，熔炉卫士就能攻上山头，并扫清那里的霜鬃和赞达拉巨魔。$B$B去找我的巡山人，或者任何被巨魔俘虏的人，他们能为你指路。"
D.Strings[21056]="请想办法阻止这场人为的风暴，勇士，并尽力拯救俘虏。$B$B祝你好运。"
D.Strings[21057]="这种令人口水直流的美酒散发着一股令人迷醉的香气。"
D.Strings[21058]="我看见你了！"
D.Strings[21059]="那是什么？"
D.Strings[21060]="我没想到会有这么多军队……"
D.Strings[21061]="我以前也卷入过不少麻烦，但这也太荒唐了！"
D.Strings[21062]="我们只要专心执行任务就好，肯定能够全身而退的。"
D.Strings[21063]="这些箱子上有库卡隆的印记。山洞里摆满了各种武器和其他战略物资。从这些东西来看，加尔鲁什正在策划一场入侵。"
D.Strings[21064]="山洞里整齐地码放着始祖龙蛋。周围散落着许多刚刚孵化的蛋。有了这么多始祖龙，加尔鲁什的入侵足以威胁到任何地方。"
D.Strings[21065]="你最近有找到什么稀有卡牌吗？把它们带给我，我可以把它们加入我的藏品里去。"
D.Strings[21066]="我想买一张挑战卡牌。"
D.Strings[21067]="很高兴见到你，我的朋友。最近发生了太多事情，让我这样的游学者都觉得目不暇接了。我已经通过洄梦仙酒看到了许多事件，但我们还需要像你这样的英雄来帮忙书写新的历史篇章。"
D.Strings[21068]="|cff6600aa绝版挑战者：|r\n  地下城主韦沙斯：$7433w-$7434w\n  压路者：$7451w-$7452w\n  莉安娜·地风：$7487w-$7488w\n  迪肯：$7469w-$7470w\n  弗琼：$7463w-$7464w\n  T440双模机器人：$8068w-$8067w\n  海克索斯：$8064w-$8063w\n  硬煤：$8070w-$8069w\n  史诗逆天鲨：$7385w-$7386w\n  干涉者：$7417w-$7418w\n  米尔豪斯·法力风暴：$7401w-$7402w\n  兹恩沙尔：$7409w-$7410w"
D.Strings[21069]="|cff6600aa特殊挑战者：|r\n  老爹土笛子：$8080w-$8079w\n  布姆布姆大师：$8084w-$8083w\n  泰塔尔：$8086w-$8085w\n  锋齿：$8088w-$8087w\n  斯普拉特：$8090w-$8089w\n  帝皮和杜皮：$8094w-$8093w\n  巨熊与淑女：$8082w-$8081w\n  布林顿3000：$8098w-$8097w\n  猜拳手：$8096w-$8095w\n  机甲布鲁斯：$8092w-$8091w\n  明格斯·迪格斯：$8100w-$8099w\n  盲眼英雄：$8102w-$8101w"
D.Strings[21070]="嘿嘿嘿！你想快速前往贫瘠之地吗？"
D.Strings[21071]="你要去其他地方吗？如果那个“其他地方”是棘齿城，那我马上就能给你开辟一条快速通道！"
D.Strings[21072]="顾客满意度百分之百！今天就来试试跳闸旅行社的服务吧！"
D.Strings[21073]="我的高新传送器可以将你直接送往北贫瘠之地。想试试吗？"
D.Strings[21074]="当时我们正在这里对付这堵墙，然后……额，我不记得了。那么，你是谁？轮滑去哪儿了？"
D.Strings[21075]="你休想用那套猫皮伪装骗过老岑塔布拉。我会记住你的，$r。"
D.Strings[21076]="<沃金的临时义军营地里散发着令人难以忍受的恶臭。巨魔首领示意你先开口，而他的护卫们则警惕地盯着你。>"
D.Strings[21077]="<沃金的脸愤怒地扭曲了起来。>$b$b你不明白。部落在你们眼里是什么？嗯？一群病夫？怪胎？叛徒？魔崽子？野兽？我知道你们是怎么说我们的。$b$b我来告诉你们部落是什么。部落是我和萨尔一手建立起来的。它是一个大家庭。当全世界都试图消灭我们时，这个家庭向我们伸出了援手。$b$b而地狱咆哮，他不懂这个家庭的意义。所以他也得不到家人的支持。"
D.Strings[21078]="对他来说，部落的全部意义便是兽人，以及如何壮大兽人的力量。他就像是刚刚穿过黑暗之门。任何挡他路的人，任何与他意见相左的人，都得闭嘴。$b$b<沃金用只有三根手指的手摸了摸身上的刀疤。>$b$b他就像一条疯狗。噢，没错，我是与地狱咆哮并肩战斗过。但要让他来掌管一切？你简直是在自找麻烦。他热衷于搞自己的小团体，发动他自己的战争，将我们这些老兄弟丢在一边……他觉得自己用不着任何人帮忙。但是，他错了。$b$b他会明白：一个人永远无法与这个大家庭对抗。"
D.Strings[21079]="<沃金笑了起来，带着恶臭的灼热呼吸直往你的鼻孔里钻。>$b$b噢，你有其他方案？我这儿正好也有一个备用方案。我就让你们自己去围攻奥格瑞玛。看看你们能打成什么样。等到城里堆满了尸体时，我再派出暗影猎手攻进去，干掉剩下的人，包括库卡隆和联盟，然后把你们的死者交给希尔瓦娜斯。哼！这么一来，我还可以保住许多暗矛部族同胞的性命。$B$B嗯？你不喜欢这个方案？那我们还是来谈谈第一个方案吧。我们合作。$b$b这并不需要我们喜欢彼此。"
D.Strings[21080]="很多年以前，我帮忙在这片沙漠上建起了部落。唉……时代真的不同了。"
D.Strings[21081]="$n！真没想到，居然能在离潘达利亚的葱郁森林这么远的地方见到你。$b$b许多年前，当我第一次乘船离开迷踪岛时，这片怪石嶙峋的海滩是我最先造访的几个地方之一。啊！这里的空气还是这个味儿！$b$b但时代不同了。那时，我帮助萨尔、沃金、雷克萨和洛坎为奥格瑞玛打下了基石。今天，我差点就认不出这地方了。$b$b<陈的脸沉了下来。>$b$B太多毫无意义的流血牺牲了。我真不明白。潘达利亚给我们的教训还不够吗？"
D.Strings[21082]="国王陛下不想让加尔鲁什继续他那疯狂的战役了。它已经吞噬了太多无辜的生命。$b$b我们是来寻找奥格瑞玛的防线弱点的，那种能够为联盟部队所用的弱点。$b$b不幸的是，加尔鲁什显然也没闲着。他已经加快了库卡隆的征兵速度，并将他们变成了彻头彻尾的战争机器。"
D.Strings[21083]="他们原本是一支由精锐兽人组成的卫队，负责保护酋长的安全并执行他的命令。$b$b而现在，他们变成了一支由训练有素的屠夫组成的军队，加尔鲁什的私人军队。"
D.Strings[21084]="但愿这只隐身小鸡不会出什么岔子。她最近不太对劲。"
D.Strings[21085]="我好像看见一些带着镣铐的巨魔被押走了。兽人为什么要给巨魔戴镣铐，还要押着他们走呢？"
D.Strings[21086]="藏身于敌军腹地，只靠这只隐身小鸡来保护我们。这已经变成我最新的日常工作了！"
D.Strings[21087]="部落带回来一只猢狲？！他们在潘达利亚还没有受够那些家伙吗？"
D.Strings[21088]="我以前从没在一个地方见过那么多库卡隆！$b$b那些兽人总是又暴躁又愤怒。他们肯定扩大了征兵规模。"
D.Strings[21089]="老靴子？！它可是我的杰作。自从袜子死后，愿它安息，我需要一个更加耐用的小伙伴。$b$b都是安玻想出来要用它来执行这个任务的，所以你千万别把它炸坏了！"
D.Strings[21090]="<沃金发现自己的机会正在溜走。他举起了手。>$b$b等等，$r！奥格瑞玛是一座坚城。我的人，我们不可能自己啃下这块硬骨头。我们又能在这里坚持多久呢？几天？几周？沃金可说不准。$b$b只要你们能源源不断地提供补给，我保证，我们一定能干掉更多的库卡隆，而且是在你们的部队登陆之前！你们的人甚至都不用流血牺牲！这应该能值几箱肉吧？"
D.Strings[21091]="去找莱恩·法尔娜。他可以教你任何的专业技能。"
D.Strings[21092]="你应该去找温比尔·任务栏，他就在南边的大路旁。\n\n他可以帮你学习任何感兴趣的专业技能！"
D.Strings[21093]="去找伊兰尼斯·影花吧。\n\n你可以在旅店的主层找到他。"
D.Strings[21094]="去鹰翼广场的旅店找塞伦吧。\n\n你可以在楼上的厨房附近找到他。"
D.Strings[21095]="瓦伦可以帮助你。\n\n你可以在碧蓝岗哨的南边找到他。"
D.Strings[21096]="能再给我一头赛羊吗？"
D.Strings[21097]="当你靠近时，雕像发出了柔和的嗡鸣声。"
D.Strings[21098]="开启基础坦克（青铜）试炼"
D.Strings[21099]="你好啊，$n。我是奥利安娜，我负责救治重伤的宠物，并为参赛者解释规则。\n\n你不能在比武大会期间治疗或复活宠物。如果你没有能够出战的宠物了，可以离开然后再次进入比武大会。\n\n如果你输给某个挑战者，就需要与其重新比赛。"
D.Strings[21100]="聪明的猢狲说了：发光的不都是金子。但是金子总会发光。"
D.Strings[21101]="聪明的猢狲说了：财富就在你的内心深处，或者在这些箱子中。"
D.Strings[21102]="聪明的猢狲说了：外表充满了欺骗性，尤其是当你的眼神不好时。"
D.Strings[21103]="聪明的猢狲说了：有多大胃口吃多少东西，除非附近有其他饥饿的猢狲。"
D.Strings[21104]="聪明的猢狲说了：行动比言语更加振聋发聩，除非那家伙在大喊大叫。"
D.Strings[21105]="聪明的猢狲说了：如果你第一次失败了，就找别人来帮你做。"
D.Strings[21106]="聪明的猢狲说了：今日事今日毕……噢，算了，后半句我下次再告诉你吧。"
D.Strings[21107]="欢迎，旅行者！我这里有来自世界各地的宝物。$B$B想来试试手气吗？几个永恒铸币就能换一把钥匙了！"
D.Strings[21108]="嗨，$N！很高兴再次见到你。大家还在议论你上次赢得比武大会的事呢……我没能从头看到尾，因为有太多伤员需要我来治疗了。但不用担心，他们现在都好了！"
D.Strings[21109]="我不眠不休的监视将傲慢的腐蚀困锁于此。要想亲身面对这种腐蚀，你们就必须在熊熊燃烧的光明中净化自己。这个过程可不容易。\n\n你们准备好了吗？"
D.Strings[21110]="开启基础治疗（青铜）试炼"
D.Strings[21111]="我们做出了这么多牺牲，可战斗依然久拖不决。这些战斗足以消磨我的意志……"
D.Strings[21112]="坚强点，$c。珍惜你所爱的人。我们永远不知道自己能在这个世界上停留多久。"
D.Strings[21113]="进入试炼场。"
D.Strings[21114]="想要兑换你的战斗石吗？"
D.Strings[21115]="我的方法是绝不会失败的！"
D.Strings[21116]="很多人都质疑我的方法，但没人能否认我的成果。"
D.Strings[21117]="相信我吧，$r。酷刑能撬开所有人的嘴巴。"
D.Strings[21118]="我这活儿可不是人人都能干的。$b$b<折磨者赛普磨着他的小刀。>$b$b天赋，明白吗？噢，我真是个天才。"
D.Strings[21119]="那个巨魔似乎并不打算开口。你想拿他来练练手吗，$c？"
D.Strings[21120]="等这场战争结束后，我打算回杜隆塔尔去。$b$b在山上造一座小房子，或许还带一个小花园。$b$b嗯，听起来不错。"
D.Strings[21121]="等一会儿，我马上就让那个巨魔尖叫到半夜。"
D.Strings[21122]="锦绣谷发生了一些可怕的事，但真正的悲剧在于，那里已经完全不适合钓鱼了。所有的珍宝斑马鱼！都完了！$b $b但你很走运，我听说东部海岸附近的一座岛上还能钓到珍宝斑马鱼。如果传言属实的话，你可以在那儿找到满满一湖的鱼。"
D.Strings[21123]="如果传言属实的话，你应该可以在这里找到珍宝斑马鱼。$b$b<班宏在你的地图上做了一个标记。>$b$b"
D.Strings[21124]="我们来战斗吧！"
D.Strings[21125]="看看这儿！一个与世隔绝的、完整的生态圈，与已知的所有时间流都毫无牵连！$b$b很少有东西能让我这样的人感到吃惊。我一定要好好珍惜在这里度过的每一秒钟。"
D.Strings[21126]="我们已经站在了战争的悬崖边上。当你的部队准备好之后，就给我发信号吧，然后我就会下达进攻的指令。"
D.Strings[21127]="一台来历不明的大型设备在你面前嗡鸣。它的一侧刻着一行小字：\n\n|TInterface\\Icons\\inv_gizmo_02:20|t |cFFDD2222[地精泰坦控制模块]|r\n\n它似乎受到了声音识别模块的保护。"
D.Strings[21128]="你不觉得吗？这地方很神奇！"
D.Strings[21129]="烧吧，宝贝，烧吧！"
D.Strings[21130]="这里真是热火朝天啊！"
D.Strings[21131]="谁说火焰不美丽？"
D.Strings[21132]="我的守望永不停歇，但我很珍惜这个短暂的假期。"
D.Strings[21133]="一场精彩的战斗总能令我肾上腺素飙升。"
D.Strings[21134]="这里聚集了来自各行各业的人们。今天，我们都是观众，来此观看这些史诗般的战斗。"
D.Strings[21135]="干嘛这么吃惊，$n？$b$b我早就跟你说了。潘达利亚是一片充满未解之谜的神奇土地。"
D.Strings[21136]="挑战至尊天神将考验你的决心、技巧并唤醒你的崇高精神。$B$B你准备好了吗？"
D.Strings[21137]="可惜没有酿酒比赛。我从没见过这么多酒仙聚在一起！"
D.Strings[21138]="今天，就让我们看看谁能打败至尊天神，谁又会被打得一败涂地吧。"
D.Strings[21139]="嗯？你想跟至尊天神打架吗，蠢蛋？$B$B卡哈卡哈很乐意看热闹，但不会出手帮你。"
D.Strings[21140]="该死的锦鱼人居然也来了！$B$B$n愿意帮卡哈卡哈干掉几个锦鱼人吗？"
D.Strings[21141]="愿意给卡哈卡哈一把亮闪闪的武器吗？$B$B想想看，要是卡哈卡哈有了这么一把武器，能干出多少大事啊！"
D.Strings[21142]="当我们在地狱咆哮之拳上第一次见到潘达利亚时，谁能想到这里还会有这种地方的存在？"
D.Strings[21143]="两个字：轰隆！$B$B我想说的是，像这样的盛会，如果能再来一两桶炸药就更好了。"
D.Strings[21144]="我正在研究一项能把你的理智炸飞的新发明！$B$B或许还能让你的其他肢体一起瘫痪。"
D.Strings[21145]="让我们看一场精彩的战斗吧！"
D.Strings[21146]="这真的很刺激，不是吗？"
D.Strings[21147]="能在与煞魔斗争之余稍稍休息一下，这种感觉可真不错。"
D.Strings[21148]="非离最好小心摆弄她那些焰火。"
D.Strings[21149]="这地方可真是安宁祥和。它完全没有被肆虐大陆的战火所波及。"
D.Strings[21150]="忠于自我，你的决心就会变成强大的冰川。"
D.Strings[21151]="一只螳螂妖试图跟踪我到这里。$B$B他的下场可不太好。"
D.Strings[21152]="这座岛上一定会有很多奇遇的！"
D.Strings[21153]="我看出来了，这里会有很多乐趣的！"
D.Strings[21154]="放松点。你还有朋友呢。"
D.Strings[21155]="保持警惕，但也别忘了享受生活中的小乐趣。美食，好友，还有美酒！"
D.Strings[21156]="我们可以通过观摩他人的战斗学到很多东西。"
D.Strings[21157]="能见到雪怒和其他至尊天神真是我的荣幸。"
D.Strings[21158]="我觉得自己根本不可能去挑战任何一位至尊天神。"
D.Strings[21159]="听说这座岛屿不受时光的侵蚀。在这里肯定能发现许多神奇的东西！"
D.Strings[21160]="我从没见过这样的水。它会说话，可我听不懂它说的是什么。"
D.Strings[21161]="好好打，为你的同胞争光吧！"
D.Strings[21162]="你有出色的战斗技巧，也有坚定的战斗意志。但愿有一天我也能像你一样。"
D.Strings[21163]="我都想自己下场试试了……但现在还不行。"
D.Strings[21164]="在与魔古族战斗过之后，其他敌人又能比他们强大多少呢？"
D.Strings[21165]="至尊天神的子民们，天神比武大会将考验你们在宠物战斗中的领导能力，以及你们能否做个成功的领袖。"
D.Strings[21166]="我很仰慕赤精。伟大的朱鹤或许能传授一些智慧给我。"
D.Strings[21167]="大家都在努力战斗。大家都在开怀畅饮。大家都很开心！"
D.Strings[21168]="你也该喝一杯！干！祝你开心！"
D.Strings[21169]="这里的时间是停滞的，这样真好。肯肯希望比试永远不要结束！"
D.Strings[21170]="我很高兴看到砮皂依然健壮。"
D.Strings[21171]="在更多冲突降临之前，我们一定要好好享受这段团聚的时光。"
D.Strings[21172]="我好久没这么放松过了！"
D.Strings[21173]="我不是战士。我只是个种菜养牦牛的。$B$B你去打，我就看看。"
D.Strings[21174]="你何不表现一番，让我开开眼界呢？"
D.Strings[21175]="我正考虑在这里种点庄稼。$B$B你能想象，如果我在这里种下一颗谜之种，会发生什么事吗？"
D.Strings[21176]="只有经过充分训练的人才能参加比武大会。\n\n当你拥有15只满级宠物时，你才能获得参赛资格。"
D.Strings[21177]="这些小鸡现在或许还很小，但它们很快就会长大的！"
D.Strings[21178]="少打架，多种田。我跟你说，这才是生活。$B$B当然，如果你想打架，我也不妨来看看。"
D.Strings[21179]="哼。想当年，我们可得翻过一座雪山才能觐见至尊天神的。"
D.Strings[21180]="我很乐意与你并肩战斗，但你并没有向我求助。"
D.Strings[21181]="我很期待能看到一位真正的$c全部的潜力。"
D.Strings[21182]="对我而言，竞技场有点太吵了，但能看到这么精彩的比赛还是值得的。"
D.Strings[21183]="你喜欢我今天这身打扮吗？"
D.Strings[21184]="祝你能在这里交上好运！"
D.Strings[21185]="真不敢相信，农夫老愚和农夫老方都来了！$B$B这叫我一个姑娘家该怎么办啊？"
D.Strings[21186]="让我们坐下来喝杯冰镇啤酒，好好聊聊吧？"
D.Strings[21187]="许多阡陌客都赶来看比赛了。再没有比精彩的战斗和冰镇啤酒更棒的消遣了！"
D.Strings[21188]="好好打，但可别忘了去照料你的农场！"
D.Strings[21189]="赛场上的激烈战斗可以帮助你保持状态，迎接未来的挑战。"
D.Strings[21190]="这座岛上隐藏着许多秘密。你得把它们找出来。"
D.Strings[21191]="见到像你这么强大的$r总是一件令人高兴的事。"
D.Strings[21192]="我显然已经离家万里了！"
D.Strings[21193]="我很少打架，但这真的很刺激！"
D.Strings[21194]="哇，打得好！"
D.Strings[21195]="这会是一个很精彩的故事的，你不觉得吗？"
D.Strings[21196]="我一早上都在跟至尊天神们搏斗！"
D.Strings[21197]="发生了那么多的事！这难道不刺激吗？"
D.Strings[21198]="哇！你真是狠狠教训了他们一顿啊！"
D.Strings[21199]="最近怎么样啊，老板？跟蒙蒙来喝一杯吧！"
D.Strings[21200]="蒙蒙尝过老酒湾的啤酒。太难喝了！"
D.Strings[21201]="反正我现在不用种田，这真是个消遣的好去处！"
D.Strings[21202]="在战斗之余，别忘了好好休息。一个好$c应该懂得劳逸结合。"
D.Strings[21203]="蒙蒙不够耐心，没法独立工作。$B$B我正试图帮他放慢节奏。"
D.Strings[21204]="噢！你好啊！我……呃……没想到能在这儿遇见你！$B$B<艾拉突然回头向竞技场看去。>"
D.Strings[21205]="那些粉色的仙鹤真漂亮！$B$B我是说……如果你想知道的话……"
D.Strings[21206]="噢，我得去看看我的猫咪们了。但愿它们一切都好！"
D.Strings[21207]="这地方真古怪，到处都充斥着强大的魔力。"
D.Strings[21208]="我不敢在这里开传送门。这么做的后果会……很有趣的。"
D.Strings[21209]="我听说岛上藏着许多宝藏。"
D.Strings[21210]="我永远不会忘记我父亲的牺牲。"
D.Strings[21211]="要说我不珍惜这个放松的机会，那是假的。"
D.Strings[21212]="这些比赛让我想起了自己接受新兵训练时的日子。"
D.Strings[21213]="这里没有战争的空间。"
D.Strings[21214]="为荣耀而战。"
D.Strings[21215]="战士的责任是永无止尽的。"
D.Strings[21216]="你听说了吗？迪娜·泥爪也来了。$B$B不知道农夫老愚和农夫老方发现没有……"
D.Strings[21217]="总算不用打理市集了，真是太轻松了。"
D.Strings[21218]="我真该带一辆餐车来的。在这里绝对能赚大钱！"
D.Strings[21219]="你的力量将这片土地从恒古的黑暗中解救了出来。我很荣幸能亲眼见证你的事迹，勇士。"
D.Strings[21220]="这棵树就是希望的象征。但愿你所做的一切能让这片土地痊愈，并更加繁荣昌盛。"
D.Strings[21221]="你总能打动我，$n。"
D.Strings[21222]="要想治愈这片土地和我们自己的伤口，还有许多事情要做。多亏了你的帮助，我们再也不用担心亚煞极的七大吐息了。$b$b同时，煞魔也不再活动了，你的美名将与末代皇帝一样流芳百世。"
D.Strings[21223]="来喝一杯吧，$c？"
D.Strings[21224]="带着决心去战斗吧，朋友。"
D.Strings[21225]="能和至尊天神战斗真是叫人羡慕。"
D.Strings[21226]="和老朋友一起渡过的时光总是宝贵的。"
D.Strings[21227]="这座岛上藏着许多未解之谜。"
D.Strings[21228]="我们今天可走运了。好多人都来托运东西了。"
D.Strings[21229]="你很有冠军像哦，$r。"
D.Strings[21230]="忙碌的土地精才是好土地精！"
D.Strings[21231]="愿你的美酒醇香，心志坚定。"
D.Strings[21232]="你的故事还将继续，朋友。$B$B这个故事很有看头。"
D.Strings[21233]="你战斗起来就像个真正的$r。"
D.Strings[21234]="再也没有比环游世界，谱写你的故事更有趣的工作了。$B$B这就是云游者之道。"
D.Strings[21235]="这种场合怎么能少了美酒呢！"
D.Strings[21236]="想跟我一起去岛上探险吗？"
D.Strings[21237]="你看到那些烟火了吗？真漂亮！"
D.Strings[21238]="至尊天神都好高大啊！"
D.Strings[21239]="哇，你肯定是个$c吧？$B$B$C最厉害了！"
D.Strings[21240]="战斗和啤酒。再也没有比这里更棒的地方了。"
D.Strings[21241]="下次我请！"
D.Strings[21242]="今天是个好日子。"
D.Strings[21243]="我学到了很多酿酒知识。我还没能酿出自己的酒，但快了！"
D.Strings[21244]="要来杯好酒吗？"
D.Strings[21245]="你看来需要喝一杯。"
D.Strings[21246]="没有好酒的战斗不是好战斗！"
D.Strings[21247]="再没有比美酒更好的东西了！"
D.Strings[21248]="再来一杯怎么样？"
D.Strings[21249]="为了私利而去干扰时间流的家伙通常都很危险。\n\n所以我才加入了守望者的队伍，这是时光旅行者中的防卫部队。\n\n我们会在观察者和编织者执行任务时保护他们。"
D.Strings[21250]="编织者都是精通时间法术的魔法师，最擅长编织时间。\n\n在时光旅行者中，只有我们能修复受损的时间流，开启时光传送门，并执行其他类似的任务。\n\n这些事原本对青铜龙军团来说轻而易举，可惜，一切都变了。"
D.Strings[21251]="观察者是时光旅行者中的学者、斥候、研究员以及密探。\n\n我们观察时间流并记录、调查和报告时光的扰动和异常现象。\n\n也正是观察者将时光旅行者的目光引向这座时间凝固的小岛的。"
D.Strings[21252]="我这里有着皇帝陛下最珍贵的遗物。如果你想赢得少昊的青睐，就请帮我们赶走那些试图占据天神庭院的斡耳朵野牛人吧。"
D.Strings[21253]="里克里克可是很有两下子的……"
D.Strings[21254]="里克喜欢烟火！"
D.Strings[21255]="里克有个主意。乱斗俱乐部！"
D.Strings[21256]="当河流转向时，我们应该顺应潮流，而非逆势而上。"
D.Strings[21257]="永远不要忘记你最伟大的朋友，他们会与你并肩作战，直到最后一刻。"
D.Strings[21258]="皇帝就快成功了，他击败了猜忌、仇恨、暴怒和恐惧。"
D.Strings[21259]="请小心些，$n。\n\n至尊天神严禁联盟和部落在此地私斗。"
D.Strings[21260]="出门在外，请多加小心。\n\n除了那些巨兽，这片海滩的另一头还有敌人的营地。"
D.Strings[21261]="你要离开营地吗？\n\n至尊天神已经要求我们岛上的部队停止推近了，所以我们就留在这里守卫登陆点。\n\n你要出去的话一定要小心。敌人也对这里表现出了兴趣。他们的营地就在海滩的另一头，且守卫森严。"
D.Strings[21262]="想想看：这个地方完全在我们的时间流之外——而且已经存在了上千年！\n\n我们最有经验的编织者已经确认，这座岛的时空坐标目前还是稳定的，可我还是忍不住会想……\n\n万一这岛在我们滞留期间又消失了该怎么办？"
D.Strings[21263]="你能相信吗？世上居然有这种地方的存在！这里有太多需要学习和发现的东西了！在这里的发现绝对能让我著作等身。$b$b但它们的信息量太大了，我不知道有谁能读完它们。查德里克觉得我们该把它们写成歌谣，但这太蠢了……对吧？"
D.Strings[21264]="在很久很久以前，志向高远的英雄和帝王们会来这里面对至尊天神的考验。\n\n如今，我们也像我们的祖先一样，守卫着这些被时光侵蚀的道路。\n\n天神卫士绝不容许在这片圣地上发生阵营冲突。"
D.Strings[21265]="我已经尽力不去看太阳了。它是不会移动的。$b$b这到底是什么地方？"
D.Strings[21266]="这座岛真是既迷人又可怕。"
D.Strings[21267]="那就让我们来测试一下你的历史知识吧！告诉我，英雄，亡灵鱼人被称作什么？"
D.Strings[21268]="答错了！"
D.Strings[21269]="答对了！"
D.Strings[21270]="那就让我们来测试一下你的历史知识吧！白狼曾是哪个兽人氏族最喜爱的坐骑？"
D.Strings[21271]="那就让我们来测试一下你的历史知识吧！德鲁伊的最高称号是什么？"
D.Strings[21272]="那就让我们来测试一下你的历史知识吧！侏儒如今的领袖是谁？"
D.Strings[21273]="那就让我们来测试一下你的历史知识吧！由玛法里奥·怒风协助建立的，艾泽拉斯最主要的德鲁伊组织叫什么名字？"
D.Strings[21274]="那就让我们来测试一下你的历史知识吧！在第三次大战过去数年之后，黑暗之门重新开启时，艾泽拉斯首次出现了棕色皮肤的兽人。这些兽人被称为什么？"
D.Strings[21275]="那就让我们来测试一下你的历史知识吧！在被阿尔萨斯复活为亡灵，并加入天灾军团之前，辛达苟萨曾属于哪个巨龙军团？"
D.Strings[21276]="那就让我们来测试一下你的历史知识吧！赞加沼泽有一个地方，那里为纳迦所控制，他们还试图在那里抽取一种珍贵而稀有的资源：外域之水。这个地方叫什么名字？"
D.Strings[21277]="那就让我们来测试一下你的历史知识吧！在上古之战后，守护巨龙们给了暗夜精灵什么东西？"
D.Strings[21278]="那就让我们来测试一下你的历史知识吧！在第三次大战期间，是什么证据促使阿尔萨斯王子屠杀了斯坦索姆的居民？"
D.Strings[21279]="那就让我们来测试一下你的历史知识吧！阿尔萨斯用来训练死亡骑士，后来又由于大部分死亡骑士背叛巫妖王而被占领的浮空堡垒叫什么名字？"
D.Strings[21280]="那就让我们来测试一下你的历史知识吧！大领主库德兰·蛮锤最近痛失爱将，他英勇的狮鹫在一次大火中不幸丧生。这头狮鹫叫什么名字？"
D.Strings[21281]="那就让我们来测试一下你的历史知识吧！有一位王后，在大灾变和被遗忘者袭击她的国度时，她井井有条地安排了人民的疏散工作。这位王后叫什么名字？"
D.Strings[21282]="那就让我们来测试一下你的历史知识吧！在撕心狼变成狼人之前，他也曾有过家室。他的妻子叫什么名字？"
D.Strings[21283]="那就让我们来测试一下你的历史知识吧！艾泽拉斯出现的第一个死亡骑士是谁？"
D.Strings[21284]="那就让我们来测试一下你的历史知识吧！有一位德莱尼人，他曾是一个健康的圣骑士，但在与燃烧军团作战时，他身染恶疾，变成了破碎者。后来，他成了一个强大的萨满。这个德莱尼人是谁？"
D.Strings[21285]="那就让我们来测试一下你的历史知识吧！在黑曜石圣殿守护暮光龙蛋的三头暮光幼龙分别叫什么？"
D.Strings[21286]="那就让我们来测试一下你的历史知识吧！提里奥·弗丁的灰色公马叫什么名字？"
D.Strings[21287]="那就让我们来测试一下你的历史知识吧！由地精制造，原计划搭载萨尔和阿格娜前往大漩涡，却被联盟意外摧毁的部落舰船叫什么名字？"
D.Strings[21288]="那就让我们来测试一下你的历史知识吧！隶属于万神殿精锐的泰坦知识守护者叫什么名字？"
D.Strings[21289]="那就让我们来测试一下你的历史知识吧！被洛肯捕获并变成锋鳞的强大始祖龙叫什么名字？"
D.Strings[21290]="那就让我们来测试一下你的历史知识吧！根据德莱尼人的玩笑，“埃索达”在纳鲁语中是什么意思？"
D.Strings[21291]="那就让我们来测试一下你的历史知识吧！这个世界上的第一个萨特是谁？"
D.Strings[21292]="那就让我们来测试一下你的历史知识吧！瓦里安·乌瑞恩国王的第一任妻子的正确名字是什么？"
D.Strings[21293]="那就让我们来测试一下你的历史知识吧！在最初的部落建立之前，有一种高传染性的病毒在兽人间快速传播。兽人们称这种病为什么？"
D.Strings[21294]="那就让我们来测试一下你的历史知识吧！一位血色十字军保卫者在刺杀恐惧魔王贝塞利斯时遇害，她叫什么名字？"
D.Strings[21295]="那就让我们来测试一下你的历史知识吧！铁炉堡图书馆中展出了一具巨型山羊的骨架复制品。这头传奇山羊叫什么名字？"
D.Strings[21296]="那就让我们来测试一下你的历史知识吧！在突袭冰冠堡垒时，部落军队无耻地偷袭正与天灾军团激战的联盟士兵，并试图占领的那座城门叫什么名字？"
D.Strings[21297]="那就让我们来测试一下你的历史知识吧！下列哪句话是龙语中“谢谢你”的意思？"
D.Strings[21298]="那就让我们来测试一下你的历史知识吧！不久之前，一个脆弱的赞达拉巨魔想要驯服一头恐角龙。虽然他登上了巨兽岛，却在任务过程中遇害。请问这个巨魔叫什么名字？"
D.Strings[21299]="那就让我们来测试一下你的历史知识吧！嫌弃银月城过于明亮和干净的部落大使叫什么名字？"
D.Strings[21300]="那就让我们来测试一下你的历史知识吧！魅魔热衷于制造痛苦，她们在燃烧军团中专门负责进行可怕的拷问工作。请问魅魔属于哪个品种的恶魔？"
D.Strings[21301]="那就让我们来测试一下你的历史知识吧！头衔中包含“夜晚之友”的是哪位神灵？"
D.Strings[21302]="那就让我们来测试一下你的历史知识吧！在牛头人的语言中，lar'korwi是什么意思？"
D.Strings[21303]="嘿，伙计！我是助理历史学家帕吉。他们还没有正式授予我这个的头衔，但我相信那是迟早的事。"
D.Strings[21304]="你好！我是历史学家勒洛尔！大家都说我笑得太多了，可我觉得这完全不可能！"
D.Strings[21305]="我喜欢穿短裤！它最适合这里的天气！"
D.Strings[21306]="你是来拿包裹的吗？还是来寄信的？$B$B我可以提供超速快递服务哦！"
D.Strings[21307]="呃！什、什么？！噢……$B$B你、你需要、要什么吗？$B$B我、我怎么就让姐姐给骗过来了呢……你看到那些动物有多、多大吗？！"
D.Strings[21308]="<这个脏兮兮的老熊猫人安详地打着呼噜，身边丢满了各种瓶子。>"
D.Strings[21309]="噢，你好！$B$B请进，快请进！请休息一会儿吧。$B$B你想吃点什么吗？或者来杯喝的？"
D.Strings[21310]="你瞧，历史学家的工作是永远也干不完的。那些需要我们铭记的重要事件总是层出不穷。$B$B我已经记下了你的大部分事迹，但有待了解的东西还是太多了！你的事迹肯定会流芳百世的。"
D.Strings[21311]="我不是眼花了吧？！船上那些……是骷髅吗？"
D.Strings[21312]="那场风暴将我们吹离了航道。我们可能位于库尔提拉斯和洛丹伦之间的任何地方，所以都给我提高警惕！"
D.Strings[21313]="我从没见过这么浓的雾。我们得把帆降下来，等雾散开。我可不想让藤壶号撞上暗礁啥的。"
D.Strings[21314]="远处那是什么？船帆！嘿！我们都搁浅九天啦！救命！"
D.Strings[21315]="全体上甲板！藤壶号遭到攻击啦！"
D.Strings[21316]="时间既是美丽的，也是残酷的。"
D.Strings[21317]="我不管你的装备有多好，$n，如果不注意脚下，那你就死定了。让那些小崽子们休息一下，用我的传送门立即返回入口处吧。"
D.Strings[21318]="每个生命都是一条线，而把我们交织起来，就构成了这个世界的故事。熊猫人游学者对此的理解无人能及。看看这个图书馆吧！这么多故事……"
D.Strings[21319]="欢迎光临王记，这里的太阳永不下山，这里的美食永远热气腾腾！"
D.Strings[21320]="能和新朋旧友欢聚一堂真是太好了。"
D.Strings[21321]="别忘了花点时间去欣赏风景！"
D.Strings[21322]="我的位子是整个庭院里最好的，你不觉得吗？"
D.Strings[21323]="这里的人都很好……吱吱喜欢这里。"
D.Strings[21324]="你要去跟大牛战斗吗？"
D.Strings[21325]="你是吱吱见过的，最强大的$c！"
D.Strings[21326]="好好，我这就跟你走。但让我再玩一盘。"
D.Strings[21327]="这是我近几年玩过的最好的游戏！"
D.Strings[21328]="看到这张牌了吗？它肯定能把那个矮人从椅子上打翻。"
D.Strings[21329]="你说他怎么就打得那么好呢？"
D.Strings[21330]="看见这张牌了吗？他这次休想打败我！"
D.Strings[21331]="我会打败他的，我发誓！"
D.Strings[21332]="欢迎，$r。我是观察者麦佳娜的忠实守卫。她有着特殊的天赋，令我……呃，我们的领袖……十分欣赏，所以必须受到严密的保护。"
D.Strings[21333]="几代以来，我一直用迷雾保护着我的人民，但看着眼前的一个个勇士，我越来越意识到自己的错误。愿你和我一样，从潘达利亚的历史中得到教训。"
D.Strings[21334]="我很高兴能和我的儿子分享这一时刻。"
D.Strings[21335]="是的！一首关于传说，以及我们从中所得到的知识的歌谣。听起来很激动人心吧？$b$b不过……我们还在研究。查德里克最近似乎一直在分心。我的战袍上有什么脏东西吗？"
D.Strings[21336]="皮埃尔很厉害吧？是我的朋友贾德帮我做的！"
D.Strings[21337]="我想要训练他，可我又不想让他受伤害。"
D.Strings[21338]="他真的很好，还想帮我煮东西吃。可惜那些东西根本没法入口，我只能趁他不注意的时候都扔了。"
D.Strings[21339]="那些火炮都哑火了。干得好，英雄。你做好解决这一切的准备了吗？"
D.Strings[21340]="数千年前，潘达利亚的人民曾在这里见证雄心勃勃的帝王们面对至尊天神的挑战。\n\n那么，你是来观看未来的英雄接受天神试炼的吗？\n\n还是想要亲自挑战一下呢？"
D.Strings[21341]="<砮皂赞许地向你点点头。>"
D.Strings[21342]="你今天的壮举将决定潘达利亚在未来几千年中的面貌。$b$b谢谢你，英雄。游学者将会世代传颂你的故事。"
D.Strings[21343]="可是……"
D.Strings[21344]="赞美艾露恩，$c。"
D.Strings[21345]="我能看出你的灵魂有多么空虚，$n。最后的赢家一定是我！"
D.Strings[21346]="别担心我。他们看不见这个投影的。$B$B我们在这里所做的一切只有一个目的，$n：那就是抓住古尔丹。"
D.Strings[21347]="今天，有一团明亮的火焰在天空中爆散，$B$B一块巨大的白色石头就落在我们村子下面的平原上。$B$B我们不知道那是什么。那是先祖给我们的礼物吗？"
D.Strings[21348]="不久之后，天空中的白月之下浮现出一块阴影。有些人恐惧地看着它，其他人则对它顶礼膜拜。$B$B族人们给它起了很多名字：比如圣父，比如黑暗之母。$B$B酋长则称它为“黑暗之星”。"
D.Strings[21349]="自从水晶从天而降，我们的力量就出现了难以理解的增长。$B$B我们一直在聆听群星和大地的低语。而现在，我们听到了另一种声音——暗影之声。"
D.Strings[21350]="昨天，我们发现有一个族人亵渎了先祖的灵魂。$B$B酋长十分暴怒。显然——这种新魔法很危险。它会将我们引上一条不归路。$B$B从今日起，我们要世代牢记，所有族人都禁止使用暗影的力量。$B$B“黑暗之星”是邪恶的。"
D.Strings[21351]="只要同心协力，我们就能战胜暗影议会。"
D.Strings[21352]="格罗玛什·地狱咆哮：传奇战士，可怕的敌人。他将带领我们走向更美好的明天！"
D.Strings[21353]="不要相信德莱尼人。他们只想让你衰弱！"
D.Strings[21354]="相信你的同胞。相信钢铁部落的力量！"
D.Strings[21355]="做骄傲的兽人！帮助钢铁部落！"
D.Strings[21356]="<这面盾牌似乎是属于失踪的搜索队。$b$b经过进一步的检查，你发现在血迹斑斑的护甲上有着上百处细小的刺痕。>"
D.Strings[21357]="<你发现在死去的运货骡子身上，有着成百上千处微小的刺痕。>"
D.Strings[21358]="多年来，鲁尔坎一直是耐奥祖最信赖的顾问。耐奥祖的力量和雄心引领着我们的肉体，但鲁尔坎的智慧和预言鼓舞着我们的精神。"
D.Strings[21359]="耐奥祖的风格粗暴而直接。他会用暴力打倒敌人。$B$B而鲁尔坎聪明又睿智，最擅长以彼之道还施彼身。"
D.Strings[21360]="影月氏族完了。虽然它的躯壳还在，但它的灵魂已经堕落了。"
D.Strings[21361]="我们是自我放逐来到这里的。我们都不愿意接受耐奥祖的黑暗之星的魔力。"
D.Strings[21362]="我们今后的命运还不明朗，但有一点是肯定的，我对女酋长鲁尔坎绝对忠诚。"
D.Strings[21363]="<这把武器似乎是属于某个失踪的搜索队成员的。>"
D.Strings[21364]="阿卡特岗哨的研究员们已经收集到了许多先祖的原始残骸碎片。"
D.Strings[21365]="我的斥候敏捷而强大。他们会第一时间向我们通报敌人动向的。"
D.Strings[21366]="卡拉波的斥候迅捷如风。我们的攻击快速精准。"
D.Strings[21367]="没有光明照不透的黑暗。"
D.Strings[21368]="我们总在不断探索。"
D.Strings[21369]="睁大眼睛，保持警惕。危机就潜伏在沼泽之中。"
D.Strings[21370]="你好，$n。先知维伦跟我说过你的事迹。"
D.Strings[21371]="我们的斥候遍布整个沼泽和森林。影月兽人的一举一动都在我们的严密监控之下。"
D.Strings[21372]="生命即圣光，圣光即生命。它们可以互相转换并保持守恒。"
D.Strings[21373]="<这个棱镜依然散发着温和的能量。它看起来依然可以使用，但原本以它作为能源的那个古怪机器——可能是某种毁灭性武器，或是某种卑劣的刑具——看来已经完全毁坏了。>"
D.Strings[21374]="鲁特瞪着你思考了一会——然后对着一片火腿打了个响鼻。"
D.Strings[21375]="鲁特边摇尾巴边流口水；要不是它还同时放屁打嗝，这个样子还是挺可爱的。"
D.Strings[21376]="我是奈玛之女，鲁尔坎。我曾是影月氏族的长老，但现在已经不是了。$B$B耐奥祖是我的丈夫。我和我的追随者们，已经同他和他的追随者们分道扬镳了。"
D.Strings[21377]="我们的族人一直从大地和月亮中汲取魔力。$B$B大约三个世纪前，我们的祖先感受到了另一种魔力。一种黑暗的力量。$B$B这就是暗影魔法。它能腐蚀心智，令使用它的人堕落，让他们发疯。$B$B从那时起，我们氏族就严禁使用这些暗影魔法。"
D.Strings[21378]="以前搞草药学可比现在容易多了。如今哪怕是要弄一点点草药，我们都得在地狱里杀个来回！"
D.Strings[21379]="萨玛拉是我唯一的亲人。从我记事起，她就一直教导着我。$B$B她既亲切又善良，而我就……没那么出色了。"
D.Strings[21380]="多年来，影月氏族与卡拉波的德莱尼一直保持着相对的和平。$B$B自从钢铁部落……到来之后……情况就变了。"
D.Strings[21381]="玛尔拉德说他的伤不严重，事实上，他遭到了耐奥祖的重创。虽然我也说不好究竟哪一样伤得更重——到底是他的身体还是他的自尊。$B$B无论如何，他很走运，因为你及时赶到了。"
D.Strings[21382]="要是我们能把钢铁部落赶出沙塔斯，那将对他们的战略造成重大打击。如果我们还能解决掉他们的超级武器……"
D.Strings[21383]="预言是高难度的法术。未来经常模糊不清，一个人只能靠直觉来分辨哪些是必然发生的，哪些是有可能发生的。"
D.Strings[21384]="我……坚持……不住了……"
D.Strings[21385]="虫洞正在飞速旋转。你只能先跳下去，然后乞求老天保佑。"
D.Strings[21386]="尤鲁恩矿场为奥金顿和沙塔斯提供了大量能量水晶。"
D.Strings[21387]="我们就不该进那座森林。我……我都不知道该怎么面对这场灾难。"
D.Strings[21388]="欢迎，旅行者。这片土地近来虽然灾祸频发，但也涌现出了许多英雄事迹。你愿意追随这些勇者的脚步，见证他们的事迹吗？"
D.Strings[21389]="你好，我一直在研究那些新来的外来者们的英勇事迹。你想听听这些故事吗？"
D.Strings[21390]="你听说了吗？钢铁部落派出特使来跟耐奥祖谈判了。"
D.Strings[21391]="我从一个钢铁部落的家伙那里偷听到，他们好像计划在近期攻打卡拉波。"
D.Strings[21392]="耐奥祖教会我们如何获得自己应得的力量。德莱尼很快就会见识到我们的厉害了。"
D.Strings[21393]="鲁尔坎带着氏族里那些不愿意拥抱虚空的弱者们出走了。"
D.Strings[21394]="我听到传言说，耐奥祖打算召唤黑暗之星！"
D.Strings[21395]="我们的盟友只能帮我们争取到这点时间了，那个……钢铁部落很快就会全力突袭我们的营地。$b$b我们得继续前进了。"
D.Strings[21396]="当我说我愿意征战沙场时，我还以为自己会作为一名士兵，用熟练的武器技艺赢得胜利。$b结果我却在这里绘图砌砖。$b$b但我想这至少能让我多活几年。"
D.Strings[21397]="为你效劳，指挥官。"
D.Strings[21398]="已经没有希望了。我们该怎么出去？"
D.Strings[21399]="你这家店很不错嘛。比我在沙塔斯工作的那个小棚子大多了。"
D.Strings[21400]="既然奥金顿之心已经回归，我们的防御工事应该就固若金汤了！"
D.Strings[21401]="那么，这里就是你建造要塞的地方了。$b$b你以前指挥过这么多部队吗？$b$b我相信你会做得很好的……但愿如此。"
D.Strings[21402]="欢迎来到试炼竞技场！我正在这里举办格斗比赛。如果你想要赚点外快，那你可来对地方了！"
D.Strings[21403]="你想参加竞技场的比赛？去跟戴克希尔说吧，负责比赛的人是他。$b$b我？我只是来宣布比赛开始……并在战斗后清理尸体的！哇哈哈！"
D.Strings[21404]="指挥官。我随时听候你的差遣。$B$B你还有别的命令吗？"
D.Strings[21405]="噢，太好了，你来了，$n。"
D.Strings[21406]="幻象指引着我们，$n。让我们看看它想告诉我们什么吧。"
D.Strings[21407]="指挥官。让我们的游侠好好教训一下战歌氏族怎么样？"
D.Strings[21408]="愿圣光宽恕我。我辜负了他们。"
D.Strings[21409]="碎手氏族灭绝人性的罪行不可宽恕，我们不能违心地无视他们的罪行。"
D.Strings[21410]="如果我们能活着走出这片丛林，我会亲自监督，确保你和你的人民得到妥善的安置。"
D.Strings[21411]="审讯者克安的遗体就在你面前。"
D.Strings[21412]="<剑柄刻着一行铭文：>\n\n“为了平息古树的怒火，守备官托瓦斯战殁于此。\n\n 愿圣光照耀着他拼死守护的这片树林，并为它的住民带来永久的和平。”"
D.Strings[21413]="和你并肩作战是一种荣幸，$n。"
D.Strings[21414]="我知道这地方有多危险，但在拿回属于我的东西之前，我是不会走的！"
D.Strings[21415]="只有一个办法能向我证明你的价值，陌生人。$B$B那就是战斗。"
D.Strings[21416]="你想亲眼看一看奥金顿？$B$B那就用战斗向我证明你的资格吧。"
D.Strings[21417]="伪装可以一直维持到你完成任务。$B$B但魔法是善变的！$B$B拿上我的幻影护符。如果你在沙兹古尔弄丢了伪装，那就使用护符。"
D.Strings[21418]="小心沙兹古尔里那些巡逻的狼。伪装能骗过眼睛，但骗不过它们的鼻子。"
D.Strings[21419]="我怀念塔拉，但见到你总能让我感到欣慰，指挥官$n。$B$B愿纳鲁照亮你的道路。"
D.Strings[21420]="噢，呵呵呵，你这个可爱的小蝌蚪。告诉我，你喜欢青蛙吗？"
D.Strings[21421]="其他人都不相信我，可我真的看见“他”了。伟大的蛙神。只要被他看上一眼，你就会脱胎换骨！"
D.Strings[21422]="呱……呱……呱……听听它们的叫声！我最喜欢听它们说话了。"
D.Strings[21423]="你喝过青蛙汤吗，亲爱的？非常美味，而且对你的身体有好处。"
D.Strings[21424]="噢，我最喜欢它们可爱的小肚子和滑溜溜的小脚趾了，你呢？"
D.Strings[21425]="那些肮脏的刃牙虎人是跑不了的……没有人能在偷了热砂港的东西之后逍遥法外！$b$b没有！"
D.Strings[21426]="试炼竞技场是个赚钱的好地方！"
D.Strings[21427]="兽栏建造完毕。是时候好好利用它，让正义在纳格兰得到伸张了。"
D.Strings[21428]="<这头骡子用大而衰老的眼睛看着你……接着又嚼了嚼你的衬衣。>"
D.Strings[21429]="这附近很难找到好的食材。"
D.Strings[21430]="我是加总本次探险之旅的左膀右臂。像加总这样的天才是不屑理会那些日常琐事的。$b$b我的责任就是打理好一切，让他能够集中精力处理那些大事！"
D.Strings[21431]="热砂保护协会的创会宗旨就是保护艾泽拉斯和德拉诺的珍贵遗物和古董。$b$b我们远赴各地，寻找最珍贵的遗物！$b$b我们的任务就是让这些无价之宝找到最好的归宿……也就是价高者得！"
D.Strings[21432]="什么风把你给吹来了？我这里没有东西可卖，也不需要流浪汉！"
D.Strings[21433]="你需要穿过灌木林地。快去吧，睁大你的眼睛！$B$B啊哈哈哈！"
D.Strings[21434]="告诉我，当你看着一件古老的遗物时，你看见了什么？$b$b历史？文化？未解之谜？$b$b那是因为你的眼睛没有受过训练！你知道我看见的是什么吗？$b$b钱！大把的钱！$b$b如果你够聪明的话，只要跟着我一段时间，你就会对考古学的真谛有所领悟！"
D.Strings[21435]="我是一个老派的萨满，我对氏族间的无聊冲突毫无兴趣。$b$b在漫长的岁月中，许多氏族都曾称这座山谷为家园，但它始终是属于元素的。"
D.Strings[21436]="我这儿很少有人来。有客人上门的感觉真不错。$b$b你要留下来吃晚餐吗？"
D.Strings[21437]="一把扳手加一条灵巧的胳膊足以解决一切难题。"
D.Strings[21438]="< 铁钩刺穿了他的四肢，他的喙上还烙着一个碎手氏族的印记。$B$B看来兽人先找到了他。>"
D.Strings[21439]="感谢你在塔拉的帮助，$n。$B$B我已经控制住她了，但有你在身边总是让人觉得安心，$g小子:丫头;。"
D.Strings[21440]="不久之前，外来者的船只搁浅在潘达利亚的海岸，带来了冲突和勇气。听着，我要告诉你深渊中的阴影是如何肆虐潘达利亚，而勇敢的英雄又是如何为我们带来新的黎明的。"
D.Strings[21441]="水能够滋养并延续生命，也能够切断泥土和岩石。"
D.Strings[21442]="那些有着炽烈信念和凶猛勇气的人常常会发现自己很适合烈焰之道。"
D.Strings[21443]="风是元素之声，它会在微风中轻声低语，在风暴中凶猛呼号。"
D.Strings[21444]="愿鸦母庇佑你。"
D.Strings[21445]="你找到隐藏的神器了吗？$B$B你可以在阿什兰各地找到它的碎片。我听说最近有人在击杀荣耀之路外围的生物时也发现了一些。$B$B你可以把你找到的神器交给我，我会将它们分发给需要的人。"
D.Strings[21446]="我爱我的小猫咪！"
D.Strings[21447]="噢……巴伯是不是你见过的最可爱的小猫咪？"
D.Strings[21448]="迪娜是个小甜心。但要小心她的爪子，特别是当她眼神疯狂的时候。"
D.Strings[21449]="那些植物人想把我活埋了！"
D.Strings[21450]="哇，哇，有位英雄来救我们了。小心点，我的朋友，戈尔隆德可不是逞英雄的地方。"
D.Strings[21451]="要让你疲惫的身体休息一下吗？"
D.Strings[21452]="茂林幽谷有麻烦了。我们最好去看看能不能帮上忙。"
D.Strings[21453]="伊瑞尔是我最聪明的学生，但有时也是最糟糕的。$B$B她战斗起来十分勇猛，但从不把训练当回事。$B$B她学得很快，但总是静不下心来读书。$B$B比起背诵圣典，她宁愿去和村子的孩子玩耍。$B$B要是她能再专心一点该多好！"
D.Strings[21454]="先知维伦是个很好的老师，但他有时候太一本正经了！$B$B我宁愿在生活中实践神圣的戒律，而不是在书本上阅读它们。你说呢？"
D.Strings[21455]="我们从嘲颅兽人那里学会了一个秘诀：魔荚人最恨火焰。"
D.Strings[21456]="那些邪恶的生物在长矛上涂抹了毒药。我还有一支解毒剂，但我需要一点时间，等头脑清醒后才能移动。"
D.Strings[21457]="我们已经尽力厮杀了。但最后，我的许多朋友还是牺牲了。"
D.Strings[21458]="当那些东西冲出来攻击我们时，吉德文和我正在外面钓鱼。$b$b多亏了这些德莱尼，否则我们就死定了。$b$b要不是需要有人把吉德文送回营地，我一定要亲手杀了它们……这个白痴矮人。"
D.Strings[21459]="我们得确保旅行者不再受木精的袭击。$b$b阿瑞菲奥刚带着其他人离开了，如果你现在就走，或许还能追上他。"
D.Strings[21460]="要是我们只能整天干坐在这儿，那我还怎么赚钱？$b$b是的，我知道吉德文看起来有些不好，可我还有很多货要卖呢。"
D.Strings[21461]="根据我学到的专业知识，水晶的特质与德莱尼非常相似。\n\n它的核心材料有着惊人的潜力，但最初的水晶原石总是十分粗糙，而且布满瑕疵。只有通过精心打磨和培育，它的潜力才能完全发挥出来。\n\n然后，它才能展现出惊人的美丽与澄澈。"
D.Strings[21462]="如果你打算去平原上闲逛的话，最好小心点，旅行者。风牙狼崽子们最近变得特别危险。"
D.Strings[21463]="我们不太习惯有这么多同伴。我们游侠所受的训练都是要求我们自给自足，并在荒野中长时间生存。$b$b你或许会发现我们中的一些人更喜欢这种方式。"
D.Strings[21464]="贸易是安波里村的支柱产业。作为我们村的商人代表，我的责任就是确保商业运转流畅。"
D.Strings[21465]="天空中隐藏着无数奇迹等待人们的发现。我们的研究员就在瞭望台上研究星辰和其他课题。\n\n旅行者，如果你有时间的话，我建议你上去看看。"
D.Strings[21466]="安波里牧场饲养的雷象和塔布羊满足了沙塔斯和许多小型德莱尼村庄的需求。\n\n如果你想看看那些家畜，可以在村子外围找到那些牧场。"
D.Strings[21467]="真菌怪物还在不断爬进来，而我们就要不断烧死它们。就好像天天都在庆祝火焰节一样。我喜欢这样！"
D.Strings[21468]="你是来灭火的还是来干嘛的？"
D.Strings[21469]="嗯？一个旅行者？要知道，现在进入斯克提斯可是非常危险的。"
D.Strings[21470]="阿兹克派你来向我寻求答案，我保证会给你一个满意的答复。$B$B但现在，我们得先逃跑了。"
D.Strings[21471]="如果你不介意高温和让人喘不过气来的潮湿的话，宾奇维斯拓殖点也不失为一个好地方。$b$b好吧，我的意思是，如果你不介意高温和让人喘不过气来的潮湿，以及到处传染的真菌的话。"
D.Strings[21472]="宾奇维斯拓殖点绝对不容有失，我必须找到治疗方法！"
D.Strings[21473]="派普斯去哪儿了？这些小鬼一直在偷我的补给。$b$b噢！我原本打算去跟巴隆斯核对一下的，可我们实在太忙了。$b$b这座森林里已经快要没有木头了……我得制定一个砍伐计划。我会尽快向巴隆斯提交完整报告的。"
D.Strings[21474]="我们是来寻找对付鬣蜥人的方法的，结果我跟同伴走散了。$b$b然后这些木精就冒了出来，喂我吃各种浆果、蜜酒和蜂蜜。$b$b我发誓，自从来了这里之后，我至少胖了二十磅。"
D.Strings[21475]="你想要什么，新兵？"
D.Strings[21476]="我们才是神的选民。"
D.Strings[21477]="萨格雷必将夺回本该属于我们的一切。"
D.Strings[21478]="<拉安达压低声音，悄声说道：>$B$B你看起来像是我们的盟友，但我时间有限。我正在努力打入萨格雷，从内部瓦解他们的组织。到目前为止，还没有人怀疑我的身份。"
D.Strings[21479]="我已经把你的部队可以接受的任务清单都放在你的指挥台上了。$B$B为了方便起见，我可以帮你把命令传达给要塞里的部队，指挥官。"
D.Strings[21480]="不久，这个食人魔堡垒就会比以前繁忙多了。$b$b让我们做点什么吧，嗯？"
D.Strings[21481]="池塘中肥大的种子和根须扎入莱拉的尸体中大快朵颐着。"
D.Strings[21482]="这个死去的矮人脸上凝固着震惊的表情。"
D.Strings[21483]="这个矮人在死前似乎胖了很多。"
D.Strings[21484]="巴隆斯在找我？$b$b我一直跟我的工人待在这里……可怜的家伙，他真是忙昏头了。$b$b好吧，休息时间结束了。"
D.Strings[21485]="你还好吗？欢迎来到德拉诺最好的修理厂。$b$b如果你想修理三轮车、改装跑车、伐木机、火焰喷射器或火箭车的话，那找我们就对了！$b$b事实上，我们已经垄断了这个市场。"
D.Strings[21486]="要想对付老重拳，光靠几个爱吹牛的大地生物可不够！"
D.Strings[21487]="别问我们是怎么找到那个神器的。那可不是什么愉快的故事。"
D.Strings[21488]="我的合同里只提到了烧死真菌、修理引擎和打捞工作。这上面可没说还要对付虫子！"
D.Strings[21489]="你好，新兵。我能为你做些什么？"
D.Strings[21490]="我们必须保持警惕。这里到处都是食人魔。"
D.Strings[21491]="看到你在加洛克临终前让他得到安息，我感到非常欣慰。我们会永远感激你的善良与勇敢的。"
D.Strings[21492]="这些朝圣者从德拉诺各地涌来，聆听埋葬在奥金顿内的灵魂们的智慧。对德莱尼来说，这种智慧将带来巨大的回报。"
D.Strings[21493]="暗影议会的散兵游勇已经将许多旅行者困在了奥金顿里。\n\n除非战局扭转，否则我们可能永远离不开这个地方了。"
D.Strings[21494]="我们的补给已经快用完了，但难民还在不断涌来。这种情况维持不了多久。"
D.Strings[21495]="谨遵主人的命令！"
D.Strings[21496]="目前为止，我们的药物对这种蜘蛛毒素毫无作用。\n\n我们必须采集更多的样本，才能调制出有效的解毒剂。"
D.Strings[21497]="补给？什么补给？我根本不知道你在说什么。$b$b<斯克拉普的眼珠转来转去，同时紧张地清着嗓子。>$b$b什么？我没偷过任何东西……我是说，我根本不知道你在说什么。"
D.Strings[21498]="还有许多伤员需要我的帮助。不能再浪费时间了。"
D.Strings[21499]="我们走吧！"
D.Strings[21500]="我的工人都去哪儿了？他们得加班干完这些才行。"
D.Strings[21501]="<爱丽丝似乎完全没有注意到你的存在。>"
D.Strings[21502]="我听说过元素王座，元素可以在那里与兽人交流。我从没想过自己有一天会站在这些巨人面前。$b$b虽然我在这里只是一个陌生人，但我觉得自己似乎来过这里……也许是在梦中吧。"
D.Strings[21503]="在被兽人称为沃舒古的水晶山下，躺着吉尼达尔的残骸。要不是先知维伦和纳鲁克乌雷的仁慈，我的人民早就死于燃烧军团之手了。"
D.Strings[21504]="吉尼达尔曾是一艘由纳鲁领航，圣光驱动的飞船。现在，当我们站在这艘伟大飞船的残骸中时，圣光已经消逝……我只能在这里感觉到黑暗。"
D.Strings[21505]="这里是我们训练幼年灵龙听从指令的地方。\n\n虽然它们滑稽的动作看起来傻乎乎的，但要想把它们训练成坐骑，现在所学习的纪律是必不可少的。"
D.Strings[21506]="我本应该干掉你，可这又有什么意义呢……我没能完成任务，只能在这里等死……"
D.Strings[21507]="迪奥诺是我们族中一位强大而勇敢的勇士。他曾试图突破古老的战线与我们的敌人交战。$b$b但他最终死于几个玛戈隆之手……这里是他的陨落之地，他的力量为我们这些幸存者制造出了一片小小的避难所。如果我能够成功……可我失败了……"
D.Strings[21508]="像迪奥诺这样的勇士陨落后，他的躯壳上会生长出一个凋零之蕾。我想要采集这朵芽蕾并在此举行神圣的仪式，解放他的生命力，让他返回森林。$b$b可在行动时，我遭到了一些毛茸茸的两腿生物的攻击，他们抢先夺走了芽蕾。我们试图追上去，可他们升起了屏障，并用火焰逼退了我们。$b$b所以现在我只能咀嚼失败的苦果，等着敌人将我们碾为尘土……"
D.Strings[21509]="你想要什么？你没看到我正打算喝一杯吗？给你自己也倒一杯吧。$B$B赫米特来到了联盟和部落口中的纳格兰。因为这里还有大型野兽可供狩猎。$B$B可是，当我来到这里之后，他们有让我尽情狩猎吗？没有！$B$B赫米特，去杀掉战歌氏族的座狼。杀光兽人的坐骑。$B$B这可不是赫米特·奈辛瓦里该做的事！"
D.Strings[21510]="我曾是一个像你一样的冒险者……$b$b那些日子至今依然历历在目，就好像发生在昨天一样。那时我还在艾泽拉斯，坐在我最喜欢的旅店里，或许你听说过它？就是狮王之傲旅店，就在闪金镇的中央。$b$b那时，我就坐在老杜宾斯的对面，就着一壶西瓜汁享用美味的陈年干酪。突然，多吉冲进了旅店！$b$b他的脸色变得雪白……不对，是比雪还要白！他说他在附近看见了一只狗头人，它还带着一支蜡烛，好像是打算将闪金镇付之一炬！$b$b我丢下美味的陈年干酪，冲向门口，却被一个矮人猎人绊倒了。$b$b我们都摔在了地上，然后“啪”的一声，我的膝盖中了一箭！"
D.Strings[21511]="我是部队中速度最快的通讯员。你有报告需要递交吗？"
D.Strings[21512]="嘿，再次感谢你在宾奇维斯拓殖点救了我。"
D.Strings[21513]="萨皮饿了。"
D.Strings[21514]="欢迎欢迎！来休息一下，并留下你的金币吧！"
D.Strings[21515]="你的内心乐观向上，但枪林弹雨即将到来。祝你渡过愉快的一天。"
D.Strings[21516]="我们会想出办法的，这可是宾奇维斯拓殖点最擅长的事！"
D.Strings[21517]="我们的部队已经摇摇欲坠，我的力量也在衰退，$n。剩下的时间不多了，我们马上就会被击溃的。"
D.Strings[21518]="在死后……我将解脱……"
D.Strings[21519]="这里的瘴气笼罩了一切！我们不能停留太久……"
D.Strings[21520]="我好像没办法弄掉这个恶心的玩意儿了……别担心，我还遇到过更糟的情况呢……"
D.Strings[21521]="这里的雾太浓了，我几乎都看不见东西了……它太吵了。真想让所有人都闭嘴！"
D.Strings[21522]="在戈尔隆德，就连天空都非常危险。请保持警惕。"
D.Strings[21523]="这片丛林很美丽。我以前从没见过这样的地方。$b$b当然，卡尔娅总是强调，“就因为这样，所以丛林会害死你的。”"
D.Strings[21524]="这片丛林可不是拜神者和金属匠来的地方。$b$b可是对你，我却有些不敢肯定。$b$b你的武器和装备说明你是一个去过许多地方的人。"
D.Strings[21525]="这是一个传统的路边神龛。泰罗克在各地建造了许多这样的神龛来引导流亡者前往斯克提斯。"
D.Strings[21526]="如果我们想要进步，就得明白自己究竟遗忘了什么。"
D.Strings[21527]="来吧，来吧！到我的火炉旁来坐坐。想要来几条青蛙腿吗？"
D.Strings[21528]="非常遗憾，这位审讯者没能坚持下来，他牺牲时正当盛年。"
D.Strings[21529]="艾泽拉斯被一个想要统治世界的邪恶敌人入侵了。$b$b如果我们想制止这逐渐蔓延的混乱，就必须尽快行动。"
D.Strings[21530]="求求你，$c，发挥出这颗核心真正的作用！你一定会赢得迪奥诺的极大好感的！"
D.Strings[21531]="如果你有现金，我就送你一程！"
D.Strings[21532]="$n，看着我的眼睛，你就能从远处监视阿什兰。$B$B你想看什么？"
D.Strings[21533]="好像有鱼咬钩了……"
D.Strings[21534]="<老国王泰罗克的遗物上装饰着一个粗糙的鸦人雕像。>"
D.Strings[21535]="还有补给品吗，指挥官？我们的战士总会需要它们的。"
D.Strings[21536]="听候您的调遣。"
D.Strings[21537]="不要对部落的家伙手软，$n。把他们死亡的证据带来给我，我会好好奖赏你的。"
D.Strings[21538]="只有通过对鸦母的信仰，我们才能获得救赎。"
D.Strings[21539]="<当你靠近萨满之石，卡拉迪奥斯的声音在你脑海中响起。>"
D.Strings[21540]="作为泰兰德的侍女，我的哨兵们随时可以与你并肩作战，并保卫你的要塞。"
D.Strings[21541]="这座要塞是你的地盘，指挥官。"
D.Strings[21542]="如果你不介意和怪物、陷阱、强盗以及一切试图杀死你的家伙战斗的话，不知道你能挖到点什么。"
D.Strings[21543]="光让座狼认你为主还不够。要想骑上你的狼，你还必须彻底征服它的意志。\n\n在驯服你的狼之后，你必须骑着它爬上纳格兰最高的山峰。如果你的狼足够倔强，它可能会把你摔死在山坡上。 \n\n如果你能活着登上山顶，那你的狼就已经完全驯服了。 \n\n然后，你就能自称为“狼骑兵”了。"
D.Strings[21544]="自从我的远征军进入这片被遗忘的土地，你是第一个没有在见到我之后立刻攻击的家伙……我就不该来这儿！"
D.Strings[21545]="自从“巫师之王”马尔高克掌权并发现了那些神器之后，他就整天念叨着破魔者长灭火者短的。有了新发现的力量之后，他就觉得自己不再需要我们的军团了！$b$b这个帝国是靠食人魔的力量和刀剑建立起来的，我就是这么告诉他的！"
D.Strings[21546]="他不但听不进去，还用我的话来对付我！$b$b他命令我和我的忠实支持者发起这场该死的远征，寻找食人魔的原始文明以及一些白痴神器！我不能反抗……现在我的部队全完了，我也回不去了……"
D.Strings[21547]="不打算买的话就别碰我的商品。"
D.Strings[21548]="难以置信，我们俩居然会站在这里，$n。这是德拉诺……但它又不是德拉诺。我感觉我们好像走到了镜子的另一面。$b$b让我们赶快完成任务，然后离开这个地方吧，好吗？"
D.Strings[21549]="<这团难以名状的魔法能量似乎带着人们游览你的要塞。>"
D.Strings[21550]="千万别低估了这片土地的危险性。$b$b<索恩指了指自己的眼罩。>$b$b这就是我的天真和疏漏留下的记号。"
D.Strings[21551]="在潘达利亚，我从没有在执行任务时请求“帮助”的习惯。或许这就是我们从没见过的原因？"
D.Strings[21552]="我的鲜血如玫瑰般鲜红。我的心永远为吉尔尼斯而跳动。"
D.Strings[21553]="哈哈，谁能想到一个学徒的身份能让我来到这里？这真是太刺激了！"
D.Strings[21554]="嘿，你觉不觉得阿历克斯顿和索恩很般配？呵呵！"
D.Strings[21555]="嘿，指挥官，你玩过战球游戏嘛？去试试吧！"
D.Strings[21556]="那个索恩真该放松一点，开朗一点！呃……指挥官！"
D.Strings[21557]="你看见布莱斯顿了吗？呃……我新来的助手还真是麻烦。$b$b她干什么都非常极端——不管是酗酒、聊天还是干活……$b$b但她是个超棒的建筑师，或许也会是我最聪敏的学生。$b$b所以我也就忍了。"
D.Strings[21558]="索恩中尉是我们所有人的光辉榜样。我从没见过这么敬业的领袖。$b$b我还没鼓起勇气跟她搭讪过，但或许有一天，她会记住我的名字的。"
D.Strings[21559]="<这头狮鹫期待地看着你。>"
D.Strings[21560]="我们的命运交织在了一起。"
D.Strings[21561]="接受我的力量。现在它归你了。"
D.Strings[21562]="我从没想过能在有生之年目睹如此神奇的地方，指挥官。$B$B我很高兴和我最信赖的老朋友，贝林顿先生一起来到这里。"
D.Strings[21563]="就算是你，偶尔也需要休息一下的，指挥官。"
D.Strings[21564]="为了等你修好他，我已经等了一整天了。不过没关系，还有很多事情可以用来打发时间。"
D.Strings[21565]="为了找到横穿山谷的“捷径”，费尔沃什把我们的团队都带迷路了。现在，我的靴子里都是泥沙！\n\n从现在开始，我来保管地图。"
D.Strings[21566]="我们没有迷路，我只是选择了比较冒险的路线！"
D.Strings[21567]="我们收到风声说，在这个名为阿什兰的地方藏着一些神器，是由一些残余的悬槌食人魔留下的。$B$B它们或许就是我们战胜钢铁部落的关键。"
D.Strings[21568]="敌人的旗舰就停在海滩旁。我们来拖住黑手，毁掉船只、拯救沙塔斯的任务就交给你了！"
D.Strings[21569]="<考里格双眼紧闭，肤色十分苍白。>"
D.Strings[21570]="雪莉？是你吗？"
D.Strings[21571]="别相信他们，雪莉！他们是在骗你。他们会吃了你的。他们会把我们都吃了的！"
D.Strings[21572]="我最讨厌蔬菜了……"
D.Strings[21573]="<鲁比洛洛好像饿了。或许她的主人可以提供一些帮助。>"
D.Strings[21574]="你没看见我正在钓鱼吗？"
D.Strings[21575]="此时此刻，我们只需要等待一个机会。一旦敌人的攻势减弱，我们就可以行动了。"
D.Strings[21576]="<大法师全神贯注地盯着黑暗之门。>$b$b看，他们的人数变少了，但还很不明显。这或许就是我们的机会。$b$b你们做好准备，面对黑暗之门另一边的一切了吗？"
D.Strings[21577]="告诉我，指挥官，你觉得索恩中尉这人怎么样？每次靠近她时，我就会变得紧张。$b$b我就是……不擅长和女性相处。只有她是个例外。是的，一个女人。虽然她是个狼人。那我也喜欢。噢，那长长的，丝滑的毛发……$b$b唉……"
D.Strings[21578]="指挥官，我就是想问问。巴隆斯有没有跟你提过我？什么？噢……我就是随口问问。$b$b<索恩脸红了起来。>"
D.Strings[21579]="对我们来说，天空也不是遥不可及的。是的，就是这样。"
D.Strings[21580]="暮色渐起，群星璀璨。"
D.Strings[21581]="即使在光明之下，也有阴影的存在。"
D.Strings[21582]="现在我们必须面对钢铁部落的舰队了。他们的一艘战舰上搭载了一件强大的武器，现在就停泊在海岸边。我知道一个可以肃清道路的法术，但它需要我集中全部精神来引导。在念诵咒语时，我将非常脆弱，只能靠你和我们的盟友来保护我了。"
D.Strings[21583]="伊瑞尔、玛尔拉德和杜隆坦需要你去旗舰上帮忙。黑手是不会不战而降的。"
D.Strings[21584]="你想要打一场吗，勇士？"
D.Strings[21585]="一个$c？噢，你来得正是时候。$b$b我们像往常一样进行挖掘时，根本没想到会发现什么东西。"
D.Strings[21586]="我会为这份工作找到合适的人选的。"
D.Strings[21587]="抱歉让你失望了，如果你是来加入奈辛瓦里狩猎队的话，那就太不走运了。$b$b赫米特去协助联盟和部落对付战歌氏族了，所以狩猎队的活动已经暂停了。$b$b这确实很遗憾，这里是我见过的最壮观、最狂野的土地。"
D.Strings[21588]="感谢你帮助我的人民渡过这个黑暗时期。希望有一天我们能够报答你的恩情。"
D.Strings[21589]="战斗已经趋于白热化。我们必须继续推进！"
D.Strings[21590]="这是我们打散钢铁部落的机会。坚强点，我们必须守住前线！"
D.Strings[21591]="哦，伙计，刚才那下撞得太狠了，我的肚子里都搅成一锅粥了。"
D.Strings[21592]="我还以为自己肯定要死在那里了。真是太感谢你了！"
D.Strings[21593]="我一定要请你喝一杯！"
D.Strings[21594]="我欠你一条命！谢谢你救了我！"
D.Strings[21595]="长官，敌人正在接近我们的要塞。我已经准备了一些你可能用得上的东西。"
D.Strings[21596]="铁炉堡的大军听候您的召唤，指挥官。"
D.Strings[21597]="侏儒别动队随时待命，指挥官！"
D.Strings[21598]="尽管下令吧，指挥官，德莱尼很愿意为维护和平出一份力。"
D.Strings[21599]="别来烦我。只有熟悉附魔之道的人才能理解我的窘境。"
D.Strings[21600]="你想要什么，废物？"
D.Strings[21601]="我不能再等下去了。利爪之王必须归来。"
D.Strings[21602]="你能来真是太好了，这里的麻烦已经超出我的处理能力了。"
D.Strings[21603]="一个嘲颅兽人在这里做出了可怕的暴行。我们得在他们回来之前尽快完成任务。$b$b这个家伙特别残暴……"
D.Strings[21604]="这些刃牙虎人在摆弄他们根本不理解的魔法！他们一定会激怒玛戈隆的。"
D.Strings[21605]="但愿这能起作用……"
D.Strings[21606]="今天天气真不错，指挥官。"
D.Strings[21607]="这里的一切都生长良好。"
D.Strings[21608]="这些植物看起来都很棒，不是吗？"
D.Strings[21609]="德拉诺的各个草药点都能收集到德拉诺种子。等你手里的种子超过5个之后再来找我吧，我可以帮你把它们种成草药。"
D.Strings[21610]="不死鸟大挑战该怎么玩？"
D.Strings[21611]="我准备起飞了！|cFF0008E8（暗月游戏代币）|r"
D.Strings[21612]="欢迎！我们特别准备了这种“不死鸟”级烟火，它可以绑在你的背上，让你在天空翱翔，追寻戒指和荣耀！"
D.Strings[21613]="只要一个游戏代币，我就可以把我们最新的“不死鸟”级烟火绑在你的背上。你将被发射到高空，长出烈焰的翅膀！$B$B接下来就是最困难的地方：你只有10秒的飞行时间，同时会有一些火圈分散出现在马戏团各处。你每穿过一个火圈，你的总分就会增加一点。最重要的是，它能让你再飞行10秒。$B$B只要穿过15个火圈，奖品就归你了！但如果你没能穿过足够的火圈，就得再交出一个游戏代币！"
D.Strings[21614]="今天真是个钓鱼的好日子！现在我们顿顿都能吃鱼了！"
D.Strings[21615]="我不像我丈夫那么热衷于钓鱼，但能获得足够的食物还是让我很开心。"
D.Strings[21616]="你准备好与塞泰战斗了吗，$r？"
D.Strings[21617]="结束了。到蕾希之眠来找我吧。"
D.Strings[21618]="<幽灵狼并没有发现你的存在，依然空洞地盯着附近一座粗糙的坟墓。>"
D.Strings[21619]="嘿，伙计！很高兴能在这儿见到联盟的$g小伙子:小丫头;！\n\n我敢打赌，有了你的帮助，我的工作一定能取得进展。"
D.Strings[21620]="萨格雷可不蠢。他们一直在盯着我。$B$B但知道自己的努力没有白费，我还是很高兴的。"
D.Strings[21621]="你能帮我到附近抓点鱼回来吗？"
D.Strings[21622]="补给能够决定一支大军的生死。"
D.Strings[21623]="不用担心，我总会让这玩意儿飞起来的。"
D.Strings[21624]="德拉诺的各个采矿点都能挖到德拉诺岩石。等你手里的岩石超过5个之后再来找我吧，我可以帮你把它们提炼成矿石。"
D.Strings[21625]="日安，指挥官。还是说现在已经是晚上了？这个该死的地方，连白天黑夜都分不清楚。"
D.Strings[21626]="向你致敬，指挥官$n，你是联盟的英雄！"
D.Strings[21627]="你是这个黑暗之地的明灯，指挥官。"
D.Strings[21628]="指挥官！德拉诺从来不会让人觉得无聊，对吧？"
D.Strings[21629]="胜利或死亡，指挥官！但如果有可能的话，我还是喜欢前者。"
D.Strings[21630]="让那些钢铁杂种看看真正的部落是什么样的吧，指挥官！"
D.Strings[21631]="力量与荣耀！"
D.Strings[21632]="为了沃金酋长和指挥官$n！"
D.Strings[21633]="你为部落带来了荣耀，指挥官！"
D.Strings[21634]="向你致敬，指挥官$n，你是部落的骄傲！"
D.Strings[21635]="今晚，我们为你举办庆功宴，指挥官！"
D.Strings[21636]="很高兴见到你，指挥官。"
D.Strings[21637]="能为您效劳是我的荣幸。"
D.Strings[21638]="要塞很安全。"
D.Strings[21639]="那道疤是新的吧，指挥官？你现在一共有多少疤了？"
D.Strings[21640]="各位，注意了！指挥官来了！"
D.Strings[21641]="指挥官！"
D.Strings[21642]="只要看你一眼，我们敌人就会像狗一样落荒而逃！"
D.Strings[21643]="愿为您效劳。"
D.Strings[21644]="我在空气中闻到了战争的味道，指挥官。"
D.Strings[21645]="能与你并肩作战是我的荣幸！"
D.Strings[21646]="需要我去杀敌吗？"
D.Strings[21647]="指挥官，战斗进行得怎么样了？"
D.Strings[21648]="快下令吧，我保证完成任务。"
D.Strings[21649]="有什么指示吗，指挥官？"
D.Strings[21650]="我们会奋勇作战的。"
D.Strings[21651]="我遇见了一位活的传奇。"
D.Strings[21652]="我在空气中闻到了战争的味道，指挥官。难道这又是厕所的味道吗？"
D.Strings[21653]="无论我喂它们多少东西，你的宠物还是会溜到议政厅去讨残羹冷饭。"
D.Strings[21654]="<丽奥眯了眯双眼。>"
D.Strings[21655]="你真的想知道答案吗？"
D.Strings[21656]="<丽奥轻声咆哮起来。>"
D.Strings[21657]="以前也有人这么问过我……但就那么一次。"
D.Strings[21658]="小鬼，别来惹我。"
D.Strings[21659]="有什么宠物用品卖吗？"
D.Strings[21660]="噢，真是个好问题。让我们把它记下来吧。"
D.Strings[21661]="你喜欢疤痕吗？"
D.Strings[21662]="钢铁码头急需我的支援。"
D.Strings[21663]="和你的公会同伴一起征服德拉诺的所有地下城，以此向你的公会表达忠诚吧。一旦你完成了这个任务，就可以从公会商人那里购买要塞公会旗帜。\n\n等你拿到旗帜后再来找我，我可以帮你在要塞中升起公会旗帜，让所有人都看到。"
D.Strings[21664]="你需要什么，指挥官？"
D.Strings[21665]="哇！你也在这儿呢？呼……我都开始以为自己干了件蠢事呢。我已经准备好为联盟赢得这场战争了，$G长官:女士;！"
D.Strings[21666]="欢迎，指挥官。如果有什么能让你感觉更加舒适，请尽管告诉我。"
D.Strings[21667]="等等，伙计。你没看见我正忙着吗？"
D.Strings[21668]="我还是个小伙子时，曾接受过我爷爷吉加克斯的训练。我跟你保证，在这一带，你再也找不到比我更出色的战士了。"
D.Strings[21669]="你的灵魂总是燃烧得如此明亮！"
D.Strings[21670]="你的英勇壮举进行地怎么样了？"
D.Strings[21671]="为您效劳。"
D.Strings[21672]="愿万灵护佑着你，指挥官。"
D.Strings[21673]="只要团结一致，我们就不会屈从于黑暗。"
D.Strings[21674]="圣光永远指引着我们，指挥官。"
D.Strings[21675]="很高兴见到你，$n。"
D.Strings[21676]="在我们俩面前，敌人毫无机会。"
D.Strings[21677]="想要交流一下有关打仗的老故事吗？"
D.Strings[21678]="有部落的踪迹吗？"
D.Strings[21679]="此生此世，为了联盟。"
D.Strings[21680]="圣光指引我们走向胜利。"
D.Strings[21681]="我将与你并肩作战，碾压一切敌人。"
D.Strings[21682]="如果你在铁炉堡、达纳苏斯、诺莫瑞根、埃索达、吉尔尼斯或土水派熊猫人中的声望达到崇拜，或者作为死亡骑士在黑锋骑士团达到崇拜声望，就可以与议政厅内对应的征募官对话，从他们那里招募守卫了。"
D.Strings[21683]="愿意为您效劳，指挥官。"
D.Strings[21684]="你有东西要修吗，指挥官？"
D.Strings[21685]="愿艾露恩祝福你，指挥官。"
D.Strings[21686]="愿星辰照耀着你。"
D.Strings[21687]="美好的一天在等着我们。"
D.Strings[21688]="我听候您的吩咐，指挥官。"
D.Strings[21689]="愿意为您效劳。"
D.Strings[21690]="你有任务要交给我吗，指挥官？"
D.Strings[21691]="你需要杀什么人吗，指挥官？"
D.Strings[21692]="派我上前线吧，指挥官。"
D.Strings[21693]="我的剑听候您的召唤。"
D.Strings[21694]="向你致敬，指挥官。"
D.Strings[21695]="我今天能帮你什么忙吗？"
D.Strings[21696]="元素在召唤。"
D.Strings[21697]="今天有什么工作吗？"
D.Strings[21698]="拜托，我都快无聊死了。你有什么事要让我做的吗？"
D.Strings[21699]="那么你喜欢哪个，火药还是汽油弹？我？我比较喜欢汽油弹。"
D.Strings[21700]="什么事，指挥官？"
D.Strings[21701]="嘿，指挥官，你是来给我分派任务的还是直接来给我送钱的？"
D.Strings[21702]="只有最出色的战士才能在竞技场中战斗。"
D.Strings[21703]="请在阴影中休息一会儿吧。"
D.Strings[21704]="你好，指挥官。你需要我的协助吗？"
D.Strings[21705]="随时为您效劳。"
D.Strings[21706]="这把武器比得上我的角吗？我正打算给它们涂上相配的颜色呢。"
D.Strings[21707]="这可比在某个尘封的老城市的熔炉边工作强多了。"
D.Strings[21708]="你好，指挥官。"
D.Strings[21709]="在钢铁部落覆灭之前，我是不会安息的。"
D.Strings[21710]="我欠你一份人情，指挥官。"
D.Strings[21711]="我们将一起打败钢铁部落，指挥官。"
D.Strings[21712]="有钢铁部落的踪迹吗，指挥官？"
D.Strings[21713]="多亏了你，剑圣巴罗克再也不能折磨我的家人了。"
D.Strings[21714]="我听候你的调遣，指挥官。"
D.Strings[21715]="一切平静，指挥官。太平静了。"
D.Strings[21716]="你们在阿什兰的事业是正义的，我们德莱尼会尽一切可能帮助你们的。"
D.Strings[21717]="人们一直很好奇一个狼人是怎么会变成饲养员的，可事实是，在被感染之前，我一直都是饲养员。只要把你的宠物交给老奥维尔就行了，我会好好照顾它们的。\n\n不用问了，我保证，我肯定不会吃了它们的。"
D.Strings[21718]="愿意为您效劳！"
D.Strings[21719]="你好，指挥官。想试试我的按摩手法吗？"
D.Strings[21720]="你好！请让我来帮助你吧！"
D.Strings[21721]="能为您效劳是我的……荣幸！"
D.Strings[21722]="指挥官，你的衣服好像脏了。让我为你清洁一下吧。"
D.Strings[21723]="抱歉，亲爱的，在考虑还能造什么建筑之前，我们需要先有更多的地皮。等你的要塞升到2级后再来吧，到时候我们再详谈。"
D.Strings[21724]="你喜欢泡吧吗？"
D.Strings[21725]="你有个好地方，指挥官。"
D.Strings[21726]="你好啊。"
D.Strings[21727]="厕所在哪儿？"
D.Strings[21728]="你准备好传送后就进入传送门吧。你将被直接传送到阿什兰岛的暴风之盾。\n\n不用怕，暴风之盾不会让你自动进入PVP状态的。"
D.Strings[21729]="你好，指挥官！$b$b今天还好吗？"
D.Strings[21730]="有兴趣在这里钓钓鱼吗？"
D.Strings[21731]="<荣耀圣坛静静地等待着供品。>"
D.Strings[21732]="写呀写，写上一整天。抄呀抄，美妙的文字流出来。"
D.Strings[21733]="万岁，指挥官。我们发现了一具能够修好的钢铁之星，那边的加兹鲁维帮我将它修好了。\n\n等你准备好时，它应该也能动了。\n\n卡德加说他和其他人会在港口的入口处等你。或许你可以开着它顺手压死沿路上遇到的钢铁部落渣滓。"
D.Strings[21734]="我们是不可战胜的！"
D.Strings[21735]="还有额外的神器碎片吗，$n？我的朋友艾希兰姆可能会用得上它们。"
D.Strings[21736]="如果你交给克里斯·克拉奇一些牛头人蹄子，他就会好好奖赏你的。$B$B但我也不明白是为什么。"
D.Strings[21737]="很高兴你能安全抵达这里。准备好了吗？"
D.Strings[21738]="你不感到欣慰吗？"
D.Strings[21739]="历史里有许多值得我们学习的东西。"
D.Strings[21740]="你好，勇士。$b$B我是自愿加入远征队，来考察德拉诺的奇异物种的。$b$b如果你在旅途中发现了什么奇怪的东西，我很希望能够检查一番。"
D.Strings[21741]="你需要个伴儿吗，指挥官？"
D.Strings[21742]="就等你了！"
D.Strings[21743]="欢迎，指挥官。我这里有全阿什兰最好的武器和护甲。$b$b如果你有什么需要我帮忙的，尽管开口。"
D.Strings[21744]="欢迎光临星酒附魔店，本店可提供全暴风之盾最低价的附魔。\n\n要看看我们的配方列表吗？"
D.Strings[21745]="<这个年轻冒险者的尸体上有好几处伤口。$B$B从这个临时营地的状况来看，这里不久之前刚爆发过战斗。$B$B他的手中握着一个纸团。>"
D.Strings[21746]="兽人……$B$B<库卢斯吐了口口水。>$B$B要是你能把这片土地上的兽人赶尽杀绝，那真是帮了这个世界的原住民一个大忙了。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[21747]="在我的语言中，地精基本就是寄生虫的意思。他们给自己取得名字可真合适。就让他们的死亡给其他所谓的“部落”成员一个教训吧。$B$B你面前的道路危机四伏，许多敌人都会想方设法阻挠你的正义事业。你的结局只有一个：非胜即死。$B$B你确定要做出这个选择吗？"
D.Strings[21748]="你以为你能击败塔尔的宠物？可笑。"
D.Strings[21749]="像我这样的资深模特从不走没有准备的秀。\n\n我一辈子都在练习我的独创造型。"
D.Strings[21750]="你要招募干活的人吗？我能帮你找两个来。"
D.Strings[21751]="有人要找工作吗？"
D.Strings[21752]="艾斯卡希望泰罗克能以实体形态归来。可利爪之王到底是会拯救我们，还是将我们引入更深的黑暗？$B$B我不想再重复过去的错误。$B$B在你身上，我看到了足以掌握利爪之王力量的可贵品质。伊沙尔也同意了，并帮我将你们的精魂结合在了一起。$B$B艾斯卡不会高兴的，但生米已经煮成熟饭了。"
D.Strings[21753]="很高兴你能来阿什兰，$C。这里很快就会需要你了。\n\n这座岛屿上出土的神器来自古代食人魔王国，它们或许将成为我们对抗钢铁部落的决定性因素。不幸的是，部落想要罔顾停战协议，独占这些知识。\n\n我们决不能让部落妨碍我们在德拉诺的行动。如果有必要的话，你尽管与他们开战，从他们的死人手里夺取神器吧！\n\n为了联盟！"
D.Strings[21754]="觉醒教派的出现让许多流亡者感到迷茫。虽然他们称自己的目的很单纯，可他们过去已经误导过我们太多次了。\n\n希望他们说的都是真的，但目前我们还是先拭目以待吧。"
D.Strings[21755]="我这里出售超出你想象的神奇发明的结构图！\n\n想要看一看吗？"
D.Strings[21756]="准备好把那些破破烂烂的旧皮革变成有用的东西了吗？"
D.Strings[21757]="你应该也看出来了，我很忙。\n\n你要买什么东西吗？"
D.Strings[21758]="日安，$G先生:女士;，需要我帮你销毁什么东西吗？"
D.Strings[21759]="呱！"
D.Strings[21760]="对稀有宠物有兴趣吗？我的小宝贝们可是最棒的！"
D.Strings[21761]="你得去暴风城，找奥黛丽·伯恩赫普聊聊！城里的任何一名守卫都能为你指路。\n\n法师塔里就有通向暴风城的传送门。祝你好运！"
D.Strings[21762]="别忘了掩盖你的足迹。"
D.Strings[21763]="<瑞秋礼貌地向你点点头。>$B$B你好。"
D.Strings[21764]="<瑞秋看着自己的工具。>$B$B还有很多工作要做呢。"
D.Strings[21765]="<瑞秋耸了耸肩。>$B$B我不太爱说话。"
D.Strings[21766]="我知道一些法术可以修复你的装备——但这是收费的。"
D.Strings[21767]="我马上就能复制出埃匹希斯控制器了。"
D.Strings[21768]="噢，你说的一定是我的父亲，贝洛克。他和神圣遗物学会的所作所为很难被称为是“考古”。那更像是盗墓。$b$b真正的考古学是搜寻真相，而不是宝藏。我希望了解历史，研究我们的起源，发掘失落的知识。"
D.Strings[21769]="$R，我一直致力于训练安苏的守护者们。你愿意协助我吗？"
D.Strings[21770]="你受到了朝圣者祭坛的祝福。一种祥和宁静的感受包裹着你。"
D.Strings[21771]="这座岩石雕像散发出祥和的光环。上面的一块铭牌写着：$B$B受阿达尔的光辉祝福的人将获得韧性和护甲值，能够对抗最具挑战性的敌人。$B$B德欧里的祝福能让你在需要时得到治疗。$B$B卡拉指引着受祝福者的武器，让他们能在战斗中获得额外的攻击机会。$B$B克乌雷则会嘉奖虔诚的信徒，让他们变得像风一样迅捷。"
D.Strings[21772]="德拉诺出产的材料既神秘又神奇。\n\n只要一点钱，我就可以教你驾驭它们的力量。"
D.Strings[21773]="以鸦母的羽毛保证，你绝对找不到比这更划算的买卖了！"
D.Strings[21774]="让我看看你的货物。"
D.Strings[21775]="类似哈里森·琼斯那种江湖骗子可能不赞同我的做法，可石化需要数千年的时间！$b$b保存稀有而神奇的生物的最佳方法就是自己动手！$b$b既然你自己就能做得更好，何必要等上几千年让大自然来完成演化呢？"
D.Strings[21776]="<见你靠近，波兹尔疯狂地挥舞起手臂来。>$b$b哇！嘿！谁在那儿？$b$b噢，抱歉……自从遇到那个该死的……艾克加纳克后，我的视力就不大行了。"
D.Strings[21777]="你问我这些双头飞龙是不是从钢铁部落那里偷来的？$b$b那得看是谁问了！"
D.Strings[21778]="你看起来是个爱冒险的家伙！$b$b如果你在外面找到什么遗物或神器，请把它们带回来给我。我们可以做笔买卖！"
D.Strings[21779]="你的订单已经提交了。"
D.Strings[21780]="你好像是指挥官啊……嗝儿！我一直都在对付兽人！……嗝儿！"
D.Strings[21781]="最近，有许多冒险者来到阿什兰。有些人是在赚钱的，其他人则是来帮助联盟对抗部落的。\n\n你想在这里得到些什么呢，朋友？"
D.Strings[21782]="我已经好几年没来过这样的野外了。$B$B<威严的大法师深吸了一口气。>$B$B再也没有比清新的空气和危险更迷人的味道了。"
D.Strings[21783]="如果要我说，这个任务应该交给我来负责。可大法师卡德加坚持说你会带来惊喜。"
D.Strings[21784]="我身上还有恶魔第一次入侵艾泽拉斯时造成的伤口。我还记得那种笼罩在被毁灭的城市上空的恐怖、疯狂和寂静。$B$B我会尽我所能防止这种惨剧重演。"
D.Strings[21785]="我不明白为什么会有人投靠燃烧军团。$B$B那都是些渴望力量，又不懂得如何运用它的家伙。"
D.Strings[21786]="萨格雷的村庄就像一个蜂窝。$B$B要是我们惊动了里面的居民，一定会被叮得满头包。可如果烧掉它，又会损失宝贵的蜂蜜。$B$B唯一的办法就是通过潜入来获取我们需要的信息。"
D.Strings[21787]="我们的任务无比艰巨，但却是必要的。"
D.Strings[21788]="你听说过我吗，$n？我是隶属于六人议会的大法师茉德拉，肯瑞托和达拉然的统治者之一。$B$B如果我愿意，我可以彻底夷平这座村庄。$B$B可那不是我们来这里的原因。根据我多年来学到的经验，有时你只需要一点蜂蜜就能引来苍蝇。"
D.Strings[21789]="我是个大师级的说客，可萨格雷似乎更看重实力，而非语言。$B$B赢得他们信任的最快办法就是战斗。我相信这就是茉德拉派你来帮我的原因。"
D.Strings[21790]="数千年前，燃烧军团的恶魔来到我们的家园，为我们的领袖送上一份大礼。$B$B其中的两位，基尔加丹和阿克蒙德看出了他们的提议中所蕴含的智慧，可最后一位领袖，先知维伦却拒绝了。$B$B他和他的追随者逃出了那个世界，被那些曾向他们伸出友谊之手的人永世追杀。$B$B维伦是个蠢货！而作为这些蠢货的后裔，我们仍旧拒绝天堂的召唤！$B$B但一切到此为止了，我的兄弟们！今天，我们将臣服于恶魔领主。他们又给了我们一次分享力量的机会。$B$B我的兄弟姐妹们，这，才是我们真正的命运。今天，我们要踏上艾瑞达的先驱们走过的道路，未来将属于我们！"
D.Strings[21791]="燃烧军团的行动决不能再受干扰。德拉诺有一些人想要阻挠他们的计划，尤其是那些无信者——那些依然追随圣光的德拉尼。$B$B去消灭我们的同胞，确保我们的主人免受干扰。击败那些德莱尼人，向燃烧军团表明我们的忠诚。只要毁灭沙塔斯，恶魔就将赐予我们不朽的荣耀！"
D.Strings[21792]="我们德莱尼是天选的民族……文明、优雅，具有高度的智慧。$B$B世间没有我们的头脑无法理解的技术，也没有我们的法师无法掌握的魔法。$B$B我们在阿古斯建立了辉煌灿烂的文明。$B$B我们的人民从不沉迷也不畏惧自己的潜力。$B$B我们的人民注定要征服星辰大海！$B$B团结起来吧，兄弟姐妹们，让我们夺取理应属于我们的一切！"
D.Strings[21793]="小心阴影，指挥官。"
D.Strings[21794]="我经过长期艰苦的努力才获得为你效力的机会，指挥官。$B$B这真是我的荣幸。"
D.Strings[21795]="你的故事已经流传甚广了，$c。请允许我为你复述一下你最了不起的一些事迹。"
D.Strings[21796]="别来烦我！这些人类带来了让你流口水的肉！看看吧！想象一下，一口咬上去，用牙撕裂纤维，吞下去时，肉汁从骨头里涌出…… \n\n<这头狼人的眼神迷离了……>\n\n你想要什么来着？"
D.Strings[21797]="你好，$r。$B$B我能从你的举手投足中看出你不是普通的冒险者。$B$B德拉诺是一个严酷的世界，许多宫殿和墓穴中都潜伏着危险的敌人。它们想要用可怕的武器和魔法毁灭这片土地。如果能占领这些地方和它们的宝藏，你和你的同伴一定能获得不菲的收益。$B$B但是，在这些地方容不得半点懈怠，因为其他冒险者也会紧随而至，只有和时间赛跑才能证明你无与伦比的实力！$B$B你准备好迎接德拉诺的新挑战了吗？"
D.Strings[21798]="我把戒指弄丢了，该去找谁换个新的，或是再领一个呢？"
D.Strings[21799]="这不可能！你的戒指是精妙的魔法工艺的最高杰作，是无可替代的无价之宝！$b$b不过，我的法师塔外面的佐提·轮怒就是化不可能为可能的专家。或许你可以用一些金币换取他的援手。$b$b但我不能保证。"
D.Strings[21800]="我能送你飞去任何地方……当然是要收费的！"
D.Strings[21801]="我没时间闲聊，大元帅泰布雷德急需坦克帮忙对付部落。$B$B我把扳手放哪儿了……"
D.Strings[21802]="我对今天能来到这里感到超级激动！"
D.Strings[21803]="你想学习哪种专业技能呢？"
D.Strings[21804]="祝你今天交好运！"
D.Strings[21805]="希尔达·铜丝是暴风之盾的首席工程师。\n\n你可以在镇中心的工坊里找到她。"
D.Strings[21806]="你在这里做什么，凡人？\n\n我把毕生的精力都用来守护这些古代传送门了。如果你想激活它们，就需要获得一些名为食人魔道标石的古代神器。"
D.Strings[21807]="你没有游戏代币。等你至少弄到1个代币之后再来找我吧。"
D.Strings[21808]="我准备好了，开始把达拉然传送到破碎群岛吧。"
D.Strings[21809]="军团正在全力向我们发动攻击，我们已经没有多少时间了。\n\n我们即将释放的奥术能量冲击波应该足够暂时将他们送回那个被诅咒的次元空间，给我们争取一个喘息的机会，同时也让我们能有时间寻找创世之柱。\n\n你准备好了吗？"
D.Strings[21810]="我想离开这里。"
D.Strings[21811]="这片林地很危险，你要我送你离开吗？"
D.Strings[21812]="苹果树的水果货车通常停在达拉然的西南部。"
D.Strings[21813]="你可以在魔法商业区的坦克用品店二楼找到采矿训练师和供应商，就在达拉然的西北部。"
D.Strings[21814]="你真走运！魔法商业区刚刚开了一家叫作“往日纪念”的新商店。"
D.Strings[21815]="守护者大厅是位于达拉然中心的魔法焦点。"
D.Strings[21816]="守护者大厅"
D.Strings[21817]="部落的访客主要集中在达拉然东北方的风行者圣殿。$B$B那里有旅店，也有通向不同城市的传送门。"
D.Strings[21818]="联盟旅客主要集中在达拉然西南部的灰牙领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。"
D.Strings[21819]="克拉苏斯平台在达拉然的最东边。$B$B城市的飞行管理员就在那里。"
D.Strings[21820]="你可以前往达拉然东北部的部落区，去风行者圣殿的“肮脏的野兽”瞧一瞧。$B$B听说那里非常脏乱，但是有一位很棒的烹饪训练师。"
D.Strings[21821]="英雄之家位于达拉然西南部的灰牙领地旁边。$B$B那里不仅设有露天啤酒店，还汇集了全城最好的烹饪训练师。"
D.Strings[21822]="一个满是盗贼与罪犯的藏污纳垢之地，味道也令人难以忍受。$B$B至少有三条路可以进去：东边、西边以及北边的入口。"
D.Strings[21823]="达拉然下水道"
D.Strings[21824]="如果燃烧军团的恶魔觉得老安古斯已经完了，那么他们就有麻烦了！我会的把戏比达拉然的法师还多！"
D.Strings[21825]="管好你的舌头！戴斯蒙娜不是驴子，她是一头骡子！\n\n总之，我用她换了三份萨格拉斯之血。我想做双靴子。"
D.Strings[21826]="等你弄到了足够的抑魔金粉尘，你就可以把它们团成一个小球，然后把它涂在你的手工护甲上，你的护甲就会变得更强大。"
D.Strings[21827]="这很简单！你知道拿几件制作出来的装备——帽子啊、指环啊、圣物啊、合剂啊之类的——然后把它们扔进这家伙喷火的小嘴里。再加上一些萨格拉斯之血当燃料，然后轰得一声！你就能得到抑魔金了！\n\n你知道的，那些工匠总是用邪能球茎、邪钢和混沌水晶来做装备。总之那种护甲里全是恶魔的材料。你只要给这些恶魔材料加热，就能得到抑魔金啦！"
D.Strings[21828]="嘿，$n！你想要拆解装备吗？或许你想用抑魔金来强化你身上的装备？那你就找对矮人了！有话就说吧！"
D.Strings[21829]="这真的很简单。去摆弄一下那个盒子，就能开始一轮游戏了。你只要在所有格子都被填满前走完它显示出来的路线，就能赢得游戏。只要多赢几次，你就能激活那个盒子了。"
D.Strings[21830]="在它划过天际的时候，你只要留在任意宝珠的范围内，就能一直飞翔了！你看，我现在就是这么做的！一直跟着宝珠飞，看看它们究竟指向哪里。"
D.Strings[21831]="你想听听过去的故事吗，$n？"
D.Strings[21832]="风中有血腥味。"
D.Strings[21833]="这是你的船，$n。愿圣光与你同在。"
D.Strings[21834]="<骑上大嘴。>"
D.Strings[21835]="<大嘴警惕地盯着你。>"
D.Strings[21836]="大地之环与你同在，先知！我们将不惜一切，与你并肩对抗燃烧军团！"
D.Strings[21837]="我们进去吧！"
D.Strings[21838]="你准备好进入天文台了吗？"
D.Strings[21839]="我准备好了，可以前往卡拉赞了。"
D.Strings[21840]="你得跟卡德加一起找到创世之柱，$n！"
D.Strings[21841]="我们去救麦格尼吧！"
D.Strings[21842]="你准备好了吗？我要驱散这道屏障了。"
D.Strings[21843]="给我们点时间准备一下，$n。$b$b去帮助城市抵挡燃烧军团吧，或是用你的地图去找一处入侵点并阻止他们。$b$b等能够开始后，我会召唤你的。"
D.Strings[21844]="我会召唤初代提瑞斯法守护者阿洛迪的灵魂。你准备好了，就告诉我一声。"
D.Strings[21845]="开始召唤。"
D.Strings[21846]="你可以说话了。"
D.Strings[21847]="<向瓦尔托伊出示塔莉萨的徽记。>"
D.Strings[21848]="再跟我说说伊利丹吧。"
D.Strings[21849]="肯瑞托感谢你的帮助。"
D.Strings[21850]="你有勇气帮我们击败燃烧军团吗？"
D.Strings[21851]="你感觉到森林里的生命了吗？我们已经保护了这片土地那么多年，但是到了现在，仅凭我们的力量已经没办法保护这里了。你愿意帮助我们吗？"
D.Strings[21852]="<他一言不发，警惕地盯着你。>"
D.Strings[21853]="<她一言不发，警惕地盯着你。>"
D.Strings[21854]="这事等不得。恶魔已经混入你们中间。让我帮你把他们揪出来吧。"
D.Strings[21855]="我叫泽拉，我是宇宙定序时期诞生的第一批纳鲁之一。"
D.Strings[21856]="<凯赛尔·夜棘的尸体几乎无法辨认。他受到了残酷的折磨，而后伤重而死。>"
D.Strings[21857]="$n，是你啊。\n\n当时我们正在追踪一个恐惧魔王。不幸的是，他将我们引入了陷阱。"
D.Strings[21858]="安息吧，老朋友。"
D.Strings[21859]="阿莎，你自由了。"
D.Strings[21860]="我都跟他们说了会这样。\n\n我早就告诉他们了。\n\n有谁听了？！"
D.Strings[21861]="告诉我，$c，你见识过达拉然的神奇货物吗？如果你找不到想要的东西，我或许可以指点你一下。"
D.Strings[21862]="这个模块看来早就失去了能量源。"
D.Strings[21863]="我看看我们收集到的其他神器的消息。"
D.Strings[21864]="<这头魔刃豹被燃烧军团禁锢住了，但使用远古魔力让水晶过载可以释放这头野兽。>"
D.Strings[21865]="我准备好了。去奥杜尔吧！"
D.Strings[21866]="我们最好快一点，$n！"
D.Strings[21867]="这些貌似普通的武器蕴藏着隐蔽的力量。"
D.Strings[21868]="看起来很久没人用这泉了。"
D.Strings[21869]="如果我们不能阻止萨维斯，梦魇就会吞噬艾泽拉斯。"
D.Strings[21870]="<这个防御矩阵似乎缺少能量。>"
D.Strings[21871]="我的技术无与伦比！$b$b但我听说来了个竞争者。有人在城外开了个铁匠铺。$b$b我喜欢挑战。放马过来吧！哈哈哈！"
D.Strings[21872]="啊哦。$b$b你的护甲好像需要修理了。"
D.Strings[21873]="欢迎光临。我能为你做点什么吗？"
D.Strings[21874]="我想把炉石绑在这里。"
D.Strings[21875]="我想交易。"
D.Strings[21876]="今天你的火焰烧得真旺，$n。"
D.Strings[21877]="无论你做什么，都不要吃碗里的果子。$b$b那玩意儿的质量太差了。如果你想尝尝苏拉玛最好的美食，就让我来给你展示一下真正的美味吧。"
D.Strings[21878]="<这头魔刃豹盯着你，你身上可能有它想吃的东西。>"
D.Strings[21879]="卓格巴尔的袭击害得我们拿不出多少东西来招待客人，但我们的就是你的，英雄。"
D.Strings[21880]="随便选一张石床吧，伙计。纳瓦罗格说你可以在这里休息。"
D.Strings[21881]="你很快就能在我这里用金币或是职业大厅资源换取破碎命运印记了。但我现在还没有东西可以提供给你。"
D.Strings[21882]="你好啊，亲爱的。希望你不要介意，凯恩让我帮忙把你的一些部队传送过来。\n\n看来燃烧军团已经在那座岛上站稳了脚跟。他认为我们最好别让他们占领整个阿苏纳。\n\n别担心。如果有需要的话，我可以将伊利达雷送回邪能之槌号，也能将他们再送过来。只要你有需要，他们随叫随到。"
D.Strings[21883]="他们把我们像畜生一样赶到一起。我不知道他们要把我们送去哪儿，可我知道我不想去。求求你……"
D.Strings[21884]="别让他们带走我！"
D.Strings[21885]="我不想死，可他们会杀掉所有逃跑的人。"
D.Strings[21886]="那些上了船的人再也没有回来……别让他们带走我。"
D.Strings[21887]="求求你……帮帮我……"
D.Strings[21888]="$n，燃烧军团派出了手下最强大的恶魔来对付我们。他们肯定不想输掉这场第三次大战，不将我们彻底从艾泽拉斯抹去，他们是不会罢手的。\n\n我们应该携起手来，好好“报答”他们的这番“深情厚谊”。"
D.Strings[21889]="$n，战斗进行得怎么样？你需要补给或是修理装备吗？"
D.Strings[21890]="非常抱歉，$n。我刚来这里侦察法罗纳尔的燃烧军团部队时受伤了。\n\n我还能为你做些什么吗？"
D.Strings[21891]="感谢你挽救了法罗纳尔的战局，$n。\n\n我真不敢相信，赛娅娜居然叛变了。她背叛了我们所有人。还有其他人也成为了魔誓者。我们会追杀他们到天涯海角，让他们给燃烧军团的新主子陪葬！\n\n我发誓！"
D.Strings[21892]="感谢你来法罗纳尔帮忙，$n。我很尴尬，我们中居然出了一个叛徒，变成了燃烧军团的魔誓者。\n\n我们会让他们付出代价的。"
D.Strings[21893]="你来带领伊利达雷抵抗恶魔，我来研究一下我们在阿苏纳的下一步行动。\n\n我们必须找到创世之柱。我知道它就在这里的某个地方。"
D.Strings[21894]="$n$g大人:女士;。我们非常感谢你能来领导我们战胜燃烧军团。"
D.Strings[21895]="你好，$n。在你的领导下，法罗纳尔的燃烧军团一定会迅速灭亡的。"
D.Strings[21896]="$n，你能来真是太好了。主母为我们的部队开启了往返邪能之槌号的传送门，以便我们巩固这里的防御力量。\n\n燃烧军团已经入侵了法罗纳尔地峡。我有一个计划，可以在他们占领整个阿苏纳之前拦截并击溃他们。\n\n我需要你帮忙带领伊利达雷走向胜利。"
D.Strings[21897]="再次感谢你把我从那些海巨人手里救出来，$n。"
D.Strings[21898]="你！你就是他们所说的那个$ct吧？所以这个“大地之环”是听你指挥的，对吧？$b$b好吧，我们是恐怖图腾的人！我的氏族已经跟元素沟通了上百代人了。你有什么权力把这片圣地据为己有？$b$b你在这里囤积的资源是我们大家的。按照巫婆长老玛加萨的命令，我要拿走属于我们的那一份！"
D.Strings[21899]="我向来欢迎富有成效的工作关系。"
D.Strings[21900]="营业中。"
D.Strings[21901]="我向来耳聪目明。我可以把我知道的告诉你……但这是有代价的。"
D.Strings[21902]="<阿鲁因对你点点头。>"
D.Strings[21903]="外面的战斗怎么样了，$c？看到什么值得剥的皮了吗？"
D.Strings[21904]="这些兽人建筑可能不如幽暗城的墓穴那么舒适，但原木比碎石好搬运多了。"
D.Strings[21905]="过去，我们的风俗是将族长放进小船，推进海里，然后点燃船只。但自从我们的海岸被迷雾笼罩后，我们就不敢这么做了。否则他就会变成克瓦迪尔，再度归来。"
D.Strings[21906]="一个好领袖、好朋友就这么走了。等我死后，但愿能与他在英灵殿再大战一场。"
D.Strings[21907]="你看起来有点与众不同，凋零者……"
D.Strings[21908]="我是来保护大酋长的。如果你敢对大酋长拔刀相向，那在你的鲜血落到地面之前，你就已经死了。$b$b至于其他的……那不关你的事。明白吗？"
D.Strings[21909]="现在不行！"
D.Strings[21910]="你知道纳萨诺斯为什么看起来那么……与众不同吗？"
D.Strings[21911]="我看着像是要找死的样子吗？我是说，像是想再死一次的样子吗？$b$b如果你对凋零者的脸感兴趣，你就去问他本人吧，或是去问黑暗女王也行。他们都很乐意跟你聊天的。$b$b<黑暗游侠冷冷一笑，又回到自己的岗位上去了。>"
D.Strings[21912]="我们不能失去希望，$ct。就算我们能打败燃烧军团，也需要新一代的萨满来治疗这个千疮百孔的世界。"
D.Strings[21913]="走开，我在工作呢。人群中可能有敌对分子。"
D.Strings[21914]="<这个盲萨满听到了你靠近的脚步声。他抬起手触摸着你的脸庞。>\n\n啊，$ct。我听出了你自信的脚步声。<咳嗽>。万灵正与你同行，它们与你的目标是一致的。\n\n自从我在德拉诺首次听到元素的召唤，已经过去了许多年。你回去过吗？我听说有人通过某种方法……回去过了……<喘气>。我不敢再看昔日的故乡了。那个黑暗与战争来临之前的德拉诺。\n\n对，但你显然不是来听一个老兽人废话的。你没有像别人那样看待我。我的年纪……<咳嗽>这把轮椅……我可不像别人以为的那么脆弱。我的力量依然强大，就在我们周围的岩石和轻风里。"
D.Strings[21915]="我已经准备好了！"
D.Strings[21916]="你好啊。好消息！我的书终于到了，至少大部分都到了。\n\n你看起来还有点糊涂，我再解释一下吧。你瞧，达拉然上一次整体传送时，我的一些书也因此损坏了。所以这一次，我让它们飞来我们的新地址。没错，就是用飞的。\n\n不幸的是，它们才飞到卡兹莫丹上空时，我们又传送了。大部分的书籍上周才刚刚抵达，并回到了城市各处。有一些还在借阅它们的同事手里，很快就会自行返回。事实上，如果它们再不回来，我就得去调查了。"
D.Strings[21917]="如果你饿了，我们有食物。如果你渴了，我们有饮料。如果你累了，我们有床铺。$b$b如果你来这儿是别有用心，那你最好是个深藏不露的高手。"
D.Strings[21918]="我思念我的妻子，更思念我们的女儿。\n\n在这里，我至少能静静地怀念她们。"
D.Strings[21919]="这地方……有点古怪。\n\n<希尔维林整了整袖口。>\n\n但这总比送命强。\n\n我想我应该感谢你，因为你敢于行动。我是个懦夫，但至少玛尔迦没有白死。\n\n我欠你一份人情。"
D.Strings[21920]="葛拉什很难钻进这个洞里。我不知道其他萨满会不会像我们一样接受他。"
D.Strings[21921]="<葛拉什难过低地下了头。>$b$b好吧。"
D.Strings[21922]="<你的回答让这个海巨人非常高兴。>$b$b<波涛语者安德莉等着你。>"
D.Strings[21923]="$n！你真是我的好朋友！$b$b下一次，葛拉什一定要去抓一条大船，掰开它，把所有人都倒进水里，告诉他们：“$N是最好的萨满，哈哈哈！”"
D.Strings[21924]="多年来，我一直在高特兰克的山脚下观察并等待，跟万灵交流，用元素之力锻造强大的武器。$b$b我能理解万灵的奇思妙想。我知道只要你愿意做出牺牲，那你的命运是可以被指引和塑造的。$b$b$ct，好好建设这座圣地吧，我就会给你塑造命运的力量。$b$b在那一天到来之前，我会一直观察并等待着。"
D.Strings[21925]="看起来你已经准备好让世界燃烧了。噢，我能跟你一起去就好了。"
D.Strings[21926]="看看他们，尽情放纵，就像燃烧军团不存在一般。去教育他们一下什么是现实吧？"
D.Strings[21927]="我准备好了，可以前往苏拉玛了。"
D.Strings[21928]="你需要破碎命运印记吗？"
D.Strings[21929]="你需要召唤元素吗？"
D.Strings[21930]="嘿，伙计！$b$b我就送你三句话：升级！升级！升级！虽然我还是个新人，可我知道怎么让你的部队发挥出潜力。我能让你的火更旺，水更急，地更猛，风更狂！"
D.Strings[21931]="噢，你好，欢迎来到达拉然。我是路灯保养员。"
D.Strings[21932]="你准备好观看榨汁演示了吗？"
D.Strings[21933]="你决定好了吗，$ct？$b$b我可以指导你，但你得自己做决定。"
D.Strings[21934]="没有比大清早来一杯咔啡，或是在经过一天的血战后来一杯冰凉的至高岭冰咖啡更舒服的。在临睡前，我喜欢喝一杯香料茶。你试过配上蜂蜜的羊角包吗？非——常——美味！$B$B至少我是这么觉得的。但你知道吗，我其实不是来谈咖啡的。"
D.Strings[21935]="枯法者已经准备好了。我们开始吧。"
D.Strings[21936]="很好。我们可以在法兰纳尔塌方的隧道里训练。$b$b你准备带几个枯法者去？"
D.Strings[21937]="我是来帮助枯法者进行战斗训练的。"
D.Strings[21938]="以前，我曾指引我的丈夫古伊尔走上萨满的道路。但他的下一个试炼只能由他独自走完。那你呢？你的道路是什么？$b$b你是要代表自然之力摧毁我们的敌人？还是成为智慧之泉，明察秋毫，完成万灵的愿望？或是成为一个治疗者，抚慰伤痛，提升士气？我告诉你一个真相吧，$n：$b$b真正的萨满必须能达到以上这三种境界。"
D.Strings[21939]="我的部族完了，$n。那些在大灾变中逃过一劫的难民都在雷霆崖避难。有一些勇士在决战奥格瑞玛时牺牲。剩下的则都战死在破碎海滩了。 $b$b现在，大地之环就是我的家，$ct。我向你保证，我会为它战斗到底的。$b$b今天我能为你做点什么吗？"
D.Strings[21940]="风在窃窃私语着你过去和现在的事迹。如果我知道正确的提问方式，就能从它们那里得到许多消息。"
D.Strings[21941]="伊利丹之手。我能为你做点什么吗，主人？"
D.Strings[21942]="当然，我要一架。"
D.Strings[21943]="你好啊，$g帅哥:靓妹;！如果你要去达拉然巨坑的话，最好小心点，摔下去可不得了。\n\n我手头正好有几架滑翔机。如果你有需要的话，我可以卖一架给你。\n\n10金一架。\n\n我们不接受退款！"
D.Strings[21944]="我准备好了，维伦！"
D.Strings[21945]="你准备好从拉基什手中救出沃洛斯，并解开圣光之心中的秘密了吗？"
D.Strings[21946]="恶魔杀害了我的大部分萨满。我们退到了这里，准备背水一战。$B$B<努波顿叹了口气。>"
D.Strings[21947]="<将神秘的缚光物体放在地上。>"
D.Strings[21948]="让我们开始吧。"
D.Strings[21949]="夜眼去侦察动物园了。但愿他能照顾好自己！"
D.Strings[21950]="夜眼又出去巡逻了。希望他这次能一路平安。"
D.Strings[21951]="小心，$r。夜之子受到了鼓动，正在离开他们城市的边境。"
D.Strings[21952]="一切都在按计划进行。你不用担心。"
D.Strings[21953]="哪怕是对你而言，下一个任务可能也太过危险了，小个子的外来者。先好好磨练一下再回来找我吧。\n\n只有这样，你才有可能战胜纳格法尔号并活下来。"
D.Strings[21954]="所有人都必须团结起来，才能击败燃烧军团。"
D.Strings[21955]="你对克瓦迪尔了解多少？"
D.Strings[21956]="海拉的国度控制着那些弱者的灵魂，而那些光荣战死的战士将穿过勇者之门面见奥丁，并接受训练，为最后的决战做准备。但海拉，那个心怀嫉妒的女巫，不满足于被分给她的那些灵魂。\n\n于是，她创造了克瓦迪尔。这些生前强大的维库人被她的邪恶魔法扭曲腐蚀。他们永远效忠于她，为她掠夺生者的灵魂，满足她对死亡的无尽渴望。\n\n他们就像一场瘟疫，外来者，纯粹的瘟疫。"
D.Strings[21957]="你知道自己看到的是什么吗，小个子的外来者？这是蔑潮的命运，那时他们还没有被潮水淹没。\n\n是那个邪恶的海巫海拉，她的怒火吞噬了他们的舰队，她邪恶的迷雾击溃了最强大的维库战士。族长们别无选择，只能放弃大海，因为战斧和长剑无法斩杀迷雾和海水。"
D.Strings[21958]="噢，我亲爱的鲁文……\n\n他是个非常自以为是的孩子，非常傲慢。我早就知道，他有一天一定会把巨大的力量据为己有。\n\n但是……我想的不是这样。噢，我的孩子……"
D.Strings[21959]="我的鲁文大人承诺过，如果他能晋升到皇宫，就会给我那种力量。而我相信了！我还制定了计划！\n\n如今他死了，我每次露面都会招来瞪视。我好羞愧。\n\n他这样的人为何会堕落至此？"
D.Strings[21960]="我曾经是鲁文大人的贴身侍从。如今我却只能给那些暴躁而又娇惯，还没有实权和影响力贵族递送酒水和甜食。\n\n真可悲。"
D.Strings[21961]="你处理好这里的事情之后就告诉我，然后我们就可以离开了。"
D.Strings[21962]="多么神奇的发现，$n。这个装置似乎有某种机关保护。"
D.Strings[21963]="我准备好了，努波顿！让他们来吧！"
D.Strings[21964]="这些魔网能量球似乎遵循着某种运动轨迹？我很好奇它们会指向哪里？"
D.Strings[21965]="你准备好前往黑鸦堡垒了吗？"
D.Strings[21966]="你能帮我修理装备吗？"
D.Strings[21967]="让我们继续研究我的神器吧。"
D.Strings[21968]="你说得对，把一切都告诉我吧，洛拉姆斯。"
D.Strings[21969]="你好，$n。为了达成互信，我想我应该解释一下。"
D.Strings[21970]="你好，亲爱的，很高兴见到你。\n\n我能帮你什么忙吗？"
D.Strings[21971]="破碎者向你致敬。"
D.Strings[21972]="伊利达雷随时为你效劳。"
D.Strings[21973]="你好，$n。我能为你做点什么吗？比如一份最新的侦察报告，或是燃烧军团在艾泽拉斯的行动报告？"
D.Strings[21974]="那好吧，你想要什么？"
D.Strings[21975]="对，对！靠近点，朋友！$B$B我看到你手里有些好东西！朋友需要些什么呢？来几件小饰品怎么样？"
D.Strings[21976]="烧得好，小鬼。烧死那些纳迦。"
D.Strings[21977]="地表的纷争与此地无关，萨满。希望你能妥善解决这件事。"
D.Strings[21978]="艾泽拉斯之心就位于这个世界元素力量的汇聚点上。全艾泽拉斯，没有比这里与元素联系更紧密的地方了。"
D.Strings[21979]="你想要招募元素吗？"
D.Strings[21980]="我们脚下的世界时刻都在变幻着，$ct。作为一个萨满，我们必须随时准备调整自己以适应它。\n\n或许你需要改变一下你那把武器中的成分？元素随时倾听着你的要求。\n\n我可以说服它们改变一下你的神器中力量流动的方式——作为回报，它们只需要神器中释放出的一小部分力量。"
D.Strings[21981]="如果我再年轻一点，就可以让这些劣魔领教一下我的利爪和尖牙了。"
D.Strings[21982]="我们最近一直有人失踪，还有人看到死人复活，古老的要塞也重新点亮了灯火。有邪恶的力量正在作祟，这一点没有疑问。如果你是来帮忙的，那就沿着这条路去找鲑鱼溪的镇长吧。但是要小心点，镇长身上的压力太大了。"
D.Strings[21983]="如果你想的话，我可以帮你改变这对战刃里的力量。\n\n但你别忘了！这种改动是有代价的。"
D.Strings[21984]="请把你带来的东西拿给我看吧。我们没有多少时间了。"
D.Strings[21985]="这个箱子被一种神秘的力量锁住了，无法当场打开。$b$b你可以解散你的部分枯法者部队，并让他们把它带回去交给塔莉萨。"
D.Strings[21986]="结束了。那两个邪魂恶棍都死了，他们再也别想回来了。\n\n你准备好之后，我们就能返回邪能之槌号了，$n。"
D.Strings[21987]="<这根柱子冰冷而安静。>"
D.Strings[21988]="在保护艾泽拉斯之心时，大漩涡之柱耗尽了力量。它会缓慢恢复，但这个过程需要几十年，我们可等不起。我们得想办法加速它的恢复。"
D.Strings[21989]="魔力酒越来越难剩下了……但只要我们有，我们都会和城里的穷人分享。"
D.Strings[21990]="我只希望这点能够用。城里有那么多嗷嗷待哺的人……"
D.Strings[21991]="凯丽娅和瓦雷迪斯就躲在这个指挥中心里。要想攻破它，我们就需要援助。\n\n我建议让阿卡玛将邪能之槌号移动到攻击位置，轰击那道邪能屏障。"
D.Strings[21992]="我的精神……越来越恍惚了……需要魔力酒……"
D.Strings[21993]="你看起来很强大……你一定有多余的魔力酒！"
D.Strings[21994]="求求你……只要几滴魔力酒就能防止我发疯……"
D.Strings[21995]="好了，你都卖些什么？"
D.Strings[21996]="这是我最喜欢的环节！这香味，这质感，还有这欢快流淌的酒液！亲手酿造过魔力酒之后，你就会明白我为什么会留在酒庄了。"
D.Strings[21997]="我们要开始制作原浆了。你做好帮忙的准备了吗？"
D.Strings[21998]="噢，事实上我很好。"
D.Strings[21999]="我为什么要不高兴？学生们都在大厅里，从来都不睡觉。他们不停地要吃的，整个地方都是一团糟。到处都是水！而他们有雇人来帮忙吗？没有！他们说了，费尔里奇会搞定的。我已经下了最后通牒，让他们弄走那些该死的书。\n\n现在，“你”到底要什么来着？"
D.Strings[22000]="你看起来很不高兴。"
D.Strings[22001]="你想要什么？我在这里干了一万年，却没有得到过哪怕一点点尊重。费尔里奇干这个，费尔里奇干那个。费尔里奇到底能为你干点儿啥？"
D.Strings[22002]="你消灭了这里所有的恶魔，可还有更多在前头等着我们。如果我们想要找到凯丽娅和瓦雷迪斯的话，就得从他们的副官中间杀出一条血路来。\n\n只要你一声令下，我们就动手。"
D.Strings[22003]="你是个幸运的$g家伙:姑娘;。你可以挣脱锁链，走出大门了。$b$b高尔克可以轻易挣断锁链，可高尔克能挤出大门吗？不能。"
D.Strings[22004]="荣耀的时刻即将到来。入侵尼斯卡拉意味着我们所有的牺牲和期待都将实现。\n\n带领我们走向胜利吧，$n。"
D.Strings[22005]="我当时没有意识到。"
D.Strings[22006]="对，有一位老师曾经提起过……"
D.Strings[22007]="我想请你带我去找高戈奈斯潮汐之石。"
D.Strings[22008]="<玛尔迦叹了口气。>\n\n局势对我们很不利。我们动辄就被打击流放。但你和首席奥术师会跟我们站在一起的。我对此深信不疑。\n\n我相信暮色百合。\n\n不过，我们已经抱怨得够多了。你准备好结束参观了吗？"
D.Strings[22009]="他们真是——我恨他们！我们尽力讨好他们，换来的却是流放和死亡。可在大魔导师把这里列为禁区的时候，我什么也做不了。\n\n你肯定有着庞大的关系网络才能进入这里。反抗军的队伍又壮大了吗？它真的能对抗艾利桑德吗？"
D.Strings[22010]="那么……你到底来这里做什么？对于反抗军的成员来说，这是绝对是最危险的地方之一。"
D.Strings[22011]="那我就放心多了。不过，我们还是接着走吧。"
D.Strings[22012]="害虫？你碰上虫害了？\n\n<玛尔迦古怪地看了你一眼。>\n\n没关系。你看，答案就在你眼前。法力浮龙会吃那些蚕食树木的害虫。它们能保护我们珍贵的植物，而且胃口很好。\n\n在参观途中，我会安排时间让你抓一些浮龙的。"
D.Strings[22013]="<玛尔迦紧张地看了看四周，然后靠近你，压低了声音。>\n\n既然其他人还在阴影中行动，那塔莉萨一定还活着。除了首席奥术师，还有谁能发起这样的行动呢？\n\n告诉我——她还好吗？"
D.Strings[22014]="我已经听过传闻了……但美好得有些不真实。\n\n请原谅——我们得小心行事，决不能引起任何怀疑。他们……对我们很苛刻。"
D.Strings[22015]="请随意参观吧。"
D.Strings[22016]="喜欢这个酒庄吗？"
D.Strings[22017]="我希望有一天我们的部族能迎来真正的和平。"
D.Strings[22018]="再也没有比准备装桶的新鲜酒浆更美妙的香味了。自己动手试试吧，那你就明白了！"
D.Strings[22019]="又一个品酒家？你愿意帮我准备原浆吗？"
D.Strings[22020]="啊……你是来学习古老的酿酒技艺的吗？"
D.Strings[22021]="我行走在这片土地上，不断观察，聆听。$b$b也许这就是你以前没见过我的原因，没什么好怀疑的。"
D.Strings[22022]="不要盯着看太久。对于我们这些上流人士来说，这地方没什么稀奇的。"
D.Strings[22023]="蝙蝠拍蝙蝠。$b$b蝙蝠拍蝙蝠。"
D.Strings[22024]="曾经有一个古老的寓言，是关于一个樵夫的。他在森林着火时去砍树。$b$b“你怎么还在砍树？”人们问他，“森林着火了。你的房子很快也会被烧到的。”$b$b樵夫看着熊熊的大火，深吸了一口浓烟。“那我该变成什么人呢？”他问，“我就是我。”$b$b<达里尔又砍了一捆木头。>$b$b这里头并没有什么寓意。"
D.Strings[22025]="我是食人魔。彻头彻尾的食人魔。当然不是……不是食人魔了。"
D.Strings[22026]="梦魇能吞噬一切，$c。它会从内部腐蚀你。它能轻松击溃你的意志，肆意在大地上横行。$b$b我们的心灵都将不可避免地被暗影笼罩，所有的希望都将熄灭。$b$b这太可怕了。这……太美妙了……"
D.Strings[22027]="<卡普里纳散发着动物毛皮和粪便的臭味。>$b$b你看什么呢，$c？你干嘛不去烦克劳福德或是希斯罗？"
D.Strings[22028]="但愿我的战友们能比我过得好些。"
D.Strings[22029]="我会将苏拉玛从燃烧军团手中解放出来的，但我首先得恢复力量。$B$B而且我们需要一个计划……"
D.Strings[22030]="<塔莉萨抬手抚摸着自己憔悴的脸庞。>$B$B我的身体状况恶化得太快了……$B$B看来我们夜之子每一天都是在刀锋上跳舞啊。"
D.Strings[22031]="别人都看不见我，可我喜欢看着他们忙忙碌碌的样子。这真是太激动人心了。一直以来，这里都只有我和伊利丹的仆从。\n\n唉，可惜我已经被永远困在扭曲虚空了。我再也不能离开这里了，$n。\n\n但这都是值得的，如果重来一遍，我还会那么做的。我还是会牺牲自己，站在那里让你打倒我，来为最后一座传送门供能，并召唤出你的恶魔大军。这是为了我们的事业必要的牺牲。\n\n哪个恶魔猎手会拒绝呢？\n\n伊利达雷万岁！"
D.Strings[22032]="守护者雷姆洛斯似乎非常疲惫和茫然。他差点被枭兽干掉。"
D.Strings[22033]="艾露恩的光芒不再照耀这个洞穴中的枭兽。他们变成了可怕的野兽，威胁着所有人的安全。"
D.Strings[22034]="送我去托里姆峰顶。"
D.Strings[22035]="送我去托林尼尔避难所外的托里姆峰。"
D.Strings[22036]="送我去碎风小径顶端。"
D.Strings[22037]="如果你有需要，我可以把你送回山顶。"
D.Strings[22038]="你准备好就叫阵吧。"
D.Strings[22039]="那个邪能领主洛查伯肯定就躲在那里。我可不想为了追杀一头恶魔到大门附近去。那样我们就得从几百头恶魔里杀出一条血路了。\n\n在关押他的过程中，我发现了一件事。这家伙很傲慢。所以，我准备当着所有人的面向他叫阵。\n\n<玛拉丝勉强忍住了很不适合守望者的咯咯笑声。>\n\n你准备好就告诉我一声吧，恶魔猎手。"
D.Strings[22040]="<这个法师的目光闪躲着。>$b$b我能为你做点什么吗，$c？我……我还……我还有事呢。"
D.Strings[22041]="奥鲁丹，我要飞往风暴峡湾。"
D.Strings[22042]="这些恶魔为我们提供了许多情报。燃烧军团的邪能秘术可以让我们更加强大。他们迟早会死在自己的秘密手上。\n\n那么，我能帮你什么忙呢，$n？"
D.Strings[22043]="山谷已不复往日之美。\n\n恶魔决心侵占这片地方，但是我要奋战到底，不到最后一刻决不放弃。\n\n我没有忙着抵御入侵者时，就会花时间精研附魔，以此来对抗他们。\n\n总有一天，我们会夺回月爪谷。"
D.Strings[22044]="你好，$n。我能为你做些什么吗？"
D.Strings[22045]="你完成了一件了不起的壮举，将我们全都带到了这里。我们重新坚定了决心，也有了周详的计划，我毫不怀疑我们一定能赢得这场战争。\n\n等到这一切全都结束，燃烧军团的威胁彻底消失后，我们的牺牲也就值得了。"
D.Strings[22046]="我让这些恶魔猎手紧张了。我这个小老头。来自洛丹伦的特德。呵呵。$b$B记住，在被邪能灌注的古代精灵地盘上，擅长放逐术的农夫也能称王。"
D.Strings[22047]="虽然我的剑在渴望恶魔的鲜血，但我得到的命令是严密监视它们。$b$b这些灵魂行者非常了解这个区域以及那些可能威胁到我们部队的灵体，这些情报对我们都是无价之宝。$b$b只要他们还有用，我们就会继续为他们提供庇护和补给。"
D.Strings[22048]="自从胡恩的时代，我的家族就守护着这片墓地！我们自豪地照料着高贵的亡者，用我们的技巧指引他们的灵魂，并向他们学习。$b$b现在，全怪该死的鲜血图腾部族——如果他们还这么称呼自己的话——我必须向外来者求助了。$b$b这真是个黑暗的年代。"
D.Strings[22049]="无论你想怎么做，我们都会支持你的，$n。但我得提醒你，他背叛过主人，直接导致了我们被囚禁以及伊利丹的死亡。\n\n要不是阿卡玛的话，燃烧军团可能已经被击败了。虽然我们希望他能充当我们的顾问，但他过去的行为说明他并不可靠。\n\n你不要误会，主人说我们应该招揽阿卡玛，所以我也同意这个计划。不过，他听起来并不怎么理智。\n\n我和阿莱利准备了一个备用计划，以防万一。"
D.Strings[22050]="那点酒根本不够我们两个喝的……所以我选择自己忍着，让她少受点苦。"
D.Strings[22051]="<他面无表情地盯着你。>你不是我的兄弟。"
D.Strings[22052]="好、好……饿……意识都……模糊了！"
D.Strings[22053]="他、他们更需要它……我没、没事……"
D.Strings[22054]="看来我别无选择了，阿卡玛。无论如何，你必须帮我们打败燃烧军团。"
D.Strings[22055]="我是不会帮你的，恶魔猎手。和其他恶魔猎手一样，你并不比跟你厮混的那些恶魔强多少。我看不出你跟他们有什么分别。\n\n燃烧军团和你的主子摧毁了我美丽的神殿。相信我，总有一天，我会复仇的。\n\n滚回虚空去发疯吧，$n。"
D.Strings[22056]="我知道了，凯恩。但愿他能理智一点，否则的话……"
D.Strings[22057]="回家的感觉真不错，哪怕只是短暂的停留。或许有一天，我们能为伊利达雷夺回这座神殿。\n\n不过现在，让我们看看能不能说服阿卡玛加入我们……或是怎么样吧。\n\n你准备好之后，就告诉我们一声吧，$n。"
D.Strings[22058]="我们上去吧，凯恩。是时候说服阿卡玛加入我们了。"
D.Strings[22059]="我不喜欢这里……\n\n<吸鼻子。>"
D.Strings[22060]="噢，我们……跟他们做了一笔交易。\n\n对，他们想让我们带着这些东西飞去达拉然，然后把它们卖掉。毕竟，在这里没有多少人会买它们，对吧？而且，还有比地精更出色的推销员吗？ \n\n那些牛头人真有生意眼光！"
D.Strings[22061]="你干嘛把牛头人的货物都搬到你的飞艇上去？"
D.Strings[22062]="我敢肯定，那些牛头人随时都会回来的。\n\n但在此之前，我能帮你什么忙吗，伙计？"
D.Strings[22063]="你的家人都在圣锤之座呢。"
D.Strings[22064]="什么？拜托对着我这只没毛病的耳朵说好吗？"
D.Strings[22065]="很壮观，不是吗？"
D.Strings[22066]="旅行者，有什么可怕的东西正在酝酿之中。我感觉得到。"
D.Strings[22067]="$c，请不要再耽搁了。我无法想像，失去了塞纳留斯的话，这个世界会变成什么样！"
D.Strings[22068]="在我的时代，我会将利刃交给军队。你们呢，凡人？你想要什么？"
D.Strings[22069]="我们银行的安保措施一流，你哪怕是想拿回自己的东西也会遇到麻烦的！哈哈！"
D.Strings[22070]="毒药，毒药，这里！自从我们早死之后，这就成了我们家族的招牌产品。"
D.Strings[22071]="唔……呱？"
D.Strings[22072]="<鸦熊们都已就位，准备开始仪式了。 \n\n它们似乎在等你。>"
D.Strings[22073]="我没带多少东西，但也许有你想要的。"
D.Strings[22074]="我得回到城里去，越快越好。"
D.Strings[22075]="我或许会对你的建议感兴趣……如果有足够的刺激的话。"
D.Strings[22076]="拿起驭风大师的图腾。"
D.Strings[22077]="你有什么需要吗？"
D.Strings[22078]="艾泽拉斯之心里蕴藏着巨大的能量。在艾泽拉斯，恐怕没有比我们现在脚下的土地更接近元素的地方了。"
D.Strings[22079]="这地方不安全，不要乱晃，快走开。"
D.Strings[22080]="别东张西望的，陌生人。"
D.Strings[22081]="希望你的表现能比上一个偷酒贼强些，愿他安息。"
D.Strings[22082]="需要我载你一程吗，陌生人？"
D.Strings[22083]="<泰林似乎有些神志不清了。>"
D.Strings[22084]="我会尽力帮助塞纳苟斯的，但我得催你尽快行动了，$n。我担心他可能撑不了多久了。\n\n其它地方也还有事情需要我去关注，我必须尽快离开。但是，我会尽快赶回来的。\n\n"
D.Strings[22085]="欢迎，$c。你对附魔感兴趣吗，还是来帮忙对抗纳迦的？"
D.Strings[22086]="虽然不再拥有肉体，可拿回附魔棒让我觉得自己又活了过来。$b$b如果你想向我学习附魔技艺，只需要带一些材料来作为交换就行了。"
D.Strings[22087]="我这里什么工具都有……只要你出得起钱。"
D.Strings[22088]="我跟这个……术士的交易……只是一种权宜之计。$b$b我想要了解这个生物，深入研究它。如果有必要的话，我也会在它对这个世界的过大于功之前杀了它。"
D.Strings[22089]="谢谢你，$r。你已经证明了自己是一个真正的盟友。但愿你能在这片土地上施展力量，对抗邪恶。"
D.Strings[22090]="你究竟是敌是友，$r？如果你自认是森林之友的话，那就证明给我看。帮我击退这股威胁到我家园的腐蚀吧。"
D.Strings[22091]="我们想要组织一次深入扎赫纳尔的探险，但那片废墟发生了太多的古怪事件。"
D.Strings[22092]="所有能拿得动锤子和钳子的蠢货都能打铁，但只有大师级的工匠才能将奥术的精华融入他的作品中，锻造出兼具灵巧和威猛的武器。"
D.Strings[22093]="你肯定听说过上古之战吧。如果你去问至高岭牛头人的话，他们肯定会告诉你，是他们打败了提克迪奥斯。\n\n不过他们确实帮了忙。事实上，他们帮了大忙。你想听听我的故事吗？"
D.Strings[22094]="<如果你有草药的话，可以把它种在这里。>"
D.Strings[22095]="<种一朵花？>"
D.Strings[22096]="莉莉丝让你去一趟，有关那批暮色百合豆荚的事。"
D.Strings[22097]="训练就要开始了，你们准备好了吗？"
D.Strings[22098]="<看到你靠近，凡瑟尔突然停下话头，怀疑地盯着你。>$B$B安纳瑞斯，你想干什么？你不用继续去讨好那些恶魔了吗？"
D.Strings[22099]="我来自波涛起伏的大海。潮汐之王响应了你的召唤，大地之环的先知。"
D.Strings[22100]="这场胜利修复了梦境，保护了你们的世界。萨维斯一伙不会罢休，但至少这次他们无法得逞。"
D.Strings[22101]="我听说了你为河鬃部族所做的一切。$b$b在达拉然第一次见到你时，我可没想到你会帮上我们这么大的忙。$b$b这真是太感谢你了。"
D.Strings[22102]="我们需要你帮忙和地底之王谈判。"
D.Strings[22103]="我刚从鲜血图腾部族的地盘回来，可我听说你帮助了我的同胞。\n\n我很羞愧，像你这样的外来者竟然比我们自己的兄弟部族更愿意帮助我们。"
D.Strings[22104]="跟我来。莉莉丝想跟你谈谈。"
D.Strings[22105]="直接……杀了我吧。"
D.Strings[22106]="我是不会坐视恶魔撕碎这个世界的。$B$B夜之子是时候站出来，在艾泽拉斯赢得一席之地了。"
D.Strings[22107]="唔，你可真迷人，不是吗？"
D.Strings[22108]="很高兴见到你，莉莉丝夫人。"
D.Strings[22109]="啊，你肯定就是希尔格林跟我提过的那个外来者。"
D.Strings[22110]="宴会还不错吧？"
D.Strings[22111]="我是不会走的，孩子。不要说了。什么地底之王都不能把我从我的家园吓跑。"
D.Strings[22112]="这些勇士快要死了。他们已经走不动了了。"
D.Strings[22113]="没时间了。快跑！"
D.Strings[22114]="他们没有给我足够的时间来收拾财物。你说它们安全吗？我可不想让那些卓格巴尔来翻检我的私人物品。"
D.Strings[22115]="这些邪教徒都被暮光蒙蔽了……甘愿避世隐居，躲在黑夜之中。"
D.Strings[22116]="<这个侍从默默无语。>"
D.Strings[22117]="再次感谢你给了我为大义而献身的荣耀。现在你应该明白了，我愿意为执行伊利丹大人的计划而付出一切。我们必须不惜一切代价摧毁燃烧军团。\n\n我欠你的太多了，$n。\n\n现在，就由你去完成我们未竟的任务吧，找到萨格里特钥石，带着胜利返回黑暗神殿。\n\n伊利丹大人在等着你。"
D.Strings[22118]="求你了，小声点！$b$b如果被他们发现我跟你说话的话……他们会杀了我的！"
D.Strings[22119]="我对你不感兴趣。我来自苏拉玛的一个声名远播的裁缝世家。而你显然不是。"
D.Strings[22120]="你需要治疗吗？"
D.Strings[22121]="嗯，你有事吗？我正忙着准备下一个庆典呢。"
D.Strings[22122]="对，我是个德鲁伊而且……呃……我大概要保持这个形态一段时间了。$b$b我在破碎海滩周围的海域里巡逻时，一头地狱火掉进水里，正好砸在了我头上。冲击力令我当场昏迷。$b$b等我醒来时，就已经在这里接受护士们的照料了。他们说，过几天我就能有足够的力量变回去了。而现在，我得呆在这个装置里，以防脱水。$b$b帮我个忙，别把这事告诉其他德鲁伊，不然我肯定会被他们笑话一辈子的！"
D.Strings[22123]="你在看什么呢？没见过海狮吗？"
D.Strings[22124]="你想要我的帮助，可你却没什么可以回报我的，$r。如果是这样的话，你或许能帮我的部族一个忙。$b$b我们已经有好几年没喝到过河鬃部族的药酒了。他们的药酒有着提神醒脑的功效，而且对牙齿有好处。幸运的是，我刚好知道这种药酒的酿造方法。$b$b我会把我的研钵和捣杵，还有药酒的配方给你。你为我的部族带回足够的药酒，我就帮你修复这个烧瓶。$b$b成交吗？"
D.Strings[22125]="蛇女巫。她就在里面。$b$b葛拉什很……害怕。$b$b那个蛇女巫会用她的魔杖控制葛拉什的。"
D.Strings[22126]="天空之墙真是个神奇的地方，$n。我这辈子都没见过类似的地方。"
D.Strings[22127]="难道就没有人愿意站出来反抗艾利桑德了吗？"
D.Strings[22128]="<用力眨眼睛。>"
D.Strings[22129]="你好吗，我的夜之子同胞？"
D.Strings[22130]="我们怎么才能摆脱燃烧军团的阴影？"
D.Strings[22131]="术士向来不可靠。万一古尔丹背叛我们怎么办？"
D.Strings[22132]="<嘲弄地>恶魔。我说对了吗？<你翻了个白眼。>"
D.Strings[22133]="有话快说——我的装扮要动起来才会更好看。"
D.Strings[22134]="<叹气。>$B$B我还以为这次我的打扮肯定是最特别的了，但看来我又输了。"
D.Strings[22135]="你在普通装扮下又穿了……外来者的装扮？$B$B多么天才的想法！"
D.Strings[22136]="自从屏障消散以来，这里的安保措施就更严格了。我们不能把任何暴民放进来，不是吗？"
D.Strings[22137]="你这身装扮……真是……特别。"
D.Strings[22138]="呃，我听说有人扮成了猫头鹰。$B$B好吧，我们中总有一个人得换掉……"
D.Strings[22139]="对，我这件礼服最漂亮了。谢谢你的称赞。$B$B虽然它害得我一动都不敢动，但这不算什么啦。"
D.Strings[22140]="我每次都告诉自己，要在这些派对上多交些朋友，可最后总是被甜点吸引。"
D.Strings[22141]="这座庄园很豪华，对吧？光是在这里走走，就让我感觉到了安宁。"
D.Strings[22142]="在我的国度里小心点，萨满。先知也可能被烧伤……"
D.Strings[22143]="隔壁有个蛇人。大蛇人。$b$b葛拉什闻到鱼腥味儿了。"
D.Strings[22144]="欧申克这家伙总是用“螺丝刀”来拧螺栓。难道他都没听说过锤子吗？"
D.Strings[22145]="唔……你进来的时候没有看到任何核能炸弹对吧？没有吧？好吧，我会继续找的。"
D.Strings[22146]="我今天还没有炸到任何人呢。真是个好日子。"
D.Strings[22147]="让我看看你最新的货物。"
D.Strings[22148]="我们去月神殿。阿什阿拉的速度更快，让它载我们一程吧。你做好离开的准备了吗？"
D.Strings[22149]="我是无人能及的情报贩子。$B$B你只要知道这一点就够了。"
D.Strings[22150]="你来这个无法无天的地方做什么？"
D.Strings[22151]="你要去杀蛇女巫？$b$b你要抢走魔杖？$b$b好啊！葛拉什要帮忙！"
D.Strings[22152]="我是葛拉沙尔之子葛拉什。$b$b那个蛇女巫用魔杖控制了我们。那些跟她作对的人都被杀害了。$b$b你是来杀那个蛇女巫的吗？"
D.Strings[22153]="很高兴见到你，朋友。"
D.Strings[22154]="但愿我们不算太迟。"
D.Strings[22155]="我以荣誉起誓，你一定会安然无恙，女祭司。"
D.Strings[22156]="我要集中精神理解这个幻象。\n\n我们有过许多分歧，但此事事关重大。我能相信你吗？"
D.Strings[22157]="我的目标是尝遍这片土地上的美酒。只要有酒有朋友，你就没什么可担忧的。"
D.Strings[22158]="不，不，我来自雷霆崖。我是个冒险者，和你一样。这些至高岭牛头人对我来说同样很陌生。\n\n但我是胡恩·高岭的热心研究者，他是这片土地上有史以来最伟大的牛头人之一。这个“之一”或许都能去掉。至高岭，将是我了解他的最佳地点。"
D.Strings[22159]="你就住在雷霆图腾吗，莱莎？"
D.Strings[22160]="<高阶考察者居高临下地看了你一眼。>\n\n难道你没听说过神圣遗物学会吗，$r？\n\n当然，我们追求的是力量。这片土地的地下埋藏着大量无价之宝。上层精灵遗失的奥术技艺比你我所了解的更多。我想找到他们失落的遗物，并让它们的力量为我和我的人民所用。\n\n好了，别再问东问西的了。"
D.Strings[22161]="我的故事已经传到城市外头去了吗，还是我们有共同的熟人……"
D.Strings[22162]="是塔莉萨派我来的。"
D.Strings[22163]="你是希尔格林吗？"
D.Strings[22164]="你很大胆，居然敢靠近我，外来者。"
D.Strings[22165]="这里的腐蚀比我所见过的任何地方都要严重……玛法里奥，坚持住。"
D.Strings[22166]="<埃洛瑟尔对外界刺激彻底失去了反应。>"
D.Strings[22167]="<埃洛瑟尔瘫软的身体空洞地凝视着远方。>"
D.Strings[22168]="<埃洛瑟尔的躯壳毫无反应。梦魇已经控制了它。>"
D.Strings[22169]="让我看看他们的故事吧。"
D.Strings[22170]="我想你应该听说过胡恩·高岭，但你听说过这个部族里其他人的故事吗？他们也是上古之战中的英雄。"
D.Strings[22171]="多亏你，我才活了下来，曼格拉斯也死了。在更多恶魔涌来之前，我们快离开这里吧。$b$b我想我知道一条出去的近路，跟我来！"
D.Strings[22172]="每个人都要选择自己的道路。"
D.Strings[22173]="你准备好了吗？这里有许多神器等着我们去发掘呢。"
D.Strings[22174]="就是想出去走走。我可能会去参观动物园。你最近去过那里没有？"
D.Strings[22175]="我必须说声抱歉，但我现在没时间跟你谈话。我等在等人。"
D.Strings[22176]="多么美好的一天啊，真是美好。"
D.Strings[22177]="在喷泉里钓鱼可能没什么意思……但总比在下水道里钓鱼强。"
D.Strings[22178]="把鱼饵挂在鱼钩上，把鱼吃进肚子里。$b$b你可别把这两个步骤搞混了。"
D.Strings[22179]="你最近见过纳特吗？"
D.Strings[22180]="首先，我们会护送你前往阿格拉玛的宝库。之后，我们再去斯考德-艾希尔的惊魂港汇合。$B$B这应该会是一段平稳的航程。"
D.Strings[22181]="黑暗女王将指引我们走向胜利。"
D.Strings[22182]="我希望有一天能成为莱莎那样伟大的人，让她为我骄傲。"
D.Strings[22183]="你好，冒险者。我叫莱莎。你也跟我一样，是来研究至高岭的牛头人的吗？"
D.Strings[22184]="查看燃烧军团在艾泽拉斯的位置。"
D.Strings[22185]="魔血剧烈地沸腾着，表面下出现了一些模糊的影像。"
D.Strings[22186]="你好，$n。我很高兴你响应了萨尔的召唤。$b$b你也看到了，这里没有阵营之分。我们都是大地之环的幸存者，大家必须团结一致，否则只会被各个击破。$b$b幸存者们还在陆续从艾泽拉斯各地赶来。照顾好他们，抚平他们的伤口。要想让他们重返战场，我们就要给他们希望，$n。你必须鼓舞起他们的斗志！"
D.Strings[22187]="这地方到处都是泰坦的建筑。为什么我知道，因为北边那座山上就有一座巨型泰坦大殿！"
D.Strings[22188]="欢迎来到历史的残片！$b$b你有兴趣学习考古学吗？"
D.Strings[22189]="穆菲努斯，请允许我为你介绍$n，他帮助我们救出了诺莫瑞根的幸存者。"
D.Strings[22190]="跟我来，$n，我会把你介绍你的训练师，穆菲努斯·铬酒。"
D.Strings[22191]="我准备好了，我们前往阿苏纳吧，卡德加。"
D.Strings[22192]="在救出丝黛拉苟萨后，你就获得了一个强大的盟友。\n\n得知蓝龙军团幸存下来，我很欣慰，虽然他们也只是勉强逃过一劫。我们必须前往蓝翼栖地与这位塞纳苟斯谈一谈。\n\n如果说还有人能指点我们找到创世之柱，那就一定是他了。"
D.Strings[22193]="我的宝贝书籍……"
D.Strings[22194]="<索迪尔毫无生气地躺在泥泞中。>"
D.Strings[22195]="一支纳迦大军都不可能战胜索迪尔族长。只有他们恶毒的背叛才有可能打败他。"
D.Strings[22196]="<这个维库人几乎没有注意到你的到来。>"
D.Strings[22197]="无论你的猎物是什么，拉兹克的小玩意儿都能包你命中目标。"
D.Strings[22198]="无论你的猎物是什么，拉兹克的小玩意儿都能包你命中目标。\n\n他的最新原型机已经装好了弹药，随时可以发动。去武器架上拿一把，开始享受射击的乐趣吧。\n\n但记住，你得自己承担测试风险！"
D.Strings[22199]="我注意到你没有戴耳环。需要我为你介绍一副栓动力卡宾枪箍吗？它们还没怎么生锈呢！"
D.Strings[22200]="无论如何，你又有什么损失呢？"
D.Strings[22201]="你想知道吗？"
D.Strings[22202]="这算是威胁吗？$B$B需要我提醒你，你是在我的监狱里，被我的卫兵包围着吗？"
D.Strings[22203]="没时间解释了。让我们进入堡垒，守望者。"
D.Strings[22204]="让我们进去，否则我就让你看看我们到底有什么不同。"
D.Strings[22205]="我不相信你们，“恶魔猎手”。$B$B在我看来，你们和燃烧军团没有什么不同。"
D.Strings[22206]="我们曾经依赖一种魔力的本源精华。这种药剂甚至能够媲美永恒之井。$B$B再想想我们现在只能依赖一些残羹冷炙。$B$B<瓦尔托伊的嘴唇嫌恶地扭曲起来。>"
D.Strings[22207]="<瓦尔托伊没有反应。她的表情说明她正忍受着巨大的痛苦。|cFFF92304必须首先满足她的饥渴，然后才能进行其他行动。|r>"
D.Strings[22208]="无论你要打什么样的猎物，我这儿有一样武器肯定能让你如愿以偿。"
D.Strings[22209]="记住，无论你把谜题弄得多么乱，最后总是有办法解决它的，图腾如此，生活同样如此。认识到这一点或许会让你觉得欣慰一些。$b$b但是，新的开始有时也是大有裨益的。"
D.Strings[22210]="图腾迷阵在等着你，$c！触摸图腾来转变它以及它周围图腾的属性，将所有图腾都变成水图腾吧。"
D.Strings[22211]="你将会看到一个五纵五横的元素图腾迷阵。里面有火图腾，也有水图腾。你的目标就是把它们都变成水图腾。$b$b你只要触摸图腾就可以转变它的属性。啊，但元素是互相关联的！触摸图腾也会转变与它相邻的四个图腾的属性。$b$b经过耐心的尝试，也许还会犯一些错，你一定可以将所有图腾变成水图腾的。加油吧，$c！$b$b如果你感觉自己彻底失败了，就跟我说，我可以帮你重置迷阵。"
D.Strings[22212]="要想与元素和谐共鸣，你必须研究并理解它们之间的交互作用。图腾迷阵是一种古老的训练方法，一种挑战你头脑和精神力的谜题。$b$b目标是将所有图腾都变成水图腾。触摸图腾就可以转化它。记住，万事万物都是互相关联的，这就是这个谜题教给你的最宝贵的一课……也是你一生中最重要的一课！"
D.Strings[22213]="让我看看我们的战利品。"
D.Strings[22214]="没有谁会嫌恶魔“死得太多”的。"
D.Strings[22215]="那个夜之子骗了我们。月之守卫很快就会消亡。"
D.Strings[22216]="我从一个地底之王的手下那里偷了一块能量宝石。$b$b使用这块宝石，你就可以获得一个听命于你的水晶之怒了。$b$b请你用它到水晶裂隙那里多弄点水晶回来。有了那些水晶。我和我的部族就可以更好地协助雷霆图腾……无论他们想做什么。$b$b那就这么说定了？"
D.Strings[22217]="你好，$n大师。我们今天该做些什么菜呢？"
D.Strings[22218]="你们是逃出守望者地窟的恶魔猎手？$B$B你们从那些试图摧毁我们世界的家伙身上汲取力量。告诉我，我为什么要相信你们？"
D.Strings[22219]="<萨鲁法尔眯着眼睛上下打量了你一番。>$b$b卡德加跟我说，我们今天要会见恶魔猎手时，我还嘲笑他来着。当他说我应该听你把话说完时，我笑得就更大声了。$b$b可是，你还是来了。$b$b我允许你独自进入要塞。但你得把武器和同伴留在门口。在我允许之前，你也不能乱说话。$b$B你要敢轻举妄动，我马上就用斧子劈了你。"
D.Strings[22220]="我听几个家伙说，黯石部族背叛了我们。很好！没有那些废物，我们会更强大。他们又瘦……又弱。还很矮。"
D.Strings[22221]="你迷路了吗，伙计？你看着像是迷路了。"
D.Strings[22222]="你应该去找蘑菇商人。他那儿应该会有长杆子。哈！"
D.Strings[22223]="别担心，伙计！很快，我们新的地底之王就会碾碎软弱的蠢牛和他们的盟友。之后，你这副小身板就不用上战场啦。"
D.Strings[22224]="新的地底之王会带领我们再次崛起的！"
D.Strings[22225]="你想找什么？快下来吧，兄弟。"
D.Strings[22226]="你的个子怎么这么矮啊，伙计？你看起来就像头小蠢牛似的，哈！"
D.Strings[22227]="伙计，你到底用力了没有？"
D.Strings[22228]="我很高兴你跟我来这里，$n。你恐怕已经察觉到我的计划了。"
D.Strings[22229]="你好，伙计。$b$b你想要乔装成卓格巴尔吗？你想要神不知鬼不觉地潜入啮岩孤地吗？你想混入偷了巴布尔私人配方的那群人中间吗？你想拿回巴布尔的配方吗？$b$b那就喝了这杯特制的药剂，变成他们中间的一员吧！$b$b如果你还需要更多药剂，可以回来找我。噢，还有，小心那些蜥蜴。"
D.Strings[22230]="凯恩一直是个忠诚的战士，无畏的领袖和杰出的战略家。$B$B可他对伊利丹的忠诚蒙蔽了他的眼睛。$B$B随着伊利丹的力量增长，他所吸收的恶魔力量开始失控。$B$B我知道我的行为可能会被视为背叛，可我只是做了我认为正确的事。$B$B现在，凯恩也开始走上伊利丹的老路。这样的人不能领导伊利达雷。"
D.Strings[22231]="你为什么不喜欢凯恩？"
D.Strings[22232]="很多年以前，伊利丹大人还控制着黑暗神殿时，受难者奥图里斯就跟我们的领袖以及恶魔猎手决裂了。$B$B奥图里斯认为伊利丹已经变成了他最痛恨的那种东西，并为此发动了一场邪恶的战争，导致了主人的陨落。$B$B他还害死了我们的四位战友——阿兰蒂恩、瑟拉斯、奈萨里尔和瓦雷迪斯。$B$B他们是我们的导师、我们的兄弟姐妹。$B$B所以，我无法原谅他。"
D.Strings[22233]="你和奥图里斯为什么那么合不来？"
D.Strings[22234]="是凯恩还是奥图里斯？"
D.Strings[22235]="<欧库勒斯语无伦次地小声自言自语着。|cFFF92304必须首先满足他的饥渴，然后才能进行其他行动。|r>"
D.Strings[22236]="我饿了，可我会继续前进的。"
D.Strings[22237]="我正在迅速衰弱。塔莉萨呢？"
D.Strings[22238]="塔莉萨就在梅瑞戴尔附近。你能把我们传送过去吗？"
D.Strings[22239]="赫米特和他的猎人们每到一个地方，就会带来死亡和毁灭，为了一时之快而屠杀无辜的动物。\n他们必须为自己反自然的罪行付出代价。\n\n如果这片盆地里的动物会说话，它们肯定会向我们求助的。让我们把这场游戏变得更加平衡一点，让那些猎人也尝尝被狩猎的滋味。\n\n我会把你变成生活在这一地区的某种动物的样子。你变形之后，那些猎人就会变成你的猎物。\n\n你准备好了吗？"
D.Strings[22240]="我们是不会认输的。我们是伊利达雷。"
D.Strings[22241]="有话快说。我的行动决定了我不能引起任何不必要的注意。"
D.Strings[22242]="诺瓦的牙齿最锋利了。"
D.Strings[22243]="太忙了。总是有事情做！\n\n聪明的工人抓老鼠。最聪明的工人点蜡烛。\n\n其他人……去挖矿。"
D.Strings[22244]="鹰身人喜欢亮晶晶。\n\n我们用宝贝换蜡油。\n\n做最大的蜡烛！"
D.Strings[22245]="老鼠比兔子更美味，而且更好抓。"
D.Strings[22246]="老鼠不怕黑。"
D.Strings[22247]="老鼠是很好的挖掘工，否则至少也是一顿美餐。"
D.Strings[22248]="好的，杰斯，我这就用我的幽灵视觉来查看一下洞穴。"
D.Strings[22249]="$n，我认为这个洞穴里藏着某个非常强大的东西。但由于马顿已经被大量邪能彻底渗透了，所以我也无法确定。我的视线非常模糊。\n\n如果里面真有东西的话，那我们决不能忽视它。你的幽灵视觉比我们都要强，仅次于伊利丹大人。\n\n你能用幽灵视觉看看这座洞穴，确认一下我的怀疑吗？"
D.Strings[22250]="我们的单向礼物发放数量已达上限。该上限每日重置一次。"
D.Strings[22251]="向议会陈述你的想法吧，卡德加。"
D.Strings[22252]="这次会议可能不太愉快。你准备好了吗，$n？"
D.Strings[22253]="我能帮什么忙吗，大法师？"
D.Strings[22254]="战斗怎么样了？看来达拉然是才出狼窝，又入虎穴啊。$b$b不过这里至少暖和一些。我也必须承认，在离卡拉赞这么近的地方勾起了我不少的回忆。"
D.Strings[22255]="老鼠是好朋友。除非老鼠敢咬我，咬我的老鼠都变成了美餐。"
D.Strings[22256]="燃烧军团的力量正在增长。我们不能再浪费时间了。"
D.Strings[22257]="今天的风要将你吹向何方呢？"
D.Strings[22258]="我做好出发的准备了。"
D.Strings[22259]="我们这里有全世界最珍奇的货物。$b$b你想要什么呢？"
D.Strings[22260]="我决定了，瑟维斯。我要你来为传送门供能。"
D.Strings[22261]="当然，我很乐意为我们的事业付出一切。又有哪个恶魔猎手会拒绝呢？"
D.Strings[22262]="等等，瑟维斯。我再考虑一下。"
D.Strings[22263]="在伊利丹大人打败了他们的前主人，深渊领主玛瑟里顿之后，这个破坏魔和许多其他恶魔都宣誓效忠于他。我们还有纳迦、破碎者和其他生物为我们效劳。\n\n如果外域之王没有意见的话，那我觉得这样已经足够了。"
D.Strings[22264]="你对破坏魔怎么看？"
D.Strings[22265]="你是来对付贾布尔的吗？是的话，就赶紧动手吧！"
D.Strings[22266]="我想看一下我们可以追求的武器。"
D.Strings[22267]="带我进入格罗玛什要塞吧。"
D.Strings[22268]="你比我想象中要强大，伙计。"
D.Strings[22269]="你的眼睛会欺骗你。不要相信它们！"
D.Strings[22270]="坩埚？我们可以用这个装置占卜其他人的下落，或者进行长距离的通讯。\n\n我们甚至可以用它来跟其他位面沟通。\n\n它需要用邪能驱动。目标的距离越远，仪式所需要的能量就越多。"
D.Strings[22271]="杰斯，这个虚空坩埚有什么用？"
D.Strings[22272]="<嗝儿>"
D.Strings[22273]="头儿听起来都不像是狗头人了。"
D.Strings[22274]="用你的矿镐从洞穴里储量最丰富的矿脉中挖掘珍贵的金属，将样品带回来给我。"
D.Strings[22275]="把这些洞穴里最强壮的那只蜥蜴拖到我脚下来！"
D.Strings[22276]="这是头儿自己发明的语言吗？一点都听不懂。"
D.Strings[22277]="到附近墓地里去偷墓穴里的金币。"
D.Strings[22278]="什么蜡？头儿的话太难懂了。"
D.Strings[22279]="用最好的蜡制作魔法蜡烛，配得上蜡烛大王的蜡烛。"
D.Strings[22280]="<把靴子交给泰图斯。>"
D.Strings[22281]="<睁大眼睛，耐心地等待着他的报酬。>"
D.Strings[22282]="真正的英雄从不单打独斗。这个挑战需要你展现团队合作的谋略和能力。与你的搭档一起通过这个考验吧。$b$b你的队伍准备好了吗？"
D.Strings[22283]="想看看我的新款饰品吗？"
D.Strings[22284]="如果你的弹簧松了，我或许可以告诉你该怎么修好它们！"
D.Strings[22285]="我丈夫每次总是不收拾干净就跑了，让我来给他收拾烂摊子。$b$b如果你在达拉然遇见他，能不能告诉他一声，就说我爱他比他爱我要深得多？"
D.Strings[22286]="我听说卓格巴尔已经开始进攻白水溪和雷霆图腾了。$b$b这真是个黑暗的年代。"
D.Strings[22287]="这么说，你就是黑角提到的那个人？$b$b真是古怪的灵魂行者做出的古怪预言。$b$b要我说的话，这可真是太古怪了。"
D.Strings[22288]="洁儿想跟卓格巴尔谈判。没有其他部族的帮助，我们别无选择，只能想办法和平解决。"
D.Strings[22289]="你听说了吗？大酋长死了！$b$b卓格巴尔地底之王背叛了他。"
D.Strings[22290]="你想要什么，陌生人？"
D.Strings[22291]="圣光作证，珠宝可是我的老本行！$b$b我能为你做点什么吗？"
D.Strings[22292]="你的第一个试炼是力量的考验。这个维库人勇士也想代表他的氏族夺取风暴的武器。你们中只有一个人能通过这个考验。"
D.Strings[22293]="你早已声名远播了，$c。我听说你去过破碎海滩的前线。你比任何人都清楚我们的世界要面对的是什么。$b$b如果你想要获得风暴守护者莱登的武器，别忘了之前已经有许多人尝试过，但至今还没有人成功过。你将要面对一系列的挑战，但不要搞错了……武器本身才是最危险的考验。$b$b你打算继续下去吗？"
D.Strings[22294]="至今还没有人成功拿起过风暴守护者的武器。你会成为第一个吗？"
D.Strings[22295]="奥鲁丹，我有急事要去瓦尔莎拉。你能为我安排一下吗？"
D.Strings[22296]="正义终将获得胜利。我确信这一点。"
D.Strings[22297]="不要拿走蜡烛！如果蜡烛熄灭了，黑暗就要吃人了！"
D.Strings[22298]="你来指挥，我来帮忙！"
D.Strings[22299]="椅子空着。我坐，没人在意吗？"
D.Strings[22300]="大魔导师将许多夜之子逐出了苏拉玛。那些不同意与燃烧军团媾和的、政敌、还有她信不过的人都被赶出了城市。$b$b我们此时更需要团结起来。我将他们带了回来，让他们能再次汲取暗夜井的能量。我救出的人都恢复了魔法力量。我又给了他们一次为更加伟大的事业而奋斗的机会。"
D.Strings[22301]="我们将要迎来艰难的一天。"
D.Strings[22302]="不聊了！我得继续挖了！"
D.Strings[22303]="我挖！我找！我藏！"
D.Strings[22304]="我已经坐了一整天了。"
D.Strings[22305]="跟我说说胡恩的故事吧。"
D.Strings[22306]="<这个夜之子狐疑地打量着你。>$b$b如果你是来找麻烦的，那你就是个蠢货。快走开，否则我要叫巡逻队了。苏拉玛的力量将让你死无葬身之地！"
D.Strings[22307]="我会坚持我们的传统，直到有能够替代我的人出现。"
D.Strings[22308]="<这个元素生物对你做了个乞求的姿势，又指了指它身旁饥饿的鲨鱼。你听不懂它所说的语言。或许你该找个萨满来帮你翻译一下？>"
D.Strings[22309]="我准备好协助你了，玛法里奥。"
D.Strings[22310]="我欠你一个大人情，$n。再次感谢你。"
D.Strings[22311]="森林之神塞纳留斯。$b$b我从没见过他这个样子。保持警惕，朋友。我们脆弱的世界已经陷入了深重的危机之中。"
D.Strings[22312]="<瑟维斯付出的生命的代价，让你启动了军团传送门，并召唤出破坏魔大军。>\n\n<不要让他白白牺牲。>"
D.Strings[22313]="我想让你用我的力量来为传送门供能。"
D.Strings[22314]="蛛后肯定在这个传送门上做了手脚。靠莫尔葛已经没法没法打开它了。\n\n但是，恶魔猎手可以拼尽全力去开启它。你得做出选择了，$n……\n\n……我们谁来？"
D.Strings[22315]="<灰舌秘法师躺在这里，由于为军团传送门提供能量而晕了过去。>"
D.Strings[22316]="秘法师，感谢你的帮助。"
D.Strings[22317]="让我帮你一把吧。"
D.Strings[22318]="他们的行为太孩子气了。$B$B但我知道这是必然的。他们最好还是立刻解决他们间的分歧。"
D.Strings[22319]="<这片饱受折磨的大地在你脚下发出慑人的轰鸣声。作为萨满，你可以举行一个仪式来召唤并安抚愤怒的大地之灵……但也要做好战斗的准备。>"
D.Strings[22320]="我想我们刚好有合用的火把……"
D.Strings[22321]="蜡烛已经准备好了！只要有魔法火把，蜡烛大王就能做出最棒的蜡烛了！"
D.Strings[22322]="你真是我见过的最利落的杀人机器！要给你最好的奖赏……"
D.Strings[22323]="我在洞里发现了最大的蜥蜴！它现在已经死了！我的奖赏呢？"
D.Strings[22324]="你拿一块，剩下的归我。"
D.Strings[22325]="我在墓地里找到了亮晶晶的金币！好多，好亮。我该拿他们怎么办？"
D.Strings[22326]="挖石头，找亮晶晶！越亮越好。"
D.Strings[22327]="我来采矿！你别拿矿镐！你想去哪儿挖石头？想要金属吗？镐头有点钝了。"
D.Strings[22328]="做大蜡烛！好多蜡！"
D.Strings[22329]="你想让我做什么？去掉多余的毛发？准备蜡油浴？还是检查耳朵里的蜡？"
D.Strings[22330]="你要杀人吗？我的凿斧最锋利了！"
D.Strings[22331]="把洞里最大的那只蜥蜴带回来给我！"
D.Strings[22332]="还有什么吗？"
D.Strings[22333]="快去找亮晶晶！去挖死人的地盘。"
D.Strings[22334]="你想让我找什么？我有铲子！"
D.Strings[22335]="我以头上的角发誓，我要杀光这些纳迦！"
D.Strings[22336]="这真是个打猎的好日子。"
D.Strings[22337]="这些该死的堕夜精灵真是凶残。你是来帮我们对付他们的吗？"
D.Strings[22338]="我要是能多帮塞纳苟斯一点忙就好了。"
D.Strings[22339]="<这个维库人似乎已经失去了意识。>"
D.Strings[22340]="你把我的族人从邪能图腾以及他们的燃烧军团盟友手中救了出来。现在，我们愿意帮助你和你的高岭部族盟友对抗达古尔以及他的愚蠢追随者。"
D.Strings[22341]="不要害怕，我并不惧怕死亡。我很快就能和挚爱的妻子团聚了。你身边的这些英雄们都是和我一样的人。他们有自己的爱恨情仇，他们也懂得牺牲的意义，而这也将成为我生命的意义。$b$b<泰德里斯叹了口气。>$b$b或许你是对的，$n。我已经受够了族人们背负的耻辱。我曾以为我无路可走，也不会有人来帮助我。的确，我无法补偿我们所做下的一切。不管你怎么想，我并不是英雄。我只是饱经沧桑的老人而已。"
D.Strings[22342]="这座纪念碑不如周围其他纪念碑那么宏伟、那么著名，但这对我来说有着特别重要的意义。这里长眠着拉塔娜夫人，她是一位优秀的女猎手，也是我的妻子。噢，我真想念她。"
D.Strings[22343]="来了解一下我们的故事吧，外来者。它们蕴含着深刻的意义。"
D.Strings[22344]="脱下靴子休息一会儿吧。没有什么能比在星空下睡觉更舒服的了。"
D.Strings[22345]="欢迎来到坦克用品店。我们这里有锻造和采矿所需的各种优质物品。"
D.Strings[22346]="河鬃部族并不好战，但这种入侵我们神圣洞穴的行为决不能轻易放过。让卓格巴尔看看水系魔法的威力吧。\n\n悠久的历史带来智慧，而智慧则能带来力量！"
D.Strings[22347]="塔莉萨逃跑了？她总是那么理智。我很高兴她没有留下来，与大魔导师同流合污。$b$b可是，这也是徒劳的。我们的盟友稀少而分散，我们的敌人却有一个强大的靠山。我们不可能阻止他们的联军。$b$b来吧，如果你想得到我的硬币，就还有许多事要做。"
D.Strings[22348]="看看这座城市，$r。它是如此美丽，又是如此悲哀。$b$b我们都是龟缩在那个护盾下的懦夫。我们本该守护艾泽拉斯，可却选择了抛弃她。我们没有履行保护世界的神圣职责，这是我们最大的耻辱。"
D.Strings[22349]="这些邪恶的暴徒休想在我的宝贝林地里横行。"
D.Strings[22350]="我得集中精神准备献给女王的酒。我为什么会如此……不安？"
D.Strings[22351]="哈！看来阿维亚什没在来的路上把你扔进河里。很好！这说明他开始喜欢你了。$b$b我们可以开始完成仪式了吗？"
D.Strings[22352]="请送我去沉船海湾。"
D.Strings[22353]="元素选择了你作为他们的勇士，$n。你手中的神器就是证据。$b$b你的命运就是领导大地之环对抗燃烧军团。我们需要你。你愿意接受这份责任吗？"
D.Strings[22354]="看来你已经准备好挨揍了！"
D.Strings[22355]="曼瑟瑞尔，做好准备。我要把燃烧军团的秘密力量灌输给你。"
D.Strings[22356]="你准备好了解燃烧军团的秘密了吗，考瓦斯？"
D.Strings[22357]="要不是黑暗神殿遭到了攻击，我不介意在这里多呆一会儿。\n\n这里有太多恶魔可供我们杀了。"
D.Strings[22358]="凯恩，我要把我了解到的恶魔秘密传授给你。"
D.Strings[22359]="听好了，赛娅娜。这是我从邪魔之秘魔典中学到的知识。"
D.Strings[22360]="我不知道你怎么想，但为了活下来，我什么都愿意做。\n\n我们需要更多的力量！"
D.Strings[22361]="阿莱利，这是我发现的秘密。"
D.Strings[22362]="我们在这里的主要目标就是夺取萨格里特钥石。\n\n我们得先搞定下面的敌人，然后登上泰兰娜的浮空指挥中心。"
D.Strings[22363]="玛维还活着。我永远都不会忘记你的恩情的。"
D.Strings[22364]="鲜血图腾是个狡猾的部族，但我从没想过他们会接受恶魔的提议。我们必须在他们摧毁整个至高岭之前阻止他们。"
D.Strings[22365]="赫米特让你来教我打猎？\n\n我很高兴你愿意接下这个任务。我还有很多东西要学，但我起码还知道子弹是从枪的哪一头飞出来的……\n\n我已经准备好了，随时都能出发！"
D.Strings[22366]="$n，我们又在危险地带见面了。再次感谢你在河湾的帮助。但你和鲜血图腾打交道时一定要保持警惕。他们对外来者通常都不怎么友好。"
D.Strings[22367]="噢，你什么时候过来的，$c？"
D.Strings[22368]="跟我说说胡恩·高岭的故事吧。"
D.Strings[22369]="让开！你挡住我的枪口了。"
D.Strings[22370]="去别处打猎吧！"
D.Strings[22371]="我只是需要一点时间来考虑我的决定。现在我已经准备好了。"
D.Strings[22372]="我们的猎物撤退了！是时候大举进攻了。"
D.Strings[22373]="我正在使用夺魂之镰拷问这些恶魔，但他们对萨格里特钥石的下落一无所知。\n\n他们只是保持着对某位女王的忠诚。\n\n赛娅娜和杰斯已经到前面去了。不幸的是，赛娅娜为了营救其他恶魔猎手被俘了。\n\n她有点不对劲。"
D.Strings[22374]="污染者阿克蒙德始终致力于发掘魔法技艺中最黑暗的分支。数千年来，无数世界的知识和历史都包含在了这本书里。$B$B现在，我们将宣扬你的传奇，$g大人:女士;。"
D.Strings[22375]="这具阴燃的尸体手中还抓着一根风灵环绕的图腾。"
D.Strings[22376]="我把这些好朋友的灵魂都托付给你了。保护好他们，附魔师。"
D.Strings[22377]="<这个土灵探索者的尸体已经被切开了。他的内脏——看起来就是一堆沙子和石子——洒得地板上到处都是。狰狞的伤口上残留着邪能的痕迹。>"
D.Strings[22378]="很高兴有你这样的英雄来帮助我们这些小附魔师！我的意思不是说我们个子小。大法师星歌其实挺高的。$b$b我是说……唉，算了！"
D.Strings[22379]="作为一名德鲁伊，这里的过度生长现象让我非常忧虑。但作为一名草药师，没什么能比这更让我开心的了。$b$b草药师$n。你是来拿我的报告的吗？"
D.Strings[22380]="不，我没有迷路——我只是在寻找稀有的草药。我……等等，你是不是$n？那个草药师$n？"
D.Strings[22381]="嘘！我正在听植物说话呢。"
D.Strings[22382]="我之前就觉得跟着弗蕾亚会找到某些绿色的玩意儿，可我真没想到会是这样！$b$b我能为你做点什么吗？"
D.Strings[22383]="我们必须扑灭燃烧军团在这座山上的威胁，这样你就能将我们的剩余部队从黑暗神殿调过来了。"
D.Strings[22384]="如果不阻止那些卓格巴尔，至高岭的巨鹰就要绝种了。"
D.Strings[22385]="送我回勇者之门。"
D.Strings[22386]="斯科瓦尔德虽然跑了，但胜利仍然属于我们。多亏了你，他的恶魔再也不能为祸风暴峡湾了。\n\n让我们返回大门吧，朋友。我相信哈维也会想要谢谢你的。"
D.Strings[22387]="我们决不能让斯科瓦尔德把这些污秽之物带入英灵殿！"
D.Strings[22388]="我要挑战你，赫尔多。"
D.Strings[22389]="你好！有兴趣学习制皮吗？"
D.Strings[22390]="<这块水晶散发着邪恶的能量。>"
D.Strings[22391]="送我去山顶，维瑟尔！"
D.Strings[22392]="有人在大门上方看到了神王斯科瓦尔德。\n\n你准备好之后，我们就跟他开战！"
D.Strings[22393]="“过来，尼古拉。”$b$b“把那个拿给我，尼古拉。”$b$b我跟你说，总有一天，发号施令的人会变成我的。"
D.Strings[22394]="不要这么招摇。相比与敌人战斗，静静观察可以了解到更多。"
D.Strings[22395]="沼岩鱼人最喜欢用它们的临时灯塔制造海难。鱼人很好，但这群鱼人太残忍了。\n\n我们必须拯救这片海滩！这个年轻的鱼人叫奔波尔霸，他是我一手带大的。我们得帮他变强，这样他就能训练我们的蝌蚪，让他们青出于蓝了。"
D.Strings[22396]="你是在与一片古老土地上的元素之灵同行，$r。"
D.Strings[22397]="虽然很难，我还是设法收集到了一些武器和补给。你需要什么？"
D.Strings[22398]="这些年来，我们被守望者隔离、放逐到世界最黑暗的深渊。\n\n现在，我们必须站出来面对这个世界前所未有的挑战。现在，我们必须保护艾泽拉斯，抵抗它最强大的敌人。"
D.Strings[22399]="这些野兽相当暴躁，除非你知道该怎么对付它们。这个应该会听你的命令……至少会听一会儿。"
D.Strings[22400]="使用狱卒的碎片打开维瑟尔的牢笼。"
D.Strings[22401]="这个邪能祭坛和斯科瓦尔德试图奴役托里姆峰的托林尼尔巨龙时所使用的很相似。$B$B它非常强大，似乎无法用常规手段来摧毁。"
D.Strings[22402]="<名单上的大部分条目都空着。其中一张纸的角落里写着几行潦草的字迹。>$B$B让这些该死的迷雾都下冥狱深渊去吧！它们出现后不久，我的大部分工人就都失踪了，剩下的少部分人也都无心工作了。他们看起来就好像一头撞上了桅杆似的。$B$B就凭这一小撮懒鬼，我要怎么才能让斯坦的船做好出航的准备？$B$B我会尽量让船做好准备的，哪怕只剩我一个人干活也不怕，但我的工作队伍急需人员的补充。"
D.Strings[22403]="<补给采购单上还附了一张纸条。>$B$B港口主管柯吉尔，$B$B我不知道这些雾气到底携带着什么邪恶的灾祸，可它们才笼罩了港口一天，我们所有的补给品就都坏了。我们需要立即补充补给。$B$B等斯坦船长一恢复，就派他出去搜索补给品，当然，这还得建立在他能制止船员无休止的吵架和打斗的情况下。$B$B与此同时，我们都必须勒紧裤腰带，节省度日了。鉴于大部分镇民都已失踪，我想这应该并不困难。"
D.Strings[22404]="我们的港口受到了诅咒。$B$B海鸥像石头一样从天而降。前几天我还看到一只海鸥砸到了一个码头工人的头上，直接把他砸晕了。$B$B大批翻着肚皮的死鱼在浅湾中腐烂。我们的渔夫已经连续几周没有捕到像样的鱼了，而且到处还充满了死鱼的可怕臭气。$B$B我的大部分卫兵都失踪了，我不得不担负起额外的瞭望任务。我只能到这里来喘口气，至少这里的臭味和陈腐的空气没那么严重。$B$B这个港口已经死了。迷雾正在扼杀这里的所有生命。"
D.Strings[22405]="或许我应该留在据点。我在下头被俘虏时受的伤还没有恢复。\n\n这个世界充斥着恶魔能量。这会让我更加难以控制体内的邪能。"
D.Strings[22406]="我们完成了不可能的任务。我必须承认，我原本对你的领导能力是有所怀疑的，$n。但这种疑虑现在已经打消了。\n\n让我们回去终结黑暗神殿的战斗吧。伊利丹大人还在等着我们。"
D.Strings[22407]="这种雾气对我的船员有着不好的影响。他们变得狂暴且难以控制。他们不再关注大海，而更喜欢互相争吵打斗。$B$B港口主管柯吉尔已经命令我们出去尽快寻找新的补给了。我还有一个额外的任务，就是希望工作能够让他们忙碌起来，直到我们的船出发为止。$B$B我只希望海风能让我的船员冷静下来，恢复活力。"
D.Strings[22408]="这里的服务真是糟糕。太糟糕了！"
D.Strings[22409]="别客气，愿清风常伴你左右。"
D.Strings[22410]="凯恩，告诉我有关马顿的情况。"
D.Strings[22411]="对，我知道外面有人在打架。我的卫兵们只是需要……休息一下。$b$b<莱杉压低了声音悄悄地道：>$b$b你想让我们回到岗位上去？那就过一会儿再来，记得带上盲目之眼。"
D.Strings[22412]="如果你想要贿赂我，那你最好三思而行。我有责任保障这些下水道的安全！$b$b<莱杉压低了声音悄悄地道：>$b$b你过一会儿再来，我们好好谈谈，$c。"
D.Strings[22413]="来吧，让你疲惫的灵魂在柔软的床铺上好好休息一下吧。"
D.Strings[22414]="暗夜井蕴藏着不可思议的庞大力量。我们决不能让燃烧军团染指它。"
D.Strings[22415]="<塔莉萨无法控制地颤抖起来，几乎说不出话来。|cFFF92304必须首先满足她的饥渴，然后才能进行其他行动。|r>"
D.Strings[22416]="我的时间宝贵。有话快说，不然就走。"
D.Strings[22417]="我们已经击败了你的勇士。现在，让我们离开冥狱深渊！"
D.Strings[22418]="我们至今仍在传颂许多个世纪前至高岭对抗燃烧军团如潮攻势的传说。$b$b能再次站出来反抗他们是一种荣耀。"
D.Strings[22419]="关于这些粉末，你有什么想说的吗？"
D.Strings[22420]="我正在拼命忍住不杀了你。"
D.Strings[22421]="我这么说吧：$b$b这些粉尘和躺在我店门口那具还在闷烧的尸体有什么关系吗？"
D.Strings[22422]="让我看看……它闻上去很像恶魔之火，它的颜色也很像恶魔的腐蚀，而在达拉然的街道刚刚发生过爆炸和尖叫后不久，它就出现在了我的店铺里。$b$b你是想杀了我吗，$c？"
D.Strings[22423]="我们与鹰身人的战斗仍在持续，但你的行动让盆地的局势稍微恢复了一点平衡。"
D.Strings[22424]="再见，教授。"
D.Strings[22425]="……不是。"
D.Strings[22426]="我能问你几个有关这种粉末的问题吗？"
D.Strings[22427]="你是在浪费我的时间吗？"
D.Strings[22428]="还是某种卷轴？"
D.Strings[22429]="粉尘这种东西其实不怎么合适我，孩子。我是一个文字工作者，只跟墨水和卷轴打交道。$b$b现在，让我们理性思考一下这个问题吧：$b$b你的这些粉尘……是一种墨水吗？"
D.Strings[22430]="你知不知道为什么你的车会爆炸并燃起邪能火焰？"
D.Strings[22431]="她是一辆漂亮的马车，曾经是。$b$b<塞林把眼泪抹在了他的胡子上。>"
D.Strings[22432]="我不属于这里！我要离开冥狱深渊！"
D.Strings[22433]="海拉巨大的身影耸立在平台的远处。\n\n这个祭坛似乎是和她沟通的渠道。"
D.Strings[22434]="那么，你对这种粉末知道多少？"
D.Strings[22435]="当然不了！我相信你的故事。"
D.Strings[22436]="对，我就是要敲诈你。"
D.Strings[22437]="等等……你不是想敲诈我吧？"
D.Strings[22438]="只是例行公事。我相信你。"
D.Strings[22439]="我很想相信你，可你的话很没有说服力。"
D.Strings[22440]="我不知道你干嘛要不依不饶地盘问我。我可是刚刚才失去了我的马车和所有的财产。"
D.Strings[22441]="好，我相信你。"
D.Strings[22442]="你的骡子？你一定是在逗我。"
D.Strings[22443]="当然，我的骡子就在那儿。"
D.Strings[22444]="好吧，我相信你。"
D.Strings[22445]="事情发生的时候，还有其他目击者在场吗？"
D.Strings[22446]="不……我是个好人！我……我有捐款给慈善基金，捐过一次！我也很少乱丢垃圾！$b$b还有，我从来都没有搞过大减价。"
D.Strings[22447]="很好，我相信你。"
D.Strings[22448]="我知道你是什么人。一个卑鄙的拍卖行投机商。"
D.Strings[22449]="我只是个商人，童叟无欺，我就想到拍卖行里买了货物之后再高价卖回给别人，赚到一千万金币之后就平安回家！这个要求很过分吗？"
D.Strings[22450]="我为什么要相信你？"
D.Strings[22451]="我发誓，我对各种恶魔之火都一无所知！我只是个买卖护甲的，仅此而已！"
D.Strings[22452]="我们去打猎吧！"
D.Strings[22453]="这真是一次令人难忘的狩猎！\n\n要是没有你和艾迪，我都不知道我们能不能拿下那只野兽。"
D.Strings[22454]="赫米特只会接受那些狩猎技巧高超的人加入他的狩猎小队。"
D.Strings[22455]="你们不仅仅是证明了自己的实力。能跟你和艾迪一起打猎是我的荣幸。"
D.Strings[22456]="你比我想象中的$r更有本事。"
D.Strings[22457]="$n，我抓到了几头魔蝠。在你决定飞上那艘燃烧军团的指挥舰前，我一定会驯服它们的。"
D.Strings[22458]="这看似只是一个小洞，连一支军队都装不下，但它却通向奈萨里奥的老巢。$b$b进去之后，你就能绕到忠于达古尔的卓格巴尔主力军团背后。$b$b但前进的时候还是要小心点，因为你会见到比目前为止你所遇到的所有卓格巴尔还要强大得多的敌人。祝你好运，伙计。"
D.Strings[22459]="我已经沉睡了许多个季节。\n\n能再次闻到符文林地的空气真好。"
D.Strings[22460]="我感觉到了足印……但它们很陌生……\n\n陌生人……你必须帮助……"
D.Strings[22461]="你能送我回堡垒吗？"
D.Strings[22462]="万古之前，萨格拉斯创造了马顿，并将恶魔们囚禁在这里。他还创造了萨格里特钥石来关住他们。\n\n可当这位泰坦决定焚毁所有的造物后，他打碎了马顿，无数碎片划过扭曲虚空。燃烧军团由此诞生了。\n\n萨格拉斯将他的钥匙藏在这个碎片里。这是一把“万能钥匙”，能够接入燃烧军团占领的任何世界。它也是伊利丹大人覆灭燃烧军团的计划中最关键的一环。"
D.Strings[22463]="让我看看可接的任务。"
D.Strings[22464]="这张桌子上列出了当前所有你可接的任务。"
D.Strings[22465]="有很多人反对他，但伊利丹是对的。我们是注定要摧毁燃烧军团的利刃。"
D.Strings[22466]="许多个世纪之前，我曾是天角部族的首领。我从没在我们古老的墓地中见过如此严重的亵渎行为！"
D.Strings[22467]="一万多年前，燃烧军团的恶魔首次入侵艾泽拉斯时，玛洛恩和其他强大的古代生物曾与他们战斗过。$b$b他在战斗中英勇牺牲，为了将他受伤的儿子塞纳留斯送去安全的地方疗伤而献出了生命。$b$b为了保护孩子而死，这是父母们最崇高的牺牲方式。$b$b但我要解释清楚一点：对于玛洛恩这样的古老生物而言，我们都是他的孩子。他能死而复生并回到我们中间，这是我们的幸运。"
D.Strings[22468]="瓦尔莎拉已经宁静了几百年，直到最近才有所改变。我们低估了这场危机。不要害怕，勇士。我们不会再被打个措手不及了。"
D.Strings[22469]="和玛洛恩一样，我们的大部分时间都是在荒野中度过的。$b$b可在这个危难时刻，没有人能独善其身。我们必须团结起来，否则就会一败涂地。"
D.Strings[22470]="让我看看你准备了哪些任务？"
D.Strings[22471]="在有些传说里，玛洛恩在世界诞生后的第一个黄昏里爱上了月神。$b$b她的光辉引导他穿越森林，让他知道自己并不孤单。这光辉赶走了恐惧，带来了希望。$b$b许多动物都爱着月亮，并疯狂的追逐她。而月神只遵循自己意志，按她安排的时间播撒光辉，月光是不能被捕捉或占有的。$b$b但白鹿还是夜复一夜的追逐着她横越天空。他变得越来越敏捷强壮，最终终于成功追上了她。$b$b她被他的热情和美丽打动了，接受了他成为她的配偶。直到今天，他仍然最喜爱在她的光辉笼罩下的荒野。"
D.Strings[22472]="你听说过白鹿和月神的故事吗？据说牛头人曾猎杀玛洛恩，并差点将他逼入绝境。为了逃跑，玛洛恩跳上了天空，可他的鹿角挂在了星星上。$b$b无论他怎么挣扎都无法摆脱。月神艾露恩见到了他，并愿意让他自由，只要他答应爱她，让她摆脱孤单。$b$b啊，但这只是这个神话的其中一个版本，是由骄傲的猎人们代代相传下来的。"
D.Strings[22473]="查看可接的任务。"
D.Strings[22474]="萨特已经入侵了我们的林地。他们曾是暗夜精灵，但却投靠了燃烧军团，被恶魔的魔法所扭曲。自然界没有这种怪物的位置。"
D.Strings[22475]="这些日子，恐怕梦境林地正在日渐稀薄。$b$b玛洛恩的庇护所是德鲁伊力量在破碎群岛上的一大重镇。我们决不能让它陷落。"
D.Strings[22476]="嘿，你还活着啊！"
D.Strings[22477]="我准备好接受你的礼物了。"
D.Strings[22478]="在我们继续前进之前，我想先送给你一份来自托林尼尔的礼物。\n\n举起你的武器，外来者，打起精神来。这份礼物对你们来说，可能有点难受。"
D.Strings[22479]="我承认，我从没想到过我的炼金师生涯会这么刺激！$b$b不过看看我是在跟谁说话呀……你的冒险经历可比我多多了！"
D.Strings[22480]="噢，你知道的，没什么大不了的。我只是帮忙把一整座城市从冰天雪地的北方搬到了一座闹鬼的要塞旁边，然后再搬到一片恶魔横行的群岛上！我想只要一天应该就能搞定了。$b$b我现在已经半退休了，德崔斯是个很不错的接班人。他是个好人……就是对他那个炼金台太上心了点！"
D.Strings[22481]="要想修复炼金台，我们还有许多工作要做呢！"
D.Strings[22482]="我这里有很多配方可供选择。"
D.Strings[22483]="你做好飞行的准备了吗？我们为你准备了最快的坐骑。"
D.Strings[22484]="好的，谢谢你，夜歌。你能帮我看一下装备吗？"
D.Strings[22485]="有什么吩咐吗？在我们出发前，你有什么装备需要修理吗？"
D.Strings[22486]="主母，我要你带着你的破坏魔穿过腐化熔炉的壕沟，让他们吃点苦头。"
D.Strings[22487]="我早就知道自己总有一天也会走上胡恩之路。我只希望在上路之前可以先解决掉达古尔。$b$b"
D.Strings[22488]="女士，请率领你的纳迦前往北方。打断恶魔在灵魂引擎举行的仪式。"
D.Strings[22489]="战争领主，你的部队负责突袭东南方的末日堡垒，阻止那里的恶魔大军攻击我们。"
D.Strings[22490]="带我飞去山顶，维瑟尔。"
D.Strings[22491]="等你处理完这里的事务，就来跟我谈谈，我会送你飞上山顶。$B$B一旦出发，我们可能就回不来了。"
D.Strings[22492]="你所做的一切非常了不起，但我们的任务还没有完成。$B$B准备好之后就跟我说一声吧，我们得到山顶上去。"
D.Strings[22493]="我们不会让你白白帮助托林尼尔的，外来者。$B$B如果你真的想获得我们族群的祝福，就帮我们把这群祸害赶出我们的家园吧。"
D.Strings[22494]="我明白了。"
D.Strings[22495]="月爪大师！你的林地出什么事了？"
D.Strings[22496]="我可以把我们弄出去。我知道一条密道。"
D.Strings[22497]="我准备好接受你的恩赐了，尤特纳。"
D.Strings[22498]="你已经证明了自己确实有资格挑战试炼。能够考验你是我的荣幸。"
D.Strings[22499]="你已经证明了自己可以成为我宝贵的盟友，$n。我能帮你什么忙吗？"
D.Strings[22500]="纳萨诺斯要你去惊魂港见他。$B$B可以出发了吗？"
D.Strings[22501]="虽然至高岭的有些部族看不起我们和平的生活方式，但他们大部分的食物都是我们提供的，我们还能治愈战斗带来的创伤。\n\n那些小崽子们应该学会尊重长者。"
D.Strings[22502]="没有了河鬃部族供应的水产，我们的大山很快就会遭遇饥荒的。"
D.Strings[22503]="这里的卓格巴尔向来与我们和平共处，某些人甚至还很友好。他们的地底之王究竟做了些什么，使得他们开始针对起我们来了？我也不知道。"
D.Strings[22504]="现在安全了。"
D.Strings[22505]="大、大、大——大家都去哪儿了？"
D.Strings[22506]="我的人民经历过太多的苦难。许多年前，天灾军团的暴动让我们逃离了吉尔尼斯。$B$B现在，亡灵生物又出现在了北边的要塞中。$B$B我要保卫这座村子，直到生命的最后一刻。"
D.Strings[22507]="这里出什么事了？"
D.Strings[22508]="莫拉舒在这座山脉中活动的历史不亚于任何一个部族。他的存在确保了生死轮回的延续，保证了自然的平衡。\n\n据说莫拉舒会在动物死后引导它们的灵魂。当它们的眼睛失去光彩，莫拉舒就会来到它们身边，引导它们回归大自然的怀抱。"
D.Strings[22509]="再跟我说说有关莫拉舒的故事吧。"
D.Strings[22510]="天角部族不是鹰身人的唯一受害者。\n\n这座山脉里的野生动物都深受这些残酷混乱的女巫之害，没有了莫拉舒引导它们的灵魂，它们将永远无法安息。"
D.Strings[22511]="我建议你给那个可怜的狼人格雷迈恩一个痛快。\n\n可惜我没法亲眼欣赏他临终前的痛苦挣扎了。"
D.Strings[22512]="被惊扰的坟墓、黑鸦堡垒里的恶魔、还有充满敌意的暗夜精灵，这绝不是巧合。$B$B燃烧军团已经复活了拉文凯斯大人。我曾经的导师又活过来了。"
D.Strings[22513]="我在这里都能感觉到那剧烈的爆炸！\n\n那个吉尔尼斯混蛋永远都别想搞明白自己是被什么袭击了！"
D.Strings[22514]="感谢你能第一时间赶来。我们的外墙已经承受不了格雷迈恩的下一次炮击了。"
D.Strings[22515]="我早就发现了一些蛛丝马迹，可我被困在了梦境中。要是我能早点警告他们就好了！"
D.Strings[22516]="上古之战后，幸存的萨特被集中到了一起。我据理力争，想要根据他们的罪行处死他们，但我们仁慈的大自然占了上风，我的提议被否决了。$b$b最终，那些萨特被囚禁在莎拉达希尔根须之下，陷入永恒的沉睡。而现在，他们被某种力量唤醒了。$B$B我们不能再犯同样的错误了，如果有必要的话，我会亲手杀了他们！"
D.Strings[22517]="亲爱的$g先生:女士;，今天我能为你做点什么吗？"
D.Strings[22518]="欢迎来到铭文师的殿堂！"
D.Strings[22519]="无论它结局如何，你们都得死在这里。"
D.Strings[22520]="Ishnu-dal-dieb，旅行者。"
D.Strings[22521]="即使这片林地已经被莎拉达希尔给腐蚀了，它仍然是我们的家园。$b$b我们要和它同呼吸共命运。"
D.Strings[22522]="再也没有比这更美妙的体验了：微风送来松树的清香，还有一大堆猎物可供我们狩猎。"
D.Strings[22523]="这片盾牌描绘了一个背生双翼的女武神托起了一个倒在战场上的维库人的尸体。\n\n而这位女武神的形象却和瓦格里出奇的相似。"
D.Strings[22524]="在这面盾牌上，刻着艾尔站在一个泰坦宝库的入口处。\n\n她似乎正在迎接一名背生双翼的女武神勇士进入宝库。"
D.Strings[22525]="这面盾牌上的场景是一位女武神在一位古代斯考德-艾希尔勇士的雕像上方盘旋。\n\n这位女武神光环缠身，背后还有金色的双翼。"
D.Strings[22526]="这块盾牌上刻了一位女武神，跪在一根精美的长矛前。\n\n神殿的女祭司就站在不远处，默默观察着整个仪式。"
D.Strings[22527]="这片盾牌似乎描绘了斯考德-艾希尔的战士们需要经历的各种试炼。\n\n而盾牌中间则是附近的神殿。"
D.Strings[22528]="盾牌上雕刻了一位女武神的女神，在战场上守护着她们。\n\n在她的头上刻着一个名字“艾尔”。"
D.Strings[22529]="我想要看看你出售的货物。"
D.Strings[22530]="这仅仅是个开始。"
D.Strings[22531]="<这名伊利达雷的尸体已经几乎面目全非了。他受到了严刑拷打，最终伤重而死。>"
D.Strings[22532]="当时我们正在追踪一个恐惧魔王。不幸的是，他将我们引入了陷阱。"
D.Strings[22533]="<这个恶魔猎手的脸色像鬼魂一样苍白，身体无法控制的颤抖着。>"
D.Strings[22534]="我会帮你找到玛维。"
D.Strings[22535]="我了解我的姐姐。她不可能犯下这种罪行，除非是受到了某种邪恶的影响。$B$B即便如此，我还是在没有彻底调查清楚的情况下就做出了最坏的推断。$B$B我是个糟糕的弟弟，但现在还来得及纠正我的错误。"
D.Strings[22536]="为了断绝我们的人民与联盟的关系，她谋杀了无辜者。$B$B可是，我仍然无法说服自己去杀害她。$B$B一开始，我觉得这是因为软弱——这份感情让我没法去做我应该做的事。"
D.Strings[22537]="我和玛维选择了完全不同的人生道路。$B$B燃烧军团首次败走艾泽拉斯之后不久，她就决定终生追求正义的事业。$B$B有时，人们会觉得她对于正义过于偏执了。"
D.Strings[22538]="那你为什么还想要救她？"
D.Strings[22539]="她干了什么？"
D.Strings[22540]="你和你的姐姐是怎么失散的？"
D.Strings[22541]="我们与鹰身人的战争还在继续，但你的行动让盆地的局势稍微平衡了一点。\n\n随着莫拉舒的灵魂重生，他将再次引导其他动物回归大自然。"
D.Strings[22542]="我的女儿就是我的一切。多亏你将她安全地带回家来，我真不知道该怎么感谢你了。"
D.Strings[22543]="你知道吗，他们以前叫我“坏脾气的玛莱恩”。我能在一百步外打掉钉子的头。"
D.Strings[22544]="<显然这个勇敢的灵魂是因为捕捉某种危险的存在而死的。>$B$B<她的枪就躺在边上。你敢捡起它然后继续调查吗？>"
D.Strings[22545]="嗯？我能帮你什么忙吗，$n？"
D.Strings[22546]="尝试与雕像沟通。"
D.Strings[22547]="你面前的雕像属于斯考德-艾希尔的女武神领袖。\n\n她的脸看起来有些眼熟……"
D.Strings[22548]="过来，靠近点，让我好好看看你。$B$B啊！一个$c，千里迢迢跑来这里？我的女神！"
D.Strings[22549]="我很高兴你能来，$n。\n\n现在，来解决我们的问题吧。"
D.Strings[22550]="我从未见过这些元素之灵如此狂躁。"
D.Strings[22551]="我们很幸运。要是地底之王解开了圣锤的全部秘密，我们就没法站在这里说话了。$b$b他现在就像一个得到了新玩具的孩子，虽然危险，但只要持有圣锤的时间不长，就不算致命。"
D.Strings[22552]="我想看看贵重点的首饰，谢谢。"
D.Strings[22553]="欢迎来到卡蒂亚精品珠宝店，$c。我看得出来，你是个有品味的客人。$b$b今天你想看点什么呢？"
D.Strings[22554]="我必须让他们听从我的劝解，而不是我的剑。新手常常会诉诸武力，但劝说才是高手的武器。"
D.Strings[22555]="我不会对这些平民动手的。他们不知道我是谁，对我也没有威胁。"
D.Strings[22556]="我们的房间永远欢迎你，$c。"
D.Strings[22557]="谢谢你救了我的侄子。但愿我们能重建我们的村子。"
D.Strings[22558]="<这个德鲁伊继续在睡梦中自言自语，偶尔翻个身。>"
D.Strings[22559]="<这个德鲁伊在睡梦中喃喃自语。>$B$B他们永远别想找到我的宝藏。我已经把它藏好了。$B$B<然后，他的声音又低沉了下去，几乎听不清楚。>"
D.Strings[22560]="沙沙声越来越响。林精们正在接近洞穴入口！准备迎接他们的攻击！$b$b这只小熊看起来又无助又害怕。"
D.Strings[22561]="欢迎来到铁角飞地。"
D.Strings[22562]="我看见你了，$n。你有什么打算？"
D.Strings[22563]="我会救你的，可怜的小东西。"
D.Strings[22564]="看来林精已经杀害了这只小熊的家人。$b$b这只熊崽用绝望的眼睛仰视着你，显然是在发抖。$b$b你听到附近的树林里传来沙沙的声响：林精们快要回来了。$b$b这是小熊是不可能靠自己活下来的。你愿意救它吗？"
D.Strings[22565]="<这头幼龙用阴险的目光死死地盯着你。>"
D.Strings[22566]="对，我想我需要停留一会儿。"
D.Strings[22567]="小$r$n是文雅的洛什的朋友。\n\n你要待上一会儿吗？"
D.Strings[22568]="梦魇的力量已经征服了这片森林……包括伟大的世界之树莎拉达希尔。$b$b恐怕我们将要面对瓦尔莎拉有史以来最可怕的威胁了……"
D.Strings[22569]="翡翠梦魇的危险如同势不可挡的风暴，已经出现在了地平线上……可我们宁可战死，也不会让它夺走我们所珍视的一切。"
D.Strings[22570]="这座神殿作为给月神艾露恩的献礼，已经矗立了几百年了。$b$b这不是燃烧军团第一次试图摧毁它了……他们也会和前几次一样失败的。"
D.Strings[22571]="$n，我们必须在火山这里与燃烧军团作战。我们必须在飞上蛛后的指挥舰邪能之槌号之前消灭他们。\n\n然后，我们再干掉她，拿走萨格里特钥石，返回黑暗神殿消灭入侵者。\n\n这可不是什么小打小闹，但我相信我们能做到。"
D.Strings[22572]="决不能让古尔丹成功。只要我还活着，就要跟燃烧军团抗争到底。"
D.Strings[22573]="最终，我也无法再追随伊利丹的脚步。他已经被恶魔腐蚀了，变成了曾与他势不两立的敌人。"
D.Strings[22574]="我很怀疑奥图里斯的动机，但眼下我们的目标是一致的，那就是离开这座监狱。"
D.Strings[22575]="小心点，你要是敢轻举妄动的话，我们就用铁链把你锁起来。"
D.Strings[22576]="我看出来了，我是在跟一位身经百战的老兵说话。"
D.Strings[22577]="别犹豫了，$r。我们不能再浪费时间了。"
D.Strings[22578]="我也很想解释到底发生了什么，但就是死者好像都复活了。"
D.Strings[22579]="没有这种粮食的话，我们的村民就死定了。但不要担心，亲爱的，我已经把这片区域封锁了！"
D.Strings[22580]="放轻你的蹄子。你脚下的青草还在呼吸。"
D.Strings[22581]="只要你愿意聆听，就能从鲜花身上学到许多。"
D.Strings[22582]="这片土地的植被与我家乡的完全不同。它们中的某些与其说是植物，不如说更像是动物。"
D.Strings[22583]="听到什么？"
D.Strings[22584]="纳萨诺斯委托我们将他的船修好。$b$b可这些懒骨头的动作太……等等……你听到了吗？"
D.Strings[22585]="我会帮你击败血喙的。"
D.Strings[22586]="这些小鸟是多么的珍贵啊！如果我们不帮忙的话，它们就有灭绝的危险。"
D.Strings[22587]="这片林地里的猫头鹰正受到一只名叫血喙的凶残秃鹫的威胁。$B$B提瑞斯和我打算将那只畜生从它的巢穴里引出来。$B$B我们必须杀了它，才能恢复森林的平衡，但我们需要一切可能的帮助。"
D.Strings[22588]="第四页：$b”在完成义务之后，应当支付给乙方的上述报酬将通过第三方直接抽取的方式支付，该角色的承担者为——“$b$b下面的字体实在太小了，肉眼已经无法辨认。"
D.Strings[22589]="翻到第四页。"
D.Strings[22590]="上面字体已经几乎看不清了：$b$b第三页：$b“作为交换，达格洛普同意向乙方提供大量不具实体的邪能能源，供乙方为其所拥有的一件神器充能，以下简称为‘‘报酬’。\""
D.Strings[22591]="契约继续用越来越小的字体写道：$b$b第二页：$b“这些条款包括获取沙拉扎恩仪式所需的材料，以下简称为‘‘义务’，以及消灭、屠杀、暗杀或谋杀所有妨害履行义务及达格洛普要求的主体，不论死活。”"
D.Strings[22592]="翻到第一页。"
D.Strings[22593]="翻到第三页。"
D.Strings[22594]="翻到第二页。"
D.Strings[22595]="契约开头的几行字写得巨大，运笔流畅，邪气十足，但每一句的字体都变得越来越小。上面这样写道：$b$b第一页：$b“我，签署者，以下简称为‘‘乙方’，在此郑重承诺，接受达格洛普·拉瓦利什·迪斯考尔·布拉特，以下简称为‘‘达格洛普’，所提出之条款。”"
D.Strings[22596]="用鲜血签署契约。"
D.Strings[22597]="阅读契约。"
D.Strings[22598]="我，伪善者、暴虐者、至邪者达格洛普，前来订约！"
D.Strings[22599]="我们必须重新集结，赶到我们的女王身边去。寻找阿格拉玛之盾的任务就交给你了。"
D.Strings[22600]="这些纳迦是最近才侵入阿苏纳的。他们想要解放法罗迪斯王子。\n\n毫无疑问，和你一样，他们和艾萨拉女王也在寻找高戈奈斯潮汐之石。只有王子知道它的下落。"
D.Strings[22601]="森林已经悄悄将你的到来告诉了我，年轻人。$b$b很少有外来者能进入我珍爱的林地。在此期间，请你保持敬意。"
D.Strings[22602]="大德鲁伊跟随塞纳留斯本人学习了数千年。"
D.Strings[22603]="我准备好了，玛法里奥。"
D.Strings[22604]="我们的任务就快完成了。$b$b我必须谢谢你让我参与你的冒险，$n。我虽然帮你找到了潮汐之石，可我觉得你为我和我的人民做的更多。"
D.Strings[22605]="听好了，$n。"
D.Strings[22606]="欢迎来到洛拉希尔，这里是德鲁伊的圣地。虽然这片森林已经非常古老，但它的灵魂还记得我。"
D.Strings[22607]="我是个糟糕的领袖。我有眼无珠，为我的人民选择了错误的道路。我……$b$b……我没法说得更详细了。给我一点时间，$n。我相信等到合适的时机，一切都会真相大白的。"
D.Strings[22608]="我诅咒了我的子民。我给我们世代安居的家园带来了灭顶之灾。$b$b是我害死了他们。$b$b因为我干的蠢事，我的人民在死后也不得安息。我的失败让他们变成这种不人不鬼的模样。"
D.Strings[22609]="这太困难了。我无法直视子民的眼睛，向他们解释我的行为。$b$b我应该回到我那孤零零的宫殿去。至少我的卫兵们都会忽视我的存在。"
D.Strings[22610]="阿苏纳曾是精灵文明的中心之一。我的人民欣欣向荣。而现在，他们都受到了诅咒。$b$b大部分人都不愿意看我一眼。$b$b他们都是我旧日的伤疤。是我可耻的印记。"
D.Strings[22611]="请原谅我的侍从。他们的无礼并不是针对你的……而是针对我。"
D.Strings[22612]="我的梦境被阴影占领了。当我醒来时，却发现那些阴影已经蔓延到了我们的世界。"
D.Strings[22613]="我的德鲁伊们还被困在翡翠梦境中无法醒来。"
D.Strings[22614]="塞纳留斯，我的导师……$b$b什么样的邪恶力量能支配得了他？"
D.Strings[22615]="开始仪式吧。"
D.Strings[22616]="我的仆从！很高兴你能成功。是时候让我的老主人为破坏契约而付出代价了。你做好面对他的准备了吗？"
D.Strings[22617]="我说我能酿出比他们更好的酒，可他们都嘲笑我。我告诉他们我可以酿出让查丽妮夫人赞不绝口的酒，没准还能获得女王陛下的青睐。"
D.Strings[22618]="这里发生了什么？"
D.Strings[22619]="$C，燃烧军团派出了手下最强大的恶魔来对付我们。他们肯定不想输掉这场第三次大战，不将我们彻底从艾泽拉斯抹去，他们是不会罢手的。\n\n我们也要好好“报答”他们的这番“深情厚谊”。"
D.Strings[22620]="直接……带路吧，鲁纳斯。"
D.Strings[22621]="啊，我的朋友。我最亲爱、最可靠的朋友$n。$b$b你身边有没有带着法力水晶？$b$b听着，我的朋友。如果你有任何需要——我要强调一下，是“任何”需要——只要告诉你忠实的朋友鲁纳斯就行了。我可以解决你的任何烦恼。我绝对靠得住。$b$b当然，如果我有什么需要，我相信你也会帮我的，对吧？比如，如果我需要法力水晶或者类似的东西，你会给我一块的，对吧？"
D.Strings[22622]="<你面前站着的……不是塞纳苟斯本人，而是他的一个魔法投影。他看起来强大、自信、心情愉快。他和你看到的那条在池塘中苟延残喘的衰老巨龙完全不同。>"
D.Strings[22623]="我们回蓝翼栖地吧！"
D.Strings[22624]="我们该回去找祖父了。"
D.Strings[22625]="<巨龙喷出微弱的龙息。他很痛苦。>"
D.Strings[22626]="你要是够聪明，就立刻交出斗士大餐。"
D.Strings[22627]="束缚我吧。我可能会在这里待一段时间。"
D.Strings[22628]="你到底在说啥？！"
D.Strings[22629]="你好，$c。\n\n燃烧军团已经占领了法罗纳尔。我有一个计划，可以在他们占领整个阿苏纳之前拦截并击溃他们。\n\n但这需要你的帮助。"
D.Strings[22630]="我准备好了，阿莱利。我们开始吧。"
D.Strings[22631]="乌卡，我能尝尝你那美味的斗士大餐吗？我听说这是最美味的佳肴。"
D.Strings[22632]="我们要一起放出宝石中的恶魔之魂，并用这把镰刀迫使他们交代。\n\n你准备好之后就告诉我一声吧。"
D.Strings[22633]="我听凭你的吩咐，$g阁下:女士;。"
D.Strings[22634]="别把我们当成走私者。你应该把我们看做专业的救捞队。\n\n我们可是打捞专家，擅长回收各种海上漂浮物、废弃物、船难货物，当然，还有珍稀的考古发现。\n\n噢，还有，你最好避开南边的神殿一带。我派人去那里进行商业调查了，我可不希望你被当成来抢饭碗的。"
D.Strings[22635]="燃烧军团已经攻占了宝库，我的大部分守望者都战死了。所以我才会把你放出来。没有人比你更擅长杀恶魔了，$n。\n\n他们冲着伊利丹的墓穴去了。我们必须合作以阻止燃烧军团。"
D.Strings[22636]="<欧库纳·长牙的包裹就扔在地上。上面的一条带子已经断了，还有打斗的痕迹。但里面的东西却一样都没有少。>\n\n<欧库纳可能已经被抓去了欧逊努斯王子那里。看来要撇下他独自前进了。>"
D.Strings[22637]="发生了什么事，法罗迪斯？"
D.Strings[22638]="他们准备好了，尾锚。让我上战场吧。"
D.Strings[22639]="我这辈子最大的梦想就是在真正的挑战赛中击败锈舵的三位勇士。他们实在太优秀了！\n\n或许你能帮我实现梦想，$n？"
D.Strings[22640]="你还知道，违反封锁禁令的人都将被处以死刑甚至拘留的吧？"
D.Strings[22641]="你——噗——什么！？$b$b你是知道的吧？在法罗迪斯王子背叛之后，潮汐之石大厅就被封锁了！"
D.Strings[22642]="好的好的，那是啥？$b$b如果是有关塑能系的期末考试的话，那么答案就是不，你休想再得到它了。"
D.Strings[22643]="我早就看穿你和你那个小伙伴了。你以为你能在我这里横插一杠子？\n\n想都别想。\n\n我可以跟你保证，等今天结束后，我就会踩着你的脖子，让你趴在竞技场的地板上，$r。"
D.Strings[22644]="鲸腹老板，很高兴见到你。你记住了，就在今天，我一定会成为竞技场冠军的。"
D.Strings[22645]="像你这么弱小的$r来这里做什么？\n\n噢，把你切碎做成鱼饵一定会很有趣的。"
D.Strings[22646]="请带我去找潮汐之石。"
D.Strings[22647]="我们去找那块潮汐之石吧。"
D.Strings[22648]="莽撞的混账蠢蛋，你最好把它还回来！"
D.Strings[22649]="该死的混账蠢蛋！"
D.Strings[22650]="这都是你干的？你怎么做到的？为什么要这么做？"
D.Strings[22651]="你的同胞都很鄙视你。为什么？你干了什么？"
D.Strings[22652]="怎么？啥？这种斗士大餐是祖传秘方。\n\n你休想搞到它，$r。"
D.Strings[22653]="我们得集中力量为其他囚犯弄到武器，并让你成为尾锚的角斗士冠军。\n\n然后，我们就能去干掉欧逊努斯王子了。"
D.Strings[22654]="我妈妈？我妈妈！你这混蛋！"
D.Strings[22655]="又怎么了？你这个该死的、狡猾的、凶残的家伙？"
D.Strings[22656]="我们要团结起来，一同封印萨格拉斯之墓并击败燃烧军团。"
D.Strings[22657]="妈呀！"
D.Strings[22658]="%s发起了冲锋！"
D.Strings[22659]="你不能拿走我的蜡烛！"
D.Strings[22660]="还没到吗？"
D.Strings[22661]="%s变得愤怒了！"
D.Strings[22662]="你好，$c。给你一个建议：当你在世界各地旅行的时候，要当心魔法，未经训练的外行人很容易为魔法所伤。"
D.Strings[22663]="欢迎来到我的旅店，疲惫的旅行者。我能为您做点什么吗？"
D.Strings[22664]="将这座旅店设为你的家。"
D.Strings[22665]="公会注册员及公会商人"
D.Strings[22666]="你在寻找哪种专业的训练师？"
D.Strings[22667]="萨满祭司"
D.Strings[22668]="我能在旅店里干些什么？"
D.Strings[22669]="我想要看看你出售的东西。"
D.Strings[22670]="魔法只会使弱者堕落。继续你的训练吧，不然你的命运就跟那些家伙相差无几了。"
D.Strings[22671]="邮箱"
D.Strings[22672]="你想去哪里？"
D.Strings[22673]="飞艇管理员"
D.Strings[22674]="我们有闪光的钩子。这是基里安·哈根给我们的，他教我们如何剥皮。你有很好的兽皮。去盗贼区的内环找他吧。"
D.Strings[22675]="什么意思？"
D.Strings[22676]="你需要什么方面的指引？"
D.Strings[22677]="愿月神与你同在，$c。"
D.Strings[22678]="我们的导师玛法里奥已经从沉睡中回来了，$c。他是我们的指路明灯，我们必须竭尽全力保护他。"
D.Strings[22679]="我跟你没什么好说的，你最好找个$c训练师来帮助你。"
D.Strings[22680]="告诉我更多的信息。"
D.Strings[22681]="愿灵魂与你同在。"
D.Strings[22682]="你向我们发出挑战而我们来了。你所说的大师在哪里？"
D.Strings[22683]="魔法只会使那些软弱的人堕落。继续你的训练吧，不然你的命运就跟那些人相差无几了。"
D.Strings[22684]="这些都是大地之母走过的道路。愿你的祖先保佑你$c。"
D.Strings[22685]="我不会伤害你的。我在监视野猪人并记录他们的活动。我的人民注意到了某些奇怪的事情——黑暗的弥漫——从这个地区来的。我是来调查的，而我的发现很令人不安。$B$B似乎有一个很善于奥术的亡灵外交官。我不相信他也是被遗忘者……我认为事态更坏了。"
D.Strings[22686]="我想接受更多的德鲁伊训练，更好地理解大地之母的意愿。"
D.Strings[22687]="作为一个法师，你是极少数可以操纵传送门魔法来帮助你回到这里的$r之一。如果你准备好了，我现在就可以教你。"
D.Strings[22688]="作为一名法师，你是少数可以召唤传送门返回这个地方的$r。如果你已经准备就绪，我就可以教你这种法术。"
D.Strings[22689]="我想你不愿意向我学习吧。你最好找个$c训练师帮助你。"
D.Strings[22690]="有什么事吗，$c？"
D.Strings[22691]="我能帮忙吗？"
D.Strings[22692]="我想要看看你出售的物品，卡兰德拉斯。"
D.Strings[22693]="您好，$c，欢迎来到暗月马戏团。在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。这就是我在这里帮忙的原因。您有什么问题吗？"
D.Strings[22694]="我需要牧师训练。"
D.Strings[22695]="联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，与你想要提升声望的主城中的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。"
D.Strings[22696]="联盟荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，跟你想要提升声望的主城的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找大元帅斯诺·落雪。"
D.Strings[22697]="很高兴见到你，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B联盟和部落需要同仇敌忾，共同对抗安其拉异种虫类和它们的首脑。我们在铁炉堡的军事区收集原料以制造各种战争物资，这些收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[22698]="嗨，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主使者。在奥格瑞玛的精神谷，我们正在收集原料制造战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[22699]="艾露恩与你同在，$c。"
D.Strings[22700]="让我们看看你的能力吧。"
D.Strings[22701]="你好，$C。"
D.Strings[22702]="你好，$R。"
D.Strings[22703]="你无法阻止我们！"
D.Strings[22704]="圣光给了我们通往胜利和力量之路的魔法。"
D.Strings[22705]="你有什么烹饪材料吗？"
D.Strings[22706]="你有什么烹饪调料吗？"
D.Strings[22707]="术士"
D.Strings[22708]="灵魂与你同在。"
D.Strings[22709]="你要找哪位专业技能训练师？"
D.Strings[22710]="嗯？什么？"
D.Strings[22711]="在春节期间，我们应该花时间来寻找我们的长者，思考他们的智慧。"
D.Strings[22712]="你看到烟火了吗？这是一年中购买烟火的最好时刻。"
D.Strings[22713]="永夜港的德鲁伊们正在月光林地举办一个隆重的春节庆祝活动。"
D.Strings[22714]="不许抢走我的蜡烛！"
D.Strings[22715]="欢迎来到我的旅店，疲劳的旅者。有什么我可以帮你的吗？"
D.Strings[22716]="送我到荣耀岗哨去！"
D.Strings[22717]="送我去地狱岩床！"
D.Strings[22718]="你毫无价值！"
D.Strings[22719]="听从我的命令。"
D.Strings[22720]="珠宝加工"
D.Strings[22721]="嗨，$C。我想你是为安其拉之战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主人。在奥格瑞玛的精神谷，我们正在收集原料以赶制战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[22722]="很高兴见到你，$C。我想你是为安其拉一战而来的吧。我们急需帮助。$B$B部落和联盟必须携手对抗安其拉异种虫类大军和它们的主人。在铁炉堡的军事区，我们正在收集原料以赶制战争物资，收集工作需要你的帮助。$B$B你可以跟我们的指挥官谈谈吗？"
D.Strings[22723]="停住！"
D.Strings[22724]="我们赶紧离开这里！"
D.Strings[22725]="在艾泽拉斯再也找不到比这更好的啤酒了。"
D.Strings[22726]="呀啊啊啊啊啊啊啊！"
D.Strings[22727]="伊米隆国王万岁！"
D.Strings[22728]="没有效果？"
D.Strings[22729]="没有效果！！！？？？"
D.Strings[22730]="为伊米隆国王而战！"
D.Strings[22731]="我觉得和假人对练都比和你来得有用。"
D.Strings[22732]="我觉得和假人对打都比和你来得有用。"
D.Strings[22733]="你在艾泽拉斯找不到更好的酒了。"
D.Strings[22734]="你有没有看过他们在泰罗卡森林的表演？太精彩了！"
D.Strings[22735]="你没看过他们在泰罗卡森林的表演吗？太精彩了！"
D.Strings[22736]="传说强大的年兽沉睡在月光林地的月神湖底，每年只会醒来一次。不过那也只是个传说。"
D.Strings[22737]="春节期间，我们应该花些时间去寻找长者，并领略他们的智慧。"
D.Strings[22738]="你看过烟花吗？现在是一年当中买烟花放的最佳季节！"
D.Strings[22739]="月光林地的德鲁伊正在举办隆重的庆典，庆祝春节的到来。"
D.Strings[22740]="我们等一下不如去玩“不给糖果就捣乱”的游戏。"
D.Strings[22741]="呀！！！"
D.Strings[22742]="哈？"
D.Strings[22743]="你以为自己在干什么？"
D.Strings[22744]="啊啊啊啊啊啊啊……"
D.Strings[22745]="你还不知道“本月美酒俱乐部”？那些姑娘最喜欢聚会了。如果她们能想到合适的办法，美酒节将会永不落幕！去年她们就曾希望美酒节不要结束。$b$b但现在她们找到了更好地发扬美酒节精神的方法，那就是让人们加入她们的俱乐部。$b$b你只需要付出很少的费用，只需要几枚美酒节奖币，你就能加入了！会员每个月都会收到俱乐部邮寄来的酒样，还可以购买自己喜欢的啤酒。这个精英俱乐部能永远继承美酒节的精神。"
D.Strings[22746]="你还不知道“本月美酒俱乐部”？那些家伙最喜欢聚会。如果他们能想到合适的办法，美酒节将会永不落幕！去年他们就曾希望美酒节不要结束。$b$b但现在他们找到了更好地发扬美酒节精神的方法，那就是让人们加入他们的俱乐部。$b$b你只需要付出很少的费用，只需要几张美酒节奖币，你就能加入了！会员每个月都会收到俱乐部邮寄来的酒样，还可以购买自己喜欢的啤酒。这个精英俱乐部能永远继承美酒节的精神。"
D.Strings[22747]="我们走着瞧吧！"
D.Strings[22748]="你即将面临新一轮的挑战。魔网守护者埃雷苟斯拥有可怕的力量。他就在魔枢顶层盘旋。"
D.Strings[22749]="%s嘟囔着。"
D.Strings[22750]="狡猾的法师领主伊洛姆守护着第三道环。表面上他显得孤立无援，但那不过是欺骗敌人的假象！伊洛姆是位强大的咒术师，能召唤各种幽灵生物为他作战。去上面找他吧。"
D.Strings[22751]="$n，你给我记好了，今天将是你彻底溃败的日子。"
D.Strings[22752]="$n，你给我记好了，今天将是你被彻底击败的日子。"
D.Strings[22753]="法师领主伊洛姆守护着第三环。他独自在平台上踱步，一副毫无防备的模样，你千万别被假象蒙骗了！伊洛姆是一名强大的咒术师，能召唤大量的幻影生物。去我们头顶的环面找他吧。"
D.Strings[22754]="接下来，你将迎接最艰难的挑战。魔网守护者埃雷苟斯，一条拥有无穷力量的蓝龙。他就在最顶层的环面上空盘旋。"
D.Strings[22755]="遵命，长官！"
D.Strings[22756]="欢迎你，$n。"
D.Strings[22757]="杀呀！"
D.Strings[22758]="长者基里亚斯在哪里？"
D.Strings[22759]="你阻止不了我们！"
D.Strings[22760]="传送门训练师"
D.Strings[22761]="寒冷天气飞行训练师"
D.Strings[22762]="训练师"
D.Strings[22763]="名胜地"
D.Strings[22764]="商人"
D.Strings[22765]="锁匠"
D.Strings[22766]="我能帮你吗， $c？"
D.Strings[22767]="休想通过这里！"
D.Strings[22768]="你以为你在干什么？"
D.Strings[22769]="什么，$c？"
D.Strings[22770]="我们会搞清楚的。"
D.Strings[22771]="我来自于元素位面！"
D.Strings[22772]="开火！开火！"
D.Strings[22773]="我来自于元素位面！！"
D.Strings[22774]="火箭里携带了一种化学品。是什么东西？"
D.Strings[22775]="火箭里携带了一种化学制品。是什么东西？"
D.Strings[22776]="站在这把杀害我的长剑面前……那种痛苦……仿佛又重新回来了。"
D.Strings[22777]="就是这把剑终结了我的生命……那种痛苦……挥之不去。"
D.Strings[22778]="%s开始冲锋！"
D.Strings[22779]="等你准备好了，我就护送你去太阳之井。"
D.Strings[22780]="等你准备好了，我就护送你去太阳井。"
D.Strings[22781]="无能之辈！"
D.Strings[22782]="嗨，$g小伙子:姑娘;我正努力要拿到我的那一份。"
D.Strings[22783]="嗨，$g小伙子:姑娘;我正在想应该怎样拿到我的那一份。"
D.Strings[22784]="有什么需要？"
