D.Strings[22808]="我们的主人玛法里奥已从梦境中返回，$c。他是指引我们前进方向的灯塔之光，我们必须竭尽全力保护这道光芒。"
D.Strings[22809]="无人能够通过！"
D.Strings[22810]="首先，你要给我一个游戏代币。然后我就给你一个大锤。然后你就会看见有豺狼人从游戏场地上的桶里冒出来。$B$B你就要用锤子去打这些豺狼人，来获取积分。$b$B但比较复杂的是，这里一共有三种目标：普通豺狼人，霍格豺狼人和娃娃。$b$b普通豺狼人计一分，霍格豺狼人计三分。而娃娃呢？击打他们会导致你被击倒并昏迷……所以千万别打那些娃娃！$b$b如果你没能在规定时间内砸到足够的豺狼人，可以再花一个代币再试一次！你累积的分数也可以带入下一轮。"
D.Strings[22811]="首先，你要给我一个游戏代币。然后我就给你一个大锤。然后你就会看见有豺狼人从游戏场地上的桶里冒出来。$B$B你就要用锤子去打这些豺狼人，来获取积分。$b$B但比较复杂的是，这里一共有三种豺狼人：普通豺狼人，霍格豺狼人和小豺狼人。$b$b普通豺狼人计一分，霍格豺狼人计三分。而小豺狼人呢？击打他们会导致你被击倒并昏迷……所以千万别打小豺狼人！$b$b如果你没能在规定时间内砸到足够的豺狼人，可以再花一个代币再试一次！你累积的分数也可以带入下一轮。"
D.Strings[22812]="您好，$c，欢迎来到暗月马戏团。$b$b在马戏团可以做的事儿数不甚数，第一次来的客人可能会觉得有些不知所措。所以我才会在这里帮忙。$b$b您有什么问题吗？"
D.Strings[22813]="我能帮你什么吗，$c？"
D.Strings[22814]="欢迎，$r。"
D.Strings[22815]="你这身衣服，好像很适合旅行时穿。看起来很有趣。我或许会将它用到以后的服装系列里。我打算叫它：$b$b$p特别款。"
D.Strings[22816]="土地精的鼻子很灵。能通过气味辨别是好运还是厄运。你身上有好运的气息。"
