D.Strings[22832]="部落荣誉徽章是奖励给那些富于责任感的英雄的。各大主城均设有嘉奖官，跟你想要提升声望的主城的嘉奖官交谈，按照规定的数量缴纳徽章吧！$B$B顺便说一句，在安其拉大战期间，如果你想要用徽章换取实物奖励而不是提升声望的话，可以去找督军格尔库克。"
