D.Strings[22888]="让我看看你有些什么。"
D.Strings[22889]="他们当初就该听我的，消灭所有萨特，就不会发生这种事了。\n\n谢谢你把我从萨维斯的疯狂中解救出来，$p。"
D.Strings[22890]="好的！"
D.Strings[22891]="让我们离开这里！"
