D.Strings[22893]="瑟维斯，我要为你最后一座传送门供能。"
D.Strings[22894]="<还有一页看得清字的，但是这本书剩下的部分实在太破旧了……>\n今天有客人。麦迪文来找艾里克斯讨论一些机密事宜，然后艾里克斯带他在这里逛了逛。\n\n麦迪文对艾里克斯的计划抱有很大的兴趣，主动提出帮忙。艾里克斯提到了在设置结界时现实的脆弱性，麦迪文说会研究一下，并鼓励艾里克斯尝试在恶魔的世界进行仪式。\n\n奇怪的是，有那么一小会儿，我看到麦迪文在盯着结界的时候，脸上的笑容有点诡异。这让我……很不安。不过他马上又变得严肃、友好，所以大概是我想太多了吧。"
D.Strings[22895]="虽然议会很庆幸巴拉杜尔不能进入艾泽拉斯，但是这也导致他的攻击几乎无法化解。议会所有的法师都收到了警告，小心他的捕猎行为。"
D.Strings[22896]="<这本书上的字几乎无法辨识……>\n今天的实验很顺利。在结界里，卡拉赞扭曲现实的腐化现象似乎完全消失了。艾里克斯非常高兴，虽然因为法力蛭的缘故，做一场实验要花很久的时间。设置结界的时候似乎会吸引大批的法力蛭。"
D.Strings[22897]="真是祸从天降！艾里克斯和他的徒弟全都死了！剩下的议会成员不想重蹈覆辙，正在销毁艾里克斯和他的仪式的全部记录。戴奥因为卷入其中，也被打发走了。\n\n他们把这件事看成是一场事故，一场失败的实验，但是还有其他成员去世，所以我怀疑这其实是谋杀。巴拉杜尔极其擅长发现法师的弱点。实在是过于擅长了。我一定要展开调查。\n\n——K"
D.Strings[22898]="虽然情报并不丰富，但是很显然，提瑞斯法议会的成功已经引起了一些更高层的恶魔领主的注意。\n\n如今，已经出现了好几次法师被恶魔袭击，甚至被偷袭的情况，这些恶魔是听命于一个叫巴拉杜尔的强悍艾瑞达。议会的很多计划也因此受挫。如果是力量非凡的咒术师或者大法师，巴拉杜尔会亲自参战，用某种方式在现实中制造裂隙，然后强迫或者说服这些法师进入裂隙。\n\n在一个极其罕见的个例里，有人活着从那里回来了。他看到巴拉杜尔玩弄着死去猎物的武器，把它们作为战利品，耀武扬威。\n\n"
D.Strings[22899]="<由于年代久远，这本书的大部分内容都难以辨认>\n……所以这就是他的命运，注定要被流放到扭曲虚空，再也无法回到艾泽拉斯。就连他的亲生儿子米尔豪斯，最终也背叛了他。不过在我看来，米尔豪斯这么做，并不是为了达拉然和艾泽拉斯的命运着想。\n\n一想到玛格努斯有办法逃出我们制造的魔力流放监狱，我就觉得荒谬透顶。但是我总觉得有些事情不太对劲。可是，我们别无选择。玛格努斯的问题相当罕见：他死了带来的麻烦比他活着更严重。\n\n<还有一些可以辨认的笔记，提到了一个叫幽幻区的东西。它是某个维度里的一个监狱空间，会永远在扭曲虚空里飘荡，里面的犯人可以看到外面，但是永远逃不出去。>"
D.Strings[22900]="这个指南针十分老旧，由于长期的使用而变得破损不堪。\n\n它好像已经坏掉了——指针毫无规律地改变方向，但就是无法指向正北方。"
D.Strings[22901]="箱子里装着各种神奇的小玩意。\n\n仔细检查之后，你发现这些“圣物”不过只是些高仿的赝品。"
